// ========================================================================
static std::string toLowerUtf8(const std::string& s);

static bool shouldEnforceRLS(const TableSchema& tbl, const std::string& user) {
    if (!tbl.rowLevelSecurity) return false;
    if (tbl.forceRowLevelSecurity || user.empty()) return true;

    // RLS bypass is a role attribute, not a username convention. Unknown
    // identities fail closed; authenticated superusers and BYPASSRLS roles
    // bypass ordinary RLS, while FORCE ROW LEVEL SECURITY still applies it.
    const auto account = authCatalog().getAuthIdByName(user);
    if (!account) return true;

    // PostgreSQL table owners bypass ordinary RLS. FORCE ROW LEVEL SECURITY
    // is handled above and deliberately applies policies to the owner too.
    // Require an existing role before comparing names; an arbitrary or
    // unauthenticated identity must never become an owner bypass.
    if (!tbl.owner.empty() && tbl.owner == account->rolname) return false;

    return !(account->rolsuper || account->rolbypassrls);
}

static bool evaluateRlsPolicies(
    const std::vector<StorageEngine::RowPolicy>& policies,
    bool withCheck,
    const std::map<std::string, std::string>& values,
    const std::map<std::string, std::string>& typeHints,
    const std::string& dbname,
    const std::string& user,
    bool& evaluationError,
    StorageEngine* functionEngine) {
    bool hasPermissive = false;
    bool permissivePassed = false;

    for (const auto& policy : policies) {
        std::string expression = withCheck ? policy.withCheckExpr : policy.usingExpr;
        // PostgreSQL uses USING as the default WITH CHECK expression for
        // ALL and UPDATE policies when WITH CHECK is omitted.
        if (withCheck && expression.empty()) {
            const std::string command = toLowerUtf8(policy.cmd);
            if (command == "all" || command == "update") {
                expression = policy.usingExpr;
            }
        }

        bool passed = true;
        if (!expression.empty()) {
            std::string error;
            passed = ExprHelper::evalBool(expression, values, typeHints, &error,
                                          dbname, user, functionEngine);
            if (!error.empty()) {
                evaluationError = true;
                return false;
            }
        }

        if (policy.permissive) {
            hasPermissive = true;
            permissivePassed = permissivePassed || passed;
        } else if (!passed) {
            // Every applicable restrictive policy must accept the row.
            return false;
        }
    }

    // A set containing only restrictive policies is still default-deny: a
    // permissive policy must establish the positive access set first.
    return hasPermissive && permissivePassed;
}

static bool rowPassesRLS(const StorageEngine* engine,
                         const std::string& dbname,
                         const std::string& tablename,
                         const TableSchema& tbl,
                         const std::string& command,
                         const std::map<std::string, std::string>& values,
                         const std::map<std::string, std::string>& typeHints,
                         bool withCheck) {
    if (!engine) return false;
    const std::string user = StorageEngine::getRLSUser();
    if (!shouldEnforceRLS(tbl, user)) return true;
    const auto policies = engine->getApplicablePolicies(dbname, tablename, command, user);
    if (policies.empty()) return false;

    bool evaluationError = false;
    return evaluateRlsPolicies(policies, withCheck, values, typeHints,
                               dbname, user, evaluationError,
                               const_cast<StorageEngine*>(engine)) &&
           !evaluationError;
}

// ========================================================================
// Unicode string helpers
// ========================================================================
static std::string toUpperUtf8(const std::string& s) {
    std::wstring ws;
    size_t i = 0;
    while (i < s.size()) {
        unsigned char c = s[i];
        if (c < 0x80) { ws.push_back(static_cast<wchar_t>(c)); ++i; }
        else if ((c & 0xE0) == 0xC0 && i + 1 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x1F) << 6) | (s[i + 1] & 0x3F))); i += 2;
        } else if ((c & 0xF0) == 0xE0 && i + 2 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x0F) << 12) | ((s[i + 1] & 0x3F) << 6) | (s[i + 2] & 0x3F))); i += 3;
        } else if ((c & 0xF8) == 0xF0 && i + 3 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x07) << 18) | ((s[i + 1] & 0x3F) << 12) | ((s[i + 2] & 0x3F) << 6) | (s[i + 3] & 0x3F))); i += 4;
        } else { ws.push_back(static_cast<wchar_t>(c)); ++i; }
    }
    for (wchar_t& wc : ws) wc = std::towupper(wc);
    std::string out;
    for (wchar_t wc : ws) {
        if (wc < 0x80) out.push_back(static_cast<char>(wc));
        else if (wc < 0x800) { out.push_back(static_cast<char>(0xC0 | (wc >> 6))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
        else { out.push_back(static_cast<char>(0xE0 | (wc >> 12))); out.push_back(static_cast<char>(0x80 | ((wc >> 6) & 0x3F))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
    }
    return out;
}

static std::string toLowerUtf8(const std::string& s) {
    std::wstring ws;
    size_t i = 0;
    while (i < s.size()) {
        unsigned char c = s[i];
        if (c < 0x80) { ws.push_back(static_cast<wchar_t>(c)); ++i; }
        else if ((c & 0xE0) == 0xC0 && i + 1 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x1F) << 6) | (s[i + 1] & 0x3F))); i += 2;
        } else if ((c & 0xF0) == 0xE0 && i + 2 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x0F) << 12) | ((s[i + 1] & 0x3F) << 6) | (s[i + 2] & 0x3F))); i += 3;
        } else if ((c & 0xF8) == 0xF0 && i + 3 < s.size()) {
            ws.push_back(static_cast<wchar_t>(((c & 0x07) << 18) | ((s[i + 1] & 0x3F) << 12) | ((s[i + 2] & 0x3F) << 6) | (s[i + 3] & 0x3F))); i += 4;
        } else { ws.push_back(static_cast<wchar_t>(c)); ++i; }
    }
    for (wchar_t& wc : ws) wc = std::towlower(wc);
    std::string out;
    for (wchar_t wc : ws) {
        if (wc < 0x80) out.push_back(static_cast<char>(wc));
        else if (wc < 0x800) { out.push_back(static_cast<char>(0xC0 | (wc >> 6))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
        else { out.push_back(static_cast<char>(0xE0 | (wc >> 12))); out.push_back(static_cast<char>(0x80 | ((wc >> 6) & 0x3F))); out.push_back(static_cast<char>(0x80 | (wc & 0x3F))); }
    }
    return out;
}

bool StorageEngine::ReadView::isVisible(uint64_t rowTxnId) const {
    if (rowTxnId == 0) return true;              // non-transactional rows always visible
    if (rowTxnId == creatorTxnId) return true;   // inserted by current transaction
    // Prepared transactions are retained in the active xid set across a
    // process restart. Check that set before age-based snapshot shortcuts:
    // a prepared xid may be numerically older than this snapshot's xmin but
    // must remain invisible until COMMIT PREPARED.
    if (activeTxnIds.count(rowTxnId)) return false;
    if (subTxnIds.count(rowTxnId)) return false;
    if (rowTxnId >= lowLimitId) return false;    // all newer xids not started

    // Snapshot xmin only proves that an older xid is no longer active; it
    // does not prove that it committed. Consult CLOG for every non-current
    // xid below xmax so an old aborted INSERT cannot become visible merely
    // because newer transactions advanced the snapshot horizon.
    if (commitLog) {
        auto status = commitLog->getStatus(static_cast<TxnId>(rowTxnId));
        if (status == CommitLog::Status::Committed) return true;
        // ABORTED, SUB_COMMITTED, and an unflushed IN_PROGRESS status are all
        // non-visible. Never infer a commit from a missing/unfinished CLOG
        // entry: doing so leaks uncommitted rows across snapshots.
        return false;
    }

    // Legacy callers without a CLOG retain the snapshot-only fallback.
    return true;
}

// Visibility using the current PostgreSQL-style HeapTupleHeader.
bool StorageEngine::ReadView::isVisible(const char* rowBuffer, size_t len, uint32_t formatVersion) const {
    if (len == 0) return false;
    if (!usesHeapTupleHeader(formatVersion)) return false;

    if (len < sizeof(HeapTupleHeaderData)) return false;
    const auto* htup = castHeapHeader(rowBuffer);

    uint64_t xmin = htup->t_fields.t_xmin;
    uint64_t xmax = htup->t_fields.t_xmax;
    uint32_t cmin = htup->t_fields.t_cid;
    uint32_t cmax = htup->t_fields.t_cid;
    bool comboResolved = true;
    if ((htup->t_infomask & HEAP_COMBOCID) != 0) {
        const auto combo = comboCommandIds.find(htup->t_fields.t_cid);
        if (combo == comboCommandIds.end()) {
            comboResolved = false;
        } else {
            cmin = combo->second.first;
            cmax = combo->second.second;
        }
    }

    // Use hint bits when available
    bool xminComm = xminCommitted(htup);
    bool xminInv = xminInvalid(htup);
    bool xmaxComm = xmaxCommitted(htup);
    bool xmaxInv = xmaxInvalid(htup);

    // --- xmin visibility ---
    bool xminVisible = false;
    if (xmin == 0) {
        xminVisible = true;
    } else if (xminInv) {
        xminVisible = false;
    } else if (xmin == creatorTxnId) {
        if (commandIdVisibility) {
            // A command reads the transaction snapshot from its start.  Its
            // own inserts (cmin >= curcid) are not visible to sibling CTEs or
            // the outer query until the command counter advances.
            if (!comboResolved) return false;
            xminVisible = cmin < currentCommandId;
        } else {
            xminVisible = true;
        }
    } else if (activeTxnIds.count(xmin)) {
        xminVisible = false; // transaction is still in progress
    } else if (subTxnIds.count(xmin)) {
        xminVisible = false; // subtransaction in progress
    } else if (xmin >= lowLimitId) {
        xminVisible = false;
    } else if (commitLog) {
        // CLOG is authoritative when it is available.  PITR can deliberately
        // change a transaction that committed on the source timeline into an
        // aborted transaction on the restored timeline, while heap pages may
        // still carry the old committed hint bit.
        auto s = commitLog->getStatus(static_cast<TxnId>(xmin));
        xminVisible = (s == CommitLog::Status::Committed);
    } else if (xminComm) {
        // Legacy callers without a CLOG may still use the tuple hint.
        xminVisible = true;
    } else {
        xminVisible = true; // fallback
    }

    if (!xminVisible) return false;

    // --- xmax (deletion/lock) visibility ---
    if (xmax == 0 || xmaxInv) return true; // not deleted
    if (xmaxIsLock(htup)) return true;     // xmax is only a lock, not deletion

    bool xmaxVisible = false; // true means row is still visible (delete not committed)
    if (xmax == creatorTxnId) {
        if (commandIdVisibility) {
            if (!comboResolved) return false;
            // A delete/update performed by this command is outside the
            // command snapshot, so the OLD version remains visible.
            xmaxVisible = cmax >= currentCommandId;
        } else {
            xmaxVisible = false; // current tx deleted it
        }
    } else if (activeTxnIds.count(xmax) || subTxnIds.count(xmax)) {
        xmaxVisible = true; // prepared/in-progress delete is not committed
    } else if (xmax >= lowLimitId) {
        xmaxVisible = true;
    } else if (commitLog) {
        // As with xmin, a restored timeline's CLOG overrides stale source-
        // timeline commit hints left in the heap tuple.
        auto s = commitLog->getStatus(static_cast<TxnId>(xmax));
        xmaxVisible = (s != CommitLog::Status::Committed);
    } else if (xmaxComm) {
        // The delete committed and was no longer active at snapshot time.
        xmaxVisible = false;
    } else {
        xmaxVisible = true;
    }

    return xmaxVisible;
}

static std::string trim(const std::string& s) {
    size_t a = 0;
    while (a < s.size() && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
    size_t b = s.size();
    while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
    return s.substr(a, b - a);
}

static bool parseFloatLiteral(const std::string& input, float& value) {
    const std::string token = trim(input);
    if (token.empty()) return false;
    errno = 0;
    char* end = nullptr;
    value = std::strtof(token.c_str(), &end);
    // ERANGE also reports a representable, nonzero subnormal. Reject only
    // genuine overflow/underflow, and still require the complete input.
    return end != token.c_str() && end == token.c_str() + token.size() &&
        !(errno == ERANGE && (value == 0.0f || std::isinf(value)));
}

static bool parseDoubleLiteral(const std::string& input, double& value) {
    const std::string token = trim(input);
    if (token.empty()) return false;
    errno = 0;
    char* end = nullptr;
    value = std::strtod(token.c_str(), &end);
    return end != token.c_str() && end == token.c_str() + token.size() &&
        !(errno == ERANGE && (value == 0.0 || std::isinf(value)));
}

static bool parseFiniteDouble(const std::string& input, double& value) {
    return parseDoubleLiteral(input, value) && std::isfinite(value);
}

static bool parseMoneyLiteral(const std::string& input, int64_t& minorUnits,
                              std::string* canonical = nullptr) {
    Money money;
    const std::string locale = StorageEngine::getMoneyLocale();
    if (!Money::parse(input, money, locale)) return false;
    minorUnits = money.minorUnits();
    if (canonical) *canonical = money.format(locale);
    return true;
}

static std::string moneyIndexKey(int64_t minorUnits) {
    // Bias the sign bit and emit fixed-width hexadecimal.  Lexicographic
    // B-tree order then exactly matches signed money order.
    const uint64_t ordered = static_cast<uint64_t>(minorUnits) ^
                             (uint64_t{1} << 63);
    char key[17] = {};
    const auto result = std::to_chars(key, key + 16, ordered, 16);
    if (result.ec != std::errc()) return {};
    const size_t digits = static_cast<size_t>(result.ptr - key);
    return std::string(16 - digits, '0') + std::string(key, result.ptr);
}

template <typename Floating>
static std::string formatFloatingValue(Floating value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return std::signbit(value) ? "-Infinity" : "Infinity";

    char buffer[64];
    const auto converted = std::to_chars(
        buffer, buffer + sizeof(buffer), value, std::chars_format::general);
    if (converted.ec == std::errc())
        return std::string(buffer, converted.ptr);

    // libstdc++ implementations with incomplete floating-point to_chars
    // support still get a lossless fallback.
    std::ostringstream out;
    out << std::setprecision(std::numeric_limits<Floating>::max_digits10)
        << value;
    return out.str();
}

static std::string formatPointCoordinate(double value) {
    return formatFloatingValue(value);
}

static bool isIntegerStorageType(const std::string& type) {
    return type == "tinyint" || type == "smallint" || type == "int" ||
           type == "integer" || type == "bigint" || type == "long" ||
           type == "int2" || type == "int4" || type == "int8" ||
           type == "tinyint unsigned" || type == "smallint unsigned" ||
           type == "int unsigned" || type == "integer unsigned" ||
           type == "bigint unsigned";
}

// Checked parsing must not use a valid datum (INT64_MIN) as its failure
// sentinel. The legacy parseInt API remains for compatibility callers.
static std::optional<int64_t> parseStoredInteger(const std::string& value) {
    if (value.empty()) return std::nullopt;
    const char* begin = value.data();
    const char* end = begin + value.size();
    if (*begin == '+') {
        if (++begin == end) return std::nullopt;
    }
    int64_t result = 0;
    const auto parsed = std::from_chars(begin, end, result, 10);
    if (parsed.ec != std::errc{} || parsed.ptr != end) return std::nullopt;
    return result;
}

// Semantic input is normalized before physical encoding. A zoned datum keeps
// its explicit UTC suffix so trigger/final validation cannot apply TimeZone twice.
// Key lookups intentionally do NOT round to the column's declaration precision.
static bool normalizeTemporalColumn(const Column& column, const std::string& value,
                                    std::string& canonical, bool applyPrecision = true) {
    try {
        CastExpr cast;
        cast.typeName = column.dataType == "datetime" ? "timestamp" : column.dataType;
        auto parameter = std::make_unique<ParameterExpr>();
        parameter->origin = ParameterOrigin::RuntimeCell;
        parameter->declaredType = "unknown";
        cast.operand = std::move(parameter);
        RowContext context;
        context.setParameters({ExprValue("unknown", value, false)});
        ExprEvaluator evaluator;
        const auto datum = evaluator.eval(&cast, context);
        if (datum.isNull) return false;
        const bool time = column.dataType == "time";
        const auto parsed = time ? temporal_storage_detail::parseTimeMicros(datum.value)
                                 : temporal_storage_detail::parseTimestampMicros(datum.value);
        if (!parsed) return false;
        const auto rounded = time
            ? temporal_storage_detail::roundTimeMicros(*parsed, applyPrecision ? column.typeMod : -1)
            : temporal_storage_detail::roundTimestampMicros(*parsed, applyPrecision ? column.typeMod : -1);
        if (!rounded) return false;
        canonical = time ? temporal_storage_detail::formatTimeMicros(*rounded)
                         : temporal_storage_detail::formatTimestampMicros(
                               *rounded, column.dataType == "timestamptz");
        return !canonical.empty();
    } catch (const DbError&) { return false; }
}

static std::optional<int64_t> temporalColumnMicros(const Column& column,
                                                  const std::string& value) {
    return column.dataType == "time"
        ? temporal_storage_detail::parseTimeMicros(value)
        : temporal_storage_detail::parseTimestampMicros(value);
}

static std::string canonicalColumnKeyValue(const Column& column,
                                           const std::string& value) {
    if (value.empty()) return {};
    if (column.storageCodec == Column::StorageCodec::TemporalMicros) {
        std::string canonical;
        if (!normalizeTemporalColumn(column, value, canonical, false)) return value;
        const auto micros = temporalColumnMicros(column, canonical);
        if (!micros) return value;
        // B+Tree stores only 20 bytes: ISO timestamp text loses all fractional
        // digits at that boundary. Bias the signed int64 then use 16 fixed hex
        // digits, preserving exact equality AND chronological byte ordering.
        uint64_t ordered = static_cast<uint64_t>(*micros) ^ (uint64_t{1} << 63);
        std::string key(16, '0');
        constexpr char hex[] = "0123456789abcdef";
        for (size_t digit = key.size(); digit-- > 0;) {
            key[digit] = hex[ordered & 15];
            ordered >>= 4;
        }
        return key;
    }
    if (!column.isArray && column.dataType == "regtype") {
        const Oid oid = stored_regtype_detail::rawOid(value);
        // Fixed width preserves unsigned OID ordering in the existing byte-key
        // B+tree/hash/SSI/unique-key owners. This is not a rendered type name.
        std::string key(8, '0');
        for (size_t digit=0; digit<8; ++digit)
            key[7-digit] = "0123456789abcdef"[(oid >> (4*digit)) & 15u];
        return key;
    }
    if (!column.isArray && isIntegerStorageType(column.dataType)) {
        // Heap encoding parses the integer datum, so index writes and unique
        // checks must not preserve alternate lexical spellings of that datum.
        const auto integer = parseStoredInteger(value);
        if (integer) return std::to_string(*integer);
        return value;
    }
    if (column.dataType == "char" || column.dataType == "character") {
        const size_t end = value.find_last_not_of(' ');
        return end == std::string::npos ? std::string() : value.substr(0, end + 1);
    }
    if (column.dataType == "float") {
        float parsed = 0.0f;
        if (!parseFloatLiteral(value, parsed)) return value;
        // IEEE -0 and +0 compare equal even though their display forms and
        // bit patterns differ. Index/constraint keys must therefore merge.
        return parsed == 0.0f ? "0" : formatFloatingValue(parsed);
    }
    if (column.dataType == "double" || column.dataType == "decimal") {
        double parsed = 0.0;
        if (!parseDoubleLiteral(value, parsed)) return value;
        return parsed == 0.0 ? "0" : formatFloatingValue(parsed);
    }
    if (column.dataType == "money") {
        int64_t minorUnits = 0;
        if (!parseMoneyLiteral(value, minorUnits)) return value;
        return moneyIndexKey(minorUnits);
    }
    if (column.dataType == "uuid") {
        UuidValue uuid;
        if (!UuidValue::parse(value, uuid)) return value;
        return uuid.indexKey();
    }
    if (!column.isArray && column.dataType == "numeric") {
        try {
            std::string key = Numeric(value).toString();
            // Numeric preserves display scale; keys must instead identify the
            // exact SQL value. Strip only fractional zeros, never integer zeros
            // or significant digits, and never round through float/double.
            if (key.find('.') != std::string::npos) {
                while (!key.empty() && key.back() == '0') key.pop_back();
                if (!key.empty() && key.back() == '.') key.pop_back();
            }
            return key;
        } catch (const std::invalid_argument&) {
            return value; // The mutation's value validator reports invalid input.
        } catch (const std::out_of_range&) {
            return value;
        }
    }
    return value;
}

std::string StorageEngine::groupingValueKey(const Column& column,
                                            const std::string& value,
                                            bool valueIsNull) {
    if (valueIsNull) return "N;";
    const std::string key = canonicalColumnKeyValue(column, value);
    return "V" + std::to_string(key.size()) + ":" + key;
}

template <typename Floating>
static int compareFloatingValues(Floating left, Floating right) {
    const bool leftNaN = std::isnan(left);
    const bool rightNaN = std::isnan(right);
    if (leftNaN) return rightNaN ? 0 : 1;
    if (rightNaN) return -1;
    return left < right ? -1 : (right < left ? 1 : 0);
}

static bool floatingPredicateMatches(const std::string& op, int comparison) {
    if (op == "=") return comparison == 0;
    if (op == "!=" || op == "<>") return comparison != 0;
    if (op == "<") return comparison < 0;
    if (op == ">") return comparison > 0;
    if (op == "<=") return comparison <= 0;
    if (op == ">=") return comparison >= 0;
    return false;
}

static bool normalizePointLiteral(const std::string& input, std::string& output,
                                  double* parsedX = nullptr,
                                  double* parsedY = nullptr) {
    dbms::GeometryValue value;
    if (!dbms::parseGeometryValue(input, "point", value)) return false;
    output = dbms::formatGeometryValue(value, false);
    if (output.empty()) return false;
    if (parsedX) *parsedX = value.coordinates[0];
    if (parsedY) *parsedY = value.coordinates[1];
    return true;
}

static bool normalizePointColumns(const TableSchema& table,
                                  std::map<std::string, std::string>& values,
                                  const std::set<std::string>* nullColumns = nullptr) {
    for (size_t i = 0; i < table.len; ++i) {
        const Column& column = table.cols[i];
        if (column.dataType != "point") continue;
        auto value = values.find(column.dataName);
        const bool isNull = value != values.end() &&
            (nullColumns ? nullColumns->count(column.dataName) != 0
                         : value->second == "NULL");
        if (value == values.end() || value->second.empty() || isNull)
            continue;
        std::string canonical;
        if (!normalizePointLiteral(value->second, canonical)) return false;
        value->second = std::move(canonical);
    }
    return true;
}

static size_t characterColumnByteLimit(const Column& column);

static bool variableColumnWidthsValid(
    const TableSchema& table,
    const std::map<std::string, std::string>& values,
    const std::set<std::string>* nullColumns = nullptr) {
    for (size_t i = 0; i < table.len; ++i) {
        const Column& column = table.cols[i];
        if (!column.isVariableLength) continue;
        const auto value = values.find(column.dataName);
        const bool isNull = value != values.end() &&
            (nullColumns ? nullColumns->count(column.dataName) != 0
                         : value->second == "NULL");
        if (value == values.end() || isNull) continue;
        const size_t maxLength = column.isArray && column.dataType != "regtype" ? 1024 :
            characterColumnByteLimit(column);
        if (value->second.size() > maxLength) return false;
    }
    return true;
}

static bool characterWidthLimitedType(const Column& column) {
    return !column.isArray &&
        (column.dataType == "char" || column.dataType == "character" ||
         column.dataType == "bpchar" || column.dataType == "varchar" ||
         column.dataType == "character varying");
}

static bool characterExcessIsSpaces(const std::string& value,
                                    size_t maximumLength);

static bool varyingCharacterColumn(const Column& column) {
    return !column.isArray &&
        (column.dataType == "varchar" ||
         column.dataType == "character varying");
}

static bool variableBlankPaddedCharacterColumn(const Column& column) {
    return !column.isArray && column.isVariableLength &&
        (column.dataType == "char" || column.dataType == "character" ||
         column.dataType == "bpchar");
}

static size_t characterColumnByteLimit(const Column& column) {
    if (!varyingCharacterColumn(column) &&
        !variableBlankPaddedCharacterColumn(column)) return column.dsize;
    // The row/TOAST representation still caps character values at 64 KiB.
    // Four bytes per declared character covers valid UTF-8 code points.
    return std::min(column.dsize * size_t(4), size_t(65535));
}

static bool truncateCharacterValue(std::string& value,
                                   size_t maximumCharacters,
                                   size_t* retainedCharacters = nullptr) {
    size_t characters = 0;
    size_t excessByte = value.size();
    for (size_t offset = 0; offset < value.size();) {
        if (characters == maximumCharacters && excessByte == value.size()) {
            excessByte = offset;
        }
        const unsigned char first = static_cast<unsigned char>(value[offset]);
        const size_t bytes = first < 0x80 ? 1 :
            (first & 0xe0) == 0xc0 ? 2 :
            (first & 0xf0) == 0xe0 ? 3 : 4;
        offset += std::min(bytes, value.size() - offset);
        ++characters;
    }
    if (characters <= maximumCharacters) {
        if (retainedCharacters) *retainedCharacters = characters;
        return true;
    }
    if (!characterExcessIsSpaces(value, excessByte)) return false;
    value.resize(excessByte);
    if (retainedCharacters) *retainedCharacters = maximumCharacters;
    return true;
}

static bool characterExcessIsSpaces(const std::string& value,
                                    size_t maximumLength) {
    return std::all_of(value.begin() + maximumLength, value.end(),
                       [](char c) { return c == ' '; });
}

static DBStatus normalizeCharacterColumnWidths(
    const TableSchema& table,
    std::map<std::string, std::string>& values,
    const std::set<std::string>* nullColumns = nullptr) {
    for (size_t i = 0; i < table.len; ++i) {
        const Column& column = table.cols[i];
        if (!characterWidthLimitedType(column)) continue;
        auto value = values.find(column.dataName);
        if (value == values.end() ||
            (nullColumns && nullColumns->count(column.dataName) != 0)) continue;
        if (varyingCharacterColumn(column) ||
            variableBlankPaddedCharacterColumn(column)) {
            size_t characters = 0;
            if (!truncateCharacterValue(
                    value->second, column.dsize, &characters)) {
                return DBStatus::STRING_DATA_RIGHT_TRUNCATION;
            }
            if (variableBlankPaddedCharacterColumn(column) &&
                characters < column.dsize) {
                value->second.append(column.dsize - characters, ' ');
            }
            if (value->second.size() > characterColumnByteLimit(column)) {
                return DBStatus::STRING_DATA_RIGHT_TRUNCATION;
            }
            continue;
        }
        if (value->second.size() > column.dsize) {
            if (!characterExcessIsSpaces(value->second, column.dsize))
                return DBStatus::STRING_DATA_RIGHT_TRUNCATION;
            value->second.resize(column.dsize);
        }
        if ((column.dataType == "char" || column.dataType == "character") &&
            value->second.size() < column.dsize) {
            value->second.append(column.dsize - value->second.size(), ' ');
        }
    }
    return DBStatus::OK;
}

static bool columnAcceptsEmptyValue(const Column& column) {
    if (column.isArray) return false;
    if (column.dataType == "bit varying") return true;
    if (!column.enumValues.empty()) {
        return std::find(column.enumValues.begin(), column.enumValues.end(),
                         std::string()) != column.enumValues.end();
    }
    const TypeEntry* type =
        TypeRegistry::instance().findType(column.dataType);
    return type && (type->category == TypeCategory::String ||
                    type->category == TypeCategory::Binary ||
                    type->category == TypeCategory::XML);
}

// HashIndex supports zero-byte keys. Only SQL NULL (or a legacy empty
// non-string sentinel) is absent, not a valid empty text/enum datum.
static bool hashKeyIncluded(const Column& column, const std::string& value,
                            bool isNull) {
    // During RENAME VALUE the new schema no longer admits the old empty
    // label, but its existing heap/index key must still be removed/undone.
    // Validate new writes at the DML boundary, not when maintaining OLD keys.
    const bool enumDatum = !column.isArray && !column.enumValues.empty();
    return !isNull &&
        (!value.empty() || enumDatum || columnAcceptsEmptyValue(column));
}

static std::string valueFromRowMap(
    const std::map<std::string, std::string>& values,
    const std::string& columnName) {
    const auto value = values.find(columnName);
    return value == values.end() ? std::string() : value->second;
}

static std::string canonicalKeyValueFromRowMap(
    const std::map<std::string, std::string>& values,
    const TableSchema& table, const std::string& columnName) {
    for (size_t i = 0; i < table.len; ++i) {
        if (table.cols[i].dataName == columnName) {
            return canonicalColumnKeyValue(
                table.cols[i], valueFromRowMap(values, columnName));
        }
    }
    return {};
}

static std::string buildCompositeKeyFromRowMap(
    const std::map<std::string, std::string>& values,
    const TableSchema& table,
    const std::vector<std::string>& columnNames) {
    std::string key;
    for (const auto& columnName : columnNames) {
        const Column* column = nullptr;
        for (size_t i = 0; i < table.len; ++i) {
            if (table.cols[i].dataName == columnName) {
                column = &table.cols[i];
                break;
            }
        }
        if (!column) continue;
        if (!key.empty()) key += '\x01';
        key += canonicalColumnKeyValue(
            *column, valueFromRowMap(values, columnName));
    }
    return key;
}

// Build a column-name -> data-type map from a TableSchema for expression eval.
static std::map<std::string, std::string> buildTypeHints(const dbms::TableSchema& tbl) {
    std::map<std::string, std::string> hints;
    for (size_t i = 0; i < tbl.len; ++i) {
        hints[tbl.cols[i].dataName] = tbl.cols[i].dataType + (tbl.cols[i].isArray ? "[]" : "");
    }
    return hints;
}

// Callers that retain SQL NULL metadata need the evaluator's NULL bit as well
// as its text.  A string result equal to "NULL" is ordinary data and must not
// be folded into SQL NULL at this boundary.
static bool evalExpressionSqlValue(
    const std::string& exprSql,
    const std::map<std::string, std::string>& row,
    const std::map<std::string, std::string>& typeHints,
    const std::string& currentDB,
    std::string& value,
    bool& isNull,
    const std::set<std::string>* nullColumns = nullptr,
    StorageEngine* functionEngine = nullptr,
    bool referenceOutput = false,
    const TableSchema* referenceSchema = nullptr,
    std::optional<ExprValue>* owningValue = nullptr,
    const StorageEngine::OwningSqlRow* owningInputs = nullptr,
    const DatumMetadataContext* datumMetadata = nullptr) {
    if (owningValue) owningValue->reset();
    value.clear();
    isNull = false;
    if (exprSql.empty()) return false;
    DatumMetadataContextPtr referenceMetadata;
    if(referenceOutput && referenceSchema && functionEngine)
        referenceMetadata=functionEngine->prepareDatumMetadataContext(currentDB,referenceSchema->tablename);
    const bool captureValue = referenceOutput || owningValue;
    auto result = nullColumns
        ? dbms::ExprHelper::evalStringWithNulls(
              exprSql, row, *nullColumns, typeHints, currentDB, "", functionEngine,
              {}, captureValue, owningInputs, datumMetadata ? datumMetadata : referenceMetadata.get())
        : dbms::ExprHelper::evalString(
              exprSql, row, typeHints, currentDB, "", functionEngine,
              captureValue, datumMetadata ? datumMetadata : referenceMetadata.get());
    if (!result.ok) return false;
    isNull = result.isNull;
    if (!isNull) {
        if(referenceOutput) {
            if(!result.owningValue)return false;
            value=stored_regtype_detail::storageText(*result.owningValue);
        } else value = result.value;
    }
    if (owningValue && result.owningValue) *owningValue=std::move(result.owningValue);
    return true;
}

static std::string storedPatternOperator(const std::string& input) {
    std::string op;
    for (const unsigned char c : input) if (!std::isspace(c)) op += std::tolower(c);
    if (op == "like" || op == "~~") return "like";
    if (op == "notlike" || op == "!~~") return "notlike";
    if (op == "ilike" || op == "~~*") return "ilike";
    if (op == "notilike" || op == "!~~*") return "notilike";
    if (op == "similar" || op == "similarto") return "similar";
    if (op == "notsimilar" || op == "notsimilarto") return "notsimilar";
    return {};
}

static bool storedPatternTextType(const std::string& input) {
    const auto type = ExprHelper::canonicalResultTypeName(input);
    return type == "text" || type == "character varying" || type == "character" ||
           type == "name" || type == "citext" || type == "unknown";
}

static void validateStoredPatternTypes(const Column& column,
                                      const StorageEngine::Condition& condition) {
    const auto op = storedPatternOperator(condition.op);
    if (op.empty()) return;
    const bool bytes = isByteaTypeName(column.dataType);
    const bool like = op == "like" || op == "notlike";
    const auto accepts = [&](const std::string& type) {
        return type.empty() || type == "unknown" ||
               (bytes ? isByteaTypeName(type) : storedPatternTextType(type));
    };
    if (column.isArray || (bytes ? !like : !storedPatternTextType(column.dataType)) ||
        !accepts(condition.patternType) || !accepts(condition.patternEscapeType))
        throw DbError("42883", "operator does not exist for stored pattern operand types");
}

static std::string storedPatternBytes(const std::string& input) {
    ByteaValue value;
    if (!ByteaValue::parse(input,value)) throw DbError("22P02", "invalid input syntax for type bytea");
    return value.bytes();
}

static std::string storedPatternTextArgument(std::string value,const std::string& type) {
    if (ExprHelper::canonicalResultTypeName(type)=="character")
        while (!value.empty() && value.back()==' ') value.pop_back();
    return value;
}

static StorageEngine::Condition bindStoredPatternTypes(
    const TableSchema& table, const StorageEngine::Condition& input) {
    auto condition = input;
    if (storedPatternOperator(condition.op).empty()) return condition;
    const Column* left = nullptr;
    for (size_t i=0;i<table.len;++i) {
        const auto& column = table.cols[i];
        const auto type = column.dataType + (column.isArray ? "[]" : "");
        if (column.dataName == condition.colName) left = &column;
        if (!condition.decodedLiteralRhs && column.dataName == condition.value)
            condition.patternType = type;
        if (column.dataName == condition.patternEscapeColumn)
            condition.patternEscapeType = type;
    }
    if (!condition.patternEscapeColumn.empty() && condition.patternEscapeType.empty())
        throw DbError("42703", "pattern escape column does not exist");
    if (left) {
        validateStoredPatternTypes(*left,condition);
        if (condition.decodedLiteralRhs && !condition.patternIsNull &&
            condition.patternEscape && !condition.patternEscapeIsNull &&
            condition.patternEscapeColumn.empty()) {
            const bool bytes=isByteaTypeName(left->dataType);
            const auto escape=bytes ? storedPatternBytes(*condition.patternEscape)
                : storedPatternTextArgument(*condition.patternEscape,condition.patternEscapeType);
            if (sql_pattern::characters(escape,bytes).size()>1)
                throw DbError("22025", "invalid escape string");
        }
    }
    return condition;
}

static std::vector<StorageEngine::Condition> prepareStoredUnknownBitScalarInputs(
    const TableSchema& table, const std::vector<StorageEngine::Condition>& inputs) {
    auto conditions = inputs;
    for (auto& condition : conditions) {
        // Only a genuine SQL string-literal occurrence has UNKNOWN input
        // identity. Native apicond values remain decoded data, not SQL input.
        if (condition.patternType != "unknown" || !condition.decodedLiteralRhs ||
            !(condition.op == "=" || condition.op == "<>" || condition.op == "!=" ||
              condition.op == "<" || condition.op == ">" || condition.op == "<=" ||
              condition.op == ">=")) continue;
        for (size_t i = 0; i < table.len; ++i) {
            const auto& column = table.cols[i];
            if (column.dataName != condition.colName) continue;
            // Storage publishes the actual base representation. A TEXT
            // domain called varbit is not a BIT column by spelling.
            if (column.isArray || (column.dataType != "bit" && column.dataType != "bit varying")) break;
            const auto binding = ExprEvaluator::resolveComparison(condition.op, column.dataType, "unknown");
            ExprEvaluator evaluator;
            const auto input = evaluator.coerceComparison(binding, ExprValue("unknown", condition.value, condition.patternIsNull), false);
            condition.value = input.value;
            condition.patternType = input.typeName;
            break;
        }
    }
    return conditions;
}

// This is a WHERE-only truth property, not value folding: NULL remains
// Unknown in projections, NOT, CASE and function arguments. Only positive
// AND/OR branches containing an actual strict column/NULL comparison qualify.
static bool nullWhereComparison(const Expr* expression) {
    const auto* binary=dynamic_cast<const BinaryOpExpr*>(expression);
    if(!binary) return false;
    if(binary->op=="AND") return nullWhereComparison(binary->left.get()) || nullWhereComparison(binary->right.get());
    if(binary->op=="OR") return nullWhereComparison(binary->left.get()) && nullWhereComparison(binary->right.get());
    if(binary->op!="=" && binary->op!="<>" && binary->op!="!=" && binary->op!="<" &&
       binary->op!=">" && binary->op!="<=" && binary->op!=">=") return false;
    const auto isNull=[](const Expr* operand) {
        const auto* literal=dynamic_cast<const LiteralExpr*>(operand);
        return literal && literal->typeName.empty() && !literal->preparedSubquery && literal->value=="null";
    };
    const auto column=[](const Expr* operand) {
        const auto* reference=dynamic_cast<const ColumnRefExpr*>(operand);
        return reference && reference->schema.empty() && reference->table.empty();
    };
    return (column(binary->left.get()) && isNull(binary->right.get())) ||
           (column(binary->right.get()) && isNull(binary->left.get()));
}

static bool containsNullWhereComparison(const Expr* expression) {
    if(nullWhereComparison(expression)) return true;
    const auto* binary=dynamic_cast<const BinaryOpExpr*>(expression);
    return binary && (binary->op=="AND" || binary->op=="OR") &&
        (containsNullWhereComparison(binary->left.get()) || containsNullWhereComparison(binary->right.get()));
}

static bool nullScalarComparison(const StorageEngine::Condition& condition) {
    return condition.patternIsNull && (condition.op=="typedexpr" || condition.op=="=" || condition.op=="<>" || condition.op=="!=" ||
        condition.op=="<" || condition.op==">" || condition.op=="<=" || condition.op==">=");
}

static void validateNullWhereColumns(const Expr* expression,const TableSchema& table) {
    const auto* binary=dynamic_cast<const BinaryOpExpr*>(expression);
    if(!binary) return;
    if(binary->op=="AND" || binary->op=="OR") {
        validateNullWhereColumns(binary->left.get(),table);validateNullWhereColumns(binary->right.get(),table);return;
    }
    if(!nullWhereComparison(expression)) return;
    const auto* column=dynamic_cast<const ColumnRefExpr*>(binary->left.get());
    if(!column) column=dynamic_cast<const ColumnRefExpr*>(binary->right.get());
    for(size_t i=0;i<table.len;++i) if(table.cols[i].dataName==column->column) return;
    throw DbError("42703","column does not exist: "+column->column);
}

static bool nullScalarBranch(const std::vector<StorageEngine::Condition>& conditions) {
    return std::any_of(conditions.begin(), conditions.end(), nullScalarComparison);
}

static void validateStoredPatternConditions(
    const TableSchema& table, const std::vector<StorageEngine::Condition>& conditions) {
    for (const auto& condition : conditions) {
        if (nullScalarComparison(condition) && condition.op!="typedexpr") {
            bool found=false;
            for(size_t i=0;i<table.len;++i) if(table.cols[i].dataName==condition.colName) {
                found=true;
                (void)ExprEvaluator::resolveComparison(condition.op,table.cols[i].dataType+
                    (table.cols[i].isArray?"[]":""),"unknown");
                break;
            }
            if(!found) throw DbError("42703","column does not exist: "+condition.colName);
        }
        (void)bindStoredPatternTypes(table,condition);
        // The SQL literal adapter retains BIT operand type independently
        // of its decoded bytes. The existing right-operand type slot also
        // carries this metadata for non-pattern scalar/list predicates.
        if (condition.patternType != "bit" || !storedPatternOperator(condition.op).empty()) continue;
        for (size_t i=0;i<table.len;++i) if (table.cols[i].dataName==condition.colName) {
            const auto& column=table.cols[i];
            (void)ExprEvaluator::resolveComparison("=",column.dataType+(column.isArray?"[]":""),"bit");
            if (condition.op=="in" || condition.op=="notin" ||
                condition.op=="between" || condition.op=="notbetween") {
                const auto tokens=SQLParser::tokenize(condition.value);
                const bool range=condition.op=="between" || condition.op=="notbetween";
                if(range && tokens.size()!=2)throw DbError("42601","BIT BETWEEN requires two operands");
                const auto hints=buildTypeHints(table);
                ExprEvaluator evaluator;
                for(size_t member=0;member<tokens.size();++member) {
                    SQLParser parser;auto parsed=parser.parse("SELECT "+tokens[member]);
                    const auto* select=parsed.success ? dynamic_cast<const SelectStmt*>(parsed.stmt.get()) : nullptr;
                    if(!select || select->selectList.size()!=1 || select->fromClause)
                        throw DbError("42601","invalid compact BIT predicate operand");
                    const auto* operand=select->selectList.front().expr.get();
                    if(const auto* reference=dynamic_cast<const ColumnRefExpr*>(operand);
                       reference && reference->table.empty() && !hints.count(reference->column))
                        throw DbError("42703","compact predicate column does not exist: "+reference->column);
                    const auto type=ExprHelper::inferParsedInputType(operand,hints);
                    const auto binding=ExprEvaluator::resolveComparison(range ? (member==0?">=":"<=") : "=",
                        column.dataType+(column.isArray?"[]":""),type);
                    // Signature resolution is schema-owned and complete.
                    // Only a real pure literal may be input-validated here;
                    // row references, parameters and routines are not run.
                    if(const auto* literal=dynamic_cast<const LiteralExpr*>(operand);
                       literal && !literal->preparedSubquery) {
                        auto value=evaluator.eval(operand,{});value.typeName=type;
                        (void)evaluator.coerceComparison(binding,value,false);
                    }
                }
            }
            break;
        }
    }
}

static StorageEngine::PredicateTruth storedPatternTruth(
    const Column& column, const std::string& value, bool valueIsNull,
    const std::string& pattern, bool patternIsNull,
    const StorageEngine::Condition& condition) {
    using Truth = StorageEngine::PredicateTruth;
    validateStoredPatternTypes(column,condition);
    if (patternIsNull || condition.patternIsNull || condition.patternEscapeIsNull)
        return Truth::Unknown;
    const bool bytes = isByteaTypeName(column.dataType);
    const std::string escape = condition.patternEscape
        ? (bytes ? storedPatternBytes(*condition.patternEscape)
                 : storedPatternTextArgument(*condition.patternEscape,condition.patternEscapeType))
        : "\\";
    if (condition.patternEscape && sql_pattern::characters(escape,bytes).size() > 1)
        throw DbError("22025", "invalid escape string");
    if (valueIsNull) return Truth::Unknown;
    std::string source = bytes ? storedPatternBytes(value) : value;
    std::string match = bytes ? storedPatternBytes(pattern) : pattern;
    if (!bytes) match=storedPatternTextArgument(std::move(match),condition.patternType);
    // The retained SQL string normalizer used 0x01 to encode escape literals.
    // Translate only that untagged legacy form; decoded native data keeps it.
    if (!condition.patternEscape && !condition.decodedLiteralRhs && condition.patternType.empty() &&
        match.find(char(1)) != std::string::npos) {
        std::string translated;
        for (size_t i=0;i<match.size();++i) {
            if (match[i] == char(1)) translated += '\\';
            else { if (match[i] == '\\') translated += '\\'; translated += match[i]; }
        }
        match = std::move(translated);
    }
    const auto locale = collation::normalizeName(column.resolvedCollation.empty()
        ? column.collation : column.resolvedCollation);
    const bool ascii = locale == "c" || locale == "posix";
    const auto op = storedPatternOperator(condition.op);
    bool matched = (op == "similar" || op == "notsimilar")
        ? sql_pattern::similar(source,match,escape,ascii)
        : sql_pattern::like(source,match,escape,op == "ilike" || op == "notilike",bytes,ascii);
    if (op == "notlike" || op == "notilike" || op == "notsimilar") matched = !matched;
    return matched ? Truth::True : Truth::False;
}

// REGEXP pattern matching (ECMAScript syntax), case-insensitive
static bool regexMatch(const std::string& text, const std::string& pattern) {
    try {
        std::regex re(pattern, std::regex::icase | std::regex::ECMAScript);
        return std::regex_search(text, re);
    } catch (...) {
        return false;
    }
}

// ========================================================================
// Helper: fixed-length string IO for the current binary catalog format.
// ========================================================================
static void writeFixedString(std::ostream& out, const std::string& s, size_t len) {
    std::string buf = s;
    buf.resize(len, '\0');
    out.write(buf.data(), static_cast<std::streamsize>(len));
}

static bool writeFixedStringRecordsAtomically(
    const std::filesystem::path& path,
    const std::vector<std::string>& records,
    size_t recordLength) {
    std::ostringstream serialized(std::ios::out | std::ios::binary);
    for (const auto& record : records) {
        writeFixedString(serialized, record, recordLength);
    }
    if (!serialized) return false;
    const std::string bytes = serialized.str();
    if (index_file::writeAtomically(path, bytes)) return true;

    // writeAtomically can report a parent-directory fsync error after the
    // rename has already published the complete file.  Retry that barrier
    // only when the destination exactly matches our serialized generation;
    // this turns transient fsync errors into a confirmed durable result while
    // preserving the error for failures that did not publish these bytes.
    std::ifstream current(path, std::ios::binary);
    if (!current) return false;
    const std::string published{
        std::istreambuf_iterator<char>(current),
        std::istreambuf_iterator<char>()};
    if (current.bad() || published != bytes) return false;
    const auto parent = path.parent_path().empty()
        ? std::filesystem::path(".") : path.parent_path();
    return index_file::syncDirectory(parent);
}

static std::string readFixedString(std::istream& in, size_t len) {
    std::string buf(len, '\0');
    in.read(buf.data(), static_cast<std::streamsize>(len));
    auto pos = buf.find('\0');
    if (pos != std::string::npos) buf.resize(pos);
    return buf;
}

static bool validStoredIdentifier(const std::string& value, size_t fieldSize) {
    return value.find('\0') == std::string::npos && value.size() < fieldSize &&
           value.find('/') == std::string::npos &&
           value.find('\\') == std::string::npos &&
           value != "." && value != "..";
}

static bool validStoredRelationName(const std::string& value) {
    return relation_name_codec::valid(value);
}

static bool writeRelationListAtomically(const std::filesystem::path& path,
                                        const std::vector<std::string>& names) {
    const auto bytes = relation_name_codec::encode(names);
    return bytes && index_file::writeAtomically(path, *bytes);
}

static std::string primaryKeyConstraintName(const TableSchema& table) {
    if (!table.hasPrimaryKey()) return {};
    const auto storedName = table.storageParams.find(
        PRIMARY_KEY_CONSTRAINT_NAME_PARAM);
    if (storedName != table.storageParams.end() &&
        !storedName->second.empty()) {
        return storedName->second;
    }
    return table.tablename + "_pkey";
}

// Auxiliary object definitions are stored in line-oriented sidecars.  Keep
// their object names safe both as path components and as metadata fields; a
// delimiter or newline here would make the definition ambiguous on reload.
static bool validMetadataObjectName(const std::string& value) {
    if (value.empty() || !validStoredIdentifier(value, MAX_TABLE_NAME_LEN)) {
        return false;
    }
    for (char c : value) {
        if (c == '|' || c == ':' || c == ',' || c == '\n' || c == '\r') {
            return false;
        }
    }
    return true;
}

static bool ensureMetadataDirectory(const std::filesystem::path& path) {
    std::error_code error;
    if (std::filesystem::exists(path, error)) {
        return !error && std::filesystem::is_directory(path, error) && !error;
    }
    if (!std::filesystem::create_directories(path, error) && error) return false;
    return std::filesystem::is_directory(path, error) && !error;
}

static DBStatus persistMetadata(const std::filesystem::path& path,
                                const std::string& contents) {
    return index_file::writeAtomically(path, contents) ? DBStatus::OK : DBStatus::IO_ERROR;
}

static bool normalizeForeignKeyAction(const std::string& action,
                                      std::string& normalized) {
    std::string compact;
    compact.reserve(action.size());
    for (const char c : action) {
        if (std::isspace(static_cast<unsigned char>(c)) || c == '_') {
            continue;
        }
        compact.push_back(static_cast<char>(
            std::tolower(static_cast<unsigned char>(c))));
    }
    if (compact.empty() || compact == "restrict" ||
        compact == "noaction") {
        normalized = "restrict";
        return true;
    }
    if (compact == "cascade") {
        normalized = "cascade";
        return true;
    }
    if (compact == "setnull") {
        normalized = "setnull";
        return true;
    }
    return false;
}

static bool validateTableSchemaIdentifiers(const TableSchema& tbl, std::string* error) {
    auto reject = [&](const std::string& value, size_t fieldSize, const char* kind) {
        if (validStoredIdentifier(value, fieldSize)) return false;
        if (error) *error = std::string(kind) + " exceeds the current 63-byte identifier limit";
        return true;
    };
    if (!validStoredRelationName(tbl.tablename)) {
        if (error) *error = "invalid table storage identity (each SQL identifier is limited to 63 bytes)";
        return false;
    }
    if (tbl.len > MAX_COLUMNS || tbl.fkLen > MAX_COLUMNS) {
        if (error) *error = "table exceeds the current column or constraint limit";
        return false;
    }
    std::set<std::string> columnNames;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (reject(tbl.cols[i].dataName, MAX_COL_NAME_LEN, "column name") ||
            reject(tbl.cols[i].dataType, MAX_TYPE_NAME_LEN, "type name") ||
            reject(tbl.cols[i].checkConstraintName, MAX_COL_NAME_LEN, "constraint name")) {
            return false;
        }
        if (!columnNames.insert(tbl.cols[i].dataName).second) {
            if (error) {
                *error = "duplicate column name: " + tbl.cols[i].dataName;
            }
            return false;
        }
        if (tbl.cols[i].checkExpr.size() >
            std::numeric_limits<uint16_t>::max()) {
            if (error) *error = "CHECK constraint expression is too long";
            return false;
        }
    }
    std::set<size_t> primaryKeyColumns;
    if (!tbl.pkColIndices.empty()) {
        if (tbl.pkColIndices.size() > tbl.len) {
            if (error) *error = "invalid primary key column metadata";
            return false;
        }
        for (const size_t columnIndex : tbl.pkColIndices) {
            if (columnIndex >= tbl.len ||
                !primaryKeyColumns.insert(columnIndex).second) {
                if (error) *error = "invalid primary key column metadata";
                return false;
            }
        }
        for (size_t columnIndex = 0; columnIndex < tbl.len;
             ++columnIndex) {
            if (tbl.cols[columnIndex].isPrimaryKey &&
                primaryKeyColumns.count(columnIndex) == 0) {
                if (error) {
                    *error = "primary key flags conflict with primary key columns";
                }
                return false;
            }
        }
    }
    for (const auto& name : tbl.uniqueConstraintNames) {
        if (reject(name, MAX_TABLE_NAME_LEN, "constraint name")) return false;
    }
    if (tbl.uniqueConstraints.size() > MAX_COLUMNS ||
        tbl.uniqueConstraintNames.size() > tbl.uniqueConstraints.size()) {
        if (error) *error = "invalid UNIQUE constraint metadata";
        return false;
    }
    for (const auto& constraint : tbl.uniqueConstraints) {
        if (constraint.empty() || constraint.size() > tbl.len) {
            if (error) *error = "UNIQUE constraint requires valid columns";
            return false;
        }
        std::set<size_t> distinctColumns;
        for (const size_t columnIndex : constraint) {
            if (columnIndex >= tbl.len ||
                !distinctColumns.insert(columnIndex).second) {
                if (error) *error = "invalid UNIQUE constraint column metadata";
                return false;
            }
        }
    }
    if (tbl.additionalCheckConstraints.size() > 1024) {
        if (error) *error = "too many CHECK constraints";
        return false;
    }
    for (const auto& check : tbl.additionalCheckConstraints) {
        if (reject(check.name, MAX_TABLE_NAME_LEN, "constraint name")) {
            return false;
        }
        if (check.expression.empty() || check.expression.size() > 1024 * 1024) {
            if (error) *error = "CHECK constraint expression is invalid";
            return false;
        }
    }
    for (size_t i = 0; i < tbl.fkLen; ++i) {
        std::string normalizedDelete;
        std::string normalizedUpdate;
        if (reject(tbl.fks[i].name, MAX_TABLE_NAME_LEN, "constraint name") ||
            !validStoredRelationName(tbl.fks[i].refTable) ||
            !normalizeForeignKeyAction(
                tbl.fks[i].onDelete, normalizedDelete) ||
            !normalizeForeignKeyAction(
                tbl.fks[i].onUpdate, normalizedUpdate)) {
            if (error && error->empty()) {
                *error = "unsupported foreign key referential action";
            }
            return false;
        }
        for (const auto& name : tbl.fks[i].colNames) {
            if (reject(name, MAX_COL_NAME_LEN, "column name")) return false;
        }
        for (const auto& name : tbl.fks[i].refCols) {
            if (reject(name, MAX_COL_NAME_LEN, "column name")) return false;
        }
    }
    return true;
}

// ========================================================================
// Column / TableSchema
// ========================================================================
void Column::print() const {
    std::cout << "ColumnName: " << dataName << '\n';
    std::cout << "hasNull: " << isNull << '\n';
    std::cout << "PrimaryKey: " << isPrimaryKey << '\n';
    std::cout << "DataType: " << dataType << '\n';
    std::cout << "DataSize: " << dsize << "\n\n";
}

void TableSchema::append(const Column& ncol) {
    if (len < MAX_COLUMNS) {
        cols[len++] = ncol;
    }
}

void TableSchema::appendFK(const ForeignKey& fk) {
    if (fkLen < MAX_COLUMNS) {
        fks[fkLen++] = fk;
    }
}

void TableSchema::print() const {
    std::cout << tablename << "\n\n";
    for (size_t i = 0; i < len; ++i) cols[i].print();
    if (fkLen > 0) {
        std::cout << "Foreign Keys:\n";
        for (size_t i = 0; i < fkLen; ++i) {
            std::cout << "  ";
            for (size_t ci = 0; ci < fks[i].colNames.size(); ++ci) {
                if (ci > 0) std::cout << ",";
                std::cout << fks[i].colNames[ci];
            }
            std::cout << " -> " << fks[i].refTable << "(";
            for (size_t ci = 0; ci < fks[i].refCols.size(); ++ci) {
                if (ci > 0) std::cout << ",";
                std::cout << fks[i].refCols[ci];
            }
            std::cout << ") ON DELETE " << fks[i].onDelete;
            if (!fks[i].onUpdate.empty() && fks[i].onUpdate != "restrict")
                std::cout << " ON UPDATE " << fks[i].onUpdate;
            std::cout << "\n";
        }
    }
}

size_t TableSchema::rowSize() const {
    size_t total = 0;
    for (size_t i = 0; i < len; ++i) total += cols[i].dsize;
    return total + rowHeaderSize(formatVersion, len);
}

bool TableSchema::hasVariableLength() const {
    for (size_t i = 0; i < len; ++i) {
        if (cols[i].isVariableLength) return true;
    }
    return false;
}

size_t TableSchema::fixedDataSize() const {
    size_t total = 0;
    for (size_t i = 0; i < len; ++i) {
        if (!cols[i].isVariableLength) total += cols[i].dsize;
    }
    return total;
}

size_t TableSchema::varColCount() const {
    size_t count = 0;
    for (size_t i = 0; i < len; ++i) {
        if (cols[i].isVariableLength) ++count;
    }
    return count;
}

size_t TableSchema::getVarColIndex(size_t colIdx) const {
    size_t idx = 0;
    for (size_t i = 0; i < colIdx; ++i) {
        if (cols[i].isVariableLength) ++idx;
    }
    return idx;
}

size_t TableSchema::getFixedColOffset(size_t colIdx) const {
    size_t off = 0;
    for (size_t i = 0; i < colIdx; ++i) {
        if (!cols[i].isVariableLength) off += cols[i].dsize;
    }
    return off;
}

