}

namespace {

struct PartitionLeaf {
    std::string partition;
    std::string subPartition;
};

std::vector<PartitionLeaf> partitionLeaves(const TableSchema& table) {
    std::vector<std::string> partitions;
    if (table.partitionType == TableSchema::PartitionType::Range) {
        for (const auto& entry : table.rangePartitions) {
            partitions.push_back(entry.first);
        }
    } else if (table.partitionType == TableSchema::PartitionType::List) {
        for (const auto& entry : table.listPartitions) {
            partitions.push_back(entry.first);
        }
    } else if (table.partitionType == TableSchema::PartitionType::Hash) {
        for (size_t index = 0; index < table.hashPartitions; ++index) {
            partitions.push_back("p" + std::to_string(index));
        }
    }
    if (!table.defaultPartitionName.empty() &&
        std::find(partitions.begin(), partitions.end(),
                  table.defaultPartitionName) == partitions.end()) {
        partitions.push_back(table.defaultPartitionName);
    }

    std::vector<PartitionLeaf> leaves;
    for (const auto& partition : partitions) {
        if (table.subPartitionType == TableSchema::PartitionType::Hash) {
            for (size_t index = 0; index < table.subHashPartitions; ++index) {
                leaves.push_back(
                    {partition, "sp" + std::to_string(index)});
            }
        } else {
            leaves.push_back({partition, ""});
        }
    }
    return leaves;
}

// Heap WAL already carries a 32-bit fork number.  Derive a stable non-zero
// physical-partition identity from both path components instead of recording
// a local page as a parent-table page.  A collision is always detected by
// resolving against the complete schema and therefore fails closed.
uint32_t partitionForkNumber(const std::string& partition,
                             const std::string& subPartition) {
    uint32_t hash = 2166136261u;
    const auto add = [&](unsigned char byte, uint32_t& value) {
        value ^= byte;
        value *= 16777619u;
    };
    for (unsigned char byte : partition) add(byte, hash);
    add(0xffu, hash);
    for (unsigned char byte : subPartition) add(byte, hash);
    return hash == 0 ? 1u : hash;
}

bool resolvePartitionFork(const TableSchema& table, uint32_t forkNum,
                          PartitionLeaf& resolved, bool& collision) {
    collision = false;
    bool found = false;
    for (const auto& leaf : partitionLeaves(table)) {
        if (partitionForkNumber(leaf.partition, leaf.subPartition) != forkNum) {
            continue;
        }
        if (found) {
            collision = true;
            return false;
        }
        resolved = leaf;
        found = true;
    }
    return found;
}

bool partitionForkIsUnique(const TableSchema& table,
                           const std::string& partition,
                           const std::string& subPartition) {
    const uint32_t forkNum =
        partitionForkNumber(partition, subPartition);
    PartitionLeaf resolved;
    bool collision = false;
    return resolvePartitionFork(table, forkNum, resolved, collision) &&
           !collision && resolved.partition == partition &&
           resolved.subPartition == subPartition;
}

}  // namespace

bool StorageEngine::ensureUnloggedInitForks(
    const std::string& dbname, const std::string& tablename) {
    try {
        const TableSchema table = getTableSchema(dbname, tablename);
        if (!table.isUnlogged) return false;

        std::vector<std::pair<std::filesystem::path, size_t>> heaps;
        if (table.partitionType == TableSchema::PartitionType::None) {
            heaps.emplace_back(dataPath(dbname, tablename), table.rowSize());
        } else {
            std::set<std::string> parentPartitions;
            for (const auto& leaf : partitionLeaves(table)) {
                if (parentPartitions.insert(leaf.partition).second) {
                    heaps.emplace_back(
                        partitionDataPath(
                            dbname, tablename, leaf.partition),
                        table.rowSize());
                }
                if (!leaf.subPartition.empty()) {
                    heaps.emplace_back(
                        partitionDataPath(
                            dbname, tablename, leaf.partition,
                            leaf.subPartition),
                        table.rowSize());
                }
            }
        }
        const bool hasVariableLength = std::any_of(
            table.cols, table.cols + table.len,
            [](const Column& column) { return column.isVariableLength; });
        if (hasVariableLength) {
            heaps.emplace_back(toastDataPath(dbname, tablename), 0);
        }

        static std::atomic<uint64_t> initSequence{0};
        for (const auto& [mainPath, rowSize] : heaps) {
            auto initPath = mainPath;
            initPath += ".init";
            std::error_code error;
            const bool exists = std::filesystem::exists(initPath, error);
            if (error) return false;
            bool valid = false;
            if (exists &&
                std::filesystem::is_regular_file(initPath, error) && !error &&
                std::filesystem::file_size(initPath, error) ==
                    pageSizeForFormatVersion(table.formatVersion) && !error) {
                PageAllocator existing(
                    initPath.string(), rowSize,
                    pageSizeForFormatVersion(table.formatVersion),
                    table.formatVersion);
                valid = existing.open() && existing.numPages() == 1;
                existing.close();
            }
            if (valid) continue;

            auto temporary = initPath;
            temporary += ".tmp." + std::to_string(::getpid()) + "." +
                std::to_string(initSequence.fetch_add(
                    1, std::memory_order_relaxed));
            auto temporaryTde = temporary;
            temporaryTde += ".tde";
            std::filesystem::remove(temporary, error);
            error.clear();
            std::filesystem::remove(temporaryTde, error);

            PageAllocator empty(
                temporary.string(), rowSize,
                pageSizeForFormatVersion(table.formatVersion),
                table.formatVersion);
            if (!empty.open() || empty.numPages() != 1 || !empty.flush()) {
                empty.close();
                std::filesystem::remove(temporary, error);
                error.clear();
                std::filesystem::remove(temporaryTde, error);
                return false;
            }
            empty.close();

            std::ifstream input(temporary, std::ios::binary);
            const std::string bytes{
                std::istreambuf_iterator<char>(input),
                std::istreambuf_iterator<char>()};
            const bool readOk = !input.bad() &&
                bytes.size() == pageSizeForFormatVersion(table.formatVersion);
            const bool published = readOk &&
                index_file::writeAtomically(initPath, bytes);
            std::filesystem::remove(temporary, error);
            error.clear();
            std::filesystem::remove(temporaryTde, error);
            if (!published) return false;
        }
        return true;
    } catch (const std::exception& error) {
        std::cerr << "[storage] cannot initialize UNLOGGED forks for "
                  << dbname << "/" << tablename << ": "
                  << error.what() << std::endl;
        return false;
    } catch (...) {
        std::cerr << "[storage] cannot initialize UNLOGGED forks for "
                  << dbname << "/" << tablename << std::endl;
        return false;
    }
}

std::filesystem::path StorageEngine::fsmPath(const std::string& dbname,
                                               const std::string& tablename) const {
    return relationDir(dbname, tablename) / (tablename + ".fsm");
}

std::filesystem::path StorageEngine::vmPath(const std::string& dbname,
                                             const std::string& tablename) const {
    return relationDir(dbname, tablename) / (tablename + ".vm");
}

// Relation forks and access-method files share the table-name prefix, while
// catalog sidecars (for example .stc and .params) remain in dbPath(). Keep
// this predicate in one place so migration, snapshot filtering and DROP use
// identical boundaries and never confuse table "t" with table "t2".
static bool isRelationPhysicalFileName(const std::string& name,
                                        const std::string& tablename) {
    static constexpr std::string_view initSuffix = ".init";
    static constexpr std::string_view tdeSuffix = ".tde";
    static constexpr std::string_view extentMarkerSuffix =
        ".extent_pending";
    static constexpr std::string_view mapPublicationSuffix = ".map_publication";
    static constexpr std::string_view temporaryReceipt = ".map_publication.tmp.";
    const auto temporaryPosition = name.rfind(temporaryReceipt);
    if (temporaryPosition != std::string::npos) {
        const auto serial = name.substr(temporaryPosition + temporaryReceipt.size());
        const auto dot = serial.find('.');
        if (dot != std::string::npos && dot != 0 && dot + 1 < serial.size() &&
            serial.find_first_not_of("0123456789.") == std::string::npos &&
            serial.find('.', dot + 1) == std::string::npos)
            return isRelationPhysicalFileName(name.substr(0, temporaryPosition), tablename);
    }
    if (name.size() > mapPublicationSuffix.size() &&
        name.compare(name.size() - mapPublicationSuffix.size(), mapPublicationSuffix.size(),
                     mapPublicationSuffix) == 0) {
        return isRelationPhysicalFileName(
            name.substr(0, name.size() - mapPublicationSuffix.size()), tablename);
    }
    if (name.size() > initSuffix.size() &&
        name.compare(name.size() - initSuffix.size(), initSuffix.size(),
                     initSuffix) == 0) {
        return isRelationPhysicalFileName(
            name.substr(0, name.size() - initSuffix.size()), tablename);
    }
    if (name.size() > tdeSuffix.size() &&
        name.compare(name.size() - tdeSuffix.size(), tdeSuffix.size(),
                     tdeSuffix) == 0) {
        return isRelationPhysicalFileName(
            name.substr(0, name.size() - tdeSuffix.size()), tablename);
    }
    if (name.size() > extentMarkerSuffix.size() &&
        name.compare(name.size() - extentMarkerSuffix.size(),
                     extentMarkerSuffix.size(), extentMarkerSuffix) == 0) {
        return isRelationPhysicalFileName(
            name.substr(0, name.size() - extentMarkerSuffix.size()),
            tablename);
    }
    if (name == tablename + ".toast") return true;
    const std::array<std::string, 11> suffixes = {
        ".dt", ".fsm", ".vm", ".idx", ".hidx", ".bidx", ".fti",
        ".gin", ".gist", ".spgist", ".brin"};
    const auto hasSuffix = [&](const std::string& suffix) {
        return name.size() >= suffix.size() &&
               name.compare(name.size() - suffix.size(), suffix.size(),
                            suffix) == 0;
    };

    // Partitions have their own `#` component, and all supported relation
    // forks/access-method files may follow it.
    if (name.rfind(tablename + "#", 0) == 0) {
        for (const auto& suffix : suffixes) {
            if (hasSuffix(suffix)) return true;
        }
        return false;
    }

    // Column indexes use `<table>_<column>.<am>`; underscore alone does not
    // make a neighboring table's `.dt` heap part of this relation.
    if (name.rfind(tablename + "_", 0) == 0) {
        const std::array<std::string, 8> indexSuffixes = {
            ".idx", ".hidx", ".bidx", ".fti", ".gin", ".gist",
            ".spgist", ".brin"};
        const size_t prefixLength = tablename.size() + 1;
        for (const auto& suffix : indexSuffixes) {
            if (name.size() > prefixLength + suffix.size() &&
                hasSuffix(suffix)) {
                return true;
            }
        }
        return false;
    }

    // Main relation forks and indexes use exact `<table>.<fork>` names. TOAST
    // heaps/indexes are the only multi-component dotted storage names.
    for (const auto& suffix : suffixes) {
        if (name == tablename + suffix ||
            name == tablename + ".toast" + suffix) return true;
    }
    const std::string compositeIndexPrefix = tablename + ".idx_";
    return name == tablename + ".toastmeta" ||
           (name.rfind(compositeIndexPrefix, 0) == 0 &&
            name.size() > compositeIndexPrefix.size());
}

// Until relation files are keyed by OID, a table's main heap name can also
// be interpreted as another table's partition/fork/index file. Reject names
// whose canonical heap filenames overlap those legacy ownership prefixes.
static bool relationHeapNamesOverlap(const std::string& first,
                                     const std::string& second) {
    return isRelationPhysicalFileName(first + ".dt", second) ||
           isRelationPhysicalFileName(second + ".dt", first);
}

static bool relationNamespaceContainsPhysicalFiles(
    const std::filesystem::path& relationDirectory,
    const std::string& tablename, std::error_code& error) {
    std::filesystem::directory_iterator it(relationDirectory, error), end;
    if (error == std::errc::no_such_file_or_directory) {
        error.clear();
        return false;
    }
    if (error) return false;
    for (; it != end; it.increment(error)) {
        if (error) return false;
        if (isRelationPhysicalFileName(
                it->path().filename().string(), tablename)) {
            return true;
        }
    }
    return false;
}

static bool isDefinitionBearingSpecializedIndexFileName(
    const std::string& name, const std::string& tablename) {
    if (name.rfind(tablename + "_", 0) != 0) return false;
    const std::array<std::string_view, 5> suffixes = {
        ".fti", ".gin", ".gist", ".spgist", ".brin"};
    return std::any_of(
        suffixes.begin(), suffixes.end(), [&](std::string_view suffix) {
            return name.size() > suffix.size() &&
                name.compare(name.size() - suffix.size(), suffix.size(),
                             suffix) == 0;
        });
}

