PageAllocator* StorageEngine::getToastPageAllocator(const std::string& dbname,
                                                    const std::string& tablename) const {
    requireDatabaseTransactionOwnership(dbname);
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::string key = dbname + ":" + tablename;
    auto it = toastPageAllocators_.find(key);
    if (it != toastPageAllocators_.end()) {
        if (it->second && it->second->isOpen() &&
            it->second->bufferPool()->refersToCurrentFiles())
            return it->second.get();
        toastPageAllocators_.erase(it);
    }
    const auto path = toastDataPath(dbname, tablename);
    std::error_code dataError;
    if (!std::filesystem::is_regular_file(path, dataError) || dataError)
        return nullptr;
    auto pa = acquireSharedHeap(dbname, path,
                                              /*rowSize=*/0, // variable-length rows
                                              /*pageSize=*/8192,
                                              /*formatVersion=*/DATA_FILE_FORMAT_VERSION);
    if (!pa) return nullptr;
    PageAllocator* ptr = pa.get();
    toastPageAllocators_[key] = std::move(pa);
    return ptr;
}

BPTree* StorageEngine::getToastIndex(const std::string& dbname,
                                     const std::string& tablename) const {
    return loadBtreeIndex(toastIndexes_, dbname + ":" + tablename,
                          toastIndexPath(dbname, tablename), false);
}

void StorageEngine::closeAllToast() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    toastPageAllocators_.clear();
    toastIndexes_.clear();
}

uint64_t StorageEngine::allocToastId(const std::string& dbname, const std::string& tablename) {
    const auto invalidCounter = []() -> uint64_t {
        toastIdReservation.clear();
        return 0;
    };
    auto metaPath = toastMetaPath(dbname, tablename);
    ToastCounterFileLock counterLock(metaPath);
    if (!counterLock.ok()) return invalidCounter();

    uint64_t nextId = 1;
    bool canonicalCounter = false;
    std::error_code ec;
    const bool exists = std::filesystem::exists(metaPath, ec);
    // Only the owner of a new TOAST generation may initialize its counter.
    // Restarting an existing relation at ID 1 can collide with live chunks;
    // failed-write cleanup would then delete the old value's chunks as well.
    if (ec || !exists) return invalidCounter();
    if (exists) {
        const uintmax_t fileSize = std::filesystem::file_size(metaPath, ec);
        if (ec || (fileSize != TOAST_COUNTER_LEGACY_SIZE &&
                   fileSize != TOAST_COUNTER_SIZE)) {
            return invalidCounter();
        }
        std::ifstream ifs(metaPath, std::ios::binary);
        if (!ifs) return invalidCounter();
        std::string bytes(static_cast<size_t>(fileSize), '\0');
        if (!ifs.read(bytes.data(), static_cast<std::streamsize>(bytes.size())) ||
            ifs.peek() != std::char_traits<char>::eof()) {
            return invalidCounter();
        }
        if (bytes.size() == TOAST_COUNTER_LEGACY_SIZE) {
            std::memcpy(&nextId, bytes.data(), sizeof(nextId));
        } else {
            uint32_t magic = 0;
            uint32_t version = 0;
            uint64_t storedChecksum = 0;
            std::memcpy(&magic, bytes.data(), sizeof(magic));
            std::memcpy(&version, bytes.data() + sizeof(magic), sizeof(version));
            std::memcpy(&nextId, bytes.data() + sizeof(magic) + sizeof(version),
                        sizeof(nextId));
            std::memcpy(&storedChecksum, bytes.data() + TOAST_COUNTER_PAYLOAD_SIZE,
                        sizeof(storedChecksum));
            if (magic != TOAST_COUNTER_MAGIC || version != TOAST_COUNTER_VERSION ||
                storedChecksum != toastCounterChecksum(bytes.data(),
                                                       TOAST_COUNTER_PAYLOAD_SIZE)) {
                return invalidCounter();
            }
            canonicalCounter = true;
        }
    }
    if (nextId == 0) return invalidCounter();

    // Always reread and validate the actual counter under the existing
    // cross-process lock, even on a hit. A cache cannot hide corruption,
    // legacy-format replacement, another allocator or a changed file.
    uint64_t allocated = 0;
    if (canonicalCounter && toastIdReservation.take(metaPath, nextId, allocated))
        return allocated;
    // UINT64_MAX is the exhausted durable floor, but an already confirmed
    // final reservation may still contain IDs strictly below that floor.
    if (nextId == std::numeric_limits<uint64_t>::max()) return invalidCounter();

    toastIdReservation.clear();
    allocated = nextId;
    const auto count = std::min(TOAST_ID_RESERVATION_SIZE,
        std::numeric_limits<uint64_t>::max() - nextId);
    const uint64_t limit = nextId + count;
    if (!persistToastCounter(metaPath, limit)) return invalidCounter();
    // Publish a reservation only after both syncs succeed. On failure after
    // rename, the next attempt burns the unconfirmed range from its new floor.
    toastIdReservation.remember(metaPath, allocated + 1, limit);
    return allocated;
}

static std::string toastIndexKey(uint64_t toastId, uint32_t seq) {
    return "T" + std::to_string(toastId) + ":" + std::to_string(seq);
}

bool StorageEngine::writeToast(const std::string& dbname, const std::string& tablename,
                               uint64_t toastId, const std::string& data) {
    if (toastId == 0) return false;
    PageAllocator* pa = getToastPageAllocator(dbname, tablename);
    BPTree* idx = getToastIndex(dbname, tablename);
    if (!pa || !idx) return false;

    uint8_t flags = 0;
    const std::string storedData = compressToastPayload(data, flags);
    const uint64_t originalSize = static_cast<uint64_t>(data.size());
    size_t offset = 0;
    uint32_t seq = 0;
    const size_t chunkSize = TOAST_CHUNK_SIZE;
    while (offset < storedData.size()) {
        size_t len = std::min(chunkSize, storedData.size() - offset);
        std::string row;
        row.reserve(TOAST_CHUNK_HEADER_SIZE + len);
        row.append(reinterpret_cast<const char*>(&toastId), sizeof(toastId));
        row.append(reinterpret_cast<const char*>(&seq), sizeof(seq));
        row.push_back(static_cast<char>(flags));
        row.append(reinterpret_cast<const char*>(&originalSize), sizeof(originalSize));
        row.append(storedData.data() + offset, len);

        bool inserted = false;
        uint32_t numPages = pa->numPages();
        uint16_t slotId = 0;
        for (uint32_t pid = (numPages == 0 ? 0 : 1); pid < numPages && !inserted; ++pid) {
            if (!lockManager_.pageLockExclusive(dbname, tablename + ".toast", pid)) return false;
            char* buf = pa->fetchPage(pid);
            if (!buf) {
                lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
                return false;
            }
            PageWrapper page(buf, pa->pageSize(), DATA_FILE_FORMAT_VERSION);
            if (page.canFit(row.size())) {
                if (page.insert(row.data(), row.size(), slotId)) {
                    pa->markDirty(pid);
                    int64_t rid = encodeRid(pid, slotId);
                    inserted = idx->insert(toastIndexKey(toastId, seq), rid);
                    if (!inserted) {
                        // The chunk is unreachable without its index entry.
                        // Remove it before trying another page so a failed
                        // index write cannot leak an orphan tuple.
                        page.remove(slotId);
                        pa->markDirty(pid);
                    }
                }
            }
            pa->unpinPage(pid);
            lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
        }
        if (!inserted) {
            uint32_t pid = pa->allocPage();
            if (pid == 0) return false;
            if (!lockManager_.pageLockExclusive(dbname, tablename + ".toast", pid)) return false;
            char* buf = pa->fetchPage(pid);
            if (!buf) {
                lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
                return false;
            }
            PageWrapper page(buf, pa->pageSize(), DATA_FILE_FORMAT_VERSION);
            if (page.insert(row.data(), row.size(), slotId)) {
                pa->markDirty(pid);
                int64_t rid = encodeRid(pid, slotId);
                inserted = idx->insert(toastIndexKey(toastId, seq), rid);
                if (!inserted) {
                    page.remove(slotId);
                    pa->markDirty(pid);
                }
            }
            pa->unpinPage(pid);
            lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
        }

        if (!inserted) return false;

        offset += len;
        ++seq;
    }
    return true;
}

bool StorageEngine::readToast(const std::string& dbname,
                              const std::string& tablename,
                              uint64_t toastId,
                              size_t maxSize,
                              std::string& data) {
    data.clear();
    if (toastId == 0 || maxSize == 0) return false;
    maxSize = std::min(
        maxSize, static_cast<size_t>(std::numeric_limits<int32_t>::max()));
    PageAllocator* pa = getToastPageAllocator(dbname, tablename);
    BPTree* idx = getToastIndex(dbname, tablename);
    if (!pa || !idx) return false;

    std::string result;
    uint8_t flags = 0;
    uint64_t originalSize = 0;
    size_t maxChunks = 0;
    size_t previousPayloadSize = 0;
    for (uint32_t seq = 0;; ++seq) {
        int64_t rid = -1;
        if (!idx->search(toastIndexKey(toastId, seq), rid)) {
            if (seq == 0) return false;
            break;
        }
        if (seq > 0 && previousPayloadSize != TOAST_CHUNK_SIZE) return false;
        uint32_t pid = 0;
        uint16_t slotId = 0;
        decodeRid(rid, pid, slotId);

        if (!lockManager_.pageLockShared(dbname, tablename + ".toast", pid))
            return false;
        char* buf = pa->fetchPage(pid);
        if (!buf) {
            lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
            return false;
        }
        PageWrapper page(buf, pa->pageSize(), DATA_FILE_FORMAT_VERSION);
        const char* row = nullptr;
        size_t rowLen = 0;
        if (!page.read(slotId, row, rowLen) || rowLen < TOAST_CHUNK_HEADER_SIZE) {
            pa->unpinPage(pid);
            lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
            return false;
        }
        uint64_t storedToastId = 0;
        uint32_t storedSeq = 0;
        uint8_t storedFlags = 0;
        uint64_t storedOriginalSize = 0;
        std::memcpy(&storedToastId, row, sizeof(storedToastId));
        std::memcpy(&storedSeq, row + sizeof(storedToastId), sizeof(storedSeq));
        std::memcpy(&storedFlags, row + sizeof(storedToastId) + sizeof(storedSeq), sizeof(storedFlags));
        std::memcpy(&storedOriginalSize,
                    row + sizeof(storedToastId) + sizeof(storedSeq) + sizeof(storedFlags),
                    sizeof(storedOriginalSize));
        if (storedToastId != toastId || storedSeq != seq) {
            pa->unpinPage(pid);
            lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
            return false;
        }
        if (seq == 0) {
            if (storedFlags != 0 && storedFlags != TOAST_FLAG_COMPRESSED) {
                pa->unpinPage(pid);
                lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
                return false;
            }
            flags = storedFlags;
            originalSize = storedOriginalSize;
            if (originalSize == 0 || originalSize > maxSize ||
                originalSize > std::numeric_limits<size_t>::max()) {
                pa->unpinPage(pid);
                lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
                return false;
            }
            maxChunks = static_cast<size_t>(originalSize / TOAST_CHUNK_SIZE) +
                        (originalSize % TOAST_CHUNK_SIZE != 0 ? 1 : 0);
        } else if (storedFlags != flags || storedOriginalSize != originalSize) {
            pa->unpinPage(pid);
            lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
            return false;
        }
        const size_t payloadSize = rowLen - TOAST_CHUNK_HEADER_SIZE;
        if (payloadSize == 0 || payloadSize > TOAST_CHUNK_SIZE ||
            seq >= maxChunks || payloadSize > originalSize - result.size()) {
            pa->unpinPage(pid);
            lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
            return false;
        }
        result.append(row + TOAST_CHUNK_HEADER_SIZE, payloadSize);
        previousPayloadSize = payloadSize;
        pa->unpinPage(pid);
        lockManager_.pageUnlock(dbname, tablename + ".toast", pid);

        if (flags == 0) {
            if (result.size() == originalSize) {
                int64_t unexpectedRid = -1;
                if (seq != std::numeric_limits<uint32_t>::max() &&
                    idx->search(toastIndexKey(toastId, seq + 1), unexpectedRid)) {
                    return false;
                }
                data = std::move(result);
                return true;
            }
            if (static_cast<size_t>(seq) + 1 >= maxChunks) return false;
        } else {
            // writeToast only chooses compression when it strictly shrinks
            // the value.  This also bounds memory while walking a corrupt
            // index that invents arbitrarily many chunk keys.
            if (result.size() >= originalSize) return false;
        }
    }
    if (flags != TOAST_FLAG_COMPRESSED || result.empty() ||
        originalSize > std::numeric_limits<uInt>::max() ||
        result.size() > std::numeric_limits<uInt>::max()) {
        return false;
    }

    std::string decompressed(static_cast<size_t>(originalSize), '\0');
    z_stream stream{};
    stream.next_in = reinterpret_cast<Bytef*>(result.data());
    stream.avail_in = static_cast<uInt>(result.size());
    stream.next_out = reinterpret_cast<Bytef*>(decompressed.data());
    stream.avail_out = static_cast<uInt>(decompressed.size());
    if (inflateInit(&stream) != Z_OK) return false;
    const int status = inflate(&stream, Z_FINISH);
    const bool valid = status == Z_STREAM_END && stream.avail_in == 0 &&
                       stream.total_in == result.size() &&
                       stream.total_out == originalSize;
    inflateEnd(&stream);
    if (!valid) return false;
    data = std::move(decompressed);
    return true;
}

std::string StorageEngine::readToast(const std::string& dbname,
                                     const std::string& tablename,
                                     uint64_t toastId) {
    std::string data;
    if (!readToast(dbname, tablename, toastId,
                   static_cast<size_t>(std::numeric_limits<int32_t>::max()),
                   data)) {
        return "";
    }
    return data;
}

void StorageEngine::deleteToast(const std::string& dbname, const std::string& tablename,
                                 uint64_t toastId) {
    PageAllocator* pa = getToastPageAllocator(dbname, tablename);
    BPTree* idx = getToastIndex(dbname, tablename);
    if (!pa || !idx) return;

    for (uint32_t seq = 0;; ++seq) {
        std::string key = toastIndexKey(toastId, seq);
        int64_t rid = -1;
        if (!idx->search(key, rid)) break;
        idx->removeMulti(key, rid);
        uint32_t pid = 0;
        uint16_t slotId = 0;
        decodeRid(rid, pid, slotId);
        if (!lockManager_.pageLockExclusive(dbname, tablename + ".toast", pid)) return;
        char* buf = pa->fetchPage(pid);
        if (buf) {
            PageWrapper page(buf, pa->pageSize(), DATA_FILE_FORMAT_VERSION);
            page.remove(slotId);
            pa->markDirty(pid);
        }
        pa->unpinPage(pid);
        lockManager_.pageUnlock(dbname, tablename + ".toast", pid);
    }
}

bool StorageEngine::parseToastMarker(const std::string& val, uint64_t& toastId) {
    const size_t prefixLen = strlen(TOAST_PREFIX);
    if (val.size() <= prefixLen) return false;
    if (val.compare(0, prefixLen, TOAST_PREFIX) != 0) return false;
    uint64_t parsed = 0;
    const char* begin = val.data() + prefixLen;
    const char* end = val.data() + val.size();
    const auto converted = std::from_chars(begin, end, parsed, 10);
    if (converted.ec != std::errc{} || converted.ptr != end || parsed == 0)
        return false;
    toastId = parsed;
    return true;
}

void StorageEngine::deleteRowToast(const std::string& dbname, const std::string& tablename,
                                    int64_t rid) {
    // Read the row and find all toast markers
    TableSchema tbl = getTableSchema(dbname, tablename);
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    std::string row;
    if (!readRowByRid(pa, rid, row, tbl)) return;
    deleteToastForRow(dbname, tablename, row);
}

void StorageEngine::deleteToastForRow(const std::string& dbname,
                                       const std::string& tablename,
                                       const std::string& rowBuffer) {
    const TableSchema tbl = getTableSchema(dbname, tablename);
    for (size_t i = 0; i < tbl.len; ++i) {
        if (!tbl.cols[i].isVariableLength) continue;
        const std::string val = extractColumnValue(rowBuffer, tbl, i);
        uint64_t toastId = 0;
        if (parseToastMarker(val, toastId)) {
            deleteToast(dbname, tablename, toastId);
        }
    }
}

void StorageEngine::deleteToastForRowExcept(const std::string& dbname,
                                             const std::string& tablename,
                                             const std::string& rowBuffer,
                                             const std::string& preservedRowBuffer) {
    const TableSchema tbl = getTableSchema(dbname, tablename);
    std::set<uint64_t> preservedIds;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (!tbl.cols[i].isVariableLength) continue;
        uint64_t toastId = 0;
        if (parseToastMarker(extractColumnValue(preservedRowBuffer, tbl, i), toastId)) {
            preservedIds.insert(toastId);
        }
    }
    for (size_t i = 0; i < tbl.len; ++i) {
        if (!tbl.cols[i].isVariableLength) continue;
        uint64_t toastId = 0;
        if (parseToastMarker(extractColumnValue(rowBuffer, tbl, i), toastId) &&
            !preservedIds.count(toastId)) {
            deleteToast(dbname, tablename, toastId);
        }
    }
}

bool StorageEngine::prepareToastValues(const std::string& dbname, const std::string& tablename,
                                       const TableSchema& tbl,
                                       std::map<std::string, std::string>& values) {
    size_t threshold = toastThreshold(tbl.formatVersion);
    std::vector<uint64_t> allocatedIds;
    const auto discardAllocated = [&]() {
        for (auto it = allocatedIds.rbegin(); it != allocatedIds.rend(); ++it) {
            deleteToast(dbname, tablename, *it);
        }
    };
    for (size_t i = 0; i < tbl.len; ++i) {
        const Column& col = tbl.cols[i];
        if (!col.isVariableLength) continue;
        auto it = values.find(col.dataName);
        if (it == values.end()) continue;
        uint64_t apparentToastId = 0;
        // A user value can legitimately look like an internal marker.  Store
        // it externally as data even when it is short, otherwise a later read
        // aliases another row's value (or an arbitrary missing toast ID).
        if (it->second.size() > threshold ||
            parseToastMarker(it->second, apparentToastId)) {
            uint64_t toastId = allocToastId(dbname, tablename);
            if (toastId == 0) {
                discardAllocated();
                return false;
            }
            allocatedIds.push_back(toastId);
            if (!writeToast(dbname, tablename, toastId, it->second)) {
                discardAllocated();
                return false;
            }
            it->second = std::string(TOAST_PREFIX) + std::to_string(toastId);
        }
    }
    return true;
}

std::string StorageEngine::resolveToastValues(const std::string& dbname,
                                              const std::string& tablename,
                                              const std::string& rowBuffer,
                                              const TableSchema& tbl) {
    return resolveToastValues(dbname, tablename, rowBuffer, tbl, nullptr);
}

std::string StorageEngine::resolveToastValues(const std::string& dbname,
                                              const std::string& tablename,
                                              const std::string& rowBuffer,
                                              const TableSchema& tbl,
                                              bool* ok) {
    if (ok) *ok = true;
    if (tbl.varColCount() == 0) return rowBuffer;

    // Never recursively interpret a literal such as "__TOAST__1" that was
    // itself retrieved from TOAST and placed in an already-resolved row.
    uint32_t ignoredOffset = 0;
    uint32_t ignoredLength = 0;
    if (resolvedToastEntry(rowBuffer, tbl, 0, &ignoredOffset, &ignoredLength))
        return rowBuffer;

    std::vector<std::string> values;
    values.reserve(tbl.varColCount());
    bool foundMarker = false;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (!tbl.cols[i].isVariableLength) continue;
        std::string val = extractColumnValueStatic(rowBuffer, tbl, i);
        uint64_t toastId = 0;
        if (parseToastMarker(val, toastId)) {
            std::string resolved;
            if (!readToast(dbname, tablename, toastId,
                           characterColumnByteLimit(tbl.cols[i]),
                           resolved)) {
                if (ok) *ok = false;
                return rowBuffer;
            }
            val = std::move(resolved);
            foundMarker = true;
        }
        values.push_back(std::move(val));
    }
    if (!foundMarker) return rowBuffer;

    const size_t fixedSize = tbl.fixedDataSize();
    const size_t varCount = values.size();
    if (fixedSize > rowBuffer.size() ||
        varCount > (std::numeric_limits<size_t>::max() - fixedSize) / 4) {
        if (ok) *ok = false;
        return rowBuffer;
    }
    const size_t legacyArraySize = varCount * 4;
    constexpr size_t resolvedHeaderSize = sizeof(uint32_t) * 2;
    if (varCount > (std::numeric_limits<size_t>::max() - fixedSize -
                    legacyArraySize - resolvedHeaderSize) / 8) {
        if (ok) *ok = false;
        return rowBuffer;
    }
    const size_t entriesSize = varCount * 8;
    const size_t dataStart = fixedSize + legacyArraySize +
                             resolvedHeaderSize + entriesSize;
    uint64_t totalSize = dataStart;
    for (const auto& value : values) totalSize += value.size();
    if (totalSize > std::numeric_limits<uint32_t>::max() ||
        totalSize > std::numeric_limits<size_t>::max()) {
        if (ok) *ok = false;
        return rowBuffer;
    }

    std::string result;
    result.reserve(static_cast<size_t>(totalSize));
    result.append(rowBuffer.data(), fixedSize);
    result.append(legacyArraySize, '\0');
    std::memcpy(result.data() + fixedSize, &RESOLVED_TOAST_SENTINEL,
                sizeof(RESOLVED_TOAST_SENTINEL));
    std::memcpy(result.data() + fixedSize + sizeof(RESOLVED_TOAST_SENTINEL),
                &RESOLVED_TOAST_SENTINEL, sizeof(RESOLVED_TOAST_SENTINEL));
    result.append(reinterpret_cast<const char*>(&RESOLVED_TOAST_MAGIC),
                  sizeof(RESOLVED_TOAST_MAGIC));
    const uint32_t storedCount = static_cast<uint32_t>(varCount);
    result.append(reinterpret_cast<const char*>(&storedCount), sizeof(storedCount));

    uint32_t valueOffset = static_cast<uint32_t>(dataStart);
    for (const auto& value : values) {
        const uint32_t valueLength = static_cast<uint32_t>(value.size());
        result.append(reinterpret_cast<const char*>(&valueOffset), sizeof(valueOffset));
        result.append(reinterpret_cast<const char*>(&valueLength), sizeof(valueLength));
        valueOffset += valueLength;
    }
    for (const auto& value : values) result.append(value);
    return result;
}

namespace {

struct ValidatedForeignKeyDefinition {
    std::vector<size_t> localColumnIndices;
    std::vector<size_t> referencedColumnIndices;
    std::vector<std::string> referencedColumnNames;
};

bool collectPrimaryKeyColumns(const TableSchema& table,
                              std::vector<size_t>& columns) {
    columns = table.pkColIndices;
    if (columns.empty()) {
        for (size_t columnIndex = 0; columnIndex < table.len; ++columnIndex) {
            if (table.cols[columnIndex].isPrimaryKey) {
                columns.push_back(columnIndex);
            }
        }
    }
    std::set<size_t> distinct;
    for (const size_t columnIndex : columns) {
        if (columnIndex >= table.len || !distinct.insert(columnIndex).second) {
            return false;
        }
    }
    return true;
}

bool sameColumnSet(std::vector<size_t> left, std::vector<size_t> right) {
    if (left.size() != right.size()) return false;
    std::sort(left.begin(), left.end());
    std::sort(right.begin(), right.end());
    return left == right;
}

bool foreignKeyColumnTypesCompatible(const Column& local,
                                     const Column& referenced) {
    if (local.isArray != referenced.isArray) return false;
    // A domain's declared identity/constraints remain on the column, but FK
    // equality resolves against its already-resolved physical base type.
    // Distinct domain names must not reject compatible base comparisons.
    if (!local.enumValues.empty() || !referenced.enumValues.empty()) {
        // Named enums are assignment-compatible only with the same enum
        // type.  The labels are not their identity: PostgreSQL treats two
        // separately declared enums as distinct even when their current
        // label lists happen to be identical.  Inline legacy ENUM columns
        // have no named identity and retain their historical label-based
        // compatibility.
        return local.dataType == referenced.dataType &&
               local.enumValues == referenced.enumValues;
    }

    const auto baseType = [](const Column& column) {
        std::string type = column.dataType;
        if (type.size() >= 2 &&
            type.compare(type.size() - 2, 2, "[]") == 0) {
            type.resize(type.size() - 2);
        }
        const std::string normalized =
            TypeRegistry::instance().normalizeTypeName(type);
        return normalized.empty() ? type : normalized;
    };
    const std::string localType = baseType(local);
    const std::string referencedType = baseType(referenced);
    if (localType == referencedType) return true;
    if (local.isArray) return false;

    const TypeEntry* localEntry =
        TypeRegistry::instance().findType(localType);
    const TypeEntry* referencedEntry =
        TypeRegistry::instance().findType(referencedType);
    if (!localEntry || !referencedEntry) return false;
    if (localEntry->category != referencedEntry->category) return false;
    return localEntry->category == TypeCategory::Numeric ||
           localEntry->category == TypeCategory::String ||
           localEntry->category == TypeCategory::Binary;
}

DBStatus validateForeignKeyDefinition(
    const TableSchema& localTable, const TableSchema& referencedTable,
    const std::vector<std::string>& localColumnNames,
    const std::vector<std::string>& requestedReferencedColumnNames,
    ValidatedForeignKeyDefinition& result, std::string* error = nullptr) {
    const auto reject = [&](const std::string& message) {
        if (error) *error = message;
        return DBStatus::INVALID_VALUE;
    };
    if (localColumnNames.empty() || localColumnNames.size() > MAX_COLUMNS) {
        return reject("foreign key requires at least one local column");
    }

    result = {};
    std::set<size_t> distinctLocalColumns;
    for (const auto& columnName : localColumnNames) {
        size_t columnIndex = localTable.len;
        for (size_t candidate = 0; candidate < localTable.len; ++candidate) {
            if (localTable.cols[candidate].dataName == columnName) {
                columnIndex = candidate;
                break;
            }
        }
        if (columnIndex >= localTable.len) {
            return reject("foreign key local column does not exist: " +
                          columnName);
        }
        if (!distinctLocalColumns.insert(columnIndex).second) {
            return reject("foreign key local column appears more than once: " +
                          columnName);
        }
        result.localColumnIndices.push_back(columnIndex);
    }

    std::vector<size_t> primaryColumns;
    if (!collectPrimaryKeyColumns(referencedTable, primaryColumns)) {
        return reject("referenced primary key metadata is invalid");
    }
    result.referencedColumnNames = requestedReferencedColumnNames;
    if (result.referencedColumnNames.empty()) {
        if (primaryColumns.empty() ||
            primaryColumns.size() != localColumnNames.size()) {
            return reject(
                "foreign key column count does not match referenced primary key");
        }
        for (const size_t columnIndex : primaryColumns) {
            result.referencedColumnNames.push_back(
                referencedTable.cols[columnIndex].dataName);
        }
    }
    if (result.referencedColumnNames.size() != localColumnNames.size()) {
        return reject(
            "foreign key column count does not match referenced key");
    }

    std::set<size_t> distinctReferencedColumns;
    for (const auto& columnName : result.referencedColumnNames) {
        size_t columnIndex = referencedTable.len;
        for (size_t candidate = 0; candidate < referencedTable.len;
             ++candidate) {
            if (referencedTable.cols[candidate].dataName == columnName) {
                columnIndex = candidate;
                break;
            }
        }
        if (columnIndex >= referencedTable.len) {
            return reject("foreign key referenced column does not exist: " +
                          columnName);
        }
        if (!distinctReferencedColumns.insert(columnIndex).second) {
            return reject(
                "foreign key referenced column appears more than once: " +
                columnName);
        }
        result.referencedColumnIndices.push_back(columnIndex);
    }

    bool referencedKeyIsUnique =
        !primaryColumns.empty() &&
        sameColumnSet(result.referencedColumnIndices, primaryColumns);
    if (!referencedKeyIsUnique &&
        result.referencedColumnIndices.size() == 1) {
        referencedKeyIsUnique = referencedTable
            .cols[result.referencedColumnIndices.front()]
            .isUnique;
    }
    for (const auto& uniqueColumns : referencedTable.uniqueConstraints) {
        for (const size_t columnIndex : uniqueColumns) {
            if (columnIndex >= referencedTable.len) {
                return reject("referenced unique-key metadata is invalid");
            }
        }
        if (sameColumnSet(result.referencedColumnIndices, uniqueColumns)) {
            referencedKeyIsUnique = true;
            break;
        }
    }
    if (!referencedKeyIsUnique) {
        return reject("foreign key target is not a primary or unique key");
    }

    for (size_t columnIndex = 0;
         columnIndex < result.localColumnIndices.size(); ++columnIndex) {
        if (!foreignKeyColumnTypesCompatible(
                localTable.cols[result.localColumnIndices[columnIndex]],
                referencedTable.cols[
                    result.referencedColumnIndices[columnIndex]])) {
            return reject("foreign key column types are incompatible");
        }
    }
    return DBStatus::OK;
}

}  // namespace

DBStatus StorageEngine::createTable(const std::string& dbname, const TableSchema& tbl, std::string* error) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) {
        if (error) *error = "database not found";
        return DBStatus::DATABASE_NOT_FOUND;
    }
    if (!validateTableSchemaIdentifiers(tbl, error)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    if (isSessionTempPhysicalName(tbl.tablename)) {
        Session* session = currentSession();
        const std::string expectedPrefix = session
            ? tempTablePrefix(*session, "")
            : std::string();
        if (!tbl.isTemporary || !session ||
            tbl.tablename.rfind(expectedPrefix, 0) != 0) {
            if (error) {
                *error = "the __tmp_<backend>_ namespace is reserved for session temporary relations";
            }
            return DBStatus::INVALID_ARGUMENT;
        }
    } else if (tbl.isTemporary) {
        if (error) *error = "temporary relations must use the session temporary namespace";
        return DBStatus::INVALID_ARGUMENT;
    }
    if (tableExists(dbname, tbl.tablename)) {
        if (error) *error = "table already exists";
        return DBStatus::TABLE_ALREADY_EXISTS;
    }

    // Wave 0: 通过 TypeRegistry 校验并补齐每列类型元数据
    TableSchema tblWithVersion = tbl;
    const DBStatus collationStatus = resolveTableCollations(
        *this, dbname, tblWithVersion, error);
    if (collationStatus != DBStatus::OK) return collationStatus;
    // pkColIndices is the authoritative representation when present.  The
    // embedded API historically permits callers to omit duplicate per-column
    // primary-key flags, but PRIMARY KEY must still imply NOT NULL before the
    // schema reaches disk.
    if (!tblWithVersion.pkColIndices.empty()) {
        for (const size_t columnIndex : tblWithVersion.pkColIndices) {
            tblWithVersion.cols[columnIndex].isNull = false;
        }
    } else {
        for (size_t columnIndex = 0; columnIndex < tblWithVersion.len;
             ++columnIndex) {
            if (tblWithVersion.cols[columnIndex].isPrimaryKey) {
                tblWithVersion.cols[columnIndex].isNull = false;
            }
        }
    }
    if (tblWithVersion.tablespace.empty()) tblWithVersion.tablespace = "pg_default";
    std::unique_ptr<TablespaceCatalogLock> tablespaceCatalogLock;
    if (tblWithVersion.tablespace != "pg_default") {
        const auto metadataDirectory =
            tablespaceMetadataDirectory(*this, dbname);
        std::error_code tablespaceError;
        if (!std::filesystem::is_directory(
                metadataDirectory, tablespaceError) || tablespaceError) {
            if (error) *error = "tablespace metadata is unavailable";
            return DBStatus::INVALID_VALUE;
        }
        tablespaceCatalogLock = std::make_unique<TablespaceCatalogLock>(
            tablespaceCatalogLockPath(*this, dbname), true);
        std::filesystem::path tablespaceRoot;
        if (!tablespaceCatalogLock->acquired() ||
            !resolveTablespaceRoot(
                *this, dbname, tblWithVersion.tablespace, tablespaceRoot)) {
            if (error) *error = "tablespace does not exist or is corrupt";
            return DBStatus::INVALID_VALUE;
        }
    }
    const auto prospectiveRelationDir =
        tblWithVersion.tablespace == "pg_default"
            ? dbPath(dbname)
            : tablespaceDir(dbname, tblWithVersion.tablespace) / dbname;
    std::string conflictingRelationName;
    for (const auto& existingName : getTableNames(dbname)) {
        if (relationHeapNamesOverlap(
                tblWithVersion.tablename, existingName) &&
            relationDir(dbname, existingName).lexically_normal() ==
                prospectiveRelationDir.lexically_normal()) {
            conflictingRelationName = existingName;
            break;
        }
    }
    if (!conflictingRelationName.empty()) {
        if (error) {
            *error = "relation name overlaps the name-based storage namespace of '" +
                     conflictingRelationName + "'";
        }
        return DBStatus::INVALID_ARGUMENT;
    }
    std::error_code relationNamespaceError;
    if (relationNamespaceContainsPhysicalFiles(
            prospectiveRelationDir, tblWithVersion.tablename,
            relationNamespaceError)) {
        if (error) {
            *error = "physical relation namespace is already occupied";
        }
        return DBStatus::INVALID_ARGUMENT;
    }
    if (relationNamespaceError) {
        if (error) *error = "could not inspect physical relation namespace";
        return DBStatus::IO_ERROR;
    }
    for (size_t i = 0; i < tblWithVersion.len; ++i) {
        std::string typeErr = TypeRegistry::instance().validateColumn(tblWithVersion.cols[i]);
        if (!typeErr.empty()) {
            if (error) *error = typeErr;
            return DBStatus::INVALID_ARGUMENT;
        }
    }

    // A malformed FK embedded in a CREATE TABLE schema used to be persisted
    // without any of the checks performed by ALTER TABLE ADD CONSTRAINT.  Do
    // all definition validation before creating the first relation file, and
    // materialize an omitted referenced-column list as the parent's PK.
    for (size_t foreignKeyIndex = 0;
         foreignKeyIndex < tblWithVersion.fkLen; ++foreignKeyIndex) {
        ForeignKey& foreignKey = tblWithVersion.fks[foreignKeyIndex];
        std::string normalizedDelete;
        std::string normalizedUpdate;
        if (!normalizeForeignKeyAction(
                foreignKey.onDelete, normalizedDelete) ||
            !normalizeForeignKeyAction(
                foreignKey.onUpdate, normalizedUpdate)) {
            if (error) *error = "unsupported foreign key referential action";
            return DBStatus::INVALID_VALUE;
        }
        foreignKey.onDelete = std::move(normalizedDelete);
        foreignKey.onUpdate = std::move(normalizedUpdate);
        if (foreignKey.refTable.empty()) {
            if (error) *error = "foreign key referenced table is empty";
            return DBStatus::INVALID_VALUE;
        }

        TableSchema storedReferencedTable;
        const TableSchema* referencedTable = nullptr;
        if (foreignKey.refTable == tblWithVersion.tablename) {
            referencedTable = &tblWithVersion;
        } else {
            if (!tableExists(dbname, foreignKey.refTable)) {
                if (error) {
                    *error = "foreign key referenced table does not exist: " +
                             foreignKey.refTable;
                }
                return DBStatus::TABLE_NOT_FOUND;
            }
            storedReferencedTable =
                getTableSchema(dbname, foreignKey.refTable);
            referencedTable = &storedReferencedTable;
        }

        ValidatedForeignKeyDefinition definition;
        const DBStatus validationStatus = validateForeignKeyDefinition(
            tblWithVersion, *referencedTable, foreignKey.colNames,
            foreignKey.refCols, definition, error);
        if (validationStatus != DBStatus::OK) return validationStatus;
        foreignKey.refCols = std::move(definition.referencedColumnNames);
    }

    if (tblWithVersion.formatVersion != DATA_FILE_FORMAT_VERSION) {
        if (error) *error = "unsupported table storage format; expected format version 2";
        return DBStatus::INVALID_ARGUMENT;
    }
    size_t pageSize = pageSizeForFormatVersion(tblWithVersion.formatVersion);

    // CREATE TABLE is a multi-relation operation: schema, heap forks, TOAST,
    // indexes, sequences and tlist.lst are created in stages.  Keep a narrow
    // rollback guard so a failed initializer cannot publish a half-created
    // relation or leave cache entries pointing at removed files.
    std::vector<std::string> priorTableNames;
    bool tableListMutationAttempted = false;
    auto cleanupFailedCreate = [&]() {
        const std::string key = dbname + "/" + tbl.tablename;
        pageAllocators_.erase(key);
        pkIndexCache_.erase(key);
        fsmCache_.erase(key);
        vmCache_.erase(key);
        const std::string secondaryPrefix = dbname + "/" + tbl.tablename + "/";
        for (auto it = secondaryIndexCache_.begin(); it != secondaryIndexCache_.end();) {
            if (it->first.rfind(secondaryPrefix, 0) == 0) it = secondaryIndexCache_.erase(it);
            else ++it;
        }
        const std::string hashPrefix = dbname + "." + tbl.tablename + ".";
        for (auto it = hashIndexCache_.begin(); it != hashIndexCache_.end();) {
            if (it->first.rfind(hashPrefix, 0) == 0) it = hashIndexCache_.erase(it);
            else ++it;
        }
        for (auto it = bloomIndexCache_.begin(); it != bloomIndexCache_.end();) {
            if (it->first.rfind(hashPrefix, 0) == 0) it = bloomIndexCache_.erase(it);
            else ++it;
        }
        toastPageAllocators_.erase(dbname + ":" + tbl.tablename);
        toastIndexes_.erase(dbname + ":" + tbl.tablename);

        std::error_code ec;
        const auto relationRoot = tblWithVersion.tablespace == "pg_default"
            ? dbPath(dbname)
            : tablespaceDir(dbname, tblWithVersion.tablespace) / dbname;
        for (const auto& path : {
                 schemaPath(dbname, tbl.tablename), paramsPath(dbname, tbl.tablename),
                 dataPath(dbname, tbl.tablename), indexPath(dbname, tbl.tablename),
                 secondaryIndexMetaPath(dbname, tbl.tablename),
                 hashIndexMetaPath(dbname, tbl.tablename),
                 namedIndexMetaPath(*this, dbname, tbl.tablename),
                 truncateStatePath(*this, dbname, tbl.tablename),
                 specializedIndexDirtyPath(
                     *this, dbname, tbl.tablename),
                 fsmPath(dbname, tbl.tablename), vmPath(dbname, tbl.tablename),
                 toastMetaPath(dbname, tbl.tablename),
                 toastDataPath(dbname, tbl.tablename), toastIndexPath(dbname, tbl.tablename)}) {
            std::filesystem::remove(path, ec);
            ec.clear();
        }
        removeSeq(dbname, tbl.tablename);
        std::filesystem::remove_all(toastDir(dbname, tbl.tablename), ec);
        ec.clear();

        for (const auto& leaf : partitionLeaves(tblWithVersion)) {
            const std::string suffix = "#" + leaf.partition +
                (leaf.subPartition.empty()
                     ? "" : "#" + leaf.subPartition);
            std::filesystem::remove(
                relationRoot / (tbl.tablename + suffix + ".dt"), ec);
            ec.clear();
        }
        if (std::filesystem::exists(relationRoot, ec) && !ec) {
            for (const auto& entry :
                 std::filesystem::directory_iterator(relationRoot)) {
                if (isRelationPhysicalFileName(
                        entry.path().filename().string(), tbl.tablename)) {
                    std::filesystem::remove_all(entry.path(), ec);
                    ec.clear();
                }
            }
        }

        if (tableListMutationAttempted) {
            if (!writeRelationListAtomically(tableListPath(dbname), priorTableNames)) {
                std::cerr << "[catalog] failed to restore table list after "
                          << "CREATE TABLE rollback: " << dbname << std::endl;
            }
            invalidateCatalogTableList(dbname);
        }
    };
    auto failCreate = [&](const std::string& message, DBStatus status = DBStatus::IO_ERROR) {
        cleanupFailedCreate();
        if (error) *error = message;
        return status;
    };
    bool createCompleted = false;
    std::unique_ptr<int, std::function<void(int*)>> cleanupGuard(
        reinterpret_cast<int*>(1),
        [&](int*) {
            if (!createCompleted) cleanupFailedCreate();
        });

    {
        std::error_code staleStateError;
        std::filesystem::remove(
            truncateStatePath(*this, dbname, tbl.tablename),
            staleStateError);
        if (staleStateError) {
            return failCreate("could not remove stale truncate state");
        }
        staleStateError.clear();
        std::filesystem::remove(
            specializedIndexDirtyPath(*this, dbname, tbl.tablename),
            staleStateError);
        if (staleStateError) {
            return failCreate(
                "could not remove stale specialized-index state");
        }
    }

    {
        const auto identityStatus = allocatePhysicalRelationId(*this, dbname, tblWithVersion.physicalRelationId);
        if (identityStatus != DBStatus::OK)
            return failCreate("could not allocate durable physical relation identity", identityStatus);
        if (!tblWithVersion.isUnlogged) {
            WALManager* wal = getWAL(dbname);
            const auto payload = heap_wal_identity::event(
                tblWithVersion.physicalRelationId, tblWithVersion.tablename);
            const uint64_t xid = transactionContext().inTransaction
                ? transactionContext().currentTxnId : 0;
            const Lsn birthLsn = wal ? wal->XLogInsert(
                RM_SMGR_ID, XLOG_SMGR_RELATION_CREATE, xid, payload) : INVALID_LSN;
            if (!wal || birthLsn == INVALID_LSN || !wal->XLogFlush(birthLsn))
                return failCreate("could not persist relation creation identity");
        }
        std::ofstream out(schemaPath(dbname, tblWithVersion.tablename), std::ios::binary);
        if (!out) return failCreate("could not create table schema");
        writeSchema(out, tblWithVersion);
        out.flush();
        const bool schemaWritten = out.good();
        out.close();
        if (!schemaWritten || !out) return failCreate("could not write table schema");
        invalidateCatalogSchema(dbname, tblWithVersion.tablename);
    }
    {
        std::error_code ec;
        std::filesystem::create_directories(relationDir(dbname, tblWithVersion.tablename), ec);
        if (ec) return failCreate("could not create tablespace relation directory");
    }

    auto initializeHeap = [&](const std::filesystem::path& path, size_t rowSize) {
        if (rowSize > std::numeric_limits<uint32_t>::max()) return DBStatus::INVALID_VALUE;
        auto pa = std::make_unique<PageAllocator>(path.string(), rowSize, pageSize,
                                                   tblWithVersion.formatVersion);
        const bool initialized = pa->open() && pa->flush();
        // close() cannot report its flush error. Check while the initializer
        // still owns the file, then close before the outer failure cleanup.
        pa->close();
        return initialized ? DBStatus::OK : DBStatus::IO_ERROR;
    };
    const auto initializeIndex = [&](const std::filesystem::path& path) {
        BPTree index(path.string());
        const bool initialized = index.open() && index.flush();
        index.close();
        return initialized;
    };
    // Initialize page-based data file(s) via PageAllocator
    if (tblWithVersion.partitionType != TableSchema::PartitionType::None) {
        for (const auto& leaf : partitionLeaves(tblWithVersion)) {
            const auto path = leaf.subPartition.empty()
                ? partitionDataPath(
                      dbname, tblWithVersion.tablename, leaf.partition)
                : partitionDataPath(
                      dbname, tblWithVersion.tablename, leaf.partition,
                      leaf.subPartition);
            const auto heapStatus = initializeHeap(path, tblWithVersion.rowSize());
            if (heapStatus != DBStatus::OK) {
                return failCreate("could not initialize table partition", heapStatus);
            }
        }
    } else {
        const auto heapStatus = initializeHeap(dataPath(dbname, tblWithVersion.tablename), tblWithVersion.rowSize());
        if (heapStatus != DBStatus::OK) {
            return failCreate("could not initialize table heap", heapStatus);
        }
    }
    priorTableNames = getTableNames(dbname);
    tableListMutationAttempted = true;
    auto updatedTableNames = priorTableNames;
    if (std::find(updatedTableNames.begin(), updatedTableNames.end(),
                  tbl.tablename) == updatedTableNames.end()) {
        updatedTableNames.push_back(tbl.tablename);
    }
    if (!writeRelationListAtomically(tableListPath(dbname), updatedTableNames)) {
        invalidateCatalogTableList(dbname);
        return failCreate("could not update table list");
    }
    invalidateCatalogTableList(dbname);
    invalidateCatalogSchema(dbname, tbl.tablename);
    // Create TOAST relation and index if table has variable-length columns
    bool hasVarLen = false;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].isVariableLength) { hasVarLen = true; break; }
    }
    if (hasVarLen) {
        // TOAST has its own fixed page/format declaration, not the user's
        // row format. Its owners must close before failed-CREATE cleanup.
        bool toastInitialized = false;
        {
            PageAllocator toast(toastDataPath(dbname, tblWithVersion.tablename).string(),
                /*rowSize=*/0, /*pageSize=*/8192, /*formatVersion=*/DATA_FILE_FORMAT_VERSION);
            toastInitialized = toast.open() && toast.flush();
            toast.close();
        }
        if (!toastInitialized) return failCreate("could not initialize TOAST heap");
        if (!initializeIndex(toastIndexPath(dbname, tblWithVersion.tablename)))
            return failCreate("could not initialize TOAST index");
        // Initialize the next-ID state without consuming ID 1 merely for
        // creating the relation.
        if (!persistToastCounter(toastMetaPath(dbname, tblWithVersion.tablename), 1))
            return failCreate("could not initialize TOAST metadata");
    }

    // Create B+ tree index if table has primary key
    if (tbl.hasPrimaryKey()) {
        if (!initializeIndex(indexPath(dbname, tbl.tablename)))
            return failCreate("could not initialize primary key index");
    }
    // Initialize auto-increment sequences
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].isAutoIncrement) {
            writeNextSeq(dbname, tbl.tablename, tbl.cols[i].dataName, 1);
        }
    }
    // Auto-create secondary index for UNIQUE columns
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].isUnique) {
            const auto indexStatus = createIndex(dbname, tbl.tablename, tbl.cols[i].dataName);
            if (indexStatus != DBStatus::OK) {
                return failCreate("could not initialize unique index", indexStatus);
            }
        }
    }
    if (tblWithVersion.isUnlogged &&
        !ensureUnloggedInitForks(dbname, tblWithVersion.tablename)) {
        return failCreate("could not initialize UNLOGGED init forks");
    }
    createCompleted = true;
    dbms::resetRuntimeTableStats(dbname, tblWithVersion.tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::createTable(const std::string& dbname,
                                     const std::string& tablename,
                                     const TableSchema& tbl,
                                     std::string* error) {
    TableSchema t = tbl;
    t.tablename = tablename;
    return createTable(dbname, t, error);
}

static std::filesystem::path grantChainPath(
    const std::filesystem::path& dbPath);

static bool removeTableStatistics(const std::filesystem::path& path,
                                  const std::string& tablename,
                                  std::string* original = nullptr,
                                  bool* existed = nullptr) {
    std::error_code error;
    if (!std::filesystem::exists(path, error)) {
        if (original) original->clear();
        if (existed) *existed = false;
        return !error;
    }
    std::ifstream input(path, std::ios::binary);
    if (!input) return false;
    std::string before((std::istreambuf_iterator<char>(input)),
                       std::istreambuf_iterator<char>());
    if (input.bad()) return false;
    if (original) *original = before;
    if (existed) *existed = true;

    std::istringstream lines(before);
    std::ostringstream retained;
    std::string line;
    while (std::getline(lines, line)) {
        if (line.empty()) continue;
        std::istringstream fields(line);
        std::string storedTable;
        fields >> storedTable;
        if (storedTable != tablename) retained << line << '\n';
    }
    return index_file::writeAtomically(path, retained.str());
}

