    if (colIdx >= tbl.len) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    tbl.cols[colIdx].defaultValue.clear();
    tbl.cols[colIdx].defaultOrigin = tbl.cols[colIdx].domainName.empty()
        ? Column::DefaultOrigin::LegacyFrozen : Column::DefaultOrigin::Domain;
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableIdentity(const std::string& dbname,
                                            const std::string& tablename,
                                            const std::string& colName,
                                            const std::string& action,
                                            char identityKind,
                                            bool ifExists) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t colIdx = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colName) {
            colIdx = i;
            break;
        }
    }
    if (colIdx >= tbl.len) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    Column& column = tbl.cols[colIdx];
    bool initializeSequence = false;
    if (action == "drop") {
        if (column.identityKind == 0) {
            lockManager_.unlock(tablename);
            return ifExists ? DBStatus::OK : DBStatus::INVALID_VALUE;
        }
        column.identityKind = 0;
        column.isAutoIncrement = false;
    } else if (action == "set") {
        if (column.identityKind == 0 ||
            (identityKind != 'a' && identityKind != 'd')) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        column.identityKind = identityKind;
    } else if (action == "add") {
        const std::string type = toLowerUtf8(column.dataType);
        const bool integerType = type == "smallint" || type == "int" ||
                                 type == "bigint";
        // Refuse to manufacture NOT NULL over existing rows. Callers can make
        // the column NOT NULL explicitly, after the normal validation scan.
        if (column.identityKind != 0 || column.isAutoIncrement ||
            !integerType || column.isArray || !column.domainName.empty() ||
            !column.defaultValue.empty() || !column.generatedExpr.empty() ||
            column.isNull || (identityKind != 'a' && identityKind != 'd')) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        column.identityKind = identityKind;
        column.isAutoIncrement = true;
        initializeSequence = true;
    } else {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_ARGUMENT;
    }

    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (initializeSequence) writeNextSeq(dbname, tablename, colName, 1);
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableSetLogged(const std::string& dbname,
                                             const std::string& tablename,
                                             bool logged) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    TableSchema tbl = getTableSchema(dbname, tablename);
    if (tbl.isUnlogged == !logged) {
        lockManager_.unlock(tablename);
        return DBStatus::OK;
    }
    if (!logged) {
        std::vector<Publication> publications;
        std::string publicationError;
        if (!PublicationCatalog::instance().list(
                dbname, publications, publicationError)) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
        const bool published = std::any_of(
            publications.begin(), publications.end(),
            [&](const Publication& publication) {
                return publication.publishAllTables ||
                    std::find(publication.tables.begin(),
                              publication.tables.end(), tablename) !=
                        publication.tables.end();
            });
        if (published) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    }
    if (logged) {
        const auto relationRoot = relationDir(dbname, tablename);
        std::error_code error;
        for (std::filesystem::directory_iterator iterator(
                 relationRoot,
                 std::filesystem::directory_options::skip_permission_denied,
                 error), end;
             !error && iterator != end; iterator.increment(error)) {
            const std::string filename =
                iterator->path().filename().string();
            if (filename.size() <= 5 ||
                filename.compare(filename.size() - 5, 5, ".init") != 0 ||
                !isRelationPhysicalFileName(filename, tablename)) {
                continue;
            }
            std::filesystem::remove(iterator->path(), error);
        }
        if (error || !syncDirectoryDurably(relationRoot)) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
    }
    const TableSchema original = tbl;
    tbl.isUnlogged = !logged;
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        // Removing an init fork is harmless while the schema still says
        // UNLOGGED: startup can regenerate the empty baseline. Do not publish
        // a catalog/storage persistence mismatch on a failed schema write.
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (!logged && !ensureUnloggedInitForks(dbname, tablename)) {
        (void)writeSchemaFile(dbname, tablename, original);
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableSetCluster(const std::string& dbname,
                                              const std::string& tablename,
                                              const std::string& indexName) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!indexName.empty() && !getNamedIndex(dbname, tablename, indexName)) {
        return DBStatus::INVALID_VALUE;
    }
    return updateStorageParams(dbname, tablename, {{"cluster_on", indexName}});
}

DBStatus StorageEngine::alterTableSetReplicaIdentity(
    const std::string& dbname, const std::string& tablename,
    const std::string& identity, const std::string& indexName) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    const std::string mode = toLowerUtf8(trim(identity));
    char relreplident = 'd';
    if (mode == "full") relreplident = 'f';
    else if (mode == "nothing") relreplident = 'n';
    else if (mode == "index") {
        if (indexName.empty() || !getNamedIndex(dbname, tablename, indexName)) {
            return DBStatus::INVALID_VALUE;
        }
        relreplident = 'i';
    } else if (mode != "default") {
        return DBStatus::INVALID_ARGUMENT;
    }

    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    try {
        auto& catalog = catalogService().get(dbname);
        const auto qualifiedName = CatalogService::logicalName(tablename);
        const std::string schemaName = qualifiedName.schema.empty()
            ? "public" : qualifiedName.schema;
        const auto relation = catalog.resolveRelationSnapshot(
            qualifiedName.name, {schemaName});
        if (relation) {
            auto updated = *relation;
            updated.relreplident = relreplident;
            if (!catalog.updateClass(relation->oid, updated)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            if (!catalog.persistAll()) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
        }
    } catch (...) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    lockManager_.unlock(tablename);

    std::map<std::string, std::string> changes{{"replica_identity", mode}};
    if (mode == "index") changes["replica_identity_index"] = indexName;
    else changes["replica_identity_index"] = "";
    return updateStorageParams(dbname, tablename, changes);
}

DBStatus StorageEngine::alterTableSetConstraintDeferrability(
    const std::string& dbname, const std::string& tablename,
    const std::string& constraintName, bool deferrable, bool initiallyDeferred) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t match = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].checkConstraintName == constraintName) {
            match = i;
            break;
        }
    }
    auto additionalMatch = std::find_if(
        tbl.additionalCheckConstraints.begin(),
        tbl.additionalCheckConstraints.end(),
        [&](const CheckConstraint& check) {
            return check.name == constraintName;
        });
    if (match == tbl.len &&
        additionalMatch == tbl.additionalCheckConstraints.end()) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    if (match != tbl.len) {
        tbl.cols[match].deferrable = deferrable;
        tbl.cols[match].initiallyDeferred = initiallyDeferred;
    } else {
        additionalMatch->deferrable = deferrable;
        additionalMatch->initiallyDeferred = initiallyDeferred;
    }
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableSetNotNull(const std::string& dbname,
                                              const std::string& tablename,
                                              const std::string& colName) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t colIdx = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colName) { colIdx = i; break; }
    }
    if (colIdx >= tbl.len) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Reject if any existing row has SQL NULL in this column.  The logical
    // value alone is insufficient here because an empty string is a valid,
    // non-NULL value; consult the tuple's physical null bitmap by RID.
    bool hasNull = false;
    if (!forEachRow(
            dbname, tablename,
            [&](uint32_t pageId, uint16_t slotId, const char*, size_t) {
                if (hasNull) return;
                hasNull = dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, encodeRid(pageId, slotId), colIdx);
            })) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (hasNull) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    tbl.cols[colIdx].isNull = false;
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableDropNotNull(const std::string& dbname,
                                               const std::string& tablename,
                                               const std::string& colName) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t colIdx = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colName) { colIdx = i; break; }
    }
    if (colIdx >= tbl.len) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    if (tbl.cols[colIdx].isPrimaryKey ||
        std::find(tbl.pkColIndices.begin(), tbl.pkColIndices.end(), colIdx) !=
            tbl.pkColIndices.end()) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    tbl.cols[colIdx].isNull = true;
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableAddCheckConstraint(const std::string& dbname,
                                                        const std::string& tablename,
                                                        const std::string& name,
                                                        const std::string& expr) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!validStoredIdentifier(name, MAX_TABLE_NAME_LEN) || expr.empty() ||
        expr.size() > std::numeric_limits<uint16_t>::max()) {
        return DBStatus::INVALID_VALUE;
    }
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    // Find the first column referenced in the expression
    size_t targetCol = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (expr.find(tbl.cols[i].dataName) != std::string::npos) {
            targetCol = i;
            break;
        }
    }
    if (targetCol >= tbl.len) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    // Ensure constraint name is unique
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].checkConstraintName == name) {
            lockManager_.unlock(tablename);
            return DBStatus::TABLE_ALREADY_EXISTS;
        }
    }
    for (const auto& check : tbl.additionalCheckConstraints) {
        if (check.name == name) {
            lockManager_.unlock(tablename);
            return DBStatus::TABLE_ALREADY_EXISTS;
        }
    }

    // CHECK constraints apply to the whole relation immediately. Validate
    // every visible row before publishing the expression so ALTER cannot
    // leave pre-existing rows that violate the newly advertised invariant.
    const auto typeHints = buildTypeHints(tbl);
    DBStatus validationStatus = DBStatus::OK;
    const bool scanOk = forEachRow(
        dbname, tablename,
        [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
            if (validationStatus != DBStatus::OK) return;
            const int64_t rid = encodeRid(pageId, slotId);
            const std::string row(data, len);
            std::map<std::string, std::string> rowValues;
            for (size_t columnIndex = 0;
                 columnIndex < tbl.len; ++columnIndex) {
                if (tbl.cols[columnIndex].isNull &&
                    dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, columnIndex)) {
                    rowValues[tbl.cols[columnIndex].dataName] = "";
                } else {
                    rowValues[tbl.cols[columnIndex].dataName] =
                        extractColumnValue(
                            row, tbl, columnIndex, dbname);
                }
            }
            std::string evaluationError;
            if (!dbms::ExprHelper::evalCheck(
                    expr, rowValues, typeHints, &evaluationError, dbname,
                    "", this)) {
                // Distinguish a valid predicate that rejects an existing row
                // from a malformed or otherwise unevaluable expression,
                // just as the INSERT/UPDATE CHECK paths do.
                validationStatus = evaluationError.empty()
                    ? DBStatus::CHECK_VIOLATION : DBStatus::INVALID_VALUE;
            }
        });
    if (!scanOk) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (validationStatus != DBStatus::OK) {
        lockManager_.unlock(tablename);
        return validationStatus;
    }

    if (tbl.cols[targetCol].checkExpr.empty()) {
        tbl.cols[targetCol].checkExpr = expr;
        tbl.cols[targetCol].checkConstraintName = name;
        tbl.cols[targetCol].deferrable = false;
        tbl.cols[targetCol].initiallyDeferred = false;
    } else {
        if (tbl.additionalCheckConstraints.size() >=
            static_cast<size_t>(MAX_ADDITIONAL_CHECK_CONSTRAINTS)) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        CheckConstraint check;
        check.name = name;
        check.expression = expr;
        tbl.additionalCheckConstraints.push_back(std::move(check));
    }
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableAddUniqueConstraint(const std::string& dbname,
                                                         const std::string& tablename,
                                                         const std::string& name,
                                                         const std::vector<std::string>& colNames) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!validStoredIdentifier(name, MAX_TABLE_NAME_LEN)) return DBStatus::INVALID_VALUE;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    if (colNames.empty()) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    std::vector<size_t> colIndices;
    std::set<size_t> distinctColumns;
    for (const auto& cname : colNames) {
        bool found = false;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == cname) {
                if (!distinctColumns.insert(i).second) {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
                colIndices.push_back(i);
                found = true;
                break;
            }
        }
        if (!found) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    }
    // Check for duplicate constraint name
    for (const auto& n : tbl.uniqueConstraintNames) {
        if (n == name) {
            lockManager_.unlock(tablename);
            return DBStatus::TABLE_ALREADY_EXISTS;
        }
    }

    // Adding a constraint validates the rows that already exist. Publishing
    // metadata without this scan leaves a table that advertises uniqueness
    // while retaining duplicate keys from before the ALTER statement.
    const bool needsCollationScan =
        constraintNeedsCollationScan(tbl, colIndices);
    std::set<std::vector<std::string>> seenBinaryKeys;
    std::vector<std::vector<std::string>> seenCollatedKeys;
    bool duplicate = false;
    const bool scanOk = forEachRow(
        dbname, tablename,
        [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
            if (duplicate) return;
            const std::string row(data, len);
            const int64_t rid = encodeRid(pageId, slotId);
            std::vector<std::string> key;
            key.reserve(colIndices.size());
            for (const size_t columnIndex : colIndices) {
                if (tbl.cols[columnIndex].isNull &&
                    dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, columnIndex)) {
                    return;  // UNIQUE treats NULL keys as distinct.
                }
                key.push_back(extractColumnValue(
                    row, tbl, columnIndex, dbname));
            }
            if (needsCollationScan) {
                duplicate = std::any_of(
                    seenCollatedKeys.begin(), seenCollatedKeys.end(),
                    [&](const std::vector<std::string>& existingKey) {
                        return constraintKeyValuesEqual(
                            tbl, colIndices, existingKey, key);
                    });
                if (!duplicate) {
                    seenCollatedKeys.push_back(std::move(key));
                }
            } else {
                for (size_t valueIndex = 0;
                     valueIndex < colIndices.size(); ++valueIndex) {
                    key[valueIndex] = canonicalColumnKeyValue(
                        tbl.cols[colIndices[valueIndex]], key[valueIndex]);
                }
                duplicate =
                    !seenBinaryKeys.insert(std::move(key)).second;
            }
        });
    if (!scanOk) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (duplicate) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    tbl.uniqueConstraints.push_back(colIndices);
    tbl.uniqueConstraintNames.push_back(name);
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableAddPrimaryKey(const std::string& dbname,
                                                const std::string& tablename,
                                                const std::string& name,
                                                const std::vector<std::string>& colNames) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!validStoredIdentifier(name, MAX_TABLE_NAME_LEN)) return DBStatus::INVALID_VALUE;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);

    TableSchema tbl = getTableSchema(dbname, tablename);

    // A table may have at most one primary key.
    bool hasPk = !tbl.pkColIndices.empty();
    for (size_t i = 0; i < tbl.len && !hasPk; ++i)
        if (tbl.cols[i].isPrimaryKey) hasPk = true;
    if (hasPk) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;  // multiple primary keys not allowed
    }

    // Resolve the named columns to indices.
    std::vector<size_t> colIndices;
    std::set<size_t> distinctColumns;
    for (const auto& cname : colNames) {
        bool found = false;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == cname) {
                if (!distinctColumns.insert(i).second) {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
                colIndices.push_back(i);
                found = true;
                break;
            }
        }
        if (!found) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    }
    if (colIndices.empty()) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Validate existing data: every PK column must be non-NULL and the tuple of
    // PK columns must be unique across all rows.
    const bool needsCollationScan =
        constraintNeedsCollationScan(tbl, colIndices);
    std::set<std::vector<std::string>> seenBinaryKeys;
    std::vector<std::vector<std::string>> seenCollatedKeys;
    bool violation = false;
    if (!forEachRow(dbname, tablename,
               [&](uint32_t pageId, uint16_t slotId,
                   const char* data, size_t len) {
                   if (violation) return;
                   const int64_t rid = encodeRid(pageId, slotId);
                   const std::string row(data, len);
                   std::vector<std::string> key;
                   key.reserve(colIndices.size());
                   for (size_t ci : colIndices) {
                       if (tbl.cols[ci].isNull &&
                           dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, ci)) {
                           violation = true;
                           return;
                       }
                       key.push_back(extractColumnValue(
                           row, tbl, ci, dbname));
                   }
                   if (needsCollationScan) {
                       violation = std::any_of(
                           seenCollatedKeys.begin(),
                           seenCollatedKeys.end(),
                           [&](const std::vector<std::string>& existingKey) {
                               return constraintKeyValuesEqual(
                                   tbl, colIndices, existingKey, key);
                           });
                       if (!violation) {
                           seenCollatedKeys.push_back(std::move(key));
                       }
                   } else {
                       for (size_t valueIndex = 0;
                            valueIndex < colIndices.size(); ++valueIndex) {
                           key[valueIndex] = canonicalColumnKeyValue(
                               tbl.cols[colIndices[valueIndex]],
                               key[valueIndex]);
                       }
                       violation =
                           !seenBinaryKeys.insert(std::move(key)).second;
                   }
               })) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (violation) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;  // existing data violates the primary key
    }

    // Record the primary key: composite indices plus per-column flags.
    tbl.pkColIndices = colIndices;
    for (size_t ci : colIndices) {
        tbl.cols[ci].isPrimaryKey = true;
        tbl.cols[ci].isNull = false;  // PK columns are implicitly NOT NULL
    }
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }

    // Build the physical PK index and populate it from existing rows so that
    // insert-time uniqueness enforcement (which consults this index) works.
    {
        std::string pkKey = dbname + "/" + tablename;
        auto cit = pkIndexCache_.find(pkKey);
        if (cit != pkIndexCache_.end()) pkIndexCache_.erase(cit);
        std::filesystem::remove(indexPath(dbname, tablename));
        BPTree* pkIdx = loadBtreeIndex(pkIndexCache_, pkKey,
                                      indexPath(dbname, tablename), true);
        if (!pkIdx) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
        if (!forEachRow(dbname, tablename,
                       [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
                           std::string row(data, len);
                           std::string pkVal = extractPKValue(row, tbl);
                           if (!pkVal.empty()) pkIdx->insert(pkVal, encodeRid(pageId, slotId));
                       })) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
    }
    DBStatus metadataStatus = updateStorageParams(
        dbname, tablename,
        {{PRIMARY_KEY_CONSTRAINT_NAME_PARAM, name}});
    if (metadataStatus != DBStatus::OK) {
        lockManager_.unlock(tablename);
        return metadataStatus;
    }
    invalidateCatalogSchema(dbname, tablename);
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}


DBStatus StorageEngine::alterTableAddFKConstraint(const std::string& dbname,
                                                     const std::string& tablename,
                                                     const std::string& name,
                                                     const std::vector<std::string>& localCols,
                                                     const std::string& refTable,
                                                     const std::vector<std::string>& refCols,
                                                     const std::string& onDelete,
                                                     const std::string& onUpdate) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    std::string normalizedDelete;
    std::string normalizedUpdate;
    if (!normalizeForeignKeyAction(onDelete, normalizedDelete) ||
        !normalizeForeignKeyAction(onUpdate, normalizedUpdate)) {
        return DBStatus::INVALID_VALUE;
    }
    if (!validStoredIdentifier(name, MAX_TABLE_NAME_LEN) ||
        !validStoredRelationName(refTable)) return DBStatus::INVALID_VALUE;
    if (localCols.empty() ||
        (!refCols.empty() && localCols.size() != refCols.size()) ||
        localCols.size() > MAX_COLUMNS) {
        return DBStatus::INVALID_VALUE;
    }
    for (const auto& columnName : localCols) {
        if (!validStoredIdentifier(columnName, MAX_COL_NAME_LEN)) {
            return DBStatus::INVALID_VALUE;
        }
    }
    for (const auto& columnName : refCols) {
        if (!validStoredIdentifier(columnName, MAX_COL_NAME_LEN)) {
            return DBStatus::INVALID_VALUE;
        }
    }
    if (!tableExists(dbname, refTable)) {
        // FK references a table in the same database
        if (!std::filesystem::exists(schemaPath(dbname, refTable))) {
            return DBStatus::TABLE_NOT_FOUND;
        }
    }

    // The definition scan must see stable child and parent relations. Acquire
    // both metadata locks in a canonical order to avoid cross-table DDL
    // deadlocks; self-references acquire the relation only once.
    std::vector<std::string> relationNames = {tablename};
    if (refTable != tablename) relationNames.push_back(refTable);
    std::sort(relationNames.begin(), relationNames.end());
    std::vector<std::string> lockedRelations;
    for (const auto& relationName : relationNames) {
        if (!lockManager_.lockMetadata(relationName)) {
            for (auto it = lockedRelations.rbegin();
                 it != lockedRelations.rend(); ++it) {
                lockManager_.unlock(*it);
            }
            return DBStatus::LOCK_CONFLICT;
        }
        lockedRelations.push_back(relationName);
    }
    const auto finish = [&](DBStatus status) {
        for (auto it = lockedRelations.rbegin();
             it != lockedRelations.rend(); ++it) {
            lockManager_.unlock(*it);
        }
        return status;
    };

    if (!tableExists(dbname, tablename) ||
        !tableExists(dbname, refTable)) {
        return finish(DBStatus::TABLE_NOT_FOUND);
    }

    TableSchema tbl = getTableSchema(dbname, tablename);
    TableSchema referencedTable = getTableSchema(dbname, refTable);
    if (tbl.fkLen >= MAX_COLUMNS) {
        return finish(DBStatus::INVALID_VALUE);
    }

    // Check for duplicate constraint name
    for (size_t i = 0; i < tbl.fkLen; ++i) {
        if (tbl.fks[i].name == name) {
            return finish(DBStatus::TABLE_ALREADY_EXISTS);
        }
    }

    ValidatedForeignKeyDefinition definition;
    const DBStatus validationStatus = validateForeignKeyDefinition(
        tbl, referencedTable, localCols, refCols, definition);
    if (validationStatus != DBStatus::OK) {
        return finish(validationStatus);
    }
    const auto& localColumnIndices = definition.localColumnIndices;
    const auto& referencedColumnIndices =
        definition.referencedColumnIndices;

    std::set<std::vector<std::string>> referencedKeys;
    const bool parentScanOk = forEachRow(
        dbname, refTable,
        [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
            const int64_t rid = encodeRid(pageId, slotId);
            const std::string row(data, len);
            std::vector<std::string> key;
            key.reserve(referencedColumnIndices.size());
            for (const size_t columnIndex : referencedColumnIndices) {
                if (referencedTable.cols[columnIndex].isNull &&
                    dbms::detail::storedRowColumnIsNull(*this, dbname, refTable, referencedTable, rid, columnIndex)) {
                    return;
                }
                key.push_back(canonicalColumnKeyValue(
                    referencedTable.cols[columnIndex],
                    extractColumnValue(
                        row, referencedTable, columnIndex, dbname)));
            }
            referencedKeys.insert(std::move(key));
        });
    if (!parentScanOk) return finish(DBStatus::IO_ERROR);

    bool orphanedRow = false;
    const bool childScanOk = forEachRow(
        dbname, tablename,
        [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
            if (orphanedRow) return;
            const int64_t rid = encodeRid(pageId, slotId);
            const std::string row(data, len);
            std::vector<std::string> key;
            key.reserve(localColumnIndices.size());
            for (size_t valueIndex = 0;
                 valueIndex < localColumnIndices.size(); ++valueIndex) {
                const size_t localColumnIndex =
                    localColumnIndices[valueIndex];
                if (tbl.cols[localColumnIndex].isNull &&
                    dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, localColumnIndex)) {
                    return;  // MATCH SIMPLE: any NULL suppresses the check.
                }
                key.push_back(canonicalColumnKeyValue(
                    referencedTable.cols[referencedColumnIndices[valueIndex]],
                    extractColumnValue(
                        row, tbl, localColumnIndex, dbname)));
            }
            orphanedRow = referencedKeys.count(key) == 0;
        });
    if (!childScanOk) return finish(DBStatus::IO_ERROR);
    if (orphanedRow) return finish(DBStatus::INVALID_VALUE);

    ForeignKey fk;
    fk.name = name;
    fk.colNames = localCols;
    fk.refCols = definition.referencedColumnNames;
    fk.refTable = refTable;
    fk.onDelete = std::move(normalizedDelete);
    fk.onUpdate = std::move(normalizedUpdate);
    tbl.appendFK(fk);
    if (!writeSchemaFile(dbname, tablename, tbl)) {
        return finish(DBStatus::IO_ERROR);
    }
    return finish(DBStatus::OK);
}

DBStatus StorageEngine::alterTableDropConstraint(const std::string& dbname,
                                                  const std::string& tablename,
                                                  const std::string& name) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);

    TableSchema tbl = getTableSchema(dbname, tablename);
    bool found = false;
    bool droppedPrimaryKey = false;

    // Search CHECK constraints
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].checkConstraintName == name) {
            tbl.cols[i].checkExpr.clear();
            tbl.cols[i].checkConstraintName.clear();
            tbl.cols[i].deferrable = false;
            tbl.cols[i].initiallyDeferred = false;
            found = true;
            break;
        }
    }
    if (!found) {
        const auto check = std::find_if(
            tbl.additionalCheckConstraints.begin(),
            tbl.additionalCheckConstraints.end(),
            [&](const CheckConstraint& candidate) {
                return candidate.name == name;
            });
        if (check != tbl.additionalCheckConstraints.end()) {
            tbl.additionalCheckConstraints.erase(check);
            found = true;
        }
    }

    // Search UNIQUE constraints
    if (!found) {
        for (size_t i = 0; i < tbl.uniqueConstraintNames.size(); ++i) {
            if (tbl.uniqueConstraintNames[i] == name) {
                tbl.uniqueConstraints.erase(tbl.uniqueConstraints.begin() + i);
                tbl.uniqueConstraintNames.erase(tbl.uniqueConstraintNames.begin() + i);
                found = true;
                break;
            }
        }
    }

    // Search FK constraints
    if (!found) {
        for (size_t i = 0; i < tbl.fkLen; ++i) {
            if (tbl.fks[i].name == name) {
                // Shift left
                for (size_t j = i; j + 1 < tbl.fkLen; ++j) {
                    tbl.fks[j] = tbl.fks[j + 1];
                }
                tbl.fkLen--;
                found = true;
                break;
            }
        }
    }

    // Primary keys must be addressed by their actual constraint name.  Older
    // schemas written before the name metadata was introduced use the normal
    // implicit name as a safe compatibility fallback; an arbitrary unknown
    // name must never remove the key.
    const std::string effectivePrimaryKeyName =
        primaryKeyConstraintName(tbl);
    if (!found && tbl.hasPrimaryKey() && name == effectivePrimaryKeyName) {
        tbl.pkColIndices.clear();
        for (size_t i = 0; i < tbl.len; ++i) tbl.cols[i].isPrimaryKey = false;
        std::string pkKey = dbname + "/" + tablename;
        auto cit = pkIndexCache_.find(pkKey);
        if (cit != pkIndexCache_.end()) pkIndexCache_.erase(cit);
        std::filesystem::remove(indexPath(dbname, tablename));
        found = true;
        droppedPrimaryKey = true;
    }

    if (!found) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (droppedPrimaryKey) {
        DBStatus metadataStatus = updateStorageParams(
            dbname, tablename,
            {{PRIMARY_KEY_CONSTRAINT_NAME_PARAM, ""}});
        if (metadataStatus != DBStatus::OK) {
            lockManager_.unlock(tablename);
            return metadataStatus;
        }
    }
    invalidateCatalogSchema(dbname, tablename);
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::alterTableRenameConstraint(const std::string& dbname,
                                                    const std::string& tablename,
                                                    const std::string& oldName,
                                                    const std::string& newName) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!validStoredIdentifier(newName, MAX_TABLE_NAME_LEN)) return DBStatus::INVALID_VALUE;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    const std::string primaryKeyName = primaryKeyConstraintName(tbl);

    // Reject if the new name already names a constraint.
    auto nameInUse = [&](const std::string& n) {
        if (!primaryKeyName.empty() && primaryKeyName == n) return true;
        for (size_t i = 0; i < tbl.len; ++i)
            if (tbl.cols[i].checkConstraintName == n) return true;
        for (const auto& check : tbl.additionalCheckConstraints)
            if (check.name == n) return true;
        for (const auto& un : tbl.uniqueConstraintNames)
            if (un == n) return true;
        for (size_t i = 0; i < tbl.fkLen; ++i)
            if (tbl.fks[i].name == n) return true;
        return false;
    };
    if (oldName == newName) {
        const bool found = nameInUse(oldName);
        lockManager_.unlock(tablename);
        return found ? DBStatus::OK : DBStatus::NOT_FOUND;
    }
    if (nameInUse(newName)) {
        lockManager_.unlock(tablename);
        return DBStatus::TABLE_ALREADY_EXISTS;
    }

    bool found = false;
    for (size_t i = 0; i < tbl.len && !found; ++i) {
        if (tbl.cols[i].checkConstraintName == oldName) {
            tbl.cols[i].checkConstraintName = newName;
            found = true;
        }
    }
    for (auto& check : tbl.additionalCheckConstraints) {
        if (!found && check.name == oldName) {
            check.name = newName;
            found = true;
        }
    }
    for (size_t i = 0; i < tbl.uniqueConstraintNames.size() && !found; ++i) {
        if (tbl.uniqueConstraintNames[i] == oldName) {
            tbl.uniqueConstraintNames[i] = newName;
            found = true;
        }
    }
    for (size_t i = 0; i < tbl.fkLen && !found; ++i) {
        if (tbl.fks[i].name == oldName) {
            tbl.fks[i].name = newName;
            found = true;
        }
    }
    bool renamedPrimaryKey = false;
    if (!found && !primaryKeyName.empty() && oldName == primaryKeyName) {
        found = true;
        renamedPrimaryKey = true;
    }
    if (!found) {
        lockManager_.unlock(tablename);
        return DBStatus::NOT_FOUND;
    }

    if (!writeSchemaFile(dbname, tablename, tbl)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    std::map<std::string, std::string> metadataChanges;
    const std::string oldPrefix = "constraint." + oldName + ".";
    const std::string newPrefix = "constraint." + newName + ".";
    for (const auto& [key, value] : tbl.storageParams) {
        if (key.rfind(oldPrefix, 0) != 0) continue;
        metadataChanges[newPrefix + key.substr(oldPrefix.size())] = value;
        metadataChanges[key] = "";
    }
    if (renamedPrimaryKey) {
        metadataChanges[PRIMARY_KEY_CONSTRAINT_NAME_PARAM] = newName;
    }
    if (!metadataChanges.empty()) {
        DBStatus metadataStatus = updateStorageParams(
            dbname, tablename, metadataChanges);
        if (metadataStatus != DBStatus::OK) {
            lockManager_.unlock(tablename);
            return metadataStatus;
        }
    }
    invalidateCatalogSchema(dbname, tablename);
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

static bool renameTablespaceEntryNoReplace(
    const std::filesystem::path& source,
    const std::filesystem::path& destination,
    std::error_code& error) {
#ifdef SYS_renameat2
    constexpr unsigned kRenameNoReplace = 1;
    if (::syscall(SYS_renameat2, AT_FDCWD, source.c_str(), AT_FDCWD,
                  destination.c_str(), kRenameNoReplace) == 0) {
        error.clear();
        return true;
    }
    error = std::error_code(errno, std::generic_category());
#else
    (void)source;
    (void)destination;
    error = std::make_error_code(std::errc::operation_not_supported);
#endif
    return false;
}

DBStatus StorageEngine::alterTableTablespace(const std::string& dbname,
                                              const std::string& tablename,
                                              const std::string& tablespace) {
    return alterTableTablespace(dbname, tablename, tablespace, {});
}

DBStatus StorageEngine::alterTableTablespace(const std::string& dbname,
                                              const std::string& tablename,
                                              const std::string& tablespace,
                                              const std::function<void(
                                                  const std::filesystem::path&,
                                                  bool)>& beforeRenameForTesting) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    const std::string targetTablespace = tablespace.empty() ? "pg_default" : tablespace;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);

    TableSchema tbl = getTableSchema(dbname, tablename);
    const std::string oldTablespace = tbl.tablespace.empty() ? "pg_default" : tbl.tablespace;
    std::unique_ptr<TablespaceCatalogLock> tablespaceCatalogLock;
    if (oldTablespace != "pg_default" || targetTablespace != "pg_default") {
        const auto metadataDirectory =
            tablespaceMetadataDirectory(*this, dbname);
        std::error_code tablespaceError;
        if (!std::filesystem::is_directory(
                metadataDirectory, tablespaceError) || tablespaceError) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        tablespaceCatalogLock = std::make_unique<TablespaceCatalogLock>(
            tablespaceCatalogLockPath(*this, dbname), true);
        std::filesystem::path resolvedRoot;
        if (!tablespaceCatalogLock->acquired() ||
            (oldTablespace != "pg_default" &&
             !resolveTablespaceRoot(
                 *this, dbname, oldTablespace, resolvedRoot)) ||
            (targetTablespace != "pg_default" &&
             !resolveTablespaceRoot(
                 *this, dbname, targetTablespace, resolvedRoot))) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    }
    if (oldTablespace == targetTablespace) {
        lockManager_.unlock(tablename);
        return DBStatus::OK;
    }

    // The relation can have dirty pages in the shared buffer pool even when
    // the SQL statement itself is outside an explicit transaction. Flush the
    // owning allocator before moving its inode across tablespace directories.
    if (PageAllocator* pa = getPageAllocator(dbname, tablename)) {
        if (!pa->flush()) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
    }
    closeDatabaseCaches(dbname);
    const auto oldDir = relationDir(dbname, tablename);
    const auto newDir = targetTablespace == "pg_default"
        ? dbPath(dbname)
        : tablespaceDir(dbname, targetTablespace) / dbname;
    std::error_code ec;
    std::filesystem::create_directories(newDir, ec);
    if (ec) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    std::vector<std::pair<std::filesystem::path, std::filesystem::path>> moved;
    auto rollbackMove = [&]() {
        std::error_code rollbackEc;
        for (auto it = moved.rbegin(); it != moved.rend(); ++it) {
            if (!std::filesystem::exists(it->first)) continue;
            std::filesystem::rename(it->first, it->second, rollbackEc);
            if (rollbackEc) {
                rollbackEc.clear();
                std::filesystem::copy(it->first, it->second,
                    std::filesystem::copy_options::recursive |
                    std::filesystem::copy_options::overwrite_existing, rollbackEc);
                if (!rollbackEc) std::filesystem::remove_all(it->first, rollbackEc);
                rollbackEc.clear();
            }
        }
        (void)index_file::syncDirectory(oldDir);
        if (newDir != oldDir) (void)index_file::syncDirectory(newDir);
    };

    try {
        static std::atomic<uint64_t> moveSequence{0};
        if (std::filesystem::exists(oldDir)) {
            for (const auto& entry : std::filesystem::directory_iterator(oldDir)) {
                const auto name = entry.path().filename().string();
                if (!isRelationPhysicalFileName(name, tablename)) continue;
                if (entry.is_symlink()) {
                    rollbackMove();
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
                const bool sourceIsDirectory = entry.is_directory();
                const auto destination = newDir / name;
                std::error_code destinationEc;
                if (pathEntryExists(destination, destinationEc) ||
                    destinationEc) {
                    rollbackMove();
                    lockManager_.unlock(tablename);
                    return destinationEc ? DBStatus::IO_ERROR
                                         : DBStatus::INVALID_VALUE;
                }
                std::error_code moveEc;
                if (beforeRenameForTesting) {
                    beforeRenameForTesting(destination, false);
                }
                if (!renameTablespaceEntryNoReplace(
                        entry.path(), destination, moveEc)) {
                    if (moveEc != std::errc::cross_device_link) {
                        rollbackMove();
                        lockManager_.unlock(tablename);
                        return moveEc == std::errc::file_exists
                            ? DBStatus::INVALID_VALUE : DBStatus::IO_ERROR;
                    }
                    const auto staging = std::filesystem::path(
                        destination.string() + ".tablespace_move." +
                        std::to_string(::getpid()) + "." +
                        std::to_string(moveSequence.fetch_add(
                            1, std::memory_order_relaxed)));
                    std::error_code stagingEntryEc;
                    if (pathEntryExists(staging, stagingEntryEc) ||
                        stagingEntryEc) {
                        rollbackMove();
                        lockManager_.unlock(tablename);
                        return stagingEntryEc ? DBStatus::IO_ERROR
                                              : DBStatus::INVALID_VALUE;
                    }
                    moveEc.clear();
                    if (sourceIsDirectory) {
                        std::filesystem::copy(entry.path(), staging,
                            std::filesystem::copy_options::recursive, moveEc);
                    } else {
                        std::filesystem::copy_file(
                            entry.path(), staging,
                            std::filesystem::copy_options::none, moveEc);
                    }
                    const bool stagedDurably = !moveEc &&
                        (sourceIsDirectory
                             ? syncMovedTreeDurably(staging)
                             : syncRegularFileDurably(staging));
                    if (!stagedDurably) {
                        std::error_code ignored;
                        // If another actor occupied the path after the
                        // precheck, copy did not create it. Never erase that
                        // unrelated entry while handling the failed copy.
                        if (moveEc != std::errc::file_exists &&
                            moveEc != std::errc::is_a_directory) {
                            std::filesystem::remove_all(staging, ignored);
                        }
                        rollbackMove();
                        lockManager_.unlock(tablename);
                        return DBStatus::IO_ERROR;
                    }
                    moveEc.clear();
                    if (beforeRenameForTesting) {
                        beforeRenameForTesting(destination, true);
                    }
                    const bool published = renameTablespaceEntryNoReplace(
                        staging, destination, moveEc);
                    if (!published || !index_file::syncDirectory(newDir)) {
                        std::error_code ignored;
                        std::filesystem::remove_all(staging, ignored);
                        if (published) {
                            std::filesystem::remove_all(destination, ignored);
                        }
                        (void)index_file::syncDirectory(newDir);
                        rollbackMove();
                        lockManager_.unlock(tablename);
                        return DBStatus::IO_ERROR;
                    }
                    moved.emplace_back(destination, entry.path());
                    moveEc.clear();
                    std::filesystem::remove_all(entry.path(), moveEc);
                    if (moveEc || !index_file::syncDirectory(oldDir)) {
                        rollbackMove();
                        lockManager_.unlock(tablename);
                        return DBStatus::IO_ERROR;
                    }
                    continue;
                }
                moved.emplace_back(destination, entry.path());
                if (!index_file::syncDirectory(newDir) ||
                    (oldDir != newDir &&
                     !index_file::syncDirectory(oldDir))) {
                    rollbackMove();
                    lockManager_.unlock(tablename);
                    return DBStatus::IO_ERROR;
                }
            }
        }

        tbl.tablespace = targetTablespace;
        if (!writeSchemaFile(dbname, tablename, tbl)) {
            rollbackMove();
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
    } catch (...) {
        rollbackMove();
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

static std::filesystem::path commentsPath(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".comments";
}

// Version 2 comment records hex-encode every field.  The legacy line format
// stored the comment verbatim, so a newline in a perfectly valid SQL string
// could inject another metadata record.  Keep legacy records readable while
// ensuring all newly written records remain one unambiguous physical line.
static std::string encodeCommentField(const std::string& value) {
    static constexpr char hex[] = "0123456789abcdef";
    std::string encoded;
    encoded.reserve(value.size() * 2);
    for (unsigned char byte : value) {
        encoded.push_back(hex[byte >> 4]);
        encoded.push_back(hex[byte & 0x0f]);
    }
    return encoded;
}

static bool decodeCommentField(const std::string& encoded,
                               std::string& value) {
    if (encoded.size() % 2 != 0) return false;
    auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };

    value.clear();
    value.reserve(encoded.size() / 2);
    for (size_t i = 0; i < encoded.size(); i += 2) {
        const int high = nibble(encoded[i]);
        const int low = nibble(encoded[i + 1]);
        if (high < 0 || low < 0) {
            value.clear();
            return false;
        }
        value.push_back(static_cast<char>((high << 4) | low));
    }
    return true;
}

static std::optional<std::string> tableCommentFromRecord(
    const std::string& line, const std::string& tablename) {
    if (line.rfind("T2|", 0) == 0) {
        const size_t separator = line.find('|', 3);
        if (separator == std::string::npos ||
            line.find('|', separator + 1) != std::string::npos) {
            return std::nullopt;
        }
        std::string storedTable;
        std::string comment;
        if (!decodeCommentField(line.substr(3, separator - 3), storedTable) ||
            storedTable != tablename ||
            !decodeCommentField(line.substr(separator + 1), comment)) {
            return std::nullopt;
        }
        return comment;
    }

    const std::string legacyPrefix = "T|" + tablename + "|";
    if (line.rfind(legacyPrefix, 0) == 0) {
        return line.substr(legacyPrefix.size());
    }
    return std::nullopt;
}

static std::optional<std::string> columnCommentFromRecord(
    const std::string& line, const std::string& tablename,
    const std::string& colname) {
    if (line.rfind("C2|", 0) == 0) {
        const size_t tableEnd = line.find('|', 3);
        if (tableEnd == std::string::npos) return std::nullopt;
        const size_t columnEnd = line.find('|', tableEnd + 1);
        if (columnEnd == std::string::npos ||
            line.find('|', columnEnd + 1) != std::string::npos) {
            return std::nullopt;
        }
        std::string storedTable;
        std::string storedColumn;
        std::string comment;
        if (!decodeCommentField(line.substr(3, tableEnd - 3), storedTable) ||
            !decodeCommentField(
                line.substr(tableEnd + 1, columnEnd - tableEnd - 1),
                storedColumn) ||
            storedTable != tablename || storedColumn != colname ||
            !decodeCommentField(line.substr(columnEnd + 1), comment)) {
            return std::nullopt;
        }
        return comment;
    }

    const std::string legacyPrefix =
        "C|" + tablename + "|" + colname + "|";
    if (line.rfind(legacyPrefix, 0) == 0) {
        return line.substr(legacyPrefix.size());
    }
    return std::nullopt;
}

static DBStatus readCommentRecords(const std::filesystem::path& path,
                                   std::vector<std::string>& lines) {
    std::error_code error;
    const bool exists = std::filesystem::exists(path, error);
    if (error) return DBStatus::IO_ERROR;
    if (!exists) return DBStatus::OK;
    if (!std::filesystem::is_regular_file(path, error) || error) {
        return DBStatus::IO_ERROR;
    }

    std::ifstream in(path, std::ios::binary);
    if (!in) return DBStatus::IO_ERROR;
    std::string line;
    while (std::getline(in, line)) {
        if (!line.empty()) lines.push_back(line);
    }
    return in.bad() ? DBStatus::IO_ERROR : DBStatus::OK;
}

static DBStatus writeCommentRecords(const std::filesystem::path& path,
                                    const std::vector<std::string>& lines) {
    std::ostringstream contents;
    for (const auto& line : lines) {
        if (!line.empty()) contents << line << '\n';
    }
    return persistMetadata(path, contents.str());
}

// Decode a record for one known table.  Supplying the table name lets the
// legacy parser retain its historical prefix semantics even for unusual
// quoted identifiers containing the old delimiter.
static bool commentRecordForTable(const std::string& line,
                                  const std::string& tablename,
                                  bool& isColumn,
                                  std::string& column,
                                  std::string& comment) {
    if (line.rfind("T2|", 0) == 0) {
        const size_t tableEnd = line.find('|', 3);
        if (tableEnd == std::string::npos ||
            line.find('|', tableEnd + 1) != std::string::npos) {
            return false;
        }
        std::string storedTable;
        if (!decodeCommentField(line.substr(3, tableEnd - 3), storedTable) ||
            storedTable != tablename ||
            !decodeCommentField(line.substr(tableEnd + 1), comment)) {
            return false;
        }
        isColumn = false;
        column.clear();
        return true;
    }
    if (line.rfind("C2|", 0) == 0) {
        const size_t tableEnd = line.find('|', 3);
        if (tableEnd == std::string::npos) return false;
        const size_t columnEnd = line.find('|', tableEnd + 1);
        if (columnEnd == std::string::npos ||
            line.find('|', columnEnd + 1) != std::string::npos) {
            return false;
        }
        std::string storedTable;
        if (!decodeCommentField(line.substr(3, tableEnd - 3), storedTable) ||
            storedTable != tablename ||
            !decodeCommentField(
                line.substr(tableEnd + 1, columnEnd - tableEnd - 1),
                column) ||
            !decodeCommentField(line.substr(columnEnd + 1), comment)) {
            return false;
        }
        isColumn = true;
        return true;
    }

    const std::string legacyTablePrefix = "T|" + tablename + "|";
    if (line.rfind(legacyTablePrefix, 0) == 0) {
        isColumn = false;
        column.clear();
        comment = line.substr(legacyTablePrefix.size());
        return true;
    }
    const std::string legacyColumnPrefix = "C|" + tablename + "|";
    if (line.rfind(legacyColumnPrefix, 0) != 0) return false;
    const size_t columnEnd = line.find('|', legacyColumnPrefix.size());
    if (columnEnd == std::string::npos) return false;
    isColumn = true;
    column = line.substr(
        legacyColumnPrefix.size(), columnEnd - legacyColumnPrefix.size());
    comment = line.substr(columnEnd + 1);
    return true;
}

static bool rewriteCommentsForTable(
    std::vector<std::string>& lines, const std::string& oldName,
    const std::optional<std::string>& newName) {
    std::optional<std::string> tableComment;
    std::map<std::string, std::string> columnComments;
    std::vector<std::string> retained;
    retained.reserve(lines.size());
    bool changed = false;

    for (const auto& line : lines) {
        bool isColumn = false;
        std::string column;
        std::string comment;
        if (commentRecordForTable(
                line, oldName, isColumn, column, comment)) {
            changed = true;
            if (newName) {
                if (isColumn) columnComments.emplace(column, comment);
                else if (!tableComment) tableComment = comment;
            }
            continue;
        }
        // A relation name may be reusable even though an older buggy DROP
        // left metadata behind.  Remove destination records before moving
        // the live source so stale comments can never take precedence.
        if (newName && commentRecordForTable(
                           line, *newName, isColumn, column, comment)) {
            changed = true;
            continue;
        }
        retained.push_back(line);
    }

    if (newName) {
        if (tableComment) {
            retained.push_back("T2|" + encodeCommentField(*newName) + "|" +
                               encodeCommentField(*tableComment));
        }
        for (const auto& entry : columnComments) {
            retained.push_back("C2|" + encodeCommentField(*newName) + "|" +
                               encodeCommentField(entry.first) + "|" +
                               encodeCommentField(entry.second));
        }
    }
    lines = std::move(retained);
    return changed;
}

static bool rewriteCommentForColumn(std::vector<std::string>& lines,
                                    const std::string& tablename,
                                    const std::string& oldName,
                                    const std::string& newName) {
    std::optional<std::string> movedComment;
    std::vector<std::string> retained;
    retained.reserve(lines.size());
    bool changed = false;
    for (const auto& line : lines) {
        if (auto comment = columnCommentFromRecord(
                line, tablename, oldName)) {
            if (!movedComment) movedComment = std::move(*comment);
            changed = true;
            continue;
        }
        if (columnCommentFromRecord(line, tablename, newName)) {
            changed = true;
            continue;
        }
        retained.push_back(line);
    }
    if (movedComment) {
        retained.push_back("C2|" + encodeCommentField(tablename) + "|" +
                           encodeCommentField(newName) + "|" +
                           encodeCommentField(*movedComment));
    }
    lines = std::move(retained);
    return changed;
}

CommentRewriteGuard::CommentRewriteGuard(
    std::filesystem::path path, std::vector<std::string> original,
    std::vector<std::string> rewritten, bool changed)
    : path_(std::move(path)), original_(std::move(original)),
      rewritten_(std::move(rewritten)), changed_(changed) {}

DBStatus CommentRewriteGuard::publish() {
    if (!changed_) return DBStatus::OK;
    rollbackNeeded_ = true;
    return writeCommentRecords(path_, rewritten_);
}

void CommentRewriteGuard::commit() {
    rollbackNeeded_ = false;
}

CommentRewriteGuard::~CommentRewriteGuard() {
    if (rollbackNeeded_) {
        (void)writeCommentRecords(path_, original_);
    }
}

DBStatus StorageEngine::commentOnTable(const std::string& dbname,
                                        const std::string& tablename,
                                        const std::string& comment) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    const auto path = commentsPath(dbname);
    std::vector<std::string> lines;
    DBStatus status = readCommentRecords(path, lines);
    if (status != DBStatus::OK) return status;

    lines.erase(std::remove_if(lines.begin(), lines.end(),
                               [&](const std::string& line) {
                                   return tableCommentFromRecord(
                                              line, tablename).has_value();
                               }),
                lines.end());
    if (!comment.empty()) {
        lines.push_back("T2|" + encodeCommentField(tablename) + "|" +
                        encodeCommentField(comment));
    }
    return writeCommentRecords(path, lines);
}

DBStatus StorageEngine::commentOnColumn(const std::string& dbname,
                                         const std::string& tablename,
                                         const std::string& colname,
                                         const std::string& comment) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    const TableSchema table = getTableSchema(dbname, tablename);
    bool columnExists = false;
    for (size_t i = 0; i < table.len; ++i) {
        if (table.cols[i].dataName == colname) {
            columnExists = true;
            break;
        }
    }
    if (!columnExists) return DBStatus::INVALID_VALUE;

    const auto path = commentsPath(dbname);
    std::vector<std::string> lines;
    DBStatus status = readCommentRecords(path, lines);
    if (status != DBStatus::OK) return status;

    lines.erase(std::remove_if(lines.begin(), lines.end(),
                               [&](const std::string& line) {
                                   return columnCommentFromRecord(
                                              line, tablename,
                                              colname).has_value();
                               }),
                lines.end());
    if (!comment.empty()) {
        lines.push_back("C2|" + encodeCommentField(tablename) + "|" +
                        encodeCommentField(colname) + "|" +
                        encodeCommentField(comment));
    }
    return writeCommentRecords(path, lines);
}

std::string StorageEngine::getTableComment(const std::string& dbname,
                                            const std::string& tablename) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::vector<std::string> lines;
    if (readCommentRecords(commentsPath(dbname), lines) != DBStatus::OK) {
        return "";
    }
    for (const auto& line : lines) {
        auto stored = tableCommentFromRecord(line, tablename);
        if (stored) return *stored;
    }
    return "";
}

std::string StorageEngine::getColumnComment(const std::string& dbname,
                                             const std::string& tablename,
                                             const std::string& colname) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::vector<std::string> lines;
    if (readCommentRecords(commentsPath(dbname), lines) != DBStatus::OK) {
        return "";
    }
    for (const auto& line : lines) {
        auto stored = columnCommentFromRecord(line, tablename, colname);
        if (stored) return *stored;
    }
    return "";
}

std::vector<std::string> StorageEngine::getTableNames(const std::string& dbname) const {
    const auto status = ensureDatabaseTransactionOwnership(dbname);
    if (status != DBStatus::OK)
        throw DbError(sqlstateForDBStatus(status), "could not acquire database transaction ownership");
    {
        std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
        if (transactionContext().catalogSnapshot) {
            auto it = transactionContext().catalogSnapshot->tableNames.find(dbname);
            if (it != transactionContext().catalogSnapshot->tableNames.end()) {
                return it->second;
            }
        }
    }

    std::ifstream in(tableListPath(dbname), std::ios::binary);
    if (!in) return {};
    std::error_code listError;
    const auto listSize = std::filesystem::file_size(tableListPath(dbname), listError);
    if (listError || listSize > relation_name_codec::maxListBytes)
        throw DbError("XX001", "invalid relation list size");
    const std::string bytes{std::istreambuf_iterator<char>(in),
                            std::istreambuf_iterator<char>()};
    const auto decoded = relation_name_codec::decode(bytes);
    if (in.bad() || !decoded) throw DbError("XX001", "invalid relation list");
    auto names = *decoded;

    {
        std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
        if (transactionContext().catalogSnapshot) {
            transactionContext().catalogSnapshot->tableNames[dbname] = names;
        }
    }
    return names;
}

bool StorageEngine::cleanupStaleSessionTemporaryFiles() {
    for (const auto& dbname : getDatabaseNames()) {
        const auto names = getTableNames(dbname);
        bool tableListChanged = false;
        for (const auto& name : names) {
            if (isSessionTempPhysicalName(name)) {
                tableListChanged = true;
                break;
            }
        }

        // Remove entries even when the backend died before its schema file was
        // fully written.  This path runs before any client can observe the
        // database, so it is safe to rewrite the persistent relation list
        // without SQL metadata locks. Publish the complete fixed-record image
        // to keep an interrupted cleanup from truncating unrelated names.
        if (tableListChanged) {
            std::vector<std::string> retainedNames;
            for (const auto& name : names) {
                if (!isSessionTempPhysicalName(name)) {
                    retainedNames.push_back(name);
                }
            }
            if (!writeRelationListAtomically(tableListPath(dbname), retainedNames)) {
                std::cerr << "[catalog] startup could not durably clean "
                          << "temporary table names from " << dbname
                          << std::endl;
                return false;
            }
            invalidateCatalogTableList(dbname);
        }

        // A crash can leave relation forks behind even if the tlist append was
        // never reached.  All files belonging to the reserved physical temp
        // namespace share this prefix, including partition and TOAST files.
        try {
            for (const auto& entry : std::filesystem::directory_iterator(
                     dbPath(dbname), std::filesystem::directory_options::skip_permission_denied)) {
                const std::string filename = entry.path().filename().string();
                if (!isSessionTempPhysicalName(filename)) continue;
                // A fork suffix/index column can complete a name which is
                // not itself TEMP: __tmp_12_.stc or __tmp_34_tag.idx. Durable
                // relation ownership wins over a guessed backend prefix.
                const auto stem = entry.path().stem().string();
                const bool persistentOwned = std::any_of(names.begin(), names.end(),
                    [&](const std::string& name) {
                        return !isSessionTempPhysicalName(name) &&
                            (stem == name || isRelationPhysicalFileName(filename, name));
                    });
                if (persistentOwned) continue;
                std::error_code ec;
                std::filesystem::remove_all(entry.path(), ec);
                if (ec) {
                    std::cerr << "[catalog] startup could not remove stale "
                              << "temporary relation file " << entry.path()
                              << ": " << ec.message() << std::endl;
                    return false;
                }
            }
        } catch (const std::filesystem::filesystem_error&) {
            return false;
        }
        // Session namespaces and sequences use real catalog identities.
        // They must not survive restart after their temporary heaps vanish.
        try {
            auto& catalog = catalogService().get(dbname);
            const auto relations = catalog.listClasses();
            for (const auto& nameSpace : catalog.listNamespaces()) {
                const std::string prefix = "pg_temp_";
                if (nameSpace.nspname.rfind(prefix, 0) != 0) continue;
                const std::string suffix = nameSpace.nspname.substr(prefix.size());
                if (suffix.empty() || !std::all_of(suffix.begin(), suffix.end(),
                        [](unsigned char c) { return std::isdigit(c); })) continue;
                if (nameSpace.oid == 1213 && std::none_of(relations.begin(), relations.end(),
                        [&](const PgClassRow& relation) {
                            return relation.relnamespace == nameSpace.oid && relation.relpersistence == 't';
                        })) continue; // Legacy empty bootstrap placeholder.
                if (!dropSessionTemporaryObjects(dbname, std::stoull(suffix))) {
                    std::cerr << "[TEMP] restart namespace cleanup failed for "
                              << dbname << "/" << nameSpace.nspname << std::endl;
                    return false;
                }
            }
        } catch (const std::exception& error) {
            std::cerr << "[TEMP] restart catalog cleanup failed: " << error.what() << std::endl;
            return false;
        }
    }
    return true;
}

static std::mutex g_sequenceMutex;

bool StorageEngine::dropSessionTemporaryTable(const std::string& dbname,
        uint64_t sessionId, const std::string& logicalName) {
    if (!databaseExists(dbname)) return true;
    try {
        auto& catalog = catalogService().get(dbname);
        const auto nameSpace = catalog.getTempNamespace(sessionId);
        const Oid namespaceOid = nameSpace ? nameSpace->oid : INVALID_OID;
        const auto table = nameSpace ? catalog.getClassByName(logicalName, namespaceOid) : std::nullopt;
        const Oid tableOid = table ? table->oid : INVALID_OID;
        if (table && (table->relkind != 'r' || table->relpersistence != 't')) return false;
        std::vector<Oid> indexOids;
        if (tableOid != INVALID_OID) {
            for (const auto& dependency : catalog.findRefs(PgClassOid_Class, tableOid, -1)) {
                if (dependency.classid != PgClassOid_Class || dependency.objsubid != 0 ||
                    (dependency.deptype != 'a' && dependency.deptype != 'i')) continue;
                const auto sequence = catalog.getClass(dependency.objid);
                if (sequence && sequence->relkind == 'i' && dependency.refobjsubid == 0) {
                    if (sequence->relnamespace != namespaceOid || sequence->relpersistence != 't') return false;
                    indexOids.push_back(sequence->oid);
                    continue;
                }
                if (dependency.refobjsubid <= 0) continue;
                if (!sequence || sequence->relkind != 'S') continue;
                if (sequence->relnamespace != namespaceOid || sequence->relpersistence != 't') return false;
                const std::string storageName = sequenceStorageName(
                    "pg_temp_" + std::to_string(sessionId), sequence->relname);
                const auto status = dropSequence(dbname, storageName);
                if (status != DBStatus::OK && status != DBStatus::TABLE_NOT_FOUND) return false;
                if (!catalog.dropClass(dependency.objid)) return false;
            }
        }
        const auto status = dropTable(dbname, "__tmp_" + std::to_string(sessionId) + "_" + logicalName);
        if (status != DBStatus::OK && status != DBStatus::TABLE_NOT_FOUND) return false;
        // dropTable removes the physical named indexes. Remove their catalog
        // identities only after that succeeds, including preserved namespaces.
        for (const Oid indexOid : indexOids)
            if (!catalog.dropClass(indexOid)) return false;
        if (tableOid != INVALID_OID && !catalog.dropClass(tableOid)) return false;
        return catalog.persistAll();
    } catch (...) {
        return false;
    }
}

bool StorageEngine::dropSessionTemporaryObjects(const std::string& dbname, uint64_t sessionId) {
    return dropSessionTemporaryObjects(dbname, sessionId, false);
}

bool StorageEngine::dropSessionTemporaryObjects(const std::string& dbname,
        uint64_t sessionId, bool preserveNamespace) {
    if (!databaseExists(dbname)) return true;
    try {
        auto& catalog = catalogService().get(dbname);
        const auto nameSpace = catalog.getTempNamespace(sessionId);
        if (!nameSpace) return true;
        const Oid namespaceOid = nameSpace->oid;
        const auto relations = catalog.listClasses();
        // Retire tables first: their owned sequences are removed by the
        // table path. Independent sequences still need both file and catalog
        // retirement when DISCARD preserves this session's namespace.
        for (const auto& relation : relations) {
            if (relation.relnamespace == namespaceOid && relation.relkind == 'r' &&
                !dropSessionTemporaryTable(dbname, sessionId, relation.relname)) return false;
        }
        for (const auto& relation : relations) {
            if (relation.relnamespace == namespaceOid && relation.relkind == 'S' &&
                catalog.getClass(relation.oid)) {
                const auto status = dropSequence(dbname, sequenceStorageName(
                    "pg_temp_" + std::to_string(sessionId), relation.relname));
                if (status != DBStatus::OK && status != DBStatus::TABLE_NOT_FOUND) return false;
                if (!catalog.dropClass(relation.oid)) return false;
            }
        }
        return (preserveNamespace || catalog.dropTempNamespace(sessionId)) &&
               catalog.persistAll();
    } catch (...) {
        return false;
    }
}

static bool validSequenceName(const std::string& seqname) {
    if (seqname.rfind("seqv2..", 0) == 0) {
        if (seqname.size() <= 7 || seqname.size() > 249) return false;
        return std::all_of(seqname.begin() + 7, seqname.end(),
                           [](unsigned char ch) {
            return (ch >= 'A' && ch <= 'Z') ||
                   (ch >= 'a' && ch <= 'z') ||
                   (ch >= '0' && ch <= '9') ||
                   ch == '_' || ch == '-';
        });
    }
    const size_t separator = seqname.find('.');
    if (separator == std::string::npos) {
        return validStoredIdentifier(seqname, MAX_TABLE_NAME_LEN);
    }
    if (separator == 0 || separator + 1 >= seqname.size() ||
        seqname.find('.', separator + 1) != std::string::npos) {
        return false;
    }
    return validStoredIdentifier(
               seqname.substr(0, separator), MAX_TABLE_NAME_LEN) &&
           validStoredIdentifier(
               seqname.substr(separator + 1), MAX_TABLE_NAME_LEN);
}

static std::filesystem::path sequencePath(const std::string& dbname, const std::string& seqname) {
    if (seqname.rfind("seqv2..", 0) == 0) {
        // A distinct extension prevents collision with a table's legacy
        // auto-increment <tablename>.seq sidecar, even if a quoted table name
        // happens to equal the encoded sequence key.
        return std::filesystem::path(dbname) / (seqname + ".seqv2");
    }
    const std::string storageName = seqname.rfind("public.", 0) == 0
        ? seqname.substr(7) : seqname;
    return std::filesystem::path(dbname) / (storageName + ".seq");
}

struct ResolvedSequenceReference {
    Oid oid = INVALID_OID;
    std::string storageName;
    std::string displayName;
    char persistence = 'p';
};

static std::optional<std::string> normalizeRegclassPart(std::string part) {
    size_t first = 0;
    size_t last = part.size();
    while (first < last && std::isspace(
               static_cast<unsigned char>(part[first]))) ++first;
    while (last > first && std::isspace(
               static_cast<unsigned char>(part[last - 1]))) --last;
    part = part.substr(first, last - first);
    if (part.empty()) return std::nullopt;
    if (part.front() == '"') {
        if (part.size() < 2 || part.back() != '"') return std::nullopt;
        std::string decoded;
        for (size_t i = 1; i + 1 < part.size(); ++i) {
            if (part[i] != '"') {
                decoded.push_back(part[i]);
                continue;
            }
            if (i + 2 >= part.size() || part[i + 1] != '"') {
                return std::nullopt;
            }
            decoded.push_back('"');
            ++i;
        }
        return decoded.empty() ? std::nullopt
                               : std::optional<std::string>(decoded);
    }
    if (part.find('"') != std::string::npos) return std::nullopt;
    for (char& c : part) {
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    return part;
}

static std::string quoteRegclassPart(const std::string& part) {
    std::string quoted = "\"";
    for (char ch : part) {
        quoted += ch;
        if (ch == '"') quoted += '"';
    }
    quoted += '"';
    return quoted;
}

static std::optional<std::string> normalizeRegclassText(
    const std::string& input) {
    bool quoted = false;
    size_t separator = std::string::npos;
    for (size_t i = 0; i < input.size(); ++i) {
        if (input[i] == '"') {
            if (quoted && i + 1 < input.size() && input[i + 1] == '"') {
                ++i;
            } else {
                quoted = !quoted;
            }
        } else if (input[i] == '.' && !quoted) {
            if (separator != std::string::npos) return std::nullopt;
            separator = i;
        }
    }
    if (quoted) return std::nullopt;
    if (separator == std::string::npos) {
        const auto relation = normalizeRegclassPart(input);
        return relation ? std::optional<std::string>(
                              quoteRegclassPart(*relation))
                        : std::nullopt;
    }
    const auto schema = normalizeRegclassPart(input.substr(0, separator));
    const auto relation = normalizeRegclassPart(input.substr(separator + 1));
    if (!schema || !relation) return std::nullopt;
    return quoteRegclassPart(*schema) + "." +
           quoteRegclassPart(*relation);
}

static ResolvedSequenceReference resolveSequenceReference(
    StorageEngine& engine, const std::string& dbname,
    const std::string& input) {
    if (dbname.empty() || !engine.databaseExists(dbname)) {
        throw DbError("3D000", "database does not exist");
    }
    const auto normalized = normalizeRegclassText(input);
    CatalogManager::QualifiedName qualified;
    if (!normalized ||
        !CatalogManager::parseQualifiedName(*normalized, qualified) ||
        !validStoredIdentifier(qualified.name, MAX_TABLE_NAME_LEN) ||
        (!qualified.schema.empty() &&
         !validStoredIdentifier(qualified.schema, MAX_TABLE_NAME_LEN))) {
        throw DbError("42P01", "relation \"" + input + "\" does not exist");
    }

    Session* session = currentSession();
    if (!session) {
        return {INVALID_OID,
                sequenceStorageName(qualified.schema, qualified.name),
                input, 'p'};
    }

    std::vector<std::string> searchPath;
    std::string canonical;
    if (!parseSessionSearchPath(session->searchPath, searchPath, canonical)) {
        searchPath = {"public"};
    }
    for (auto& entry : searchPath) {
        entry = expandSessionSearchPathEntry(entry, session->username);
        if (entry == "pg_temp") entry = sessionTempSchemaName(*session);
    }
    CatalogManager& catalog = engine.catalogService().get(dbname);
    if (session->tempNamespaceCreated && catalog.getTempNamespace(session->pid) &&
        std::find(searchPath.begin(), searchPath.end(), sessionTempSchemaName(*session)) == searchPath.end()) {
        searchPath.insert(searchPath.begin(), sessionTempSchemaName(*session));
    }
    const std::string lookup = qualified.schema == "pg_temp"
        ? quoteRegclassPart(sessionTempSchemaName(*session)) + "." + quoteRegclassPart(qualified.name)
        : *normalized;
    const auto relation = catalog.resolveRelationSnapshot(
        lookup, searchPath.empty() ? std::vector<std::string>{"public"}
                                        : searchPath);
    if (!relation) {
        throw DbError("42P01",
                      "relation \"" + input + "\" does not exist");
    }
    if (relation->relkind != 'S') {
        throw DbError("42809",
                      "\"" + input + "\" is not a sequence");
    }
    const auto relationNamespace =
        catalog.getNamespace(relation->relnamespace);
    if (!relationNamespace) {
        throw DbError("XX001", "sequence namespace metadata is corrupt");
    }
    const std::string storageName = sequenceStorageName(
        relationNamespace->nspname, relation->relname);
    return {relation->oid, storageName, input,
            relation->relpersistence};
}

static void throwSequenceReadError(const std::filesystem::path& path,
                                   const std::string& displayName) {
    std::error_code error;
    const auto status = std::filesystem::symlink_status(path, error);
    if (!error && !std::filesystem::exists(status)) {
        throw DbError("42P01",
                      "relation \"" + displayName + "\" does not exist");
    }
    throw DbError("XX001",
                  "could not read sequence \"" + displayName + "\"");
}

static std::string fallbackSequenceStateKey(
    const std::string& dbname, const std::string& storageName) {
    return dbname + '\x1f' + storageName;
}

static bool checkedAdd(int64_t lhs, int64_t rhs, int64_t& result) {
    return !__builtin_add_overflow(lhs, rhs, &result);
}

static bool checkedSub(int64_t lhs, int64_t rhs, int64_t& result) {
    return !__builtin_sub_overflow(lhs, rhs, &result);
}

static bool checkedMul(int64_t lhs, int64_t rhs, int64_t& result) {
    return !__builtin_mul_overflow(lhs, rhs, &result);
}

static void sequencePredecessor(int64_t value, int64_t increment,
                                int64_t& predecessor) {
    // Equality is an explicit exhausted marker when value-increment is not
    // representable (for example INT64_MAX with a positive increment).
    if (!checkedSub(value, increment, predecessor)) predecessor = value;
}

static constexpr const char* SEQUENCE_FILE_V2 = "DBMSSEQ2";
static constexpr const char* SEQUENCE_FILE_V3 = "DBMSSEQ3";
static constexpr const char* SEQUENCE_FILE_V4 = "DBMSSEQ4";
static constexpr const char* SEQUENCE_FILE_V5 = "DBMSSEQ5";
static constexpr const char* SEQUENCE_RUNTIME_DIRECTORY = ".sequence_runtime";

struct SequenceCallState {
    int64_t lastValue = 0; // persistent reservation high-water, like pg_sequence_data
    bool called = false;
    bool known = false;
};

static bool validSequenceGeneration(const std::string& generation) {
    UuidValue parsed;
    return generation.size() == 36 && UuidValue::parse(generation, parsed) &&
           parsed.toString() == generation;
}

static std::filesystem::path sequenceRuntimePath(
    const std::filesystem::path& declaration, const std::string& generation) {
    return declaration.parent_path() / SEQUENCE_RUNTIME_DIRECTORY / generation;
}

static bool readSequenceRuntime(const std::filesystem::path& path,
    const std::string& generation, int64_t& next, int64_t& allocated,
    bool& exhausted, SequenceCallState* callState = nullptr) {
    if (!validSequenceGeneration(generation)) return false;
    std::error_code error;
    const auto status = std::filesystem::symlink_status(path, error);
    if (error || !std::filesystem::is_regular_file(status)) return false;
    std::ifstream input(path);
    std::string magic, storedGeneration, trailing;
    int exhaustedFlag = 0;
    if (!(input >> magic >> storedGeneration >> next >> allocated >> exhaustedFlag) ||
        (magic != "DBMSSEQR1" && magic != "DBMSSEQR2") || storedGeneration != generation ||
        (exhaustedFlag != 0 && exhaustedFlag != 1)) {
        return false;
    }
    SequenceCallState state;
    if (magic == "DBMSSEQR2") {
        int called = 0;
        if (!(input >> state.lastValue >> called) || (called != 0 && called != 1)) return false;
        state.called = called != 0;
        state.known = true;
    }
    if (input >> trailing) return false;
    if (!input.eof() || input.bad()) return false;
    exhausted = exhaustedFlag != 0;
    if (callState) *callState = state;
    return true;
}

static bool writeSequenceRuntime(const std::filesystem::path& declaration,
    const std::string& generation, int64_t next, int64_t allocated,
    bool exhausted, const SequenceCallState* callState = nullptr) {
    if (!validSequenceGeneration(generation)) return false;
    const auto path = sequenceRuntimePath(declaration, generation);
    std::error_code error;
    std::filesystem::create_directories(path.parent_path(), error);
    if (error || std::filesystem::is_symlink(path.parent_path())) return false;
    std::ostringstream serialized;
    serialized << (callState ? "DBMSSEQR2 " : "DBMSSEQR1 ") << generation << ' '
               << next << ' ' << allocated << ' ' << (exhausted ? 1 : 0);
    if (callState) serialized << ' ' << callState->lastValue << ' ' << (callState->called ? 1 : 0);
    serialized << '\n';
    return index_file::writeAtomically(path, serialized.str());
}

// Only SQL rollback restores keep nontransactional allocations. Explicit
// physical restore must continue to restore the exact backed-up counters.
static thread_local const std::string* sequenceRollbackDatabase = nullptr;
class SequenceRollbackRestoreScope {
    const std::string* previous_;
public:
    explicit SequenceRollbackRestoreScope(const std::string& database)
        : previous_(sequenceRollbackDatabase) {
        sequenceRollbackDatabase = &database;
    }
    ~SequenceRollbackRestoreScope() { sequenceRollbackDatabase = previous_; }
};

static bool preserveSequenceRuntimeForks(const std::filesystem::path& live,
    const std::filesystem::path& staged) {
    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    const auto source = live / SEQUENCE_RUNTIME_DIRECTORY;
    std::error_code error;
    const auto status = std::filesystem::symlink_status(source, error);
    if (error == std::errc::no_such_file_or_directory ||
        (!error && !std::filesystem::exists(status))) return true;
    if (error || !std::filesystem::is_directory(status)) return false;
    const auto destination = staged / SEQUENCE_RUNTIME_DIRECTORY;
    std::filesystem::create_directories(destination, error);
    if (error || std::filesystem::is_symlink(destination)) return false;
    for (const auto& entry : std::filesystem::directory_iterator(source)) {
        const auto generation = entry.path().filename().string();
        int64_t next = 0, allocated = 0;
        bool exhausted = false;
        SequenceCallState state;
        if (!readSequenceRuntime(entry.path(), generation, next, allocated, exhausted, &state) ||
            !writeSequenceRuntime(staged / "declaration", generation,
                                  next, allocated, exhausted, state.known ? &state : nullptr)) return false;
    }
    return true;
}

static std::string encodeSequenceOwnedField(const std::string& value) {
    if (value.empty()) return "-";
    constexpr char digits[] = "0123456789abcdef";
    std::string encoded = "x";
    encoded.reserve(1 + value.size() * 2);
    for (unsigned char byte : value) {
        encoded += digits[byte >> 4];
        encoded += digits[byte & 0x0f];
    }
    return encoded;
}

static bool decodeSequenceOwnedField(const std::string& encoded,
                                     std::string& value) {
    value.clear();
    if (encoded == "-") return true;
    if (encoded.size() < 3 || encoded.front() != 'x' ||
        encoded.size() % 2 == 0) return false;
    const auto nibble = [](char ch) -> int {
        if (ch >= '0' && ch <= '9') return ch - '0';
        if (ch >= 'a' && ch <= 'f') return ch - 'a' + 10;
        return -1;
    };
    for (size_t i = 1; i < encoded.size(); i += 2) {
        const int high = nibble(encoded[i]);
        const int low = nibble(encoded[i + 1]);
        if (high < 0 || low < 0) return false;
        value += static_cast<char>((high << 4) | low);
    }
    return true;
}

static bool parseSequenceInt64(const std::string& token, int64_t& value) {
    if (token.empty()) return false;
    const char* begin = token.data();
    const char* end = begin + token.size();
    if (*begin == '+') {
        ++begin;
        if (begin == end) return false;
    }
    const auto parsed = std::from_chars(begin, end, value, 10);
    return parsed.ec == std::errc{} && parsed.ptr == end;
}

// V3 sequence file format adds an explicit exhausted bit.  Without it the
// on-disk boundary value cannot distinguish "not returned yet" from "already
// returned", which made non-cycling sequences repeat their final value.
// V4 encodes ownership strings so quoted whitespace cannot shift token
// boundaries. V5 separates the transactional declaration/storage generation
// from its nontransactional allocation fork. Older files remain readable.
static bool readSequenceFile(const std::filesystem::path& path,
                             dbms::SequenceInfo& info,
                             int64_t& nextValue,
                             int64_t& lastAllocated,
                             bool* exhaustedOut = nullptr,
                             std::string* generationOut = nullptr,
                             SequenceCallState* callStateOut = nullptr) {
    std::ifstream ifs(path);
    if (!ifs) return false;
    std::string firstToken;
    if (!(ifs >> firstToken)) return false;

    const bool version4 = firstToken == SEQUENCE_FILE_V4;
    const bool version5 = firstToken == SEQUENCE_FILE_V5;
    std::string generation;
    const bool version3 = firstToken == SEQUENCE_FILE_V3;
    const bool version2 = firstToken == SEQUENCE_FILE_V2;
    int64_t start = 1;
    int64_t increment = 1;
    int64_t minValue = 1;
    int64_t maxValue = std::numeric_limits<int64_t>::max();
    int64_t cache = 1;
    int64_t cycleFlag = 0;
    int64_t next = 1;
    int64_t last = 0;
    int64_t minExplicit = 0;
    int64_t maxExplicit = 0;
    int64_t exhaustedFlag = 0;
    if (version5 || version4 || version3) {
        if (!(ifs >> start >> increment >> minValue >> maxValue >> cache >>
              cycleFlag >> next >> last >> minExplicit >> maxExplicit >>
              exhaustedFlag)) {
            return false;
        }
        if ((minExplicit != 0 && minExplicit != 1) ||
            (maxExplicit != 0 && maxExplicit != 1) ||
            (exhaustedFlag != 0 && exhaustedFlag != 1)) {
            return false;
        }
    } else if (version2) {
        if (!(ifs >> start >> increment >> minValue >> maxValue >> cache >>
              cycleFlag >> next >> last >> minExplicit >> maxExplicit)) {
            return false;
        }
        if ((minExplicit != 0 && minExplicit != 1) ||
            (maxExplicit != 0 && maxExplicit != 1)) {
            return false;
        }
    } else {
        if (!parseSequenceInt64(firstToken, start) ||
            !(ifs >> increment >> minValue >> maxValue >> cache >>
              cycleFlag >> next >> last)) {
            return false;
        }
    }

    std::string ownedTable;
    std::string ownedColumn;
    if (version5 && (!(ifs >> generation) || !validSequenceGeneration(generation)))
        return false;
    if (version5 || version4) {
        std::string tableToken;
        std::string columnToken;
        if (!(ifs >> tableToken >> columnToken) ||
            !decodeSequenceOwnedField(tableToken, ownedTable) ||
            !decodeSequenceOwnedField(columnToken, ownedColumn)) {
            return false;
        }
    } else {
        // Older writers did not escape ownership names. Read the entire
        // remainder, using the final whitespace outside SQL quotes as the
        // field separator. This also recovers files already written with a
        // whitespace-bearing schema and a simple owning column.
        std::string remainder;
        if (!std::getline(ifs, remainder) && !ifs.eof()) return false;
        const auto trim = [](std::string& value) {
            size_t first = 0;
            size_t last = value.size();
            while (first < last && std::isspace(
                       static_cast<unsigned char>(value[first]))) ++first;
            while (last > first && std::isspace(
                       static_cast<unsigned char>(value[last - 1]))) --last;
            value = value.substr(first, last - first);
        };
        trim(remainder);
        if (!remainder.empty()) {
            bool quoted = false;
            size_t separator = std::string::npos;
            for (size_t i = 0; i < remainder.size(); ++i) {
                if (remainder[i] == '"') {
                    if (quoted && i + 1 < remainder.size() &&
                        remainder[i + 1] == '"') {
                        ++i;
                    } else {
                        quoted = !quoted;
                    }
                } else if (!quoted && std::isspace(
                               static_cast<unsigned char>(remainder[i]))) {
                    separator = i;
                }
            }
            if (quoted || separator == std::string::npos) return false;
            ownedTable = remainder.substr(0, separator);
            ownedColumn = remainder.substr(separator + 1);
            trim(ownedTable);
            trim(ownedColumn);
            if (ownedTable.empty() || ownedColumn.empty()) return false;
            if (ownedTable.find_first_of(" \t\r\n") != std::string::npos &&
                ownedTable.find('"') == std::string::npos) {
                // The only safely recoverable unquoted V3 shape is a
                // whitespace-bearing schema before the final dot. Reject
                // arbitrary extra words instead of inventing an owner.
                const size_t dot = ownedTable.rfind('.');
                if (dot == std::string::npos ||
                    ownedTable.substr(0, dot).find_first_of(" \t\r\n") ==
                        std::string::npos ||
                    ownedTable.substr(dot + 1).find_first_of(" \t\r\n") !=
                        std::string::npos) {
                    return false;
                }
            }
        }
    }
    ifs.clear();
    std::string extra;
    if (ifs >> extra) return false;

    SequenceCallState callState;
    if (version5) {
        bool exhausted = false;
        if (!readSequenceRuntime(sequenceRuntimePath(path, generation), generation,
                                 next, last, exhausted, &callState)) return false;
        exhaustedFlag = exhausted ? 1 : 0;
    }

    if (cycleFlag != 0 && cycleFlag != 1) return false;
    if (increment == 0 || minValue > maxValue ||
        start < minValue || start > maxValue || cache < 1 ||
        next < minValue || next > maxValue) {
        return false;
    }
    if (last < minValue || last > maxValue) {
        int64_t initialPredecessor = 0;
        if (!checkedSub(start, increment, initialPredecessor)) {
            initialPredecessor = start;
        }
        int64_t nextPredecessor = 0;
        sequencePredecessor(next, increment, nextPredecessor);
        if (last != initialPredecessor && (!version5 || last != nextPredecessor)) return false;
    }

    if (!version2 && !version3 && !version4 && !version5) {
        const int64_t defaultMinimum = increment > 0
            ? 1 : -std::numeric_limits<int64_t>::max();
        const int64_t defaultMaximum = increment > 0
            ? std::numeric_limits<int64_t>::max() : -1;
        minExplicit = minValue != defaultMinimum;
        maxExplicit = maxValue != defaultMaximum;
    }

    info = dbms::SequenceInfo{};
    info.start = start;
    info.increment = increment;
    info.minValue = minValue;
    info.maxValue = maxValue;
    info.cache = cache;
    info.cycle = cycleFlag != 0;
    info.hasMinValue = minExplicit != 0;
    info.hasMaxValue = maxExplicit != 0;
    info.ownedByTable = std::move(ownedTable);
    info.ownedByColumn = std::move(ownedColumn);
    nextValue = next;
    lastAllocated = last;
    if (!callState.known) {
        // Old declarations encoded an unallocated predecessor rather than
        // is_called. Preserve their exact next cursor while migrating; new
        // allocations thereafter persist both independent fields.
        callState.called = exhaustedFlag != 0 || (last >= minValue && last <= maxValue);
        callState.lastValue = callState.called ? last : next;
        callState.known = true;
    }
    if (version5 && callState.lastValue < minValue) return false;
    if (version5 && callState.lastValue > maxValue) return false;
    if (exhaustedOut) *exhaustedOut = exhaustedFlag != 0;
    if (generationOut) *generationOut = std::move(generation);
    if (callStateOut) *callStateOut = callState;
    return true;
}

static bool writeSequenceFile(const std::filesystem::path& path,
                              const dbms::SequenceInfo& info,
                              int64_t nextValue,
                              int64_t lastAllocated,
                              bool exhausted = false,
                              std::string generation = {},
                              const SequenceCallState* suppliedCallState = nullptr) {
    if (generation.empty()) generation = UuidValue::generateV4().toString();
    SequenceCallState initial;
    if (!suppliedCallState) {
        initial.called = false;
        initial.lastValue = nextValue;
        initial.known = true;
        suppliedCallState = &initial;
    }
    if (!writeSequenceRuntime(path, generation, nextValue, lastAllocated, exhausted, suppliedCallState))
        return false;
    std::ostringstream serialized;
    serialized << SEQUENCE_FILE_V5 << " "
               << info.start << " "
               << info.increment << " "
               << info.minValue << " "
               << info.maxValue << " "
               << info.cache << " "
               << (info.cycle ? 1 : 0) << " "
               << nextValue << " "
               << lastAllocated << " "
               << (info.hasMinValue ? 1 : 0) << " "
               << (info.hasMaxValue ? 1 : 0) << " "
               << (exhausted ? 1 : 0) << " "
               << generation << " "
               << encodeSequenceOwnedField(info.ownedByTable) << " "
               << encodeSequenceOwnedField(info.ownedByColumn) << "\n";
    return index_file::writeAtomically(path, serialized.str());
}

static bool ensureSequenceGenerationsForBackup(const std::string& dbname) {
    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    for (const auto& entry : std::filesystem::directory_iterator(dbname)) {
        const auto extension = entry.path().extension();
        if (!entry.is_regular_file() || (extension != ".seq" && extension != ".seqv2"))
            continue;
        SequenceInfo info;
        int64_t next = 0, allocated = 0;
        bool exhausted = false;
        std::string generation;
        SequenceCallState callState;
        if (!readSequenceFile(entry.path(), info, next, allocated, &exhausted, &generation, &callState)) {
            // The unrelated legacy per-table AUTO_INCREMENT sidecar also
            // has extension .seq, but its first token is a column name.
            std::ifstream input(entry.path());
            std::string magic;
            if (extension == ".seqv2" ||
                ((input >> magic) && magic.rfind("DBMSSEQ", 0) == 0)) return false;
            continue;
        }
        if (generation.empty() && !writeSequenceFile(entry.path(), info,
                next, allocated, exhausted, {}, &callState)) return false;
    }
    return true;
}

// Retired generations are necessary while any transaction image/savepoint
// can restore their declarations. Reclaim only after the owner has finished
// and discarded its rollback images, never at DROP or RESTART inside it.
static void pruneSequenceRuntimeForks(const std::string& dbname) {
    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    try {
        const auto runtime = std::filesystem::path(dbname) / SEQUENCE_RUNTIME_DIRECTORY;
        if (!std::filesystem::exists(runtime) || std::filesystem::is_symlink(runtime)) return;
        std::set<std::string> active;
        for (const auto& entry : std::filesystem::directory_iterator(dbname)) {
            const auto extension = entry.path().extension();
            if (!entry.is_regular_file() || (extension != ".seq" && extension != ".seqv2"))
                continue;
            SequenceInfo info;
            int64_t next = 0, allocated = 0;
            std::string generation;
            if (!readSequenceFile(entry.path(), info, next, allocated, nullptr, &generation)) {
                std::ifstream input(entry.path());
                std::string magic;
                if (extension == ".seqv2" ||
                    ((input >> magic) && magic.rfind("DBMSSEQ", 0) == 0)) return;
                continue;
            }
            if (!generation.empty()) active.insert(generation);
        }
        for (const auto& entry : std::filesystem::directory_iterator(runtime)) {
            const auto generation = entry.path().filename().string();
            if (!validSequenceGeneration(generation) || !entry.is_regular_file() ||
                entry.is_symlink()) return;
            if (!active.count(generation)) {
                std::error_code error;
                std::filesystem::remove(entry.path(), error);
                if (error) return; // orphan retention cannot fail a committed transaction
            }
        }
        (void)index_file::syncDirectory(runtime);
    } catch (...) {
        // Keep recoverable orphan files on an ordinary cleanup failure.
    }
}

DBStatus StorageEngine::createSequence(const std::string& dbname,
                                        const std::string& seqname,
                                        int64_t start, int64_t increment) {
    dbms::SequenceInfo info;
    info.start = start;
    info.increment = increment;
    info.startSpecified = true;
    info.incrementSpecified = true;
    info.applyDefaults();
    return createSequence(dbname, seqname, info);
}

DBStatus StorageEngine::createSequence(const std::string& dbname,
                                        const std::string& seqname,
                                        const dbms::SequenceInfo& info) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validSequenceName(seqname)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto path = sequencePath(dbname, seqname);
    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    if (std::filesystem::exists(path)) return DBStatus::TABLE_ALREADY_EXISTS;
    if (info.increment == 0) return DBStatus::INVALID_VALUE;
    dbms::SequenceInfo applied = info;
    applied.applyDefaults();
    if (!info.startSpecified && info.start == 1) {
        applied.start = applied.increment > 0
            ? applied.minValue : applied.maxValue;
    }
    if (applied.minValue > applied.start || applied.start > applied.maxValue)
        return DBStatus::INVALID_VALUE;
    if (applied.cache < 1) return DBStatus::INVALID_VALUE;
    int64_t nextValue = applied.start;
    int64_t lastAllocated = 0;
    sequencePredecessor(applied.start, applied.increment, lastAllocated);
    if (!writeSequenceFile(path, applied, nextValue, lastAllocated))
        return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

DBStatus StorageEngine::alterSequence(const std::string& dbname,
                                       const std::string& seqname,
                                       bool hasRestart, int64_t restart,
                                       bool hasIncrement, int64_t increment) {
    dbms::SequenceInfo info;
    if (hasRestart) {
        info.restart = restart;
        info.restartSpecified = true;
        info.restartValueSpecified = true;
    }
    if (hasIncrement) { info.increment = increment; info.incrementSpecified = true; }
    return alterSequence(dbname, seqname, info);
}

DBStatus StorageEngine::alterSequence(const std::string& dbname,
                                       const std::string& seqname,
                                       const dbms::SequenceInfo& info) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validSequenceName(seqname)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto path = sequencePath(dbname, seqname);
    std::unique_lock<std::mutex> lock(g_sequenceMutex);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    dbms::SequenceInfo old;
    int64_t nextValue, lastAllocated;
    bool exhausted = false;
    std::string generation;
    SequenceCallState callState;
    if (!readSequenceFile(path, old, nextValue, lastAllocated, &exhausted, &generation, &callState))
        return DBStatus::INVALID_VALUE;

    dbms::SequenceInfo merged = old;
    if (info.startSpecified) {
        merged.start = info.start;
    }
    if (info.incrementSpecified) {
        merged.increment = info.increment;
        if (merged.increment == 0) return DBStatus::INVALID_VALUE;
    }
    if (info.hasMinValue) { merged.minValue = info.minValue; merged.hasMinValue = true; merged.noMinValue = false; }
    if (info.noMinValue) {
        merged.noMinValue = true; merged.hasMinValue = false;
        merged.minValue = merged.increment > 0 ? 1 : -std::numeric_limits<int64_t>::max();
    }
    if (info.hasMaxValue) { merged.maxValue = info.maxValue; merged.hasMaxValue = true; merged.noMaxValue = false; }
    if (info.noMaxValue) {
        merged.noMaxValue = true; merged.hasMaxValue = false;
        merged.maxValue = merged.increment > 0 ? std::numeric_limits<int64_t>::max() : -1;
    }
    if (info.cacheSpecified) merged.cache = info.cache;
    if (info.cycleSpecified) merged.cycle = info.cycle;
    if (info.ownedBySpecified) {
        merged.ownedByTable = info.ownedByTable;
        merged.ownedByColumn = info.ownedByColumn;
    }

    if (merged.minValue > merged.maxValue) return DBStatus::INVALID_VALUE;
    if (merged.start < merged.minValue || merged.start > merged.maxValue) {
        return DBStatus::INVALID_VALUE;
    }
    if (info.restartSpecified) {
        const int64_t restartValue = info.restartValueSpecified
            ? info.restart : merged.start;
        if (restartValue < merged.minValue || restartValue > merged.maxValue) {
            return DBStatus::INVALID_VALUE;
        }
        nextValue = restartValue;
        sequencePredecessor(nextValue, merged.increment, lastAllocated);
        exhausted = false;
        callState = {restartValue, false, true};
    } else {
        if (callState.lastValue < merged.minValue || callState.lastValue > merged.maxValue)
            return DBStatus::INVALID_VALUE;
        // ALTER discards the backend's preallocated cache. The new stream
        // advances from persistent last_value using the NEW increment, not
        // from the old stream's already-computed next cursor.
        exhausted = false;
        nextValue = callState.lastValue;
        if (callState.called) {
            int64_t advanced = 0;
            const bool fits = checkedAdd(callState.lastValue, merged.increment, advanced);
            if (!fits || advanced < merged.minValue || advanced > merged.maxValue) {
                if (merged.cycle)
                    nextValue = merged.increment > 0 ? merged.minValue : merged.maxValue;
                else exhausted = true;
            } else nextValue = advanced;
            lastAllocated = callState.lastValue;
            if (merged.cycle && (!fits || advanced < merged.minValue || advanced > merged.maxValue))
                sequencePredecessor(nextValue, merged.increment, lastAllocated);
        } else sequencePredecessor(nextValue, merged.increment, lastAllocated);
    }
    if (merged.cache < 1) return DBStatus::INVALID_VALUE;
    // PG replaces storage for every option affecting future generation,
    // even if its value is unchanged. OWNED BY changes only metadata.
    const bool rewrite = info.startSpecified || info.restartSpecified ||
        info.incrementSpecified || info.hasMinValue || info.noMinValue ||
        info.hasMaxValue || info.noMaxValue || info.cacheSpecified || info.cycleSpecified;
    if (!writeSequenceFile(
            path, merged, nextValue, lastAllocated, exhausted,
            rewrite ? std::string{} : generation, &callState))
        return DBStatus::IO_ERROR;
    lock.unlock();
    if (!transactionContext().inTransaction) {
        // Native callers need not open a SQL owner. Do not accumulate
        // retired forks, but never reclaim a generation while another
        // backend can still own its rollback image.
        std::lock_guard<std::mutex> activeLock(globalTxnMutex());
        if (std::none_of(activeTransactionDatabases().begin(), activeTransactionDatabases().end(),
                [&](const auto& entry) { return entry.second == dbname; }))
            pruneSequenceRuntimeForks(dbname);
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::renameSequence(const std::string& dbname,
                                       const std::string& oldName,
                                       const std::string& newName) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (oldName.empty() || newName.empty() || oldName == "." || newName == "." ||
        oldName == ".." || newName == ".." ||
        !validSequenceName(oldName) ||
        !validSequenceName(newName) ||
        oldName.find('/') != std::string::npos || newName.find('/') != std::string::npos ||
        oldName.find('\\') != std::string::npos || newName.find('\\') != std::string::npos) {
        return DBStatus::INVALID_VALUE;
    }

    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    const auto oldPath = sequencePath(dbname, oldName);
    const auto newPath = sequencePath(dbname, newName);
    if (!std::filesystem::exists(oldPath)) return DBStatus::TABLE_NOT_FOUND;
    if (std::filesystem::exists(newPath)) return DBStatus::TABLE_ALREADY_EXISTS;

    std::error_code ec;
    std::filesystem::rename(oldPath, newPath, ec);
    if (ec) return DBStatus::IO_ERROR;

    const auto parent = oldPath.parent_path().empty()
        ? std::filesystem::path(".") : oldPath.parent_path();
    if (!index_file::syncDirectory(parent)) {
        std::error_code rollbackEc;
        std::filesystem::rename(newPath, oldPath, rollbackEc);
        (void)index_file::syncDirectory(parent);
        return DBStatus::IO_ERROR;
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::dropSequence(const std::string& dbname,
                                      const std::string& seqname) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validSequenceName(seqname)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto path = sequencePath(dbname, seqname);
    std::unique_lock<std::mutex> lock(g_sequenceMutex);
    std::error_code ec;
    const auto fileStatus = std::filesystem::symlink_status(path, ec);
    if (ec) return DBStatus::IO_ERROR;
    if (!std::filesystem::exists(fileStatus)) return DBStatus::TABLE_NOT_FOUND;
    if (!std::filesystem::is_regular_file(fileStatus)) {
        return DBStatus::INVALID_VALUE;
    }
    std::ifstream originalFile(path, std::ios::binary);
    if (!originalFile) return DBStatus::IO_ERROR;
    const std::string originalBytes{
        std::istreambuf_iterator<char>(originalFile),
        std::istreambuf_iterator<char>()};
    if (originalFile.bad()) return DBStatus::IO_ERROR;
    if (!std::filesystem::remove(path, ec) || ec) return DBStatus::IO_ERROR;
    if (!index_file::syncDirectory(path.parent_path())) {
        (void)index_file::writeAtomicallyNoReplace(path, originalBytes);
        return DBStatus::IO_ERROR;
    }
    lock.unlock();
    if (!transactionContext().inTransaction) {
        std::lock_guard<std::mutex> activeLock(globalTxnMutex());
        if (std::none_of(activeTransactionDatabases().begin(), activeTransactionDatabases().end(),
                [&](const auto& entry) { return entry.second == dbname; }))
            pruneSequenceRuntimeForks(dbname);
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::getSequenceInfo(const std::string& dbname,
                                        const std::string& seqname,
                                        dbms::SequenceInfo& info) const {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validSequenceName(seqname)) return DBStatus::INVALID_ARGUMENT;
    const auto path = sequencePath(dbname, seqname);
    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    std::error_code error;
    const auto status = std::filesystem::symlink_status(path, error);
    if (error) return DBStatus::IO_ERROR;
    if (!std::filesystem::exists(status)) return DBStatus::TABLE_NOT_FOUND;
    if (!std::filesystem::is_regular_file(status)) {
        return DBStatus::CORRUPTED_DATA;
    }
    int64_t nextValue = 0;
    int64_t lastAllocated = 0;
    return readSequenceFile(path, info, nextValue, lastAllocated)
        ? DBStatus::OK : DBStatus::CORRUPTED_DATA;
}

int64_t StorageEngine::nextval(const std::string& dbname,
                                const std::string& seqname) {
    const ResolvedSequenceReference resolved =
        resolveSequenceReference(*this, dbname, seqname);
    if (resolved.persistence == 't') noteTemporaryObjectAccess(dbname);
    if (transactionContext().inTransaction &&
        transactionContext().readOnly && resolved.persistence != 't') {
        throw DbError("25006",
                      "cannot execute nextval() in a read-only transaction");
    }
    const auto path = sequencePath(dbname, resolved.storageName);
    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    dbms::SequenceInfo info;
    int64_t nextValue, lastAllocated;
    bool exhausted = false;
    std::string generation;
    SequenceCallState callState;
    if (!readSequenceFile(
            path, info, nextValue, lastAllocated, &exhausted, &generation, &callState)) {
        throwSequenceReadError(path, resolved.displayName);
    }
    if (exhausted) {
        if (!info.cycle) {
            throw DbError(
                "2200H", "nextval: reached maximum or minimum value of "
                         "sequence \"" + resolved.displayName + "\"");
        }
        nextValue = info.increment > 0 ? info.minValue : info.maxValue;
        sequencePredecessor(nextValue, info.increment, lastAllocated);
        exhausted = false;
    }

    auto allocateBatch = [&](int64_t from) {
        // Allocate 'cache' values starting from 'from' in the direction of increment.
        int64_t count = 0;
        int64_t delta = 0;
        int64_t end = 0;
        if (!checkedSub(info.cache, 1, count) ||
            !checkedMul(count, info.increment, delta) ||
            !checkedAdd(from, delta, end)) {
            return std::optional<int64_t>{
                (info.increment > 0) ? info.maxValue : info.minValue};
        }
        if (info.increment > 0) {
            if (end > info.maxValue) end = info.maxValue;
        } else {
            if (end < info.minValue) end = info.minValue;
        }
        return std::optional<int64_t>{end};
    };

    auto needAllocation = [&]() {
        if (info.increment > 0) return nextValue > lastAllocated;
        return nextValue < lastAllocated;
    };

    if (needAllocation()) {
        const auto end = allocateBatch(nextValue);
        if (!end) {
            throw DbError("2200H", "sequence allocation overflow");
        }
        lastAllocated = *end;
    }

    callState = {lastAllocated, true, true};
    int64_t result = nextValue;
    int64_t advanced = 0;
    if (!checkedAdd(nextValue, info.increment, advanced)) {
        // There is no representable value beyond the current boundary. Keep
        // the boundary stable for non-cycling sequences, or wrap atomically
        // for cycling sequences, without invoking signed-overflow UB.
        if (info.cycle) {
            nextValue = (info.increment > 0) ? info.minValue : info.maxValue;
            sequencePredecessor(nextValue, info.increment, lastAllocated);
        } else {
            nextValue = result;
            lastAllocated = result;
            exhausted = true;
        }
    } else {
        nextValue = advanced;
        const bool crossedBoundary = (info.increment > 0)
            ? (nextValue > info.maxValue) : (nextValue < info.minValue);
        if (crossedBoundary) {
            if (info.cycle) {
                nextValue = (info.increment > 0) ? info.minValue : info.maxValue;
                sequencePredecessor(nextValue, info.increment, lastAllocated);
            } else {
                nextValue = result;
                lastAllocated = result;
                exhausted = true;
            }
        }
    }

    if (!(generation.empty()
            ? writeSequenceFile(path, info, nextValue, lastAllocated, exhausted, {}, &callState)
            : writeSequenceRuntime(path, generation, nextValue, lastAllocated, exhausted, &callState))) {
        throw DbError("58030",
                      "could not write sequence \"" +
                          resolved.displayName + "\"");
    }
    if (g_currentSession && resolved.oid != INVALID_OID) {
        g_currentSession->sequenceLastValuesByOid[resolved.oid] = result;
        g_currentSession->sequenceLastValues[resolved.storageName] = result;
        g_currentSession->lastUsedSequenceOid = resolved.oid;
        g_currentSession->lastUsedSequenceDatabase = dbname;
    } else {
        TransactionContext& context = transactionContext();
        context.sequenceLastValues[fallbackSequenceStateKey(
            dbname, resolved.storageName)] = result;
        context.lastvalDb = dbname;
        context.lastvalSeq = resolved.storageName;
        context.lastvalValue = result;
        context.lastvalDefined = true;
    }
    return result;
}

int64_t StorageEngine::currval(const std::string& dbname,
                               const std::string& seqname) {
    const ResolvedSequenceReference resolved =
        resolveSequenceReference(*this, dbname, seqname);
    if (resolved.persistence == 't') noteTemporaryObjectAccess(dbname);
    const auto path = sequencePath(dbname, resolved.storageName);
    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    dbms::SequenceInfo info;
    int64_t nextValue, lastAllocated;
    if (!readSequenceFile(path, info, nextValue, lastAllocated)) {
        throwSequenceReadError(path, resolved.displayName);
    }
    if (g_currentSession && resolved.oid != INVALID_OID) {
        const auto value =
            g_currentSession->sequenceLastValuesByOid.find(resolved.oid);
        if (value == g_currentSession->sequenceLastValuesByOid.end()) {
            throw DbError(
                "55000", "currval of sequence \"" + resolved.displayName +
                             "\" is not yet defined in this session");
        }
        return value->second;
    }
    const auto key = fallbackSequenceStateKey(dbname, resolved.storageName);
    const auto value = transactionContext().sequenceLastValues.find(key);
    if (value == transactionContext().sequenceLastValues.end()) {
        throw DbError(
            "55000", "currval of sequence \"" + resolved.displayName +
                         "\" is not yet defined in this session");
    }
    return value->second;
}

int64_t StorageEngine::lastval() const {
    if (g_currentSession) {
        if (g_currentSession->lastUsedSequenceOid == INVALID_OID ||
            g_currentSession->lastUsedSequenceDatabase.empty()) {
            throw DbError("55000",
                          "lastval is not yet defined in this session");
        }
        CatalogManager& catalog = const_cast<StorageEngine*>(this)
            ->catalogService().get(g_currentSession->lastUsedSequenceDatabase);
        const auto relation = catalog.getClass(
            g_currentSession->lastUsedSequenceOid);
        const auto value = g_currentSession->sequenceLastValuesByOid.find(
            g_currentSession->lastUsedSequenceOid);
        if (!relation || relation->relkind != 'S' ||
            value == g_currentSession->sequenceLastValuesByOid.end()) {
            throw DbError("55000",
                          "lastval is not yet defined in this session");
        }
        if (relation->relpersistence == 't') {
            noteTemporaryObjectAccess(g_currentSession->lastUsedSequenceDatabase);
        }
        return value->second;
    }
    if (!transactionContext().lastvalDefined) {
        throw DbError("55000", "lastval is not yet defined in this session");
    }
    return transactionContext().lastvalValue;
}

int64_t StorageEngine::setval(const std::string& dbname,
                               const std::string& seqname,
                               int64_t value, bool isCalled) {
    const ResolvedSequenceReference resolved =
        resolveSequenceReference(*this, dbname, seqname);
    if (resolved.persistence == 't') noteTemporaryObjectAccess(dbname);
    if (transactionContext().inTransaction &&
        transactionContext().readOnly && resolved.persistence != 't') {
        throw DbError("25006",
                      "cannot execute setval() in a read-only transaction");
    }
    const auto path = sequencePath(dbname, resolved.storageName);
    std::lock_guard<std::mutex> lock(g_sequenceMutex);
    dbms::SequenceInfo info;
    int64_t nextValue, lastAllocated;
    std::string generation;
    if (!readSequenceFile(path, info, nextValue, lastAllocated, nullptr, &generation)) {
        throwSequenceReadError(path, resolved.displayName);
    }
    if (value < info.minValue || value > info.maxValue) {
        throw DbError(
            "22003", "setval: value " + std::to_string(value) +
                         " is out of bounds for sequence \"" +
                         resolved.displayName + "\"");
    }
    bool exhausted = false;
    if (isCalled) {
        int64_t advanced = 0;
        const bool representable = checkedAdd(value, info.increment, advanced);
        const bool outside = representable &&
            ((info.increment > 0 && advanced > info.maxValue) ||
             (info.increment < 0 && advanced < info.minValue));
        if (!representable || outside) {
            if (info.cycle) {
                nextValue = info.increment > 0
                    ? info.minValue : info.maxValue;
            } else {
                nextValue = value;
                exhausted = true;
            }
        } else {
            nextValue = advanced;
        }
    } else {
        nextValue = value;
    }
    sequencePredecessor(nextValue, info.increment, lastAllocated);
    const SequenceCallState callState{value, isCalled, true};
    if (!(generation.empty()
            ? writeSequenceFile(path, info, nextValue, lastAllocated, exhausted, {}, &callState)
            : writeSequenceRuntime(path, generation, nextValue, lastAllocated, exhausted, &callState))) {
        throw DbError("58030",
                      "could not write sequence \"" +
                          resolved.displayName + "\"");
    }
    if (isCalled) {
        if (g_currentSession && resolved.oid != INVALID_OID) {
            g_currentSession->sequenceLastValuesByOid[resolved.oid] = value;
            g_currentSession->sequenceLastValues[resolved.storageName] = value;
        } else {
            transactionContext().sequenceLastValues[
                fallbackSequenceStateKey(dbname, resolved.storageName)] = value;
            if (transactionContext().lastvalDefined &&
                transactionContext().lastvalDb == dbname &&
                transactionContext().lastvalSeq == resolved.storageName) {
                transactionContext().lastvalValue = value;
            }
        }
    }
    return value;
}

bool StorageEngine::sequenceExists(const std::string& dbname,
                                    const std::string& seqname) const {
    if (!validSequenceName(seqname)) return false;
    return std::filesystem::exists(sequencePath(dbname, seqname));
}

std::vector<std::string> StorageEngine::getSequenceNames(const std::string& dbname) const {
    std::vector<std::string> names;
    auto dir = dbPath(dbname);
    if (!std::filesystem::exists(dir)) return names;
    for (const auto& entry : std::filesystem::directory_iterator(dir)) {
        if (entry.is_regular_file()) {
            std::string fname = entry.path().filename().string();
            if (fname.rfind("seqv2..", 0) == 0 &&
                fname.size() > 13 &&
                fname.compare(fname.size() - 6, 6, ".seqv2") == 0) {
                names.push_back(fname.substr(0, fname.size() - 6));
                continue;
            }
            if (fname.size() > 4 && fname.substr(fname.size() - 4) == ".seq") {
                // Exclude table auto-increment sequences (tablename.seq)
                // Keep only sequences that don't match a table name
                std::string tname = fname.substr(0, fname.size() - 4);
                if (!std::filesystem::exists(schemaPath(dbname, tname))) {
                    names.push_back(tname);
                }
            }
        }
    }
    return names;
}

std::shared_ptr<const TableSchema> StorageEngine::getCachedSchema(
    const std::string& dbname, const std::string& tablename) const {
    const std::string key = dbname + "/" + tablename;
    // Cheap freshness check: another StorageEngine instance in this process
    // may have rewritten the schema file without running our invalidation.
    std::error_code ec;
    const auto schemaFile = schemaPath(dbname, tablename);
    const auto st = std::filesystem::last_write_time(schemaFile, ec);
    const bool existsNow = !ec;
    uintmax_t schemaSize = 0;
    if (existsNow) schemaSize = std::filesystem::file_size(schemaFile, ec);

    const auto collationFile = dbPath(dbname) / ".collations";
    std::error_code collationError;
    const bool collationExists =
        std::filesystem::exists(collationFile, collationError);
    std::filesystem::file_time_type collationTime{};
    uintmax_t collationSize = 0;
    if (!collationError && collationExists) {
        collationTime = std::filesystem::last_write_time(
            collationFile, collationError);
        if (!collationError) {
            collationSize = std::filesystem::file_size(
                collationFile, collationError);
        }
    }
    std::lock_guard<std::mutex> lock(schemaCacheMutex_);
    auto it = schemaCache_.find(key);
    if (it == schemaCache_.end()) return nullptr;
    if (!existsNow || ec || collationError) {
        schemaCache_.erase(it);
        return nullptr;
    }
    // Compare modification timestamps with nanosecond precision when the
    // platform provides it; fall back to a whole-second comparison.
    const auto dur = st.time_since_epoch();
    const int64_t sec = std::chrono::duration_cast<std::chrono::seconds>(dur).count();
    const int64_t nsec = std::chrono::duration_cast<std::chrono::nanoseconds>(dur).count() % 1000000000LL;
    int64_t collationSec = -1;
    int64_t collationNsec = -1;
    if (collationExists) {
        const auto collationDuration = collationTime.time_since_epoch();
        collationSec = std::chrono::duration_cast<std::chrono::seconds>(
            collationDuration).count();
        collationNsec = std::chrono::duration_cast<std::chrono::nanoseconds>(
            collationDuration).count() % 1000000000LL;
    }
    if (it->second.mtimeSec != sec || it->second.mtimeNsec != nsec ||
        it->second.size != schemaSize ||
        it->second.collationMetadataExists != collationExists ||
        it->second.collationMtimeSec != collationSec ||
        it->second.collationMtimeNsec != collationNsec ||
        it->second.collationSize != collationSize) {
        schemaCache_.erase(it);
        return nullptr;
    }
    return it->second.schema;
}

void StorageEngine::invalidateCachedSchema(const std::string& dbname,
                                           const std::string& tablename) {
    std::lock_guard<std::mutex> lock(schemaCacheMutex_);
    schemaCache_.erase(dbname + "/" + tablename);
}

TableSchema StorageEngine::getTableSchema(const std::string& dbname,
                                            const std::string& tablename) const {
    const auto status = ensureDatabaseTransactionOwnership(dbname);
    if (status != DBStatus::OK)
        throw DbError(sqlstateForDBStatus(status), "could not acquire database transaction ownership");
    if (dbname.empty() || !validStoredIdentifier(dbname, MAX_TABLE_NAME_LEN) ||
        tablename.empty() || !validStoredRelationName(tablename)) {
        return {};
    }
    const auto withDomainIdentity = [&](TableSchema schema) {
        // domainName was never serialized by the binary schema format. Its
        // durable identity is the real pg_attribute domain OID; reconstruct
        // only this logical field from copied catalog metadata on every path,
        // including a schema cache hit, without modifying physical bytes.
        if (schema.len == 0 || !catalogService_) return schema;
        const auto domains = catalogService_->domainColumns(dbname, tablename);
        for (size_t i = 0; i < schema.len; ++i) {
            const auto domain = domains.find(schema.cols[i].dataName);
            if (domain != domains.end()) schema.cols[i].domainName = domain->second;
            if (schema.cols[i].defaultOrigin == Column::DefaultOrigin::Domain && physicalSchemaReader != this) {
                const auto ancestry = resolveDomainAncestry(dbname,schema.cols[i].domainName);
                if (ancestry.name.empty()) throw DbError("XX001","column domain default metadata is missing");
                schema.cols[i].defaultValue = ancestry.hasDefault ? ancestry.defaultValue : "";
            }
        }
        return schema;
    };
    std::optional<TableSchema> transactionSchema;
    {
        std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
        if (transactionContext().catalogSnapshot) {
            auto key = std::make_pair(dbname, tablename);
            auto it = transactionContext().catalogSnapshot->schemas.find(key);
            if (it != transactionContext().catalogSnapshot->schemas.end()) {
                transactionSchema = it->second;
            }
        }
    }
    if (transactionSchema) return withDomainIdentity(std::move(*transactionSchema));

    // Parsed-schema cache: DML reads the schema several times per row
    // (row encode, index lookups, WAL page images). Only the first read
    // pays the file open + parse. A cache hit must still populate the
    // transaction's catalog snapshot: later DDL by another engine instance
    // is masked by that snapshot for the rest of this transaction.
    if (auto cached = getCachedSchema(dbname, tablename)) {
        TableSchema result = withDomainIdentity(*cached);
        std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
        if (transactionContext().catalogSnapshot) {
            transactionContext().catalogSnapshot->schemas[std::make_pair(dbname, tablename)] = result;
        }
        return result;
    }

    std::ifstream in(schemaPath(dbname, tablename), std::ios::binary);
    TableSchema tbl = readSchema(in, tablename);
    tbl.storageParams = getStorageParams(dbname, tablename);

    if (tbl.len > 0) {
        std::string collationError;
        const DBStatus collationStatus = resolveTableCollations(
            *this, dbname, tbl, &collationError);
        if (collationStatus != DBStatus::OK) {
            std::cerr << "[catalog] cannot resolve collation for table "
                      << tablename << ": " << collationError << std::endl;
            return {};
        }
    }

    // Do not cache a missing/unparsed schema (readSchema returns len == 0):
    // a CREATE TABLE that follows would be masked by the cached empty entry.
    if (tbl.len > 0) {
        std::error_code mtEc;
        const auto mtime = std::filesystem::last_write_time(
            schemaPath(dbname, tablename), mtEc);
        const uintmax_t schemaSize = std::filesystem::file_size(
            schemaPath(dbname, tablename), mtEc);
        const auto collationPath = dbPath(dbname) / ".collations";
        std::error_code collationEc;
        const bool collationExists =
            std::filesystem::exists(collationPath, collationEc);
        std::filesystem::file_time_type collationMtime{};
        uintmax_t collationSize = 0;
        if (!collationEc && collationExists) {
            collationMtime = std::filesystem::last_write_time(
                collationPath, collationEc);
            if (!collationEc) {
                collationSize = std::filesystem::file_size(
                    collationPath, collationEc);
            }
        }
        std::lock_guard<std::mutex> lock(schemaCacheMutex_);
        CachedSchema entry;
        entry.schema = std::make_shared<const TableSchema>(tbl);
        if (!mtEc) {
            const auto dur = mtime.time_since_epoch();
            entry.mtimeSec = std::chrono::duration_cast<std::chrono::seconds>(dur).count();
            entry.mtimeNsec = std::chrono::duration_cast<std::chrono::nanoseconds>(dur).count() % 1000000000LL;
            entry.size = schemaSize;
        } else {
            entry.mtimeSec = -1;
            entry.mtimeNsec = -1;
        }
        if (!collationEc) {
            entry.collationMetadataExists = collationExists;
            entry.collationSize = collationSize;
            if (collationExists) {
                const auto duration = collationMtime.time_since_epoch();
                entry.collationMtimeSec =
                    std::chrono::duration_cast<std::chrono::seconds>(
                        duration).count();
                entry.collationMtimeNsec =
                    std::chrono::duration_cast<std::chrono::nanoseconds>(
                        duration).count() % 1000000000LL;
            }
        }
        schemaCache_[dbname + "/" + tablename] = std::move(entry);
    }

    tbl = withDomainIdentity(std::move(tbl));
    {
        std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
        if (transactionContext().catalogSnapshot) {
            transactionContext().catalogSnapshot->schemas[std::make_pair(dbname, tablename)] = tbl;
        }
    }
    return tbl;
}

int64_t StorageEngine::parseInt(const std::string& s) {
    if (s.empty() || s.length() > 20) return INF;
    const char* begin = s.data();
    const char* end = begin + s.size();
    if (*begin == '+') {
        ++begin;
        if (begin == end) return INF;
    }
    int64_t value = 0;
    const auto parsed = std::from_chars(begin, end, value, 10);
    // This legacy API cannot distinguish INT64_MIN from a parsing failure.
    // Full-range consumers use parseStoredInteger and the tuple NULL bitmap.
    if (parsed.ec != std::errc{} || parsed.ptr != end || value == INF) {
        return INF;
    }
    return value;
}

static bool integerValueFitsColumn(const Column& column, int64_t value) {
    if (column.dsize == 0 || column.dsize > sizeof(int64_t)) return false;
    if (column.isUnsigned) {
        if (value < 0) return false;
        if (column.dsize == sizeof(int64_t)) return true;
        const unsigned bits = static_cast<unsigned>(column.dsize * 8);
        const uint64_t maximum = (uint64_t{1} << bits) - 1;
        return static_cast<uint64_t>(value) <= maximum;
    }
    if (column.dsize == sizeof(int64_t)) return true;
    const unsigned bits = static_cast<unsigned>(column.dsize * 8);
    const int64_t minimum = -(int64_t{1} << (bits - 1));
    const int64_t maximum = (int64_t{1} << (bits - 1)) - 1;
    return value >= minimum && value <= maximum;
}

bool StorageEngine::stringToBuffer(const std::string& src, char* dst, size_t len) {
    if (src.length() > len) return false;
    std::memset(dst, 0, len);
    std::memcpy(dst, src.data(), src.length());
    return true;
}

StorageEngine::PredicateTruth StorageEngine::compareValues(
    const Column& col, const std::string& left, bool leftIsNull,
    const std::string& right, bool rightIsNull, const std::string& op) {
    if (!storedPatternOperator(op).empty()) {
        Condition pattern;
        pattern.op = op; pattern.decodedLiteralRhs = true;
        return storedPatternTruth(col,left,leftIsNull,right,rightIsNull,pattern);
    }
    if (leftIsNull || rightIsNull) return PredicateTruth::Unknown;

    auto fromCompare = [&](int cmp) -> PredicateTruth {
        bool result = false;
        if (op == "=") result = cmp == 0;
        else if (op == "!=" || op == "<>") result = cmp != 0;
        else if (op == "<") result = cmp < 0;
        else if (op == ">") result = cmp > 0;
        else if (op == "<=") result = cmp <= 0;
        else if (op == ">=") result = cmp >= 0;
        else return PredicateTruth::Unknown;
        return result ? PredicateTruth::True : PredicateTruth::False;
    };

    if (!col.isArray && col.dataType == "regtype") {
        const Oid l = stored_regtype_detail::rawOid(left);
        const Oid r = stored_regtype_detail::rawOid(right);
        return fromCompare((l > r) - (l < r));
    }
    if (col.dataType == "uuid") {
        UuidValue leftUuid;
        UuidValue rightUuid;
        if (!parseUuidValue(left, leftUuid) ||
            !parseUuidValue(right, rightUuid)) {
            return PredicateTruth::Unknown;
        }
        const int cmp = leftUuid == rightUuid
            ? 0 : (leftUuid < rightUuid ? -1 : 1);
        return fromCompare(cmp);
    }
    if (!col.isArray && (col.dataType=="bit" || col.dataType=="bit varying"))
        return fromCompare((left>right)-(left<right));
    if (col.dataType == "char" ||
        (col.isVariableLength && col.dataType != "numeric")) {
        const int cmp = compareTextValues(col, left, right);
        return fromCompare(cmp);
    }
    if (col.dataType == "date") {
        auto normalizeDate = [](std::string value) {
            for (char& c : value) if (c == '/' || c == '.') c = '-';
            return value;
        };
        const Date l(normalizeDate(left).c_str());
        const Date r(normalizeDate(right).c_str());
        if (!l.year || !r.year) return PredicateTruth::Unknown;
        return fromCompare(l < r ? -1 : (r < l ? 1 : 0));
    }
    if (col.storageCodec == Column::StorageCodec::TemporalMicros) {
        std::string canonicalLeft, canonicalRight;
        if (!normalizeTemporalColumn(col, left, canonicalLeft, false) ||
            !normalizeTemporalColumn(col, right, canonicalRight, false))
            return PredicateTruth::Unknown;
        const auto l = temporalColumnMicros(col, canonicalLeft);
        const auto r = temporalColumnMicros(col, canonicalRight);
        if (!l || !r) return PredicateTruth::Unknown;
        return fromCompare(*l < *r ? -1 : (*r < *l ? 1 : 0));
    }
    if (col.dataType == "timestamp" || col.dataType == "timestamptz" ||
        col.dataType == "datetime") {
        const int64_t l = parseTimestampToSeconds(left);
        const int64_t r = parseTimestampToSeconds(right);
        if (l == 0 && r == 0 && left != right) return PredicateTruth::Unknown;
        return fromCompare(l < r ? -1 : (r < l ? 1 : 0));
    }
    if (col.dataType == "time") {
        const int32_t l = parseTimeToSeconds(left);
        const int32_t r = parseTimeToSeconds(right);
        if (l < 0 || r < 0) return PredicateTruth::Unknown;
        return fromCompare(l < r ? -1 : (r < l ? 1 : 0));
    }
    if (col.dataType == "numeric") {
        try {
            const Numeric l(left);
            const Numeric r(right);
            return fromCompare(l < r ? -1 : (r < l ? 1 : 0));
        } catch (...) {
            return PredicateTruth::Unknown;
        }
    }
    if (col.dataType == "money") {
        int64_t l = 0;
        int64_t r = 0;
        if (!parseMoneyLiteral(left, l) || !parseMoneyLiteral(right, r))
            return PredicateTruth::Unknown;
        return fromCompare(l < r ? -1 : (r < l ? 1 : 0));
    }
    if (col.dataType == "float" || col.dataType == "double" ||
        col.dataType == "decimal") {
        double l = 0.0;
        double r = 0.0;
        if (!parseDoubleLiteral(left, l) ||
            !parseDoubleLiteral(right, r)) {
            return PredicateTruth::Unknown;
        }
        return fromCompare(compareFloatingValues(l, r));
    }
    if (col.dataType == "boolean") {
        const auto l = parsePostgresBoolean(left);
        const auto r = parsePostgresBoolean(right);
        if (!l || !r) return PredicateTruth::Unknown;
        return fromCompare(*l < *r ? -1 : (*r < *l ? 1 : 0));
    }

    // Integral types are stored in the same canonical textual form.  Unlike
    // parseInt(), stoll accepts the signed values supported by SQL literals.
    try {
        size_t lp = 0, rp = 0;
        const int64_t l = std::stoll(left, &lp);
        const int64_t r = std::stoll(right, &rp);
        if (lp != left.size() || rp != right.size()) return PredicateTruth::Unknown;
        return fromCompare(l < r ? -1 : (r < l ? 1 : 0));
    } catch (...) {
        return PredicateTruth::Unknown;
    }
}

// ========================================================================
// Helper: evaluate a single condition against a row buffer (page-based)
// ========================================================================
static std::optional<std::string> decodeBitPredicateLiteral(const std::string& raw) {
    const auto text = trim(raw);
    if (text.size() < 3 || text[1] != '\'' || text.back() != '\'' ||
        (text.front() != 'B' && text.front() != 'b' &&
         text.front() != 'X' && text.front() != 'x')) return {};
    SQLParser parser;
    auto parsed = parser.parse("SELECT " + text);
    const auto* select = parsed.success ? dynamic_cast<const SelectStmt*>(parsed.stmt.get()) : nullptr;
    const auto* literal = select && select->selectList.size() == 1
        ? dynamic_cast<const LiteralExpr*>(select->selectList.front().expr.get()) : nullptr;
    if (!literal) throw DbError("42601", "invalid bit string predicate literal");
    return ExprEvaluator{}.eval(literal,{}).value;
}

static std::string decodeSqlLiteral(std::string value, bool decodeBitLiteral = false) {
    if (decodeBitLiteral)
        if (const auto bits = decodeBitPredicateLiteral(value)) return *bits;
    if (value.size() < 2 || value.front() != '\'' || value.back() != '\'')
        return value;
    std::string decoded;
    decoded.reserve(value.size() - 2);
    for (size_t i = 1; i + 1 < value.size(); ++i) {
        decoded.push_back(value[i]);
        if (value[i] == '\'' && i + 2 < value.size() && value[i + 1] == '\'')
            ++i;
    }
    return decoded;
}

static std::string applyScalarFunc(const StorageEngine::SelectExpr& expr,
                                    const std::string& rowBuffer,
                                    const TableSchema& tbl,
                                    StorageEngine* engine,
                                    const std::string& dbname,
                                    std::optional<bool>* knownNull = nullptr,
                                    std::optional<ExprValue>* owningValue = nullptr,
                                    const DatumMetadataContext* datumMetadata = nullptr,
                                    DatumTypePtr* owningDeclaration = nullptr);

static bool containsBetweenExpression(const Expr* expression) {
    if (!expression || expression->preparedSubquery) return false;
    if (const auto* call = dynamic_cast<const FunctionCallExpr*>(expression)) {
        const auto name = SQLParser::toLower(call->funcName);
        if (call->schema.empty() && call->args.size() == 3 &&
            (name == "between" || name == "not between")) return true;
        for (const auto& argument : call->args)
            if (containsBetweenExpression(argument.get())) return true;
        for (const auto& argument : call->namedArgs)
            if (containsBetweenExpression(argument.value.get())) return true;
    } else if (const auto* binary = dynamic_cast<const BinaryOpExpr*>(expression)) {
        return containsBetweenExpression(binary->left.get()) ||
               (binary->op != "::" && containsBetweenExpression(binary->right.get()));
    } else if (const auto* unary = dynamic_cast<const UnaryOpExpr*>(expression)) {
        return containsBetweenExpression(unary->operand.get());
    } else if (const auto* cast = dynamic_cast<const CastExpr*>(expression)) {
        return containsBetweenExpression(cast->operand.get());
    } else if (const auto* conditional = dynamic_cast<const CaseExpr*>(expression)) {
        if (containsBetweenExpression(conditional->switchExpr.get()) ||
            containsBetweenExpression(conditional->elseExpr.get())) return true;
        for (const auto& arm : conditional->whenClauses)
            if (containsBetweenExpression(arm.first.get()) || containsBetweenExpression(arm.second.get())) return true;
    } else if (const auto* array = dynamic_cast<const ArrayExpr*>(expression)) {
        for (const auto& element : array->elements)
            if (containsBetweenExpression(element.get())) return true;
    } else if (const auto* row = dynamic_cast<const RowExpr*>(expression)) {
        for (const auto& element : row->elements)
            if (containsBetweenExpression(element.get())) return true;
    }
    return false;
}
bool StorageEngine::evalConditionOnRow(const Condition& cond,
                                      const std::string& rowBuffer,
                                      const TableSchema& tbl,
                                      const std::vector<bool>& nulls) {
    if (nulls.size() != tbl.len)
        throw DbError("XX000", "materialized predicate NULL bitmap width mismatch");
    struct Binding {
        const TableSchema* schema;
        const std::vector<bool>* bitmap;
        ~Binding() {
            g_bufferedConditionSchema = schema;
            g_bufferedConditionNulls = bitmap;
        }
    } binding{g_bufferedConditionSchema, g_bufferedConditionNulls};
    g_bufferedConditionSchema = &tbl;
    g_bufferedConditionNulls = &nulls;
    return evalConditionOnRow(cond, rowBuffer, tbl);
}

bool StorageEngine::evalConditionOnRow(const Condition& cond,
                                        const std::string& rowBuffer, const TableSchema& tbl) {
    return evalConditionOnRowWithSyntax(cond, rowBuffer, tbl, nullptr);
}

bool StorageEngine::evalConditionOnRowWithSyntax(const Condition& cond,
    const std::string& rowBuffer, const TableSchema& tbl, LocalExpressionSyntax* syntax) {
    if (cond.colName == "__true__") return true;
    if (cond.colName == "__false__") return false;

    StorageEngine* valueEngine = nullptr;
    std::string valueDb;
    const bool buffered = g_bufferedConditionSchema == &tbl && g_bufferedConditionNulls;
    if (g_condNullEngine && tbl.tablename == g_condNullTable) {
        valueEngine = const_cast<StorageEngine*>(g_condNullEngine);
        valueDb = g_condNullDb;
    } else if (g_nullRowEngine && tbl.tablename == g_nullRowTable) {
        valueEngine = const_cast<StorageEngine*>(g_nullRowEngine);
        valueDb = g_nullRowDb;
    }

    if (cond.op.rfind("typedrhs ", 0) == 0) {
        const Column* column = nullptr;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == cond.colName) {
                column = &tbl.cols[i];
                break;
            }
        }
        bool numericColumn = column && !column->isArray &&
            (isIntegerStorageType(column->dataType) ||
             column->dataType == "numeric" || column->dataType == "decimal" ||
             column->dataType == "float" || column->dataType == "double");
        if (!column && cond.colName.find('(') != std::string::npos) {
            // A scalar result has a declared type too. Disambiguate API
            // arithmetic-looking data without evaluating a volatile routine.
            const auto type = ExprHelper::canonicalResultTypeName(
                ExprHelper::inferResultType(cond.colName, buildTypeHints(tbl),
                                           valueDb, valueEngine));
            numericColumn = type == "smallint" || type == "integer" ||
                type == "bigint" || type == "numeric" || type == "real" ||
                type == "double precision";
        }
        Condition bound = cond;
        const std::string comparison = cond.op.substr(9);
        const bool referenceColumn=column && !column->isArray && column->dataType=="regtype";
        if (!numericColumn && !referenceColumn && (column || cond.colName.find('(') != std::string::npos)) {
            // Compact API values have historically been decoded literals.
            // Text "1+2" and date "2024-01-01" must not become arithmetic.
            bound.op = comparison;
            bound.value = decodeSqlLiteral(cond.value);
            bound.decodedLiteralRhs = true;
        } else {
            std::string left = cond.colName;
            if (column) {
                left = "\"";
                for (const char ch : cond.colName) {
                    if (ch == '"') left += '"';
                    left += ch;
                }
                left += '"';
            }
            bound.op = "typedexpr";
            bound.value = left + " " + comparison + " " + cond.value;
            bound.colName.clear();
        }
        return evalConditionOnRow(bound, rowBuffer, tbl);
    }

    // Compact execution conditions put the operator first
    // ("=UPPER(name) ALICE").  Preserve that representation for index
    // matching, but route a function-shaped left operand through the same
    // scalar evaluator used by infix predicates during a heap fallback.
    if (cond.op != "scalarexpr" &&
        cond.colName.find('(') != std::string::npos) {
        Condition scalarCondition = cond;
        scalarCondition.op = "scalarexpr";
        scalarCondition.colName = cond.colName;
        std::string right = cond.value;
        if (cond.decodedLiteralRhs) {
            // Re-encode only a proven API datum, not an arbitrary SQL name.
            // Preserve quotes, empty text and the text NULL as literal data.
            right = "'";
            for (const char ch : cond.value) {
                if (ch == '\'') right += '\'';
                right += ch;
            }
            right += '\'';
        }
        const auto pattern = storedPatternOperator(cond.op);
        std::string operation = cond.op;
        if (!pattern.empty()) {
            operation = pattern == "similar" ? "SIMILAR TO" :
                pattern == "notsimilar" ? "NOT SIMILAR TO" :
                pattern == "notlike" ? "NOT LIKE" : pattern == "notilike" ? "NOT ILIKE" : pattern;
            if (cond.patternIsNull) right = "NULL";
            if (cond.patternEscape || cond.patternEscapeIsNull || !cond.patternEscapeColumn.empty()) {
                right += " ESCAPE ";
                if (cond.patternEscapeIsNull) right += "NULL";
                else if (!cond.patternEscapeColumn.empty()) right += cond.patternEscapeColumn;
                else {
                    right += "'";
                    for (char ch : *cond.patternEscape) { right += ch; if (ch=='\'') right += ch; }
                    right += "'";
                }
            }
        }
        scalarCondition.value = cond.op == "isnull" ? "IS NULL" :
            cond.op == "isnotnull" ? "IS NOT NULL" : operation + " " + right;
        return evalConditionOnRow(scalarCondition, rowBuffer, tbl);
    }

    const auto extractValue = [&](size_t columnIndex,
                                  bool* valueIsNull = nullptr) {
        if (buffered && valueIsNull)
            *valueIsNull = columnIndex < g_bufferedConditionNulls->size() &&
                           (*g_bufferedConditionNulls)[columnIndex];
        return valueEngine
            ? valueEngine->extractColumnValue(
                  rowBuffer, tbl, columnIndex, valueDb, true, valueIsNull)
            : extractColumnValueStatic(rowBuffer, tbl, columnIndex);
    };

    if (cond.op == "typedexpr") {
        std::map<std::string, std::string> rowValues;
        std::map<std::string, std::string> collations;
        std::set<std::string> nullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool isNull = false;
            std::string value = extractValue(i, &isNull);
            if (!buffered && !valueEngine && !tbl.cols[i].isVariableLength &&
                tbl.cols[i].isNull && value.empty()) isNull = true;
            rowValues[tbl.cols[i].dataName] = std::move(value);
            collations[tbl.cols[i].dataName]=tbl.cols[i].resolvedCollation.empty()
                ? tbl.cols[i].collation : tbl.cols[i].resolvedCollation;
            if (isNull) nullColumns.insert(tbl.cols[i].dataName);
        }
        const auto hints=buildTypeHints(tbl);
        auto evaluate=[&](const std::string& sql) {
            return syntax ? ExprHelper::evalStringWithNullsSyntax(*syntax,sql,rowValues,nullColumns,hints,valueDb,"",valueEngine,collations)
                : ExprHelper::evalStringWithNulls(sql,rowValues,nullColumns,hints,valueDb,"",valueEngine,collations);
        };
        SQLParser parser;const std::string source="SELECT "+cond.value;
        auto parsed=syntax?syntax->parse(source,true):parser.parseForBinding(source);
        auto* select=parsed.success?dynamic_cast<SelectStmt*>(parsed.stmt.get()):nullptr;
        ExprEvalResult evaluated;
        const auto* root=select && select->selectList.size()==1 && !select->fromClause
            ?select->selectList.front().expr.get():nullptr;
        if(root && containsNullWhereComparison(root)) {
            // Admit the entire original AST before reducing execution demand.
            // No routine, parameter or row value is evaluated to infer a type.
            validateNullWhereColumns(root,tbl);
            ExprHelper::prepareArrayTypes(select->selectList.front().expr.get(),hints,valueDb,valueEngine);
            std::function<ExprEvalResult(const Expr*)> qualify=[&](const Expr* node)->ExprEvalResult {
                if(nullWhereComparison(node)) {
                    ExprEvalResult result;result.ok=true;result.value="false";result.typeName="boolean";return result;
                }
                const auto* binary=dynamic_cast<const BinaryOpExpr*>(node);
                if(binary && (binary->op=="AND" || binary->op=="OR") && containsNullWhereComparison(node)) {
                    auto left=qualify(binary->left.get());if(!left.ok) return left;
                    const bool truth=!left.isNull && ExprValue("boolean",left.value).asBool();
                    if((binary->op=="AND" && !truth) || (binary->op=="OR" && truth)) return left;
                    return qualify(binary->right.get());
                }
                std::function<std::pair<size_t,size_t>(const Expr*)> interval=[&](const Expr* value) {
                    if(value->sourceBegin<value->sourceEnd && value->sourceEnd<=source.size())
                        return std::make_pair(value->sourceBegin,value->sourceEnd);
                    if(const auto* comparison=dynamic_cast<const BinaryOpExpr*>(value)) {
                        const auto left=interval(comparison->left.get()),right=interval(comparison->right.get());
                        if(left.first<left.second && right.first<right.second)
                            return std::make_pair(std::min(left.first,right.first),std::max(left.second,right.second));
                    }
                    return std::make_pair(size_t(0),size_t(0));
                };
                const auto owned=interval(node);
                if(owned.first<owned.second) return evaluate(source.substr(owned.first,owned.second-owned.first));
                // Unsupported source ownership stays on the unchanged evaluator.
                return evaluate(cond.value);
            };
            evaluated=qualify(root);
        } else evaluated=evaluate(cond.value);
        if (!evaluated.ok && !evaluated.sqlState.empty()) throw DbError(evaluated.sqlState,evaluated.error);
        if (!evaluated.ok)
            throw std::runtime_error(evaluated.error.empty()
                ? "failed to evaluate typed predicate" : evaluated.error);
        if (evaluated.isNull) return false;
        if (evaluated.typeName != "boolean")
            throw std::runtime_error(
                "argument of WHERE must be type boolean (SQLSTATE 42804)");
        return ExprValue("boolean", evaluated.value, false).asBool();
    }

    // Function-left predicate ("length(v) = 0" captured by parseConditions
    // as op="scalarexpr"): evaluate the function on this row and compare.
    // A NULL result is Unknown in three-valued logic, so the row drops.
    if (cond.op == "scalarexpr") {
        // Scalar routines have their own strict/non-strict NULL contract.
        // Evaluate the complete typed predicate instead of the old manual
        // argument splitter/all-column-NULL gate (which also folded quotes).
        Condition typed = cond;
        typed.op = "typedexpr";
        typed.value = cond.colName + " " + cond.value;
        typed.colName.clear();
        return evalConditionOnRowWithSyntax(typed, rowBuffer, tbl, syntax);
    }
    // Handle OVERLAPS operator: overlaps:s1,e1,s2,e2
    if (cond.op == "overlaps") {
        std::string expr = cond.colName;
        if (!expr.empty() && expr.front() == ':') expr = expr.substr(1);
        std::vector<std::string> parts;
        std::stringstream ss(expr);
        std::string part;
        while (std::getline(ss, part, ',')) {
            // trim whitespace around each part
            size_t a = 0, b = part.size();
            while (a < b && std::isspace(static_cast<unsigned char>(part[a]))) ++a;
            while (b > a && std::isspace(static_cast<unsigned char>(part[b - 1]))) --b;
            if (a < b) parts.push_back(part.substr(a, b - a));
        }
        if (parts.size() == 4) {
            auto findCol = [&](const std::string& name) -> size_t {
                for (size_t i = 0; i < tbl.len; ++i)
                    if (tbl.cols[i].dataName == name) return i;
                return tbl.len;
            };
            size_t s1i = findCol(parts[0]);
            size_t e1i = findCol(parts[1]);
            size_t s2i = findCol(parts[2]);
            size_t e2i = findCol(parts[3]);
            if (s1i < tbl.len && e1i < tbl.len && s2i < tbl.len && e2i < tbl.len) {
                std::string s1 = extractValue(s1i);
                std::string e1 = extractValue(e1i);
                std::string s2 = extractValue(s2i);
                std::string e2 = extractValue(e2i);
                return (s1 < e2) && (s2 < e1);
            }
        }
        return false;
    }

    size_t ci = 0;
    for (; ci < tbl.len && tbl.cols[ci].dataName != cond.colName; ++ci) {}
    if (ci >= tbl.len) return false;

    bool computedNull = false;
    std::string val = extractValue(ci, &computedNull);
    const Column& col = tbl.cols[ci];
    // Stored-NULL truth: prefer the bound scan row null bitmap (see
    // NullRowBinding), which distinguishes NULL from a stored empty string.
    bool physNull = buffered ? (*g_bufferedConditionNulls)[ci] : computedNull;
    if (!buffered && col.generatedKind != 'v' &&
        g_condNullEngine && g_condNullRid >= 0 &&
        tbl.tablename == g_condNullTable &&
        detail::storedRowColumnIsNull(*g_condNullEngine, g_condNullDb,
            tbl.tablename, tbl, g_condNullRid, ci)) {
        physNull = true;
    }
    if (!storedPatternOperator(cond.op).empty()) {
        Condition pattern = bindStoredPatternTypes(tbl,cond);
        std::string right = cond.value;
        bool rightNull = cond.patternIsNull;
        if (!cond.decodedLiteralRhs && !cond.patternIsNull) {
            for (size_t i=0;i<tbl.len;++i) if (tbl.cols[i].dataName == cond.value) {
                right = extractValue(i,&rightNull);
                if (buffered) rightNull = (*g_bufferedConditionNulls)[i];
                pattern.patternType = tbl.cols[i].isArray ? tbl.cols[i].dataType+"[]" : tbl.cols[i].dataType;
                break;
            }
        }
        if (!cond.patternEscapeColumn.empty()) {
            bool found = false;
            for (size_t i=0;i<tbl.len;++i) if (tbl.cols[i].dataName == cond.patternEscapeColumn) {
                bool escapeNull = false;
                pattern.patternEscape = extractValue(i,&escapeNull);
                pattern.patternEscapeIsNull = buffered ? (*g_bufferedConditionNulls)[i] : escapeNull;
                pattern.patternEscapeType = tbl.cols[i].isArray ? tbl.cols[i].dataType+"[]" : tbl.cols[i].dataType;
                found = true; break;
            }
            if (!found) throw DbError("42703", "pattern escape column does not exist");
        }
        return storedPatternTruth(col,val,physNull,right,rightNull,pattern) == PredicateTruth::True;
    }
    if (cond.op == "isnull") return physNull;
    if (cond.op == "isnotnull") return !physNull;
    if (nullScalarComparison(cond)) return false;
    if (cond.patternType=="bit")
        (void)ExprEvaluator::resolveComparison("=",col.dataType+(col.isArray?"[]":""),"bit");
    if (physNull) {
        // NULL never satisfies scalar comparisons (three-valued logic).
        return false;
    }
    // Column-vs-column predicate ("a = b", produced by the IS [NOT]
    // DISTINCT FROM rewrite): resolve the right side against this row too;
    // a physically-NULL right column makes the comparison UNKNOWN.
    if (!cond.decodedLiteralRhs) {
        size_t rci = 0;
        for (; rci < tbl.len && tbl.cols[rci].dataName != cond.value; ++rci) {}
        if (rci < tbl.len) {
            bool rNull = buffered && (*g_bufferedConditionNulls)[rci];
            if (!buffered && tbl.cols[rci].generatedKind != 'v' &&
                g_condNullEngine && g_condNullRid >= 0 &&
                tbl.tablename == g_condNullTable &&
                detail::storedRowColumnIsNull(*g_condNullEngine, g_condNullDb,
                    tbl.tablename, tbl, g_condNullRid, rci)) {
                rNull = true;
            }
            if (rNull) return false;
            bool rightComputedNull = false;
            std::string rval = extractValue(rci, &rightComputedNull);
            if (rightComputedNull) {
                return false;
            }
            if (!col.isArray && !tbl.cols[rci].isArray &&
                (col.dataType=="bit" || col.dataType=="bit varying") &&
                (tbl.cols[rci].dataType=="bit" || tbl.cols[rci].dataType=="bit varying"))
                return compareValues(col,val,false,rval,false,cond.op)==PredicateTruth::True;
            bool num = true;
            double lv = 0, rv = 0;
            try { lv = std::stod(val); rv = std::stod(rval); } catch (...) { num = false; }
            auto eqOk = [&]() { return num ? lv == rv : val == rval; };
            auto ltOk = [&]() { return num ? lv < rv : val < rval; };
            auto gtOk = [&]() { return num ? lv > rv : val > rval; };
            const std::string& op = cond.op;
            if (op == "=") return eqOk();
            if (op == "!=" || op == "<>") return !eqOk();
            if (op == "<") return ltOk();
            if (op == ">") return gtOk();
            if (op == "<=") return !gtOk();
            if (op == ">=") return !ltOk();
            return false;
        }
    }
    if (!col.isArray && col.dataType=="regtype" &&
        (cond.op=="=" || cond.op=="<>" || cond.op=="!=" || cond.op=="<" ||
         cond.op==">" || cond.op=="<=" || cond.op==">=")) {
        std::string right=cond.referenceInputOid?std::to_string(*cond.referenceInputOid):
            decodeSqlLiteral(cond.value);
        const bool numeric=!right.empty() && std::all_of(right.begin(),right.end(),
            [](unsigned char ch){return ch>='0' && ch<='9';});
        if(!numeric) {
            if(!valueEngine || valueDb.empty())
                throw DbError("0A000","regtype name predicate requires its actual database context");
            const auto catalog=regtype_detail::metadata(*valueEngine,valueDb);
            right=stored_regtype_detail::input(right,false,catalog,currentSession());
        }
        return compareValues(col,val,false,right,false,cond.op)==PredicateTruth::True;
    }
    if (cond.op == "in" || cond.op == "notin") {
        if (cond.patternType=="bit") {
            ExprEvaluator evaluator;
            bool hit=false,sawNull=false;
            for (const auto& token:SQLParser::tokenize(cond.value)) {
                SQLParser parser;
                auto parsed=parser.parse("SELECT "+token);
                const auto* select=parsed.success?dynamic_cast<const SelectStmt*>(parsed.stmt.get()):nullptr;
                if(!select || select->selectList.size()!=1)throw DbError("42601","invalid BIT list operand");
                const auto* operand=select->selectList.front().expr.get();
                auto candidate=evaluator.eval(operand,{});
                candidate.typeName=ExprHelper::inferParsedInputType(operand,{});
                const auto binding=ExprEvaluator::resolveComparison("=",col.dataType,candidate.typeName);
                if(candidate.isNull){sawNull=true;continue;}
                if(evaluator.comparePrepared(binding,ExprValue(col.dataType,val),candidate).asBool()){hit=true;break;}
            }
            return cond.op=="in"?hit:!hit&&!sawNull;
        }
        // cond.value = space-joined literals (built by modifyLogic)
        if (val.empty()) return false;   // empty never matches IN literals
        bool hit = false;
        bool sawNull = false;
        std::istringstream iss(cond.value);
        std::string tok;
        while (iss >> tok) {
            // A NULL list element makes every non-matching comparison
            // UNKNOWN; NOT IN over (NULL, x) is therefore UNKNOWN (row
            // drops) unless a real element matches first (PG semantics).
            {
                std::string tl;
                for (char ch : tok) tl += static_cast<char>(tolower(static_cast<unsigned char>(ch)));
                if (tl == "null" || tl == "nil") { sawNull = true; continue; }
            }
            StorageEngine::Condition eq;
            eq.op = "=";
            eq.colName = cond.colName;
            eq.value = tok;
            eq.decodedLiteralRhs = cond.decodedLiteralRhs;
            if (evalConditionOnRow(eq, rowBuffer, tbl)) { hit = true; break; }
        }
        if (cond.op == "in") return hit;
        if (sawNull && !hit) return false;  // UNKNOWN
        return !hit;
    }

    if ((cond.op=="between" || cond.op=="notbetween") && cond.patternType=="bit") {
        const auto tokens=SQLParser::tokenize(cond.value);
        if(tokens.size()!=2)throw DbError("42601","BIT BETWEEN requires two operands");
        ExprEvaluator evaluator;
        bool inRange=true,sawNull=false;
        for(size_t i=0;i<2;++i) {
            SQLParser parser;auto parsed=parser.parse("SELECT "+tokens[i]);
            const auto* select=parsed.success?dynamic_cast<const SelectStmt*>(parsed.stmt.get()):nullptr;
            if(!select || select->selectList.size()!=1)throw DbError("42601","invalid BIT BETWEEN operand");
            const auto* operand=select->selectList.front().expr.get();
            auto candidate=evaluator.eval(operand,{});
            candidate.typeName=ExprHelper::inferParsedInputType(operand,{});
            const auto binding=ExprEvaluator::resolveComparison(i==0?">=":"<=",col.dataType,candidate.typeName);
            const auto comparison=evaluator.comparePrepared(binding,ExprValue(col.dataType,val),candidate);
            if(comparison.isNull)sawNull=true;
            else inRange=inRange&&comparison.asBool();
        }
        if(inRange&&sawNull)return false;
        return cond.op=="between"?inRange:!inRange;
    }

    // Three-valued logic: NULL yields UNKNOWN (FALSE in WHERE) and is
    // already handled above via the stored-null bitmap.  An empty extracted
    // value is a real empty string (storage distinguishes empty from NULL),
    // so comparisons proceed - including empty = empty.

    if (col.dataType == "uuid") {
        UuidValue valueUuid;
        if (!parseUuidValue(val, valueUuid)) return false;
        const auto compareUuid = [&](const std::string& candidate,
                                     int& comparison) {
            UuidValue candidateUuid;
            if (!parseUuidValue(candidate, candidateUuid)) return false;
            comparison = valueUuid == candidateUuid
                ? 0 : (valueUuid < candidateUuid ? -1 : 1);
            return true;
        };
        if (cond.op == "between" || cond.op == "notbetween") {
            const size_t separator = cond.value.find(' ');
            if (separator == std::string::npos) return false;
            int lower = 0;
            int upper = 0;
            if (!compareUuid(cond.value.substr(0, separator), lower) ||
                !compareUuid(cond.value.substr(separator + 1), upper)) {
                return false;
            }
            const bool inRange = lower >= 0 && upper <= 0;
            return cond.op == "between" ? inRange : !inRange;
        }
        int comparison = 0;
        if (!compareUuid(cond.value, comparison)) return false;
        if (cond.op == "=") return comparison == 0;
        if (cond.op == "!=" || cond.op == "<>") return comparison != 0;
        if (cond.op == "<") return comparison < 0;
        if (cond.op == ">") return comparison > 0;
        if (cond.op == "<=") return comparison <= 0;
        if (cond.op == ">=") return comparison >= 0;
        return false;
    }
    if (col.dataType == "char" ||
        (col.isVariableLength && col.dataType != "numeric")) {
        // Apply the column's collation for equality/comparison operators.
        auto scmp = [&](const std::string& a, const std::string& b) {
            return compareTextValues(col, a, b);
        };
        if (cond.op == "<"  && !(scmp(val, cond.value) < 0))     return false;
        if (cond.op == ">"  && !(scmp(val, cond.value) > 0))     return false;
        if (cond.op == "="  && scmp(val, cond.value) != 0)        return false;
        if (cond.op == "<=" && (scmp(val, cond.value) > 0))      return false;
        if (cond.op == ">=" && (scmp(val, cond.value) < 0))      return false;
        if (cond.op == "!=" && scmp(val, cond.value) == 0)        return false;
        if (cond.op == "between" || cond.op == "notbetween") {
            // cond.value = "lo hi" (space-joined by modifyLogic)
            size_t sp = cond.value.find(' ');
            if (sp != std::string::npos) {
                const std::string& lo = cond.value.substr(0, sp);
                const std::string& hi = cond.value.substr(sp + 1);
                bool inRange = scmp(val, lo) >= 0 && scmp(val, hi) <= 0;
                if (cond.op == "between" && !inRange) return false;
                if (cond.op == "notbetween" && inRange) return false;
            }
        }
        if (cond.op == "regexp" && !regexMatch(val, cond.value)) return false;
        if (cond.op == "notregexp" && regexMatch(val, cond.value)) return false;
        if (cond.op == "contains") {
            auto tokens = tokenizeText(val);
            std::string searchWord = cond.value;
            for (char& c : searchWord) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            bool found = false;
            for (const auto& tok : tokens) {
                if (tok == searchWord) { found = true; break; }
            }
            if (!found) return false;
        }
    } else if (col.dataType == "date") {
        auto normalizeDateStr = [](const std::string& s) -> std::string {
            if (s.size() < 8) return s;
            // YYYY/MM/DD or YYYY.MM.DD -> YYYY-MM-DD
            std::string r = s;
            for (char& c : r) if (c == '/' || c == '.') c = '-';
            return r;
        };
        std::string nv = normalizeDateStr(val);
        std::string nc = normalizeDateStr(cond.value);
        Date d = (nv.empty() ? Date{} : Date(nv.c_str()));
        Date v(nc.c_str());
        if (cond.op == "<"  && v.year && !(d < v))  return false;
        if (cond.op == ">"  && v.year && !(d > v))  return false;
        if (cond.op == "="  && v.year && d != v)    return false;
        if (cond.op == "<=" && v.year && (d > v))   return false;
        if (cond.op == ">=" && v.year && (d < v))   return false;
        if (cond.op == "!=" && v.year && d == v)    return false;
    } else if (col.storageCodec == Column::StorageCodec::TemporalMicros) {
        return compareValues(col, val, val.empty(), cond.value, false, cond.op) ==
            PredicateTruth::True;
    } else if (col.dataType == "timestamp" || col.dataType == "timestamptz" || col.dataType == "datetime") {
        int64_t num = val.empty() ? 0 : parseTimestampToSeconds(val);
        int64_t cmp = parseTimestampToSeconds(cond.value);
        if (cond.op == "<"  && cmp != 0 && !(num < cmp)) return false;
        if (cond.op == ">"  && cmp != 0 && !(num > cmp)) return false;
        if (cond.op == "="  && cmp != 0 && num != cmp)   return false;
        if (cond.op == "<=" && cmp != 0 && (num > cmp))  return false;
        if (cond.op == ">=" && cmp != 0 && (num < cmp))  return false;
        if (cond.op == "!=" && cmp != 0 && num == cmp)   return false;
    } else if (col.dataType == "time") {
        int32_t num = val.empty() ? -1 : parseTimeToSeconds(val);
        int32_t cmp = parseTimeToSeconds(cond.value);
        if (cond.op == "<"  && cmp >= 0 && !(num < cmp)) return false;
        if (cond.op == ">"  && cmp >= 0 && !(num > cmp)) return false;
        if (cond.op == "="  && cmp >= 0 && num != cmp)   return false;
        if (cond.op == "<=" && cmp >= 0 && (num > cmp))  return false;
        if (cond.op == ">=" && cmp >= 0 && (num < cmp))  return false;
        if (cond.op == "!=" && cmp >= 0 && num == cmp)   return false;
    } else if (col.dataType == "float") {
        float num = 0.0f, cmp = 0.0f;
        if ((!val.empty() && !parseFloatLiteral(val, num)) ||
            !parseFloatLiteral(cond.value, cmp)) {
            return false;  // Invalid comparison value → UNKNOWN → FALSE in WHERE
        }
        if (!floatingPredicateMatches(
                cond.op, compareFloatingValues(num, cmp))) return false;
    } else if (col.dataType == "numeric") {
        if (cond.op == "between" || cond.op == "notbetween") {
            // cond.value = "lo hi" (space-joined upstream).  Numeric bounds
            // previously failed here: Numeric("1.25 2.0") throws and the
            // whole comparison returned false.
            size_t sp = cond.value.find(' ');
            if (sp == std::string::npos) return false;
            try {
                Numeric lo(cond.value.substr(0, sp));
                Numeric hi(cond.value.substr(sp + 1));
                Numeric num = val.empty() ? Numeric(0) : Numeric(val);
                bool inRange = !(num < lo) && !(num > hi);
                if (cond.op == "between" && !inRange) return false;
                if (cond.op == "notbetween" && inRange) return false;
            } catch (...) {
                return false;
            }
            return true;
        }
        try {
            Numeric num = val.empty() ? Numeric(0) : Numeric(val);
            Numeric cmp(cond.value);
            if (cond.op == "isnull") return false;
            if (cond.op == "isnotnull") return true;
            if (cond.op == "<"  && !(num < cmp))  return false;
            if (cond.op == ">"  && !(num > cmp))  return false;
            if (cond.op == "="  && num != cmp)    return false;
            if (cond.op == "<=" && (num > cmp))   return false;
            if (cond.op == ">=" && (num < cmp))   return false;
            if (cond.op == "!=" && num == cmp)    return false;
        } catch (...) {
            return false;
        }
    } else if (col.dataType == "money") {
        int64_t num = 0;
        if (cond.op == "between" || cond.op == "notbetween") {
            const size_t separator = cond.value.find(' ');
            if (separator == std::string::npos) return false;
            int64_t lower = 0;
            int64_t upper = 0;
            if (!parseMoneyLiteral(val, num) ||
                !parseMoneyLiteral(cond.value.substr(0, separator), lower) ||
                !parseMoneyLiteral(cond.value.substr(separator + 1), upper))
                return false;
            const bool inRange = num >= lower && num <= upper;
            return cond.op == "between" ? inRange : !inRange;
        }
        int64_t cmp = 0;
        if (!parseMoneyLiteral(val, num) ||
            !parseMoneyLiteral(cond.value, cmp)) return false;
        if (cond.op == "<" && !(num < cmp)) return false;
        if (cond.op == ">" && !(num > cmp)) return false;
        if (cond.op == "=" && num != cmp) return false;
        if (cond.op == "<=" && !(num <= cmp)) return false;
        if (cond.op == ">=" && !(num >= cmp)) return false;
        if ((cond.op == "!=" || cond.op == "<>") && num == cmp) return false;
    } else if (col.dataType == "double" || col.dataType == "decimal") {
        double num = 0.0, cmp = 0.0;
        if (cond.op == "between" || cond.op == "notbetween") {
            size_t sp = cond.value.find(' ');
            if (sp == std::string::npos) return false;
            double lo = 0.0;
            double hi = 0.0;
            if (!parseDoubleLiteral(cond.value.substr(0, sp), lo) ||
                !parseDoubleLiteral(cond.value.substr(sp + 1), hi) ||
                (!val.empty() && !parseDoubleLiteral(val, num))) {
                return false;
            }
            bool inRange = compareFloatingValues(num, lo) >= 0 &&
                           compareFloatingValues(num, hi) <= 0;
            if (cond.op == "between" && !inRange) return false;
            if (cond.op == "notbetween" && inRange) return false;
            return true;
        }
        if ((!val.empty() && !parseDoubleLiteral(val, num)) ||
            !parseDoubleLiteral(cond.value, cmp)) {
            return false;  // Invalid comparison value → UNKNOWN → FALSE in WHERE
        }
        if (!floatingPredicateMatches(
                cond.op, compareFloatingValues(num, cmp))) return false;
    } else if (col.dataType == "boolean") {
        const auto nv = parsePostgresBoolean(val);
        const auto nc = parsePostgresBoolean(cond.value);
        if (!nv || !nc) return false;
        if (cond.op == "="  && *nv != *nc) return false;
        if (cond.op == "!=" && *nv == *nc) return false;
    } else if (col.dataType == "point") {
        double px = 0.0, py = 0.0;
        std::string canonicalPoint;
        if (!normalizePointLiteral(val, canonicalPoint, &px, &py)) return false;
        if (cond.op == "<@") {
            // contained within circle: "cx,cy,radius"
            std::string circle = trim(cond.value);
            if (circle.size() >= 2 && circle.front() == '\'' && circle.back() == '\'')
                circle = trim(circle.substr(1, circle.size() - 2));
            const size_t firstComma = circle.find(',');
            const size_t secondComma = circle.find(',', firstComma == std::string::npos
                                                             ? 0 : firstComma + 1);
            if (firstComma == std::string::npos || secondComma == std::string::npos ||
                circle.find(',', secondComma + 1) != std::string::npos) {
                return false;
            }
            double cx = 0.0, cy = 0.0, radius = 0.0;
            if (!parseFiniteDouble(circle.substr(0, firstComma), cx) ||
                !parseFiniteDouble(
                    circle.substr(firstComma + 1, secondComma - firstComma - 1), cy) ||
                !parseFiniteDouble(circle.substr(secondComma + 1), radius) ||
                radius < 0.0) {
                return false;
            }
            if (std::hypot(px - cx, py - cy) > radius) return false;
            return true;
        }

        double cx = 0.0, cy = 0.0;
        std::string canonicalCondition;
        if (!normalizePointLiteral(cond.value, canonicalCondition, &cx, &cy)) return false;
        if (cond.op == "=") {
            if (px != cx || py != cy) return false;
        } else if (cond.op == "!=") {
            if (px == cx && py == cy) return false;
        } else if (cond.op == "<<") {
            if (!(px < cx)) return false;
        } else if (cond.op == ">>") {
            if (!(px > cx)) return false;
        } else if (cond.op == "<^") {
            if (!(py < cy)) return false;
        } else if (cond.op == ">^") {
            if (!(py > cy)) return false;
        } else {
            // Fallback to string comparison for other operators
            if (cond.op == "<"  && !(canonicalPoint < canonicalCondition)) return false;
            if (cond.op == ">"  && !(canonicalPoint > canonicalCondition)) return false;
        }
    } else if (col.dataType == "inet" || col.dataType == "cidr") {
        // Parse INET from string representation: "192.168.1.1" or "192.168.1.0/24"
        auto parseINet = [](const std::string& s) -> std::tuple<uint8_t, uint8_t, uint32_t> {
            uint8_t family = 0, prefix = 32;
            uint32_t addr = 0;
            std::string clean = s;
            if (clean.size() >= 2 && clean.front() == '\'' && clean.back() == '\'')
                clean = clean.substr(1, clean.size() - 2);
            if (clean.empty()) return {family, prefix, addr};
            size_t slash = clean.find('/');
            std::string addrPart = clean;
            if (slash != std::string::npos) {
                try { prefix = static_cast<uint8_t>(std::stoi(clean.substr(slash + 1))); }
                catch (...) { prefix = 32; }
                addrPart = clean.substr(0, slash);
            }
            int a = 0, b = 0, c = 0, d = 0;
            if (sscanf(addrPart.c_str(), "%d.%d.%d.%d", &a, &b, &c, &d) == 4) {
                family = 2;
                addr = (static_cast<uint32_t>(a) << 24) |
                       (static_cast<uint32_t>(b) << 16) |
                       (static_cast<uint32_t>(c) << 8) |
                        static_cast<uint32_t>(d);
            }
            return {family, prefix, addr};
        };
        auto [vfam, vpref, vaddr] = parseINet(val);
        auto [cfam, cpref, caddr] = parseINet(cond.value);
        if (vfam == 0 || cfam == 0) return false;
        if (cond.op == "=") {
            if (vaddr != caddr || vpref != cpref) return false;
        } else if (cond.op == "!=") {
            if (vaddr == caddr && vpref == cpref) return false;
        } else if (cond.op == "<<") {
            // subnet of: this network is contained within the given network
            // Given network must have smaller or equal prefix (be a supernet)
            if (cpref > vpref) return false;
            uint32_t mask = (cpref == 0) ? 0 : (0xFFFFFFFF << (32 - cpref));
            if ((vaddr & mask) != (caddr & mask)) return false;
        } else if (cond.op == ">>") {
            // contains: this network contains the given network
            if (vpref > cpref) return false;
            uint32_t mask = (vpref == 0) ? 0 : (0xFFFFFFFF << (32 - vpref));
            if ((vaddr & mask) != (caddr & mask)) return false;
        } else if (cond.op == "&&") {
            // overlap: two networks share any addresses
            uint32_t vmask = (vpref == 0) ? 0 : (0xFFFFFFFF << (32 - vpref));
            uint32_t cmask = (cpref == 0) ? 0 : (0xFFFFFFFF << (32 - cpref));
            uint32_t vnet = vaddr & vmask;
            uint32_t cnet = caddr & cmask;
            uint32_t vbroad = vaddr | ~vmask;
            uint32_t cbroad = caddr | ~cmask;
            if (vnet > cbroad || cnet > vbroad) return false;
        } else {
            return false;
        }
    } else {
        const auto parsedNum = parseStoredInteger(val);
        if (!parsedNum) return false;
        const int64_t num = *parsedNum;
        // BETWEEN family: cond.value = "lo hi" (space-joined upstream).
        if (cond.op == "between" || cond.op == "notbetween") {
            size_t sp = cond.value.find(' ');
            if (sp == std::string::npos) return false;
            if (isIntegerStorageType(col.dataType)) {
                try {
                    const Numeric lower(cond.value.substr(0, sp));
                    const Numeric upper(cond.value.substr(sp + 1));
                    if (!lower.isFinite() || !upper.isFinite()) return false;
                    const Numeric integer(num);
                    const bool inRange = integer >= lower && integer <= upper;
                    return cond.op == "between" ? inRange : !inRange;
                } catch (const std::invalid_argument&) {
                    return false;
                }
            }
            // Retain the legacy fallback for non-integer storage types.
            double loD = 0.0;
            double hiD = 0.0;
            if (parseDoubleLiteral(cond.value.substr(0, sp), loD) &&
                parseDoubleLiteral(cond.value.substr(sp + 1), hiD)) {
                bool inRange = static_cast<double>(num) >= loD && static_cast<double>(num) <= hiD;
                if (cond.op == "between" && !inRange) return false;
                if (cond.op == "notbetween" && inRange) return false;
                return true;
            }
            const auto lo = parseStoredInteger(cond.value.substr(0, sp));
            const auto hi = parseStoredInteger(cond.value.substr(sp + 1));
            if (!lo || !hi) return false;
            bool inRange = num >= *lo && num <= *hi;
            if (cond.op == "between" && !inRange) return false;
            if (cond.op == "notbetween" && inRange) return false;
            return true;
        }
        const auto parsedCmp = parseStoredInteger(cond.value);
        if (!parsedCmp && isIntegerStorageType(col.dataType)) {
            // SQL promotes an integer compared with a finite decimal literal
            // to an exact numeric comparison; neither truncation nor double
            // conversion preserves fractional bounds or BIGINT precision.
            try {
                const Numeric numeric(cond.value);
                if (!numeric.isFinite()) return false;
                const Numeric integer(num);
                const int comparison = integer < numeric ? -1 :
                    (integer > numeric ? 1 : 0);
                return floatingPredicateMatches(cond.op, comparison);
            } catch (const std::invalid_argument&) {
                return false;
            }
        }
        if (!parsedCmp) return false;  // Invalid comparison value → UNKNOWN → FALSE in WHERE
        const int64_t cmp = *parsedCmp;
        if (cond.op == "<"  && !(num < cmp)) return false;
        if (cond.op == ">"  && !(num > cmp)) return false;
        if (cond.op == "="  && num != cmp)   return false;
        if (cond.op == "<=" && (num > cmp))  return false;
        if (cond.op == ">=" && (num < cmp))  return false;
        if ((cond.op == "!=" || cond.op == "<>") && num == cmp) return false;
    }
    return true;
}

// ========================================================================
// Helper: build full row buffer (with MVCC header) from column values
// ========================================================================
static std::string buildRowBuffer(const TableSchema& tbl,
                                   const std::map<std::string, std::string>& values,
                                   uint64_t creatorTxnId,
                                   const std::set<size_t>* explicitNullColumns) {
    const auto columnIsNull = [&](size_t columnIndex) {
        const auto value = values.find(tbl.cols[columnIndex].dataName);
        if (value == values.end()) return true;
        if (explicitNullColumns) {
            return explicitNullColumns->count(columnIndex) != 0;
        }
        return value->second == "NULL";
    };
    bool hasNull = false;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (columnIsNull(i)) {
            hasNull = true;
            break;
        }
    }

    std::string rowBuffer = buildHeapTupleHeader(tbl, creatorTxnId, hasNull, tbl.hasVariableLength());
    if (hasNull) {
        auto* header = castHeapHeader(rowBuffer.data());
        for (size_t i = 0; i < tbl.len; ++i) {
            // An empty-string value is a real empty value (bit set); only the
            // explicit NULL state (or an omitted column) leaves the bit clear.
            if (!columnIsNull(i)) {
                setNotNull(header, static_cast<int>(i));
            }
        }
    }

    if (!tbl.hasVariableLength()) {
        rowBuffer.resize(tbl.rowSize(), '\0');
        size_t offset = dataOffset(tbl);
        for (size_t i = 0; i < tbl.len; ++i) {
            const Column& col = tbl.cols[i];
            auto it = values.find(col.dataName);
            std::string val = (it != values.end()) ? it->second : "";
            if (columnIsNull(i)) val.clear();
            if (col.dataType == "uuid") {
                (void)writeUuidStorage(val, &rowBuffer[offset], col.dsize);
            } else if (col.dataType == "char" || col.dataType == "nchar" ||
                col.dataType == "binary") {
                std::memset(&rowBuffer[offset], 0, col.dsize);
                if (!val.empty()) {
                    size_t copyLen = std::min(val.size(), col.dsize);
                    std::memcpy(&rowBuffer[offset], val.data(), copyLen);
                }
            } else if (col.dataType == "date") {
                if (val.empty()) {
                    Date d{};
                    std::memcpy(&rowBuffer[offset], &d, DATE_SIZE);
                } else {
                    Date d(val.c_str());
                    std::memcpy(&rowBuffer[offset], &d, DATE_SIZE);
                }
            } else if (col.storageCodec == Column::StorageCodec::TemporalMicros) {
                const auto parsed = val.empty() ? std::optional<int64_t>{} : temporalColumnMicros(col, val);
                if (!val.empty() && !parsed)
                    throw DbError("22007", "invalid canonical temporal storage datum");
                const int64_t num = parsed ? *parsed : (col.dataType == "time" ? -1 : INF);
                std::memcpy(&rowBuffer[offset], &num, sizeof(num));
            } else if (col.dataType == "timestamp" || col.dataType == "timestamptz" || col.dataType == "datetime") {
                int64_t num = val.empty() ? INF : parseTimestampToSeconds(val);
                std::memcpy(&rowBuffer[offset], &num, TIMESTAMP_SIZE);
            } else if (col.dataType == "time") {
                int32_t num = val.empty() ? -1 : parseTimeToSeconds(val);
                std::memcpy(&rowBuffer[offset], &num, sizeof(int32_t));
            } else if (col.dataType == "float") {
                float num = 0.0f;
                if (!val.empty()) parseFloatLiteral(val, num);
                std::memcpy(&rowBuffer[offset], &num, sizeof(float));
            } else if (col.dataType == "money") {
                int64_t minorUnits = 0;
                if (!val.empty()) (void)parseMoneyLiteral(val, minorUnits);
                std::memcpy(&rowBuffer[offset], &minorUnits,
                            sizeof(minorUnits));
            } else if (col.dataType == "double" || col.dataType == "decimal") {
                double num = 0.0;
                if (!val.empty()) parseDoubleLiteral(val, num);
                std::memcpy(&rowBuffer[offset], &num, sizeof(double));
            } else if (col.dataType == "point") {
                double x = 0.0, y = 0.0;
                if (!val.empty()) {
                    std::string canonical;
                    normalizePointLiteral(val, canonical, &x, &y);
                }
                std::memcpy(&rowBuffer[offset], &x, sizeof(double));
                std::memcpy(&rowBuffer[offset + sizeof(double)], &y, sizeof(double));
            } else if (col.dataType == "inet" || col.dataType == "cidr") {
                // Parse IPv4 dotted-quad or IPv6 (with ::) plus optional /prefix.
                uint8_t family = 0, prefix = 32;
                uint8_t addr[16] = {0};
                if (!val.empty()) {
                    parseInetAddr(val, family, prefix, addr,
                                  col.dataType == "cidr");  // validated at INSERT
                }
                rowBuffer[offset] = static_cast<char>(family);
                rowBuffer[offset + 1] = static_cast<char>(prefix);
                rowBuffer[offset + 2] = static_cast<char>(col.dataType == "cidr" ? 1 : 0);
                rowBuffer[offset + 3] = 0;  // reserved
                std::memcpy(&rowBuffer[offset + 4], addr, 16);
            } else if (col.dataType == "macaddr" || col.dataType == "macaddr8") {
                int n = (col.dataType == "macaddr8") ? 8 : 6;
                uint8_t bytes[8] = {0};
                if (!val.empty()) normalizeMacAddr(val, n, bytes);
                std::memcpy(&rowBuffer[offset], bytes, n);
            } else if (col.dataType == "regtype" && !col.isArray) {
                const uint32_t oid = val.empty() ? 0 : stored_regtype_detail::rawOid(val);
                std::memcpy(&rowBuffer[offset], &oid, sizeof(oid));
            } else if (col.dataType == "boolean") {
                const auto parsed = parsePostgresBoolean(val);
                int8_t bval = val.empty() ? INT8_MIN :
                    parsed ? static_cast<int8_t>(*parsed) : INT8_MIN;
                std::memcpy(&rowBuffer[offset], &bval, sizeof(int8_t));
            } else {
                int64_t num = val.empty() ? INF : StorageEngine::parseInt(val);
                std::memcpy(&rowBuffer[offset], &num,
                            std::min(col.dsize, sizeof(num)));
            }
            offset += col.dsize;
        }
    } else {
        size_t fixedSize = tbl.fixedDataSize();
        size_t nVar = tbl.varColCount();
        size_t varArraySize = nVar * 4;

        std::string fixedData(fixedSize, '\0');
        std::vector<std::string> varDataList;
        size_t fixedOff = 0;
        for (size_t i = 0; i < tbl.len; ++i) {
            const Column& col = tbl.cols[i];
            auto it = values.find(col.dataName);
            std::string val = (it != values.end()) ? it->second : "";
            if (columnIsNull(i)) val.clear();
            if (col.isVariableLength) {
                size_t maxLen = col.isArray && col.dataType != "regtype" ? 1024 :
                    characterColumnByteLimit(col);
                if (val.size() > maxLen) val.resize(maxLen);
                varDataList.push_back(val);
            } else {
                if (col.dataType == "uuid") {
                    (void)writeUuidStorage(
                        val, &fixedData[fixedOff], col.dsize);
                } else if (col.dataType == "char" ||
                           col.dataType == "nchar" ||
                           col.dataType == "binary") {
                    std::memset(&fixedData[fixedOff], 0, col.dsize);
                    if (!val.empty()) {
                        size_t copyLen = std::min(val.size(), col.dsize);
                        std::memcpy(&fixedData[fixedOff], val.data(), copyLen);
                    }
                } else if (col.dataType == "date") {
                    if (val.empty()) {
                        Date d{};
                        std::memcpy(&fixedData[fixedOff], &d, DATE_SIZE);
                    } else {
                        Date d(val.c_str());
                        std::memcpy(&fixedData[fixedOff], &d, DATE_SIZE);
                    }
                } else if (col.storageCodec == Column::StorageCodec::TemporalMicros) {
                    const auto parsed = val.empty() ? std::optional<int64_t>{} : temporalColumnMicros(col, val);
                    if (!val.empty() && !parsed)
                        throw DbError("22007", "invalid canonical temporal storage datum");
                    const int64_t num = parsed ? *parsed : (col.dataType == "time" ? -1 : INF);
                    std::memcpy(&fixedData[fixedOff], &num, sizeof(num));
                } else if (col.dataType == "timestamp" || col.dataType == "timestamptz" || col.dataType == "datetime") {
                    int64_t num = val.empty() ? INF : parseTimestampToSeconds(val);
                    std::memcpy(&fixedData[fixedOff], &num, TIMESTAMP_SIZE);
                } else if (col.dataType == "time") {
                    int32_t num = val.empty() ? -1 : parseTimeToSeconds(val);
                    std::memcpy(&fixedData[fixedOff], &num, sizeof(int32_t));
                } else if (col.dataType == "float") {
                    float num = 0.0f;
                    if (!val.empty()) parseFloatLiteral(val, num);
                    std::memcpy(&fixedData[fixedOff], &num, sizeof(float));
                } else if (col.dataType == "money") {
                    int64_t minorUnits = 0;
                    if (!val.empty()) (void)parseMoneyLiteral(val, minorUnits);
                    std::memcpy(&fixedData[fixedOff], &minorUnits,
                                sizeof(minorUnits));
                } else if (col.dataType == "double" || col.dataType == "decimal" || col.dataType == "numeric") {
                    double num = 0.0;
                    if (!val.empty()) parseDoubleLiteral(val, num);
                    std::memcpy(&fixedData[fixedOff], &num, sizeof(double));
                } else if (col.dataType == "point") {
                    double x = 0.0, y = 0.0;
                    if (!val.empty()) {
                        std::string canonical;
                        normalizePointLiteral(val, canonical, &x, &y);
                    }
                    std::memcpy(&fixedData[fixedOff], &x, sizeof(double));
                    std::memcpy(&fixedData[fixedOff + sizeof(double)], &y,
                                sizeof(double));
                } else if (col.dataType == "regtype" && !col.isArray) {
                    const uint32_t oid = val.empty() ? 0 : stored_regtype_detail::rawOid(val);
                    std::memcpy(&fixedData[fixedOff], &oid, sizeof(oid));
                } else if (col.dataType == "boolean") {
                    const auto parsed = parsePostgresBoolean(val);
                    int8_t bval = val.empty() ? INT8_MIN :
                        parsed ? static_cast<int8_t>(*parsed) : INT8_MIN;
                    std::memcpy(&fixedData[fixedOff], &bval, sizeof(int8_t));
                } else if (col.dataType == "inet" || col.dataType == "cidr") {
                    uint8_t family = 0, prefix = 32;
                    uint8_t addr[16] = {0};
                    if (!val.empty()) {
                        parseInetAddr(val, family, prefix, addr,
                                      col.dataType == "cidr");  // validated at INSERT
                    }
                    fixedData[fixedOff] = static_cast<char>(family);
                    fixedData[fixedOff + 1] = static_cast<char>(prefix);
                    fixedData[fixedOff + 2] = static_cast<char>(col.dataType == "cidr" ? 1 : 0);
                    fixedData[fixedOff + 3] = 0;
                    std::memcpy(&fixedData[fixedOff + 4], addr, 16);
                } else if (col.dataType == "macaddr" || col.dataType == "macaddr8") {
                    int n = (col.dataType == "macaddr8") ? 8 : 6;
                    uint8_t bytes[8] = {0};
                    if (!val.empty()) normalizeMacAddr(val, n, bytes);
                    std::memcpy(&fixedData[fixedOff], bytes, n);
                } else {
                    int64_t num = val.empty() ? INF : StorageEngine::parseInt(val);
                    std::memcpy(&fixedData[fixedOff], &num,
                                std::min(col.dsize, sizeof(num)));
                }
                fixedOff += col.dsize;
            }
        }

        std::string varOffsetArray(varArraySize, '\0');
        std::string varDataSection;
        uint16_t varDataOffset = static_cast<uint16_t>(fixedSize + varArraySize);
        for (size_t vi = 0; vi < varDataList.size(); ++vi) {
            uint16_t vlen = static_cast<uint16_t>(varDataList[vi].size());
            size_t arrPos = vi * 4;
            std::memcpy(&varOffsetArray[arrPos], &varDataOffset, sizeof(uint16_t));
            std::memcpy(&varOffsetArray[arrPos + 2], &vlen, sizeof(uint16_t));
            varDataSection += varDataList[vi];
            varDataOffset += vlen;
        }

        rowBuffer += fixedData;
        rowBuffer += varOffsetArray;
        rowBuffer += varDataSection;
    }
    return rowBuffer;
}

// ========================================================================
// JSON validator: structural + token-level validation
// ========================================================================
static bool isValidJson(const std::string& s, bool binary) {
    if (s.empty()) return true;  // empty = NULL
    struct Token {
        enum Type { LBrace, RBrace, LBracket, RBracket, Colon, Comma,
                    String, Number, True, False, Null, End } type;
        std::string text;
    };
    size_t i = 0;
    auto skipSpace = [&]() { while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i; };
    auto nextToken = [&]() -> Token {
        skipSpace();
        if (i >= s.size()) return {Token::End, ""};
        char c = s[i];
        if (c == '{') { ++i; return {Token::LBrace, "{"}; }
        if (c == '}') { ++i; return {Token::RBrace, "}"}; }
        if (c == '[') { ++i; return {Token::LBracket, "["}; }
        if (c == ']') { ++i; return {Token::RBracket, "]"}; }
        if (c == ':') { ++i; return {Token::Colon, ":"}; }
        if (c == ',') { ++i; return {Token::Comma, ","}; }
        if (c == '"') {
            ++i;
            std::string str;
            while (i < s.size() && s[i] != '"') {
                if (s[i] == '\\' && i + 1 < s.size()) { str += s[i]; str += s[i+1]; i += 2; }
                else { str += s[i]; ++i; }
            }
            if (i >= s.size()) return {Token::End, ""};  // unclosed string
            ++i; // skip closing "
            return {Token::String, str};
        }
        // Number
        if (c == '-' || (c >= '0' && c <= '9')) {
            size_t start = i;
            if (c == '-') ++i;
            while (i < s.size() && s[i] >= '0' && s[i] <= '9') ++i;
            if (i < s.size() && s[i] == '.') {
                ++i;
                while (i < s.size() && s[i] >= '0' && s[i] <= '9') ++i;
            }
            if (i < s.size() && (s[i] == 'e' || s[i] == 'E')) {
                ++i;
                if (i < s.size() && (s[i] == '+' || s[i] == '-')) ++i;
                while (i < s.size() && s[i] >= '0' && s[i] <= '9') ++i;
            }
            return {Token::Number, s.substr(start, i - start)};
        }
        // Literals: true, false, null
        if (i + 4 <= s.size() && s.substr(i, 4) == "true") { i += 4; return {Token::True, "true"}; }
        if (i + 5 <= s.size() && s.substr(i, 5) == "false") { i += 5; return {Token::False, "false"}; }
        if (i + 4 <= s.size() && s.substr(i, 4) == "null") { i += 4; return {Token::Null, "null"}; }
        return {Token::End, ""};  // invalid token
    };

    // Parse value
    std::function<bool()> parseValue;
    parseValue = [&]() -> bool {
        Token t = nextToken();
        if (t.type == Token::String || t.type == Token::Number ||
            t.type == Token::True || t.type == Token::False || t.type == Token::Null) {
            return true;
        }
        if (t.type == Token::LBrace) {
            Token peek = nextToken();
            if (peek.type == Token::RBrace) return true;  // empty object
            if (peek.type != Token::String) return false;  // key must be string
            Token colon = nextToken();
            if (colon.type != Token::Colon) return false;
            if (!parseValue()) return false;
            while (true) {
                Token commaOrEnd = nextToken();
                if (commaOrEnd.type == Token::RBrace) return true;
                if (commaOrEnd.type != Token::Comma) return false;
                Token key = nextToken();
                if (key.type != Token::String) return false;
                Token c = nextToken();
                if (c.type != Token::Colon) return false;
                if (!parseValue()) return false;
            }
        }
        if (t.type == Token::LBracket) {
            Token peek = nextToken();
            if (peek.type == Token::RBracket) return true;  // empty array
            // Put back peek token (simplified: we already consumed it, so parse as value)
            // Actually we consumed it. We need to handle this differently.
            // Since we can't un-get, we'll restructure.
            return false;  // Will handle differently below
        }
        return false;
    };

    // Array parsing (separate to handle the consumed first token issue)
    std::function<bool()> parseArray = [&]() -> bool {
        Token peek = nextToken();
        if (peek.type == Token::RBracket) return true;
        // We consumed the first token of the first element. Need to re-parse from there.
        // Since the tokenizer is linear and we can't un-get, we'll use a different approach:
        // Count tokens and re-parse the whole thing. This is a simplified validator.
        return false;
    };

    // Simpler approach: just validate the full string recursively with index tracking
    i = 0;
    skipSpace();
    if (i >= s.size()) return true;

    std::function<bool()> parseVal;
    parseVal = [&]() -> bool {
        skipSpace();
        if (i >= s.size()) return false;
        char c = s[i];
        if (c == '"') {
            ++i;
            while (i < s.size() && s[i] != '"') {
                const unsigned char byte =
                    static_cast<unsigned char>(s[i]);
                if (byte < 0x20) return false;
                if (s[i] != '\\') {
                    ++i;
                    continue;
                }
                if (i + 1 >= s.size()) return false;
                const char escaped = s[i + 1];
                if (escaped == '"' || escaped == '\\' || escaped == '/' ||
                    escaped == 'b' || escaped == 'f' || escaped == 'n' ||
                    escaped == 'r' || escaped == 't') {
                    i += 2;
                    continue;
                }
                if (escaped != 'u' || i + 5 >= s.size()) return false;
                unsigned int codeUnit = 0;
                for (size_t digit = i + 2; digit <= i + 5; ++digit) {
                    if (!std::isxdigit(
                            static_cast<unsigned char>(s[digit]))) {
                        return false;
                    }
                    const char hex = s[digit];
                    const unsigned int value =
                        hex >= '0' && hex <= '9'
                            ? static_cast<unsigned int>(hex - '0')
                            : hex >= 'a' && hex <= 'f'
                                  ? static_cast<unsigned int>(hex - 'a' + 10)
                                  : static_cast<unsigned int>(hex - 'A' + 10);
                    codeUnit = (codeUnit << 4) | value;
                }
                if (binary) {
                    if (codeUnit == 0) return false;
                    if (codeUnit >= 0xd800 && codeUnit <= 0xdbff) {
                        if (i + 11 >= s.size() || s[i + 6] != '\\' ||
                            s[i + 7] != 'u') {
                            return false;
                        }
                        unsigned int low = 0;
                        for (size_t digit = i + 8; digit <= i + 11;
                             ++digit) {
                            const char hex = s[digit];
                            if (!std::isxdigit(
                                    static_cast<unsigned char>(hex))) {
                                return false;
                            }
                            const unsigned int value =
                                hex >= '0' && hex <= '9'
                                    ? static_cast<unsigned int>(hex - '0')
                                    : hex >= 'a' && hex <= 'f'
                                          ? static_cast<unsigned int>(
                                                hex - 'a' + 10)
                                          : static_cast<unsigned int>(
                                                hex - 'A' + 10);
                            low = (low << 4) | value;
                        }
                        if (low < 0xdc00 || low > 0xdfff) return false;
                        i += 12;
                        continue;
                    }
                    if (codeUnit >= 0xdc00 && codeUnit <= 0xdfff)
                        return false;
                }
                i += 6;
            }
            if (i >= s.size()) return false;
            ++i;
            return true;
        }
        if (c == '{') {
            ++i;
            skipSpace();
            if (i < s.size() && s[i] == '}') { ++i; return true; }
            while (true) {
                skipSpace();
                if (i >= s.size() || s[i] != '"') return false;
                if (!parseVal()) return false;  // key string
                skipSpace();
                if (i >= s.size() || s[i] != ':') return false;
                ++i;
                if (!parseVal()) return false;  // value
                skipSpace();
                if (i < s.size() && s[i] == ',') { ++i; continue; }
                if (i < s.size() && s[i] == '}') { ++i; return true; }
                return false;
            }
        }
        if (c == '[') {
            ++i;
            skipSpace();
            if (i < s.size() && s[i] == ']') { ++i; return true; }
            while (true) {
                if (!parseVal()) return false;
                skipSpace();
                if (i < s.size() && s[i] == ',') { ++i; continue; }
                if (i < s.size() && s[i] == ']') { ++i; return true; }
                return false;
            }
        }
        // Number
        if (c == '-' || (c >= '0' && c <= '9')) {
            if (c == '-') ++i;
            if (i >= s.size()) return false;
            if (s[i] == '0') {
                ++i;
                if (i < s.size() && s[i] >= '0' && s[i] <= '9')
                    return false;
            } else if (s[i] >= '1' && s[i] <= '9') {
                do {
                    ++i;
                } while (i < s.size() && s[i] >= '0' && s[i] <= '9');
            } else {
                return false;
            }
            if (i < s.size() && s[i] == '.') {
                ++i;
                const size_t fractionStart = i;
                while (i < s.size() && s[i] >= '0' && s[i] <= '9')
                    ++i;
                if (i == fractionStart) return false;
            }
            if (i < s.size() && (s[i] == 'e' || s[i] == 'E')) {
                ++i;
                if (i < s.size() && (s[i] == '+' || s[i] == '-')) ++i;
                const size_t exponentStart = i;
                while (i < s.size() && s[i] >= '0' && s[i] <= '9')
                    ++i;
                if (i == exponentStart) return false;
            }
            return true;
        }
        // true, false, null
        if (i + 4 <= s.size() && s.substr(i, 4) == "true") { i += 4; return true; }
        if (i + 5 <= s.size() && s.substr(i, 5) == "false") { i += 5; return true; }
        if (i + 4 <= s.size() && s.substr(i, 4) == "null") { i += 4; return true; }
        return false;
    };

    bool ok = parseVal();
    if (!ok) return false;
    skipSpace();
    return i == s.size();
}

static void retainGeneratedValue(
    std::shared_ptr<StorageEngine::OwningRowImage>& image,
    bool old, const std::string& name, std::optional<ExprValue>& value) {
    if (!value) return;
    if (!image) image=std::make_shared<StorageEngine::OwningRowImage>();
    (old?image->oldRow:image->newRow).emplace(name,std::move(*value));
}

DBStatus StorageEngine::insert(const std::string& dbname,
                                const std::string& tablename,
                                const std::map<std::string, std::string>& values,
                                std::vector<std::map<std::string, std::string>>* insertedRows,
                                IdentityOverride identityOverride,
                                OwningMutationRows* owningRows) {
    std::vector<SqlRow> typedRows;
    const DBStatus status = insertRow(
        dbname, tablename, sqlRowFromLegacy(values),
        insertedRows ? &typedRows : nullptr, identityOverride,owningRows);
    if (insertedRows) {
        for (const auto& row : typedRows) {
            insertedRows->push_back(legacyRowFromSql(row));
        }
    }
    return status;
}

DBStatus StorageEngine::insertRow(const std::string& dbname,
                                   const std::string& tablename,
                                   const SqlRow& sqlValues,
                                   std::vector<SqlRow>* insertedRows,
                                   IdentityOverride identityOverride,
                                OwningMutationRows* owningRows) {
    const auto ownershipStatus = ensureDatabaseTransactionOwnership(dbname);
    if (ownershipStatus != DBStatus::OK) return ownershipStatus;
    std::map<std::string, std::string> values;
    std::set<std::string> nullColumns;
    splitSqlRow(sqlValues, values, nullColumns);
    // A transaction owns one database lock, read view, commit log and undo
    // stream. Writing another database with its transaction ID would leave
    // that database's heap/index changes outside both commit and rollback.
    if (transactionContext().inTransaction &&
        dbname != transactionContext().txnDB) {
        return DBStatus::INVALID_VALUE;
    }

    // SQL execution already gives top-level DML a transaction. Give embedded
    // callers the same atomic commit boundary for ordinary tables so trigger
    // side effects, WAL/CLOG publication and logical decoding cannot diverge
    // from the inserted row. Partition tuple locators are not represented in
    // TxnLogEntry yet, so retain their legacy statement-local route rather
    // than pretending rollback can address the correct physical partition.
    // Inside an existing transaction, add a per-INSERT savepoint so a failed
    // AFTER trigger cannot abort unrelated work from earlier statements.
    const size_t returnedRowStart = insertedRows ? insertedRows->size() : 0;
    const size_t returnedOwningStart = owningRows ? owningRows->size() : 0;
    if (!transactionContext().inTransaction) {
        bool usesLegacyPartitionRoute = false;
        if (tableExists(dbname, tablename)) {
            const TableSchema table = getTableSchema(dbname, tablename);
            usesLegacyPartitionRoute =
                table.partitionType != TableSchema::PartitionType::None;
        } else {
            return insertInternal(
                dbname, tablename, values, nullColumns, insertedRows,
                identityOverride,owningRows);
        }
        if (usesLegacyPartitionRoute) {
            const DBStatus status = insertInternal(
                dbname, tablename, values, nullColumns, insertedRows,
                identityOverride,owningRows);
            if (status != DBStatus::OK && insertedRows) {
                insertedRows->resize(returnedRowStart);
            }
            if (status != DBStatus::OK && owningRows) owningRows->resize(returnedOwningStart);
            return status;
        }

        const DBStatus beginStatus = beginTransaction(dbname);
        if (beginStatus != DBStatus::OK) return beginStatus;
        try {
        const DBStatus insertStatus = insertInternal(
            dbname, tablename, values, nullColumns, insertedRows,
            identityOverride,owningRows);
        if (insertStatus != DBStatus::OK) {
            const DBStatus rollbackStatus = rollbackTransaction();
            if (insertedRows) insertedRows->resize(returnedRowStart);
            if (owningRows) owningRows->resize(returnedOwningStart);
            return rollbackStatus == DBStatus::OK
                ? insertStatus : rollbackStatus;
        }
        const DBStatus commitStatus = commitTransaction();
        if (commitStatus != DBStatus::OK && insertedRows) {
            insertedRows->resize(returnedRowStart);
        }
        if (commitStatus != DBStatus::OK && owningRows) owningRows->resize(returnedOwningStart);
        return commitStatus;
        } catch (...) {
            // Embedded callers have no SQL wrapper to roll back the implicit
            // transaction. Preserve the original typed exception even when
            // cleanup itself fails, and never publish partial RETURNING rows.
            const auto failure = std::current_exception();
            try {
                if (transactionContext().inTransaction)
                    (void)rollbackTransaction();
            } catch (...) {}
            if (insertedRows) insertedRows->resize(returnedRowStart);
            if (owningRows) owningRows->resize(returnedOwningStart);
            std::rethrow_exception(failure);
        }
    }

    static std::atomic<uint64_t> statementSavepointSequence{0};
    std::string statementSavepoint;
    auto& context = transactionContext();
    do {
        statementSavepoint = "__dbms_insert_statement_" +
            std::to_string(context.currentTxnId) + "_" +
            std::to_string(statementSavepointSequence.fetch_add(1));
    } while (context.containsSavepoint(statementSavepoint));
    const bool hasStatementSavepoint =
        createStatementSavepoint(statementSavepoint) == DBStatus::OK;

    try {
    const DBStatus insertStatus =
        insertInternal(dbname, tablename, values, nullColumns, insertedRows,
                       identityOverride,owningRows);
    if (insertStatus != DBStatus::OK) {
        DBStatus rollbackStatus = DBStatus::OK;
        if (transactionContext().inTransaction && hasStatementSavepoint) {
            rollbackStatus = rollbackToSavepoint(statementSavepoint);
            if (rollbackStatus == DBStatus::OK) {
                rollbackStatus = releaseSavepoint(statementSavepoint);
            }
        } else if (transactionContext().inTransaction) {
            rollbackStatus = rollbackTransaction();
        }
        if (insertedRows) insertedRows->resize(returnedRowStart);
            if (owningRows) owningRows->resize(returnedOwningStart);
        return rollbackStatus == DBStatus::OK
            ? insertStatus : rollbackStatus;
    }

    if (!hasStatementSavepoint) return DBStatus::OK;
    const DBStatus releaseStatus = releaseSavepoint(statementSavepoint);
    if (releaseStatus == DBStatus::OK) return DBStatus::OK;
    if (insertedRows) insertedRows->resize(returnedRowStart);
            if (owningRows) owningRows->resize(returnedOwningStart);
    const DBStatus rollbackStatus = rollbackTransaction();
    return rollbackStatus == DBStatus::OK
        ? releaseStatus : rollbackStatus;
    } catch (...) {
        const auto failure = std::current_exception();
        try {
            if (transactionContext().inTransaction) {
                DBStatus status = DBStatus::INVALID_VALUE;
                if (hasStatementSavepoint) {
                    status = rollbackToSavepoint(statementSavepoint);
                    if (status == DBStatus::OK)
                        status = releaseSavepoint(statementSavepoint);
                }
                // A damaged statement backup must not leave partial changes
                // available for a later commit of the caller's transaction.
                if (status != DBStatus::OK && transactionContext().inTransaction)
                    (void)rollbackTransaction();
            }
        } catch (...) {
            try {
                if (transactionContext().inTransaction)
                    (void)rollbackTransaction();
            } catch (...) {}
        }
        if (insertedRows) insertedRows->resize(returnedRowStart);
            if (owningRows) owningRows->resize(returnedOwningStart);
        std::rethrow_exception(failure);
    }
}

DBStatus StorageEngine::insertInternal(
                                const std::string& dbname,
                                const std::string& tablename,
                                const std::map<std::string, std::string>& values,
                                const std::set<std::string>& nullColumns,
                                std::vector<SqlRow>* insertedRows,
                                IdentityOverride identityOverride,
                                OwningMutationRows* owningRows) {
    noteTemporaryRelationAccess(dbname, tablename);
    if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
        if ((transactionContext().txnIsolationLevel == IsolationLevel::READ_COMMITTED ||
             transactionContext().txnIsolationLevel == IsolationLevel::READ_UNCOMMITTED) &&
            !transactionContext().readView.commandIdVisibility) {
            refreshReadView();
        } else {
            ensureTransactionSnapshot();
        }
        transactionContext().hasWrite = true;
    }
    if (transactionContext().readOnly &&
        !isSessionTemporaryRelation(tablename)) {
        return DBStatus::INVALID_VALUE;
    }
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    // Intention lock instead of a full table X lock: concurrent inserts into
    // different pages (and readers) proceed in parallel. Physical page state
    // is guarded by the per-page exclusive locks below plus the allocator /
    // FSM / VM internal mutexes, mirroring how UPDATE already sequences.
    if (!lockManager_.lockIntentExclusive(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl;
    try { tbl = getTableSchema(dbname, tablename); }
    catch (...) { lockManager_.unlock(tablename); throw; }
    bool captureLogicalInsert = false;
    try {
        captureLogicalInsert = !tbl.isUnlogged && PublicationCatalog::instance().publishes(
            dbname, tablename, LogicalChange::Op::Insert);
    } catch (const DbError& error) {
        if (error.sqlState() != "58030") throw;
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    const auto secondaryIndexMetadata =
        getIndexMetadata(dbname, tablename);
    const auto compositeIndexMetadata =
        getCompositeIndexes(dbname, tablename);
    std::vector<bool> domainRequired(tbl.len, false);
    try {
        for (size_t i = 0; i < tbl.len; ++i)
            if (!tbl.cols[i].domainName.empty())
                {
                    const auto domain = resolveDomainAncestry(dbname, tbl.cols[i].domainName);
                    if (domain.name.empty()) throw DbError("XX001", "column domain metadata is missing");
                    domainRequired[i] = domain.notNull;
                }
    } catch (...) {
        lockManager_.unlock(tablename);
        throw;
    }
    // A partition-local tuple locator is not represented in TxnLogEntry yet:
    // every partition starts at page 1/slot 0, so transaction rollback would
    // address the empty parent heap (or an unrelated partition row).  Reject
    // this unsupported path before defaults, sequences, triggers, TOAST, WAL,
    // or heap state can change.  Autocommit INSERT routing remains supported.
    if (tbl.partitionType != TableSchema::PartitionType::None &&
        transactionContext().inTransaction &&
        dbname == transactionContext().txnDB) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    std::vector<Trigger> operationTriggers;
    if (triggerExecutor_ && !tryGetAllTriggers(dbname, operationTriggers)) {
        lockManager_.unlock(tablename);
        return DBStatus::CORRUPTED_DATA;
    }

    // Deferrable UNIQUE/FK constraints currently deferred: their checks are
    // queued after the row lands (rid known).
    struct DeferredFkEntry {
        size_t fkIndex;
        std::vector<std::string> values;
    };
    std::vector<size_t> deferredUniqueCols;
    std::vector<DeferredFkEntry> deferredFkEntries;

    // Apply DEFAULT values
    std::map<std::string, std::string> actualValues = values;
    std::set<std::string> actualNullColumns = nullColumns;
    auto typeHints = buildTypeHints(tbl);

    // Identity input policy is enforced at the storage boundary so embedded
    // callers cannot bypass the SQL executor. OVERRIDING USER VALUE discards
    // even explicit NULL; the absence then invokes the identity sequence.
    for (size_t i = 0; i < tbl.len; ++i) {
        const Column& col = tbl.cols[i];
        if (col.identityKind == 0) continue;
        const bool supplied = values.find(col.dataName) != values.end();
        if (identityOverride == IdentityOverride::User) {
            actualValues.erase(col.dataName);
            actualNullColumns.erase(col.dataName);
        } else if (col.identityKind == 'a' && supplied &&
                   identityOverride != IdentityOverride::System) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    }

    // Reject user-supplied values for GENERATED ALWAYS columns.  Presence is
    // what matters here: SQL NULL and an empty string are still explicit
    // values, while DEFAULT has already been represented by an omitted key.
    for (size_t i = 0; i < tbl.len; ++i) {
        const Column& col = tbl.cols[i];
        if (!col.generatedExpr.empty() &&
            values.find(col.dataName) != values.end()) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    }

    for (size_t i = 0; i < tbl.len; ++i) {
        const Column& col = tbl.cols[i];
        auto it = actualValues.find(col.dataName);
        // Presence means the caller supplied the column, including an explicit
        // NULL represented by an empty value.  Only an omitted column receives
        // its DEFAULT; this is required to distinguish DEFAULT from NULL.
        if (it == actualValues.end() && !col.defaultValue.empty()) {
            std::string computed;
            bool computedNull = false;
            if (evalExpressionSqlValue(col.defaultValue, actualValues,
                                       typeHints, dbname, computed,
                                       computedNull, nullptr, this, col.dataType=="regtype")) {
                actualValues[col.dataName] = computed;
                if (computedNull) actualNullColumns.insert(col.dataName);
                else actualNullColumns.erase(col.dataName);
            } else {
                // Fall back to raw string for simple literal defaults.
                actualValues[col.dataName] = col.defaultValue;
                actualNullColumns.erase(col.dataName);
            }
        }
    }

    // Apply AUTO_INCREMENT values
    for (size_t i = 0; i < tbl.len; ++i) {
        const Column& col = tbl.cols[i];
        if (!col.isAutoIncrement) continue;
        auto it = actualValues.find(col.dataName);
        if (it != actualValues.end()) continue;
        int64_t nextVal = readNextSeq(dbname, tablename, col.dataName);
        actualValues[col.dataName] = std::to_string(nextVal);
        actualNullColumns.erase(col.dataName);
        writeNextSeq(dbname, tablename, col.dataName, nextVal + 1);
    }

    // Canonicalize packed POINT values before uniqueness/index checks.  The
    // prior writer silently turned malformed input into (0,0), and its
    // default stream precision could make distinct coordinates share a key.
    if (!normalizePointColumns(tbl, actualValues, &actualNullColumns)) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    // Uniqueness must be checked against the final NEW row, after BEFORE
    // triggers and stored generated columns. Define the validator here so it
    // can share the deferred-constraint bookkeeping, but invoke it only once
    // that row image is complete below.
    const auto validateFinalUniqueKeys = [&]() -> DBStatus {
        if (tbl.hasPrimaryKey()) {
            std::vector<size_t> primaryColumns;
            if (!collectPrimaryKeyColumns(tbl, primaryColumns) ||
                primaryColumns.empty()) {
                return DBStatus::CORRUPTED_DATA;
            }
            const std::string pkVal = tbl.buildPKValue(actualValues);
            if (!pkVal.empty()) {
                bool duplicate = false;
                if (constraintNeedsCollationScan(tbl, primaryColumns)) {
                    std::vector<std::string> candidateValues;
                    candidateValues.reserve(primaryColumns.size());
                    for (const size_t columnIndex : primaryColumns) {
                        candidateValues.push_back(valueFromRowMap(
                            actualValues,
                            tbl.cols[columnIndex].dataName));
                    }
                    if (!forEachRow(
                            dbname, tablename,
                            [&](uint32_t, uint16_t, const char* data,
                                size_t length) {
                                if (duplicate) return;
                                const std::string row(data, length);
                                std::vector<std::string> existingValues;
                                existingValues.reserve(primaryColumns.size());
                                for (const size_t columnIndex :
                                     primaryColumns) {
                                    existingValues.push_back(
                                        extractColumnValue(
                                            row, tbl, columnIndex, dbname));
                                }
                                duplicate = constraintKeyValuesEqual(
                                    tbl, primaryColumns, existingValues,
                                    candidateValues);
                            })) {
                        return DBStatus::IO_ERROR;
                    }
                } else {
                    BPTree* index = getPKIndex(dbname, tablename);
                    if (index && index->isOpen()) {
                        int64_t ignored = -1;
                        duplicate = index->search(pkVal, ignored);
                    } else if (!forEachRow(
                                   dbname, tablename,
                                   [&](uint32_t, uint16_t, const char* data,
                                       size_t length) {
                                       if (duplicate) return;
                                       duplicate = extractPKValue(
                                           std::string(data, length), tbl,
                                           dbname) == pkVal;
                                   })) {
                        return DBStatus::IO_ERROR;
                    }
                }
                if (duplicate) return DBStatus::DUPLICATE_KEY;
            }
        }

        // Check single-column UNIQUE constraints (use B+ tree index if
        // available). Deferred constraints queue their final value for the
        // commit-time validation below.
        for (size_t i = 0; i < tbl.len; ++i) {
            const Column& col = tbl.cols[i];
            if (!col.isUnique) continue;
            const auto value = actualValues.find(col.dataName);
            if (value == actualValues.end() ||
                actualNullColumns.count(col.dataName) != 0) {
                continue;
            }
            const std::string candidateKey =
                canonicalColumnKeyValue(col, value->second);
            const std::string& candidateValue = value->second;
            std::string constraintName =
                tablename + "_" + col.dataName + "_key";
            for (size_t uniqueIndex = 0;
                 uniqueIndex < tbl.uniqueConstraints.size(); ++uniqueIndex) {
                const auto& columns = tbl.uniqueConstraints[uniqueIndex];
                if (std::find(columns.begin(), columns.end(), i) ==
                    columns.end()) {
                    continue;
                }
                if (uniqueIndex < tbl.uniqueConstraintNames.size() &&
                    !tbl.uniqueConstraintNames[uniqueIndex].empty()) {
                    constraintName = tbl.uniqueConstraintNames[uniqueIndex];
                }
                break;
            }
            if (transactionContext().inTransaction &&
                isConstraintCurrentlyDeferred(
                    dbname, tablename, constraintName)) {
                deferredUniqueCols.push_back(i);
                continue;
            }

            bool duplicate = false;
            BPTree* index = getSecondaryIndex(
                dbname, tablename, col.dataName);
            // Empty strings were historically omitted from secondary
            // indexes because an empty index key also represented SQL NULL.
            // Use the heap for that value so both legacy and newly-written
            // rows participate in UNIQUE without changing on-disk keys.
            // Keys at the fixed-width boundary also need a full-value check:
            // an exact 20-byte value can collide with a longer value's prefix.
            if (columnUsesBinaryCollation(col) && !candidateKey.empty() &&
                candidateKey.size() < BP_KEY_LEN &&
                index && index->isOpen()) {
                duplicate = !index->searchMulti(candidateKey).empty();
            } else if (!forEachRow(
                           dbname, tablename,
                           [&](uint32_t pageId, uint16_t slotId,
                               const char* data,
                               size_t length) {
                               if (duplicate) return;
                               const int64_t existingRid =
                                   encodeRid(pageId, slotId);
                               if (col.isNull && dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, existingRid, i)) {
                                   return;
                               }
                               duplicate = constraintColumnValuesEqual(
                                   col, extractColumnValue(
                                            std::string(data, length), tbl,
                                            i, dbname),
                                   candidateValue);
                           })) {
                return DBStatus::IO_ERROR;
            }
            if (duplicate) return DBStatus::DUPLICATE_KEY;
        }

        // Check table-level composite UNIQUE constraints.
        for (size_t uniqueIndex = 0;
             uniqueIndex < tbl.uniqueConstraints.size(); ++uniqueIndex) {
            const auto& columns = tbl.uniqueConstraints[uniqueIndex];
            if (columns.empty()) continue;
            std::string constraintName;
            if (uniqueIndex < tbl.uniqueConstraintNames.size()) {
                constraintName = tbl.uniqueConstraintNames[uniqueIndex];
            }
            if (constraintName.empty() && columns.front() < tbl.len) {
                constraintName = tablename + "_" +
                    tbl.cols[columns.front()].dataName + "_key";
            }
            if (columns.size() == 1 &&
                transactionContext().inTransaction &&
                isConstraintCurrentlyDeferred(
                    dbname, tablename, constraintName)) {
                deferredUniqueCols.push_back(columns.front());
                continue;
            }

            std::vector<std::string> compositeKey;
            bool containsNull = false;
            for (const size_t columnIndex : columns) {
                if (columnIndex >= tbl.len) return DBStatus::CORRUPTED_DATA;
                const auto value = actualValues.find(
                    tbl.cols[columnIndex].dataName);
                if (value == actualValues.end() ||
                    actualNullColumns.count(
                        tbl.cols[columnIndex].dataName) != 0) {
                    containsNull = true;
                    break;
                }
                compositeKey.push_back(value->second);
            }
            if (containsNull) continue;

            bool duplicate = false;
            if (!forEachRow(
                    dbname, tablename,
                    [&](uint32_t pageId, uint16_t slotId,
                        const char* data,
                        size_t length) {
                        if (duplicate) return;
                        const std::string row(data, length);
                        const int64_t existingRid =
                            encodeRid(pageId, slotId);
                        std::vector<std::string> existingKey;
                        existingKey.reserve(columns.size());
                        for (const size_t columnIndex : columns) {
                            if (tbl.cols[columnIndex].isNull &&
                                dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, existingRid, columnIndex)) {
                                return;
                            }
                            existingKey.push_back(extractColumnValue(
                                row, tbl, columnIndex, dbname));
                        }
                        duplicate = constraintKeyValuesEqual(
                            tbl, columns, existingKey, compositeKey);
                    })) {
                return DBStatus::IO_ERROR;
            }
            if (duplicate) return DBStatus::DUPLICATE_KEY;
        }

        const auto validateStandaloneUniqueIndex = [&]
            (const std::vector<size_t>& columns) -> DBStatus {
            if (columns.empty()) return DBStatus::CORRUPTED_DATA;
            std::vector<std::string> candidateValues;
            candidateValues.reserve(columns.size());
            for (const size_t columnIndex : columns) {
                if (columnIndex >= tbl.len) return DBStatus::CORRUPTED_DATA;
                const std::string& columnName =
                    tbl.cols[columnIndex].dataName;
                const auto value = actualValues.find(columnName);
                // Ordinary UNIQUE indexes use NULLS DISTINCT semantics.
                if (value == actualValues.end() ||
                    actualNullColumns.count(columnName) != 0) {
                    return DBStatus::OK;
                }
                candidateValues.push_back(value->second);
            }

            bool duplicate = false;
            if (!forEachRow(
                    dbname, tablename,
                    [&](uint32_t pageId, uint16_t slotId,
                        const char* data, size_t length) {
                        if (duplicate) return;
                        const int64_t existingRid =
                            encodeRid(pageId, slotId);
                        const std::string row(data, length);
                        std::vector<std::string> existingValues;
                        existingValues.reserve(columns.size());
                        for (const size_t columnIndex : columns) {
                            if (tbl.cols[columnIndex].isNull &&
                                dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, existingRid, columnIndex)) {
                                return;
                            }
                            existingValues.push_back(extractColumnValue(
                                row, tbl, columnIndex, dbname));
                        }
                        duplicate = constraintKeyValuesEqual(
                            tbl, columns, existingValues, candidateValues);
                    })) {
                return DBStatus::IO_ERROR;
            }
            return duplicate ? DBStatus::DUPLICATE_KEY : DBStatus::OK;
        };

        for (const auto& metadata : secondaryIndexMetadata) {
            if (!metadata.isUnique) continue;
            if (metadata.isExpression ||
                !metadata.whereCondition.empty()) {
                return DBStatus::CORRUPTED_DATA;
            }
            size_t columnIndex = tbl.len;
            for (size_t candidate = 0; candidate < tbl.len; ++candidate) {
                if (tbl.cols[candidate].dataName == metadata.name) {
                    columnIndex = candidate;
                    break;
                }
            }
            if (columnIndex >= tbl.len) return DBStatus::CORRUPTED_DATA;
            const DBStatus status =
                validateStandaloneUniqueIndex({columnIndex});
            if (status != DBStatus::OK) return status;
        }
        for (const auto& metadata : compositeIndexMetadata) {
            if (!metadata.isUnique) continue;
            if (!metadata.whereCondition.empty()) {
                return DBStatus::CORRUPTED_DATA;
            }
            std::vector<size_t> columns;
            std::set<size_t> distinctColumns;
            for (const auto& columnName : metadata.columns) {
                size_t columnIndex = tbl.len;
                for (size_t candidate = 0; candidate < tbl.len;
                     ++candidate) {
                    if (tbl.cols[candidate].dataName == columnName) {
                        columnIndex = candidate;
                        break;
                    }
                }
                if (columnIndex >= tbl.len ||
                    !distinctColumns.insert(columnIndex).second) {
                    return DBStatus::CORRUPTED_DATA;
                }
                columns.push_back(columnIndex);
            }
            const DBStatus status =
                validateStandaloneUniqueIndex(columns);
            if (status != DBStatus::OK) return status;
        }
        return DBStatus::OK;
    };

    // Canonicalize input values before triggers consume them, then run the
    // same validation against the final NEW image after triggers/generated
    // columns. NOT NULL belongs only to that final pass so a BEFORE trigger
    // can supply an omitted required value.
    const auto validateRowValues = [&](bool enforceNotNull) -> DBStatus {
    for (size_t i = 0; i < tbl.len; ++i) {
        const Column& col = tbl.cols[i];
        auto it = actualValues.find(col.dataName);
        const bool hasValue = it != actualValues.end();
        const bool isNullMarker = hasValue &&
            actualNullColumns.count(col.dataName) != 0;
        std::string val = hasValue ? it->second : "";
        if (enforceNotNull && (!col.isNull || domainRequired[i]) &&
            (!hasValue || isNullMarker)) {
            lockManager_.unlock(tablename);
            return DBStatus::NULL_NOT_ALLOWED;
        }
        if (hasValue && !isNullMarker && val.empty() &&
            !columnAcceptsEmptyValue(col)) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        // The NULL marker encodes SQL NULL; type validations below must not
        // try to parse it as a value.
        if (isNullMarker) val.clear();
        if (hasValue && !isNullMarker && col.dataType == "regtype") {
            try {
                const auto catalog = regtype_detail::metadata(*this, dbname);
                actualValues[col.dataName] = stored_regtype_detail::input(
                    val, col.isArray, catalog, currentSession());
                val = actualValues[col.dataName];
            } catch (...) {
                lockManager_.unlock(tablename);
                throw;
            }
            // Reference input is complete; arithmetic/array casts must not
            // interpret the canonical OID as a different SQL input type.
            continue;
        }
        // An array's dataType names its element. Scalar validators must not
        // parse the whole brace literal as NUMERIC, UUID, MONEY, etc.
        if (col.isArray) {
            if (!val.empty()) {
                std::string canonical;
                if (!(col.dataType == "interval" || col.dataType == "numeric" ? normalizeModifiedColumn(col, val, canonical) : normalizeArray(val, col.dataType, canonical))) {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
                actualValues[col.dataName] = std::move(canonical);
            }
            continue;
        }
        if (col.storageCodec == Column::StorageCodec::TemporalMicros) {
            if (!val.empty()) {
                std::string canonical;
                if (!normalizeTemporalColumn(col, val, canonical)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
                actualValues[col.dataName] = std::move(canonical);
            }
            continue;
        }
        if (!col.isVariableLength && col.dataType == "date" && !val.empty()) {
            Date d(val.c_str());
            if (d.year == 0) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        if (!col.isVariableLength && (col.dataType == "timestamp" || col.dataType == "timestamptz" || col.dataType == "datetime") && !val.empty()) {
            int64_t ts = parseTimestampToSeconds(val);
            if (ts == 0) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        if (!col.isVariableLength && col.dataType == "time" && !val.empty()) {
            int32_t ts = parseTimeToSeconds(val);
            if (ts < 0) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        if (!col.isVariableLength && col.dataType == "float" && !val.empty()) {
            float parsed = 0.0f;
            if (!parseFloatLiteral(val, parsed)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = formatFloatingValue(parsed);
        }
        if (col.dataType == "money" && !val.empty()) {
            int64_t minorUnits = 0;
            std::string canonical;
            if (!parseMoneyLiteral(val, minorUnits, &canonical)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canonical;
        } else if (col.dataType == "numeric" && !val.empty()) {
            std::string canonical;
            if (!normalizeModifiedColumn(col, val, canonical)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = std::move(canonical);
        } else if (!col.isVariableLength && (col.dataType == "double" || col.dataType == "decimal") && !val.empty()) {
            double parsed = 0.0;
            if (!parseDoubleLiteral(val, parsed)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = formatFloatingValue(parsed);
        }
        if (!col.isVariableLength && col.dataType == "boolean" && !val.empty()) {
            const auto parsed = parsePostgresBoolean(val);
            if (!parsed) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = postgresBooleanOutput(*parsed);
        }
        if (!col.isVariableLength && (col.dataType == "macaddr" || col.dataType == "macaddr8") && !val.empty()) {
            int n = (col.dataType == "macaddr8") ? 8 : 6;
            uint8_t bytes[8];
            if (!normalizeMacAddr(val, n, bytes)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        // Validate / canonicalize bit and bit varying values (stored as the
        // literal '0'/'1' string; enforce length and strip any B'...' wrapper).
        if ((col.dataType == "bit" || col.dataType == "bit varying") && !val.empty()) {
            std::string canon;
            if (!normalizeBitString(val, col.dataType, col.dsize, canon)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canon;
        }
        // Validate / canonicalize geometric types (line/lseg/box/path/polygon/
        // circle); point is packed binary and handled elsewhere.
        if (isGeometricTextType(col.dataType) && !val.empty()) {
            std::string canon;
            if (!normalizeGeometry(val, col.dataType, canon)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canon;
        }
        // Validate / canonicalize UUID (32 hex digits → lowercase 8-4-4-4-12).
        if (col.dataType == "uuid" && !val.empty()) {
            std::string canon;
            if (!normalizeUuid(val, canon)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canon;
        }
        // Validate / canonicalize bytea (hex or escape input → canonical \xhh..).
        if (col.dataType == "blob" && !val.empty()) {
            std::string canon;
            if (!normalizeBytea(val, canon)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canon;
        }
        // Validate inet/cidr address (strict IPv4/IPv6 + prefix range).
        if ((col.dataType == "inet" || col.dataType == "cidr") && !val.empty()) {
            uint8_t family = 0, prefix = 0, addr[16];
            if (!parseInetAddr(val, family, prefix, addr,
                               col.dataType == "cidr")) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        // Validate / canonicalize range types (grammar, bound ordering,
        // discrete [) folding, empty detection).
        if (isRangeType(col.dataType) && !val.empty()) {
            std::string canon;
            if (!normalizeRange(val, col.dataType, canon)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canon;
        }
        // Validate / canonicalize array literals (brace structure, rectangular
        // dimensions, per-element type for numeric element types).
        if (col.isArray && !val.empty()) {
            std::string canon;
            if (!(col.dataType == "interval" || col.dataType == "numeric" ? normalizeModifiedColumn(col, val, canon) : normalizeArray(val, col.dataType, canon))) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canon;
        }
        // Validate XML well-formedness (stored verbatim, no canonicalization).
        if (col.dataType == "xml" && !col.isArray) {
            if (!validateXml(val, XmlParseMode::Content).ok) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        // Validate / canonicalize tsvector; validate tsquery (verbatim).
        if (col.dataType == "tsvector" && !col.isArray && !val.empty()) {
            std::string canon;
            if (!normalizeTsVectorImpl(val, canon)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canon;
        }
        if (col.dataType == "tsquery" && !col.isArray && !val.empty()) {
            if (!isValidTsQuery(val)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        // Validate jsonpath structure (stored verbatim).
        if (col.dataType == "jsonpath" && !col.isArray && !val.empty()) {
            if (!isValidJsonPath(val)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        // Validate / canonicalize interval to PG postgres style.
        if (col.dataType == "interval" && !col.isArray && !val.empty()) {
            std::string canon;
            if (!normalizeModifiedColumn(col, val, canon)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualValues[col.dataName] = canon;
        }
        // Validate / canonicalize composite-type row literals. Guard with a cheap
        // in-memory registry check so only non-builtin columns hit the catalog.
        if (!col.isArray && !val.empty() &&
            TypeRegistry::instance().findType(col.dataType) == nullptr) {
            CompositeType ct = getCompositeType(dbname, col.dataType);
            if (!ct.name.empty()) {
                std::string canon;
                if (!normalizeComposite(val, ct, canon)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
                actualValues[col.dataName] = canon;
            }
        }
        // Validate JSON / JSONB columns
        if ((col.dataType == "json" || col.dataType == "jsonb") && !val.empty()) {
            if (!isValidJson(val, col.dataType == "jsonb")) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        // Validate ENUM columns
        if (!col.enumValues.empty() && !val.empty()) {
            bool valid = false;
            for (const auto& label : col.enumValues) {
                if (label == val) { valid = true; break; }
            }
            if (!valid) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
        if (!col.isVariableLength && col.dataType != "char" && col.dataType != "binary" && col.dataType != "date" && col.dataType != "timestamp" && col.dataType != "timestamptz" && col.dataType != "datetime" && col.dataType != "time" && col.dataType != "float" && col.dataType != "double" && col.dataType != "decimal" && col.dataType != "numeric" && col.dataType != "money" && col.dataType != "boolean" && col.dataType != "uuid" && col.dataType != "point" && col.dataType != "inet" && col.dataType != "cidr" && col.dataType != "macaddr" && col.dataType != "macaddr8" && !val.empty()) {
            const auto num = parseStoredInteger(val);
            if (!num || !integerValueFitsColumn(col, *num) ||
                (*num == INF && col.isNull && !usesHeapTupleHeader(tbl.formatVersion))) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
        }
    }
    return DBStatus::OK;
    };

    const DBStatus inputValidation = validateRowValues(false);
    if (inputValidation != DBStatus::OK) return inputValidation;
    // Width is measured on the canonical SQL value. In particular BIT
    // literals may enter as B'1010' but are stored as the bare bit string.
    const DBStatus characterWidthStatus =
        normalizeCharacterColumnWidths(tbl, actualValues, &actualNullColumns);
    if (characterWidthStatus != DBStatus::OK) {
        lockManager_.unlock(tablename);
        return characterWidthStatus;
    }
    if (!variableColumnWidthsValid(tbl, actualValues, &actualNullColumns)) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Fire BEFORE INSERT triggers (row-level)
    // BEFORE triggers execute before the actual write and can modify NEW column values
    // via "SET col = val" or "NEW.col = val" assignments in the trigger action.
    if (triggerExecutor_) {
        auto beforeInsertTriggers = filterTriggers(
            operationTriggers, tablename, "before", "insert");
        for (const auto& trg : beforeInsertTriggers) {
            if (!trg.enabled) continue;
            if (!trg.forEachRow) continue;  // statement-level BEFORE not yet supported
            // Evaluate WHEN condition if present
            if (!trg.whenCondition.empty() && whenEvaluator_) {
                std::string cond = trg.whenCondition;
                for (const auto& [col, val] : actualValues) {
                    std::string placeholder = "NEW." + col;
                    size_t pos = 0;
                    while ((pos = cond.find(placeholder, pos)) != std::string::npos) {
                        cond.replace(pos, placeholder.size(), val);
                        pos += val.size();
                    }
                }
                if (!whenEvaluator_(cond, actualValues, {})) continue;
            }
            std::string action = trg.action;
            // Substitute NEW.column placeholders
            for (const auto& [col, val] : actualValues) {
                std::string placeholder = "NEW." + col;
                size_t pos = 0;
                while ((pos = action.find(placeholder, pos)) != std::string::npos) {
                    action.replace(pos, placeholder.size(), val);
                    pos += val.size();
                }
            }
            // Substitute trigger diagnostic variables
            {
                auto replaceVar = [&](const std::string& var, const std::string& val) {
                    size_t pos = 0;
                    while ((pos = action.find(var, pos)) != std::string::npos) {
                        action.replace(pos, var.size(), val);
                        pos += val.size();
                    }
                };
                replaceVar("tg_name", trg.name);
                replaceVar("tg_when", trg.timing);
                replaceVar("tg_level", trg.forEachRow ? "ROW" : "STATEMENT");
                replaceVar("tg_op", "INSERT");
                replaceVar("tg_relname", trg.tableName);
            }
            // Execute the trigger action
            stageExecFunctionCtx(*this, trg.name, trg.timing,
                              "INSERT", trg.tableName,
                              trg.forEachRow, &actualValues, nullptr, &tbl);
            if (triggerExecutor_(action)) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            // Parse only the storage layer's explicit row-assignment syntax.
            // Use the original action so NEW.col on the left-hand side is not
            // consumed by the placeholder substitution performed above.
            {
                for (const auto& assignment :
                     parseTriggerRowAssignments(trg.action)) {
                    std::string val;
                    bool evaluatedNull = false;
                    if (!evalTriggerRowAssignment(*this, dbname, tbl,
                            assignment.expression, actualValues,
                            actualNullColumns, nullptr, nullptr, val, evaluatedNull)) {
                        lockManager_.unlock(tablename);
                        return DBStatus::INVALID_VALUE;
                    }
                    for (size_t i = 0; i < tbl.len; ++i) {
                        if (tbl.cols[i].dataName == assignment.column) {
                            actualValues[assignment.column] = val;
                            if (evaluatedNull) {
                                actualNullColumns.insert(assignment.column);
                            } else {
                                actualNullColumns.erase(assignment.column);
                            }
                            break;
                        }
                    }
                }
            }
        }
    }

    // Defaults and BEFORE triggers have now had their chance to supply
    // omitted fields. Build a complete typed NEW image: absence at the SQL
    // input boundary means SQL NULL, not an unbound column in a generated
    // expression or CHECK. Do not replace a supplied empty text value.
    for (size_t i = 0; i < tbl.len; ++i) {
        const auto& column = tbl.cols[i];
        if (actualValues.emplace(column.dataName, std::string{}).second)
            actualNullColumns.insert(column.dataName);
    }

    // BEFORE INSERT triggers own the final NEW values of base columns.
    // Compute stored generated columns only after every such trigger has run,
    // so heap data, constraints, RETURNING, and every index derive from the
    // same row image. A catalog expression that cannot be evaluated must not
    // silently turn into a NULL/empty stored value.
    for (size_t i = 0; i < tbl.len; ++i) {
        const Column& col = tbl.cols[i];
        if (col.generatedExpr.empty() || col.generatedKind == 'v') continue;
        std::string computed;
        bool computedNull = false;
        if (!evalExpressionSqlValue(col.generatedExpr, actualValues,
                                    typeHints, dbname, computed,
                                    computedNull, nullptr, this, col.dataType=="regtype", &tbl)) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        actualValues[col.dataName] = computed;
        if (computedNull) actualNullColumns.insert(col.dataName);
        else actualNullColumns.erase(col.dataName);
    }

    const DBStatus finalValidation = validateRowValues(true);
    if (finalValidation != DBStatus::OK) return finalValidation;

    // BEFORE triggers and generated expressions can replace POINT values
    // after the initial input pass; validate their final row image too.
    if (!normalizePointColumns(tbl, actualValues, &actualNullColumns)) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    const DBStatus finalCharacterWidthStatus =
        normalizeCharacterColumnWidths(tbl, actualValues, &actualNullColumns);
    if (finalCharacterWidthStatus != DBStatus::OK) {
        lockManager_.unlock(tablename);
        return finalCharacterWidthStatus;
    }
    if (!variableColumnWidthsValid(tbl, actualValues, &actualNullColumns)) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    const DBStatus uniqueStatus = validateFinalUniqueKeys();
    if (uniqueStatus != DBStatus::OK) {
        lockManager_.unlock(tablename);
        return uniqueStatus;
    }

    // RLS WITH CHECK is evaluated after defaults, generated values and
    // BEFORE-trigger changes, matching the final row that will be written.
    if (!rowPassesRLS(this, dbname, tablename, tbl, "INSERT", actualValues,
                      typeHints, true)) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Compute all B-tree keys and partial-index memberships from the final
    // logical row.  The physical image may replace large values with TOAST
    // markers and must never be used for a predicate or key.
    std::vector<EvaluatedIndexEntry> secondaryIndexValues;
    for (const auto& metadata : secondaryIndexMetadata) {
        EvaluatedIndexEntry entry;
        if (!secondaryIndexEntry(
                metadata, tbl, actualValues, dbname, entry, this)) {
            lockManager_.unlock(tablename);
            return DBStatus::CORRUPTED_DATA;
        }
        secondaryIndexValues.push_back(std::move(entry));
    }
    std::vector<EvaluatedIndexEntry> compositeIndexValues;
    for (const auto& metadata : compositeIndexMetadata) {
        EvaluatedIndexEntry entry;
        if (!compositeIndexEntry(
                metadata, tbl, actualValues, dbname, entry, this)) {
            lockManager_.unlock(tablename);
            return DBStatus::CORRUPTED_DATA;
        }
        compositeIndexValues.push_back(std::move(entry));
    }

    // Check CHECK constraints before writing; collect deferrable deferred checks for commit-time validation.
    std::vector<size_t> deferredCheckCols;
    std::vector<const CheckConstraint*> deferredAdditionalChecks;
    for (size_t i = 0; i < tbl.len; ++i) {
        const Column& col = tbl.cols[i];
        if (col.checkExpr.empty()) continue;
        const bool deferred = transactionContext().inTransaction &&
            col.deferrable && isConstraintDeferred(
                col.checkConstraintName, col.initiallyDeferred);
        if (deferred) {
            deferredCheckCols.push_back(i);
            continue;
        }
        std::string err;
        if (!dbms::ExprHelper::evalCheck(
                col.checkExpr, actualValues, typeHints, &err, dbname, "", this)) {
            lockManager_.unlock(tablename);
            return err.empty() ? DBStatus::CHECK_VIOLATION
                               : DBStatus::INVALID_VALUE;
        }
    }
    for (const auto& check : tbl.additionalCheckConstraints) {
        if (check.expression.empty()) continue;
        const bool deferred = transactionContext().inTransaction &&
            check.deferrable &&
            isConstraintDeferred(
                check.name, check.initiallyDeferred);
        if (deferred) {
            deferredAdditionalChecks.push_back(&check);
            continue;
        }
        std::string err;
        if (!dbms::ExprHelper::evalCheck(
                check.expression, actualValues, typeHints, &err, dbname, "", this)) {
            lockManager_.unlock(tablename);
            return err.empty() ? DBStatus::CHECK_VIOLATION
                               : DBStatus::INVALID_VALUE;
        }
    }

    // Check EXCLUDE constraints before writing.  DEFERRABLE EXCLUDE
    // constraints currently deferred skip the immediate scan and queue a
    // commit-time re-check instead.
    const auto excludeConstraints = getExclusionConstraints(dbname, tablename);
    std::vector<const ExclusionConstraint*> deferredExcludes;

    // Check gap lock conflict (if any transaction holds a gap lock covering PK)
    if (tbl.hasPrimaryKey()) {
        std::string pkVal = tbl.buildPKValue(actualValues);
        if (!pkVal.empty() && lockManager_.isGapLocked(tablename, pkVal)) {
            lockManager_.unlock(tablename);
            return DBStatus::LOCK_CONFLICT;
        }
    }

    // Check foreign key references. DEFERRABLE FKs currently deferred skip
    // the immediate existence check and queue it for commit time.
    for (size_t fi = 0; fi < tbl.fkLen; ++fi) {
        const ForeignKey& fk = tbl.fks[fi];
        // Check if any FK column value is NULL (NULL is allowed in FKs)
        bool hasNull = false;
        for (const auto& colName : fk.colNames) {
            auto it = actualValues.find(colName);
            if (it == actualValues.end() ||
                actualNullColumns.count(colName) != 0) {
                hasNull = true;
                break;
            }
        }
        if (hasNull) continue;
        const bool statementSelfReference = transactionContext().inTransaction &&
            transactionContext().readView.commandIdVisibility &&
            fk.refTable == tablename;
        if (statementSelfReference ||
            (!fk.name.empty() && transactionContext().inTransaction &&
             isConstraintCurrentlyDeferred(dbname, tablename, fk.name))) {
            DeferredFkEntry e;
            e.fkIndex = fi;
            for (const auto& columnName : fk.colNames) {
                e.values.push_back(actualValues[columnName]);
            }
            deferredFkEntries.push_back(std::move(e));
            continue;
        }
        if (!tableExists(dbname, fk.refTable)) {
            lockManager_.unlock(tablename);
            return DBStatus::TABLE_NOT_FOUND;
        }
        TableSchema refTbl = getTableSchema(dbname, fk.refTable);
        if (fk.colNames.empty() ||
            fk.colNames.size() != fk.refCols.size()) {
            lockManager_.unlock(tablename);
            return DBStatus::CORRUPTED_DATA;
        }

        std::vector<size_t> referencedColumns;
        referencedColumns.reserve(fk.refCols.size());
        for (const auto& referencedName : fk.refCols) {
            size_t referencedColumn = refTbl.len;
            for (size_t candidate = 0; candidate < refTbl.len; ++candidate) {
                if (refTbl.cols[candidate].dataName == referencedName) {
                    referencedColumn = candidate;
                    break;
                }
            }
            if (referencedColumn >= refTbl.len) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            referencedColumns.push_back(referencedColumn);
        }

        // The new tuple is also a candidate referenced row for an immediate
        // self-reference. It has not reached the heap/PK index yet, but all
        // its defaults, generated values and SQL NULL bits are available.
        bool referencesPendingRow = fk.refTable == tablename;
        if (referencesPendingRow) {
            for (size_t valueIndex = 0;
                 valueIndex < referencedColumns.size(); ++valueIndex) {
                const std::string& referencedName = fk.refCols[valueIndex];
                const auto pendingValue = actualValues.find(referencedName);
                if (pendingValue == actualValues.end() ||
                    actualNullColumns.count(referencedName) != 0) {
                    referencesPendingRow = false;
                    break;
                }
                const Column& referencedColumn =
                    refTbl.cols[referencedColumns[valueIndex]];
                if (canonicalColumnKeyValue(referencedColumn, pendingValue->second) !=
                    canonicalColumnKeyValue(referencedColumn,
                        actualValues.at(fk.colNames[valueIndex]))) {
                    referencesPendingRow = false;
                    break;
                }
            }
        }
        if (referencesPendingRow) continue;

        std::vector<size_t> primaryColumns = refTbl.pkColIndices;
        if (primaryColumns.empty()) {
            for (size_t candidate = 0; candidate < refTbl.len; ++candidate) {
                if (refTbl.cols[candidate].isPrimaryKey) {
                    primaryColumns.push_back(candidate);
                }
            }
        }
        const bool referencesSinglePrimaryKey =
            referencedColumns.size() == 1 && primaryColumns.size() == 1 &&
            referencedColumns.front() == primaryColumns.front();
        if (referencesSinglePrimaryKey) {
            // Use the primary index only when the FK actually references the
            // table's sole PK column. A single-column FK may instead target a
            // UNIQUE non-PK column, in which case the PK index is unrelated.
            BPTree* refIdx = getPKIndex(dbname, fk.refTable);
            if (!refIdx) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            std::map<std::string, std::string> referencedKeyValues;
            referencedKeyValues[fk.refCols.front()] =
                actualValues.at(fk.colNames.front());
            int64_t referencedRid = -1;
            const auto lookup = refIdx->searchChecked(
                refTbl.buildPKValue(referencedKeyValues), referencedRid);
            if (lookup == BPTree::SearchResult::Error) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            if (lookup == BPTree::SearchResult::NotFound) {
                lockManager_.unlock(tablename);
                return DBStatus::FOREIGN_KEY_VIOLATION;
            }
            // A physical B+Tree key is a 20-byte prefix, not proof of SQL
            // equality. Recheck the visible heap datum before accepting an FK.
            std::string referencedRow;
            bool readFailed = false;
            const auto& context = transactionContext();
            const ReadView* view = context.inTransaction && context.txnDB == dbname
                ? &context.readView : nullptr;
            if (!readIndexedRowByRid(dbname, fk.refTable, referencedRid,
                    referencedRow, refTbl, view, &readFailed)) {
                lockManager_.unlock(tablename);
                return readFailed ? DBStatus::IO_ERROR : DBStatus::FOREIGN_KEY_VIOLATION;
            }
            const size_t referencedColumn = referencedColumns.front();
            if (!foreignKeyColumnValuesEqual(refTbl.cols[referencedColumn],
                    extractColumnValue(referencedRow, refTbl, referencedColumn, dbname),
                    actualValues.at(fk.colNames.front()))) {
                lockManager_.unlock(tablename);
                return DBStatus::FOREIGN_KEY_VIOLATION;
            }
        } else {
            // Non-PK and composite references must compare the declared
            // referenced columns, never an unrelated physical index.
            bool found = false;
            if (!forEachRow(dbname, fk.refTable, [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
                if (found) return;
                std::string row(data, len);
                for (size_t valueIndex = 0;
                     valueIndex < referencedColumns.size(); ++valueIndex) {
                    if (dbms::detail::storedRowColumnIsNull(*this, dbname, fk.refTable, refTbl,
                            encodeRid(pageId, slotId), referencedColumns[valueIndex])) {
                        return;
                    }
                    const Column& referencedColumn =
                        refTbl.cols[referencedColumns[valueIndex]];
                    const std::string storedValue = canonicalColumnKeyValue(
                        referencedColumn,
                        extractColumnValue(row, refTbl,
                                           referencedColumns[valueIndex],
                                           dbname));
                    const std::string localValue = canonicalColumnKeyValue(
                        referencedColumn,
                        actualValues.at(fk.colNames[valueIndex]));
                    if (storedValue != localValue) return;
                }
                found = true;
            })) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            if (!found) {
                lockManager_.unlock(tablename);
                return DBStatus::FOREIGN_KEY_VIOLATION;
            }
        }
    }

    // Determine target partition for partitioned tables
    std::string targetPartition;
    std::string targetSubPartition;
    if (tbl.partitionType != TableSchema::PartitionType::None) {
        auto pit = actualValues.find(tbl.partitionKey);
        if (pit != actualValues.end() &&
            actualNullColumns.count(tbl.partitionKey) == 0) {
            targetPartition = getPartitionName(tbl, pit->second);
        }
        if (targetPartition.empty()) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    }
    if (tbl.subPartitionType != TableSchema::PartitionType::None) {
        auto spit = actualValues.find(tbl.subPartitionKey);
        if (spit != actualValues.end() &&
            actualNullColumns.count(tbl.subPartitionKey) == 0) {
            targetSubPartition = getSubPartitionName(tbl, spit->second);
        }
        if (targetSubPartition.empty()) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    }
    const uint32_t heapFork = targetPartition.empty()
        ? 0
        : partitionForkNumber(targetPartition, targetSubPartition);
    if (!targetPartition.empty() &&
        !partitionForkIsUnique(
            tbl, targetPartition, targetSubPartition)) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // All checks that operate directly on logical SQL values have passed.
    // Allocate external values only now, and make every failure before the
    // heap tuple becomes reachable clean up those allocations.
    std::map<std::string, std::string> storedValues = actualValues;
    if (!prepareToastValues(dbname, tablename, tbl, storedValues)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    const uint64_t creatorTxnId = transactionContext().inTransaction
        ? transactionContext().currentTxnId : 0;
    std::set<size_t> physicalNullColumns;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (storedValues.find(tbl.cols[i].dataName) == storedValues.end() ||
            actualNullColumns.count(tbl.cols[i].dataName) != 0) {
            physicalNullColumns.insert(i);
        }
    }
    std::string rowBuffer = buildRowBuffer(
        tbl, storedValues, creatorTxnId, &physicalNullColumns);
    if (creatorTxnId != 0) {
        setRowCid(rowBuffer.data(), rowBuffer.size(), tbl.formatVersion,
                  transactionContext().currentCommandId);
    }
    std::string strippedRow = stripRowHeader(
        rowBuffer, tbl.formatVersion, tbl.len);
    const auto insertedColumnIsNull = [&](size_t columnIndex) {
        if (columnIndex >= tbl.len ||
            tbl.cols[columnIndex].generatedKind == 'v' ||
            !usesHeapTupleHeader(tbl.formatVersion) ||
            rowBuffer.size() < sizeof(HeapTupleHeaderData)) {
            return false;
        }
        return dbms::isNull(castHeapHeader(rowBuffer.data()),
                            static_cast<int>(columnIndex));
    };
    const auto failBeforeHeapInsert = [&](DBStatus status) {
        deleteToastForRow(dbname, tablename, strippedRow);
        lockManager_.unlock(tablename);
        return status;
    };

    // EXCLUDE operates on a row buffer, so evaluate it after building the
    // compact physical image.  A rejection still owns and removes its TOAST
    // values through failBeforeHeapInsert().
    for (const auto& ec : excludeConstraints) {
        if (!ec.name.empty() && transactionContext().inTransaction &&
            isConstraintCurrentlyDeferred(dbname, tablename, ec.name)) {
            deferredExcludes.push_back(&ec);
            continue;
        }
        bool scanFailed = false;
        if (checkExclusionConflict(
                dbname, tablename, ec, strippedRow, -1, &scanFailed)) {
            return failBeforeHeapInsert(DBStatus::EXCLUSION_VIOLATION);
        }
        if (scanFailed) return failBeforeHeapInsert(DBStatus::IO_ERROR);
    }

    // Check if row fits in a page (page capacity = PAGE_SIZE - header - slot)
    constexpr size_t MAX_ROW_SIZE = PgPage::PAGE_SIZE -
        sizeof(PgPage::PageHeaderData) - sizeof(PgPage::ItemIdData);
    if (rowBuffer.size() > MAX_ROW_SIZE) {
        return failBeforeHeapInsert(DBStatus::INVALID_VALUE);
    }

    // Write row into page-based storage
    PageAllocator* pa = nullptr;
    std::shared_ptr<PageAllocator> partPa;
    if (!targetPartition.empty() && !targetSubPartition.empty()) {
        partPa = acquireSharedHeap(dbname, partitionDataPath(dbname, tablename, targetPartition, targetSubPartition), tbl.rowSize(), pageSizeForFormatVersion(tbl.formatVersion), tbl.formatVersion,
            dbname + "/" + tablename + "#" + targetPartition + "#" + targetSubPartition);
        if (!partPa) {
            return failBeforeHeapInsert(DBStatus::INVALID_VALUE);
        }
        pa = partPa.get();
    } else if (!targetPartition.empty()) {
        partPa = acquireSharedHeap(dbname, partitionDataPath(dbname, tablename, targetPartition), tbl.rowSize(), pageSizeForFormatVersion(tbl.formatVersion), tbl.formatVersion,
            dbname + "/" + tablename + "#" + targetPartition);
        if (!partPa) {
            return failBeforeHeapInsert(DBStatus::INVALID_VALUE);
        }
        pa = partPa.get();
    } else {
        pa = getPageAllocator(dbname, tablename);
    }
    if (!pa) {
        return failBeforeHeapInsert(DBStatus::IO_ERROR);
    }
    if (!markSpecializedIndexesBeforeMutation(dbname, tablename)) {
        return failBeforeHeapInsert(DBStatus::IO_ERROR);
    }
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    {
        uint32_t numPages = pa->numPages();
        bool inserted = false;
        size_t actualRowSize = rowBuffer.size();
        uint8_t minPercent = static_cast<uint8_t>(std::min(size_t(100), actualRowSize * 100 / pa->pageSize() + 1));
        uint8_t fillfactor = getFillFactor(tbl);

        // Try FSM first for fast page lookup
        if (numPages > 1) {
            FreeSpaceMap* fsm = getFSM(dbname, tablename);
            uint32_t candidate = fsm->findPage(minPercent, 1);
            if (candidate > 0 && candidate < numPages) {
                if (!lockManager_.pageLockExclusive(dbname, tablename, candidate)) {
                    return failBeforeHeapInsert(DBStatus::LOCK_CONFLICT);
                }
                char* buf = pa->fetchPage(candidate);
                if (!buf) {
                    lockManager_.pageUnlock(dbname, tablename, candidate);
                    return failBeforeHeapInsert(DBStatus::IO_ERROR);
                }
                PageWrapper page(buf, pa->pageSize(), tbl.formatVersion);
                if (page.canFit(actualRowSize) &&
                    pageFitsWithFillfactor(page, actualRowSize, pa->pageSize(), fillfactor)) {
                    const Lsn beforeLsn = walPageImage(
                        dbname, tablename, candidate, buf,
                        pa->pageSize(), true, heapFork);
                    if (beforeLsn == INVALID_LSN) {
                        pa->unpinPage(candidate);
                        lockManager_.pageUnlock(
                            dbname, tablename, candidate);
                        return failBeforeHeapInsert(DBStatus::IO_ERROR);
                    }
                    if (page.insert(rowBuffer.data(), actualRowSize, slotId)) {
                        pageId = candidate;
                        inserted = true;
                        pa->markDirty(candidate);
                        size_t freePct = page.freeSpace() * 100 / pa->pageSize();
                        fsm->setFreePercent(candidate, static_cast<uint8_t>(freePct));
                        getVM(dbname, tablename)->setAllVisible(candidate, false);
                    }
                }
                pa->unpinPage(candidate);
                lockManager_.pageUnlock(dbname, tablename, candidate);
            }
        }

        // Fallback: sequential scan
        for (uint32_t pid = 1; pid < numPages && !inserted; ++pid) {
            if (!lockManager_.pageLockExclusive(dbname, tablename, pid)) {
                return failBeforeHeapInsert(DBStatus::LOCK_CONFLICT);
            }
            char* buf = pa->fetchPage(pid);
            if (!buf) {
                lockManager_.pageUnlock(dbname, tablename, pid);
                return failBeforeHeapInsert(DBStatus::IO_ERROR);
            }
            PageWrapper page(buf, pa->pageSize(), tbl.formatVersion);
            if (page.canFit(actualRowSize) &&
                pageFitsWithFillfactor(page, actualRowSize, pa->pageSize(), fillfactor)) {
                const Lsn beforeLsn = walPageImage(
                    dbname, tablename, pid, buf, pa->pageSize(),
                    true, heapFork);
                if (beforeLsn == INVALID_LSN) {
                    pa->unpinPage(pid);
                    lockManager_.pageUnlock(dbname, tablename, pid);
                    return failBeforeHeapInsert(DBStatus::IO_ERROR);
                }
                if (page.insert(rowBuffer.data(), actualRowSize, slotId)) {
                    pageId = pid;
                    inserted = true;
                }
            }
            if (inserted) {
                pa->markDirty(pid);
                size_t freePct = page.freeSpace() * 100 / pa->pageSize();
                getFSM(dbname, tablename)->setFreePercent(pid, static_cast<uint8_t>(freePct));
                getVM(dbname, tablename)->setAllVisible(pid, false);
            }
            pa->unpinPage(pid);
            lockManager_.pageUnlock(dbname, tablename, pid);
        }

        if (!inserted) {
            pageId = pa->allocPage();
            if (pageId == 0) {
                return failBeforeHeapInsert(DBStatus::IO_ERROR);
            }
            if (!lockManager_.pageLockExclusive(dbname, tablename, pageId)) {
                return failBeforeHeapInsert(DBStatus::LOCK_CONFLICT);
            }
            char* buf = pa->fetchPage(pageId);
            if (!buf) {
                lockManager_.pageUnlock(dbname, tablename, pageId);
                return failBeforeHeapInsert(DBStatus::IO_ERROR);
            }
            PageWrapper page(buf, pa->pageSize(), tbl.formatVersion);
            const Lsn beforeLsn = walPageImage(
                dbname, tablename, pageId, buf, pa->pageSize(),
                true, heapFork);
            if (beforeLsn == INVALID_LSN) {
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                return failBeforeHeapInsert(DBStatus::IO_ERROR);
            }
            if (!page.insert(rowBuffer.data(), actualRowSize, slotId)) {
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                return failBeforeHeapInsert(DBStatus::INVALID_VALUE);
            }
            pa->markDirty(pageId);
            size_t freePct = page.freeSpace() * 100 / pa->pageSize();
            getFSM(dbname, tablename)->setFreePercent(pageId, static_cast<uint8_t>(freePct));
            getVM(dbname, tablename)->setAllVisible(pageId, false);
            pa->unpinPage(pageId);
            lockManager_.pageUnlock(dbname, tablename, pageId);
        }
    }

    int64_t rid = encodeRid(pageId, slotId);

    // Queue deferred EXCLUDE constraints for commit-time re-validation.
    if (transactionContext().inTransaction && !deferredExcludes.empty()) {
        for (const ExclusionConstraint* ec : deferredExcludes) {
            DeferredCheck dc;
            dc.kind = DeferredCheck::Kind::Exclude;
            dc.dbname = dbname;
            dc.tablename = tablename;
            dc.rid = rid;
            dc.constraintName = ec->name;
            dc.exceptRid = rid;
            dc.excludeElements = ec->elements;
            dc.excludeWhere = ec->wherePredicate;
            transactionContext().deferredChecks[transactionContext().currentTxnId].push_back(
                std::move(dc));
        }
    }
    // Queue deferred CHECK constraints for commit-time validation.
    if (transactionContext().inTransaction && !deferredCheckCols.empty()) {
        for (size_t ci : deferredCheckCols) {
            DeferredCheck check;
            check.kind = DeferredCheck::Kind::Check;
            check.dbname = dbname;
            check.tablename = tablename;
            check.rid = rid;
            check.constraintName = tbl.cols[ci].checkConstraintName;
            check.colIdx = ci;
            transactionContext()
                .deferredChecks[transactionContext().currentTxnId]
                .push_back(std::move(check));
        }
    }
    if (transactionContext().inTransaction &&
        !deferredAdditionalChecks.empty()) {
        for (const CheckConstraint* storedCheck : deferredAdditionalChecks) {
            DeferredCheck check;
            check.kind = DeferredCheck::Kind::Check;
            check.dbname = dbname;
            check.tablename = tablename;
            check.rid = rid;
            check.constraintName = storedCheck->name;
            check.checkExpr = storedCheck->expression;
            transactionContext()
                .deferredChecks[transactionContext().currentTxnId]
                .push_back(std::move(check));
        }
    }
    // Queue deferred UNIQUE violations for commit-time validation. The queued
    // row is excluded via exceptRid; any OTHER row still holding the same
    // value at commit fails the transaction.
    if (transactionContext().inTransaction && !deferredUniqueCols.empty()) {
        for (size_t ci : deferredUniqueCols) {
            auto vit = actualValues.find(tbl.cols[ci].dataName);
            if (vit == actualValues.end() ||
                actualNullColumns.count(tbl.cols[ci].dataName) != 0) {
                continue;
            }
            std::string cname = tablename + "_" + tbl.cols[ci].dataName + "_key";
            for (size_t ui = 0; ui < tbl.uniqueConstraints.size(); ++ui) {
                for (size_t uj = 0; uj < tbl.uniqueConstraints[ui].size(); ++uj) {
                    if (tbl.uniqueConstraints[ui][uj] == ci) {
                        if (ui < tbl.uniqueConstraintNames.size()
                            && !tbl.uniqueConstraintNames[ui].empty()) {
                            cname = tbl.uniqueConstraintNames[ui];
                        }
                        break;
                    }
                }
            }
            DeferredCheck check;
            check.kind = DeferredCheck::Kind::Unique;
            check.dbname = dbname;
            check.tablename = tablename;
            check.rid = rid;
            check.constraintName = cname;
            check.colIdx = ci;
            check.uniqueCol = tbl.cols[ci].dataName;
            check.payloadValue = vit->second;
            check.exceptRid = rid;
            transactionContext()
                .deferredChecks[transactionContext().currentTxnId]
                .push_back(std::move(check));
        }
    }
    // Queue deferred FK existence checks after the row has a stable RID.
    if (transactionContext().inTransaction && !deferredFkEntries.empty()) {
        for (const auto& e : deferredFkEntries) {
            if (e.fkIndex >= tbl.fkLen) continue;
            const ForeignKey& fk = tbl.fks[e.fkIndex];
            DeferredCheck check;
            check.kind = DeferredCheck::Kind::ForeignKey;
            check.dbname = dbname;
            check.tablename = tablename;
            check.rid = rid;
            check.constraintName = fk.name;
            check.colIdx = 0;
            check.uniqueCol = fk.colNames.empty() ? "" : fk.colNames.front();
            check.payloadValue = e.values.empty() ? "" : e.values.front();
            check.refTable = fk.refTable;
            check.refCol = fk.refCols.empty() ? "" : fk.refCols.front();
            check.fkPayloadValues = e.values;
            check.fkLocalCols = fk.colNames;
            check.fkRefCols = fk.refCols;
            transactionContext()
                .deferredChecks[transactionContext().currentTxnId]
                .push_back(std::move(check));
        }
    }

    // Log for transaction rollback
    if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
        logTxnInsert(tablename, rid, strippedRow);
    }

    // Index writes are part of the INSERT atomicity boundary.  A failed
    // access-method mutation must never leave a heap tuple without a matching
    // index entry (or leave a stale entry after a non-transactional INSERT).
    auto abortIndexUpdate = [&]() -> DBStatus {
        if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
            // The INSERT is already in txnLog. The public insert() wrapper
            // owns a statement savepoint, so leave earlier transaction work
            // intact and let it undo this partially completed index update.
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }

        // Embedded callers may use insert() outside an explicit transaction.
        // Remove every index entry for this RID before removing the heap row.
        // Acquire the page lock before any cleanup mutation.  If it cannot be
        // acquired, leave the tuple and indexes untouched rather than
        // returning with a partially cleaned row.
        if (!lockManager_.pageLockExclusive(dbname, tablename, pageId)) {
            lockManager_.unlock(tablename);
            return DBStatus::LOCK_CONFLICT;
        }
        const std::string pkVal = tbl.buildPKValue(actualValues);
        if (tbl.hasPrimaryKey()) {
            if (BPTree* idx = getPKIndex(dbname, tablename); idx && !pkVal.empty()) {
                idx->remove(pkVal);
            }
        }
        for (const auto& entry : secondaryIndexValues) {
            if (!entry.included || entry.key.empty()) continue;
            if (BPTree* idx = getSecondaryIndex(
                    dbname, tablename, entry.name); idx) {
                idx->removeMulti(entry.key, rid);
            }
        }
        for (const auto& entry : compositeIndexValues) {
            if (!entry.included || entry.key.empty()) continue;
            if (BPTree* idx = getCompositeIndexTree(
                    dbname, tablename, entry.name); idx) {
                idx->removeMulti(entry.key, rid);
            }
        }
        for (const auto& colname : getHashIndexedColumns(dbname, tablename)) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx >= tbl.len) continue;
            if (HashIndex* idx = getHashIndex(dbname, tablename, colname); idx) {
                const std::string val = canonicalKeyValueFromRowMap(
                    actualValues, tbl, colname);
                if (hashKeyIncluded(tbl.cols[colIdx], val,
                        actualNullColumns.count(colname) != 0))
                    idx->remove(val, rid);
            }
        }
        for (const auto& colname : getBloomIndexedColumns(dbname, tablename)) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx >= tbl.len) continue;
            if (BloomIndex* idx = getBloomIndex(
                    dbname, tablename, colname); idx) {
                const std::string val = canonicalKeyValueFromRowMap(
                    actualValues, tbl, colname);
                if (!val.empty()) idx->remove(val, rid);
            }
        }
        deleteRowToast(dbname, tablename, rid);
        if (char* pageBuf = pa->fetchPage(pageId)) {
            PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
            walPageImage(dbname, tablename, pageId, pageBuf,
                         pa->pageSize(), true, heapFork);
            page.remove(slotId);
            pa->markDirty(pageId);
            Lsn lsn = walPageImage(dbname, tablename, pageId, pageBuf,
                                   pa->pageSize(), false, heapFork);
            if (lsn != INVALID_LSN) {
                setPageLsnAndChecksum(pageBuf, lsn);
                pa->markDirty(pageId);
            }
            pa->flush();
            pa->unpinPage(pageId);
        }
        lockManager_.pageUnlock(dbname, tablename, pageId);
        // A specialized rebuild may have published some replacement files
        // before failing. Rebuild once more from the reverted heap; if the
        // underlying I/O error persists, its dirty marker keeps reads on the
        // safe heap-scan path.
        (void)rebuildSpecializedIndexes(dbname, tablename);
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    };

    // For PostgreSQL-style tuples, set ctid to point to self after insertion.
    // Keep this inside the atomic cleanup scope: a page-lock failure after the
    // heap insert must remove the just-created tuple rather than return while
    // leaving an unindexed row behind.
    if (usesHeapTupleHeader(tbl.formatVersion)) {
        if (!lockManager_.pageLockExclusive(dbname, tablename, pageId)) {
            return abortIndexUpdate();
        }
        bool finalized = false;
        char* buf = pa->fetchPage(pageId);
        if (buf) {
            // Stage the tuple/header update in a private page image. The
            // shared buffer must not expose a new ctid unless its matching
            // after-image has entered WAL successfully.
            std::vector<char> stagedPage(
                buf, buf + pa->pageSize());
            PageWrapper page(
                stagedPage.data(), pa->pageSize(), tbl.formatVersion);
            const char* data = nullptr;
            size_t len = 0;
            if (page.read(slotId, data, len)) {
                ItemPointer selfCtid{ pageId, static_cast<OffsetNumber>(slotId + 1) };
                std::string mutableRow(data, len);
                setRowCtid(mutableRow.data(), mutableRow.size(), tbl.formatVersion, selfCtid);
                if (page.update(
                        slotId, mutableRow.data(), mutableRow.size())) {
                    const Lsn lsn = walPageImage(
                        dbname, tablename, pageId, stagedPage.data(),
                        pa->pageSize(), false, heapFork);
                    if (lsn != INVALID_LSN) {
                        std::memcpy(
                            buf, stagedPage.data(), pa->pageSize());
                        setPageLsnAndChecksum(buf, lsn);
                        pa->markDirty(pageId);
                        finalized = true;
                    }
                }
            }
            pa->unpinPage(pageId);
        }
        lockManager_.pageUnlock(dbname, tablename, pageId);
        if (!finalized) return abortIndexUpdate();
    }

    // Update B+ tree PK index.
    {
        BPTree* idx = getPKIndex(dbname, tablename);
        std::string pkVal = tbl.buildPKValue(actualValues);
        if (tbl.hasPrimaryKey() && !pkVal.empty() && (!idx || !idx->insert(pkVal, rid))) {
            return abortIndexUpdate();
        }
    }
    // Update ordinary and expression secondary indexes.
    for (const auto& entry : secondaryIndexValues) {
        BPTree* idx = getSecondaryIndex(dbname, tablename, entry.name);
        if (!idx || (entry.included && !entry.key.empty() &&
                     !idx->insertMulti(entry.key, rid))) {
            return abortIndexUpdate();
        }
    }
    // Update composite indexes.
    for (const auto& entry : compositeIndexValues) {
        BPTree* index = getCompositeIndexTree(
            dbname, tablename, entry.name);
        if (!index || (entry.included && !entry.key.empty() &&
                       !index->insertMulti(entry.key, rid))) {
            return abortIndexUpdate();
        }
    }
    // Update hash indexes.
    {
        auto hashCols = getHashIndexedColumns(dbname, tablename);
        for (const auto& colname : hashCols) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx >= tbl.len) return abortIndexUpdate();
            HashIndex* hidx = getHashIndex(dbname, tablename, colname);
            std::string val = canonicalKeyValueFromRowMap(
                actualValues, tbl, colname);
            if (!hidx || (hashKeyIncluded(tbl.cols[colIdx], val,
                    actualNullColumns.count(colname) != 0) &&
                    !hidx->insert(val, rid))) {
                return abortIndexUpdate();
            }
        }
    }
    // Update bloom indexes.
    {
        auto bloomCols = getBloomIndexedColumns(dbname, tablename);
        for (const auto& colname : bloomCols) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx >= tbl.len) return abortIndexUpdate();
            BloomIndex* bidx = getBloomIndex(dbname, tablename, colname);
            std::string val = canonicalKeyValueFromRowMap(
                actualValues, tbl, colname);
            if (!bidx || (!val.empty() && !bidx->insert(val, rid))) {
                return abortIndexUpdate();
            }
        }
    }
    // Partition INSERT uses a statement-local allocator, whereas the
    // whole-table specialized builders reopen partition files. Publish its
    // dirty pages first so that scan observes the tuple just indexed above.
    if (partPa && !partPa->flush()) {
        return abortIndexUpdate();
    }
    if (!maintainSpecializedIndexesAfterMutation(dbname, tablename)) {
        return abortIndexUpdate();
    }
    // Logical decoding: buffer the change for streaming at commit.
    if (captureLogicalInsert) {
        auto& txn = transactionContext();
        if (txn.inTransaction) {
            // Retain the row's own NULL bitmap, including dependencies of
            // virtual generated columns; text bytes never imply SQL NULL.
            std::vector<bool> nulls(tbl.len, false);
            for (const size_t column : physicalNullColumns) nulls[column] = true;
            BufferedNullRowBinding binding(tbl, nulls);
            std::vector<LogicalDecoder::Cell> cells;
            cells.reserve(tbl.len);
            for (size_t i = 0; i < tbl.len; ++i) {
                bool isNull = false;
                const auto value = extractColumnValue(
                    strippedRow, tbl, i, dbname, true, &isNull);
                cells.emplace_back(tbl.cols[i].dataType,
                    isNull ? std::nullopt : std::optional<std::string>(value));
            }
            txn.txnLogicalChanges.push_back(
                {tablename, 0, "", LogicalDecoder::encodeRow(cells)});
        }
    }
    lockManager_.unlock(tablename);

    // INSERT RETURNING observes the tuple after BEFORE INSERT triggers and
    // generated columns have been applied, but before AFTER triggers run.
    // Capture the logical values here so callers do not need a second query.
    if (insertedRows || owningRows) {
        SqlRow returnedValues;
        std::shared_ptr<OwningRowImage> owning;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (insertedColumnIsNull(i)) {
                returnedValues[tbl.cols[i].dataName] = std::nullopt;
            } else {
                std::optional<ExprValue> value;
                bool computedNull=false;
                auto text=extractColumnValue(strippedRow,tbl,i,dbname,true,&computedNull,
                    owningRows && tbl.cols[i].generatedKind=='v'?&value:nullptr);
                returnedValues[tbl.cols[i].dataName]=computedNull?SqlCell{}:SqlCell{std::move(text)};
                retainGeneratedValue(owning,false,tbl.cols[i].dataName,value);
            }
        }
        if (insertedRows) insertedRows->push_back(std::move(returnedValues));
        if (owningRows) owningRows->push_back(std::move(owning));
    }

    // Fire AFTER INSERT triggers
    if (triggerExecutor_) {
        auto triggers = filterTriggers(
            operationTriggers, tablename, "after", "insert");
        for (const auto& trg : triggers) {
            // Evaluate WHEN condition if present
            if (!trg.whenCondition.empty() && whenEvaluator_) {
                std::string cond = trg.whenCondition;
                if (trg.forEachRow) {
                    for (const auto& [col, val] : actualValues) {
                        std::string placeholder = "NEW." + col;
                        size_t pos = 0;
                        while ((pos = cond.find(placeholder, pos)) != std::string::npos) {
                            cond.replace(pos, placeholder.size(), val);
                            pos += val.size();
                        }
                    }
                }
                if (!whenEvaluator_(cond, actualValues, {})) continue;
            }
            std::string action = trg.action;
            if (trg.forEachRow) {
                for (const auto& [col, val] : actualValues) {
                    std::string placeholder = "NEW." + col;
                    size_t pos = 0;
                    while ((pos = action.find(placeholder, pos)) != std::string::npos) {
                        action.replace(pos, placeholder.size(), val);
                        pos += val.size();
                    }
                }
            }
            // Trigger diagnostic variables
            {
                auto replaceVar = [&](const std::string& var, const std::string& val) {
                    size_t pos = 0;
                    while ((pos = action.find(var, pos)) != std::string::npos) {
                        action.replace(pos, var.size(), val);
                        pos += val.size();
                    }
                };
                replaceVar("tg_name", trg.name);
                replaceVar("tg_when", trg.timing);
                replaceVar("tg_level", trg.forEachRow ? "ROW" : "STATEMENT");
                replaceVar("tg_op", "INSERT");
                replaceVar("tg_relname", trg.tableName);
            }
            stageExecFunctionCtx(*this, trg.name, trg.timing,
                              "INSERT", trg.tableName,
                              trg.forEachRow, &actualValues, nullptr, &tbl);
            if (triggerExecutor_(action)) {
                if (transactionContext().inTransaction &&
                    transactionContext().txnDB == dbname) {
                    // The public insert() wrapper owns the statement
                    // savepoint and will remove both this row and any trigger
                    // side effects recorded after it.
                    return DBStatus::IO_ERROR;
                }
                // Embedded non-transactional callers still need the local
                // heap/index compensation path. It expects the table intent
                // lock that was released before running AFTER triggers.
                if (!lockManager_.lockIntentExclusive(tablename)) {
                    return DBStatus::LOCK_CONFLICT;
                }
                return abortIndexUpdate();
            }
        }
    }

    recordModification(dbname, tablename, 1);
    dbms::recordTableMutation(dbname, tablename, dbms::TableMutation::Insert, 1);
    maybeAutoAnalyze(dbname, tablename);
    return DBStatus::OK;
}

std::vector<StorageEngine::Condition> StorageEngine::parseConditions(
    const std::vector<std::string>& cstr) {
    std::vector<Condition> conds;
    auto decodeSqlIdentifier = [](const std::string& value) {
        if (value.size() < 2 || value.front() != '"' ||
            value.back() != '"') return value;
        std::string decoded;
        decoded.reserve(value.size() - 2);
        for (size_t i = 1; i + 1 < value.size(); ++i) {
            if (value[i] == '"') {
                if (i + 2 >= value.size() || value[i + 1] != '"') {
                    return value;
                }
                ++i;
            }
            decoded += value[i];
        }
        return decoded;
    };
    // Strip one level of single quotes from every space-separated token:
    // "betweenid 'b' 'c'" -> value "b c" (comparisons must not see quotes).
    auto unquoteTokens = [&](const std::string& v, bool decodeBitLiteral) {
        std::string out;
        std::istringstream iss(v);
        std::string tok;
        bool first = true;
        while (iss >> tok) {
            tok = decodeSqlLiteral(std::move(tok),decodeBitLiteral);
            if (!first) out += ' ';
            out += tok;
            first = false;
        }
        return out;
    };
    const auto listOperands = [&](const std::string& raw, bool apiCondition, Condition& condition) {
        condition.decodedLiteralRhs=apiCondition;
        if(!apiCondition)for(const auto& token:SQLParser::tokenize(raw))
            if(decodeBitPredicateLiteral(token)) {
                // Retain literal syntax/type, empty elements and SQL NULL.
                // A whitespace-joined decoded string cannot represent them.
                condition.patternType="bit";
                condition.decodedLiteralRhs=true;
                condition.value=raw;
                return;
            }
        condition.value=unquoteTokens(raw,false);
    };
    for (const auto& input : cstr) {
        const bool apiCondition = input.rfind("apicond ", 0) == 0;
        const std::string s = apiCondition ? input.substr(8) : input;
        if (s.empty()) continue;
        Condition c;
        if (s.rfind("typedexpr ", 0) == 0) {
            c.op = "typedexpr";
            c.value = s.substr(10);
            conds.push_back(std::move(c));
            continue;
        }
        bool parsedPattern = false;
        for (const std::string prefix : {"notsimilarto","notsimilar","notilike","notlike",
                                         "similarto","similar","ilike","like"}) {
            if (s.compare(0,prefix.size(),prefix) != 0) continue;
            size_t begin = prefix.size();
            while (begin < s.size() && std::isspace(static_cast<unsigned char>(s[begin]))) ++begin;
            size_t space = begin;
            char quote = 0; size_t depth = 0;
            for (;space<s.size();++space) {
                const char ch=s[space];
                if (quote) {
                    if (ch==quote) {
                        if (space+1<s.size() && s[space+1]==quote) { ++space; continue; }
                        quote=0;
                    }
                } else if (ch=='\'' || ch=='"') quote=ch;
                else if (ch=='(') ++depth;
                else if (ch==')' && depth) --depth;
                else if (!depth && std::isspace(static_cast<unsigned char>(ch))) break;
            }
            if (space == s.size()) throw DbError("42601", "missing stored pattern operand");
            c.op = storedPatternOperator(prefix);
            c.colName = s.substr(begin,space-begin);
            std::string raw = trim(s.substr(space+1));
            c.decodedLiteralRhs = apiCondition;
            if (!apiCondition) {
                // Parse operand syntax only. Physical rows remain native data.
                const std::string operation = c.op == "similar" ? "SIMILAR TO" :
                    c.op == "notsimilar" ? "NOT SIMILAR TO" :
                    c.op == "notlike" ? "NOT LIKE" : c.op == "notilike" ? "NOT ILIKE" : c.op;
                SQLParser parser;
                auto parsed = parser.parse("SELECT NULL " + operation + " " + raw);
                auto* select = parsed.success ? dynamic_cast<SelectStmt*>(parsed.stmt.get()) : nullptr;
                const Expr* pattern = nullptr; const Expr* escape = nullptr;
                if (select && select->selectList.size()==1 && !select->fromClause) {
                    const Expr* expression = select->selectList.front().expr.get();
                    if (const auto* binary=dynamic_cast<const BinaryOpExpr*>(expression)) pattern=binary->right.get();
                    else if (const auto* call=dynamic_cast<const FunctionCallExpr*>(expression);
                             call && call->args.size()==3 && SQLParser::toLower(call->funcName).find("escape")!=std::string::npos) {
                        pattern=call->args[1].get(); escape=call->args[2].get();
                    }
                }
                const auto decode = [&](const Expr* operand,std::string& datum,
                                        std::string& type,bool& isNull,bool& literal) {
                    if (!operand) return false;
                    if (const auto* reference=dynamic_cast<const ColumnRefExpr*>(operand)) {
                        datum=reference->toString(); literal=false; return true;
                    }
                    const Expr* leaf=operand;
                    for (;;) {
                        if (const auto* cast=dynamic_cast<const CastExpr*>(leaf)) leaf=cast->operand.get();
                        else if (const auto* binary=dynamic_cast<const BinaryOpExpr*>(leaf);binary && binary->op=="::") leaf=binary->left.get();
                        else break;
                    }
                    if (!dynamic_cast<const LiteralExpr*>(leaf)) return false;
                    ExprEvaluator evaluator; const auto value=evaluator.eval(operand,{});
                    datum=value.value;type=ExprHelper::inferParsedInputType(operand,{});
                    isNull=value.isNull;literal=true;return true;
                };
                bool decoded=decode(pattern,c.value,c.patternType,c.patternIsNull,c.decodedLiteralRhs);
                if (decoded && escape) {
                    std::string value; bool literal=false;
                    decoded=decode(escape,value,c.patternEscapeType,c.patternEscapeIsNull,literal);
                    if (literal) c.patternEscape=std::move(value);
                    else c.patternEscapeColumn=std::move(value);
                }
                if (pattern && !decoded) {
                    c.value=c.colName+" "+operation+" "+raw;
                    c.colName.clear();c.op="typedexpr";
                } else if (!decoded) c.value=decodeSqlLiteral(raw);
            } else c.value=decodeSqlLiteral(raw);
            // Quoted compact values have always been literal data, including
            // the four-byte string NULL and values equal to column names.
            if (!raw.empty() && raw.front() == '\'') c.decodedLiteralRhs = true;
            conds.push_back(std::move(c)); parsedPattern = true; break;
        }
        if (parsedPattern) continue;
        // Handle LIKE operator
        // Accept both "notlike<col> <val>" (glued, from modifyLogic's
        // compact path) and "notlike <col> <val>" (spaced, from splitConds
        // substrings).
        if (s.size() >= 7 && s.substr(0, 7) == "notlike") {
            c.op = "notlike";
            size_t off = 7;
            if (off < s.size() && s[off] == ' ') ++off;
            size_t sp = s.find(' ', off);
            if (sp != std::string::npos) {
                c.colName = s.substr(off, sp - off);
                c.value = unquoteTokens(s.substr(sp + 1),!apiCondition);
            }
            conds.push_back(c);
            continue;
        }
        if (s.size() >= 7 && s.substr(0, 7) == "between") {
            c.op = "between";
            size_t off = 7;
            if (off < s.size() && s[off] == ' ') ++off;
            size_t sp = s.find(' ', off);
            if (sp != std::string::npos) {
                c.colName = s.substr(off, sp - off);
                listOperands(s.substr(sp+1),apiCondition,c);
            }
            conds.push_back(c);
            continue;
        }
        if (s.size() >= 10 && s.substr(0, 10) == "notbetween") {
            c.op = "notbetween";
            size_t off = 10;
            if (off < s.size() && s[off] == ' ') ++off;
            size_t sp = s.find(' ', off);
            if (sp != std::string::npos) {
                c.colName = s.substr(off, sp - off);
                listOperands(s.substr(sp+1),apiCondition,c);
            }
            conds.push_back(c);
            continue;
        }
        if (s.size() >= 8 && s.substr(0, 8) == "notilike") {
            c.op = "notilike";
            size_t sp = s.find(' ', 8);
            if (sp == std::string::npos) continue;
            c.colName = s.substr(8, sp - 8);
            c.value = decodeSqlLiteral(s.substr(sp + 1));
            conds.push_back(c);
            continue;
        }
        if (s.size() >= 5 && s.substr(0, 5) == "ilike") {
            c.op = "ilike";
            size_t sp = s.find(' ', 5);
            if (sp == std::string::npos) continue;
            c.colName = s.substr(5, sp - 5);
            c.value = decodeSqlLiteral(s.substr(sp + 1));
            conds.push_back(c);
            continue;
        }
        if (s.size() >= 4 && s.substr(0, 4) == "like") {
            c.op = "like";
            size_t sp = s.find(' ', 4);
            if (sp == std::string::npos) continue;
            c.colName = s.substr(4, sp - 4);
            c.value = decodeSqlLiteral(s.substr(sp + 1));
            conds.push_back(c);
            continue;
        }
        // Handle REGEXP operator
        if (s.size() >= 6 && s.substr(0, 6) == "regexp") {
            c.op = "regexp";
            size_t sp = s.find(' ', 6);
            if (sp == std::string::npos) continue;
            c.colName = s.substr(6, sp - 6);
            c.value = decodeSqlLiteral(s.substr(sp + 1));
            conds.push_back(c);
            continue;
        }
        // Handle CONTAINS operator (full-text search)
        if (s.size() >= 8 && s.substr(0, 8) == "contains") {
            c.op = "contains";
            size_t sp = s.find(' ', 8);
            if (sp == std::string::npos) continue;
            c.colName = s.substr(8, sp - 8);
            c.value = decodeSqlLiteral(s.substr(sp + 1));
            conds.push_back(c);
            continue;
        }
        // Handle OVERLAPS operator
        if (s.size() >= 8 && s.substr(0, 8) == "overlaps") {
            c.op = "overlaps";
            c.colName = trim(s.substr(8));
            conds.push_back(c);
            continue;
        }
        // Handle 2-char operators: spatial << >> <^ >^ <@ and network &&
        // Format: operator_colname value (e.g., "<<loc 5.0,0.0" or "&&ip '192.168.1.0/24'")
        if (s.size() >= 4 && (s.substr(0, 2) == "<<" || s.substr(0, 2) == ">>" ||
                               s.substr(0, 2) == "<^" || s.substr(0, 2) == ">^" ||
                               s.substr(0, 2) == "<@" || s.substr(0, 2) == "&&")) {
            c.op = s.substr(0, 2);
            size_t sp = s.find(' ', 2);
            if (sp == std::string::npos) continue;
            c.colName = s.substr(2, sp - 2);
            c.value = decodeSqlLiteral(s.substr(sp + 1));
            conds.push_back(c);
            continue;
        }
        // Handle IN / NOT IN lists ("in<col> v1 v2 ..." from modifyLogic:
        // op prefix directly concatenated with the column name, then the
        // space-joined literal values).
        if (s.size() > 5 && s.substr(0, 5) == "notin") {
            size_t sp = s.find(' ');
            if (sp != std::string::npos && sp > 5) {
                c.op = "notin";
                c.colName = s.substr(5, sp - 5);
                listOperands(s.substr(sp+1),apiCondition,c);
                conds.push_back(c);
                continue;
            }
        }
        if (s.size() > 2 && s.substr(0, 2) == "in") {
            size_t sp = s.find(' ');
            if (sp != std::string::npos && sp > 2) {
                c.op = "in";
                c.colName = s.substr(2, sp - 2);
                listOperands(s.substr(sp+1),apiCondition,c);
                conds.push_back(c);
                continue;
            }
        }
        // Handle IS NOT NULL operator
        if (s.size() >= 9 && s.substr(0, 9) == "isnotnull") {
            c.op = "isnotnull";
            c.colName = trim(s.substr(9));
            conds.push_back(c);
            continue;
        }
        // Handle IS NULL operator
        if (s.size() >= 6 && s.substr(0, 6) == "isnull") {
            c.op = "isnull";
            c.colName = trim(s.substr(6));
            conds.push_back(c);
            continue;
        }
        // Function-left predicate (e.g. "length(v) = 0"): the op scan below
        // starts at position 0 and finds nothing, silently dropping the
        // condition (every row matched).  Capture it for row-context
        // evaluation in evalConditionOnRow instead.
        {
            size_t opos = 0;
            while (opos < s.size() && s[opos] != '(' &&
                   !(s[opos] == '<' || s[opos] == '>' || s[opos] == '=' || s[opos] == '!')) ++opos;
            if (opos > 0 && opos < s.size() && s[opos] == '(' &&
                (isalpha(static_cast<unsigned char>(s[0])) || s[0] == '_')) {
                size_t depth = 0, close = std::string::npos;
                for (size_t i = opos; i < s.size(); ++i) {
                    if (s[i] == '(') ++depth;
                    else if (s[i] == ')') { if (--depth == 0) { close = i; break; } }
                }
                size_t after = (close == std::string::npos) ? s.size() : close + 1;
                while (after < s.size() && isspace(static_cast<unsigned char>(s[after]))) ++after;
                size_t opLen = 0;
                while (after + opLen < s.size() &&
                       (s[after + opLen] == '<' || s[after + opLen] == '>' ||
                        s[after + opLen] == '=' || s[after + opLen] == '!')) ++opLen;
                if (opLen > 0) {
                    c.op = "scalarexpr";
                    c.colName = s.substr(0, after);
                    // keep the operator text in front for the evaluator
                    c.value = s.substr(after, opLen) + " " + s.substr(after + opLen);
                    conds.push_back(c);
                    continue;
                }
            }
        }
        size_t opEnd = 0;
        while (opEnd < s.size() && (s[opEnd] == '<' || s[opEnd] == '>' || s[opEnd] == '=' || s[opEnd] == '!')) ++opEnd;
        if (opEnd == 0) continue;
        c.op = s.substr(0, opEnd);
        if (c.op == "<>") c.op = "!=";  // canonical not-equal
        const auto protectedBytes=sqlProtectedBytes(s);
        size_t sp=opEnd;
        while(sp<s.size() && (protectedBytes[sp] || !std::isspace(static_cast<unsigned char>(s[sp]))))++sp;
        if(sp==s.size())continue;
        c.colName = s.substr(opEnd, sp - opEnd);
        // Computed operands are not physical column names. Preserve the
        // original RHS before literal decoding for typed comparison/coercion.
        const auto computedOperand = [](const std::string& operand, bool constantOnly,
                                        bool* numericArithmetic = nullptr) {
            if (numericArithmetic) *numericArithmetic = false;
            SQLParser parser;
            const auto parsed = parser.parse("SELECT " + operand);
            const auto* select = parsed.success
                ? dynamic_cast<const SelectStmt*>(parsed.stmt.get()) : nullptr;
            if (!select || select->selectList.size() != 1) return false;
            const auto* expression = select->selectList.front().expr.get();
            if (const auto* unary = dynamic_cast<const UnaryOpExpr*>(expression)) {
                if ((unary->op == "+" || unary->op == "-") &&
                    dynamic_cast<const LiteralExpr*>(unary->operand.get())) return false;
            }
            if (numericArithmetic) {
                std::function<bool(const Expr*)> pureNumeric =
                    [&](const Expr* node) -> bool {
                    if (const auto* literal = dynamic_cast<const LiteralExpr*>(node)) {
                        // The parser preserves untyped number tokens verbatim;
                        // strings, typed literals and special constants are not numbers.
                        return literal->typeName.empty() && !literal->value.empty() &&
                            (std::isdigit(static_cast<unsigned char>(literal->value[0])) ||
                             literal->value[0] == '.');
                    }
                    if (const auto* binary = dynamic_cast<const BinaryOpExpr*>(node)) {
                        const auto& op = binary->op;
                        return (op == "+" || op == "-" || op == "*" || op == "/" ||
                                op == "%" || op == "^") &&
                            pureNumeric(binary->left.get()) && pureNumeric(binary->right.get());
                    }
                    if (const auto* unary = dynamic_cast<const UnaryOpExpr*>(node))
                        return (unary->op == "+" || unary->op == "-") &&
                            pureNumeric(unary->operand.get());
                    return false;
                };
                *numericArithmetic = pureNumeric(expression);
            }
            if (constantOnly) {
                // Compact API RHS tokens also carry decoded text values.
                // A hyphenated value is not a row-dependent subtraction.
                std::function<bool(const Expr*)> hasRowReference =
                    [&](const Expr* node) -> bool {
                    if (!node) return false;
                    if (node->type == ExprType::ColumnRef ||
                        node->type == ExprType::Subquery ||
                        node->type == ExprType::Parameter ||
                        node->type == ExprType::A_Star) return true;
                    if (const auto* binary = dynamic_cast<const BinaryOpExpr*>(node))
                        return hasRowReference(binary->left.get()) ||
                            (binary->op != "::" && hasRowReference(binary->right.get()));
                    if (const auto* unary = dynamic_cast<const UnaryOpExpr*>(node))
                        return hasRowReference(unary->operand.get());
                    if (const auto* cast = dynamic_cast<const CastExpr*>(node))
                        return hasRowReference(cast->operand.get());
                    if (const auto* function = dynamic_cast<const FunctionCallExpr*>(node)) {
                        for (const auto& arg : function->args)
                            if (hasRowReference(arg.get())) return true;
                    } else if (const auto* conditional = dynamic_cast<const CaseExpr*>(node)) {
                        if (hasRowReference(conditional->switchExpr.get()) ||
                            hasRowReference(conditional->elseExpr.get())) return true;
                        for (const auto& clause : conditional->whenClauses)
                            if (hasRowReference(clause.first.get()) ||
                                hasRowReference(clause.second.get())) return true;
                    }
                    return false;
                };
                if (hasRowReference(expression)) return false;
            }
            return dynamic_cast<const BinaryOpExpr*>(expression) ||
                   dynamic_cast<const UnaryOpExpr*>(expression) ||
                   dynamic_cast<const CastExpr*>(expression);
        };
        const std::string rawRight = s.substr(sp + 1);
        if (computedOperand(c.colName, false)) {
            c.value = c.colName + " " + c.op + " " + rawRight;
            c.colName.clear();
            c.op = "typedexpr";
            conds.push_back(std::move(c));
            continue;
        }
        bool numericArithmetic = false;
        if (computedOperand(rawRight, true, &numericArithmetic)) {
            if (apiCondition && numericArithmetic) {
                // Only legacy read API values need schema-based disambiguation.
                // SQL expressions and explicit casts retain expression semantics.
                c.value = rawRight;
                c.op = "typedrhs " + c.op;
            } else {
                c.value = c.colName + " " + c.op + " " + rawRight;
                c.colName.clear();
                c.op = "typedexpr";
            }
            conds.push_back(std::move(c));
            continue;
        }
        // A typed SQL bit/hex literal is not an ordinary quoted string.
        // Decode the genuine literal AST once before scanning, retaining
        // empty data and rejecting invalid digits even on an empty input.
        const auto bits = apiCondition ? std::optional<std::string>{} : decodeBitPredicateLiteral(rawRight);
        if (bits) {
            c.value = *bits;
            c.decodedLiteralRhs = true;
            c.patternType = "bit";
            conds.push_back(std::move(c));
            continue;
        }
        c.value = decodeSqlLiteral(s.substr(sp + 1));
        c.decodedLiteralRhs = apiCondition || (!rawRight.empty() && rawRight.front()=='\'');
        if (!apiCondition && !rawRight.empty() && rawRight.front()=='\'') c.patternType = "unknown";
        if (!apiCondition) {
            SQLParser parser; const auto parsed=parser.parse("SELECT "+rawRight);
            const auto* select=parsed.success?dynamic_cast<const SelectStmt*>(parsed.stmt.get()):nullptr;
            const auto* literal=select && select->selectList.size()==1 && !select->fromClause
                ?dynamic_cast<const LiteralExpr*>(select->selectList.front().expr.get()):nullptr;
            if(literal && !literal->preparedSubquery && literal->typeName.empty() && literal->value=="null") {
                c.patternIsNull=true;c.patternType="unknown";c.decodedLiteralRhs=true;c.value.clear();
            }
        }
        conds.push_back(c);
    }
    for (auto& condition : conds) {
        condition.colName = decodeSqlIdentifier(condition.colName);
        if(condition.op=="typedexpr") {
            SQLParser parser;const auto parsed=parser.parseForBinding("SELECT "+condition.value);
            const auto* select=parsed.success?dynamic_cast<const SelectStmt*>(parsed.stmt.get()):nullptr;
            if(select && select->selectList.size()==1 && !select->fromClause)
                condition.patternIsNull=nullWhereComparison(select->selectList.front().expr.get());
        }
    }
    return conds;
}

// EXISTS(subquery): any row of the table satisfying the conditions?
bool StorageEngine::anyRowMatches(const std::string& dbname,
                                  const std::string& tablename,
                                  const std::vector<Condition>& conds,
                                  bool* scanFailed,
                                  bool* indexReadFailed) {
    return !filterRows(dbname, tablename, conds, nullptr, scanFailed,
                      indexReadFailed).empty();
}

std::set<int64_t> StorageEngine::filterRows(const std::string& dbname,
                                             const std::string& tablename,
                                             const std::vector<Condition>& inputConditions,
                                             bool* usedIndex,
                                             bool* scanFailed,
                                             bool* indexReadFailed) {
    noteTemporaryRelationAccess(dbname, tablename);
    std::set<int64_t> ids;
    if (usedIndex) *usedIndex = false;
    if (scanFailed) *scanFailed = false;
    if (indexReadFailed) *indexReadFailed = false;
    bool scanFailureDetected = false;
    auto failScan = [&]() {
        ids.clear();
        scanFailureDetected = true;
        if (scanFailed) *scanFailed = true;
        return ids;
    };
    auto failIndexScan = [&]() {
        if (indexReadFailed) *indexReadFailed = true;
        return failScan();
    };
    TableSchema tbl = getTableSchema(dbname, tablename);
    auto conds = prepareStoredUnknownBitScalarInputs(tbl, inputConditions);
    LocalExpressionSyntax predicateSyntax; // parses lazily only when a real row reaches its consumer
    for (auto& condition : conds) {
        if (condition.op!="=" && condition.op!="<>" && condition.op!="!=" &&
            condition.op!="<" && condition.op!=">" && condition.op!="<=" && condition.op!=">=") continue;
        const Column* declared=nullptr; bool rightIsColumn=false;
        for(size_t i=0;i<tbl.len;++i) {
            if(tbl.cols[i].dataName==condition.colName)declared=&tbl.cols[i];
            if(!condition.decodedLiteralRhs && tbl.cols[i].dataName==condition.value)rightIsColumn=true;
        }
        if(declared && !rightIsColumn && !declared->isArray && declared->dataType=="regtype") {
            const auto catalog=regtype_detail::metadata(*this,dbname);
            condition.value=condition.referenceInputOid?std::to_string(*condition.referenceInputOid):
                stored_regtype_detail::input(
                    decodeSqlLiteral(condition.value),false,catalog,currentSession());
            condition.decodedLiteralRhs=true;
        }
    }
    validateStoredPatternConditions(tbl,conds);
    for (const auto& condition:conds) if (condition.op=="typedexpr") {
        SQLParser parser;auto parsed=parser.parse("SELECT "+condition.value);
        auto* select=parsed.success ? dynamic_cast<SelectStmt*>(parsed.stmt.get()) : nullptr;
        if (!select || select->selectList.size()!=1 || select->fromClause)
            throw DbError("42601","invalid typed predicate");
        validateNullWhereColumns(select->selectList[0].expr.get(),tbl);
        ExprHelper::prepareArrayTypes(select->selectList[0].expr.get(),buildTypeHints(tbl),dbname,this);
    }
    // A strict comparison to the actual SQL NULL datum cannot qualify a
    // row. Admit every signature/input first, then avoid all row/routine
    // execution in this AND branch; quoted/API text NULL is not this datum.
    if (nullScalarBranch(conds)) return {};
    const auto secondaryMetadata = getIndexMetadata(dbname, tablename);
    const auto hasCompleteSecondaryIndex = [&](const std::string& columnName) {
        return std::any_of(
            secondaryMetadata.begin(), secondaryMetadata.end(),
            [&](const IndexMetadata& metadata) {
                return !metadata.isExpression &&
                       metadata.name == columnName &&
                       metadata.whereCondition.empty();
            });
    };

    // Record logical index predicates independently of the physical access
    // path. Range conditions may still use a heap scan today, but their
    // serializable read dependency must cover matching future index keys.
    bool hasSsiIndexPredicate = false;
    for (const auto& condition : conds) {
        hasSsiIndexPredicate = recordSsiIndexPredicate(
            dbname, tablename, condition, tbl) || hasSsiIndexPredicate;
    }

    // Current-version indexes cannot supply superseded heap versions for an
    // old snapshot, an overlapping writer or our own earlier command image.
    // An otherwise isolated, unmodified current read owner is different:
    // ordinary SELECT now has an implicit transaction, so treating that
    // owner as an overlap would disable every useful index probe.
    // The allocation high-water is monotonic even for aborted transactions;
    // fence the candidate lookup as well as checking the snapshot on entry.
    const auto& readContext = transactionContext();
    const uint64_t indexOwnerXid = readContext.currentTxnId;
    const bool currentReadOwner = readContext.inTransaction &&
        readContext.txnDB == dbname && readContext.currentTxnId != 0 &&
        readContext.snapshotAcquired && !readContext.hasWrite &&
        readContext.txnLog.empty() && readContext.ddlUndoActions.empty() &&
        !readContext.transactionBackupDirty &&
        readContext.readView.activeTxnIds.empty();
    uint64_t indexAllocationFence = 0;
    bool indexesAreSnapshotComplete = true;
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        indexAllocationFence = TxnIdGenerator::instance().maxCommittedTxId();
        if (readContext.inTransaction &&
            (!currentReadOwner ||
             readContext.readView.lowLimitId != indexAllocationFence + 1))
            indexesAreSnapshotComplete = false;
        for (const auto& [transactionId, activeDatabase] :
             activeTransactionDatabases()) {
            if (activeDatabase == dbname &&
                !(currentReadOwner && transactionId == readContext.currentTxnId)) {
                indexesAreSnapshotComplete = false;
                break;
            }
        }
    }

    // Helper: a column with a non-binary collation cannot use binary indexes
    // for equality/range lookup because the index keys are stored binary.
    auto columnNeedsCollation = [&](const std::string& colName) -> bool {
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == colName) {
                return !columnUsesBinaryCollation(tbl.cols[i]);
            }
        }
        return false;
    };

    auto registerPageSiread = [&](uint32_t pageId) {
        if (!transactionContext().inTransaction ||
            transactionContext().txnDB != dbname ||
            transactionContext().txnIsolationLevel != IsolationLevel::SERIALIZABLE) return;
        const std::string page = ssiPageKey(dbname, tablename, pageId);
        transactionContext().txnReadPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiReadPages_[transactionContext().currentTxnId].insert(page);
    };

    auto finishSerializablePredicateRead = [&]() {
        if (!transactionContext().inTransaction ||
            transactionContext().txnDB != dbname ||
            transactionContext().txnIsolationLevel != IsolationLevel::SERIALIZABLE) return;
        if (ids.empty()) {
            // A recorded index predicate is a sound superset of an empty
            // query result: any future row matching the query must also match
            // this indexed conjunct. Keep the relation fallback only when no
            // usable predicate was recorded, avoiding false conflicts between
            // disjoint empty index probes.
            if (hasSsiIndexPredicate) return;
            const std::string relation = ssiRelationKey(dbname, tablename);
            transactionContext().txnReadRelations.insert(relation);
            std::lock_guard<std::mutex> lock(ssiMutex_);
            ssiReadRelations_[transactionContext().currentTxnId].insert(relation);
            return;
        }
        for (int64_t rid : ids) {
            uint32_t pageId = 0;
            uint16_t slotId = 0;
            decodeRid(rid, pageId, slotId);
            (void)slotId;
            registerPageSiread(pageId);
        }
    };

    if (indexesAreSnapshotComplete) {
    const Condition* indexPredicate = nullptr;
    bool recheckIndexPredicate = false;
    const auto indexedCandidates = [&]() -> std::optional<std::set<int64_t>> {
    // Try full-text index for CONTAINS conditions
    for (const auto& c : conds) {
        if (c.op == "contains") {
            if (hasFullTextIndex(dbname, tablename, c.colName)) {
                auto rids = fullTextSearch(dbname, tablename, c.colName, c.value);
                for (int64_t rid : rids) ids.insert(rid);
                if (!ids.empty()) {
                    indexPredicate = &c;
                    return ids;
                }
            }
        }
    }

    // Try B+ tree PK index for = conditions
    for (const auto& c : conds) {
        if (c.op == "=") {
            // Non-binary collation requires collation-aware comparison; skip binary indexes.
            if (columnNeedsCollation(c.colName)) continue;
            const Column* searchColumn = nullptr;
            bool hasPK = false;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == c.colName) {
                    searchColumn = &tbl.cols[i];
                }
                if (tbl.cols[i].isPrimaryKey && tbl.cols[i].dataName == c.colName) {
                    hasPK = true; break;
                }
            }
            const std::string searchValue = searchColumn
                ? canonicalColumnKeyValue(*searchColumn, c.value)
                : c.value;
            // Old index builds and writes can omit non-NULL empty keys.
            // Even a nonempty candidate set would therefore be incomplete.
            if (searchValue.empty()) continue;
            if (hasPK) {
                BPTree* idx = getPKIndex(dbname, tablename);
                if (!idx) return failIndexScan();
                int64_t val = -1;
                const auto status = idx->searchChecked(searchValue, val);
                if (status == BPTree::SearchResult::Error) return failIndexScan();
                if (status == BPTree::SearchResult::Found) ids.insert(val);
            } else {
                // Try hash index first (O(1) equality lookup)
                HashIndex* hidx = getHashIndex(dbname, tablename, c.colName);
                if (hidx) {
                    auto vals = hidx->search(searchValue);
                    for (int64_t v : vals) ids.insert(v);
                }
                // Fallback to B+ tree secondary index
                if (ids.empty() && hasCompleteSecondaryIndex(c.colName)) {
                    BPTree* secIdx = getSecondaryIndex(dbname, tablename, c.colName);
                    if (!secIdx) return failIndexScan();
                    std::vector<int64_t> vals;
                    if (!secIdx->searchMultiChecked(searchValue, vals))
                        return failIndexScan();
                    for (int64_t v : vals) ids.insert(v);
                }
                // Try expression index (e.g. UPPER(name) = 'FOO')
                if (ids.empty()) {
                    for (const auto& meta : secondaryMetadata) {
                        // A partial index is only a subset.  Until predicate
                        // implication is proven, using it as a complete
                        // equality source could silently omit matching rows.
                        if (!meta.isExpression ||
                            !meta.whereCondition.empty()) continue;
                        // Normalize: compare uppercase versions
                        std::string queryExpr = c.colName;
                        std::string idxExpr = meta.name;
                        // Convert function names to uppercase for comparison
                        size_t qlp = queryExpr.find('(');
                        size_t ilp = idxExpr.find('(');
                        if (qlp != std::string::npos && ilp != std::string::npos) {
                            std::string qfunc = queryExpr.substr(0, qlp);
                            std::string ifunc = idxExpr.substr(0, ilp);
                            for (char& ch : qfunc) ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
                            for (char& ch : ifunc) ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
                            if (qfunc == ifunc) {
                                // Functions match, check inner column
                                std::string qcol = queryExpr.substr(qlp + 1, queryExpr.find(')') - qlp - 1);
                                std::string icol = idxExpr.substr(ilp + 1, idxExpr.find(')') - ilp - 1);
                                if (qcol == icol) {
                                    BPTree* exprIdx = getSecondaryIndex(dbname, tablename, meta.name);
                                    if (exprIdx) {
                                        std::string searchVal = c.value;
                                        if (meta.exprFunc == "UPPER") {
                                            for (char& ch : searchVal) ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
                                        } else if (meta.exprFunc == "LOWER") {
                                            for (char& ch : searchVal) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
                                        }
                                        std::vector<int64_t> vals;
                                        if (!exprIdx->searchMultiChecked(searchVal, vals))
                                            return failIndexScan();
                                        for (int64_t v : vals) ids.insert(v);
                                    } else {
                                        return failIndexScan();
                                    }
                                    break;
                                }
                            }
                        }
                    }
                }
            }
            if (!ids.empty()) {
                // Fixed-width index equality only proves prefix equality at
                // this boundary. Recheck the indexed atom itself as well.
                indexPredicate = &c;
                recheckIndexPredicate = searchValue.size() >= BP_KEY_LEN;
                return ids;
            }
        }
    }

    // Try GIN index for = conditions (supports text/json/array multi-key lookup)
    for (const auto& c : conds) {
        if (c.op == "=") {
            if (hasGinIndex(dbname, tablename, c.colName)) {
                auto rids = ginSearch(dbname, tablename, c.colName, c.value);
                for (int64_t rid : rids) ids.insert(rid);
                if (!ids.empty()) {
                    indexPredicate = &c;
                    return ids;
                }
            }
        }
    }

    // Try GiST index for range conditions (overlap/containment)
    for (const auto& c : conds) {
        if (columnNeedsCollation(c.colName)) continue;
        if (hasGiSTIndex(dbname, tablename, c.colName)) {
            if (c.op == "=") {
                // GiST overlap with [val, val] is equivalent to equality for scalars
                auto rids = giSTSearchOverlap(dbname, tablename, c.colName, c.value, c.value);
                for (int64_t rid : rids) ids.insert(rid);
            } else if (c.op == ">=" || c.op == ">") {
                // Search for values that overlap with [query_val, +inf)
                auto rids = giSTSearchOverlap(dbname, tablename, c.colName, c.value, "");
                for (int64_t rid : rids) ids.insert(rid);
            } else if (c.op == "<=" || c.op == "<") {
                // Search for values that overlap with (-inf, query_val]
                auto rids = giSTSearchOverlap(dbname, tablename, c.colName, "", c.value);
                for (int64_t rid : rids) ids.insert(rid);
            }
            if (!ids.empty()) {
                indexPredicate = &c;
                return ids;
            }
        }
    }

        return std::nullopt;
    }();
    if (indexedCandidates) {
        // Index corruption still fails closed. Do not hide a checked read
        // error merely because concurrent transaction allocation changed.
        if (scanFailureDetected) return *indexedCandidates;
        // Materialize only physical rows before the allocation fence. Never
        // run residual/generated SQL speculatively: a stored writer would
        // invalidate the owner and be executed again by the heap fallback.
        struct CandidateRow {
            int64_t rid;
            std::string value;
            std::vector<bool> nulls;
        };
        std::vector<CandidateRow> candidateRows;
        if (conds.size() > 1 || recheckIndexPredicate) {
            PageAllocator* pa = getPageAllocator(dbname, tablename);
            for (int64_t rid : *indexedCandidates) {
                CandidateRow row{rid, {}, {}};
                if (readRowByRid(pa, rid, row.value, tbl, &row.nulls))
                    candidateRows.push_back(std::move(row));
            }
        }
        const auto& current = transactionContext();
        const bool candidatesComplete = !currentReadOwner ||
            (current.inTransaction && current.currentTxnId == indexOwnerXid &&
            current.txnDB == dbname && !current.hasWrite &&
            current.txnLog.empty() && current.ddlUndoActions.empty() &&
            !current.transactionBackupDirty && current.snapshotAcquired &&
            current.readView.activeTxnIds.empty() &&
            current.readView.lowLimitId == indexAllocationFence + 1 &&
            TxnIdGenerator::instance().maxCommittedTxId() == indexAllocationFence);
        if (candidatesComplete) {
            // Once physical completeness is established, expression effects
            // cannot change this already selected snapshot's candidates.
            // Recheck each required conjunct once; do not restart afterward.
            if (conds.size() > 1 || recheckIndexPredicate) {
                ids.clear();
                for (const auto& candidate : candidateRows) {
                    const int64_t rid = candidate.rid;
                    const auto& row = candidate.value;
                    NullRowBinding rowBinding(this, dbname, tablename, rid, tbl.len);
                    BufferedNullRowBinding nullBinding(tbl, candidate.nulls);
                    bool match = true;
                    for (const auto& condition : conds) {
                        if (&condition == indexPredicate && !recheckIndexPredicate) continue;
                        if (!evalConditionOnRowWithSyntax(condition, row, tbl, &predicateSyntax)) {
                            match = false;
                            break;
                        }
                    }
                    if (match) ids.insert(rid);
                }
            }
            if (usedIndex) *usedIndex = true;
            finishSerializablePredicateRead();
            return ids;
        }
    }
    // A new transaction may have begun, written and even rolled back before
    // the lookup completed. Discard its possibly incomplete current-index
    // candidates and retain the original command snapshot in the heap scan.
    ids.clear();
    if (usedIndex) *usedIndex = false;
    }

    // Full table scan via page iterator.
    // Partition pruning: if conditions involve partition key, scan only matching partitions
    if (tbl.partitionType != TableSchema::PartitionType::None) {
        auto targetParts = getTargetPartitions(tbl, conds);
        if (!targetParts.empty()) {
            for (const auto& pname : targetParts) {
                auto ppa = acquireSharedHeap(
                    dbname, partitionDataPath(dbname, tablename, pname), tbl.rowSize(), pageSizeForFormatVersion(tbl.formatVersion), tbl.formatVersion,
                    dbname + "/" + tablename + "#" + pname);
                if (!ppa) return failScan();
                uint32_t np = ppa->numPages();
                for (uint32_t pid = 1; pid < np; ++pid) {
                    registerPageSiread(pid);
                    char* buf = ppa->fetchPage(pid);
                    if (!buf) {
                        return failScan();
                    }
                    PageWrapper page(buf, ppa->pageSize(), tbl.formatVersion);
                    page.forEachLive([&]([[maybe_unused]] uint16_t sid, const char* data, size_t len) {
                        int64_t rid = encodeRid(pid, sid);
                        bool match = true;
                        std::string row(data, len);
                        for (const auto& c : conds) {
                            if (!evalConditionOnRowWithSyntax(c, row, tbl, &predicateSyntax)) { match = false; break; }
                        }
                        if (match) ids.insert(rid);
                    });
                    ppa->unpinPage(pid);
                }
            }
            finishSerializablePredicateRead();
            return ids;
        }
    }
    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId, [[maybe_unused]] const char* data, [[maybe_unused]] size_t len) {
        int64_t rid = encodeRid(pageId, slotId);
        bool match = true;
        std::string row(data, len);
        for (const auto& c : conds) {
            if (!evalConditionOnRowWithSyntax(c, row, tbl, &predicateSyntax)) { match = false; break; }
        }
        if (match) ids.insert(rid);
    }, nullptr, {}, false)) return failScan();
    finishSerializablePredicateRead();
    return ids;
}

DBStatus StorageEngine::insertDefaultValues(const std::string& dbname,
                                             const std::string& tablename,
                                             const TableSchema& tbl,
                                             std::vector<std::map<std::string, std::string>>* insertedRows,
                                             OwningMutationRows* owningRows) {
    // Omission is the storage boundary's representation of DEFAULT. insert()
    // evaluates default expressions, allocates identity values, and checks
    // NOT NULL against columns without defaults. Supplying raw default text
    // here bypasses expression evaluation and can reject valid timestamp
    // literals; manufacturing values for NOT NULL columns is also invalid.
    (void)tbl;
    return insert(dbname, tablename, {}, insertedRows,IdentityOverride::None,owningRows);
}

DBStatus StorageEngine::remove(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    std::vector<std::map<std::string, std::string>>* deletedRows,
    const DeleteMatcher& deleteMatcher) {
    return remove(
        dbname, tablename, conditions, deletedRows, deleteMatcher, nullptr);
}

DBStatus StorageEngine::remove(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    std::vector<std::map<std::string, std::string>>* deletedRows,
    const DeleteMatcher& deleteMatcher,
    size_t* affectedRows) {
    SqlDeleteMatcher typedMatcher;
    if (deleteMatcher) {
        typedMatcher = [deleteMatcher](const SqlRow& row) {
            return deleteMatcher(legacyRowFromSql(row));
        };
    }
    std::vector<SqlRow> typedRows;
    const DBStatus status = removeRows(
        dbname, tablename, conditions,
        deletedRows ? &typedRows : nullptr, typedMatcher, affectedRows);
    if (deletedRows) {
        for (const auto& row : typedRows) {
            deletedRows->push_back(legacyRowFromSql(row));
        }
    }
    return status;
}

DBStatus StorageEngine::removeRows(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    std::vector<SqlRow>* deletedRows,
    const SqlDeleteMatcher& deleteMatcher) {
    return removeRows(
        dbname, tablename, conditions, deletedRows, deleteMatcher, nullptr);
}

DBStatus StorageEngine::removeRows(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    std::vector<SqlRow>* deletedRows,
    const SqlDeleteMatcher& deleteMatcher,
    size_t* affectedRows,
    const SqlMutationCallbacks* mutationCallbacks,
    OwningMutationRows* owningRows) {
    const auto ownershipStatus = ensureDatabaseTransactionOwnership(dbname);
    if (ownershipStatus != DBStatus::OK) return ownershipStatus;
    if (affectedRows) *affectedRows = 0;
    if (transactionContext().inTransaction &&
        dbname != transactionContext().txnDB) {
        return DBStatus::INVALID_VALUE;
    }

    // Referential actions can touch several child relations before the
    // parent heap is changed. Give the public DELETE a statement boundary so
    // a later child failure cannot leave earlier cascades or SET NULL actions
    // applied on their own.
    const bool ownsTransaction = !transactionContext().inTransaction;
    const std::vector<SqlRow> originalDeletedRows =
        deletedRows
            ? *deletedRows
            : std::vector<SqlRow>{};
    const OwningMutationRows originalOwningRows=owningRows?*owningRows:OwningMutationRows{};
    std::string statementSavepoint;
    bool hasStatementSavepoint = false;
    if (ownsTransaction) {
        const DBStatus beginStatus = beginTransaction(dbname);
        if (beginStatus != DBStatus::OK) return beginStatus;
    } else {
        static std::atomic<uint64_t> statementSavepointSequence{0};
        auto& context = transactionContext();
        do {
            statementSavepoint = "__dbms_delete_statement_" +
                std::to_string(context.currentTxnId) + "_" +
                std::to_string(statementSavepointSequence.fetch_add(1));
        } while (context.containsSavepoint(statementSavepoint));
        hasStatementSavepoint =
            createStatementSavepoint(statementSavepoint) == DBStatus::OK;
    }

    const auto rollbackDeleteStatement = [&]() {
        DBStatus rollbackStatus = DBStatus::OK;
        if (ownsTransaction && transactionContext().inTransaction) {
            rollbackStatus = rollbackTransaction();
        } else if (transactionContext().inTransaction &&
                   hasStatementSavepoint) {
            rollbackStatus = rollbackToSavepoint(statementSavepoint);
            if (rollbackStatus == DBStatus::OK) {
                rollbackStatus = releaseSavepoint(statementSavepoint);
            }
        } else if (transactionContext().inTransaction) {
            rollbackStatus = rollbackTransaction();
        }
        if (deletedRows) *deletedRows = originalDeletedRows;
        if (owningRows) *owningRows=originalOwningRows;
        if (affectedRows) *affectedRows = 0;
        return rollbackStatus;
    };

    ReferentialActionContext referentialContext;
    DBStatus deleteStatus;
    try {
        deleteStatus = removeInternal(
            dbname, tablename, conditions, deletedRows, deleteMatcher, nullptr,
            referentialContext, affectedRows, mutationCallbacks,owningRows);
    } catch (...) {
        // Predicates, typed RETURNING observations and trigger callbacks can
        // throw after opening the same statement owner used by status errors.
        // Restore that boundary, including output containers, before letting
        // the original exception/SQLSTATE reach the native or SQL caller.
        const auto error = std::current_exception();
        const DBStatus rollbackStatus = rollbackDeleteStatement();
        if (rollbackStatus != DBStatus::OK)
            throw DbError(sqlstateForDBStatus(rollbackStatus),
                          "could not roll back DELETE after an exception");
        std::rethrow_exception(error);
    }
    if (deleteStatus != DBStatus::OK) {
        const DBStatus rollbackStatus = rollbackDeleteStatement();
        return rollbackStatus == DBStatus::OK ? deleteStatus : rollbackStatus;
    }

    if (!ownsTransaction) {
        if (!hasStatementSavepoint) return DBStatus::OK;
        const DBStatus releaseStatus = releaseSavepoint(statementSavepoint);
        if (releaseStatus == DBStatus::OK) return DBStatus::OK;
        if (deletedRows) *deletedRows = originalDeletedRows;
        if (owningRows) *owningRows=originalOwningRows;
        if (affectedRows) *affectedRows = 0;
        const DBStatus rollbackStatus = rollbackTransaction();
        return rollbackStatus == DBStatus::OK
            ? releaseStatus : rollbackStatus;
    }

    const DBStatus commitStatus = commitTransaction();
    if (commitStatus != DBStatus::OK && deletedRows) {
        *deletedRows = originalDeletedRows;
    }
    if (commitStatus != DBStatus::OK && affectedRows) *affectedRows = 0;
    return commitStatus;
}

DBStatus StorageEngine::removeInternal(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    std::vector<SqlRow>* deletedRows,
    const SqlDeleteMatcher& deleteMatcher,
    const std::set<int64_t>* exactRids,
    ReferentialActionContext& referentialContext,
    size_t* affectedRows,
    const SqlMutationCallbacks* mutationCallbacks,
    OwningMutationRows* owningRows) {
    if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
        if ((transactionContext().txnIsolationLevel == IsolationLevel::READ_COMMITTED ||
             transactionContext().txnIsolationLevel == IsolationLevel::READ_UNCOMMITTED) &&
            !transactionContext().readView.commandIdVisibility) {
            refreshReadView();
        } else {
            ensureTransactionSnapshot();
        }
        transactionContext().hasWrite = true;
    }
    if (transactionContext().readOnly &&
        !isSessionTemporaryRelation(tablename)) {
        return DBStatus::INVALID_VALUE;
    }
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockIntentExclusive(tablename)) return DBStatus::LOCK_CONFLICT;

    TableSchema tbl = getTableSchema(dbname, tablename);
    bool captureLogicalDelete = false;
    try {
        captureLogicalDelete = !tbl.isUnlogged && PublicationCatalog::instance().publishes(
            dbname, tablename, LogicalChange::Op::Delete);
    } catch (const DbError& error) {
        if (error.sqlState() != "58030") throw;
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    // UPDATE/DELETE currently consume a parent-table RID after predicate
    // scanning.  Such a RID has no partition identity, so proceeding can
    // silently report success while touching no row, or target a different
    // partition that happens to reuse the same page/slot.  Fail explicitly
    // until row locators carry the physical partition.
    if (tbl.partitionType != TableSchema::PartitionType::None) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    std::vector<Trigger> operationTriggers;
    if (triggerExecutor_ && !tryGetAllTriggers(dbname, operationTriggers)) {
        lockManager_.unlock(tablename);
        return DBStatus::CORRUPTED_DATA;
    }
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    if (!pa) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }

    const bool enforceRls = exactRids == nullptr &&
        shouldEnforceRLS(tbl, StorageEngine::getRLSUser());
    std::set<int64_t> toDelete;
    if (exactRids) {
        toDelete = *exactRids;
    } else if (enforceRls) {
        auto conds = parseConditions(conditions);
        const bool scanOk = forEachVisibleRow(
            dbname, tablename, "DELETE",
            [&](uint32_t pid, uint16_t sid, const char* data, size_t len) {
                const std::string row(data, len);
                for (const auto& c : conds) {
                    if (!evalConditionOnRow(c, row, tbl)) return;
                }
                toDelete.insert(encodeRid(pid, sid));
            });
        if (!scanOk) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    } else {
        auto conds = parseConditions(conditions);
        bool scanFailed = false;
        toDelete = filterRows(dbname, tablename, conds, nullptr, &scanFailed);
        if (scanFailed) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
    }

    // Structured DELETE ... USING performs the source-row match before this
    // storage operation.  Keep the final target-row selection inside the
    // storage boundary so RLS, row locks, FK actions, indexes and RETURNING
    // continue to use the same delete path as ordinary DELETE.
    if (!exactRids && (deleteMatcher || (mutationCallbacks && mutationCallbacks->matches)) && !toDelete.empty()) {
        std::set<int64_t> filteredIds;
        for (int64_t rid : toDelete) {
            std::string row;
            std::vector<bool> nullColumns;
            if (!readRowByRid(pa, rid, row, tbl, &nullColumns)) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            BufferedNullRowBinding nullBinding(tbl, nullColumns);
            SqlRow rowValues;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].generatedKind!='v' && tbl.cols[i].isNull &&
                    dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, i)) {
                    rowValues[tbl.cols[i].dataName] = std::nullopt;
                } else {
                    bool computedNull=false;
                    auto value=extractColumnValue(row,tbl,i,dbname,true,&computedNull);
                    rowValues[tbl.cols[i].dataName]=computedNull
                        ?SqlCell{}:SqlCell{std::move(value)};
                }
            }
            if (mutationCallbacks && mutationCallbacks->matches
                    ? mutationCallbacks->matches(rid, rowValues)
                    : deleteMatcher(rowValues)) filteredIds.insert(rid);
        }
        toDelete.swap(filteredIds);
    }

    // A cyclic CASCADE can point back to a row already being deleted by an
    // ancestor action. Skip only those active physical rows; the guard removes
    // them again when this call unwinds, so a later independent statement is
    // unaffected.
    std::vector<std::string> activeDeleteKeys;
    for (auto it = toDelete.begin(); it != toDelete.end();) {
        const std::string key = ssiRidKey(dbname, tablename, *it);
        if (referentialContext.activeDeletes.count(key)) {
            it = toDelete.erase(it);
        } else {
            activeDeleteKeys.push_back(key);
            ++it;
        }
    }

    if (toDelete.empty()) {
        lockManager_.unlock(tablename);
        return DBStatus::OK;
    }
    ActiveReferentialRows activeDeleteGuard(
        referentialContext.activeDeletes, std::move(activeDeleteKeys));

    // Acquire row-level exclusive locks on rows to be deleted
    for (int64_t rid : toDelete) {
        if (!lockManager_.rowLockExclusive(tablename, rid)) {
            const DBStatus lockFailure = lockManager_.lastRowLockWasDeadlock()
                ? DBStatus::DEADLOCK_DETECTED : DBStatus::LOCK_CONFLICT;
            if (transactionContext().inTransaction) {
                // A user savepoint can recover this statement. Its public
                // wrapper rolls back the internal boundary, including locks
                // acquired here, without discarding earlier transaction work.
                if (hasUserSavepoint()) lockManager_.unlock(tablename);
                else rollbackTransaction();
            } else {
                lockManager_.unlockAll();
                lockManager_.unlockAllGaps();
            }
            return lockFailure;
        }
    }

    // Check foreign key references and apply ON DELETE actions
    {
        struct DeletedReferencedRow {
            std::string row;
            std::vector<bool> nullColumns;
        };
        std::vector<DeletedReferencedRow> deletedReferencedRows;
        deletedReferencedRows.reserve(toDelete.size());
        for (int64_t rid : toDelete) {
            DeletedReferencedRow deleted;
            if (!readRowByRid(
                    pa, rid, deleted.row, tbl, &deleted.nullColumns)) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            deletedReferencedRows.push_back(std::move(deleted));
        }

        if (!deletedReferencedRows.empty()) {
                // Scan all other tables for FK references and collect actions
                struct CascadeAction { std::string table; int64_t rid; };
                struct SetNullAction { std::string table; int64_t rid; std::vector<size_t> colIndices; };
                std::vector<CascadeAction> cascadeActions;
                std::vector<SetNullAction> setNullActions;
                std::set<std::string> restrictTables;
                DBStatus dependencyScanStatus = DBStatus::OK;

                auto allTables = getTableNames(dbname);
                // The exact RIDs collected below stay meaningful only while
                // writers are excluded from every referencing relation. Take
                // those relation locks before the scan so a concurrent UPDATE
                // cannot change the FK or recycle a slot between discovery and
                // the referential action.
                std::set<std::string> cascadeTables;
                for (const auto& otherTable : allTables) {
                    if (otherTable == tablename) continue;
                    const TableSchema otherTbl =
                        getTableSchema(dbname, otherTable);
                    for (size_t fi = 0; fi < otherTbl.fkLen; ++fi) {
                        if (otherTbl.fks[fi].refTable == tablename) {
                            cascadeTables.insert(otherTable);
                            break;
                        }
                    }
                }
                std::vector<std::string> sortedTables(
                    cascadeTables.begin(), cascadeTables.end());
                std::sort(sortedTables.begin(), sortedTables.end());
                std::vector<std::string> acquiredTables;
                for (const auto& tableName : sortedTables) {
                    if (!lockManager_.lockIntentExclusive(tableName)) {
                        for (const auto& acquired : acquiredTables) {
                            lockManager_.unlock(acquired);
                        }
                        lockManager_.unlock(tablename);
                        if (transactionContext().inTransaction) {
                            rollbackTransaction();
                        }
                        return DBStatus::LOCK_CONFLICT;
                    }
                    acquiredTables.push_back(tableName);
                }

                for (const auto& otherTable : allTables) {
                    if (dependencyScanStatus != DBStatus::OK) break;
                    TableSchema otherTbl = getTableSchema(dbname, otherTable);
                    for (size_t fi = 0; fi < otherTbl.fkLen; ++fi) {
                        const ForeignKey& fk = otherTbl.fks[fi];
                        if (fk.refTable != tablename) continue;

                        ValidatedForeignKeyDefinition definition;
                        if (validateForeignKeyDefinition(
                                otherTbl, tbl, fk.colNames, fk.refCols,
                                definition) != DBStatus::OK) {
                            dependencyScanStatus = DBStatus::CORRUPTED_DATA;
                            break;
                        }
                        const auto& fkColIndices =
                            definition.localColumnIndices;
                        const auto& referencedColumnIndices =
                            definition.referencedColumnIndices;

                        if (!forEachRow(dbname, otherTable, [&](uint32_t opid, uint16_t osid, const char* data, size_t len) {
                            const std::string row(data, len);
                            const int64_t orid = encodeRid(opid, osid);
                            bool matched = false;
                            for (const auto& deleted : deletedReferencedRows) {
                                bool allMatch = true;
                                for (size_t valueIndex = 0;
                                     valueIndex < fkColIndices.size();
                                     ++valueIndex) {
                                    const size_t localColumnIndex =
                                        fkColIndices[valueIndex];
                                    const size_t referencedColumnIndex =
                                        referencedColumnIndices[valueIndex];
                                    const bool referencedIsNull =
                                        referencedColumnIndex <
                                            deleted.nullColumns.size() &&
                                        deleted.nullColumns[
                                            referencedColumnIndex];
                                    const bool localIsNull =
                                        otherTbl.cols[localColumnIndex].isNull &&
                                        dbms::detail::storedRowColumnIsNull(*this, dbname, otherTable, otherTbl, orid, localColumnIndex);
                                    if (referencedIsNull || localIsNull) {
                                        allMatch = false;
                                        break;
                                    }
                                    const Column& referencedColumn =
                                        tbl.cols[referencedColumnIndex];
                                    const std::string referencedValue =
                                        canonicalColumnKeyValue(
                                            referencedColumn,
                                            [&] {
                                                BufferedNullRowBinding binding(
                                                    tbl, deleted.nullColumns);
                                                return extractColumnValue(
                                                    deleted.row, tbl,
                                                    referencedColumnIndex,
                                                    dbname);
                                            }());
                                    const std::string localValue =
                                        canonicalColumnKeyValue(
                                            referencedColumn,
                                            extractColumnValue(
                                                row, otherTbl,
                                                localColumnIndex, dbname));
                                    if (localValue != referencedValue) {
                                        allMatch = false;
                                        break;
                                    }
                                }
                                if (allMatch) { matched = true; break; }
                            }
                            if (matched) {
                                // A self-referencing row selected by this same
                                // DELETE disappears with its referenced row;
                                // it cannot leave a dangling reference.
                                if (otherTable == tablename &&
                                    toDelete.count(orid) != 0) {
                                    return;
                                }
                                if (fk.onDelete == "cascade") {
                                    cascadeActions.push_back({otherTable, orid});
                                } else if (fk.onDelete == "setnull") {
                                    setNullActions.push_back({otherTable, orid, fkColIndices});
                                } else {
                                    restrictTables.insert(otherTable);
                                }
                            }
                        })) {
                            dependencyScanStatus = DBStatus::IO_ERROR;
                            break;
                        }
                    }
                }

                if (dependencyScanStatus != DBStatus::OK) {
                    for (const auto& acquired : acquiredTables) {
                        lockManager_.unlock(acquired);
                    }
                    lockManager_.unlock(tablename);
                    return dependencyScanStatus;
                }

                if (!restrictTables.empty()) {
                    for (const auto& acquired : acquiredTables) {
                        lockManager_.unlock(acquired);
                    }
                    lockManager_.unlock(tablename);
                    return DBStatus::FOREIGN_KEY_VIOLATION;
                }

                // Publish every affected relation as unsafe before changing
                // the first heap tuple. This includes the parent so a later
                // marker I/O error cannot strand already-applied cascades.
                bool cascadeMarkersOk =
                    markSpecializedIndexesBeforeMutation(
                        dbname, tablename);
                for (const auto& tableName : sortedTables) {
                    if (!markSpecializedIndexesBeforeMutation(
                            dbname, tableName)) {
                        cascadeMarkersOk = false;
                    }
                }
                if (!cascadeMarkersOk) {
                    for (const auto& acquired : acquiredTables) {
                        lockManager_.unlock(acquired);
                    }
                    lockManager_.unlock(tablename);
                    return DBStatus::IO_ERROR;
                }

                // Merge actions by child relation and exact physical row. A
                // single child row may match multiple composite constraints;
                // applying one logical UPDATE avoids duplicate trigger firings
                // and, for MVCC, multiple successor versions of the same RID.
                using ReferentialValues = SqlRow;
                std::map<std::string, std::set<int64_t>> cascadeRows;
                std::map<std::string,
                         std::map<ReferentialValues, std::set<int64_t>>>
                    setNullRows;
                for (const auto& ca : cascadeActions) {
                    cascadeRows[ca.table].insert(ca.rid);
                }
                for (const auto& sa : setNullActions) {
                    TableSchema child = getTableSchema(dbname, sa.table);
                    ReferentialValues nullValues;
                    for (const size_t columnIndex : sa.colIndices) {
                        if (columnIndex < child.len) {
                            nullValues[child.cols[columnIndex].dataName] =
                                std::nullopt;
                        }
                    }
                    if (!nullValues.empty()) {
                        setNullRows[sa.table][nullValues].insert(sa.rid);
                    }
                }
                // DELETE CASCADE wins for a row that is reached through
                // another FK configured as SET NULL.
                for (auto& [tableName, groups] : setNullRows) {
                    const auto cascadeIt = cascadeRows.find(tableName);
                    if (cascadeIt == cascadeRows.end()) continue;
                    for (auto& [values, rows] : groups) {
                        (void)values;
                        for (const int64_t rid : cascadeIt->second) {
                            rows.erase(rid);
                        }
                    }
                }

                DBStatus actionStatus = DBStatus::OK;
                for (const auto& [tableName, groups] : setNullRows) {
                    for (const auto& [values, rows] : groups) {
                        if (rows.empty()) continue;
                        std::map<std::string, std::string> rawValues;
                        std::set<std::string> nullColumns;
                        splitSqlRow(values, rawValues, nullColumns);
                        actionStatus = updateInternal(
                            dbname, tableName, rawValues, nullColumns, {},
                            nullptr, SqlUpdateResolver{}, SqlUpdateMatcher{},
                            &rows,
                            referentialContext);
                        if (actionStatus != DBStatus::OK) break;
                    }
                    if (actionStatus != DBStatus::OK) break;
                }
                if (actionStatus == DBStatus::OK) {
                    for (const auto& [tableName, rows] : cascadeRows) {
                        if (rows.empty()) continue;
                        actionStatus = removeInternal(
                            dbname, tableName, {}, nullptr,
                            SqlDeleteMatcher{},
                            &rows, referentialContext);
                        if (actionStatus != DBStatus::OK) break;
                    }
                }

                bool cascadeSpecializedIndexesOk = true;
                for (const auto& tableName : sortedTables) {
                    if (!maintainSpecializedIndexesAfterMutation(
                            dbname, tableName)) {
                        cascadeSpecializedIndexesOk = false;
                    }
                }

                // Release locks on referenced tables
                for (const auto& t : sortedTables) {
                    lockManager_.unlock(t);
                }
                if (actionStatus != DBStatus::OK) {
                    lockManager_.unlock(tablename);
                    return actionStatus;
                }
                if (!cascadeSpecializedIndexesOk) {
                    lockManager_.unlock(tablename);
                    return DBStatus::IO_ERROR;
                }
        }
    }

    // Pre-read row data for index removal (before tombstone)
    const std::vector<int64_t> rowRids(toDelete.begin(), toDelete.end());
    std::vector<std::string> rowsToDelete;
    std::vector<std::vector<bool>> nullColumnsToDelete;
    rowsToDelete.reserve(toDelete.size());
    nullColumnsToDelete.reserve(toDelete.size());
    for (int64_t rid : rowRids) {
        std::string row;
        std::vector<bool> nullColumns;
        if (!readRowByRid(pa, rid, row, tbl, &nullColumns)) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
        rowsToDelete.push_back(std::move(row));
        nullColumnsToDelete.push_back(std::move(nullColumns));
    }

    // Resolve every OLD image while its external chunks still exist.  The
    // physical rows remain available for transaction undo and TOAST cleanup;
    // constraints, triggers and every index access method use these logical
    // copies even after the external chunks have been reclaimed.
    std::vector<std::string> logicalRowsToDelete;
    logicalRowsToDelete.reserve(rowsToDelete.size());
    for (const auto& row : rowsToDelete) {
        if (row.empty()) {
            logicalRowsToDelete.emplace_back();
            continue;
        }
        bool resolved = false;
        logicalRowsToDelete.push_back(
            resolveToastValues(dbname, tablename, row, tbl, &resolved));
        if (!resolved) {
            lockManager_.unlock(tablename);
            return DBStatus::CORRUPTED_DATA;
        }
    }
    const auto deletedColumnValue = [&](size_t rowIndex, size_t columnIndex,
                                        bool computeVirtual = false,
                                        std::optional<ExprValue>* owningValue = nullptr,
                                        bool* valueIsNull = nullptr) {
        if (rowIndex >= logicalRowsToDelete.size() ||
            columnIndex >= tbl.len) {
            return std::string{};
        }
        if (!(computeVirtual && tbl.cols[columnIndex].generatedKind == 'v') &&
            rowIndex < nullColumnsToDelete.size() &&
            columnIndex < nullColumnsToDelete[rowIndex].size() &&
            nullColumnsToDelete[rowIndex][columnIndex]) {
            return std::string{};
        }
        BufferedNullRowBinding binding(tbl, nullColumnsToDelete[rowIndex]);
        return extractColumnValue(logicalRowsToDelete[rowIndex], tbl,
                                  columnIndex, dbname, computeVirtual,valueIsNull,owningValue);
    };

    std::vector<std::vector<EvaluatedIndexEntry>> deleteSecondaryValues(
        logicalRowsToDelete.size());
    const auto deleteIndexMetadata = getIndexMetadata(dbname, tablename);
    for (size_t rowIndex = 0; rowIndex < logicalRowsToDelete.size(); ++rowIndex) {
        if (logicalRowsToDelete[rowIndex].empty()) continue;
        NullRowBinding nullBinding(
            this, dbname, tablename, rowRids[rowIndex], tbl.len);
        for (const auto& metadata : deleteIndexMetadata) {
            EvaluatedIndexEntry entry;
            if (!secondaryIndexEntryFromBuffer(
                    *this, metadata, tbl, logicalRowsToDelete[rowIndex],
                    dbname, entry)) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            deleteSecondaryValues[rowIndex].push_back(std::move(entry));
        }
    }
    std::vector<std::vector<EvaluatedIndexEntry>> deleteCompositeValues(
        logicalRowsToDelete.size());
    const auto deleteCompositeMetadata = getCompositeIndexes(dbname, tablename);
    for (size_t rowIndex = 0; rowIndex < logicalRowsToDelete.size(); ++rowIndex) {
        if (logicalRowsToDelete[rowIndex].empty()) continue;
        NullRowBinding nullBinding(
            this, dbname, tablename, rowRids[rowIndex], tbl.len);
        for (const auto& metadata : deleteCompositeMetadata) {
            EvaluatedIndexEntry entry;
            if (!compositeIndexEntryFromBuffer(
                    *this, metadata, tbl, logicalRowsToDelete[rowIndex],
                    dbname, entry)) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            deleteCompositeValues[rowIndex].push_back(std::move(entry));
        }
    }

    // DELETE RETURNING observes the target OLD rows before tombstones are
    // installed.  BEFORE DELETE triggers cannot mutate OLD, so capture maps
    // here and never re-query a row after DELETE.
    if (deletedRows || owningRows || (mutationCallbacks && mutationCallbacks->observed)) {
        if (deletedRows) deletedRows->clear();
        if (owningRows) owningRows->clear();
        for (size_t rowIndex = 0;
             rowIndex < logicalRowsToDelete.size(); ++rowIndex) {
            const auto& row = logicalRowsToDelete[rowIndex];
            if (row.empty()) continue;
            SqlRow values;
            std::shared_ptr<OwningRowImage> owning;
            for (size_t i = 0; i < tbl.len; ++i) {
                const bool physicallyNull =
                    tbl.cols[i].generatedKind != 'v' &&
                    rowIndex < nullColumnsToDelete.size() &&
                    i < nullColumnsToDelete[rowIndex].size() &&
                    nullColumnsToDelete[rowIndex][i];
                if (physicallyNull) {
                    values[tbl.cols[i].dataName] = std::nullopt;
                } else {
                    std::optional<ExprValue> value;
                    bool computedNull=false;
                    auto text=deletedColumnValue(rowIndex,i,true,
                        owningRows && tbl.cols[i].generatedKind=='v'?&value:nullptr,&computedNull);
                    values[tbl.cols[i].dataName]=computedNull?SqlCell{}:SqlCell{std::move(text)};
                    retainGeneratedValue(owning,true,tbl.cols[i].dataName,value);
                }
            }
            if (mutationCallbacks && mutationCallbacks->observed)
                mutationCallbacks->observed(rowRids[rowIndex], values, {});
            if (deletedRows) deletedRows->push_back(std::move(values));
            if (owningRows) owningRows->push_back(std::move(owning));
        }
    }

    // Fire BEFORE DELETE triggers (row-level)
    // BEFORE DELETE triggers have access to OLD values (the row being deleted).
    // They cannot modify the row (deletion is immutable) but can perform side effects
    // such as logging to an audit table or raising an error to abort the delete.
    if (triggerExecutor_) {
        auto beforeDeleteTriggers = filterTriggers(
            operationTriggers, tablename, "before", "delete");
        for (const auto& trg : beforeDeleteTriggers) {
            if (!trg.enabled) continue;
            if (trg.forEachRow) {
                for (size_t rowIndex = 0;
                     rowIndex < logicalRowsToDelete.size(); ++rowIndex) {
                    const auto& row = logicalRowsToDelete[rowIndex];
                    if (row.empty()) continue;
                    std::map<std::string, std::string> oldValues;
                    for (size_t i = 0; i < tbl.len; ++i) {
                        oldValues[tbl.cols[i].dataName] =
                            deletedColumnValue(rowIndex, i);
                    }
                    // Evaluate WHEN condition if present
                    if (!trg.whenCondition.empty() && whenEvaluator_) {
                        std::string cond = trg.whenCondition;
                        for (const auto& [col, val] : oldValues) {
                            std::string placeholder = "OLD." + col;
                            size_t pos = 0;
                            while ((pos = cond.find(placeholder, pos)) != std::string::npos) {
                                cond.replace(pos, placeholder.size(), val);
                                pos += val.size();
                            }
                        }
                        if (!whenEvaluator_(cond, {}, oldValues)) continue;
                    }
                    std::string action = trg.action;
                    for (const auto& [col, val] : oldValues) {
                        std::string placeholder = "OLD." + col;
                        size_t pos = 0;
                        while ((pos = action.find(placeholder, pos)) != std::string::npos) {
                            action.replace(pos, placeholder.size(), val);
                            pos += val.size();
                        }
                    }
                    {
                        auto replaceVar = [&](const std::string& var, const std::string& val) {
                            size_t pos = 0;
                            while ((pos = action.find(var, pos)) != std::string::npos) {
                                action.replace(pos, var.size(), val);
                                pos += val.size();
                            }
                        };
                        replaceVar("tg_name", trg.name);
                        replaceVar("tg_when", trg.timing);
                        replaceVar("tg_level", trg.forEachRow ? "ROW" : "STATEMENT");
                        replaceVar("tg_op", "DELETE");
                        replaceVar("tg_relname", trg.tableName);
                    }
                    stageExecFunctionCtx(*this, trg.name, trg.timing,
                                      "DELETE", trg.tableName,
                                      trg.forEachRow, nullptr, &oldValues, &tbl);
                    if (triggerExecutor_(action)) {
                        lockManager_.unlock(tablename);
                        return DBStatus::IO_ERROR;
                    }
                }
            } else {
                // Statement-level BEFORE DELETE
                if (!trg.whenCondition.empty() && whenEvaluator_) {
                    if (!whenEvaluator_(trg.whenCondition, {}, {})) continue;
                }
                std::string action = trg.action;
                {
                    auto replaceVar = [&](const std::string& var, const std::string& val) {
                        size_t pos = 0;
                        while ((pos = action.find(var, pos)) != std::string::npos) {
                            action.replace(pos, var.size(), val);
                            pos += val.size();
                        }
                    };
                    replaceVar("tg_name", trg.name);
                    replaceVar("tg_when", trg.timing);
                    replaceVar("tg_level", "STATEMENT");
                    replaceVar("tg_op", "DELETE");
                    replaceVar("tg_relname", trg.tableName);
                }
                stageExecFunctionCtx(*this, trg.name, trg.timing,
                                  "DELETE", trg.tableName,
                                  trg.forEachRow, nullptr, nullptr);
                if (triggerExecutor_(action)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::IO_ERROR;
                }
            }
        }
    }

    // Delete TOAST entries only after BEFORE DELETE triggers succeed.  Keep
    // old chunks until COMMIT in an explicit transaction so rollback can
    // restore the logged tuple and its external values.
    if (!markSpecializedIndexesBeforeMutation(dbname, tablename)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (!(transactionContext().inTransaction && dbname == transactionContext().txnDB)) {
        for (int64_t rid : toDelete) {
            deleteRowToast(dbname, tablename, rid);
        }
    }

    // Delete rows via PageAllocator tombstones
    size_t delIdx = 0;
    for (int64_t rid : toDelete) {
        uint32_t pageId; uint16_t slotId;
        decodeRid(rid, pageId, slotId);
        if (!lockManager_.pageLockExclusive(dbname, tablename, pageId)) {
            if (transactionContext().inTransaction) {
                lockManager_.unlock(tablename);
                rollbackTransaction();
            } else {
                lockManager_.unlockAll();
                lockManager_.unlockAllGaps();
            }
            return DBStatus::LOCK_CONFLICT;
        }
        char* pageBuf = pa->fetchPage(pageId);
        if (!pageBuf) {
            lockManager_.pageUnlock(dbname, tablename, pageId);
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }

        PageWrapper page(pageBuf, pa->pageSize(), tbl.formatVersion);
        const char* currentData = nullptr;
        size_t currentLen = 0;
        if (!page.read(slotId, currentData, currentLen) ||
            currentLen < rowHeaderSize(tbl.formatVersion, tbl.len)) {
            pa->unpinPage(pageId);
            lockManager_.pageUnlock(dbname, tablename, pageId);
            lockManager_.unlock(tablename);
            return DBStatus::CORRUPTED_DATA;
        }

        const Lsn beforeLsn = walPageImage(
            dbname, tablename, pageId, pageBuf, pa->pageSize(), true);
        if (beforeLsn == INVALID_LSN) {
            pa->unpinPage(pageId);
            lockManager_.pageUnlock(dbname, tablename, pageId);
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
        const bool transactionalDelete =
            usesHeapTupleHeader(tbl.formatVersion) &&
            transactionContext().inTransaction &&
            dbname == transactionContext().txnDB;
        bool pageChanged = false;
        if (transactionalDelete) {
            std::string mutableRow(currentData, currentLen);
            if (!markTupleDeletedByCurrentCommand(
                    mutableRow.data(), mutableRow.size(),
                    tbl.formatVersion)) {
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            pageChanged = page.update(
                slotId, mutableRow.data(), mutableRow.size());
        } else {
            pageChanged = page.remove(slotId);
        }
        if (!pageChanged) {
            pa->unpinPage(pageId);
            lockManager_.pageUnlock(dbname, tablename, pageId);
            lockManager_.unlock(tablename);
            return DBStatus::CORRUPTED_DATA;
        }

        // Publish the undo record only after the heap mutation succeeds. A
        // failed fetch/read/update must not make rollback re-add index keys
        // that this statement never removed.
        if (transactionContext().inTransaction &&
            dbname == transactionContext().txnDB &&
            !rowsToDelete[delIdx].empty()) {
            logTxnDelete(tablename, rid, rowsToDelete[delIdx]);
        }

        pa->markDirty(pageId);
        Lsn lsn = walPageImage(
            dbname, tablename, pageId, pageBuf, pa->pageSize(), false);
        if (lsn == INVALID_LSN) {
            pa->unpinPage(pageId);
            lockManager_.pageUnlock(dbname, tablename, pageId);
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
        setPageLsnAndChecksum(pageBuf, lsn);
        pa->markDirty(pageId);
        size_t freePct = page.freeSpace() * 100 / pa->pageSize();
        getFSM(dbname, tablename)->setFreePercent(
            pageId, static_cast<uint8_t>(freePct));
        getVM(dbname, tablename)->setAllVisible(pageId, false);
        pa->unpinPage(pageId);
        lockManager_.pageUnlock(dbname, tablename, pageId);
        ++delIdx;
    }

    // Every expected index entry must be removed successfully. Continuing
    // after a missing/unavailable access method would commit a heap/index
    // split; the statement wrapper can instead roll the heap versions back.
    if (tbl.hasPrimaryKey()) {
        BPTree* pkIdx = getPKIndex(dbname, tablename);
        if (!pkIdx) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
        size_t rowIndex = 0;
        for (int64_t rid : toDelete) {
            if (rowIndex >= logicalRowsToDelete.size()) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            const auto& row = logicalRowsToDelete[rowIndex++];
            if (row.empty()) continue;
            const std::string pkVal = extractPKValue(row, tbl);
            int64_t indexedRid = -1;
            if (pkVal.empty() || !pkIdx->search(pkVal, indexedRid) ||
                indexedRid != rid || !pkIdx->remove(pkVal)) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
        }
    }

    // Remove ordinary and expression secondary entries from the logical OLD
    // images captured before TOAST cleanup.
    {
        size_t rowIndex = 0;
        for (int64_t rid : toDelete) {
            if (rowIndex >= deleteSecondaryValues.size()) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            for (const auto& entry : deleteSecondaryValues[rowIndex]) {
                if (!entry.included || entry.key.empty()) continue;
                BPTree* index = getSecondaryIndex(
                    dbname, tablename, entry.name);
                if (!index || !index->removeMulti(entry.key, rid)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::IO_ERROR;
                }
            }
            ++rowIndex;
        }
    }
    // Remove from composite indexes.
    {
        size_t rowIndex = 0;
        for (int64_t rid : toDelete) {
            if (rowIndex >= deleteCompositeValues.size()) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            for (const auto& entry : deleteCompositeValues[rowIndex]) {
                if (!entry.included || entry.key.empty()) continue;
                BPTree* index = getCompositeIndexTree(
                    dbname, tablename, entry.name);
                if (!index || !index->removeMulti(entry.key, rid)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::IO_ERROR;
                }
            }
            ++rowIndex;
        }
    }
    // Remove from hash indexes
    {
        auto hashCols = getHashIndexedColumns(dbname, tablename);
        for (const auto& colname : hashCols) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx >= tbl.len) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            HashIndex* hidx = getHashIndex(dbname, tablename, colname);
            if (!hidx) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            size_t hidx_i = 0;
            for (int64_t rid : toDelete) {
                if (hidx_i >= logicalRowsToDelete.size()) {
                    lockManager_.unlock(tablename);
                    return DBStatus::CORRUPTED_DATA;
                }
                if (!logicalRowsToDelete[hidx_i].empty()) {
                    std::string val = canonicalColumnKeyValue(
                        tbl.cols[colIdx],
                        deletedColumnValue(hidx_i, colIdx));
                    const bool isNull = hidx_i < nullColumnsToDelete.size() &&
                        colIdx < nullColumnsToDelete[hidx_i].size() &&
                        nullColumnsToDelete[hidx_i][colIdx];
                    // Old builds intentionally omitted empty keys. Keep
                    // their safe fallback readable while upgrading writes.
                    const bool included = hashKeyIncluded(tbl.cols[colIdx], val, isNull);
                    // SQL NULL has no index entry, even when its storage
                    // bytes equal the real empty key's potentially large bucket.
                    const auto indexedRids = included ? hidx->search(val)
                        : std::vector<int64_t>{};
                    const bool mapped = std::find(indexedRids.begin(),
                        indexedRids.end(), rid) != indexedRids.end();
                    if (included &&
                        (!val.empty() || mapped) &&
                        !hidx->remove(val, rid)) {
                        lockManager_.unlock(tablename);
                        return DBStatus::IO_ERROR;
                    }
                }
                ++hidx_i;
            }
        }
    }
    // Remove from bloom indexes
    {
        auto bloomCols = getBloomIndexedColumns(dbname, tablename);
        for (const auto& colname : bloomCols) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx >= tbl.len) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            BloomIndex* bidx = getBloomIndex(dbname, tablename, colname);
            if (!bidx) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            size_t bidx_i = 0;
            for (int64_t rid : toDelete) {
                if (bidx_i >= logicalRowsToDelete.size()) {
                    lockManager_.unlock(tablename);
                    return DBStatus::CORRUPTED_DATA;
                }
                if (!logicalRowsToDelete[bidx_i].empty()) {
                    std::string val = canonicalColumnKeyValue(
                        tbl.cols[colIdx],
                        deletedColumnValue(bidx_i, colIdx));
                    if (!val.empty()) {
                        const auto indexedRids = bidx->search(val);
                        if (std::find(indexedRids.begin(), indexedRids.end(),
                                      rid) == indexedRids.end() ||
                            !bidx->remove(val, rid)) {
                            lockManager_.unlock(tablename);
                            return DBStatus::IO_ERROR;
                        }
                    }
                }
                ++bidx_i;
            }
        }
    }
    if (!maintainSpecializedIndexesAfterMutation(dbname, tablename)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    // Logical decoding: buffer the deletes (old images) for streaming at
    // commit.
    if (captureLogicalDelete) {
        auto& txn = transactionContext();
        if (txn.inTransaction) {
            size_t di = 0;
            for (int64_t rid : toDelete) {
                if (di < logicalRowsToDelete.size() &&
                    !logicalRowsToDelete[di].empty()) {
                    BufferedNullRowBinding binding(tbl, nullColumnsToDelete[di]);
                    std::vector<LogicalDecoder::Cell> cells;
                    cells.reserve(tbl.len);
                    for (size_t i = 0; i < tbl.len; ++i) {
                        bool isNull = false;
                        const auto value = extractColumnValue(
                            logicalRowsToDelete[di], tbl, i, dbname, true, &isNull);
                        cells.emplace_back(tbl.cols[i].dataType,
                            isNull ? std::nullopt : std::optional<std::string>(value));
                    }
                    txn.txnLogicalChanges.push_back(
                        {tablename, 2, LogicalDecoder::encodeRow(cells), ""});
                }
                ++di;
            }
        }
    }
    lockManager_.unlock(tablename);

    // Fire AFTER DELETE triggers
    if (triggerExecutor_) {
        auto triggers = filterTriggers(
            operationTriggers, tablename, "after", "delete");
        for (const auto& trg : triggers) {
            if (trg.forEachRow) {
                for (size_t rowIndex = 0;
                     rowIndex < logicalRowsToDelete.size(); ++rowIndex) {
                    const auto& row = logicalRowsToDelete[rowIndex];
                    if (row.empty()) continue;
                    std::map<std::string, std::string> oldValues;
                    for (size_t i = 0; i < tbl.len; ++i) {
                        oldValues[tbl.cols[i].dataName] =
                            deletedColumnValue(rowIndex, i);
                    }
                    // Evaluate WHEN condition if present
                    if (!trg.whenCondition.empty() && whenEvaluator_) {
                        std::string cond = trg.whenCondition;
                        for (const auto& [col, val] : oldValues) {
                            std::string placeholder = "OLD." + col;
                            size_t pos = 0;
                            while ((pos = cond.find(placeholder, pos)) != std::string::npos) {
                                cond.replace(pos, placeholder.size(), val);
                                pos += val.size();
                            }
                        }
                        if (!whenEvaluator_(cond, {}, oldValues)) continue;
                    }
                    std::string action = trg.action;
                    for (const auto& [col, val] : oldValues) {
                        std::string placeholder = "OLD." + col;
                        size_t pos = 0;
                        while ((pos = action.find(placeholder, pos)) != std::string::npos) {
                            action.replace(pos, placeholder.size(), val);
                            pos += val.size();
                        }
                    }
                    // Trigger diagnostic variables
                    {
                        auto replaceVar = [&](const std::string& var, const std::string& val) {
                            size_t pos = 0;
                            while ((pos = action.find(var, pos)) != std::string::npos) {
                                action.replace(pos, var.size(), val);
                                pos += val.size();
                            }
                        };
                        replaceVar("tg_name", trg.name);
                        replaceVar("tg_when", trg.timing);
                        replaceVar("tg_level", trg.forEachRow ? "ROW" : "STATEMENT");
                        replaceVar("tg_op", "DELETE");
                        replaceVar("tg_relname", trg.tableName);
                    }
                    stageExecFunctionCtx(*this, trg.name, trg.timing,
                                      "DELETE", trg.tableName,
                                      trg.forEachRow, nullptr, &oldValues, &tbl);
                    if (triggerExecutor_(action)) {
                        return DBStatus::IO_ERROR;
                    }
                }
            } else {
                // Statement-level trigger: execute once
                if (!trg.whenCondition.empty() && whenEvaluator_) {
                    if (!whenEvaluator_(trg.whenCondition, {}, {})) continue;
                }
                std::string action = trg.action;
                {
                    auto replaceVar = [&](const std::string& var, const std::string& val) {
                        size_t pos = 0;
                        while ((pos = action.find(var, pos)) != std::string::npos) {
                            action.replace(pos, var.size(), val);
                            pos += val.size();
                        }
                    };
                    replaceVar("tg_name", trg.name);
                    replaceVar("tg_when", trg.timing);
                    replaceVar("tg_level", trg.forEachRow ? "ROW" : "STATEMENT");
                    replaceVar("tg_op", "DELETE");
                    replaceVar("tg_relname", trg.tableName);
                }
                stageExecFunctionCtx(*this, trg.name, trg.timing,
                                  "DELETE", trg.tableName,
                                  trg.forEachRow, nullptr, nullptr);
                // Transition tables (REFERENCING OLD TABLE ...): stage the
                // full pre-statement row set for the executor to
                // materialize as a session temp table.
                if (!trg.transitions.empty()) {
                    auto& ctx = const_cast<StorageEngine*>(this)->getExecFunctionCtxMut();
                    for (const auto& spec : trg.transitions) {
                        if (spec.rfind("old ", 0) != 0) continue;
                        std::string name = trim(spec.substr(4));
                        std::vector<std::map<std::string, std::string>> rows;
                        for (size_t rowIndex = 0;
                             rowIndex < logicalRowsToDelete.size(); ++rowIndex) {
                            const auto& row = logicalRowsToDelete[rowIndex];
                            if (row.empty()) continue;
                            std::map<std::string, std::string> m;
                            for (size_t i = 0; i < tbl.len; ++i) {
                                m[tbl.cols[i].dataName] =
                                    deletedColumnValue(rowIndex, i);
                            }
                            rows.push_back(std::move(m));
                        }
                        ctx.transitionRows[name] = std::move(rows);
                    }
                }
                if (triggerExecutor_(action)) {
                    return DBStatus::IO_ERROR;
                }
            }
        }
    }

    // Track dead tuples for auto-vacuum
    {
        auto key = std::make_pair(dbname, tablename);
        std::lock_guard<std::mutex> lock(deadTupleMutex_);
        deadTupleCounts_[key] += toDelete.size();
    }
    maybeAutoVacuum(dbname, tablename);
    recordModification(dbname, tablename, toDelete.size());
    dbms::recordTableMutation(dbname, tablename, dbms::TableMutation::Delete,
                              toDelete.size());
    maybeAutoAnalyze(dbname, tablename);

    if (affectedRows) *affectedRows = toDelete.size();
    return DBStatus::OK;
}

DBStatus StorageEngine::update(
    const std::string& dbname, const std::string& tablename,
    const std::map<std::string, std::string>& updates,
    const std::vector<std::string>& conditions,
    std::vector<std::map<std::string, std::string>>* updatedRows,
    const UpdateResolver& updateResolver,
    const UpdateMatcher& updateMatcher) {
    return update(
        dbname, tablename, updates, conditions, updatedRows,
        updateResolver, updateMatcher, nullptr);
}

DBStatus StorageEngine::update(
    const std::string& dbname, const std::string& tablename,
    const std::map<std::string, std::string>& updates,
    const std::vector<std::string>& conditions,
    std::vector<std::map<std::string, std::string>>* updatedRows,
    const UpdateResolver& updateResolver,
    const UpdateMatcher& updateMatcher,
    size_t* affectedRows) {
    return update(dbname, tablename, updates, conditions, updatedRows,
                  updateResolver, updateMatcher, affectedRows, nullptr);
}

DBStatus StorageEngine::update(
    const std::string& dbname, const std::string& tablename,
    const std::map<std::string, std::string>& updates,
    const std::vector<std::string>& conditions,
    std::vector<std::map<std::string, std::string>>* updatedRows,
    const UpdateResolver& updateResolver,
    const UpdateMatcher& updateMatcher,
    size_t* affectedRows,
    std::vector<UpdateRowImage>* rowImages,
    OwningMutationRows* owningRows) {
    const auto ownershipStatus = ensureDatabaseTransactionOwnership(dbname);
    if (ownershipStatus != DBStatus::OK) return ownershipStatus;
    SqlUpdateResolver typedResolver;
    if (updateResolver) {
        typedResolver = [updateResolver](const SqlRow& oldValues,
                                         SqlRow& effectiveUpdates) {
            const auto legacyOld = legacyRowFromSql(oldValues);
            auto legacyUpdates = legacyRowFromSql(effectiveUpdates);
            if (!updateResolver(legacyOld, legacyUpdates)) return false;
            effectiveUpdates = sqlRowFromLegacy(legacyUpdates);
            return true;
        };
    }
    SqlUpdateMatcher typedMatcher;
    if (updateMatcher) {
        typedMatcher = [updateMatcher](const SqlRow& oldValues) {
            return updateMatcher(legacyRowFromSql(oldValues));
        };
    }
    std::vector<SqlRow> typedRows;
    const DBStatus status = updateRows(
        dbname, tablename, sqlRowFromLegacy(updates), conditions,
        updatedRows ? &typedRows : nullptr, typedResolver, typedMatcher,
        affectedRows, rowImages,nullptr,owningRows);
    if (updatedRows) {
        for (const auto& row : typedRows) {
            updatedRows->push_back(legacyRowFromSql(row));
        }
    }
    return status;
}

DBStatus StorageEngine::updateRows(
    const std::string& dbname, const std::string& tablename,
    const SqlRow& sqlUpdates,
    const std::vector<std::string>& conditions,
    std::vector<SqlRow>* updatedRows,
    const SqlUpdateResolver& updateResolver,
    const SqlUpdateMatcher& updateMatcher) {
    return updateRows(
        dbname, tablename, sqlUpdates, conditions, updatedRows,
        updateResolver, updateMatcher, nullptr);
}

DBStatus StorageEngine::updateRows(
    const std::string& dbname, const std::string& tablename,
    const SqlRow& sqlUpdates,
    const std::vector<std::string>& conditions,
    std::vector<SqlRow>* updatedRows,
    const SqlUpdateResolver& updateResolver,
    const SqlUpdateMatcher& updateMatcher,
    size_t* affectedRows) {
    return updateRows(dbname, tablename, sqlUpdates, conditions, updatedRows,
                      updateResolver, updateMatcher, affectedRows, nullptr);
}

DBStatus StorageEngine::updateRows(
    const std::string& dbname, const std::string& tablename,
    const SqlRow& sqlUpdates,
    const std::vector<std::string>& conditions,
    std::vector<SqlRow>* updatedRows,
    const SqlUpdateResolver& updateResolver,
    const SqlUpdateMatcher& updateMatcher,
    size_t* affectedRows,
    std::vector<UpdateRowImage>* rowImages,
    const SqlMutationCallbacks* mutationCallbacks,
    OwningMutationRows* owningRows) {
    if (affectedRows) *affectedRows = 0;
    std::map<std::string, std::string> updates;
    std::set<std::string> updateNullColumns;
    splitSqlRow(sqlUpdates, updates, updateNullColumns);
    if (transactionContext().inTransaction &&
        dbname != transactionContext().txnDB) {
        return DBStatus::INVALID_VALUE;
    }

    // A single UPDATE may touch many rows. In autocommit mode, run it inside
    // an engine-owned transaction so a constraint or storage error on a later
    // row cannot leave earlier rows permanently modified.
    const bool ownsTransaction = !transactionContext().inTransaction;
    const size_t returnedRowStart = updatedRows ? updatedRows->size() : 0;
    const size_t returnedImageStart = rowImages ? rowImages->size() : 0;
    const size_t returnedOwningStart=owningRows?owningRows->size():0;
    std::string statementSavepoint;
    bool hasStatementSavepoint = false;
    if (ownsTransaction) {
        const DBStatus beginStatus = beginTransaction(dbname);
        if (beginStatus != DBStatus::OK) return beginStatus;
    } else {
        static std::atomic<uint64_t> statementSavepointSequence{0};
        auto& context = transactionContext();
        do {
            statementSavepoint = "__dbms_update_statement_" +
                std::to_string(context.currentTxnId) + "_" +
                std::to_string(statementSavepointSequence.fetch_add(1));
        } while (context.containsSavepoint(statementSavepoint));
        hasStatementSavepoint =
            createStatementSavepoint(statementSavepoint) == DBStatus::OK;
    }

    ReferentialActionContext referentialContext;
    const DBStatus updateStatus = updateInternal(
        dbname, tablename, updates, updateNullColumns, conditions,
        updatedRows, updateResolver, updateMatcher, nullptr,
        referentialContext, affectedRows, rowImages, mutationCallbacks,owningRows);
    if (updateStatus != DBStatus::OK) {
        DBStatus rollbackStatus = DBStatus::OK;
        if (ownsTransaction && transactionContext().inTransaction) {
            rollbackStatus = rollbackTransaction();
        } else if (transactionContext().inTransaction &&
                   hasStatementSavepoint) {
            rollbackStatus = rollbackToSavepoint(statementSavepoint);
            if (rollbackStatus == DBStatus::OK) {
                rollbackStatus = releaseSavepoint(statementSavepoint);
            }
        } else if (transactionContext().inTransaction) {
            // A transaction containing a dirty DDL snapshot cannot create a
            // savepoint. Abort it rather than expose a partially applied DML
            // statement if such an UPDATE fails.
            rollbackStatus = rollbackTransaction();
        }
        if (updatedRows) updatedRows->resize(returnedRowStart);
        if (rowImages) rowImages->resize(returnedImageStart);
        if (owningRows) owningRows->resize(returnedOwningStart);
        if (affectedRows) *affectedRows = 0;
        return rollbackStatus == DBStatus::OK ? updateStatus : rollbackStatus;
    }

    if (!ownsTransaction) {
        if (!hasStatementSavepoint) return DBStatus::OK;
        const DBStatus releaseStatus = releaseSavepoint(statementSavepoint);
        if (releaseStatus == DBStatus::OK) return DBStatus::OK;
        if (updatedRows) updatedRows->resize(returnedRowStart);
        if (rowImages) rowImages->resize(returnedImageStart);
        if (owningRows) owningRows->resize(returnedOwningStart);
        if (affectedRows) *affectedRows = 0;
        const DBStatus rollbackStatus = rollbackTransaction();
        return rollbackStatus == DBStatus::OK
            ? releaseStatus : rollbackStatus;
    }

    const DBStatus commitStatus = commitTransaction();
    if (commitStatus != DBStatus::OK && updatedRows)
        updatedRows->resize(returnedRowStart);
    if (commitStatus != DBStatus::OK && rowImages)
        rowImages->resize(returnedImageStart);
    if (commitStatus != DBStatus::OK && affectedRows) *affectedRows = 0;
    if (commitStatus != DBStatus::OK && owningRows) owningRows->resize(returnedOwningStart);
    return commitStatus;
}

DBStatus StorageEngine::updateInternal(
    const std::string& dbname, const std::string& tablename,
    const std::map<std::string, std::string>& updates,
    const std::set<std::string>& updateNullColumns,
    const std::vector<std::string>& conditions,
    std::vector<SqlRow>* updatedRows,
    const SqlUpdateResolver& updateResolver,
    const SqlUpdateMatcher& updateMatcher,
    const std::set<int64_t>* exactRids,
    ReferentialActionContext& referentialContext,
    size_t* affectedRows,
    std::vector<UpdateRowImage>* rowImages,
    const SqlMutationCallbacks* mutationCallbacks,
    OwningMutationRows* owningRows) {
    if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
        if ((transactionContext().txnIsolationLevel == IsolationLevel::READ_COMMITTED ||
             transactionContext().txnIsolationLevel == IsolationLevel::READ_UNCOMMITTED) &&
            !transactionContext().readView.commandIdVisibility) {
            refreshReadView();
        } else {
            ensureTransactionSnapshot();
        }
        transactionContext().hasWrite = true;
    }
    if (transactionContext().readOnly &&
        !isSessionTemporaryRelation(tablename)) {
        return DBStatus::INVALID_VALUE;
    }
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;

    TableSchema tbl = getTableSchema(dbname, tablename);
    bool captureLogicalUpdate = false;
    try {
        captureLogicalUpdate = !tbl.isUnlogged && PublicationCatalog::instance().publishes(
            dbname, tablename, LogicalChange::Op::Update);
    } catch (const DbError& error) {
        if (error.sqlState() != "58030") throw;
        return DBStatus::IO_ERROR;
    }
    // See removeInternal(): the current UPDATE machinery re-opens every RID
    // through the parent heap and cannot safely identify a partition tuple.
    if (tbl.partitionType != TableSchema::PartitionType::None) {
        return DBStatus::INVALID_VALUE;
    }
    std::vector<bool> domainRequired(tbl.len, false);
    for (size_t i = 0; i < tbl.len; ++i)
        if (!tbl.cols[i].domainName.empty())
            {
                const auto domain = resolveDomainAncestry(dbname, tbl.cols[i].domainName);
                if (domain.name.empty()) throw DbError("XX001", "column domain metadata is missing");
                domainRequired[i] = domain.notNull;
            }

    // Validate columns and pre-check values. The same preparation function is
    // reused for row-dependent UPDATE expressions so all update entry points
    // share storage-level type normalization and validation.
    auto prepareColumnUpdates = [&](
                                     const std::map<std::string, std::string>& source,
                                     const std::set<std::string>& sourceNullColumns,
                                     std::map<size_t, std::string>& prepared,
                                     std::set<size_t>& preparedNullColumns,
                                     bool allowGeneratedColumns) -> DBStatus {
        prepared.clear();
        preparedNullColumns.clear();
        for (const auto& kv : source) {
            bool found = false;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == kv.first) {
                    found = true;
                    const Column& col = tbl.cols[i];
                    // GENERATED ALWAYS AS ... columns cannot be directly updated.
                    if (!allowGeneratedColumns &&
                        !col.generatedExpr.empty()) {
                        return DBStatus::INVALID_VALUE;
                    }
                    const bool isNullMarker =
                        sourceNullColumns.count(kv.first) != 0;
                    if ((!col.isNull || domainRequired[i]) && isNullMarker) {
                        return DBStatus::NULL_NOT_ALLOWED;
                    }
                    if (isNullMarker) {
                        prepared[i].clear();
                        preparedNullColumns.insert(i);
                        break;
                    }
                    if (kv.second.empty() &&
                        !columnAcceptsEmptyValue(col)) {
                        return DBStatus::INVALID_VALUE;
                    }
                    std::string storeVal = kv.second;
                    if (col.dataType == "regtype" && !isNullMarker) {
                        const auto catalog = regtype_detail::metadata(*this, dbname);
                        storeVal = stored_regtype_detail::input(
                            kv.second, col.isArray, catalog, currentSession());
                    }
                    if (col.dataType == "regtype") {
                        // Already canonicalized once by the actual input owner.
                    } else if (col.storageCodec == Column::StorageCodec::TemporalMicros) {
                        if (!normalizeTemporalColumn(col, kv.second, storeVal)) return DBStatus::INVALID_VALUE;
                    } else if (col.isArray && col.dataType == "numeric") {
                        if (!normalizeModifiedColumn(col, kv.second, storeVal)) return DBStatus::INVALID_VALUE;
                    } else if (col.dataType == "date") {
                        Date d(kv.second.c_str());
                        if (d.year == 0) return DBStatus::INVALID_VALUE;
                    } else if (col.dataType == "timestamp" ||
                               col.dataType == "timestamptz" ||
                               col.dataType == "datetime") {
                        if (!kv.second.empty() &&
                            parseTimestampToSeconds(kv.second) == 0) {
                            return DBStatus::INVALID_VALUE;
                        }
                    } else if (col.dataType == "time") {
                        if (!kv.second.empty() &&
                            parseTimeToSeconds(kv.second) < 0) {
                            return DBStatus::INVALID_VALUE;
                        }
                    } else if (col.dataType == "float") {
                        if (!kv.second.empty()) {
                            float parsed = 0.0f;
                            if (!parseFloatLiteral(kv.second, parsed)) {
                                return DBStatus::INVALID_VALUE;
                            }
                            storeVal = formatFloatingValue(parsed);
                        }
                    } else if (col.dataType == "money") {
                        if (!kv.second.empty()) {
                            int64_t minorUnits = 0;
                            if (!parseMoneyLiteral(kv.second, minorUnits,
                                                   &storeVal)) {
                                return DBStatus::INVALID_VALUE;
                            }
                        }
                    } else if (col.dataType == "double" ||
                               col.dataType == "decimal") {
                        if (!kv.second.empty()) {
                            double parsed = 0.0;
                            if (!parseDoubleLiteral(kv.second, parsed)) {
                                return DBStatus::INVALID_VALUE;
                            }
                            storeVal = formatFloatingValue(parsed);
                        }
                    } else if (col.dataType == "numeric") {
                        if (!kv.second.empty()) {
                            if (!normalizeModifiedColumn(col, kv.second, storeVal)) return DBStatus::INVALID_VALUE;
                        }
                    } else if (col.dataType == "macaddr" || col.dataType == "macaddr8") {
                        if (!kv.second.empty()) {
                            int n = (col.dataType == "macaddr8") ? 8 : 6;
                            uint8_t bytes[8];
                            if (!normalizeMacAddr(kv.second, n, bytes)) return DBStatus::INVALID_VALUE;
                        }
                    } else if (col.dataType == "bit" || col.dataType == "bit varying") {
                        if (!kv.second.empty()) {
                            std::string canon;
                            if (!normalizeBitString(kv.second, col.dataType, col.dsize, canon))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (isGeometricTextType(col.dataType)) {
                        if (!kv.second.empty()) {
                            std::string canon;
                            if (!normalizeGeometry(kv.second, col.dataType, canon))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (col.dataType == "point") {
                        if (!kv.second.empty()) {
                            if (!normalizePointLiteral(kv.second, storeVal))
                                return DBStatus::INVALID_VALUE;
                        }
                    } else if (col.dataType == "uuid") {
                        if (!kv.second.empty()) {
                            std::string canon;
                            if (!normalizeUuid(kv.second, canon))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (col.dataType == "blob") {
                        if (!kv.second.empty()) {
                            std::string canon;
                            if (!normalizeBytea(kv.second, canon))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (col.dataType == "inet" || col.dataType == "cidr") {
                        if (!kv.second.empty()) {
                            uint8_t family = 0, prefix = 0, addr[16];
                            if (!parseInetAddr(kv.second, family, prefix, addr,
                                               col.dataType == "cidr"))
                                return DBStatus::INVALID_VALUE;
                        }
                    } else if (isRangeType(col.dataType)) {
                        if (!kv.second.empty()) {
                            std::string canon;
                            if (!normalizeRange(kv.second, col.dataType, canon))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (col.isArray) {
                        if (!kv.second.empty()) {
                            std::string canon;
                            if (!(col.dataType == "interval" ? normalizeModifiedColumn(col, kv.second, canon) : normalizeArray(kv.second, col.dataType, canon)))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (col.dataType == "xml") {
                        if (!validateXml(kv.second, XmlParseMode::Content).ok)
                            return DBStatus::INVALID_VALUE;
                    } else if (col.dataType == "tsvector") {
                        if (!kv.second.empty()) {
                            std::string canon;
                            if (!normalizeTsVectorImpl(kv.second, canon))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (col.dataType == "tsquery") {
                        if (!kv.second.empty() && !isValidTsQuery(kv.second))
                            return DBStatus::INVALID_VALUE;
                    } else if (col.dataType == "jsonpath") {
                        if (!kv.second.empty() && !isValidJsonPath(kv.second))
                            return DBStatus::INVALID_VALUE;
                    } else if (col.dataType == "json" ||
                               col.dataType == "jsonb") {
                        if (!kv.second.empty() &&
                            !isValidJson(kv.second,
                                         col.dataType == "jsonb"))
                            return DBStatus::INVALID_VALUE;
                    } else if (col.dataType == "interval") {
                        if (!kv.second.empty()) {
                            std::string canon;
                            if (!normalizeModifiedColumn(col, kv.second, canon))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (col.dataType == "boolean") {
                        if (!kv.second.empty()) {
                            const auto parsed =
                                parsePostgresBoolean(kv.second);
                            if (!parsed) return DBStatus::INVALID_VALUE;
                            storeVal = postgresBooleanOutput(*parsed);
                        }
                    } else if (isIntegerStorageType(col.dataType)) {
                        if (!kv.second.empty()) {
                            const auto num = parseStoredInteger(kv.second);
                            if (!num || !integerValueFitsColumn(col, *num) ||
                                (*num == INF && col.isNull && !usesHeapTupleHeader(tbl.formatVersion))) {
                                return DBStatus::INVALID_VALUE;
                            }
                        }
                    } else if (!col.enumValues.empty()) {
                        if (!kv.second.empty() &&
                            std::find(col.enumValues.begin(),
                                      col.enumValues.end(), kv.second) ==
                                col.enumValues.end()) {
                            return DBStatus::INVALID_VALUE;
                        }
                    } else if (!col.isArray && TypeRegistry::instance().findType(col.dataType) == nullptr) {
                        CompositeType ct = getCompositeType(dbname, col.dataType);
                        if (!ct.name.empty() && !kv.second.empty()) {
                            std::string canon;
                            if (!normalizeComposite(kv.second, ct, canon))
                                return DBStatus::INVALID_VALUE;
                            storeVal = canon;
                        }
                    } else if (!col.isVariableLength && col.dataType != "char") {
                        if (!kv.second.empty()) {
                            const auto num = parseStoredInteger(kv.second);
                            if (!num || !integerValueFitsColumn(col, *num) ||
                                (*num == INF && col.isNull && !usesHeapTupleHeader(tbl.formatVersion))) {
                                return DBStatus::INVALID_VALUE;
                            }
                        }
                    }
                    const size_t maxLength = col.isArray && col.dataType != "regtype" ? 1024 : col.dsize;
                    if (varyingCharacterColumn(col) ||
                        variableBlankPaddedCharacterColumn(col)) {
                        size_t characters = 0;
                        if (!truncateCharacterValue(
                                storeVal, col.dsize, &characters)) {
                            return DBStatus::STRING_DATA_RIGHT_TRUNCATION;
                        }
                        if (variableBlankPaddedCharacterColumn(col) &&
                            characters < col.dsize) {
                            storeVal.append(col.dsize - characters, ' ');
                        }
                        if (storeVal.size() > characterColumnByteLimit(col))
                            return DBStatus::STRING_DATA_RIGHT_TRUNCATION;
                    } else if (col.isVariableLength &&
                        storeVal.size() > maxLength) {
                        if (characterWidthLimitedType(col)) {
                            if (!characterExcessIsSpaces(storeVal, maxLength))
                                return DBStatus::STRING_DATA_RIGHT_TRUNCATION;
                            storeVal.resize(maxLength);
                        } else {
                            return DBStatus::INVALID_VALUE;
                        }
                    }
                    if (!col.isVariableLength &&
                        (col.dataType == "char" ||
                         col.dataType == "character") &&
                        storeVal.size() < maxLength) {
                        storeVal.append(maxLength - storeVal.size(), ' ');
                    }
                    prepared[i] = storeVal;
                    break;
                }
            }
            if (!found) return DBStatus::INVALID_VALUE;
        }
        return DBStatus::OK;
    };

    std::map<size_t, std::string> colUpdates;  // column index -> new value
    std::set<size_t> colUpdateNullColumns;
    if (const DBStatus status =
            prepareColumnUpdates(updates, updateNullColumns, colUpdates,
                                 colUpdateNullColumns, false);
        status != DBStatus::OK) {
        return status;
    }

    if (!lockManager_.lockIntentExclusive(tablename)) return DBStatus::LOCK_CONFLICT;

    std::vector<Trigger> operationTriggers;
    if (triggerExecutor_ && !tryGetAllTriggers(dbname, operationTriggers)) {
        lockManager_.unlock(tablename);
        return DBStatus::CORRUPTED_DATA;
    }
    PageAllocator* pa = getPageAllocator(dbname, tablename);

    const bool enforceRls = exactRids == nullptr &&
        shouldEnforceRLS(tbl, StorageEngine::getRLSUser());
    std::set<int64_t> matchIds;
    bool scanFailed = false;
    if (exactRids) {
        matchIds = *exactRids;
    } else if (enforceRls) {
        auto conds = parseConditions(conditions);
        const bool scanOk = forEachVisibleRow(
            dbname, tablename, "UPDATE",
            [&](uint32_t pid, uint16_t sid, const char* data, size_t len) {
                const std::string row(data, len);
                for (const auto& c : conds) {
                    if (!evalConditionOnRow(c, row, tbl)) return;
                }
                matchIds.insert(encodeRid(pid, sid));
            });
        if (!scanOk) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
    } else {
        auto conds = parseConditions(conditions);
        if (conds.empty()) {
            if (!forEachRow(dbname, tablename, [&](uint32_t pid, uint16_t sid, const char*, size_t) {
                matchIds.insert(encodeRid(pid, sid));
            })) scanFailed = true;
        } else {
            matchIds = filterRows(dbname, tablename, conds, nullptr, &scanFailed);
        }
        if (scanFailed) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
    }

    if (!exactRids && (updateMatcher || (mutationCallbacks && mutationCallbacks->matches)) && !matchIds.empty()) {
        std::set<int64_t> filteredIds;
        for (const int64_t rid : matchIds) {
            std::string row;
            std::vector<bool> nullColumns;
            if (!readRowByRid(pa, rid, row, tbl, &nullColumns)) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            BufferedNullRowBinding nullBinding(tbl, nullColumns);
            SqlRow rowValues;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].generatedKind!='v' && tbl.cols[i].isNull &&
                    dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, i)) {
                    rowValues[tbl.cols[i].dataName] = std::nullopt;
                } else {
                    bool computedNull=false;
                    auto value=extractColumnValue(row,tbl,i,dbname,true,&computedNull);
                    rowValues[tbl.cols[i].dataName]=computedNull
                        ?SqlCell{}:SqlCell{std::move(value)};
                }
            }
            if (mutationCallbacks && mutationCallbacks->matches
                    ? mutationCallbacks->matches(rid, rowValues)
                    : updateMatcher(rowValues)) filteredIds.insert(rid);
        }
        matchIds.swap(filteredIds);
    }

    std::vector<std::string> activeUpdateKeys;
    for (auto it = matchIds.begin(); it != matchIds.end();) {
        const std::string key = ssiRidKey(dbname, tablename, *it);
        if (referentialContext.activeDeletes.count(key) ||
            referentialContext.activeUpdates.count(key)) {
            it = matchIds.erase(it);
        } else {
            activeUpdateKeys.push_back(key);
            ++it;
        }
    }

    if (matchIds.empty()) {
        lockManager_.unlock(tablename);
        return DBStatus::OK;
    }
    ActiveReferentialRows activeUpdateGuard(
        referentialContext.activeUpdates, std::move(activeUpdateKeys));

    // Acquire row-level exclusive locks on rows to be updated
    for (int64_t rid : matchIds) {
        if (!lockManager_.rowLockExclusive(tablename, rid)) {
            const DBStatus lockFailure = lockManager_.lastRowLockWasDeadlock()
                ? DBStatus::DEADLOCK_DETECTED : DBStatus::LOCK_CONFLICT;
            // Preserve user recovery points. With no user savepoint, abort
            // the whole transaction so a deadlock survivor can resume. An
            // internal statement savepoint alone is not a user recovery point.
            if (transactionContext().inTransaction) {
                if (hasUserSavepoint()) lockManager_.unlock(tablename);
                else rollbackTransaction();
            } else {
                lockManager_.unlockAll();
                lockManager_.unlockAllGaps();
            }
            return lockFailure;
        }
    }

    // Pre-fetch indexed column lists (hoisted out of the per-row loop)
    auto hashIndexedCols = getHashIndexedColumns(dbname, tablename);
    const auto secondaryIndexMetadata = getIndexMetadata(dbname, tablename);
    const auto compositeIndexMetadata = getCompositeIndexes(dbname, tablename);

    // For each matching row, read old data, update, write back, update indexes
    // Pre-update row images keyed by rid: AFTER UPDATE triggers expose OLD
    // from these.  Transactional updates keep OLD and NEW at separate RIDs.
    std::map<int64_t, std::map<std::string, std::string>> oldImages;
    std::map<int64_t, int64_t> newVersionRids;
    // Heap scans use the command snapshot, so a later row in the same UPDATE
    // cannot necessarily see an earlier row's new version. Track every
    // immediate final key by its participating columns and compare with SQL
    // equality semantics (including collation) before either version is
    // allowed to land. Deferred constraints remain commit-time checks.
    std::map<std::vector<size_t>,
             std::vector<std::pair<int64_t, std::vector<std::string>>>>
        statementImmediateUniqueKeys;
    for (int64_t rid : matchIds) {
        std::string row;
        std::vector<bool> oldNullColumns;
        if (!readRowByRid(pa, rid, row, tbl, &oldNullColumns)) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }

        bool resolvedOldRowOk = false;
        const std::string resolvedOldRow = resolveToastValues(
            dbname, tablename, row, tbl, &resolvedOldRowOk);
        if (!resolvedOldRowOk) {
            lockManager_.unlock(tablename);
            return DBStatus::CORRUPTED_DATA;
        }
        std::map<std::string, std::string> oldLogicalValues;
        std::array<bool,MAX_COLUMNS> oldVirtualNulls{};
        std::shared_ptr<OwningRowImage> owning;
        for (size_t i = 0; i < tbl.len; ++i) {
            BufferedNullRowBinding binding(tbl, oldNullColumns);
            if (tbl.cols[i].generatedKind != 'v' &&
                i < oldNullColumns.size() && oldNullColumns[i]) {
                oldLogicalValues[tbl.cols[i].dataName].clear();
            } else {
                std::optional<ExprValue> value;
                bool computedNull=false;
                oldLogicalValues[tbl.cols[i].dataName] = extractColumnValue(
                    resolvedOldRow,tbl,i,dbname,true,&computedNull,
                    owningRows && tbl.cols[i].generatedKind=='v'?&value:nullptr);
                oldVirtualNulls[i]=tbl.cols[i].generatedKind=='v' && computedNull;
                retainGeneratedValue(owning,true,tbl.cols[i].dataName,value);
            }
        }

        oldImages.emplace(rid, oldLogicalValues);
        // Save old PK and indexed column values before modification
        std::string oldPK = tbl.buildPKValue(oldLogicalValues);
        std::map<std::string, std::string> oldIdxVals;
        // Also save hash-indexed column values
        for (const auto& colname : hashIndexedCols) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx < tbl.len) {
                oldIdxVals[colname] = canonicalKeyValueFromRowMap(
                    oldLogicalValues, tbl, colname);
            }
        }
        // Also save bloom-indexed column values
        for (const auto& colname : getBloomIndexedColumns(dbname, tablename)) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx < tbl.len) {
                oldIdxVals[colname] = canonicalKeyValueFromRowMap(
                    oldLogicalValues, tbl, colname);
            }
        }

        // Rebuild row buffer with updates
        std::map<std::string, std::string> rowValues = oldLogicalValues;
        if (updateResolver || (mutationCallbacks && mutationCallbacks->resolve)) {
            SqlRow resolverValues;
            for (size_t i = 0; i < tbl.len; ++i) {
                if ((tbl.cols[i].generatedKind=='v' && oldVirtualNulls[i]) ||
                    (tbl.cols[i].generatedKind!='v' && i<oldNullColumns.size() && oldNullColumns[i])) {
                    resolverValues[tbl.cols[i].dataName] = std::nullopt;
                } else {
                    resolverValues[tbl.cols[i].dataName] =
                        valueFromRowMap(rowValues, tbl.cols[i].dataName);
                }
            }
            SqlRow effectiveSqlUpdates =
                joinSqlRow(updates, updateNullColumns);
            if (!(mutationCallbacks && mutationCallbacks->resolve
                    ? mutationCallbacks->resolve(rid, resolverValues, effectiveSqlUpdates)
                    : updateResolver(resolverValues, effectiveSqlUpdates))) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            std::map<std::string, std::string> effectiveUpdates;
            std::set<std::string> effectiveNullColumns;
            splitSqlRow(effectiveSqlUpdates, effectiveUpdates,
                        effectiveNullColumns);
            const DBStatus prepareStatus = prepareColumnUpdates(
                effectiveUpdates, effectiveNullColumns, colUpdates,
                colUpdateNullColumns, false);
            if (prepareStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return prepareStatus;
            }
        }
        std::set<size_t> assignedColumnIndices;
        std::set<size_t> assignedNullColumnIndices;
        for (const auto& kv : colUpdates) {
            const bool assignsNull =
                colUpdateNullColumns.count(kv.first) != 0;
            rowValues[tbl.cols[kv.first].dataName] =
                assignsNull ? std::string() : kv.second;
            assignedColumnIndices.insert(kv.first);
            if (assignsNull) assignedNullColumnIndices.insert(kv.first);
        }
        // Compute type hints for generated column / check evaluation
        auto updateTypeHints = buildTypeHints(tbl);

        // Recompute STORED generated columns after updates (VIRTUAL are query-time only).
        for (size_t i = 0; i < tbl.len; ++i) {
            const Column& col = tbl.cols[i];
            if (col.generatedExpr.empty() || col.generatedKind == 'v') continue;
            std::string computed;
            bool assignsNull = false;
            if (!evalExpressionSqlValue(
                    col.generatedExpr, rowValues, updateTypeHints, dbname,
                    computed, assignsNull, nullptr, this, col.dataType=="regtype", &tbl)) {
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            rowValues[col.dataName] =
                assignsNull ? std::string() : computed;
            assignedColumnIndices.insert(i);
            if (assignsNull) assignedNullColumnIndices.insert(i);
            else assignedNullColumnIndices.erase(i);
        }
        // Validate ENUM columns in updates
        for (const auto& kv : colUpdates) {
            const Column& col = tbl.cols[kv.first];
            if (!col.enumValues.empty() &&
                colUpdateNullColumns.count(kv.first) == 0 &&
                !kv.second.empty()) {
                bool valid = false;
                for (const auto& label : col.enumValues) {
                    if (label == kv.second) { valid = true; break; }
                }
                if (!valid) {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
            }
        }
        // Fire BEFORE UPDATE triggers (row-level)
        // BEFORE UPDATE triggers have access to both OLD (current row) and NEW (pending update) values.
        // They can modify NEW column values via "SET col = val" in the trigger action.
        if (triggerExecutor_) {
            std::set<std::string> oldTriggerNulls, newTriggerNulls;
            for (size_t i = 0; i < tbl.len; ++i) {
                const bool wasNull = i < oldNullColumns.size() && oldNullColumns[i];
                if (wasNull) oldTriggerNulls.insert(tbl.cols[i].dataName);
                const bool isNull = assignedColumnIndices.count(i)
                    ? assignedNullColumnIndices.count(i) != 0 : wasNull;
                if (isNull) newTriggerNulls.insert(tbl.cols[i].dataName);
            }
            auto beforeUpdateTriggers = filterTriggers(
                operationTriggers, tablename, "before", "update");
            // BEFORE triggers must see the logical OLD image, never the
            // physical TOAST reference stored in the heap tuple.
            const std::map<std::string, std::string>& oldRowValues =
                oldLogicalValues;
            for (const auto& trg : beforeUpdateTriggers) {
                if (!trg.enabled) continue;
                if (!trg.forEachRow) continue;
                // Evaluate WHEN condition if present
                if (!trg.whenCondition.empty() && whenEvaluator_) {
                    std::string cond = trg.whenCondition;
                    for (const auto& [col, val] : rowValues) {
                        std::string placeholder = "NEW." + col;
                        size_t pos = 0;
                        while ((pos = cond.find(placeholder, pos)) != std::string::npos) {
                            cond.replace(pos, placeholder.size(), val);
                            pos += val.size();
                        }
                    }
                    for (const auto& [col, val] : oldRowValues) {
                        std::string placeholder = "OLD." + col;
                        size_t pos = 0;
                        while ((pos = cond.find(placeholder, pos)) != std::string::npos) {
                            cond.replace(pos, placeholder.size(), val);
                            pos += val.size();
                        }
                    }
                    if (!whenEvaluator_(cond, rowValues, oldRowValues)) continue;
                }
                std::string action = trg.action;
                // Substitute NEW.column and OLD.column placeholders
                for (const auto& [col, val] : rowValues) {
                    std::string placeholder = "NEW." + col;
                    size_t pos = 0;
                    while ((pos = action.find(placeholder, pos)) != std::string::npos) {
                        action.replace(pos, placeholder.size(), val);
                        pos += val.size();
                    }
                }
                for (const auto& [col, val] : oldRowValues) {
                    std::string placeholder = "OLD." + col;
                    size_t pos = 0;
                    while ((pos = action.find(placeholder, pos)) != std::string::npos) {
                        action.replace(pos, placeholder.size(), val);
                        pos += val.size();
                    }
                }
                // Substitute trigger diagnostic variables
                {
                    auto replaceVar = [&](const std::string& var, const std::string& val) {
                        size_t pos = 0;
                        while ((pos = action.find(var, pos)) != std::string::npos) {
                            action.replace(pos, var.size(), val);
                            pos += val.size();
                        }
                    };
                    replaceVar("tg_name", trg.name);
                    replaceVar("tg_when", trg.timing);
                    replaceVar("tg_level", trg.forEachRow ? "ROW" : "STATEMENT");
                    replaceVar("tg_op", "UPDATE");
                    replaceVar("tg_relname", trg.tableName);
                }
                stageExecFunctionCtx(*this, trg.name, trg.timing,
                                  "UPDATE", trg.tableName,
                                  trg.forEachRow, &rowValues, &oldRowValues, &tbl);
                if (triggerExecutor_(action)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::IO_ERROR;
                }
                // Parse only explicit row assignments from the original action;
                // arbitrary SQL may contain equals signs of its own.
                {
                    for (const auto& assignment :
                         parseTriggerRowAssignments(trg.action)) {
                        std::string val;
                        bool evaluatedNull = false;
                        if (!evalTriggerRowAssignment(*this, dbname, tbl,
                                assignment.expression, rowValues, newTriggerNulls,
                                &oldRowValues, &oldTriggerNulls, val, evaluatedNull)) {
                            lockManager_.unlock(tablename);
                            return DBStatus::INVALID_VALUE;
                        }
                        for (size_t i = 0; i < tbl.len; ++i) {
                            if (tbl.cols[i].dataName == assignment.column) {
                                const bool assignsNull = evaluatedNull;
                                rowValues[assignment.column] =
                                    assignsNull ? std::string() : val;
                                assignedColumnIndices.insert(i);
                                if (assignsNull) {
                                    assignedNullColumnIndices.insert(i);
                                    newTriggerNulls.insert(assignment.column);
                                } else {
                                    assignedNullColumnIndices.erase(i);
                                    newTriggerNulls.erase(assignment.column);
                                }
                                break;
                            }
                        }
                    }
                }
            }
            // Re-apply generated column computation after BEFORE trigger modifications
            auto updateTypeHints2 = buildTypeHints(tbl);
            for (size_t i = 0; i < tbl.len; ++i) {
                const Column& col = tbl.cols[i];
                if (col.generatedExpr.empty() || col.generatedKind == 'v') continue;
                std::string computed;
                bool assignsNull = false;
                if (!evalExpressionSqlValue(
                        col.generatedExpr, rowValues, updateTypeHints2,
                        dbname, computed, assignsNull, nullptr, this, col.dataType=="regtype", &tbl)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
                rowValues[col.dataName] =
                    assignsNull ? std::string() : computed;
                assignedColumnIndices.insert(i);
                if (assignsNull) assignedNullColumnIndices.insert(i);
                else assignedNullColumnIndices.erase(i);
            }
        }

        // BEFORE triggers and generated expressions own the final NEW image.
        // Re-run storage-level validation and canonicalization for every
        // column they (or the original UPDATE) assigned before constructing a
        // row buffer, where malformed fixed-width values could otherwise be
        // truncated, converted to sentinels, or throw from stof/stod.
        std::map<std::string, std::string> finalAssignedValues;
        std::set<std::string> finalAssignedNullColumns;
        for (const size_t columnIndex : assignedColumnIndices) {
            if (columnIndex >= tbl.len) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            const std::string& columnName = tbl.cols[columnIndex].dataName;
            finalAssignedValues[columnName] =
                valueFromRowMap(rowValues, columnName);
            if (assignedNullColumnIndices.count(columnIndex) != 0) {
                finalAssignedNullColumns.insert(columnName);
            }
        }
        std::map<size_t, std::string> finalPreparedValues;
        std::set<size_t> finalPreparedNullColumns;
        const DBStatus finalPrepareStatus = prepareColumnUpdates(
            finalAssignedValues, finalAssignedNullColumns,
            finalPreparedValues, finalPreparedNullColumns, true);
        if (finalPrepareStatus != DBStatus::OK) {
            lockManager_.unlock(tablename);
            return finalPrepareStatus;
        }
        for (const auto& [columnIndex, value] : finalPreparedValues) {
            const bool assignsNull =
                finalPreparedNullColumns.count(columnIndex) != 0;
            rowValues[tbl.cols[columnIndex].dataName] =
                assignsNull ? std::string() : value;
            if (assignsNull) assignedNullColumnIndices.insert(columnIndex);
            else assignedNullColumnIndices.erase(columnIndex);
        }

        // Handle the special case where the row whose referenced key is
        // changing also references that old key through a self-FK. Recursive
        // DML cannot update this same active RID, so fold CASCADE/SET NULL
        // into the pending row image before constraints are evaluated.
        const auto pendingColumnIsNull = [&](size_t columnIndex) {
            return columnIndex < tbl.len &&
                tbl.cols[columnIndex].generatedKind != 'v' &&
                (assignedNullColumnIndices.count(columnIndex) != 0 ||
                 (columnIndex < oldNullColumns.size() &&
                  oldNullColumns[columnIndex] &&
                  assignedColumnIndices.count(columnIndex) == 0));
        };
        SqlRow selfReferentialAssignments;
        for (size_t foreignKeyIndex = 0;
             foreignKeyIndex < tbl.fkLen; ++foreignKeyIndex) {
            const ForeignKey& foreignKey = tbl.fks[foreignKeyIndex];
            if (foreignKey.refTable != tablename) continue;

            ValidatedForeignKeyDefinition definition;
            if (validateForeignKeyDefinition(
                    tbl, tbl, foreignKey.colNames, foreignKey.refCols,
                    definition) != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }

            bool referencedKeyChanged = false;
            bool oldRowReferencesOldKey = true;
            std::vector<std::string> oldReferencedValues;
            oldReferencedValues.reserve(
                definition.referencedColumnIndices.size());
            for (size_t valueIndex = 0;
                 valueIndex < definition.localColumnIndices.size();
                 ++valueIndex) {
                const size_t localColumnIndex =
                    definition.localColumnIndices[valueIndex];
                const size_t referencedColumnIndex =
                    definition.referencedColumnIndices[valueIndex];
                const bool oldLocalIsNull =
                    localColumnIndex < oldNullColumns.size() &&
                    oldNullColumns[localColumnIndex];
                const bool oldReferencedIsNull =
                    referencedColumnIndex < oldNullColumns.size() &&
                    oldNullColumns[referencedColumnIndex];
                const bool newReferencedIsNull =
                    pendingColumnIsNull(referencedColumnIndex);
                const Column& referencedColumn =
                    tbl.cols[referencedColumnIndex];
                const std::string oldReferencedValue =
                    oldReferencedIsNull
                    ? std::string()
                    : canonicalColumnKeyValue(
                          referencedColumn,
                          valueFromRowMap(
                              oldLogicalValues,
                              referencedColumn.dataName));
                const std::string newReferencedValue =
                    newReferencedIsNull
                    ? std::string()
                    : canonicalColumnKeyValue(
                          referencedColumn,
                          valueFromRowMap(
                              rowValues,
                              referencedColumn.dataName));
                referencedKeyChanged = referencedKeyChanged ||
                    oldReferencedIsNull != newReferencedIsNull ||
                    (!oldReferencedIsNull && !newReferencedIsNull &&
                     oldReferencedValue != newReferencedValue);
                if (oldLocalIsNull || oldReferencedIsNull ||
                    canonicalColumnKeyValue(
                        referencedColumn,
                        valueFromRowMap(
                            oldLogicalValues,
                            tbl.cols[localColumnIndex].dataName)) !=
                        oldReferencedValue) {
                    oldRowReferencesOldKey = false;
                }
                oldReferencedValues.push_back(oldReferencedValue);
            }
            if (!referencedKeyChanged || !oldRowReferencesOldKey) continue;

            if (foreignKey.onUpdate == "cascade") {
                for (size_t valueIndex = 0;
                     valueIndex < definition.localColumnIndices.size();
                     ++valueIndex) {
                    const size_t localColumnIndex =
                        definition.localColumnIndices[valueIndex];
                    const size_t referencedColumnIndex =
                        definition.referencedColumnIndices[valueIndex];
                    const std::string& localColumnName =
                        tbl.cols[localColumnIndex].dataName;
                    if (pendingColumnIsNull(referencedColumnIndex)) {
                        selfReferentialAssignments[localColumnName] =
                            std::nullopt;
                    } else {
                        selfReferentialAssignments[localColumnName] =
                            valueFromRowMap(
                                rowValues,
                                tbl.cols[referencedColumnIndex].dataName);
                    }
                }
            } else if (foreignKey.onUpdate == "setnull") {
                for (const size_t localColumnIndex :
                     definition.localColumnIndices) {
                    selfReferentialAssignments[
                        tbl.cols[localColumnIndex].dataName] = std::nullopt;
                }
            } else {
                bool newRowStillReferencesOldKey = true;
                for (size_t valueIndex = 0;
                     valueIndex < definition.localColumnIndices.size();
                     ++valueIndex) {
                    const size_t localColumnIndex =
                        definition.localColumnIndices[valueIndex];
                    if (pendingColumnIsNull(localColumnIndex) ||
                        canonicalColumnKeyValue(
                            tbl.cols[definition.referencedColumnIndices[
                                valueIndex]],
                            valueFromRowMap(
                                rowValues,
                                tbl.cols[localColumnIndex].dataName)) !=
                            oldReferencedValues[valueIndex]) {
                        newRowStillReferencesOldKey = false;
                        break;
                    }
                }
                if (newRowStillReferencesOldKey) {
                    lockManager_.unlock(tablename);
                    return DBStatus::FOREIGN_KEY_VIOLATION;
                }
            }
        }
        if (!selfReferentialAssignments.empty()) {
            std::map<std::string, std::string> actionValues;
            std::set<std::string> actionNullColumns;
            splitSqlRow(
                selfReferentialAssignments, actionValues,
                actionNullColumns);
            std::map<size_t, std::string> preparedActionValues;
            std::set<size_t> preparedActionNullColumns;
            const DBStatus actionPrepareStatus = prepareColumnUpdates(
                actionValues, actionNullColumns, preparedActionValues,
                preparedActionNullColumns, true);
            if (actionPrepareStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return actionPrepareStatus;
            }
            for (const auto& [columnIndex, value] : preparedActionValues) {
                const bool assignsNull =
                    preparedActionNullColumns.count(columnIndex) != 0;
                rowValues[tbl.cols[columnIndex].dataName] =
                    assignsNull ? std::string() : value;
                assignedColumnIndices.insert(columnIndex);
                if (assignsNull) {
                    assignedNullColumnIndices.insert(columnIndex);
                } else {
                    assignedNullColumnIndices.erase(columnIndex);
                }
            }

            // A generated column may depend on a local FK column changed by
            // the folded referential action. Recompute it before CHECK/index
            // validation, just as an ordinary UPDATE would.
            std::map<std::string, std::string> generatedActionValues;
            std::set<std::string> generatedActionNullColumns;
            for (size_t columnIndex = 0;
                 columnIndex < tbl.len; ++columnIndex) {
                const Column& column = tbl.cols[columnIndex];
                if (column.generatedExpr.empty() ||
                    column.generatedKind == 'v') {
                    continue;
                }
                std::string computed;
                bool computedNull = false;
                if (!evalExpressionSqlValue(
                        column.generatedExpr, rowValues, updateTypeHints,
                        dbname, computed, computedNull, nullptr, this, column.dataType=="regtype", &tbl)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::INVALID_VALUE;
                }
                generatedActionValues[column.dataName] =
                    computedNull ? std::string() : computed;
                if (computedNull) {
                    generatedActionNullColumns.insert(column.dataName);
                }
            }
            if (!generatedActionValues.empty()) {
                std::map<size_t, std::string> preparedGeneratedValues;
                std::set<size_t> preparedGeneratedNullColumns;
                const DBStatus generatedPrepareStatus =
                    prepareColumnUpdates(
                        generatedActionValues,
                        generatedActionNullColumns,
                        preparedGeneratedValues,
                        preparedGeneratedNullColumns, true);
                if (generatedPrepareStatus != DBStatus::OK) {
                    lockManager_.unlock(tablename);
                    return generatedPrepareStatus;
                }
                for (const auto& [columnIndex, value] :
                     preparedGeneratedValues) {
                    const bool assignsNull =
                        preparedGeneratedNullColumns.count(columnIndex) != 0;
                    rowValues[tbl.cols[columnIndex].dataName] =
                        assignsNull ? std::string() : value;
                    assignedColumnIndices.insert(columnIndex);
                    if (assignsNull) {
                        assignedNullColumnIndices.insert(columnIndex);
                    } else {
                        assignedNullColumnIndices.erase(columnIndex);
                    }
                }
            }
        }

        std::set<std::string> finalNullColumnNames;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (assignedNullColumnIndices.count(i) != 0 ||
                (i < oldNullColumns.size() && oldNullColumns[i] &&
                 assignedColumnIndices.count(i) == 0)) {
                finalNullColumnNames.insert(tbl.cols[i].dataName);
            }
        }
        if (!normalizePointColumns(
                tbl, rowValues, &finalNullColumnNames)) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        const DBStatus updatedCharacterWidthStatus =
            normalizeCharacterColumnWidths(
                tbl, rowValues, &finalNullColumnNames);
        if (updatedCharacterWidthStatus != DBStatus::OK) {
            lockManager_.unlock(tablename);
            return updatedCharacterWidthStatus;
        }
        if (!variableColumnWidthsValid(
                tbl, rowValues, &finalNullColumnNames)) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }

        const auto newColumnIsNull = [&](size_t columnIndex) {
            return columnIndex < tbl.len &&
                tbl.cols[columnIndex].generatedKind != 'v' &&
                (assignedNullColumnIndices.count(columnIndex) != 0 ||
                (columnIndex < oldNullColumns.size() &&
                 oldNullColumns[columnIndex] &&
                 assignedColumnIndices.count(columnIndex) == 0));
        };

        // Referential actions execute with relation-owner semantics. Applying
        // the caller's RLS policy here could silently leave a dangling FK even
        // though the parent mutation succeeds.
        if (!exactRids &&
            !rowPassesRLS(this, dbname, tablename, tbl, "UPDATE", rowValues,
                          updateTypeHints, true)) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }

        struct IndexTransition {
            EvaluatedIndexEntry oldEntry;
            EvaluatedIndexEntry newEntry;
        };
        std::vector<IndexTransition> secondaryIndexTransitions;
        for (const auto& metadata : secondaryIndexMetadata) {
            IndexTransition transition;
            if (!secondaryIndexEntry(
                    metadata, tbl, oldLogicalValues, dbname,
                    transition.oldEntry, this) ||
                !secondaryIndexEntry(
                    metadata, tbl, rowValues, dbname,
                    transition.newEntry, this)) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            secondaryIndexTransitions.push_back(std::move(transition));
        }
        std::vector<IndexTransition> compositeIndexTransitions;
        for (const auto& metadata : compositeIndexMetadata) {
            IndexTransition transition;
            if (!compositeIndexEntry(
                    metadata, tbl, oldLogicalValues, dbname,
                    transition.oldEntry, this) ||
                !compositeIndexEntry(
                    metadata, tbl, rowValues, dbname,
                    transition.newEntry, this)) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            compositeIndexTransitions.push_back(std::move(transition));
        }

        // Build a validation image before allocating TOAST chunks.  All
        // constraint and foreign-key checks below must be able to fail
        // without leaving newly allocated external values behind.
        uint64_t updateTxnId = transactionContext().inTransaction ? transactionContext().currentTxnId : 0;
        std::set<size_t> physicalNullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (newColumnIsNull(i)) physicalNullColumns.insert(i);
        }
        std::string newRow = buildRowBuffer(
            tbl, rowValues, updateTxnId, &physicalNullColumns);
        std::string strippedNewRow = stripRowHeader(newRow, tbl.formatVersion, tbl.len);
        std::vector<bool> newRowNulls(tbl.len, false);
        for (const size_t index : physicalNullColumns) newRowNulls[index] = true;
        const auto withNewRowNulls = [&](auto&& action) -> decltype(auto) {
            BufferedNullRowBinding binding(tbl, newRowNulls);
            return action();
        };

        // Write back via PageAllocator
        uint32_t pageId; uint16_t slotId;
        decodeRid(rid, pageId, slotId);

        const size_t deferredEntryStart =
            transactionContext().inTransaction
                ? transactionContext()
                      .deferredChecks[transactionContext().currentTxnId]
                      .size()
                : 0;

        // Check CHECK constraints before writing; collect deferrable deferred checks for commit-time validation.
        std::vector<size_t> deferredCheckCols;
        for (size_t i = 0; i < tbl.len; ++i) {
            const Column& col = tbl.cols[i];
            if (col.checkExpr.empty()) continue;
            const bool deferred = transactionContext().inTransaction &&
                col.deferrable && isConstraintDeferred(
                    col.checkConstraintName, col.initiallyDeferred);
            if (deferred) {
                deferredCheckCols.push_back(i);
                continue;
            }
            std::string err;
            if (!dbms::ExprHelper::evalCheck(
                    col.checkExpr, rowValues, updateTypeHints, &err, dbname,
                    "", this)) {
                lockManager_.unlock(tablename);
                return err.empty() ? DBStatus::CHECK_VIOLATION
                                   : DBStatus::INVALID_VALUE;
            }
        }
        if (transactionContext().inTransaction && !deferredCheckCols.empty()) {
            for (size_t ci : deferredCheckCols) {
                DeferredCheck check;
                check.kind = DeferredCheck::Kind::Check;
                check.dbname = dbname;
                check.tablename = tablename;
                check.rid = rid;
                check.constraintName = tbl.cols[ci].checkConstraintName;
                check.colIdx = ci;
                transactionContext()
                    .deferredChecks[transactionContext().currentTxnId]
                    .push_back(std::move(check));
            }
        }
        std::vector<const CheckConstraint*> deferredAdditionalChecks;
        for (const auto& storedCheck : tbl.additionalCheckConstraints) {
            if (storedCheck.expression.empty()) continue;
            const bool deferred = transactionContext().inTransaction &&
                storedCheck.deferrable &&
                isConstraintDeferred(
                    storedCheck.name, storedCheck.initiallyDeferred);
            if (deferred) {
                deferredAdditionalChecks.push_back(&storedCheck);
                continue;
            }
            std::string err;
            if (!dbms::ExprHelper::evalCheck(
                    storedCheck.expression, rowValues, updateTypeHints, &err,
                    dbname, "", this)) {
                lockManager_.unlock(tablename);
                return err.empty() ? DBStatus::CHECK_VIOLATION
                                   : DBStatus::INVALID_VALUE;
            }
        }
        for (const CheckConstraint* storedCheck : deferredAdditionalChecks) {
            DeferredCheck check;
            check.kind = DeferredCheck::Kind::Check;
            check.dbname = dbname;
            check.tablename = tablename;
            check.rid = rid;
            check.constraintName = storedCheck->name;
            check.checkExpr = storedCheck->expression;
            transactionContext()
                .deferredChecks[transactionContext().currentTxnId]
                .push_back(std::move(check));
        }

        // Check EXCLUDE constraints before writing (exclude the row being
        // updated).  DEFERRABLE EXCLUDE constraints currently deferred skip
        // the immediate scan and queue a commit-time re-check.
        auto excludeConstraints = getExclusionConstraints(dbname, tablename);
        for (const auto& ec : excludeConstraints) {
            // Deferring only matters inside a transaction (see insert path).
            if (!ec.name.empty() && transactionContext().inTransaction &&
                isConstraintCurrentlyDeferred(dbname, tablename, ec.name)) {
                if (transactionContext().inTransaction) {
                    DeferredCheck dc;
                    dc.kind = DeferredCheck::Kind::Exclude;
                    dc.dbname = dbname;
                    dc.tablename = tablename;
                    dc.rid = rid;
                    dc.constraintName = ec.name;
                    dc.exceptRid = rid;
                    dc.excludeElements = ec.elements;
                    dc.excludeWhere = ec.wherePredicate;
                    transactionContext().deferredChecks[transactionContext().currentTxnId].push_back(
                        std::move(dc));
                }
                continue;
            }
            bool scanFailed = false;
            if (checkExclusionConflict(dbname, tablename, ec, strippedNewRow, rid, &scanFailed)) {
                lockManager_.unlock(tablename);
                return DBStatus::EXCLUSION_VIOLATION;
            }
            if (scanFailed) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
        }

        // A user-visible UPDATE of foreign-key columns must not create a
        // dangling reference. Internal ON UPDATE/DELETE actions carry exact
        // RIDs and are validated by the parent operation that generated them.
        std::vector<DeferredCheck> pendingDeferredForeignKeyChecks;
        if (!exactRids) {
            for (size_t foreignKeyIndex = 0;
                 foreignKeyIndex < tbl.fkLen; ++foreignKeyIndex) {
                const ForeignKey& foreignKey = tbl.fks[foreignKeyIndex];
                if (foreignKey.colNames.empty() ||
                    foreignKey.colNames.size() != foreignKey.refCols.size()) {
                    lockManager_.unlock(tablename);
                    return DBStatus::CORRUPTED_DATA;
                }

                bool changed = false;
                bool hasNull = false;
                std::vector<std::string> localValues;
                localValues.reserve(foreignKey.colNames.size());
                for (const auto& columnName : foreignKey.colNames) {
                    size_t localColumnIndex = tbl.len;
                    for (size_t columnIndex = 0;
                         columnIndex < tbl.len; ++columnIndex) {
                        if (tbl.cols[columnIndex].dataName == columnName) {
                            localColumnIndex = columnIndex;
                            break;
                        }
                    }
                    if (localColumnIndex == tbl.len) {
                        lockManager_.unlock(tablename);
                        return DBStatus::CORRUPTED_DATA;
                    }
                    const std::string oldValue =
                        valueFromRowMap(oldLogicalValues, columnName);
                    const std::string newValue =
                        valueFromRowMap(rowValues, columnName);
                    const bool oldIsNull = localColumnIndex < oldNullColumns.size() &&
                        oldNullColumns[localColumnIndex];
                    const bool newIsNull = newColumnIsNull(localColumnIndex);
                    changed = changed || oldValue != newValue || oldIsNull != newIsNull;
                    hasNull = hasNull || newIsNull;
                    localValues.push_back(newValue);
                }
                if (!changed || hasNull) continue;
                if (!foreignKey.name.empty() &&
                    transactionContext().inTransaction &&
                    isConstraintCurrentlyDeferred(
                        dbname, tablename, foreignKey.name)) {
                    DeferredCheck check;
                    check.kind = DeferredCheck::Kind::ForeignKey;
                    check.dbname = dbname;
                    check.tablename = tablename;
                    check.rid = rid;
                    check.constraintName = foreignKey.name;
                    check.colIdx = 0;
                    check.uniqueCol = foreignKey.colNames.front();
                    check.payloadValue = localValues.front();
                    check.refTable = foreignKey.refTable;
                    check.refCol = foreignKey.refCols.front();
                    check.fkPayloadValues = localValues;
                    check.fkLocalCols = foreignKey.colNames;
                    check.fkRefCols = foreignKey.refCols;
                    pendingDeferredForeignKeyChecks.push_back(
                        std::move(check));
                    continue;
                }
                if (!tableExists(dbname, foreignKey.refTable)) {
                    lockManager_.unlock(tablename);
                    return DBStatus::TABLE_NOT_FOUND;
                }

                const TableSchema referenced =
                    getTableSchema(dbname, foreignKey.refTable);
                std::vector<size_t> referencedColumns;
                referencedColumns.reserve(foreignKey.refCols.size());
                for (const auto& columnName : foreignKey.refCols) {
                    size_t columnIndex = referenced.len;
                    for (size_t candidate = 0;
                         candidate < referenced.len; ++candidate) {
                        if (referenced.cols[candidate].dataName == columnName) {
                            columnIndex = candidate;
                            break;
                        }
                    }
                    if (columnIndex >= referenced.len) {
                        lockManager_.unlock(tablename);
                        return DBStatus::CORRUPTED_DATA;
                    }
                    referencedColumns.push_back(columnIndex);
                }

                bool found = false;
                // A row may update both its referenced key and its
                // self-reference in one statement.
                if (foreignKey.refTable == tablename) {
                    found = true;
                    for (size_t valueIndex = 0;
                         valueIndex < referencedColumns.size(); ++valueIndex) {
                        const std::string& referencedName =
                            referenced.cols[referencedColumns[valueIndex]].dataName;
                        if (newColumnIsNull(referencedColumns[valueIndex]) ||
                            valueFromRowMap(rowValues, referencedName) !=
                            localValues[valueIndex]) {
                            found = false;
                            break;
                        }
                    }
                }

                const bool scanOk = found || forEachRow(
                    dbname, foreignKey.refTable,
                    [&](uint32_t pageId, uint16_t slotId, const char* data, size_t length) {
                        if (found) return;
                        const std::string referencedRow(data, length);
                        for (size_t valueIndex = 0;
                             valueIndex < referencedColumns.size(); ++valueIndex) {
                            if (dbms::detail::storedRowColumnIsNull(*this, dbname, foreignKey.refTable, referenced,
                                    encodeRid(pageId, slotId), referencedColumns[valueIndex])) {
                                return;
                            }
                            if (extractColumnValue(
                                    referencedRow, referenced,
                                    referencedColumns[valueIndex], dbname) !=
                                localValues[valueIndex]) {
                                return;
                            }
                        }
                        found = true;
                    });
                if (!scanOk) {
                    lockManager_.unlock(tablename);
                    return DBStatus::IO_ERROR;
                }
                if (!found) {
                    lockManager_.unlock(tablename);
                    return DBStatus::FOREIGN_KEY_VIOLATION;
                }
            }
        }

        // UPDATE must enforce the same key constraints as INSERT.  Validate
        // against the final row image (including generated columns and
        // BEFORE-trigger changes) before mutating the heap or indexes.
        std::vector<DeferredCheck> pendingDeferredUniqueChecks;
        const auto validateUniqueUpdate = [&](
                const std::vector<size_t>& columns,
                const std::string& constraintName) -> DBStatus {
            if (columns.empty()) return DBStatus::OK;
            std::vector<std::string> newValues;
            newValues.reserve(columns.size());
            bool keyChanged = false;
            for (const size_t columnIndex : columns) {
                if (columnIndex >= tbl.len) return DBStatus::CORRUPTED_DATA;
                // UNIQUE permits multiple SQL NULLs. Empty non-NULL strings
                // are ordinary values and must still be compared.
                if (newColumnIsNull(columnIndex)) return DBStatus::OK;
                const std::string& columnName = tbl.cols[columnIndex].dataName;
                const std::string rawNewValue =
                    valueFromRowMap(rowValues, columnName);
                newValues.push_back(rawNewValue);
                const bool oldIsNull =
                    columnIndex < oldNullColumns.size() &&
                    oldNullColumns[columnIndex];
                if (oldIsNull || !constraintColumnValuesEqual(
                        tbl.cols[columnIndex], valueFromRowMap(
                            oldLogicalValues, columnName),
                        newValues.back())) {
                    keyChanged = true;
                }
            }
            if (!keyChanged) return DBStatus::OK;

            if (columns.size() == 1 &&
                transactionContext().inTransaction &&
                isConstraintCurrentlyDeferred(
                    dbname, tablename, constraintName)) {
                DeferredCheck check;
                check.kind = DeferredCheck::Kind::Unique;
                check.dbname = dbname;
                check.tablename = tablename;
                check.rid = rid;
                check.constraintName = constraintName;
                check.colIdx = columns.front();
                check.uniqueCol = tbl.cols[columns.front()].dataName;
                check.payloadValue = newValues.front();
                check.exceptRid = rid;
                pendingDeferredUniqueChecks.push_back(std::move(check));
                return DBStatus::OK;
            }

            auto& statementKeys = statementImmediateUniqueKeys[columns];
            bool alreadyRecordedForRow = false;
            for (const auto& [otherRid, otherValues] : statementKeys) {
                if (!constraintKeyValuesEqual(
                        tbl, columns, otherValues, newValues)) {
                    continue;
                }
                if (otherRid != rid) return DBStatus::DUPLICATE_KEY;
                alreadyRecordedForRow = true;
            }

            bool duplicate = false;
            const bool scanOk = forEachRow(
                dbname, tablename,
                [&](uint32_t otherPage, uint16_t otherSlot,
                    const char* data, size_t length) {
                    if (duplicate ||
                        encodeRid(otherPage, otherSlot) == rid) {
                        return;
                    }
                    const std::string otherRow(data, length);
                    for (size_t valueIndex = 0;
                         valueIndex < columns.size(); ++valueIndex) {
                        const size_t columnIndex = columns[valueIndex];
                        const int64_t otherRid =
                            encodeRid(otherPage, otherSlot);
                        if (tbl.cols[columnIndex].isNull &&
                            dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, otherRid, columnIndex)) {
                            return;
                        }
                        if (!constraintColumnValuesEqual(
                                tbl.cols[columnIndex],
                                extractColumnValue(
                                    otherRow, tbl, columnIndex, dbname),
                                newValues[valueIndex])) {
                            return;
                        }
                    }
                    duplicate = true;
                });
            if (!scanOk) return DBStatus::IO_ERROR;
            if (duplicate) return DBStatus::DUPLICATE_KEY;
            if (!alreadyRecordedForRow) {
                statementKeys.emplace_back(rid, std::move(newValues));
            }
            return DBStatus::OK;
        };

        if (tbl.hasPrimaryKey()) {
            std::vector<size_t> primaryColumns;
            if (!collectPrimaryKeyColumns(tbl, primaryColumns) ||
                primaryColumns.empty()) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            // Primary keys remain immediate in this storage layer. Passing an
            // empty constraint name prevents the UNIQUE deferral branch while
            // reusing its collation-aware tuple scan.
            const DBStatus primaryStatus =
                validateUniqueUpdate(primaryColumns, {});
            if (primaryStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return primaryStatus;
            }
        }

        for (const auto& metadata : secondaryIndexMetadata) {
            if (!metadata.isUnique) continue;
            if (metadata.isExpression ||
                !metadata.whereCondition.empty()) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            size_t columnIndex = tbl.len;
            for (size_t candidate = 0; candidate < tbl.len; ++candidate) {
                if (tbl.cols[candidate].dataName == metadata.name) {
                    columnIndex = candidate;
                    break;
                }
            }
            if (columnIndex >= tbl.len) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            const DBStatus indexStatus =
                validateUniqueUpdate({columnIndex}, {});
            if (indexStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return indexStatus;
            }
        }
        for (const auto& metadata : compositeIndexMetadata) {
            if (!metadata.isUnique) continue;
            if (!metadata.whereCondition.empty()) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            std::vector<size_t> columns;
            std::set<size_t> distinctColumns;
            for (const auto& columnName : metadata.columns) {
                size_t columnIndex = tbl.len;
                for (size_t candidate = 0; candidate < tbl.len;
                     ++candidate) {
                    if (tbl.cols[candidate].dataName == columnName) {
                        columnIndex = candidate;
                        break;
                    }
                }
                if (columnIndex >= tbl.len ||
                    !distinctColumns.insert(columnIndex).second) {
                    lockManager_.unlock(tablename);
                    return DBStatus::CORRUPTED_DATA;
                }
                columns.push_back(columnIndex);
            }
            const DBStatus indexStatus =
                validateUniqueUpdate(columns, {});
            if (indexStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return indexStatus;
            }
        }

        for (size_t columnIndex = 0; columnIndex < tbl.len; ++columnIndex) {
            if (!tbl.cols[columnIndex].isUnique) continue;
            const std::string constraintName =
                tablename + "_" + tbl.cols[columnIndex].dataName + "_key";
            const DBStatus uniqueStatus = validateUniqueUpdate(
                {columnIndex}, constraintName);
            if (uniqueStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return uniqueStatus;
            }
        }
        for (size_t constraintIndex = 0;
             constraintIndex < tbl.uniqueConstraints.size();
             ++constraintIndex) {
            const auto& columns = tbl.uniqueConstraints[constraintIndex];
            std::string constraintName;
            if (constraintIndex < tbl.uniqueConstraintNames.size()) {
                constraintName = tbl.uniqueConstraintNames[constraintIndex];
            }
            if (constraintName.empty() && !columns.empty() &&
                columns.front() < tbl.len) {
                constraintName = tablename + "_" +
                    tbl.cols[columns.front()].dataName + "_key";
            }
            const DBStatus uniqueStatus =
                validateUniqueUpdate(columns, constraintName);
            if (uniqueStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return uniqueStatus;
            }
        }

        // Keep the primary index synchronized when the primary key changes.
        std::string newPK = tbl.buildPKValue(rowValues);
        if (tbl.hasPrimaryKey() && oldPK != newPK && !newPK.empty()) {
            BPTree* primaryIndex = getPKIndex(dbname, tablename);
            if (!primaryIndex) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            int64_t existingRid = -1;
            if (primaryIndex->search(newPK, existingRid) &&
                existingRid != rid) {
                lockManager_.unlock(tablename);
                return DBStatus::DUPLICATE_KEY;
            }
        }

        // A foreign key may reference any declared UNIQUE key, not only the
        // primary key. Avoid scanning child relations for payload-only
        // updates, but enter the action path whenever any candidate key
        // column changes.
        std::set<size_t> referencedKeyCandidates;
        for (size_t columnIndex = 0; columnIndex < tbl.len; ++columnIndex) {
            if (tbl.cols[columnIndex].isPrimaryKey ||
                tbl.cols[columnIndex].isUnique) {
                referencedKeyCandidates.insert(columnIndex);
            }
        }
        for (const size_t columnIndex : tbl.pkColIndices) {
            if (columnIndex >= tbl.len) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            referencedKeyCandidates.insert(columnIndex);
        }
        for (const auto& uniqueColumns : tbl.uniqueConstraints) {
            for (const size_t columnIndex : uniqueColumns) {
                if (columnIndex >= tbl.len) {
                    lockManager_.unlock(tablename);
                    return DBStatus::CORRUPTED_DATA;
                }
                referencedKeyCandidates.insert(columnIndex);
            }
        }
        bool referencedKeyCandidateChanged = false;
        for (const size_t columnIndex : referencedKeyCandidates) {
            const bool oldIsNull =
                tbl.cols[columnIndex].generatedKind != 'v' &&
                columnIndex < oldNullColumns.size() &&
                oldNullColumns[columnIndex];
            const bool newIsNull = newColumnIsNull(columnIndex);
            if (oldIsNull != newIsNull ||
                (!oldIsNull && !newIsNull &&
                 canonicalColumnKeyValue(
                     tbl.cols[columnIndex],
                     valueFromRowMap(
                         oldLogicalValues,
                         tbl.cols[columnIndex].dataName)) !=
                     canonicalColumnKeyValue(
                         tbl.cols[columnIndex],
                         valueFromRowMap(
                             rowValues,
                             tbl.cols[columnIndex].dataName)))) {
                referencedKeyCandidateChanged = true;
                break;
            }
        }
        if (referencedKeyCandidateChanged) {
            // Collect all referencing rows and their ON UPDATE actions.
            struct UpdateCascadeAction {
                std::string table;
                int64_t rid;
                SqlRow newFkVals;
            };
            struct UpdateSetNullAction { std::string table; int64_t rid; std::vector<size_t> colIndices; };
            std::vector<UpdateCascadeAction> updateCascadeActions;
            std::vector<UpdateSetNullAction> updateSetNullActions;
            std::set<std::string> restrictTables;

            std::vector<std::string> sortedTables;
            std::vector<std::string> acquiredTables;
            {
                auto allTables = getTableNames(dbname);
                DBStatus dependencyScanStatus = DBStatus::OK;
                std::set<std::string> referencingTables;
                for (const auto& otherTable : allTables) {
                    if (otherTable == tablename) continue;
                    const TableSchema otherTbl =
                        getTableSchema(dbname, otherTable);
                    for (size_t fi = 0; fi < otherTbl.fkLen; ++fi) {
                        if (otherTbl.fks[fi].refTable == tablename) {
                            referencingTables.insert(otherTable);
                            break;
                        }
                    }
                }
                sortedTables.assign(
                    referencingTables.begin(), referencingTables.end());
                std::sort(sortedTables.begin(), sortedTables.end());
                for (const auto& tableName : sortedTables) {
                    if (!lockManager_.lockIntentExclusive(tableName)) {
                        for (const auto& acquired : acquiredTables) {
                            lockManager_.unlock(acquired);
                        }
                        lockManager_.unlock(tablename);
                        if (transactionContext().inTransaction) {
                            rollbackTransaction();
                        }
                        return DBStatus::LOCK_CONFLICT;
                    }
                    acquiredTables.push_back(tableName);
                }

                for (const auto& otherTable : allTables) {
                    if (dependencyScanStatus != DBStatus::OK) break;
                    TableSchema otherTbl = getTableSchema(dbname, otherTable);
                    for (size_t fi = 0; fi < otherTbl.fkLen; ++fi) {
                        const ForeignKey& fk = otherTbl.fks[fi];
                        if (fk.refTable != tablename) continue;

                        ValidatedForeignKeyDefinition definition;
                        if (validateForeignKeyDefinition(
                                otherTbl, tbl, fk.colNames, fk.refCols,
                                definition) != DBStatus::OK) {
                            dependencyScanStatus = DBStatus::CORRUPTED_DATA;
                            break;
                        }
                        const auto& fkColIndices =
                            definition.localColumnIndices;
                        const auto& referencedColumnIndices =
                            definition.referencedColumnIndices;

                        bool referencedKeyChanged = false;
                        bool oldReferencedKeyHasNull = false;
                        std::vector<std::string> oldReferencedValues;
                        oldReferencedValues.reserve(
                            referencedColumnIndices.size());
                        for (const size_t referencedColumnIndex :
                             referencedColumnIndices) {
                            const bool oldIsNull =
                                tbl.cols[referencedColumnIndex]
                                        .generatedKind != 'v' &&
                                referencedColumnIndex <
                                    oldNullColumns.size() &&
                                oldNullColumns[referencedColumnIndex];
                            const bool newIsNull =
                                newColumnIsNull(referencedColumnIndex);
                            oldReferencedKeyHasNull =
                                oldReferencedKeyHasNull || oldIsNull;
                            const std::string oldValue = oldIsNull
                                ? std::string()
                                : canonicalColumnKeyValue(
                                      tbl.cols[referencedColumnIndex],
                                      valueFromRowMap(
                                          oldLogicalValues,
                                          tbl.cols[referencedColumnIndex]
                                              .dataName));
                            const std::string newValue = newIsNull
                                ? std::string()
                                : canonicalColumnKeyValue(
                                      tbl.cols[referencedColumnIndex],
                                      valueFromRowMap(
                                          rowValues,
                                          tbl.cols[referencedColumnIndex]
                                              .dataName));
                            referencedKeyChanged = referencedKeyChanged ||
                                oldIsNull != newIsNull ||
                                (!oldIsNull && !newIsNull &&
                                 oldValue != newValue);
                            oldReferencedValues.push_back(oldValue);
                        }
                        if (!referencedKeyChanged ||
                            oldReferencedKeyHasNull) {
                            continue;
                        }

                        if (!forEachRow(dbname, otherTable, [&](uint32_t opid, uint16_t osid, const char* data, size_t len) {
                            const std::string oRow(data, len);
                            const int64_t orid = encodeRid(opid, osid);
                            bool matched = true;
                            for (size_t valueIndex = 0;
                                 valueIndex < fkColIndices.size();
                                 ++valueIndex) {
                                const size_t localColumnIndex =
                                    fkColIndices[valueIndex];
                                if (otherTbl.cols[localColumnIndex].isNull &&
                                    dbms::detail::storedRowColumnIsNull(*this, dbname, otherTable, otherTbl, orid, localColumnIndex)) {
                                    matched = false;
                                    break;
                                }
                                const Column& referencedColumn =
                                    tbl.cols[
                                        referencedColumnIndices[valueIndex]];
                                if (canonicalColumnKeyValue(
                                        referencedColumn,
                                        extractColumnValue(
                                            oRow, otherTbl,
                                            localColumnIndex, dbname)) !=
                                    oldReferencedValues[valueIndex]) {
                                    matched = false;
                                    break;
                                }
                            }
                            if (matched) {
                                // The active parent RID's self-reference was
                                // folded into rowValues before validation.
                                if (otherTable == tablename && orid == rid) {
                                    return;
                                }
                                if (fk.onUpdate == "cascade") {
                                    UpdateCascadeAction ca;
                                    ca.table = otherTable;
                                    ca.rid = orid;
                                    for (size_t valueIndex = 0;
                                         valueIndex < fk.colNames.size();
                                         ++valueIndex) {
                                        const size_t referencedColumnIndex =
                                            referencedColumnIndices[
                                                valueIndex];
                                        if (newColumnIsNull(
                                                referencedColumnIndex)) {
                                            ca.newFkVals[
                                                fk.colNames[valueIndex]] =
                                                std::nullopt;
                                        } else {
                                            ca.newFkVals[
                                                fk.colNames[valueIndex]] =
                                                valueFromRowMap(
                                                    rowValues,
                                                    tbl.cols[
                                                        referencedColumnIndex]
                                                        .dataName);
                                        }
                                    }
                                    if (!ca.newFkVals.empty()) updateCascadeActions.push_back(std::move(ca));
                                } else if (fk.onUpdate == "setnull") {
                                    updateSetNullActions.push_back({otherTable, orid, fkColIndices});
                                } else {
                                    restrictTables.insert(otherTable);
                                }
                            }
                        })) {
                            dependencyScanStatus = DBStatus::IO_ERROR;
                            break;
                        }
                    }
                }
                if (dependencyScanStatus != DBStatus::OK) {
                    for (const auto& acquired : acquiredTables) {
                        lockManager_.unlock(acquired);
                    }
                    lockManager_.unlock(tablename);
                    return dependencyScanStatus;
                }
            }

            if (!restrictTables.empty()) {
                for (const auto& acquired : acquiredTables) {
                    lockManager_.unlock(acquired);
                }
                lockManager_.unlock(tablename);
                return DBStatus::FOREIGN_KEY_VIOLATION;
            }

            bool cascadeMarkersOk =
                markSpecializedIndexesBeforeMutation(dbname, tablename);
            for (const auto& tableName : sortedTables) {
                if (!markSpecializedIndexesBeforeMutation(
                        dbname, tableName)) {
                    cascadeMarkersOk = false;
                }
            }
            if (!cascadeMarkersOk) {
                for (const auto& acquired : acquiredTables) {
                    lockManager_.unlock(acquired);
                }
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }

            using ReferentialValues = SqlRow;
            std::map<std::string,
                     std::map<int64_t, ReferentialValues>> rowUpdates;
            for (const auto& sa : updateSetNullActions) {
                TableSchema child = getTableSchema(dbname, sa.table);
                auto& values = rowUpdates[sa.table][sa.rid];
                for (const size_t columnIndex : sa.colIndices) {
                    if (columnIndex < child.len) {
                        values[child.cols[columnIndex].dataName] = std::nullopt;
                    }
                }
            }
            for (const auto& ca : updateCascadeActions) {
                auto& values = rowUpdates[ca.table][ca.rid];
                for (const auto& [column, value] : ca.newFkVals) {
                    values[column] = value;
                }
            }

            // Group rows that receive the same logical assignment. This keeps
            // one statement-level DML call per assignment while retaining the
            // exact RID identity discovered by the FK scan.
            std::map<std::string,
                     std::map<ReferentialValues, std::set<int64_t>>>
                groupedUpdates;
            for (const auto& [tableName, rows] : rowUpdates) {
                for (const auto& [rid, values] : rows) {
                    if (!values.empty()) {
                        groupedUpdates[tableName][values].insert(rid);
                    }
                }
            }

            DBStatus actionStatus = DBStatus::OK;
            for (const auto& [tableName, groups] : groupedUpdates) {
                for (const auto& [values, rows] : groups) {
                    std::map<std::string, std::string> rawValues;
                    std::set<std::string> nullColumns;
                    splitSqlRow(values, rawValues, nullColumns);
                    actionStatus = updateInternal(
                        dbname, tableName, rawValues, nullColumns, {}, nullptr,
                        SqlUpdateResolver{}, SqlUpdateMatcher{}, &rows,
                        referentialContext);
                    if (actionStatus != DBStatus::OK) break;
                }
                if (actionStatus != DBStatus::OK) break;
            }

            bool cascadeSpecializedIndexesOk = true;
            for (const auto& tableName : sortedTables) {
                if (!maintainSpecializedIndexesAfterMutation(
                        dbname, tableName)) {
                    cascadeSpecializedIndexesOk = false;
                }
            }
            for (const auto& t : sortedTables) {
                lockManager_.unlock(t);
            }
            if (actionStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                return actionStatus;
            }
            if (!cascadeSpecializedIndexesOk) {
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
        }

        // Allocate new external values only after every pre-write check has
        // passed.  The old chunks remain reachable through txnLog until
        // COMMIT; rollback removes only chunks referenced by the new row.
        if (!markSpecializedIndexesBeforeMutation(dbname, tablename)) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
        std::map<std::string, std::string> storedRowValues = rowValues;
        if (!prepareToastValues(dbname, tablename, tbl, storedRowValues)) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }

        // Log only after every trigger/constraint/cascade has succeeded and
        // immediately before the main row mutation.  Besides avoiding an
        // undo record for a row that was never changed, this preserves true
        // reverse mutation order when a cascading action logged its own rows.
        std::optional<size_t> updateLogIndex;
        if (transactionContext().inTransaction &&
            dbname == transactionContext().txnDB) {
            logTxnUpdate(tablename, rid, row);
            updateLogIndex = transactionContext().txnLog.size() - 1;
        }
        newRow = buildRowBuffer(
            tbl, storedRowValues, updateTxnId, &physicalNullColumns);
        if (updateTxnId != 0) {
            setRowCid(newRow.data(), newRow.size(), tbl.formatVersion,
                      transactionContext().currentCommandId);
        }
        strippedNewRow = stripRowHeader(newRow, tbl.formatVersion, tbl.len);

        int64_t actualRid = rid;
        const bool versionedUpdate =
            usesHeapTupleHeader(tbl.formatVersion) &&
            transactionContext().inTransaction &&
            dbname == transactionContext().txnDB;

        if (versionedUpdate) {
            if (!updateLogIndex ||
                *updateLogIndex >= transactionContext().txnLog.size() ||
                transactionContext().txnLog[*updateLogIndex].op !=
                    TxnLogEntry::Op::Update ||
                transactionContext().txnLog[*updateLogIndex].rowIdx != rid) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                lockManager_.unlock(tablename);
                const DBStatus rollbackStatus = rollbackTransaction();
                return rollbackStatus == DBStatus::OK
                    ? DBStatus::IO_ERROR : rollbackStatus;
            }

            // Insert NEW first.  Other snapshots reject its uncommitted xmin,
            // while the writer can see it immediately.  OLD remains intact
            // until its xmax/ctid are changed below.
            auto tryInsertVersion = [&](uint32_t candidate, bool& inserted,
                                        uint16_t& insertedSlot) -> DBStatus {
                if (!lockManager_.pageLockExclusive(
                        dbname, tablename, candidate)) {
                    return DBStatus::LOCK_CONFLICT;
                }
                char* buffer = pa->fetchPage(candidate);
                if (!buffer) {
                    lockManager_.pageUnlock(dbname, tablename, candidate);
                    return DBStatus::IO_ERROR;
                }
                PageWrapper page(buffer, pa->pageSize(), tbl.formatVersion);
                if (!page.isValid()) {
                    pa->unpinPage(candidate);
                    lockManager_.pageUnlock(dbname, tablename, candidate);
                    return DBStatus::CORRUPTED_DATA;
                }
                DBStatus writeStatus = DBStatus::OK;
                if (page.canFit(newRow.size())) {
                    const Lsn beforeLsn = walPageImage(
                        dbname, tablename, candidate, buffer,
                        pa->pageSize(), true);
                    if (beforeLsn == INVALID_LSN) {
                        writeStatus = DBStatus::IO_ERROR;
                    } else {
                        std::vector<char> stagedBuffer(
                            buffer, buffer + pa->pageSize());
                        PageWrapper stagedPage(
                            stagedBuffer.data(), pa->pageSize(),
                            tbl.formatVersion);
                        uint16_t stagedSlot = 0;
                        const bool stagedInsert = stagedPage.insert(
                            newRow.data(), newRow.size(), stagedSlot);
                        const char* insertedData = nullptr;
                        size_t insertedLength = 0;
                        bool finalized = stagedInsert && stagedPage.read(
                            stagedSlot, insertedData, insertedLength);
                        if (finalized) {
                            std::string mutableNew(insertedData, insertedLength);
                            setRowCtid(
                                mutableNew.data(), mutableNew.size(),
                                tbl.formatVersion,
                                ItemPointer{
                                    candidate,
                                    static_cast<OffsetNumber>(stagedSlot + 1)});
                            finalized = stagedPage.update(
                                stagedSlot, mutableNew.data(),
                                mutableNew.size());
                        }
                        if (stagedInsert && !finalized) {
                            writeStatus = DBStatus::CORRUPTED_DATA;
                        } else if (finalized) {
                            const Lsn lsn = walPageImage(
                                dbname, tablename, candidate,
                                stagedBuffer.data(), pa->pageSize(), false);
                            if (lsn == INVALID_LSN) {
                                writeStatus = DBStatus::IO_ERROR;
                            } else {
                                std::memcpy(
                                    buffer, stagedBuffer.data(),
                                    pa->pageSize());
                                setPageLsnAndChecksum(buffer, lsn);
                                insertedSlot = stagedSlot;
                                inserted = true;
                                const size_t freePercent =
                                    stagedPage.freeSpace() * 100 /
                                    pa->pageSize();
                                getFSM(dbname, tablename)->setFreePercent(
                                    candidate,
                                    static_cast<uint8_t>(freePercent));
                                getVM(dbname, tablename)->setAllVisible(
                                    candidate, false);
                            }
                        }
                        if (inserted) {
                            pa->markDirty(candidate);
                        }
                    }
                }
                pa->unpinPage(candidate);
                lockManager_.pageUnlock(dbname, tablename, candidate);
                return writeStatus;
            };

            uint32_t newPageId = 0;
            uint16_t newSlotId = 0;
            bool inserted = false;
            DBStatus insertStatus = DBStatus::OK;
            const uint32_t pageCount = pa->numPages();
            for (uint32_t candidate = 1;
                 candidate < pageCount && !inserted; ++candidate) {
                insertStatus = tryInsertVersion(
                    candidate, inserted, newSlotId);
                if (insertStatus != DBStatus::OK) break;
                if (inserted) newPageId = candidate;
            }
            if (insertStatus == DBStatus::OK && !inserted) {
                newPageId = pa->allocPage();
                if (newPageId == 0) {
                    insertStatus = DBStatus::IO_ERROR;
                } else {
                    insertStatus = tryInsertVersion(
                        newPageId, inserted, newSlotId);
                    if (insertStatus == DBStatus::OK && !inserted)
                        insertStatus = DBStatus::INVALID_VALUE;
                }
            }
            if (insertStatus != DBStatus::OK) {
                // NEW never became reachable, so remove its external values
                // directly.  Abort the transaction to undo earlier rows from
                // the same multi-row UPDATE statement.
                deleteToastForRow(dbname, tablename, strippedNewRow);
                transactionContext().txnLog.erase(
                    transactionContext().txnLog.begin() +
                    static_cast<std::ptrdiff_t>(*updateLogIndex));
                lockManager_.unlock(tablename);
                const DBStatus rollbackStatus = rollbackTransaction();
                return rollbackStatus == DBStatus::OK
                    ? insertStatus : rollbackStatus;
            }

            actualRid = encodeRid(newPageId, newSlotId);
            TxnLogEntry& updateLog =
                transactionContext().txnLog[*updateLogIndex];
            updateLog.previousRowIdx = rid;
            updateLog.rowIdx = actualRid;
            updateLog.newRowData = strippedNewRow;

            // Retire OLD without overwriting its body.  Keeping it as a
            // normal line pointer is essential: redirecting it now would make
            // snapshots that predate this update follow NEW incorrectly.
            DBStatus retireStatus = DBStatus::OK;
            if (!lockManager_.pageLockExclusive(dbname, tablename, pageId)) {
                retireStatus = DBStatus::LOCK_CONFLICT;
            } else {
                char* oldPageBuffer = pa->fetchPage(pageId);
                if (!oldPageBuffer) {
                    retireStatus = DBStatus::IO_ERROR;
                } else {
                    PageWrapper oldPage(
                        oldPageBuffer, pa->pageSize(), tbl.formatVersion);
                    const char* oldData = nullptr;
                    size_t oldLength = 0;
                    if (!oldPage.isValid() ||
                        !oldPage.read(slotId, oldData, oldLength) ||
                        stripRowHeader(oldData, oldLength, tbl.formatVersion,
                                       tbl.len) != row) {
                        retireStatus = DBStatus::CORRUPTED_DATA;
                    } else {
                        const Lsn beforeLsn = walPageImage(
                            dbname, tablename, pageId, oldPageBuffer,
                            pa->pageSize(), true);
                        if (beforeLsn == INVALID_LSN) {
                            retireStatus = DBStatus::IO_ERROR;
                        } else {
                            std::vector<char> stagedOldBuffer(
                                oldPageBuffer,
                                oldPageBuffer + pa->pageSize());
                            PageWrapper stagedOldPage(
                                stagedOldBuffer.data(), pa->pageSize(),
                                tbl.formatVersion);
                            std::string mutableOld(oldData, oldLength);
                            if (!markTupleDeletedByCurrentCommand(
                                    mutableOld.data(), mutableOld.size(),
                                    tbl.formatVersion)) {
                                retireStatus = DBStatus::CORRUPTED_DATA;
                            }
                            setRowCtid(
                                mutableOld.data(), mutableOld.size(),
                                tbl.formatVersion,
                                ItemPointer{
                                    newPageId,
                                    static_cast<OffsetNumber>(newSlotId + 1)});
                            auto* oldHeader = castHeapHeader(mutableOld.data());
                            oldHeader->t_infomask |= HEAP_UPDATED;
                            oldHeader->t_infomask &= ~(
                                HEAP_XMAX_COMMITTED | HEAP_XMAX_INVALID |
                                HEAP_XMAX_EXCL_LOCK | HEAP_XMAX_KEYSHR_LOCK |
                                HEAP_XMAX_LOCK_ONLY | HEAP_XMAX_IS_MULTI);
                            if (retireStatus == DBStatus::OK) {
                                if (!stagedOldPage.update(
                                        slotId, mutableOld.data(),
                                        mutableOld.size())) {
                                    retireStatus = DBStatus::IO_ERROR;
                                } else {
                                    const Lsn lsn = walPageImage(
                                        dbname, tablename, pageId,
                                        stagedOldBuffer.data(), pa->pageSize(),
                                        false);
                                    if (lsn == INVALID_LSN) {
                                        retireStatus = DBStatus::IO_ERROR;
                                    } else {
                                        std::memcpy(
                                            oldPageBuffer,
                                            stagedOldBuffer.data(),
                                            pa->pageSize());
                                        setPageLsnAndChecksum(oldPageBuffer, lsn);
                                        pa->markDirty(pageId);
                                        getVM(dbname, tablename)->setAllVisible(
                                            pageId, false);
                                    }
                                }
                            }
                        }
                    }
                    pa->unpinPage(pageId);
                }
                lockManager_.pageUnlock(dbname, tablename, pageId);
            }
            if (retireStatus != DBStatus::OK) {
                lockManager_.unlock(tablename);
                const DBStatus rollbackStatus = rollbackTransaction();
                return rollbackStatus == DBStatus::OK
                    ? retireStatus : rollbackStatus;
            }

            // Commit writeback needs both sides of a cross-page version
            // chain, irrespective of whether SSI bookkeeping is enabled.
            transactionContext().txnHeapWritebackPages.insert(
                {tablename, pageId});
            transactionContext().txnHeapWritebackPages.insert(
                {tablename, newPageId});
            if (transactionContext().txnIsolationLevel ==
                IsolationLevel::SERIALIZABLE) {
                const std::string newRidKey =
                    ssiRidKey(dbname, tablename, actualRid);
                transactionContext().txnWrittenPages.insert(
                    ssiPageKey(dbname, tablename, newPageId));
                transactionContext().txnWrittenRids.insert(newRidKey);
                std::lock_guard<std::mutex> ssiLock(ssiMutex_);
                ssiWriteSets_[transactionContext().currentTxnId].insert(
                    newRidKey);
                ssiWritePages_[transactionContext().currentTxnId].insert(
                    ssiPageKey(dbname, tablename, newPageId));
            }
        } else {
            // Autocommit callers do not own an xid.  Preserve the existing
            // single-version update behavior for them.
            if (!lockManager_.pageLockExclusive(
                    dbname, tablename, pageId)) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                lockManager_.unlockAll();
                lockManager_.unlockAllGaps();
                return DBStatus::LOCK_CONFLICT;
            }
            char* pageBuffer = pa->fetchPage(pageId);
            if (!pageBuffer) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            PageWrapper page(pageBuffer, pa->pageSize(), tbl.formatVersion);
            if (!page.isValid()) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            const Lsn beforeLsn = walPageImage(
                dbname, tablename, pageId, pageBuffer,
                pa->pageSize(), true);
            if (beforeLsn == INVALID_LSN) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            std::vector<char> stagedPageBuffer(
                pageBuffer, pageBuffer + pa->pageSize());
            PageWrapper stagedPage(
                stagedPageBuffer.data(), pa->pageSize(), tbl.formatVersion);
            uint16_t newSlotId = slotId;
            if (!stagedPage.update(
                    slotId, newRow.data(), newRow.size(), newSlotId)) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                lockManager_.unlock(tablename);
                return DBStatus::INVALID_VALUE;
            }
            actualRid = encodeRid(pageId, newSlotId);
            const char* finalData = nullptr;
            size_t finalLength = 0;
            if (!stagedPage.read(newSlotId, finalData, finalLength)) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            std::string mutableFinal(finalData, finalLength);
            setRowCtid(
                mutableFinal.data(), mutableFinal.size(), tbl.formatVersion,
                ItemPointer{
                    pageId, static_cast<OffsetNumber>(newSlotId + 1)});
            if (!stagedPage.update(
                    newSlotId, mutableFinal.data(), mutableFinal.size())) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            const Lsn lsn = walPageImage(
                dbname, tablename, pageId, stagedPageBuffer.data(),
                pa->pageSize(), false);
            if (lsn == INVALID_LSN) {
                deleteToastForRow(dbname, tablename, strippedNewRow);
                pa->unpinPage(pageId);
                lockManager_.pageUnlock(dbname, tablename, pageId);
                lockManager_.unlock(tablename);
                return DBStatus::IO_ERROR;
            }
            std::memcpy(
                pageBuffer, stagedPageBuffer.data(), pa->pageSize());
            setPageLsnAndChecksum(pageBuffer, lsn);
            pa->markDirty(pageId);
            const size_t freePercent =
                stagedPage.freeSpace() * 100 / pa->pageSize();
            getFSM(dbname, tablename)->setFreePercent(
                pageId, static_cast<uint8_t>(freePercent));
            getVM(dbname, tablename)->setAllVisible(pageId, false);
            pa->unpinPage(pageId);
            lockManager_.pageUnlock(dbname, tablename, pageId);
        }
        newVersionRids[rid] = actualRid;

        if (versionedUpdate) {
            auto& deferred = transactionContext().deferredChecks[
                transactionContext().currentTxnId];
            for (size_t deferredIndex = deferredEntryStart;
                 deferredIndex < deferred.size(); ++deferredIndex) {
                DeferredCheck& check = deferred[deferredIndex];
                if (check.dbname != dbname ||
                    check.tablename != tablename) {
                    continue;
                }
                if (check.rid == rid) check.rid = actualRid;
                if (check.exceptRid == rid) check.exceptRid = actualRid;
            }
        }
        if (!pendingDeferredUniqueChecks.empty()) {
            auto& deferred = transactionContext().deferredChecks[
                transactionContext().currentTxnId];
            for (auto& check : pendingDeferredUniqueChecks) {
                check.rid = actualRid;
                check.exceptRid = actualRid;
                deferred.push_back(std::move(check));
            }
        }
        if (!pendingDeferredForeignKeyChecks.empty()) {
            auto& deferred = transactionContext().deferredChecks[
                transactionContext().currentTxnId];
            for (auto& check : pendingDeferredForeignKeyChecks) {
                check.rid = actualRid;
                deferred.push_back(std::move(check));
            }
        }

        // Outside an explicit transaction the heap update is now complete,
        // so the old external values can be reclaimed safely.  In a
        // transaction they remain reachable through txnLog until COMMIT.
        if (!(transactionContext().inTransaction && dbname == transactionContext().txnDB)) {
            deleteToastForRow(dbname, tablename, row);
        }

        const auto containsIndexRid = [](const std::vector<int64_t>& values,
                                         int64_t expectedRid) {
            return std::find(values.begin(), values.end(), expectedRid) !=
                   values.end();
        };
        const auto indexMaintenanceFailure = [&]() {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        };

        // Update PK index if PK was updated or RID changed. Every expected
        // OLD mapping must exist and every mutation must complete; otherwise
        // the statement savepoint restores the heap and all earlier indexes.
        if (tbl.hasPrimaryKey()) {
            BPTree* pkIdx = getPKIndex(dbname, tablename);
            if (!pkIdx || !pkIdx->isOpen() || oldPK.empty() || newPK.empty()) {
                return indexMaintenanceFailure();
            }
            if (oldPK != newPK) {
                int64_t indexedRid = -1;
                if (!pkIdx->search(oldPK, indexedRid) || indexedRid != rid ||
                    !pkIdx->remove(oldPK) ||
                    !pkIdx->insert(newPK, actualRid)) {
                    return indexMaintenanceFailure();
                }
            } else if (actualRid != rid) {
                // RID changed but PK same: re-insert with new RID
                int64_t indexedRid = -1;
                if (!pkIdx->search(newPK, indexedRid) || indexedRid != rid ||
                    !pkIdx->remove(newPK) ||
                    !pkIdx->insert(newPK, actualRid)) {
                    return indexMaintenanceFailure();
                }
            }
        }

        // Maintain ordinary/expression keys and partial-index membership from
        // the logical OLD/NEW images computed before the heap mutation.
        for (const auto& transition : secondaryIndexTransitions) {
            BPTree* index = getSecondaryIndex(
                dbname, tablename, transition.newEntry.name);
            if (!index || !index->isOpen()) {
                return indexMaintenanceFailure();
            }
            const bool keyChanged =
                transition.oldEntry.included != transition.newEntry.included ||
                transition.oldEntry.key != transition.newEntry.key;
            if (keyChanged) {
                if (transition.oldEntry.included &&
                    !transition.oldEntry.key.empty()) {
                    if (!containsIndexRid(
                            index->searchMulti(transition.oldEntry.key), rid) ||
                        !index->removeMulti(transition.oldEntry.key, rid)) {
                        return indexMaintenanceFailure();
                    }
                }
                if (transition.newEntry.included &&
                    !transition.newEntry.key.empty()) {
                    if (containsIndexRid(
                            index->searchMulti(transition.newEntry.key),
                            actualRid) ||
                        !index->insertMulti(
                            transition.newEntry.key, actualRid)) {
                        return indexMaintenanceFailure();
                    }
                }
            } else if (actualRid != rid && transition.newEntry.included &&
                       !transition.newEntry.key.empty()) {
                if (!containsIndexRid(
                        index->searchMulti(transition.newEntry.key), rid) ||
                    !index->removeMulti(transition.newEntry.key, rid) ||
                    containsIndexRid(
                        index->searchMulti(transition.newEntry.key),
                        actualRid) ||
                    !index->insertMulti(
                        transition.newEntry.key, actualRid)) {
                    return indexMaintenanceFailure();
                }
            }
        }

        // A changed indexed value is a write to both the old and new logical
        // key.  The old key is recorded before the heap mutation by
        // logTxnUpdate; record the new key after the index maintenance so SSI
        // also detects a concurrent predicate that covers the new value.
        if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
            withNewRowNulls([&] {
                recordSsiIndexKeys(dbname, tablename, strippedNewRow, tbl);
            });
        }

        // Update composite indexes, including predicate-only transitions.
        for (const auto& transition : compositeIndexTransitions) {
            BPTree* index = getCompositeIndexTree(
                dbname, tablename, transition.newEntry.name);
            if (!index || !index->isOpen()) {
                return indexMaintenanceFailure();
            }
            const bool keyChanged =
                transition.oldEntry.included != transition.newEntry.included ||
                transition.oldEntry.key != transition.newEntry.key;
            if (keyChanged) {
                if (transition.oldEntry.included &&
                    !transition.oldEntry.key.empty()) {
                    if (!containsIndexRid(
                            index->searchMulti(transition.oldEntry.key), rid) ||
                        !index->removeMulti(transition.oldEntry.key, rid)) {
                        return indexMaintenanceFailure();
                    }
                }
                if (transition.newEntry.included &&
                    !transition.newEntry.key.empty()) {
                    if (containsIndexRid(
                            index->searchMulti(transition.newEntry.key),
                            actualRid) ||
                        !index->insertMulti(
                            transition.newEntry.key, actualRid)) {
                        return indexMaintenanceFailure();
                    }
                }
            } else if (actualRid != rid && transition.newEntry.included &&
                       !transition.newEntry.key.empty()) {
                if (!containsIndexRid(
                        index->searchMulti(transition.newEntry.key), rid) ||
                    !index->removeMulti(transition.newEntry.key, rid) ||
                    containsIndexRid(
                        index->searchMulti(transition.newEntry.key),
                        actualRid) ||
                    !index->insertMulti(
                        transition.newEntry.key, actualRid)) {
                    return indexMaintenanceFailure();
                }
            }
        }

        // Update hash indexes
        auto hashIdxCols = getHashIndexedColumns(dbname, tablename);
        for (const auto& colname : hashIdxCols) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx >= tbl.len) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            HashIndex* hidx = getHashIndex(dbname, tablename, colname);
            if (!hidx || !hidx->isOpen()) {
                return indexMaintenanceFailure();
            }
            auto itOld = oldIdxVals.find(colname);
            std::string oldVal = (itOld != oldIdxVals.end()) ? itOld->second : "";
            std::string newVal = canonicalKeyValueFromRowMap(
                rowValues, tbl, colname);
            // Generated columns and BEFORE triggers can change an indexed
            // value even when that column was absent from the user's SET
            // list. The logical OLD/NEW images are the source of truth.
            const bool oldIncluded = hashKeyIncluded(tbl.cols[colIdx], oldVal,
                colIdx < oldNullColumns.size() && oldNullColumns[colIdx]);
            const bool newIncluded = hashKeyIncluded(tbl.cols[colIdx], newVal,
                newColumnIsNull(colIdx));
            const bool oldMapped = oldIncluded &&
                containsIndexRid(hidx->search(oldVal), rid);
            if (oldVal != newVal || oldIncluded != newIncluded) {
                if (oldIncluded && (oldMapped || !oldVal.empty()) &&
                    (!oldMapped || !hidx->remove(oldVal, rid))) {
                    return indexMaintenanceFailure();
                }
                if (newIncluded &&
                    (containsIndexRid(hidx->search(newVal), actualRid) ||
                     !hidx->insert(newVal, actualRid))) {
                    return indexMaintenanceFailure();
                }
            } else if (actualRid != rid && newIncluded) {
                if (((oldMapped || !oldVal.empty()) &&
                     (!oldMapped || !hidx->remove(newVal, rid))) ||
                    containsIndexRid(hidx->search(newVal), actualRid) ||
                    !hidx->insert(newVal, actualRid)) {
                    return indexMaintenanceFailure();
                }
            }
        }

        // Update bloom indexes (same old/new swap semantics).
        auto bloomIdxCols = getBloomIndexedColumns(dbname, tablename);
        for (const auto& colname : bloomIdxCols) {
            size_t colIdx = tbl.len;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
            }
            if (colIdx >= tbl.len) {
                lockManager_.unlock(tablename);
                return DBStatus::CORRUPTED_DATA;
            }
            BloomIndex* bidx = getBloomIndex(dbname, tablename, colname);
            if (!bidx || !bidx->isOpen()) {
                return indexMaintenanceFailure();
            }
            auto itOld = oldIdxVals.find(colname);
            std::string oldVal = (itOld != oldIdxVals.end()) ? itOld->second : "";
            std::string newVal = canonicalKeyValueFromRowMap(
                rowValues, tbl, colname);
            if (oldVal != newVal) {
                if (!oldVal.empty() &&
                    (!containsIndexRid(bidx->search(oldVal), rid) ||
                     !bidx->remove(oldVal, rid))) {
                    return indexMaintenanceFailure();
                }
                if (!newVal.empty() &&
                    (containsIndexRid(bidx->search(newVal), actualRid) ||
                     !bidx->insert(newVal, actualRid))) {
                    return indexMaintenanceFailure();
                }
            } else if (actualRid != rid && !newVal.empty()) {
                if (!containsIndexRid(bidx->search(newVal), rid) ||
                    !bidx->remove(newVal, rid) ||
                    containsIndexRid(bidx->search(newVal), actualRid) ||
                    !bidx->insert(newVal, actualRid)) {
                    return indexMaintenanceFailure();
                }
            }
        }

        // Logical decoding: buffer the update (old/new images) for
        // streaming at commit.
        if (captureLogicalUpdate) {
            auto& txn = transactionContext();
            if (txn.inTransaction) {
                std::vector<LogicalDecoder::Cell> oldCells, newCells;
                oldCells.reserve(tbl.len); newCells.reserve(tbl.len);
                for (size_t i = 0; i < tbl.len; ++i) {
                    bool oldIsNull = false, newIsNull = false;
                    std::string oldValue;
                    {
                        BufferedNullRowBinding binding(tbl, oldNullColumns);
                        oldValue = extractColumnValue(
                            resolvedOldRow, tbl, i, dbname, true, &oldIsNull);
                    }
                    const auto newValue = withNewRowNulls([&] {
                        return extractColumnValue(
                            strippedNewRow, tbl, i, dbname, true, &newIsNull);
                    });
                    oldCells.emplace_back(tbl.cols[i].dataType,
                        oldIsNull ? std::nullopt : std::optional<std::string>(oldValue));
                    newCells.emplace_back(tbl.cols[i].dataType,
                        newIsNull ? std::nullopt : std::optional<std::string>(newValue));
                }
                txn.txnLogicalChanges.push_back(
                    {tablename, 1, LogicalDecoder::encodeRow(oldCells),
                        LogicalDecoder::encodeRow(newCells)});
            }
        }

        // Capture the row at the storage mutation boundary.  This is the
        // value PostgreSQL exposes through UPDATE ... RETURNING: after the
        // row has been rebuilt and generated columns/BEFORE triggers applied,
        // without a second predicate query that could select a different row.
        if (updatedRows || rowImages || owningRows || (mutationCallbacks && mutationCallbacks->observed)) {
            SqlRow oldValues;
            SqlRow newValues;
            for (size_t i = 0; i < tbl.len; ++i) {
                if ((tbl.cols[i].generatedKind=='v' && oldVirtualNulls[i]) ||
                    (tbl.cols[i].generatedKind!='v' && i<oldNullColumns.size() && oldNullColumns[i])) {
                    oldValues[tbl.cols[i].dataName] = std::nullopt;
                } else {
                    oldValues[tbl.cols[i].dataName] =
                        valueFromRowMap(oldLogicalValues,
                                        tbl.cols[i].dataName);
                }
                if (newColumnIsNull(i)) {
                    newValues[tbl.cols[i].dataName] = std::nullopt;
                } else {
                    std::optional<ExprValue> value;
                    bool computedNull=false;
                    auto text=withNewRowNulls([&] {
                        return extractColumnValue(strippedNewRow,tbl,i,dbname,true,&computedNull,
                            owningRows && tbl.cols[i].generatedKind=='v'?&value:nullptr);
                    });
                    newValues[tbl.cols[i].dataName]=computedNull?SqlCell{}:SqlCell{std::move(text)};
                    retainGeneratedValue(owning,false,tbl.cols[i].dataName,value);
                }
            }
            if (updatedRows) updatedRows->push_back(newValues);
            if (mutationCallbacks && mutationCallbacks->observed)
                mutationCallbacks->observed(rid, oldValues, newValues);
            if (rowImages) {
                rowImages->push_back(
                    {std::move(oldValues), std::move(newValues)});
            }
            if (owningRows) owningRows->push_back(std::move(owning));
        }
    }

    if (!maintainSpecializedIndexesAfterMutation(dbname, tablename)) {
        lockManager_.unlock(tablename);
        if (transactionContext().inTransaction &&
            transactionContext().txnDB == dbname) {
            const DBStatus rollbackStatus = rollbackTransaction();
            return rollbackStatus == DBStatus::OK
                ? DBStatus::IO_ERROR : rollbackStatus;
        }
        return DBStatus::IO_ERROR;
    }
    lockManager_.unlock(tablename);

    // Fire AFTER UPDATE triggers
    if (triggerExecutor_) {
        auto triggers = filterTriggers(
            operationTriggers, tablename, "after", "update");
        for (const auto& trg : triggers) {
            if (trg.forEachRow) {
                for (int64_t rid : matchIds) {
                    std::string oldRow, newRow;
                    auto newRid = newVersionRids.find(rid);
                    const int64_t triggerRid =
                        newRid == newVersionRids.end() ? rid : newRid->second;
                    if (!readRowByRid(pa, triggerRid, newRow, tbl)) {
                        return DBStatus::IO_ERROR;
                    }
                    std::map<std::string, std::string> newValues;
                    NullRowBinding nullBinding(
                        this, dbname, tbl.tablename, triggerRid, tbl.len);
                    for (size_t i = 0; i < tbl.len; ++i) {
                        newValues[tbl.cols[i].dataName] =
                            extractColumnValue(newRow, tbl, i, dbname, true);
                    }
                    const std::map<std::string, std::string>* oldImage = nullptr;
                    auto oit = oldImages.find(rid);
                    if (oit != oldImages.end()) oldImage = &oit->second;
                    // Evaluate WHEN condition if present
                    if (!trg.whenCondition.empty() && whenEvaluator_) {
                        std::string cond = trg.whenCondition;
                        for (const auto& [col, val] : newValues) {
                            std::string placeholder = "NEW." + col;
                            size_t pos = 0;
                            while ((pos = cond.find(placeholder, pos)) != std::string::npos) {
                                cond.replace(pos, placeholder.size(), val);
                                pos += val.size();
                            }
                        }
                        if (!whenEvaluator_(cond, newValues, {})) continue;
                    }
                    std::string action = trg.action;
                    for (const auto& [col, val] : newValues) {
                        std::string placeholder = "NEW." + col;
                        size_t pos = 0;
                        while ((pos = action.find(placeholder, pos)) != std::string::npos) {
                            action.replace(pos, placeholder.size(), val);
                            pos += val.size();
                        }
                    }
                    // Trigger diagnostic variables
                    {
                        auto replaceVar = [&](const std::string& var, const std::string& val) {
                            size_t pos = 0;
                            while ((pos = action.find(var, pos)) != std::string::npos) {
                                action.replace(pos, var.size(), val);
                                pos += val.size();
                            }
                        };
                        replaceVar("tg_name", trg.name);
                        replaceVar("tg_when", trg.timing);
                        replaceVar("tg_level", trg.forEachRow ? "ROW" : "STATEMENT");
                        replaceVar("tg_op", "UPDATE");
                        replaceVar("tg_relname", trg.tableName);
                    }
                    stageExecFunctionCtx(*this, trg.name, trg.timing,
                                      "UPDATE", trg.tableName,
                                      trg.forEachRow, &newValues, oldImage, &tbl);
                    if (triggerExecutor_(action)) {
                        return DBStatus::IO_ERROR;
                    }
                }
            } else {
                // Statement-level trigger: execute once
                if (!trg.whenCondition.empty() && whenEvaluator_) {
                    if (!whenEvaluator_(trg.whenCondition, {}, {})) continue;
                }
                std::string action = trg.action;
                {
                    auto replaceVar = [&](const std::string& var, const std::string& val) {
                        size_t pos = 0;
                        while ((pos = action.find(var, pos)) != std::string::npos) {
                            action.replace(pos, var.size(), val);
                            pos += val.size();
                        }
                    };
                    replaceVar("tg_name", trg.name);
                    replaceVar("tg_when", trg.timing);
                    replaceVar("tg_level", trg.forEachRow ? "ROW" : "STATEMENT");
                    replaceVar("tg_op", "UPDATE");
                    replaceVar("tg_relname", trg.tableName);
                }
                stageExecFunctionCtx(*this, trg.name, trg.timing,
                                  "UPDATE", trg.tableName,
                                  trg.forEachRow, nullptr, nullptr);
                if (triggerExecutor_(action)) {
                    return DBStatus::IO_ERROR;
                }
            }
        }
    }

    recordModification(dbname, tablename, matchIds.size());
    dbms::recordTableMutation(dbname, tablename, dbms::TableMutation::Update,
                              matchIds.size());
    maybeAutoAnalyze(dbname, tablename);
    if (affectedRows) *affectedRows = matchIds.size();
    return DBStatus::OK;
}

// ========================================================================
// information_schema virtual tables
// ========================================================================
std::vector<std::string> StorageEngine::queryInformationSchema(
    const std::string& tablename,
    const std::vector<std::string>& conditions,
    const std::set<std::string>& /*selectCols*/,
    const std::vector<OrderBySpec>& /*orderBy*/) const {

    std::vector<std::string> result;
    auto conds = parseConditions(conditions);

    if (tablename == "tables" || tablename == "TABLES") {
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& tname : getTableNames(dbname)) {
                std::string row = dbname + " " + tname + " BASE_TABLE ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                    if (c.colName == "table_name" && c.op == "=" && tname != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
            for (const auto& vname : getViewNames(dbname)) {
                std::string row = dbname + " " + vname + " VIEW ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                    if (c.colName == "table_name" && c.op == "=" && vname != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
        }
    } else if (tablename == "columns" || tablename == "COLUMNS") {
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& tname : getTableNames(dbname)) {
                TableSchema tbl = getTableSchema(dbname, tname);
                for (size_t i = 0; i < tbl.len; ++i) {
                    const Column& col = tbl.cols[i];
                    std::string nullable = col.isNull ? "YES" : "NO";
                    std::string row = dbname + " " + tname + " " + col.dataName + " " + col.dataType + " " + nullable + " ";
                    bool match = true;
                    for (const auto& c : conds) {
                        if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                        if (c.colName == "table_name" && c.op == "=" && tname != c.value) { match = false; break; }
                        if (c.colName == "column_name" && c.op == "=" && col.dataName != c.value) { match = false; break; }
                    }
                    if (match) result.push_back(row);
                }
            }
        }
    } else if (tablename == "views" || tablename == "VIEWS") {
        // information_schema.views: one row per view across databases.
        // Column layout mirrors the tables branch (catalog schema name ...)
        // so count(*) and table_schema/table_name equality filters work.
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& vname : getViewNames(dbname)) {
                std::string row = dbname + " " + vname + " VIEW ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; }
                    if (c.colName == "table_name" && c.op == "=" && vname != c.value) { match = false; }
                }
                if (match) result.push_back(row);
            }
        }
    } else if (tablename == "statistics" || tablename == "STATISTICS") {
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& tname : getTableNames(dbname)) {
                TableSchema tbl = getTableSchema(dbname, tname);
                // Single-column indexes
                auto idxCols = getIndexedColumns(dbname, tname);
                for (const auto& cname : idxCols) {
                    std::string row = dbname + " " + tname + " " + cname + "_idx " + cname + " ";
                    bool match = true;
                    for (const auto& c : conds) {
                        if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                        if (c.colName == "table_name" && c.op == "=" && tname != c.value) { match = false; break; }
                    }
                    if (match) result.push_back(row);
                }
                // Composite indexes
                auto compIdxs = getCompositeIndexes(dbname, tname);
                for (const auto& ci : compIdxs) {
                    for (size_t seq = 0; seq < ci.columns.size(); ++seq) {
                        std::string row = dbname + " " + tname + " " + ci.name + " " + ci.columns[seq] + " " + std::to_string(seq + 1) + " ";
                        bool match = true;
                        for (const auto& c : conds) {
                            if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                            if (c.colName == "table_name" && c.op == "=" && tname != c.value) { match = false; break; }
                        }
                        if (match) result.push_back(row);
                    }
                }
            }
        }
    } else if (tablename == "routines" || tablename == "ROUTINES") {
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& pname : getProcedureNames(dbname)) {
                std::string row = dbname + " " + pname + " PROCEDURE ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "routine_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                    if (c.colName == "routine_name" && c.op == "=" && pname != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
            for (const auto& fname : getUDFNames(dbname)) {
                std::string row = dbname + " " + fname + " FUNCTION ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "routine_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                    if (c.colName == "routine_name" && c.op == "=" && fname != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
            for (const auto& tname : getTVFNames(dbname)) {
                std::string row = dbname + " " + tname + " FUNCTION ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "routine_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                    if (c.colName == "routine_name" && c.op == "=" && tname != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
            for (const auto& trg : getAllTriggers(dbname)) {
                std::string row = dbname + " " + trg.name + " TRIGGER ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "routine_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                    if (c.colName == "routine_name" && c.op == "=" && trg.name != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
        }
    } else if (tablename == "views" || tablename == "VIEWS") {
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& vname : getViewNames(dbname)) {
                std::string row = dbname + " " + vname + " ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                    if (c.colName == "table_name" && c.op == "=" && vname != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
        }
    } else if (tablename == "triggers" || tablename == "TRIGGERS") {
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& trg : getAllTriggers(dbname)) {
                std::string row = dbname + " " + trg.name + " " + trg.event + " " + trg.tableName + " " + trg.timing + " ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "trigger_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                    if (c.colName == "trigger_name" && c.op == "=" && trg.name != c.value) { match = false; break; }
                    if (c.colName == "event_object_table" && c.op == "=" && trg.tableName != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
        }
    } else if (tablename == "key_column_usage" || tablename == "KEY_COLUMN_USAGE") {
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& tname : getTableNames(dbname)) {
                TableSchema tbl = getTableSchema(dbname, tname);
                // Primary key columns
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (!tbl.cols[i].isPrimaryKey) continue;
                    std::string row = dbname + " " + tname + " " + tbl.cols[i].dataName + " PRIMARY ";
                    bool match = true;
                    for (const auto& c : conds) {
                        if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                        if (c.colName == "table_name" && c.op == "=" && tname != c.value) { match = false; break; }
                        if (c.colName == "column_name" && c.op == "=" && tbl.cols[i].dataName != c.value) { match = false; break; }
                    }
                    if (match) result.push_back(row);
                }
                // Foreign key columns
                for (size_t i = 0; i < tbl.fkLen; ++i) {
                    for (const auto& colName : tbl.fks[i].colNames) {
                        std::string row = dbname + " " + tname + " " + colName + " FOREIGN ";
                        bool match = true;
                        for (const auto& c : conds) {
                            if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                            if (c.colName == "table_name" && c.op == "=" && tname != c.value) { match = false; break; }
                            if (c.colName == "column_name" && c.op == "=" && colName != c.value) { match = false; break; }
                        }
                        if (match) result.push_back(row);
                    }
                }
                // Unique columns
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (!tbl.cols[i].isUnique || tbl.cols[i].isPrimaryKey) continue;
                    std::string row = dbname + " " + tname + " " + tbl.cols[i].dataName + " UNIQUE ";
                    bool match = true;
                    for (const auto& c : conds) {
                        if (c.colName == "table_schema" && c.op == "=" && dbname != c.value) { match = false; break; }
                        if (c.colName == "table_name" && c.op == "=" && tname != c.value) { match = false; break; }
                        if (c.colName == "column_name" && c.op == "=" && tbl.cols[i].dataName != c.value) { match = false; break; }
                    }
                    if (match) result.push_back(row);
                }
            }
        }
    }
    return result;
}


// ---------------------------------------------------------------------------
// pg_stats / pg_statistic rows: one per (database, table, column) with
// schemaname tablename attname null_frac n_distinct most_common_vals
// most_common_freqs histogram_bounds.  null_frac stays 0 until per-column
// null counts are tracked; n_distinct follows PG conventions (negative =
// fraction of rows, -1 = fully unique).
// ---------------------------------------------------------------------------
std::vector<std::string> StorageEngine::getPgStatsRows(
    const std::string& onlyDb,
    const std::string& onlyTable,
    const std::string& onlyColumn) const {
    std::vector<std::string> result;
    for (const auto& dbname : getDatabaseNames()) {
        if (!onlyDb.empty() && dbname != onlyDb) continue;
        auto spath = statsPath(dbname);
        if (!std::filesystem::exists(spath)) continue;
        std::ifstream ifs(spath);
        std::string line;
        std::string currentTable;
        size_t rowCount = 0;
        std::map<std::string, StorageEngine::ColumnStats> cols;
        auto emit = [&]() {
            if (currentTable.empty()) return;
            if (!onlyTable.empty() && currentTable != onlyTable) return;
            for (const auto& cv : cols) {
                if (!onlyColumn.empty() && cv.first != onlyColumn) continue;
                double nDist = 0.0;
                if (rowCount > 0) {
                    if (cv.second.cardinality == rowCount) {
                        nDist = -1.0;
                    } else {
                        nDist = -static_cast<double>(cv.second.cardinality) /
                                static_cast<double>(rowCount);
                    }
                }
                std::ostringstream mcv, freqs, hist;
                for (size_t i = 0; i < cv.second.mcv.size(); ++i) {
                    if (i > 0) { mcv << ","; freqs << ","; }
                    mcv << "{" << cv.second.mcv[i].first << "}";
                    freqs << "{"
                          << (rowCount > 0
                                  ? static_cast<double>(cv.second.mcv[i].second) /
                                        static_cast<double>(rowCount)
                                  : 0.0)
                          << "}";
                }
                for (size_t i = 0; i < cv.second.histogram.size(); ++i) {
                    if (i > 0) hist << ",";
                    hist << "{" << cv.second.histogram[i].first << "}";
                }
                if (!cv.second.histogram.empty()) {
                    // N bucket intervals have N+1 boundaries. Include the
                    // final upper bound so the catalog spans the full range.
                    hist << ",{" << cv.second.histogram.back().second << "}";
                }
                const double nullFraction = rowCount > 0
                    ? static_cast<double>(cv.second.nullCount) / static_cast<double>(rowCount)
                    : 0.0;
                result.push_back(dbname + " " + currentTable + " " + cv.first +
                                 " " + std::to_string(nullFraction) + " " +
                                 std::to_string(nDist) + " " + mcv.str() + " " +
                                 freqs.str() + " " + hist.str() + " ");
            }
        };
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string tname, cname;
            ss >> tname >> cname;
            if (cname == "__rows__") {
                // A new table section starts: flush the previous one.
                emit();
                std::string rc;
                std::getline(ss, rc);
                try { rowCount = std::stoull(rc); } catch (...) { rowCount = 0; }
                currentTable = tname;
                cols.clear();
                continue;
            }
            if (cname == "__multi__") continue;
            if (tname != currentTable) {
                emit();
                currentTable = tname;
                cols.clear();
            }
            cols[cname] = parseStatsLine(line);
        }
        emit();
    }
    return result;
}

std::vector<std::string> StorageEngine::queryPgCatalog(
    const std::string& tablename,
    const std::vector<std::string>& conditions,
    const std::set<std::string>& /*selectCols*/,
    const std::vector<OrderBySpec>& /*orderBy*/) const {

    std::vector<std::string> result;
    auto conds = parseConditions(conditions);

    if (tablename == "pg_class" || tablename == "PG_CLASS") {
        // PostgreSQL pg_class: relname relkind relnamespace relpages reltuples
        for (const auto& dbname : getDatabaseNames()) {
            // Tables
            for (const auto& tname : getTableNames(dbname)) {
                std::string row = tname + " r " + dbname + " 0 0 ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "relname" && c.op == "=" && tname != c.value) { match = false; break; }
                    if (c.colName == "relnamespace" && c.op == "=" && dbname != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
            // Views
            for (const auto& vname : getViewNames(dbname)) {
                std::string row = vname + " v " + dbname + " 0 0 ";
                bool match = true;
                for (const auto& c : conds) {
                    if (c.colName == "relname" && c.op == "=" && vname != c.value) { match = false; break; }
                    if (c.colName == "relnamespace" && c.op == "=" && dbname != c.value) { match = false; break; }
                }
                if (match) result.push_back(row);
            }
        }
    } else if (tablename == "pg_attribute" || tablename == "PG_ATTRIBUTE") {
        // PostgreSQL pg_attribute: attrelid attname atttypid attnum attnotnull attlen
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& tname : getTableNames(dbname)) {
                TableSchema tbl = getTableSchema(dbname, tname);
                for (size_t i = 0; i < tbl.len; ++i) {
                    const Column& col = tbl.cols[i];
                    std::string notnull = col.isNull ? "f" : "t";
                    int attlen = col.isVariableLength ? -1 : col.dsize;
                    std::string row = tname + " " + col.dataName + " " + col.dataType + " " +
                                      std::to_string(i + 1) + " " + notnull + " " + std::to_string(attlen) + " ";
                    bool match = true;
                    for (const auto& c : conds) {
                        if (c.colName == "attrelid" && c.op == "=" && tname != c.value) { match = false; break; }
                        if (c.colName == "attname" && c.op == "=" && col.dataName != c.value) { match = false; break; }
                    }
                    if (match) result.push_back(row);
                }
            }
        }
    } else if (tablename == "pg_type" || tablename == "PG_TYPE") {
        // PostgreSQL pg_type: typname typlen typtype
        static const std::vector<std::pair<std::string, int>> pgTypes = {
            {"int", 4}, {"bigint", 8}, {"smallint", 2}, {"varchar", -1}, {"char", 1},
            {"text", -1}, {"boolean", 1}, {"real", 4}, {"double precision", 8},
            {"date", 4}, {"timestamp", 8}, {"timestamptz", 8}, {"json", -1}, {"jsonb", -1},
            {"uuid", 16}, {"decimal", -1}, {"blob", -1}, {"binary", -1},
            {"serial", 4}, {"time", 8}, {"datetime", 8}, {"float", 4},
        };
        for (const auto& pt : pgTypes) {
            std::string row = pt.first + " " + std::to_string(pt.second) + " b ";
            bool match = true;
            for (const auto& c : conds) {
                if (c.colName == "typname" && c.op == "=" && pt.first != c.value) { match = false; break; }
            }
            if (match) result.push_back(row);
        }
    } else if (tablename == "pg_stats" || tablename == "PG_STATS" ||
               tablename == "pg_statistic" || tablename == "PG_STATISTIC") {
        // schemaname tablename attname null_frac n_distinct
        // most_common_vals most_common_freqs histogram_bounds
        std::string fDb, fTable, fCol;
        for (const auto& c : conds) {
            if (c.op != "=") continue;
            if (c.colName == "schemaname") fDb = c.value;
            if (c.colName == "tablename") fTable = c.value;
            if (c.colName == "attname") fCol = c.value;
        }
        result = getPgStatsRows(fDb, fTable, fCol);
    } else if (tablename == "pg_index" || tablename == "PG_INDEX") {
        // PostgreSQL pg_index: indrelid indkey indisunique indisprimary
        for (const auto& dbname : getDatabaseNames()) {
            for (const auto& tname : getTableNames(dbname)) {
                TableSchema tbl = getTableSchema(dbname, tname);
                // Single-column indexes
                auto idxCols = getIndexedColumns(dbname, tname);
                const auto indexMetadata =
                    getIndexMetadata(dbname, tname);
                for (const auto& cname : idxCols) {
                    std::string isUnique = "f";
                    std::string isPrimary = "f";
                    for (size_t i = 0; i < tbl.len; ++i) {
                        if (tbl.cols[i].dataName == cname) {
                            if (tbl.cols[i].isUnique) isUnique = "t";
                            if (tbl.cols[i].isPrimaryKey) isPrimary = "t";
                        }
                    }
                    for (const auto& metadata : indexMetadata) {
                        if (!metadata.isExpression &&
                            metadata.name == cname && metadata.isUnique) {
                            isUnique = "t";
                            break;
                        }
                    }
                    std::string row = tname + " " + cname + " " + isUnique + " " + isPrimary + " ";
                    bool match = true;
                    for (const auto& c : conds) {
                        if (c.colName == "indrelid" && c.op == "=" && tname != c.value) { match = false; break; }
                    }
                    if (match) result.push_back(row);
                }
                for (const auto& metadata :
                     getCompositeIndexes(dbname, tname)) {
                    std::string key;
                    for (size_t columnIndex = 0;
                         columnIndex < metadata.columns.size();
                         ++columnIndex) {
                        if (columnIndex != 0) key += ',';
                        key += metadata.columns[columnIndex];
                    }
                    std::string row = tname + " " + key + " " +
                        (metadata.isUnique ? "t" : "f") + " f ";
                    bool match = true;
                    for (const auto& c : conds) {
                        if (c.colName == "indrelid" && c.op == "=" &&
                            tname != c.value) {
                            match = false;
                            break;
                        }
                    }
                    if (match) result.push_back(row);
                }
            }
        }
    } else if (tablename == "pg_namespace" || tablename == "PG_NAMESPACE") {
        // This old text API has no database owner. Database directory names
        // are not schema rows; require the actual database-bound source.
        throw DbError("0A000", "pg_namespace requires a database-bound catalog query");
    }
    return result;
}

static std::string leftSortTextValue(const std::string& value,
                                     int64_t count) {
    std::vector<size_t> boundaries{0};
    for (size_t offset = 0; offset < value.size();) {
        ++offset;
        while (offset < value.size() &&
               (static_cast<unsigned char>(value[offset]) & 0xc0) == 0x80)
            ++offset;
        boundaries.push_back(offset);
    }
    const size_t characters = boundaries.size() - 1;
    const uint64_t magnitude = count < 0
        ? uint64_t{0} - static_cast<uint64_t>(count)
        : static_cast<uint64_t>(count);
    const size_t take = count < 0
        ? (magnitude >= characters ? 0
                                   : characters - static_cast<size_t>(magnitude))
        : (magnitude >= characters ? characters
                                   : static_cast<size_t>(magnitude));
    return value.substr(0, boundaries[take]);
}

static std::string rightSortTextValue(const std::string& value,
                                      int64_t count) {
    std::vector<size_t> boundaries{0};
    for (size_t offset = 0; offset < value.size();) {
        ++offset;
        while (offset < value.size() &&
               (static_cast<unsigned char>(value[offset]) & 0xc0) == 0x80)
            ++offset;
        boundaries.push_back(offset);
    }
    const size_t characters = boundaries.size() - 1;
    const uint64_t magnitude = count < 0
        ? uint64_t{0} - static_cast<uint64_t>(count)
        : static_cast<uint64_t>(count);
    const size_t skip = count < 0
        ? (magnitude >= characters ? characters
                                   : static_cast<size_t>(magnitude))
        : (magnitude >= characters ? 0
                                   : characters - static_cast<size_t>(magnitude));
    return value.substr(boundaries[skip]);
}

static std::string reverseSortTextValue(const std::string& value) {
    std::vector<size_t> boundaries{0};
    for (size_t offset = 0; offset < value.size();) {
        ++offset;
        while (offset < value.size() &&
               (static_cast<unsigned char>(value[offset]) & 0xc0) == 0x80)
            ++offset;
        boundaries.push_back(offset);
    }
    std::string reversed;
    reversed.reserve(value.size());
    for (size_t i = boundaries.size() - 1; i > 0; --i)
        reversed.append(value, boundaries[i - 1],
                        boundaries[i] - boundaries[i - 1]);
    return reversed;
}

static bool parseTextSortCount(const std::string& text, int64_t& count) {
    const char* begin = text.data();
    if (begin != text.data() + text.size() && *begin == '+') ++begin;
    if (begin == text.data() + text.size()) return false;
    const auto parsed = std::from_chars(
        begin, text.data() + text.size(), count);
    return parsed.ec == std::errc{} &&
           parsed.ptr == text.data() + text.size() &&
           count >= std::numeric_limits<int32_t>::min() &&
           count <= std::numeric_limits<int32_t>::max();
}

static bool isEvaluatedNumericSort(
    const StorageEngine::OrderBySpec& spec) {
    static const std::set<std::string> functions = {
        "abs", "round", "power", "floor", "ceil", "trunc", "sign",
        "mod", "gcd", "lcm", "div", "sqrt", "ln", "log", "exp",
        "sin", "cos", "tan", "width_bucket", "to_number", "extract", "date_part"
    };
    return !spec.expressionSql.empty() &&
           functions.count(spec.exprFunc) != 0;
}

static bool isEvaluatedPolymorphicSort(
    const StorageEngine::OrderBySpec& spec) {
    static const std::set<std::string> functions = {
        "least", "greatest", "coalesce", "nullif"
    };
    return !spec.expressionSql.empty() &&
           functions.count(spec.exprFunc) != 0;
}

static void setPolymorphicSortType(Column& column,
                                   const std::string& resultType) {
    if (resultType == "smallint" || resultType == "integer" ||
        resultType == "bigint") {
        column.dataType = "int";
        column.isVariableLength = false;
    } else if (resultType == "real") {
        column.dataType = "float";
        column.isVariableLength = false;
    } else if (resultType == "double precision") {
        column.dataType = "double";
        column.isVariableLength = false;
    } else if (resultType == "numeric") {
        column.dataType = "numeric";
        column.isVariableLength = true;
    } else if (resultType == "date" || resultType == "timestamp" ||
               resultType == "timestamptz") {
        column.dataType = resultType;
        column.isVariableLength = false;
    }
}

std::vector<std::string> StorageEngine::query(const std::string& dbname,
                                               const std::string& tablename,
                                               const std::vector<std::string>& conditions,
                                               const std::set<std::string>& selectCols,
                                               const std::vector<OrderBySpec>& orderBy,
                                               bool forUpdate,
                                               bool noWait,
                                               bool skipLocked,
                                               int timezoneOffsetMinutes,
                                               const std::vector<std::string>& distinctOnCols) {
    std::vector<std::string> apiConditions;
    apiConditions.reserve(conditions.size());
    for (const auto& condition : conditions)
        apiConditions.push_back(condition.rfind("apicond ", 0) == 0
            ? condition : "apicond " + condition);
    return query(dbname, tablename, apiConditions, selectCols, orderBy,
                 forUpdate, noWait, skipLocked, timezoneOffsetMinutes,
                 distinctOnCols, nullptr, nullptr, nullptr);
}

std::vector<std::string> StorageEngine::query(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    const std::set<std::string>& selectCols,
    const std::vector<OrderBySpec>& orderBy,
    bool forUpdate, bool noWait, bool skipLocked,
    int timezoneOffsetMinutes,
    const std::vector<std::string>& distinctOnCols,
    std::vector<std::vector<std::string>>* structuredRows,
    std::vector<std::vector<bool>>* structuredNulls,
    std::vector<int64_t>* structuredRowIds) {
    noteTemporaryRelationAccess(dbname, tablename);
    std::vector<std::string> result;
    if (structuredRows) structuredRows->clear();
    if (structuredNulls) structuredNulls->clear();
    if (structuredRowIds) structuredRowIds->clear();

    if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
        if ((transactionContext().txnIsolationLevel == IsolationLevel::READ_COMMITTED ||
             transactionContext().txnIsolationLevel == IsolationLevel::READ_UNCOMMITTED) &&
            !transactionContext().readView.commandIdVisibility) {
            refreshReadView();
        } else {
            ensureTransactionSnapshot();
        }
        transactionContext().hasRead = true;
        transactionContext().querySnapshotUsed = true;
    }

    // information_schema virtual tables
    if (dbname == "information_schema") {
        return queryInformationSchema(tablename, conditions, selectCols, orderBy);
    }

    // pg_catalog virtual tables
    if (dbname == "pg_catalog") {
        return queryPgCatalog(tablename, conditions, selectCols, orderBy);
    }

    const bool existedBeforeLock = tableExists(dbname, tablename);
    if (!existedBeforeLock) {
        // Unqualified pg_catalog names (FROM pg_views) resolve through the
        // same virtual catalog path as qualified pg_catalog.pg_views.
        if (tablename.size() > 3 && tablename.substr(0, 3) == "pg_") {
            auto rows = queryPgCatalog(tablename, conditions, selectCols, orderBy);
            if (!rows.empty()) return rows;
        }
        if (dbname.empty() || !validStoredIdentifier(dbname, MAX_TABLE_NAME_LEN) ||
            tablename.empty() || !validStoredRelationName(tablename)) {
            return result;
        }
    }
    if (transactionContext().inTransaction) {
        if (forUpdate) {
            if (!lockManager_.lockIntentExclusive(tablename)) {
                throw DbError("55P03", "could not obtain lock on relation \"" +
                    tablename + "\"");
            }
        } else {
            if (!lockManager_.lockIntentShared(tablename)) {
                throw DbError("55P03", "could not obtain lock on relation \"" +
                    tablename + "\"");
            }
        }
    } else {
        if (!lockManager_.lockShared(tablename)) {
            throw DbError("55P03", "could not obtain lock on relation \"" +
                tablename + "\"");
        }
    }
    ResourceUnlockGuard tableLockGuard(lockManager_, tablename);
    if (!tableExists(dbname, tablename)) {
        return result;
    }

    TableSchema tbl = getTableSchema(dbname, tablename);
    PageAllocator* pa = getPageAllocator(dbname, tablename);

    ReadView autocommitView;
    ReadView commandInternalView;
    std::map<std::string, std::string> sortExpressionIdentities;
    // Preparation covers all keys before qualification or volatile calls,
    // including zero-row inputs. Never invoke a routine just to bind it.
    try {
        ExprEvaluator evaluator;
        evaluator.setCurrentDB(dbname);
        for (const auto& order : orderBy) {
            if (order.expressionSql.empty()) continue;
            SQLParser parser;
            auto parsed = parser.parse("SELECT " + order.expressionSql);
            auto* select = parsed.success ? dynamic_cast<SelectStmt*>(parsed.stmt.get()) : nullptr;
            if (!select || select->selectList.size() != 1)
                throw DbError("42601", "invalid ORDER BY expression");
            evaluator.bindScalarFunctions(select->selectList.front().expr.get(), this);
            if (!order.expressionIdentity.empty()) {
                sortExpressionIdentities[order.expressionSql] = order.expressionIdentity;
            } else if (order.exprFunc == "expreval") {
                sortExpressionIdentities[order.expressionSql] = ExprHelper::scalarExpressionIdentity(
                    order.expressionSql, [&](const ColumnRefExpr& column) {
                        if ((!column.schema.empty() && column.schema != "public") ||
                            (!column.table.empty() && column.table != tablename))
                            throw DbError("42P01", "missing FROM-clause entry: " + column.table);
                        for (size_t i = 0; i < tbl.len; ++i) {
                            if (column.column != tbl.cols[i].dataName) continue;
                            const auto field = [](const std::string& value) {
                                return std::to_string(value.size()) + ":" + value;
                            };
                            return "source0" + field(dbname) + field(tablename) +
                                field(std::to_string(i)) + field(tbl.cols[i].dataType) +
                                field(std::to_string(tbl.cols[i].dsize)) + field(tbl.cols[i].collation);
                        }
                        throw DbError("42703", "column does not exist: " + column.column);
                    }, dbname, this);
            } else sortExpressionIdentities[order.expressionSql] = order.expressionSql;
        }
    } catch (...) {
        throw;
    }
    const ReadView* queryView = nullptr;
    if (transactionContext().inTransaction &&
        transactionContext().txnDB == dbname) {
        queryView = &transactionContext().readView;
    } else {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        autocommitView.creatorTxnId = 0;
        autocommitView.lowLimitId = TxnIdGenerator::instance().maxCommittedTxId() + 1;
        autocommitView.upLimitId = activeTransactions().empty()
            ? autocommitView.lowLimitId : *activeTransactions().begin();
        autocommitView.activeTxnIds = activeTransactions();
        autocommitView.subTxnIds.clear();
        autocommitView.commitLog = getCommitLog(dbname);
        queryView = &autocommitView;
    }
    // The final RID fetch must use the same visibility rule as the scan.
    // CTE/derived materializations belong to this SQL command and are
    // explicitly registered as internal; applying its caller's CID again
    // here would discard every just-materialized row when WHERE is present.
    // This exception never applies to a user's ordinary or TEMP relations.
    if (queryView->commandIdVisibility && transactionContext().inTransaction &&
        transactionContext().txnDB == dbname &&
        transactionContext().commandInternalRelations.count(tablename)) {
        commandInternalView = *queryView;
        commandInternalView.commandIdVisibility = false;
        queryView = &commandInternalView;
    }

    // RLS policies are expression ASTs, not legacy index-condition strings.
    // Keep user predicates separate and apply policy visibility through the
    // relation-aware scan below; converting a policy such as
    // `owner = current_user` to the old textual condition format is unsafe.
    const bool enforceRls = shouldEnforceRLS(tbl, StorageEngine::getRLSUser());
    auto conds = parseConditions(conditions);
    std::vector<std::pair<int64_t, std::string>> matchRows;
    bool usedIndex = false;
    bool scanFailed = false;
    bool indexReadFailed = false;
    if (enforceRls) {
        const auto targetParts = tbl.partitionType == TableSchema::PartitionType::None
            ? std::vector<std::string>{}
            : getTargetPartitions(tbl, conds);
        const bool scanOk = forEachVisibleRow(
            dbname, tablename, "SELECT",
            [&](uint32_t pid, uint16_t sid, const char* data, size_t len) {
                std::string row(data, len);
                for (const auto& c : conds) {
                    if (!evalConditionOnRow(c, row, tbl)) return;
                }
                matchRows.emplace_back(encodeRid(pid, sid), std::move(row));
            }, queryView, targetParts);
        if (!scanOk) scanFailed = true;
    } else if (conds.empty()) {
        if (!forEachRow(dbname, tablename, [&](uint32_t pid, uint16_t sid, const char* data, size_t len) {
            matchRows.emplace_back(encodeRid(pid, sid), std::string(data, len));
        })) scanFailed = true;
    } else if (tbl.partitionType != TableSchema::PartitionType::None) {
        // Partitioned table: use forEachRow with partition pruning + in-callback filtering
        auto targetParts = getTargetPartitions(tbl, conds);
        if (!forEachRow(dbname, tablename, [&](uint32_t pid, uint16_t sid, const char* data, size_t len) {
            std::string row(data, len);
            bool match = true;
            for (const auto& c : conds) {
                if (!evalConditionOnRow(c, row, tbl)) { match = false; break; }
            }
            if (match) matchRows.emplace_back(encodeRid(pid, sid), std::move(row));
        }, queryView, targetParts)) scanFailed = true;
    } else {
        auto ids = filterRows(dbname, tablename, conds, &usedIndex, &scanFailed,
                              &indexReadFailed);
        for (int64_t rid : ids) {
            std::string row;
            if (readVisibleRowByRid(dbname, pa, rid, row, tbl, queryView)) {
                matchRows.emplace_back(rid, std::move(row));
            }
        }
    }
    if (scanFailed) {
        if (indexReadFailed) {
            throw DbError("XX001", "B-tree index read failed for relation \"" +
                tablename + "\"");
        }
        return result;
    }

    // Resolve TOAST markers in matched rows so downstream formatting sees
    // actual values instead of __TOAST__ markers.
    for (auto& mr : matchRows) {
        bool toastOk = false;
        std::string resolved = resolveToastValues(
            dbname, tablename, mr.second, tbl, &toastOk);
        if (!toastOk) {
            return result;
        }
        mr.second = std::move(resolved);
    }

    // Row-level locks within transaction
    if (transactionContext().inTransaction) {
        std::vector<std::pair<int64_t, std::string>> lockedRows;
        for (auto& mr : matchRows) {
            bool locked;
            if (noWait || skipLocked) {
                locked = forUpdate
                    ? lockManager_.rowLockExclusiveNoWait(tablename, mr.first)
                    : lockManager_.rowLockSharedNoWait(tablename, mr.first);
            } else {
                locked = forUpdate
                    ? lockManager_.rowLockExclusive(tablename, mr.first)
                    : lockManager_.rowLockShared(tablename, mr.first);
            }
            if (!locked) {
                if (skipLocked) {
                    continue; // skip locked rows
                }
                if (!noWait && lockManager_.lastRowLockWasDeadlock()) {
                    throw DbError("40P01", "deadlock detected while locking row in relation \"" +
                        tablename + "\"");
                }
                throw DbError("55P03", "could not obtain lock on row in relation \"" +
                    tablename + "\"");
            }
            lockedRows.push_back(std::move(mr));
        }
        matchRows = std::move(lockedRows);
        // PostgreSQL FOR UPDATE locks the selected tuples, not next-key
        // gaps. SSI read dependencies are tracked separately and must not
        // become blocking gap locks, even at SERIALIZABLE isolation.
    }

    // ORDER BY (multi-column)
    if (!orderBy.empty()) {
        std::vector<size_t> sortColumnIndices(orderBy.size(), tbl.len);
        std::vector<Column> sortComparisonColumns(orderBy.size());
        for (size_t orderIndex = 0; orderIndex < orderBy.size(); ++orderIndex) {
            const auto& spec = orderBy[orderIndex];
            for (size_t columnIndex = 0; columnIndex < tbl.len;
                 ++columnIndex) {
                if (tbl.cols[columnIndex].dataName == spec.colName) {
                    sortColumnIndices[orderIndex] = columnIndex;
                    sortComparisonColumns[orderIndex] = tbl.cols[columnIndex];
                    break;
                }
            }
            if (sortColumnIndices[orderIndex] >= tbl.len ||
                spec.collation.empty()) {
                // The SQL-facing default ordering follows the en_US locale
                // used by the other SELECT sort paths.  An empty column
                // collation is a storage detail, not a request for C order.
                if (sortColumnIndices[orderIndex] < tbl.len &&
                    sortComparisonColumns[orderIndex].collation.empty()) {
                    sortComparisonColumns[orderIndex].collation = "en_US.utf8";
                }
                continue;
            }
            Column& comparisonColumn = sortComparisonColumns[orderIndex];
            comparisonColumn.collation =
                collation::normalizeName(spec.collation) == "binary"
                    ? "C" : spec.collation;
            TableSchema collationProbe;
            collationProbe.len = 1;
            collationProbe.cols[0] = comparisonColumn;
            if (resolveTableCollations(
                    *this, dbname, collationProbe) != DBStatus::OK) {
                return result;
            }
            comparisonColumn = std::move(collationProbe.cols[0]);
        }

        struct SortKey {
            size_t rowIndex;
            std::vector<
                std::tuple<std::string, int64_t, double, Date, Numeric>> vals;
            std::vector<bool> isNulls; // true if value is NULL
        };
        std::vector<SortKey> keys;
        for (size_t rowIndex = 0; rowIndex < matchRows.size(); ++rowIndex) {
            auto& mr = matchRows[rowIndex];
            SortKey k{rowIndex, {}, {}};
            NullRowBinding nbS(this, dbname, tbl.tablename, mr.first, tbl.len);
            for (size_t orderIndex = 0; orderIndex < orderBy.size();
                 ++orderIndex) {
                const size_t sortIdx = sortColumnIndices[orderIndex];
                if (sortIdx < tbl.len) {
                    bool valueIsNull = false;
                    std::string val = extractColumnValue(
                        mr.second, tbl, sortIdx, dbname, true, &valueIsNull);
                    const Column& scol = tbl.cols[sortIdx];
                    const bool resultIsNull = valueIsNull ||
                        (scol.generatedKind != 'v' && dbms::detail::storedRowColumnIsNull(*this, dbname, tbl.tablename, tbl, mr.first, sortIdx));
                    k.isNulls.push_back(resultIsNull);
                    if (scol.dataType == "numeric") {
                        k.vals.emplace_back(
                            "", 0, 0.0, Date{},
                            val.empty() ? Numeric{} : Numeric(val));
                    } else if (scol.dataType == "char" ||
                               scol.dataType == "uuid" ||
                               scol.isVariableLength) {
                        k.vals.emplace_back(val, 0, 0.0, Date{}, Numeric{});
                    } else if (scol.dataType == "date") {
                        k.vals.emplace_back(
                            "", 0, 0.0,
                            val.empty() ? Date{} : Date(val.c_str()),
                            Numeric{});
                    } else if (scol.dataType == "timestamp" ||
                               scol.dataType == "timestamptz" ||
                               scol.dataType == "datetime") {
                        k.vals.emplace_back(
                            "", val.empty() ? 0 :
                                (scol.storageCodec == Column::StorageCodec::TemporalMicros
                                    ? temporalColumnMicros(scol, val).value_or(0)
                                    : parseTimestampToSeconds(val)),
                            0.0, Date{}, Numeric{});
                    } else if (scol.dataType == "time") {
                        k.vals.emplace_back(
                            "", val.empty() ? 0 :
                                (scol.storageCodec == Column::StorageCodec::TemporalMicros
                                    ? temporalColumnMicros(scol, val).value_or(0)
                                    : parseTimeToSeconds(val)),
                            0.0, Date{}, Numeric{});
                    } else if (scol.dataType == "money") {
                        int64_t minorUnits = 0;
                        if (!val.empty())
                            (void)parseMoneyLiteral(val, minorUnits);
                        k.vals.emplace_back(
                            "", minorUnits, 0.0, Date{}, Numeric{});
                    } else if (scol.dataType == "float") {
                        float parsed = 0.0f;
                        if (!val.empty()) (void)parseFloatLiteral(val, parsed);
                        k.vals.emplace_back(
                            "", 0, static_cast<double>(parsed), Date{},
                            Numeric{});
                    } else if (scol.dataType == "double" ||
                               scol.dataType == "decimal") {
                        double parsed = 0.0;
                        if (!val.empty()) (void)parseDoubleLiteral(val, parsed);
                        k.vals.emplace_back(
                            "", 0, parsed, Date{}, Numeric{});
                    } else {
                        k.vals.emplace_back(
                            "", val.empty() ? 0 : parseInt(val), 0.0,
                            Date{}, Numeric{});
                    }
                } else {
                    k.isNulls.push_back(true);
                    k.vals.emplace_back(
                        "", 0, 0.0, Date{}, Numeric{});
                }
            }
            keys.push_back(std::move(k));
        }
        std::sort(keys.begin(), keys.end(), [&](const SortKey& a, const SortKey& b) {
            for (size_t i = 0; i < orderBy.size(); ++i) {
                const auto& spec = orderBy[i];
                const size_t sortIdx = sortColumnIndices[i];
                if (sortIdx >= tbl.len) continue;
                // NULL handling: NULLS FIRST or NULLS LAST (default)
                bool aNull = a.isNulls[i];
                bool bNull = b.isNulls[i];
                if (aNull && bNull) continue;
                if (aNull) return spec.nullsFirst;
                if (bNull) return !spec.nullsFirst;
                const Column& scol = tbl.cols[sortIdx];
                bool less = false, greater = false;
                if (scol.dataType == "numeric") {
                    less = std::get<4>(a.vals[i]) < std::get<4>(b.vals[i]);
                    greater = std::get<4>(b.vals[i]) < std::get<4>(a.vals[i]);
                } else if (scol.dataType == "char" ||
                           scol.dataType == "uuid" ||
                           scol.isVariableLength) {
                    const int comparison = compareTextValues(
                        sortComparisonColumns[i], std::get<0>(a.vals[i]),
                        std::get<0>(b.vals[i]));
                    less = comparison < 0;
                    greater = comparison > 0;
                } else if (scol.dataType == "date") {
                    less = std::get<3>(a.vals[i]) < std::get<3>(b.vals[i]);
                    greater = std::get<3>(b.vals[i]) < std::get<3>(a.vals[i]);
                } else if (scol.dataType == "float" ||
                           scol.dataType == "double" ||
                           scol.dataType == "decimal") {
                    const int comparison = compareFloatingValues(
                        std::get<2>(a.vals[i]), std::get<2>(b.vals[i]));
                    less = comparison < 0;
                    greater = comparison > 0;
                } else {
                    less = std::get<1>(a.vals[i]) < std::get<1>(b.vals[i]);
                    greater = std::get<1>(b.vals[i]) < std::get<1>(a.vals[i]);
                }
                if (less) return spec.ascending;
                if (greater) return !spec.ascending;
            }
            return false;
        });
        std::vector<std::pair<int64_t, std::string>> sorted;
        sorted.reserve(matchRows.size());
        for (const auto& k : keys)
            sorted.push_back(std::move(matchRows[k.rowIndex]));
        matchRows = std::move(sorted);
    }

    // If any ORDER BY spec is an expression, apply expression-based sorting
    // directly on the original row buffers to preserve MVCC/formatting state.
    bool hasExprOrder = false;
    for (const auto& spec : orderBy) {
        if (spec.isExpression) { hasExprOrder = true; break; }
    }
    if (hasExprOrder) {
        std::vector<int64_t> sliceCounts(orderBy.size(), 0);
        for (size_t i = 0; i < orderBy.size(); ++i) {
            if (orderBy[i].isExpression &&
                (orderBy[i].exprFunc == "left" ||
                 orderBy[i].exprFunc == "right") &&
                !parseTextSortCount(orderBy[i].exprArg2, sliceCounts[i])) {
                throw DbError("0A000", "non-constant text slice count in ORDER BY");
            }
        }
        std::vector<Column> expressionComparisonColumns;
        for (const auto& spec : orderBy) {
            Column comparisonColumn;
            comparisonColumn.dataType = "text";
            comparisonColumn.isVariableLength = true;
            if (!spec.isExpression || spec.exprFunc == "upper" ||
                spec.exprFunc == "lower" || spec.exprFunc.empty()) {
                for (size_t columnIndex = 0; columnIndex < tbl.len;
                     ++columnIndex) {
                    if (tbl.cols[columnIndex].dataName ==
                        (spec.isExpression ? spec.exprArg : spec.colName)) {
                        comparisonColumn = tbl.cols[columnIndex];
                        break;
                    }
                }
            } else if (spec.exprFunc == "add" || spec.exprFunc == "sub" ||
                       spec.exprFunc == "abs" || spec.exprFunc == "length") {
                comparisonColumn.dataType = "numeric";
                comparisonColumn.isVariableLength = true;
            }
            if (isEvaluatedNumericSort(spec)) {
                std::map<std::string, std::string> typeHints;
                for (size_t ci = 0; ci < tbl.len; ++ci)
                    typeHints[tbl.cols[ci].dataName] = tbl.cols[ci].dataType;
                const std::string resultType = ExprHelper::inferResultType(
                    spec.expressionSql, typeHints);
                comparisonColumn.dataType =
                    resultType == "double precision" ? "double" :
                    resultType == "real" ? "float" :
                    (resultType == "integer" || resultType == "bigint" ||
                     resultType == "smallint") ? "int" : "numeric";
                comparisonColumn.isVariableLength =
                    comparisonColumn.dataType == "numeric";
            } else if (isEvaluatedPolymorphicSort(spec)) {
                std::map<std::string, std::string> typeHints;
                for (size_t ci = 0; ci < tbl.len; ++ci)
                    typeHints[tbl.cols[ci].dataName] = tbl.cols[ci].dataType;
                setPolymorphicSortType(
                    comparisonColumn,
                    ExprHelper::inferResultType(spec.expressionSql, typeHints));
            } else if (!spec.expressionSql.empty() &&
                       (spec.exprFunc == "date_trunc" ||
                        spec.exprFunc == "to_date" ||
                        spec.exprFunc == "to_timestamp")) {
                std::map<std::string, std::string> typeHints;
                for (size_t ci = 0; ci < tbl.len; ++ci)
                    typeHints[tbl.cols[ci].dataName] = tbl.cols[ci].dataType;
                const std::string resultType = ExprHelper::inferResultType(
                    spec.expressionSql, typeHints);
                if (resultType == "date" ||
                    resultType == "timestamp" ||
                    resultType == "timestamptz") {
                    comparisonColumn.dataType = resultType;
                    comparisonColumn.isVariableLength = false;
                }
            }
            if (!spec.collation.empty()) {
                comparisonColumn.collation =
                    collation::normalizeName(spec.collation) == "binary"
                        ? "C" : spec.collation;
                TableSchema collationProbe;
                collationProbe.len = 1;
                collationProbe.cols[0] = comparisonColumn;
                if (resolveTableCollations(
                        *this, dbname, collationProbe) != DBStatus::OK) {
                    return result;
                }
                comparisonColumn = std::move(collationProbe.cols[0]);
            }
            expressionComparisonColumns.push_back(
                std::move(comparisonColumn));
        }

        struct ExprKey {
            size_t idx;
            std::vector<std::string> exprVals;
            std::vector<bool> exprNulls;
        };
        std::vector<ExprKey> ekeys;
        ekeys.reserve(matchRows.size());
        std::map<std::string, std::string> expressionTypeHints;
        for (size_t ci = 0; ci < tbl.len; ++ci)
            expressionTypeHints[tbl.cols[ci].dataName] =
                tbl.cols[ci].dataType;
        // PostgreSQL resolves explicit collation conflicts during analysis,
        // including when the input relation contains no rows. Do not execute
        // the expression merely to inspect its collation.
        for (size_t keyIndex = 0; keyIndex < orderBy.size(); ++keyIndex) {
            const auto& spec = orderBy[keyIndex];
            if (spec.expressionSql.empty()) continue;
            std::string resultCollation;
            try {
                resultCollation = ExprHelper::analyzeExplicitResultCollation(
                    spec.expressionSql);
            } catch (...) {
                throw;
            }
            if (!spec.collation.empty() || resultCollation.empty()) continue;
            auto& comparisonColumn = expressionComparisonColumns[keyIndex];
            comparisonColumn.collation = resultCollation;
            TableSchema collationProbe;
            collationProbe.len = 1;
            collationProbe.cols[0] = comparisonColumn;
            if (resolveTableCollations(*this, dbname, collationProbe) !=
                DBStatus::OK) {
                return result;
            }
            comparisonColumn = std::move(collationProbe.cols[0]);
        }
        for (size_t ri = 0; ri < matchRows.size(); ++ri) {
            ExprKey ek{ri, {}, {}};
            NullRowBinding nullBinding(
                this, dbname, tbl.tablename, matchRows[ri].first, tbl.len);
            // Build column value map for expression evaluation
            std::map<std::string, std::string> rowData;
            std::map<std::string, bool> rowNulls;
            for (size_t ci = 0; ci < tbl.len; ++ci) {
                bool valueIsNull = false;
                rowData[tbl.cols[ci].dataName] = extractColumnValue(
                    matchRows[ri].second, tbl, ci, dbname, true,
                    &valueIsNull);
                rowNulls[tbl.cols[ci].dataName] = valueIsNull ||
                    (tbl.cols[ci].generatedKind != 'v' &&
                     dbms::detail::storedRowColumnIsNull(*this, dbname, tbl.tablename, tbl, matchRows[ri].first, ci));
            }
            size_t expressionIndex = 0;
            std::map<std::string, ExprEvalResult> expressionValues;
            for (const auto& spec : orderBy) {
                const size_t keyIndex = expressionIndex++;
                if (!spec.isExpression) {
                    const auto value = rowData.find(spec.colName);
                    const auto isNull = rowNulls.find(spec.colName);
                    ek.exprVals.push_back(value == rowData.end() ? "" : value->second);
                    ek.exprNulls.push_back(isNull == rowNulls.end() || isNull->second);
                    continue;
                }
                std::string ev;
                bool expressionIsNull = false;
                bool evaluatedGeneralExpression = false;
                auto getCol = [&](const std::string& name) -> std::string {
                    auto it = rowData.find(name);
                    return (it != rowData.end()) ? it->second : "";
                };
                std::string argVal = getCol(spec.exprArg);
                if (!spec.expressionSql.empty()) {
                    std::set<std::string> nullColumns;
                    for (const auto& [name, isNull] : rowNulls)
                        if (isNull) nullColumns.insert(name);
                    const auto& expressionIdentity = sortExpressionIdentities.at(spec.expressionSql);
                    auto found = expressionValues.find(expressionIdentity);
                    if (found == expressionValues.end())
                        found = expressionValues.emplace(expressionIdentity,
                            ExprHelper::evalStringWithNulls(spec.expressionSql,
                                rowData, nullColumns, expressionTypeHints, dbname,
                                "", this)).first;
                    const auto& evaluated = found->second;
                    if (!evaluated.ok) {
                        if (!evaluated.sqlState.empty())
                            throw DbError(evaluated.sqlState, evaluated.error);
                        throw std::runtime_error(evaluated.error.empty()
                            ? "unsupported ORDER BY expression (SQLSTATE 0A000)"
                            : evaluated.error);
                    }
                    ev = evaluated.value;
                    expressionIsNull = evaluated.isNull;
                    evaluatedGeneralExpression = true;
                    if (spec.exprFunc == "expreval") {
                        auto& column = expressionComparisonColumns[keyIndex];
                        setPolymorphicSortType(column,
                            ExprHelper::canonicalResultTypeName(evaluated.typeName));
                        const std::string type = ExprHelper::canonicalResultTypeName(evaluated.typeName);
                        if (type == "boolean" || type == "time" || type == "money" || type == "uuid") {
                            column.dataType = type;
                            column.isVariableLength = false;
                        }
                    }
                    if (spec.collation.empty() &&
                        !evaluated.collation.empty()) {
                        auto& comparisonColumn =
                            expressionComparisonColumns[keyIndex];
                        if (comparisonColumn.collation.empty()) {
                            comparisonColumn.collation =
                                evaluated.collation;
                            TableSchema collationProbe;
                            collationProbe.len = 1;
                            collationProbe.cols[0] = comparisonColumn;
                            if (resolveTableCollations(
                                    *this, dbname, collationProbe) !=
                                DBStatus::OK) {
                                return result;
                            }
                            comparisonColumn =
                                std::move(collationProbe.cols[0]);
                        }
                    }
                } else if (spec.exprFunc == "length") {
                    ev = std::to_string(argVal.size());
                } else if (spec.exprFunc == "upper") {
                    ev = argVal;
                    for (char& c : ev) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
                } else if (spec.exprFunc == "lower") {
                    ev = argVal;
                    for (char& c : ev) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
                } else if (spec.exprFunc == "left") {
                    ev = leftSortTextValue(argVal, sliceCounts[keyIndex]);
                } else if (spec.exprFunc == "right") {
                    ev = rightSortTextValue(argVal, sliceCounts[keyIndex]);
                } else if (spec.exprFunc == "reverse") {
                    ev = reverseSortTextValue(argVal);
                } else if (spec.exprFunc == "abs") {
                    try { ev = std::to_string(std::llabs(std::stoll(argVal))); } catch (...) { ev = "0"; }
                } else if (spec.exprFunc == "add") {
                    try { ev = std::to_string(std::stoll(argVal) + std::stoll(spec.exprArg2)); } catch (...) { ev = argVal; }
                } else if (spec.exprFunc == "sub") {
                    try { ev = std::to_string(std::stoll(argVal) - std::stoll(spec.exprArg2)); } catch (...) { ev = argVal; }
                } else {
                    ev = argVal;
                }
                ek.exprVals.push_back(ev);
                const auto nullIt = rowNulls.find(spec.exprArg);
                if (!evaluatedGeneralExpression && nullIt != rowNulls.end())
                    expressionIsNull = nullIt->second;
                ek.exprNulls.push_back(expressionIsNull);
            }
            ekeys.push_back(std::move(ek));
        }
        std::stable_sort(ekeys.begin(), ekeys.end(), [&](const ExprKey& a, const ExprKey& b) {
            for (size_t keyIndex = 0; keyIndex < orderBy.size(); ++keyIndex) {
                const auto& spec = orderBy[keyIndex];
                const std::string& av = a.exprVals[keyIndex];
                const std::string& bv = b.exprVals[keyIndex];
                const bool aNull = a.exprNulls[keyIndex];
                const bool bNull = b.exprNulls[keyIndex];
                if (aNull && bNull) continue;
                if (aNull) return spec.nullsFirst;
                if (bNull) return !spec.nullsFirst;
                const auto less = compareValues(
                    expressionComparisonColumns[keyIndex], av, false,
                    bv, false, "<");
                const auto greater = compareValues(
                    expressionComparisonColumns[keyIndex], av, false,
                    bv, false, ">");
                const bool isLess = less == PredicateTruth::True;
                const bool isGreater = greater == PredicateTruth::True;
                if (isLess) return spec.ascending;
                if (isGreater) return !spec.ascending;
            }
            return false;
        });
        std::vector<std::pair<int64_t, std::string>> sorted;
        sorted.reserve(matchRows.size());
        for (const auto& ek : ekeys) {
            sorted.push_back(std::move(matchRows[ek.idx]));
        }
        matchRows = std::move(sorted);
    }

    // DISTINCT ON: keep first row for each distinct combination of specified columns
    if (!distinctOnCols.empty()) {
        std::vector<size_t> distinctIdxs;
        for (const auto& colName : distinctOnCols) {
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == colName) { distinctIdxs.push_back(i); break; }
            }
        }
        if (distinctIdxs.size() == distinctOnCols.size()) {
            std::set<std::pair<std::vector<std::string>,
                               std::vector<bool>>> seen;
            std::vector<std::pair<int64_t, std::string>> deduped;
            for (auto& mr : matchRows) {
                NullRowBinding nullBinding(
                    this, dbname, tbl.tablename, mr.first, tbl.len);
                std::vector<std::string> keyValues;
                std::vector<bool> keyNulls;
                for (size_t idx : distinctIdxs) {
                    bool valueIsNull = false;
                    std::string value = extractColumnValue(
                        mr.second, tbl, idx, dbname, true, &valueIsNull);
                    const bool resultIsNull = valueIsNull ||
                        (tbl.cols[idx].generatedKind != 'v' &&
                         dbms::detail::storedRowColumnIsNull(*this, dbname, tbl.tablename, tbl, mr.first, idx));
                    keyValues.push_back(
                        resultIsNull ? std::string{} :
                            canonicalColumnKeyValue(tbl.cols[idx], value));
                    keyNulls.push_back(resultIsNull);
                }
                if (seen.emplace(
                        std::move(keyValues), std::move(keyNulls)).second) {
                    deduped.push_back(std::move(mr));
                }
            }
            matchRows = std::move(deduped);
        }
    }

    for (auto& mr : matchRows) {
        NullRowBinding nullBinding(
            this, dbname, tbl.tablename, mr.first, tbl.len);
        std::string rowStr;
        std::vector<std::string> structuredRow;
        std::vector<bool> structuredNullRow;
        for (size_t i = 0; i < tbl.len; ++i) {
            const Column& col = tbl.cols[i];
            if (!selectCols.empty() && selectCols.find(col.dataName) == selectCols.end())
                continue;
            bool valueIsNull = false;
            std::string val = extractColumnValue(
                mr.second, tbl, i, dbname, true, &valueIsNull);
            // VIRTUAL generated columns carry the evaluator's NULL result;
            // their unused heap slot cannot describe logical nullness.
            const bool resultIsNull = valueIsNull ||
                (col.generatedKind != 'v' && dbms::detail::storedRowColumnIsNull(*this, dbname, tbl.tablename, tbl, mr.first, i));
            // Apply session timezone for TIMESTAMPTZ columns
            if (col.dataType == "timestamptz" && !col.isArray &&
                !resultIsNull && !val.empty()) {
                // Render the logical datum, never reinterpret physical row bytes:
                // legacy seconds and tagged microseconds use different epochs.
                if (const auto micros = temporal_storage_detail::parseTimestampMicros(val)) {
                    if (!isInfiniteTimestamp(*micros)) {
                        int64_t utcSec = *micros / temporal_storage_detail::MicrosPerSecond;
                        if (*micros % temporal_storage_detail::MicrosPerSecond < 0) --utcSec;
                        utcSec += temporal_storage_detail::postgresEpochSeconds();
                        int renderOffset = timezoneOffsetMinutes;
                        if (const Session* session = currentSession()) {
                            if (const auto namedOffset = dbms::ianaTimezoneOffsetMinutes(
                                    session->timeZone, utcSec))
                                renderOffset = *namedOffset;
                        }
                        val = temporal_storage_detail::formatTimestampMicrosWithOffset(
                            *micros, renderOffset);
                    }
                }
            }
            if (resultIsNull) rowStr += "NULL ";
            else if (val.find(' ') != std::string::npos && selectCols.size() != 1)
                rowStr += "\"" + val + "\" ";
            else rowStr += val + ' ';
            structuredRow.push_back(resultIsNull ? std::string{} : val);
            structuredNullRow.push_back(resultIsNull);
        }
        result.push_back(rowStr);
        if (structuredRows) structuredRows->push_back(std::move(structuredRow));
        if (structuredNulls)
            structuredNulls->push_back(std::move(structuredNullRow));
        if (structuredRowIds) structuredRowIds->push_back(mr.first);
    }
    dbms::recordTableScan(dbname, tablename, matchRows.size(), usedIndex, conds.empty());
    return result;
}

// ========================================================================
// Scalar function helper
// ========================================================================
// Shared UDF-body executor: evaluates a stored UDF (SQL or PL/pgSQL) with
// literal argument values.  Used by scalar-function dispatch and by
// StorageEngine::callUDF (trigger EXECUTE FUNCTION actions).
static std::pair<bool, size_t> nativePlpgsqlExecSql(
    StorageEngine& engine, const std::string& dbname, const std::string& sql);
namespace {
struct StoredFunctionFrame {
    const StorageEngine* engine;
    std::string database;
    const Session* session;
    char volatility;
};
thread_local std::vector<StoredFunctionFrame> storedFunctionFrames;

bool storedFunctionTransactionControl(SqlCommand command) {
    switch (command) {
        case SqlCommand::Begin: case SqlCommand::StartTransaction:
        case SqlCommand::Commit: case SqlCommand::Rollback:
        case SqlCommand::Abort: case SqlCommand::End:
        case SqlCommand::Savepoint: case SqlCommand::ReleaseSavepoint:
        case SqlCommand::RollbackToSavepoint: case SqlCommand::PrepareTransaction:
        case SqlCommand::CommitPrepared: case SqlCommand::RollbackPrepared:
            return true;
        default: return false;
    }
}

bool storedFunctionReadOnlyQuery(const std::string& sql) {
    const auto command = SQLParser::classify(sql);
    if (command != SqlCommand::Select && command != SqlCommand::Values)
        return false;
    // Token boundaries distinguish command keywords from text and quoted
    // identifiers. SELECT classification alone does not catch a write CTE
    // or row-locking SELECT. Nested VOLATILE calls are deliberately allowed:
    // their own function frame establishes their write/snapshot policy.
    const auto tokens = SQLParser::tokenize(sql);
    for (size_t i = 0; i < tokens.size(); ++i) {
        const std::string word = SQLParser::toLower(tokens[i]);
        if (tokens[i] == "(" && i + 1 < tokens.size()) {
            const auto next = SQLParser::toLower(tokens[i + 1]);
            if (next == "insert" || next == "update" || next == "delete" ||
                next == "merge" || next == "replace") return false;
        }
        if (word == "for" && i + 1 < tokens.size()) {
            const auto next = SQLParser::toLower(tokens[i + 1]);
            if (next == "update" || next == "share" || next == "no" ||
                next == "key") return false;
        }
    }
    return true;
}
} // namespace

PlPgsqlQueryResult StorageEngine::plpgsqlQuery(const std::string& dbname,
                                             const std::string& sql,
                                             const PlPgsqlQueryOptions& options) const {
    const bool functionBody = !storedFunctionFrames.empty() &&
        storedFunctionFrames.back().engine == this &&
        storedFunctionFrames.back().database == dbname &&
        storedFunctionFrames.back().session == currentSession();
    const bool readOnlyBody = functionBody &&
        storedFunctionFrames.back().volatility != 'v';
    const auto failure = [](const std::string& state, const std::string& message) {
        PlPgsqlQueryResult result;
        result.sqlState = state;
        result.message = message;
        return result;
    };
    const auto command = SQLParser::classify(sql);
    if (storedFunctionTransactionControl(command))
        return failure("2D000", "transaction control is not allowed in a stored-function body");
    if (readOnlyBody && !storedFunctionReadOnlyQuery(sql))
        return failure("0A000", "non-read-only SQL is not allowed in a non-volatile function");

    auto& context = transactionContext();
    const bool active = context.inTransaction && context.txnDB == dbname;
    const uint64_t transactionId = active ? context.currentTxnId : 0;
    ReadView callerView = context.readView;
    // Reacquire the context at exit: a failed nested command can abort the
    // transaction or restore a DDL backup and evict its CLOG/cache objects.
    // Never retain a context/CLOG pointer across execution or resurrect an
    // ended/replaced transaction. Combo CIDs are transaction-wide and must
    // survive restoration of the caller's fixed command snapshot.
    const auto restore = [&]() noexcept {
        if (!active) return;
        try {
            auto& current = transactionContext();
            if (!current.inTransaction || current.currentTxnId != transactionId ||
                current.txnDB != dbname) return;
            // Inspect the current cache without allocating during unwind.
            // A DDL restore can destroy the pointer captured on entry.
            std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
            const auto log = commitLogs_.find(dbname);
            callerView.commitLog = log == commitLogs_.end()
                ? nullptr : log->second.get();
            callerView.comboCommandIds.swap(current.readView.comboCommandIds);
            current.readView = std::move(callerView);
            if (!current.readView.commitLog) current.snapshotAcquired = false;
        } catch (...) {
            // Do not mask the body's original failure during unwinding.
        }
    };
    struct ViewScope {
        const decltype(restore)& callback;
        ~ViewScope() { callback(); }
    } viewScope{restore};
    if (active && !readOnlyBody) {
        auto* mutableEngine = const_cast<StorageEngine*>(this);
        if (!mutableEngine->advanceSqlCommandCounter())
            return failure("54000", "stored-function command ID limit exceeded");
        if (context.txnIsolationLevel == IsolationLevel::READ_COMMITTED ||
            context.txnIsolationLevel == IsolationLevel::READ_UNCOMMITTED)
            refreshReadView();
        context.readView.currentCommandId = context.currentCommandId;
        context.readView.commandIdVisibility = true;
    }
    if (plpgsqlQueryExecutor_) return plpgsqlQueryExecutor_(dbname, sql, options);
    if (command == SqlCommand::Insert || command == SqlCommand::Update ||
        command == SqlCommand::Delete) {
        const auto executed = nativePlpgsqlExecSql(
            *const_cast<StorageEngine*>(this), dbname, sql);
        PlPgsqlQueryResult result;
        result.ok = executed.first;
        result.rowCount = executed.second;
        if (!result.ok) {
            result.sqlState = "0A000";
            result.message = "native body command requires a full SQL execution host";
        }
        return result;
    }
    return plpgsqlQueryNative(dbname, sql, options);
}

namespace {
// Analysis invokes a type's input function for an actual unknown SQL string.
// It must not fold a cast of an already typed value (including arithmetic,
// numeric narrowing, parameters, and nested queries). Ordinary typmods belong
// to the later coercion step, not this input conversion.
std::string preparedPrimitiveInputType(const std::string& spelling) {
    if(const auto geometry=geometric_input_detail::builtinType(spelling);!geometry.empty())
        return geometry;
    const auto tokens = SQLParser::tokenize(spelling);
    std::vector<std::string> base;
    for (const auto& token : tokens) {
        if (token == "[" || token == "]") return {}; // array inputs are separate
        if (token == "(" || token == ")" || token == "," || token == "+" || token == "-" ||
            (!token.empty() && std::all_of(token.begin(), token.end(), [](unsigned char c) {
                return std::isdigit(c);
            }))) break;
        base.push_back(token);
    }
    if (base.empty()) return {};
    if (base.size() == 2 && SQLParser::toLower(base[0]) == "double" &&
        SQLParser::toLower(base[1]) == "precision") return "double precision";
    std::string name;
    for (const auto& token : base) name += token;
    CatalogManager::QualifiedName resolved;
    if (!CatalogManager::parseQualifiedName(name, resolved, true) ||
        (!resolved.schema.empty() && resolved.schema != "pg_catalog")) return {};
    static const std::map<std::string, std::string> inputTypes = {
        {"smallint","smallint"}, {"int2","smallint"},
        {"integer","integer"}, {"int","integer"}, {"int4","integer"},
        {"bigint","bigint"}, {"int8","bigint"},
        {"boolean","boolean"}, {"bool","boolean"},
        {"numeric","numeric"}, {"decimal","numeric"},
        {"real","real"}, {"float4","real"},
        {"float8","double precision"}, {"uuid","uuid"}
    };
    // Quoted SQL aliases are not pg_catalog type names. Preserve case and
    // namespace rather than converting a custom quoted type to a builtin.
    static const std::set<std::string> catalogNames = {
        "int2","int4","int8","bool","numeric","float4","float8","uuid"
    };
    if (base.back().front() == '"' && !catalogNames.count(resolved.name)) return {};
    const auto found = inputTypes.find(resolved.name);
    return found == inputTypes.end() ? std::string{} : found->second;
}

void validatePreparedPrimitiveInput(const QueryOutputColumn& target, const Expr* source,
    const std::string& database) {
    if (!source || source->preparedSubquery) return;
    const LiteralExpr* input = nullptr;
    if (!target.name.empty()) {
        // A real assignment column contributes input context only to its
        // direct, untyped SQL string leaf. Typed constants, parameters,
        // routines and child results must not be evaluated/reinterpreted as
        // unknown input, even when their current bytes happen to be equal.
        input = dynamic_cast<const LiteralExpr*>(source);
        if (input && !input->typeName.empty()) input = nullptr;
    } else if (const auto* literal = dynamic_cast<const LiteralExpr*>(source)) {
        if (!literal->typeName.empty()) input = literal;
    } else if (const auto* cast = dynamic_cast<const CastExpr*>(source)) {
        input = dynamic_cast<const LiteralExpr*>(cast->operand.get());
        if (input && !input->typeName.empty()) input = nullptr;
    } else if (const auto* binary = dynamic_cast<const BinaryOpExpr*>(source);
               binary && binary->op == "::") {
        input = dynamic_cast<const LiteralExpr*>(binary->left.get());
        if (input && !input->typeName.empty()) input = nullptr;
    }
    if (!input || input->preparedSubquery) return;
    const auto literalTokens = SQLParser::tokenize(input->value);
    if (literalTokens.size() != 1 || literalTokens.front().size() < 2 ||
        literalTokens.front().front() != '\'' || literalTokens.front().back() != '\'') return;
    auto type = preparedPrimitiveInputType(target.type);
    auto regtypeSpelling=target.type;
    const bool array=regtypeSpelling.size()>=2 && regtypeSpelling.compare(regtypeSpelling.size()-2,2,"[]")==0;
    if(array)regtypeSpelling.resize(regtypeSpelling.size()-2);
    CatalogManager::QualifiedName regtypeName;
    if(CatalogManager::parseQualifiedName(regtypeSpelling,regtypeName,true) &&
       regtypeName.name=="regtype" && (regtypeName.schema.empty() || regtypeName.schema=="pg_catalog"))
        type=ExprHelper::canonicalResultTypeName(ExprHelper::declaredTypeInput(target.type,database));
    if (type.empty()) return;
    CastExpr conversion;
    auto literal = std::make_unique<LiteralExpr>();
    literal->value = input->value; // exactly one raw SQL string, no typed operand
    conversion.operand = std::move(literal);
    conversion.typeName = type; // deliberately no ordinary typmod
    ExprEvaluator evaluator;
    evaluator.setCurrentDB(database);
    (void)evaluator.eval(&conversion, RowContext{});
}
} // namespace

static const QueryHostSetReturningProvider* preparedSetReturningRole(
    const ExprEvaluator& evaluator,const FunctionCallExpr* function,
    const StorageEngine* engine) {
    return evaluator.queryHostSetReturningRole(function,const_cast<StorageEngine*>(engine));
}

bool StorageEngine::ownsPreparedSetReturningCall(const std::string& dbname,
    const FunctionCallExpr* function) const {
    ExprEvaluator evaluator;evaluator.setCurrentDB(dbname);
    return preparedSetReturningRole(evaluator,function,this)!=nullptr;
}

DatumMetadataContextPtr StorageEngine::prepareDatumMetadataContext(
    const std::string& dbname,const std::string& physicalTable) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    struct Owner {
        CatalogManager::MetadataSnapshot snapshot;
        DeclaredTypeNamespace nameSpace;
        std::unique_ptr<DatumMetadataFactory> factory;
    };
    auto owner=std::make_shared<Owner>();
    owner->nameSpace=freezeDeclaredTypeNamespace(currentSession());
    if(!dbname.empty())owner->snapshot=catalogService_->metadataSnapshot(dbname);
    if(owner->snapshot.types.empty() && owner->snapshot.namespaces.empty()) {
        // Actual immutable bootstrap identities only; not catalog seeding.
        owner->snapshot.types=CatalogManager::builtinTypeRows();
        PgNamespaceRow catalog;catalog.oid=11;catalog.nspname="pg_catalog";
        owner->snapshot.namespaces.push_back(std::move(catalog));
    }
    owner->factory=std::make_unique<DatumMetadataFactory>(owner->snapshot,
        [raw=owner.get()](const std::string& declaration) {
            return resolveDeclaredTypeName(declaration,&raw->snapshot,nullptr,&raw->nameSpace).typeOid;
        });
    auto result=std::make_shared<DatumMetadataContext>();
    result->declaration=[owner](const std::string& declaration,uint32_t oid) {
        try {return owner->factory->declaration(declaration,oid);}
        catch(const DbError&) {return DatumTypePtr{};}
    };
    result->inputDeclaration=[owner](const std::string& declaration) {
        return resolveDeclaredTypeName(declaration,&owner->snapshot,nullptr,&owner->nameSpace).inputType;
    };
    result->modifier=[owner](DatumTypePtr declaration,int32_t modifier) {
        return owner->factory->modifier(std::move(declaration),modifier);
    };
    result->sourceColumns=!physicalTable.empty();
    result->record=[owner](const std::vector<DatumTypePtr>& fields) {
        return owner->factory->record(fields);
    };
    if(!physicalTable.empty()) {
        auto logical=CatalogService::logicalName(physicalTable);
        if(const auto* session=currentSession()) {
            const auto prefix=tempTablePrefix(*session,"");
            if(physicalTable.rfind(prefix,0)==0) {
                logical.schema=sessionTempSchemaName(*session);
                logical.name=physicalTable.substr(prefix.size());
            }
        }
        if(logical.schema.empty())logical.schema="public";
        Oid schema=INVALID_OID,relation=INVALID_OID;
        for(const auto& row:owner->snapshot.namespaces)
            if(row.nspname==logical.schema)schema=row.oid;
        for(const auto& row:owner->snapshot.relations)
            if(row.relnamespace==schema && row.relname==logical.name)relation=row.oid;
        for(const auto& row:owner->snapshot.attributes) {
            if(row.attrelid!=relation || !relation || row.attnum<=0 || row.attisdropped)continue;
            DatumTypePtr declaration;
            try {declaration=owner->factory->attribute(row);}catch(const DbError&) {}
            result->columns.emplace(row.attname,declaration);
            result->columns.emplace(logical.name+"."+row.attname,declaration);
            result->columns.emplace(logical.schema+"."+logical.name+"."+row.attname,declaration);
            if(row.attgenerated!='v') {
                result->storedColumns.insert(row.attname);
                result->storedColumns.insert(logical.name+"."+row.attname);
                result->storedColumns.insert(logical.schema+"."+logical.name+"."+row.attname);
            }
        }
    }
    return result;
}

template<class Builder>
decltype(auto) StorageEngine::withQueryBindingMetadata(const std::string& dbname,
    const std::string& sql,bool finalizeUnknownOutput,
    const std::function<std::optional<QueryRelationMetadata>(const std::string&)>& queryRelations,
    Builder&& builder) const {
        // Catalog rows are copied under one lock; schema/view loads only read.
        // The lock is released on return, before any prepared AST executes.
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        std::optional<CatalogManager::MetadataSnapshot> catalogSnapshot;
        if(databaseTransactionOwnershipDeferred()) {
            SQLParser parser;
            const auto parsed=parser.parseForBinding(sql);
            if(parsed.success && parsed.stmt && SQLParser::isDatabaseIndependentQuery(*parsed.stmt)) {
                // This whole AST has no relation, routine, parameter, SQL type
                // declaration or child. Its inferred primitive identities are
                // the immutable physical builtin producer, not a reason to
                // promote the logical transaction or inspect another owner's
                // uncommitted catalog. Every non-proven query keeps the fence.
                CatalogManager::MetadataSnapshot primitives;
                PgNamespaceRow catalog;catalog.oid=11;catalog.nspname="pg_catalog";catalog.nspowner=10;
                primitives.namespaces.push_back(std::move(catalog));
                primitives.types=CatalogManager::builtinTypeRows();
                catalogSnapshot=std::move(primitives);
            }
        }
        QueryBindingMetadata metadata;
        std::unique_ptr<DatumMetadataFactory> datumFactory;
        std::unique_ptr<DatumMetadataFactory> primitiveDatumFactory;
        CatalogManager::MetadataSnapshot primitiveDatumSnapshot;
        metadata.datumType=[&](const std::string& spelling,uint32_t oid) -> DatumTypePtr {
            if((!catalogSnapshot || (catalogSnapshot->types.empty() && catalogSnapshot->namespaces.empty())) && oid) {
                const auto& builtins=CatalogManager::builtinTypeRows();
                const auto found=std::find_if(builtins.begin(),builtins.end(),
                    [&](const auto& row){return row.oid==oid && row.typnamespace==11;});
                if(found!=builtins.end()) {
                    if(!primitiveDatumFactory) {
                        primitiveDatumSnapshot.types=builtins;
                        primitiveDatumFactory=std::make_unique<DatumMetadataFactory>(primitiveDatumSnapshot);
                    }
                    return primitiveDatumFactory->type(oid);
                }
            }
            if(!catalogSnapshot)catalogSnapshot=catalogService_->metadataSnapshot(dbname);
            if(!datumFactory)datumFactory=std::make_unique<DatumMetadataFactory>(*catalogSnapshot,
                [&](const std::string& declaration) {
                    const bool empty=catalogSnapshot->types.empty() && catalogSnapshot->namespaces.empty();
                    return resolveDeclaredTypeName(declaration,empty?nullptr:&*catalogSnapshot,currentSession()).typeOid;
                });
            try {return datumFactory->declaration(spelling,oid);}
            catch(const DbError&) {return DatumTypePtr{};}
        };
        const auto physicalDatum=[&](const PgAttributeRow& attribute) -> DatumTypePtr {
            if(!catalogSnapshot)catalogSnapshot=catalogService_->metadataSnapshot(dbname);
            if(!datumFactory) (void)metadata.datumType("",attribute.atttypid);
            try {return datumFactory?datumFactory->attribute(attribute):DatumTypePtr{};}
            catch(const DbError&) {return DatumTypePtr{};}
        };
        metadata.finalizeUnknownOutput = finalizeUnknownOutput;
        // Lexical query sources are distinct from the catalog provider so a
        // stored view can reset that namespace without losing catalog types.
        metadata.queryRelation = queryRelations;
        metadata.outputExpressionIdentity=[&](const Expr* expression,const PreparedQuery& query,const SelectStmt* owner) {
            return ExprHelper::preparedSortExpressionIdentity(expression,query,[](const ColumnRefExpr& column) {
                if(!column.binding)throw DbError("XX000","output equality lost its bound source");
                const auto& binding=*column.binding;
                return std::to_string(binding.scopeDepth)+":"+std::to_string(binding.sourceOrdinal)+":"+
                    std::to_string(binding.columnOrdinal)+":"+binding.declaredType;
            },dbname,const_cast<StorageEngine*>(this),false,owner);
        };
        const auto viewSource = [&](const std::string& name) {
            auto view = getViewSQL(dbname, name);
            if (view.empty()) return view;
            const auto protectedBytes = sqlProtectedBytes(view);
            size_t envelope = view.size();
            for (const auto& marker : {std::string("\nBASE_TABLE:"), std::string("\nWITH_CHECK_OPTION:")}) {
                size_t at = view.find(marker);
                while (at != std::string::npos) {
                    if (!protectedBytes[at + 1]) { envelope = std::min(envelope, at); break; }
                    at = view.find(marker, at + marker.size());
                }
            }
            view.resize(envelope);
            return view;
        };
        metadata.relation = [&](const std::string& spelling) -> QueryRelationMetadata {
            CatalogManager::QualifiedName requested;
            if (!CatalogManager::parseQualifiedName(spelling, requested, true))
                throw DbError("42601", "invalid relation name");
            // A source-free prepared value does not require a storage read.
            // In particular, preparing CASE must not promote a deferred
            // query transaction just to copy a catalog it will never use.
            if (!catalogSnapshot) catalogSnapshot = catalogService_->metadataSnapshot(dbname);
            const auto& catalog = *catalogSnapshot;
            std::vector<std::string> schemas;
            const Session* session = currentSession();
            if (!requested.schema.empty()) schemas.push_back(requested.schema);
            else {
                std::string canonical; std::vector<std::string> path;
                if (!session || !parseSessionSearchPath(session->searchPath, path, canonical))
                    path = {"public"};
                std::vector<std::string> explicitSchemas;
                for (const auto& entry : path)
                    explicitSchemas.push_back(session ? expandSessionSearchPathEntry(entry, session->username) : entry);
                const bool explicitTemporary = session &&
                    std::any_of(explicitSchemas.begin(), explicitSchemas.end(), [&](const auto& schema) {
                        return schema == "pg_temp" || schema == sessionTempSchemaName(*session);
                    });
                if (session && !explicitTemporary) schemas.push_back(sessionTempSchemaName(*session));
                schemas.push_back("pg_catalog");
                schemas.insert(schemas.end(), explicitSchemas.begin(), explicitSchemas.end());
            }
            for (auto schema : schemas) {
                if (schema == "pg_temp" && session) schema = sessionTempSchemaName(*session);
                QueryRelationMetadata description{schema, requested.name, {}, {}};
                if (schema == "pg_catalog") {
                    static const std::map<std::string, QueryRowDescriptor> virtualTables = {
                        {"pg_class", {{"oid","oid"},{"relname","name"},{"relnamespace","oid"},
                            {"relkind","\"char\""},{"relnatts","smallint"},{"relpersistence","\"char\""},{"relowner","oid"}}},
                        {"pg_namespace", ownedNamespaceCatalogDescriptor()},
                        {"pg_settings", {{"name","text"},{"setting","text"},{"unit","text"}}},
                        {"pg_stat_activity", {{"pid","integer"},{"datname","name"},{"usename","name"},{"state","text"},{"query","text"}}}
                    };
                    const auto found = virtualTables.find(requested.name);
                    // Match the established pg_settings/pg_stat_activity
                    // dispatcher: an unqualified user table/view remains a
                    // physical relation, not a virtual INSERT/UPDATE target.
                    // Explicit pg_catalog names and pg_class keep their
                    // existing catalog identity; no source is opened here.
                    const bool physicalShadow = requested.schema.empty() &&
                        (requested.name == "pg_settings" || requested.name == "pg_stat_activity" ||
                         requested.name == "pg_namespace") &&
                        (tableExists(dbname,requested.name) || viewExists(dbname,requested.name));
                    if (found != virtualTables.end() && !physicalShadow) {
                        description.columns = found->second;
                        for(auto& column:description.columns) {
                            column.typeOid=mapBuiltinTypeNameToOid(column.type);
                            if(column.typeOid)column.typeMetadata=metadata.datumType(column.type,column.typeOid);
                        }
                        return description;
                    }
                    if(requested.name=="pg_type" &&
                       (!requested.schema.empty() ||
                        (!tableExists(dbname,requested.name) && !viewExists(dbname,requested.name)))) {
                        description.columns=ownedTypeCatalogDescriptor();
                        for(auto& column:description.columns) {
                            column.typeOid=mapBuiltinTypeNameToOid(column.type);
                            if(column.typeOid)column.typeMetadata=metadata.datumType(column.type,column.typeOid);
                        }
                        return description;
                    }
                }
                Oid namespaceId = INVALID_OID;
                for (const auto& ns : catalog.namespaces) if (ns.nspname == schema) namespaceId = ns.oid;
                for (const auto& relation : catalog.relations) {
                    if (relation.relnamespace != namespaceId || relation.relname != requested.name) continue;
                    auto attributes = catalog.attributes;
                    std::sort(attributes.begin(), attributes.end(), [](const auto& a, const auto& b) { return a.attnum < b.attnum; });
                    for (const auto& attribute : attributes) {
                        if (attribute.attrelid != relation.oid || attribute.attnum <= 0 || attribute.attisdropped) continue;
                        std::string typeName = "unknown";
                        bool arrayType = attribute.attndims > 0;
                        Oid valueType = attribute.atttypid;
                        std::set<Oid> domainTypes;
                        for (;;) {
                            const PgTypeRow* domain = nullptr;
                            for (const auto& type : catalog.types)
                                if (type.oid == valueType && type.typtype == 'd') { domain = &type; break; }
                            if (!domain) break;
                            if (domainTypes.size() >= 64 || !domainTypes.insert(valueType).second ||
                                domain->typbasetype == INVALID_OID)
                                throw DbError("XX001", "invalid domain catalog ancestry");
                            valueType = domain->typbasetype;
                        }
                        for (const auto& type : catalog.types) {
                            if (type.oid != valueType) continue;
                            typeName = type.typname;
                            if (type.typcategory == 'A' && type.typelem != INVALID_OID) {
                                arrayType = true;
                                for (const auto& element : catalog.types)
                                    if (element.oid == type.typelem) { typeName = element.typname; break; }
                            }
                            break;
                        }
                        // Normalize the element before appending []; the
                        // scalar alias registry does not fold "int4[]".
                        typeName = ExprHelper::canonicalResultTypeName(typeName) + (arrayType ? "[]" : "");
                        description.columns.push_back({attribute.attname, typeName,
                            attribute.attgenerated != '\0', attribute.attidentity, attribute.atttypid, attribute.atttypmod,
                            physicalDatum(attribute)});
                    }
                    if (relation.relkind == 'v') {
                        description.viewSql = viewSource(schema == "public" ? requested.name : schema + "." + requested.name);
                        if (description.viewSql.empty()) throw DbError("XX000", "view has no stored query");
                        return description;
                    }
                    if (!description.columns.empty()) return description;
                }
                const bool temporary = session && schema == sessionTempSchemaName(*session);
                const std::string physical = temporary ? tempTablePrefix(*session, requested.name)
                    : schema == "public" ? requested.name : schema + "__" + requested.name;
                std::ifstream input(schemaPath(dbname, physical), std::ios::binary);
                if (input) {
                    const auto table = readSchema(input, physical);
                    for (size_t i = 0; i < table.len; ++i)
                        description.columns.push_back({table.cols[i].dataName,
                            ExprHelper::canonicalResultTypeName(table.cols[i].dataType + (table.cols[i].isArray ? "[]" : "")),
                            !table.cols[i].generatedExpr.empty(), table.cols[i].identityKind, 0, table.cols[i].typeMod});
                    if (!description.columns.empty()) return description;
                }
                auto view = viewSource(schema == "public" ? requested.name : schema + "." + requested.name);
                if (!view.empty()) {
                    description.viewSql = std::move(view);
                    return description;
                }
            }
            throw DbError("42P01", "relation \"" + spelling + "\" does not exist");
        };
        const auto resolveOperatorType = [&](const std::string& spelling,uint32_t typeOid) -> const PgTypeRow* {
            if(!catalogSnapshot)catalogSnapshot=catalogService_->metadataSnapshot(dbname);
            const auto& catalog=*catalogSnapshot;
            const PgTypeRow* resolved=nullptr;
            if(typeOid) {
                for(const auto& type:catalog.types)if(type.oid==typeOid){resolved=&type;break;}
                // Before a catalog is initialized, builtin declarations can
                // already carry their real OIDs. Resolve those from the same
                // immutable physical definitions used by real bootstrap,
                // without writing/initializing a catalog or inventing user
                // type/domain/enum metadata. A populated snapshot stays
                // authoritative; missing rows there remain genuine errors.
                if(!resolved && catalog.types.empty() && catalog.namespaces.empty())
                    for(const auto& type:CatalogManager::builtinTypeRows())
                        if(type.oid==typeOid){resolved=&type;break;}
            } else {
                CatalogManager::QualifiedName requested;
                // CAST grammar may retain spaces around a qualified dot.
                // Parse its declared type envelope before catalog identity
                // lookup; quoted identifier contents remain case-sensitive.
                const auto declared=SQLParser::parseTypeSpecification(spelling);
                if(CatalogManager::parseQualifiedName(declared.typeName,requested,true)) {
                    std::vector<std::string> schemas;
                    if(!requested.schema.empty())schemas.push_back(requested.schema);
                    else {
                        const Session* session=currentSession();
                        if(session)schemas.push_back(sessionTempSchemaName(*session));
                        schemas.push_back("pg_catalog");
                        std::string canonical;std::vector<std::string> path;
                        if(session && parseSessionSearchPath(session->searchPath,path,canonical))
                            for(const auto& entry:path)schemas.push_back(expandSessionSearchPathEntry(entry,session->username));
                        else schemas.push_back("public");
                    }
                    for(auto schema:schemas) {
                        if(schema=="pg_temp" && currentSession())schema=sessionTempSchemaName(*currentSession());
                        Oid ns=INVALID_OID;
                        for(const auto& name:catalog.namespaces)if(name.nspname==schema){ns=name.oid;break;}
                        for(const auto& type:catalog.types)
                            if(type.typnamespace==ns && type.typname==requested.name){resolved=&type;break;}
                        if(resolved)break;
                    }
                }
            }
            if(!resolved) {
                if(typeOid)throw DbError("XX000","operator input type metadata is missing");
                return nullptr;
            }
            std::set<Oid> visited;
            while(resolved->typtype=='d') {
                if(resolved->typbasetype==INVALID_OID)
                    throw DbError("XX000","domain base type metadata is missing");
                if(!visited.insert(resolved->oid).second)throw DbError("XX000","cyclic domain base type metadata");
                const PgTypeRow* parent=nullptr;
                for(const auto& type:catalog.types)if(type.oid==resolved->typbasetype){parent=&type;break;}
                if(!parent)throw DbError("XX000","domain base type metadata is missing");
                resolved=parent;
            }
            return resolved;
        };
        metadata.baseType = [&](const std::string& spelling,uint32_t typeOid) {
            if(!typeOid && TypeRegistry::instance().findType(spelling))
                return ExprHelper::canonicalResultTypeName(spelling);
            if(!typeOid && (spelling=="unknown" || (spelling.size()>=2 &&
                spelling.compare(spelling.size()-2,2,"[]")==0)))return spelling;
            const auto* resolved=resolveOperatorType(spelling,typeOid);
            if(!resolved)return ExprHelper::canonicalResultTypeName(spelling);
            // Legacy physical array attributes retain their element OID and
            // attndims. Never turn that declared array envelope into a scalar
            // simply because the element's catalog row is TEXT or BYTEA.
            if(resolved->typcategory=='A' || (spelling.size()>=2 &&
                spelling.compare(spelling.size()-2,2,"[]")==0))
                return ExprHelper::canonicalResultTypeName(spelling);
            // A user type's basename is not a builtin identity. Preserve its
            // actual namespace after following domains (including an enum or
            // range named text/int4) instead of resolving a search_path alias.
            if(resolved->typnamespace!=11) {
                if(!catalogSnapshot)catalogSnapshot=catalogService_->metadataSnapshot(dbname);
                for(const auto& space:catalogSnapshot->namespaces)if(space.oid==resolved->typnamespace) {
                    const auto quote=[](const std::string& name) {
                        std::string value="\"";for(char c:name){value+=c;if(c=='\"')value+=c;}return value+'\"';
                    };
                    return quote(space.nspname)+"."+quote(resolved->typname);
                }
                throw DbError("XX000","operator input type namespace is missing");
            }
            return ExprHelper::canonicalResultTypeName(resolved->typname);
        };
        metadata.enumType = [&](const std::string& spelling,uint32_t typeOid) -> std::optional<QueryEnumType> {
            if(spelling=="unknown" || (spelling.size()>=2 && spelling.compare(spelling.size()-2,2,"[]")==0) ||
                (!typeOid && TypeRegistry::instance().findType(spelling)))return std::nullopt;
            const auto* resolved=resolveOperatorType(spelling,typeOid);
            if(!resolved || resolved->typtype!='e')return std::nullopt;
            const auto& catalog=*catalogSnapshot;
            std::string schema;
            for(const auto& ns:catalog.namespaces)if(ns.oid==resolved->typnamespace){schema=ns.nspname;break;}
            if(schema.empty())throw DbError("XX001","enum type namespace metadata is missing");
            const auto quoted=[](const std::string& input) {
                std::string out="\"";
                for(char c:input){out+=c;if(c=='\"')out+=c;}
                return out+'\"';
            };
            QueryEnumType description;
            description.typeOid=resolved->oid;
            description.typeName=quoted(schema)+"."+quoted(resolved->typname);
            description.identity="enum:"+dbname+":"+std::to_string(resolved->oid);
            std::vector<PgEnumRow> labels;
            for(const auto& label:catalog.enumLabels)if(label.enumtypid==resolved->oid)labels.push_back(label);
            std::sort(labels.begin(),labels.end(),[](const auto& a,const auto& b){return a.enumsortorder<b.enumsortorder;});
            for(const auto& label:labels) {
                description.labels.push_back(label.enumlabel);
                description.identity+=":"+std::to_string(label.enumlabel.size())+":"+label.enumlabel;
            }
            return description;
        };
        metadata.declaredType = [&](const std::string& spelling) {
            if(!catalogSnapshot)catalogSnapshot=catalogService_->metadataSnapshot(dbname);
            // Native storage consumers can use a database before its system
            // catalog has been initialized. In that genuinely empty snapshot
            // only registered builtin input identities exist; lookup remains
            // read-only and must neither bootstrap nor invent user types.
            const bool emptyCatalog=catalogSnapshot->namespaces.empty() && catalogSnapshot->types.empty();
            const auto type=resolveDeclaredTypeName(spelling,
                emptyCatalog?nullptr:&*catalogSnapshot,currentSession());
            return QueryOutputColumn{"",type.typeName,false,0,type.typeOid,-1,
                metadata.datumType(type.typeName,type.typeOid)};
        };
        ExprEvaluator evaluator; evaluator.setCurrentDB(dbname);
        metadata.setReturning = [&](const FunctionCallExpr* function) -> std::optional<QuerySetReturningBinding> {
            // Existing scalar/stored resolution wins over query-host builtins,
            // including an actual public routine named unnest.
            const auto role=preparedSetReturningRole(evaluator,function,this);
            if(!role)return std::nullopt;
            const auto spelling=function->schema.empty()?function->funcName:function->schema+"."+function->funcName;
            if(!role->acceptsArity(function->args.size()) || !function->namedArgs.empty() || function->hasOver ||
                function->filter || function->distinct || !function->orderBy.empty())
                throw DbError("42883","function does not exist: "+spelling);
            std::vector<std::string> inputs;
            for(const auto& argument:function->args)
                inputs.push_back(ExprHelper::canonicalResultTypeName(ExprHelper::inferParsedInputType(
                    argument.get(),{},dbname,const_cast<StorageEngine*>(this))));
            return QuerySetReturningBinding{role->kind,role->identity,role->resultType(inputs)};
        };
        metadata.functionType = [&](const FunctionCallExpr* function) {
            CatalogManager::QualifiedName routine;
            const std::string spelling = function->schema.empty() ? function->funcName
                : function->schema + "." + function->funcName;
            if (CatalogManager::parseQualifiedName(spelling, routine, true) &&
                !routine.schema.empty() && routine.schema != "pg_catalog") {
                // Namespace identity is resolved after the actual argument
                // transforms, before any execution. Quoted case is not a
                // catalog alias: an absent namespace is 3F000, whereas an
                // absent routine in an existing namespace is 42883.
                if (!catalogSnapshot) catalogSnapshot = catalogService_->metadataSnapshot(dbname);
                auto schema = routine.schema;
                if (schema == "pg_temp" && currentSession())
                    schema = sessionTempSchemaName(*currentSession());
                const auto& namespaces = catalogSnapshot->namespaces;
                if (std::none_of(namespaces.begin(), namespaces.end(),
                    [&](const auto& entry) { return entry.nspname == schema; }) &&
                    !(validStoredIdentifier(schema, MAX_TABLE_NAME_LEN) &&
                      std::filesystem::exists(dbPath(dbname) / (".schema_" + schema))))
                    throw DbError("3F000", "schema \"" + routine.schema + "\" does not exist");
            }
            // OVER changes the required routine role, not its namespace or
            // identity. Resolve an actual scalar first, including stored
            // routines shadowing builtin window names on the search path.
            // Its arguments have already been bound, so ordinary missing
            // column/routine diagnostics retain their preparation priority.
            if (!function->aggregateOrderKeys.empty() &&
                evaluator.hasScalarFunction(function, const_cast<StorageEngine*>(this)))
                throw DbError("42809", "ORDER BY specified, but " + spelling +
                    " is not an aggregate function");
            if (!function->aggregateOrderKeys.empty() && function->hasOver)
                throw DbError("0A000", "aggregate ORDER BY is not implemented for window functions");
            if (function->hasOver &&
                evaluator.hasScalarFunction(function, const_cast<StorageEngine*>(this)))
                throw DbError("42809", "OVER specified, but " + spelling +
                    " is not a window function nor an aggregate function");
            if (CatalogManager::parseQualifiedName(spelling, routine, true) &&
                (routine.schema.empty() || routine.schema == "pg_catalog")) {
                if (routine.name == "exists") return std::string("boolean");
                // Window functions have query-host metadata, not scalar
                // evaluator callbacks. Resolve only their real builtin
                // namespace/signatures; never execute one to obtain a type.
                const auto& name = routine.name;
                const bool zeroArgument = name == "row_number" || name == "rank" ||
                    name == "dense_rank" || name == "percent_rank" || name == "cume_dist";
                const bool shiftedValue = name == "lag" || name == "lead";
                const bool singleValue = name == "first_value" || name == "last_value";
                const auto integerArgument = [&](size_t index) {
                    const auto* argument = function->args[index].get();
                    if (const auto* literal = dynamic_cast<const LiteralExpr*>(argument)) {
                        if (literal->typeName.empty() && !literal->preparedSubquery &&
                            (literal->value == "null" || (!literal->value.empty() &&
                             literal->value.front() == '\''))) return true;
                    }
                    const auto type = ExprHelper::canonicalResultTypeName(
                        ExprHelper::inferParsedResultType(argument, {}, dbname,
                                                         const_cast<StorageEngine*>(this)));
                    return type == "smallint" || type == "integer";
                };
                const auto count = function->args.size();
                const bool windowSignature = function->namedArgs.empty() &&
                    ((zeroArgument && count == 0) ||
                     (shiftedValue && count >= 1 && count <= 3 &&
                      (count < 2 || integerArgument(1))) ||
                     (singleValue && count == 1) ||
                     (name == "nth_value" && count == 2 && integerArgument(1)) ||
                     (name == "ntile" && count == 1 && integerArgument(0)));
                if (windowSignature) {
                    if (!function->hasOver)
                        throw DbError("42809", "window function " + name + " requires an OVER clause");
                    if (function->filter)
                        throw DbError("0A000", "FILTER is not implemented for non-aggregate window functions");
                    if (function->distinct)
                        throw DbError("0A000", "DISTINCT is not implemented for window functions");
                    // Use the resolved canonical routine identity. The
                    // raw quoted spelling is not an evaluator registry key.
                    if (zeroArgument)
                        return name == "percent_rank" || name == "cume_dist"
                            ? std::string("double precision") : std::string("bigint");
                    if (name == "ntile") return std::string("integer");
                    if (shiftedValue) {
                        std::vector<std::string> inputs{ExprHelper::inferParsedInputType(
                            function->args.front().get(), {}, dbname, const_cast<StorageEngine*>(this))};
                        if (count < 3 && common_type_detail::canonical(inputs.front()) == "unknown")
                            throw DbError("42804", "could not determine polymorphic type because input has type unknown");
                        if (count == 3) inputs.push_back(ExprHelper::inferParsedInputType(
                            function->args[2].get(), {}, dbname, const_cast<StorageEngine*>(this)));
                        try { return selectCommonType(inputs, name); }
                        catch (const DbError& error) {
                            if (error.sqlState() != "42804" && error.sqlState() != "42846") throw;
                            throw DbError("42883", "function does not exist: " + spelling);
                        }
                    }
                    return ExprHelper::canonicalResultTypeName(
                        ExprHelper::inferParsedResultType(function->args.front().get(), {}, dbname,
                                                         const_cast<StorageEngine*>(this)));
                }
                if (name == "array_agg" && function->hasOver &&
                    !function->setReturning &&
                    !evaluator.hasScalarFunction(function, const_cast<StorageEngine*>(this))) {
                    if (function->distinct)
                        throw DbError("0A000", "DISTINCT is not implemented for window aggregates");
                    const auto* argument = function->args.size() == 1
                        ? function->args.front().get() : nullptr;
                    const auto* literal = dynamic_cast<const LiteralExpr*>(argument);
                    if (!argument || !function->namedArgs.empty() ||
                        (literal && literal->value == "*"))
                        throw DbError("42883", "aggregate function has no matching signature");
                    const auto input = ExprHelper::canonicalResultTypeName(
                        ExprHelper::inferParsedInputType(argument, {}, dbname,
                                                         const_cast<StorageEngine*>(this)));
                    if (input == "unknown")
                        throw DbError("42725", "aggregate function is not unique");
                    // The existing window receiver collects scalar datums.
                    // Do not admit array-valued input as quoted scalar text:
                    // PostgreSQL requires another dimension and shape checks.
                    if (common_type_detail::array(input))
                        throw DbError("0A000", "array-valued ARRAY_AGG window input is not supported");
                    return input + "[]";
                }
                if (function->hasOver && (name == "string_agg" || name == "bit_and" ||
                        name == "bit_or" || name == "bit_xor")) {
                    if (function->distinct)
                        throw DbError("0A000", "DISTINCT is not implemented for window aggregates");
                    const size_t arguments = name == "string_agg" ? 2 : 1;
                    if (function->args.size() != arguments || !function->namedArgs.empty())
                        throw DbError("42883", "aggregate function has no matching signature");
                    std::vector<std::string> inputs;
                    for (const auto& argument : function->args) {
                        const auto* literal = dynamic_cast<const LiteralExpr*>(argument.get());
                        if (literal && !literal->preparedSubquery && literal->value == "*")
                            throw DbError("42883", "aggregate function has no matching signature");
                        inputs.push_back(ExprHelper::canonicalResultTypeName(
                            ExprHelper::inferParsedInputType(argument.get(), {}, dbname,
                                const_cast<StorageEngine*>(this))));
                    }
                    if (name == "string_agg") {
                        const auto text = [](const std::string& input) {
                            return input == "unknown" || input == "text" ||
                                input == "character varying" || input == "character" ||
                                input == "name" || input == "\"char\"";
                        };
                        if (std::all_of(inputs.begin(), inputs.end(), text)) return std::string("text");
                        if (std::all_of(inputs.begin(), inputs.end(), [](const auto& input) {
                                return input == "bytea" || input == "unknown";
                            }) && std::find(inputs.begin(), inputs.end(), "bytea") != inputs.end())
                            return std::string("bytea");
                    } else {
                        const auto& input = inputs.front();
                        if (input == "unknown")
                            throw DbError("42725", "aggregate function is not unique");
                        if (input == "smallint" || input == "integer" || input == "bigint" ||
                            input == "bit") return input;
                        if (input == "bit varying") return std::string("bit");
                    }
                    throw DbError("42883", "aggregate function has no matching signature");
                }
                if (function->hasOver) {
                    static const std::set<std::string> unaryStatistics = {
                        "stddev", "stddev_pop", "stddev_samp", "variance", "var_pop", "var_samp"};
                    static const std::set<std::string> binaryStatistics = {
                        "corr", "covar_pop", "covar_samp", "regr_avgx", "regr_avgy",
                        "regr_count", "regr_intercept", "regr_r2", "regr_slope",
                        "regr_sxx", "regr_sxy", "regr_syy"};
                    if (unaryStatistics.count(name) || binaryStatistics.count(name)) {
                        const size_t count = unaryStatistics.count(name) ? 1 : 2;
                        bool signature = function->args.size() == count && function->namedArgs.empty();
                        for (const auto& argument : function->args) {
                            const auto* literal = dynamic_cast<const LiteralExpr*>(argument.get());
                            if (literal && !literal->preparedSubquery && literal->value == "*") {
                                signature = false; continue;
                            }
                            const auto type = ExprHelper::canonicalResultTypeName(
                                ExprHelper::inferParsedInputType(argument.get(), {}, dbname,
                                    const_cast<StorageEngine*>(this)));
                            if (signature && count == 1 && type == "unknown")
                                throw DbError("42725", "aggregate function is not unique");
                            signature = signature && (type == "smallint" || type == "integer" ||
                                type == "bigint" || type == "numeric" || type == "real" ||
                                type == "double precision" || (count == 2 && type == "unknown"));
                        }
                        if (!signature)
                            throw DbError("42883", "aggregate function has no matching signature");
                        throw DbError("0A000", "statistical window aggregates require additional execution lowering");
                    }
                }
                auto aggregate = aggregate_type_detail::builtinName(function);
                // Aggregate windows keep the genuine aggregate signature;
                // the ordinary aggregate planner deliberately excludes OVER.
                // Only this query-host metadata boundary admits that role.
                if(aggregate.empty() && function->hasOver && !function->setReturning)
                    for(const auto* builtin:{"count","sum","avg","min","max","bool_and","bool_or","every"})
                        if(name==builtin){aggregate=name;break;}
                if (!aggregate.empty() &&
                    !evaluator.hasScalarFunction(function, const_cast<StorageEngine*>(this))) {
                    if(function->hasOver && function->distinct)
                        throw DbError("0A000","DISTINCT is not implemented for window aggregates");
                    if (!function->aggregateOrderKeys.empty()) {
                        std::function<void(const Expr*)> validateInput = [&](const Expr* value) {
                            if (!value || value->preparedSubquery) return;
                            if (const auto* call = dynamic_cast<const FunctionCallExpr*>(value)) {
                                if (call->setReturning)
                                    throw DbError("0A000", "aggregate function calls cannot contain set-returning function calls");
                                if (call->hasOver)
                                    throw DbError("42803", "aggregate function calls cannot contain window function calls");
                                if (!aggregate_type_detail::builtinName(call).empty() &&
                                    !evaluator.hasScalarFunction(call, const_cast<StorageEngine*>(this)))
                                    throw DbError("42803", "aggregate function calls cannot be nested");
                                for (const auto& argument : call->args) validateInput(argument.get());
                                for (const auto& argument : call->namedArgs) validateInput(argument.value.get());
                                for (const auto& key : call->aggregateOrderKeys) validateInput(key.expr.get());
                                validateInput(call->filter.get());
                            } else if (const auto* unary = dynamic_cast<const UnaryOpExpr*>(value))
                                validateInput(unary->operand.get());
                            else if (const auto* cast = dynamic_cast<const CastExpr*>(value))
                                validateInput(cast->operand.get());
                            else if (const auto* binary = dynamic_cast<const BinaryOpExpr*>(value)) {
                                validateInput(binary->left.get());
                                if (binary->op != "::" && binary->op != "COLLATE") validateInput(binary->right.get());
                            } else if (const auto* quantified = dynamic_cast<const QuantifiedComparisonExpr*>(value)) {
                                validateInput(quantified->left.get()); validateInput(quantified->right.get());
                            } else if (const auto* conditional = dynamic_cast<const CaseExpr*>(value)) {
                                validateInput(conditional->switchExpr.get()); validateInput(conditional->elseExpr.get());
                                for (const auto& arm : conditional->whenClauses) {
                                    validateInput(arm.first.get()); validateInput(arm.second.get());
                                }
                            } else if (const auto* array = dynamic_cast<const ArrayExpr*>(value))
                                for (const auto& element : array->elements) validateInput(element.get());
                            else if (const auto* row = dynamic_cast<const RowExpr*>(value))
                                for (const auto& element : row->elements) validateInput(element.get());
                        };
                        for (const auto& argument : function->args) validateInput(argument.get());
                        for (const auto& key : function->aggregateOrderKeys) validateInput(key.expr.get());
                        validateInput(function->filter.get());
                    }
                    const auto input = function->args.empty() ? std::string("unknown") :
                        ExprHelper::inferParsedInputType(function->args.front().get(), {}, dbname,
                                                       const_cast<StorageEngine*>(this));
                    if (function->hasOver && (aggregate == "min" || aggregate == "max") &&
                        function->args.size() == 1 && function->namedArgs.empty()) {
                        const auto* column = dynamic_cast<const ColumnRefExpr*>(function->args.front().get());
                        const uint32_t oid = column && column->binding ? column->binding->typeOid : 0;
                        if (oid && metadata.enumType) {
                            const auto actual = metadata.enumType(input, oid);
                            if (actual) return actual->typeName;
                        }
                    }
                    return aggregate_type_detail::resultType(function, aggregate, input);
                }
            }
            if (!evaluator.hasScalarFunction(function, const_cast<StorageEngine*>(this)))
                throw DbError("42883", "function does not exist: " + function->funcName);
            auto type = evaluator.scalarFunctionResultType(function, const_cast<StorageEngine*>(this));
            // Builtin metadata can depend on already-bound argument types.
            // Infer from the actual AST, never execute a routine or inspect
            // a row value to choose its return descriptor.
            if (type.empty()) type = ExprHelper::inferParsedResultType(function, {}, dbname,
                const_cast<StorageEngine*>(this));
            return type;
        };
        metadata.aggregateFunction = [&](const FunctionCallExpr* function) {
            // Reuse the same actual scalar-first role as functionType above;
            // an identically named selected stored scalar is not an aggregate.
            return !aggregate_type_detail::builtinName(function).empty() &&
                !evaluator.hasScalarFunction(function,const_cast<StorageEngine*>(this));
        };
        metadata.assignmentInput = [&](const QueryOutputColumn& target,
                                      const Expr* source, const std::string& sourceType) {
            validateAssignmentInput(target, source, sourceType);
            validatePreparedPrimitiveInput(target, source, dbname);
        };
        metadata.updateDefault = [&](const std::string& schema,const std::string& name,
                                     const std::string& column)->std::optional<std::string> {
            // A genuine materialized target has no column-default storage.
            // Bind DEFAULT as the assignment's typed NULL, then let the
            // existing whole-bind/constant-plan target-role check report
            // 42809. Do not try its backing heap or open a no-data reader.
            if (const_cast<StorageEngine*>(this)->resolveMaterializedView(dbname,schema,name))
                return std::nullopt;
            const Session* session=currentSession();
            const bool temporary=session && (schema==sessionTempSchemaName(*session) || schema=="pg_temp");
            const auto physical=temporary?tempTablePrefix(*session,name):schema=="public"?name:schema+"__"+name;
            // getTableSchema retains explicit/frozen column defaults and
            // resolves only a proven Domain origin to the direct domain's
            // current own default. The definition is copied before runtime.
            const auto table=getTableSchema(dbname,physical);
            for(size_t i=0;i<table.len;++i)if(table.cols[i].dataName==column) {
                if(table.cols[i].defaultValue.empty())return std::nullopt;
                return table.cols[i].defaultValue;
            }
            throw DbError("XX001","UPDATE default target has no physical column metadata");
        };
        return builder(metadata,catalogSnapshot);
}

PreparedQuery StorageEngine::prepareBoundQuery(const std::string& dbname,
    const std::string& sql,const std::vector<QueryBindingDatum>& bindings,
    bool finalizeUnknownOutput,
    const std::function<std::optional<QueryRelationMetadata>(const std::string&)>& queryRelations) const {
    return withQueryBindingMetadata(dbname,sql,finalizeUnknownOutput,queryRelations,
        [&](const QueryBindingMetadata& metadata,const auto&) {
            return prepareQuery(sql,bindings,metadata);
        });
}
QueryRowDescriptor StorageEngine::prepareReturningDeclaration(const std::string& dbname,
    const std::string& sql,const std::vector<QueryBindingDatum>& bindings,
    std::vector<QueryReturningOrigin>* origins) const {
    return withQueryBindingMetadata(dbname,sql,false,{},
        [&](const QueryBindingMetadata& metadata,const auto& snapshot) {
            auto declared=dbms::prepareReturningDeclaration(sql,bindings,metadata);
            if(origins) {
                std::vector<QueryReturningOrigin> output(declared.output.size());
                for(size_t i=0;i<declared.sources.size();++i) {
                    const auto& source=declared.sources[i];
                    if(!source.available || !snapshot)continue;
                    Oid namespaceOid=INVALID_OID,relationOid=INVALID_OID;
                    for(const auto& name:snapshot->namespaces)
                        if(name.nspname==source.schema){namespaceOid=name.oid;break;}
                    for(const auto& relation:snapshot->relations)
                        if(relation.relnamespace==namespaceOid && relation.relname==source.relation) {
                            relationOid=relation.oid;break;
                        }
                    if(!relationOid)continue;
                    std::vector<const PgAttributeRow*> attributes;
                    for(const auto& attribute:snapshot->attributes)
                        if(attribute.attrelid==relationOid && attribute.attnum>0 && !attribute.attisdropped)
                            attributes.push_back(&attribute);
                    std::sort(attributes.begin(),attributes.end(),[](const auto* left,const auto* right) {
                        return left->attnum<right->attnum;
                    });
                    if(source.columnOrdinal<attributes.size())
                        output[i]={relationOid,static_cast<uint16_t>(attributes[source.columnOrdinal]->attnum)};
                }
                *origins=std::move(output); // atomic publication after all analysis
            }
            return std::move(declared.output);
        });
}

bool StorageEngine::validateReturningNamespace(const std::string& dbname,const std::string& sql) const {
    return withQueryBindingMetadata(dbname,sql,false,{},
        [&](const QueryBindingMetadata& metadata,const auto&) {
            return dbms::validateReturningNamespace(sql,metadata);
        });
}

ExprValue StorageEngine::executeScalarSubquery(const std::string& dbname,
    const std::string& sql) const {
    return executeScalarSubquery(dbname, sql, {}, nullptr, {});
}

ExprValue StorageEngine::executeScalarSubquery(const std::string& dbname,
    const std::string& sql, std::shared_ptr<PreparedQuery> query,
    const Stmt* statement, const RowContext& row) const {
    const auto command = SQLParser::classify(sql);
    if (command != SqlCommand::Select && command != SqlCommand::Values)
        throw DbError("42601", "scalar subquery must be a SELECT or VALUES query");
    PlPgsqlQueryOptions options;
    options.maxRows = 2;
    options.captureOwningFirstRow=true;
    options.purpose = PlPgsqlQueryOptions::Purpose::OrdinarySubquery;
    if (query) {
        if (!statement || !query->statementOutputs.count(statement))
            throw DbError("XX000", "ordinary typed child has no genuine prepared owner");
        options.preparedQuery = std::move(query);
        options.preparedStatement = statement;
        options.preparedRow = row;
    } else if (statement) {
        throw DbError("XX000", "ordinary typed child has no retained query");
    }
    // Ordinary children inherit their caller's snapshot/CTE context. They
    // must not enter the PL/SPI command-counter and ReadView-refresh wrapper.
    const auto result = plpgsqlQueryExecutor_
        ? plpgsqlQueryExecutor_(dbname, sql, options)
        : plpgsqlQueryNative(dbname, sql, options);
    if (!result.ok)
        throw DbError(result.sqlState.empty() ? "XX000" : result.sqlState,
            result.message.empty() ? "scalar subquery execution failed" : result.message);
    if (result.columnCount != 1)
        throw DbError("42601", "subquery must return only one column");
    if (result.rowCount > 1)
        throw DbError("21000", "more than one row returned by a subquery used as an expression");
    const auto type = result.columnTypes.empty() ? std::string("unknown") : result.columnTypes.front();
    if (result.rowCount == 0) return ExprValue(type, "", true);
    if (result.firstRow.size() != 1)
        throw DbError("XX000", "scalar subquery has no structured first row");
    if (result.firstOwningRow && result.firstOwningRow->size()==1)
        return result.firstOwningRow->front();
    return ExprValue(type, result.firstRow.front().value_or(""), !result.firstRow.front().has_value());
}

PlPgsqlQueryResult StorageEngine::plpgsqlQueryPrepared(const std::string& dbname,
    const std::string& sql, const std::vector<QueryBindingDatum>& bindings,
    const PlPgsqlQueryOptions& options) const {
    try {
        const auto command = SQLParser::classify(sql);
        if (storedFunctionTransactionControl(command))
            throw DbError("2D000", "transaction control is not allowed in a stored-function body");
        const bool functionBody = !storedFunctionFrames.empty() &&
            storedFunctionFrames.back().engine == this &&
            storedFunctionFrames.back().database == dbname &&
            storedFunctionFrames.back().session == currentSession();
        if (functionBody && storedFunctionFrames.back().volatility != 'v' &&
            !storedFunctionReadOnlyQuery(sql))
            throw DbError("0A000", "non-read-only SQL is not allowed in a non-volatile function");
        if (command != SqlCommand::Select && command != SqlCommand::Values &&
            command != SqlCommand::Insert && command != SqlCommand::Update && command != SqlCommand::Delete &&
            command != SqlCommand::Explain && command != SqlCommand::CreateTable)
            return plpgsqlQuery(dbname, sql, options);
        auto prepared = std::make_shared<PreparedQuery>(prepareBoundQuery(dbname, sql, bindings));
        // No catalog/cache mutex is retained while SQL or a called routine
        // executes. A nested DDL command can upgrade the transaction fence.
        if (command == SqlCommand::Select || command == SqlCommand::Values) {
            // Both procedural expressions and SELECT INTO need the actual
            // prepared owner, typed cells and child identities. Re-rendering
            // and reparsing would discard correlation and subquery metadata.
            auto execution = options;
            execution.preparedQuery = prepared;
            execution.preparedStatement = prepared->ast.get();
            return plpgsqlQuery(dbname, sql, execution);
        }
        return plpgsqlQuery(dbname, prepared->legacySql(), options);
    } catch (const DbError& error) {
        PlPgsqlQueryResult result; result.sqlState = error.sqlState(); result.message = error.message(); return result;
    }
}

static PlPgsqlQueryResult plpgsqlScalarResult(const ExprEvalResult& value) {
    PlPgsqlQueryResult result;
    if (!value.ok) {
        result.sqlState = value.sqlState.empty() ? "XX000" : value.sqlState;
        result.message = value.error;
        const size_t marker = value.error.rfind("(SQLSTATE ");
        if (value.sqlState.empty() && marker != std::string::npos && marker + 16 == value.error.size() &&
            value.error.back() == ')') {
            const std::string state = value.error.substr(marker + 10, 5);
            if (state.find_first_not_of("0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ") == std::string::npos)
                result.sqlState = state;
        }
        return result;
    }
    result.ok = true;
    result.columnCount = result.rowCount = 1;
    result.columnTypes = {value.typeName};
    result.firstRow = {value.isNull ? std::nullopt
        : std::optional<std::string>{value.value}};
    if (value.owningValue) result.firstOwningRow=std::vector<ExprValue>{*value.owningValue};
    return result;
}

// Interpreter variable names are already decoded/canonical identifiers.
// RowContext itself folds keys, so bind real expression references to private
// positional keys before evaluation instead of collapsing "X" into x.
static PlPgsqlQueryResult plpgsqlEvalBoundExpression(
    const std::string& expression,
    const std::map<std::string, std::string>& variables,
    const std::set<std::string>& nullVariables,
    const std::map<std::string, std::string>& types,
    const std::string& dbname, const std::string& username,
    StorageEngine* sqlFunctionEngine = nullptr,
    bool captureOwningValue = false) {
    try {
        SQLParser parser;
        auto parsed = parser.parse("SELECT " + expression);
        auto* select = parsed.stmt
            ? dynamic_cast<SelectStmt*>(parsed.stmt.get()) : nullptr;
        if (!parsed.success || !select || select->selectList.size() != 1 ||
            !select->selectList.front().expr || !select->selectList.front().alias.empty())
            throw DbError("42601", parsed.error.empty()
                ? "invalid scalar PL/pgSQL expression" : parsed.error);
        if (select->fromClause || select->whereClause || !select->ctes.empty() ||
            select->setOp != SetOp::None || select->distinct || !select->distinctOn.empty() ||
            !select->groupBy.empty() || !select->orderBy.empty() || select->having ||
            select->limit || select->offset || !select->windowDefs.empty() ||
            !select->locking.empty() || !select->valuesRows.empty())
            throw DbError("0A000", "query clauses require the PL/pgSQL query host");

        RowContext context;
        std::map<std::string, std::string> bindings;
        size_t position = 0;
        for (const auto& variable : variables) {
            const std::string key = "__plpgsql_variable_" + std::to_string(position++);
            const auto type = types.find(variable.first);
            if (type != types.end() && !type->second.empty()) {
                // Preserve actual SQL widths (especially BIGINT), rather
                // than the legacy row helper's integer-family narrowing.
                context.set(key, ExprValue(ExprHelper::canonicalResultTypeName(type->second),
                    variable.second, nullVariables.count(variable.first) != 0));
            } else {
                // Trigger-context values historically have no type metadata.
                // Keep their existing interpretation on one collision-free
                // value, without treating its datum as SQL text.
                const auto value = ExprHelper::evalStringWithNulls(key,
                    {{key, variable.second}}, nullVariables.count(variable.first)
                        ? std::set<std::string>{key} : std::set<std::string>{},
                    {}, dbname, username, sqlFunctionEngine);
                if (!value.ok) return plpgsqlScalarResult(value);
                context.set(key, ExprValue(value.typeName, value.value, value.isNull));
            }
            bindings.emplace(variable.first, key);
        }
        // Preserve the scalar host's session values independently of local
        // variables of the same spelling; only actual variable references
        // are rebound to the private keys above.
        static const std::set<std::string> sessionValues = {
            "current_user", "session_user", "current_date",
            "current_timestamp", "localtimestamp"
        };
        ExprEvaluator evaluator;
        evaluator.setCurrentDB(dbname);
        const auto userValue = [username](const std::vector<ExprValue>&) {
            return ExprValue("name", username, username.empty());
        };
        evaluator.registerFunction("current_user", userValue, 's');
        evaluator.registerFunction("session_user", userValue, 's');
        std::vector<std::pair<FunctionCallExpr*,std::string>> functionNames;
        std::function<void(Expr*)> bind;
        bind = [&](Expr* node) {
            if (!node) throw DbError("42601", "missing scalar expression");
            if (auto* column = dynamic_cast<ColumnRefExpr*>(node)) {
                const std::string name = column->toString();
                const auto binding = bindings.find(name);
                if (binding == bindings.end()) {
                    if (!column->table.empty() || !column->schema.empty())
                        throw DbError("42P01", "missing variable record " + column->table);
                    if (!sessionValues.count(name))
                        throw DbError("42703", "variable does not exist: " + name);
                    if (!context.has(name)) {
                        const auto value = ExprHelper::evalStringWithNulls(
                            name, {}, {}, {}, dbname, username,
                            sqlFunctionEngine);
                        if (!value.ok) {
                            const auto failure = plpgsqlScalarResult(value);
                            throw DbError(failure.sqlState, failure.message);
                        }
                        context.set(name, ExprValue(value.typeName, value.value, value.isNull));
                    }
                    return;
                }
                column->column = binding->second;
                column->table.clear();
                column->schema.clear();
            } else if (auto* unary = dynamic_cast<UnaryOpExpr*>(node)) {
                bind(unary->operand.get());
            } else if (auto* binary = dynamic_cast<BinaryOpExpr*>(node)) {
                bind(binary->left.get());
                if (binary->op != "::") {
                    const auto operation = SQLParser::toLower(binary->op);
                    auto* list = dynamic_cast<RowExpr*>(binary->right.get());
                    if (list && (operation == "in" || operation == "not in")) {
                        for (auto& item : list->elements) bind(item.get());
                    } else bind(binary->right.get());
                }
            } else if (auto* cast = dynamic_cast<CastExpr*>(node)) {
                bind(cast->operand.get());
            } else if (auto* conditional = dynamic_cast<CaseExpr*>(node)) {
                if (conditional->switchExpr) bind(conditional->switchExpr.get());
                for (auto& arm : conditional->whenClauses) {
                    bind(arm.first.get());
                    bind(arm.second.get());
                }
                if (conditional->elseExpr) bind(conditional->elseExpr.get());
            } else if (auto* function = dynamic_cast<FunctionCallExpr*>(node)) {
                if(function->sqlValue!=FunctionCallExpr::SqlValue::None) {
                    // The parser's intrinsic is not a callable registry
                    // entry. Preserve its validated grammar and identity.
                    sql_value_detail::validate(*function);
                    return;
                }
                if (function->hasOver || function->filter || function->distinct ||
                    !function->orderBy.empty())
                    throw DbError("0A000", "aggregate/window expression requires a query host");
                static const std::set<std::string> syntaxFunctions = {
                    "coalesce", "nullif", "greatest", "least", "make_interval",
                    "between", "not between", "like escape", "not like escape",
                    "ilike escape", "not ilike escape", "similar to escape",
                    "not similar to escape"
                };
                std::string name = SQLParser::toLower(function->funcName);
                if (!syntaxFunctions.count(name)) {
                    CatalogManager::QualifiedName decoded;
                    if (!CatalogManager::parseQualifiedName(function->funcName, decoded, true) ||
                        !decoded.schema.empty())
                        throw DbError("42883", "function does not exist: " + function->funcName);
                    name = decoded.name;
                }
                std::string schemaName;
                if (!function->schema.empty()) {
                    CatalogManager::QualifiedName schema;
                    if (!CatalogManager::parseQualifiedName(function->schema, schema, true) ||
                        !schema.schema.empty())
                        throw DbError("42883", "function does not exist: " + function->schema + "." + name);
                    schemaName = schema.name;
                }
                const bool builtin = name == SQLParser::toLower(name) &&
                    (schemaName.empty() || schemaName == "pg_catalog") &&
                    (evaluator.hasFunction(name) || syntaxFunctions.count(name));
                if(!builtin) {
                    // Reuse the real typed scalar binder after its argument
                    // variables are transformed. A name-only private callback
                    // cannot select or retain one of several input signatures.
                    for(auto& argument:function->args)bind(argument.get());
                    for(auto& argument:function->namedArgs)bind(argument.value.get());
                    evaluator.bindScalarFunctions(function,sqlFunctionEngine);
                    if(!evaluator.hasScalarFunction(function,sqlFunctionEngine))
                        throw DbError("42883","function does not exist: "+function->funcName);
                    return;
                }
                functionNames.emplace_back(function,name);
                // SQL EXTRACT's field is syntax, not a procedural variable.
                // The shared parser represents it as the first argument.
                if (name == "extract" && !function->args.empty()) {
                    if (const auto* field = dynamic_cast<ColumnRefExpr*>(function->args.front().get());
                        field && field->table.empty() && field->schema.empty()) {
                        auto literal = std::make_unique<LiteralExpr>();
                        literal->typeName = "text";
                        literal->value = "'";
                        for (char c : field->column) {
                            literal->value += c;
                            if (c == '\'') literal->value += c;
                        }
                        literal->value += "'";
                        function->args.front() = std::move(literal);
                    }
                }
                for (auto& argument : function->args) bind(argument.get());
                for (auto& argument : function->namedArgs) bind(argument.value.get());
            } else if (auto* array = dynamic_cast<ArrayExpr*>(node)) {
                for(auto& element:array->elements)bind(element.get());
            } else if (node->type != ExprType::Literal) {
                throw DbError("0A000", "unsupported scalar PL/pgSQL expression");
            }
        };
        bind(select->selectList.front().expr.get());
        std::map<std::string,std::string> arrayTypes;
        for(const auto& binding:bindings)arrayTypes[binding.second]=context.get(binding.second)->typeName;
        // Resolve ARRAY metadata while SQL names and the actual owner remain
        // available; only then lower functions to execution-private slots.
        ExprHelper::prepareArrayTypes(select->selectList.front().expr.get(),arrayTypes,dbname,sqlFunctionEngine);
        for(const auto& function:functionNames){function.first->funcName=function.second;function.first->schema.clear();}
        // Set the actual engine owner for intrinsic namespace values too;
        // custom scalar slots above remain execution-private registrations.
        evaluator.bindScalarFunctions(select->selectList.front().expr.get(),sqlFunctionEngine);
        const ExprValue value = evaluator.eval(select->selectList.front().expr.get(), context);
        ExprEvalResult evaluated;
        evaluated.ok = !value.isUnknown();
        evaluated.value = value.value;
        evaluated.isNull = value.isNull;
        evaluated.typeName = value.typeName;
        evaluated.collation = value.collation;
        if (captureOwningValue && evaluated.ok) evaluated.owningValue=value;
        if (!evaluated.ok) evaluated.error = "unsupported scalar PL/pgSQL expression (SQLSTATE 0A000)";
        return plpgsqlScalarResult(evaluated);
    } catch (const DbError& error) {
        PlPgsqlQueryResult result;
        result.sqlState = error.sqlState();
        result.message = error.message();
        return result;
    } catch (const std::exception& error) {
        ExprEvalResult failure;
        failure.error = error.what();
        return plpgsqlScalarResult(failure);
    }
}

static bool evalUDFBody(const StorageEngine::UDFInfo& udf,
                        const std::string& funcName,
                        const std::vector<std::string>& argValues,
                        StorageEngine* engine,
                        const std::string& dbname,
                        std::string& returnValue,
                        const std::map<std::string, std::string>* extraVars,
                        bool* returnIsNull,
                        const std::vector<bool>* argNulls,
                        std::optional<ExprValue>* owningReturn) {
    if (owningReturn) owningReturn->reset();
    // SQL dispatched by a stored body can invoke that body again. Each
    // interpreter owns a separate step budget, so also bound the native
    // call stack and restore the counter on every error/return. The stack
    // watermark handles the much larger full-query dispatcher frames.
    struct CallBudget {
        unsigned depth = 0;
        uintptr_t origin = 0;
    };
    static thread_local CallBudget budget;
    const char stackMarker = 0;
    const uintptr_t position = reinterpret_cast<uintptr_t>(&stackMarker);
    const uintptr_t stackUsed = budget.origin > position
        ? budget.origin - position : position - budget.origin;
    if (budget.depth >= 128 || (budget.depth && stackUsed > 2 * 1024 * 1024))
        throw DbError("54001", "stored-function call stack limit exceeded");
    struct CallScope {
        CallBudget& budget;
        CallScope(CallBudget& state, uintptr_t position) : budget(state) {
            if (!budget.depth) budget.origin = position;
            ++budget.depth;
        }
        ~CallScope() { if (!--budget.depth) budget.origin = 0; }
    } callScope(budget, position);
    struct FunctionScope {
        FunctionScope(const StorageEngine* engine, const std::string& database,
                      char volatility) {
            storedFunctionFrames.push_back({engine, database, currentSession(), volatility});
        }
        ~FunctionScope() { storedFunctionFrames.pop_back(); }
    } functionScope(engine, dbname, udf.provolatile);
    // Native callers have no SQL dispatcher to supply the outer statement
    // boundary. Own one function-call transaction only in that case; a
    // server query/trigger/nested function always reuses its caller's owner.
    const bool ownsTransaction = engine && !engine->inTransaction();
    if (ownsTransaction) {
        const auto status = engine->beginTransaction(dbname);
        if (status != DBStatus::OK)
            throw DbError(sqlstateForDBStatus(status), "could not start function transaction");
        if (!engine->beginSqlCommand()) {
            engine->rollbackTransaction();
            throw DbError("XX000", "could not start function command");
        }
    }
    struct TransactionScope {
        StorageEngine* engine;
        bool owned;
        ~TransactionScope() noexcept {
            // The body/commit has already failed. Rollback helpers can
            // allocate or restore files; never replace that original error
            // with terminate() if their cleanup throws while unwinding.
            try {
                if (owned && engine->inTransaction()) engine->rollbackTransaction();
            } catch (...) {}
        }
    } transactionScope{engine, ownsTransaction};
    const auto body = [&]() -> bool {
    (void)funcName;
    if (returnIsNull) *returnIsNull = false;
    std::vector<std::string> funcArgs = argValues;
    size_t expectedArgs = udf.paramNames.size();
    if (expectedArgs == 1 && udf.paramNames.front().empty() &&
        (udf.paramTypes.empty() || udf.paramTypes.front().empty())) expectedArgs = 0;
    if (funcArgs.size() != expectedArgs) return false;
    if (udf.strict && argNulls &&
        std::any_of(argNulls->begin(), argNulls->end(), [](bool value) {
            return value;
        })) {
        returnValue.clear();
        if (returnIsNull) *returnIsNull = true;
        return true;
    }
    const auto coerceReturn = [&](const std::string& value, bool valueIsNull,
                                  const std::string& sourceType,
                                  const ExprValue* actualValue = nullptr) {
        if (valueIsNull ||
            TypeRegistry::instance().normalizeTypeName(udf.returnType) ==
                "void") {
            returnValue.clear();
            if (returnIsNull) *returnIsNull = true;
            if (owningReturn) *owningReturn=ExprValue(
                ExprHelper::canonicalResultTypeName(udf.returnType),"",true);
            return true;
        }
        const std::string binding = "__dbms_function_result";
        std::map<std::string, std::string> row{{binding, value}};
        std::map<std::string, std::string> hints{
            {binding, sourceType.empty() ? "text" : sourceType}};
        std::map<std::string, ExprValue> actualOutput;
        if (actualValue) actualOutput.emplace(binding,*actualValue);
        const auto converted = ExprHelper::evalStringWithNulls(
            "CAST(" + binding + " AS " + udf.returnType + ")",
            row, {}, hints, dbname, "", engine, {}, owningReturn!=nullptr,
            actualValue ? &actualOutput : nullptr);
        if (!converted.ok) {
            const auto failure = plpgsqlScalarResult(converted);
            throw DbError(failure.sqlState, failure.message);
        }
        returnValue = converted.isNull ? std::string{} : converted.value;
        if (returnIsNull) *returnIsNull = converted.isNull;
        if (owningReturn) *owningReturn=converted.owningValue;
        return true;
    };
    if (udf.language == "plpgsql") {
        std::map<std::string, std::string> params;
        std::set<std::string> nullParams;
        for (size_t i = 0; i < udf.paramNames.size() && i < funcArgs.size(); ++i) {
            params[udf.paramNames[i]] = funcArgs[i];
            if (argNulls && i < argNulls->size() && (*argNulls)[i]) {
                nullParams.insert(udf.paramNames[i]);
            }
        }
        // Trigger context (NEW.col / OLD.col / TG_*): pre-bound like
        // parameters; explicit parameters take precedence.
        if (extraVars) {
            for (const auto& kv : *extraVars) {
                params.emplace(kv.first, kv.second);
            }
        }
        PlPgsqlHost host;
        host.functionLabel = udf.name;
        host.parameterOrder = udf.paramNames;
        if (host.parameterOrder.size() == 1 && host.parameterOrder.front().empty()) host.parameterOrder.clear();
        for (size_t i = 0; i < udf.paramNames.size() && i < udf.paramTypes.size(); ++i)
            host.parameterTypes[udf.paramNames[i]] = udf.paramTypes[i];
        host.evalExprTyped = [engine, &dbname, owningReturn](const std::string& expression,
                                      const std::map<std::string, std::string>& variables,
                                      const std::set<std::string>& nullVariables,
                                      const std::map<std::string, std::string>& types) {
            try {
                const Session* session = currentSession();
                return plpgsqlEvalBoundExpression(expression, variables,
                    nullVariables, types, dbname,
                    session ? session->username : std::string{}, engine,owningReturn!=nullptr);
            } catch (const DbError& error) {
                PlPgsqlQueryResult result;
                result.sqlState = error.sqlState();
                result.message = error.message();
                return result;
            }
        };
        host.coerceValueTyped = [engine, &dbname](const std::optional<std::string>& value,
                                         const std::string& sourceType,
                                         const std::string& targetType) {
            const std::string key = "__plpgsql_assignment";
            const std::map<std::string, std::string> values{{key, value.value_or("")}};
            const std::set<std::string> nulls = value
                ? std::set<std::string>{} : std::set<std::string>{key};
            const std::map<std::string, std::string> types{
                {key, sourceType.empty() ? "text" : sourceType}};
            try {
                const Session* session = currentSession();
                return plpgsqlScalarResult(ExprHelper::evalStringWithNulls(
                    "CAST(" + key + " AS " + targetType + ")", values,
                    nulls, types, dbname, session ? session->username : std::string{}, engine));
            } catch (const DbError& error) {
                PlPgsqlQueryResult result;
                result.sqlState = error.sqlState();
                result.message = error.message();
                return result;
            }
        };
        host.evalExpr = [engine, &dbname](const std::string& e,
                           const std::map<std::string, std::string>&) {
            auto r = ExprHelper::evalString(e, {}, {}, dbname, "", engine);
            if (!r.ok) return std::optional<std::string>{};
            return std::optional<std::string>{r.isNull ? "null" : r.value};
        };
        host.execStmt = [engine, &dbname](const std::string& sql,
                                          const std::map<std::string, std::string>&) {
            const auto result = engine->plpgsqlQuery(dbname, sql);
            if (!result.ok)
                throw DbError(result.sqlState.empty() ? "XX000" : result.sqlState,
                              result.message);
            return true;
        };
        host.query = [engine, &dbname](const std::string& sql,
                                     const PlPgsqlQueryOptions& options) {
            return engine->plpgsqlQuery(dbname, sql, options);
        };
        host.queryPrepared = [engine, &dbname](const std::string& sql,
            const std::vector<QueryBindingDatum>& bindings, const PlPgsqlQueryOptions& options) {
            return engine->plpgsqlQueryPrepared(dbname, sql, bindings, options);
        };
        std::string rv, err, sqlState, plpgsqlReturnType;
        std::optional<ExprValue> plpgsqlOwningReturn;
        bool plpgsqlIsNull = false;
        const auto notice = [](const std::string& level, const std::string& message) {
            if (level == "notice") emitNotice(message);
            else if (level == "warning") emitWarning(message);
        };
        if (!PlPgsql::run(udf.expression, params, host, rv, err, notice,
                          &plpgsqlIsNull, &nullParams, &sqlState, &plpgsqlReturnType,
                          owningReturn ? &plpgsqlOwningReturn : nullptr)) {
            if (!sqlState.empty()) throw DbError(sqlState, err);
            return false;
        }
        return coerceReturn(rv, plpgsqlIsNull, plpgsqlReturnType,
            plpgsqlOwningReturn ? &*plpgsqlOwningReturn : nullptr);
    }

    // A SQL query body is a whole statement, not a scalar-expression suffix.
    // Keep the historical bare-expression form by giving it one SELECT
    // envelope, but never strip clauses, substitute text or borrow caller CTEs.
    std::string sql = trim(udf.expression);
    if (sql.empty()) return false;
    const auto command = SQLParser::classify(sql);
    if (command != SqlCommand::Select && command != SqlCommand::Values)
        sql = "SELECT " + sql;
    std::vector<QueryBindingDatum> parameters;
    for (size_t i = 0; i < udf.paramNames.size() && i < funcArgs.size(); ++i) {
        const std::string& name = udf.paramNames[i];
        if (i >= udf.paramTypes.size() || udf.paramTypes[i].empty())
            throw DbError("XX000", "SQL-function parameter has no declared type");
        const bool null = argNulls && i < argNulls->size() && (*argNulls)[i];
        parameters.push_back({"sql-function:" + std::to_string(i), name,
            udf.paramTypes[i], {udf.name}, !name.empty(),
            null ? std::nullopt : std::optional<std::string>{funcArgs[i]},
            i + 1, ParameterOrigin::RuntimeCell, true});
    }
    auto prepared = std::make_shared<PreparedQuery>(engine->prepareBoundQuery(dbname, sql, parameters, true));
    if (prepared->output.size() != 1)
        throw DbError("42601", "SQL scalar function must return one column");
    PlPgsqlQueryOptions options;
    options.maxRows = 1; // SQL scalar functions return the first row, not scalar-subquery cardinality.
    options.captureOwningFirstRow=owningReturn!=nullptr;
    options.purpose = PlPgsqlQueryOptions::Purpose::StoredFunction;
    options.preparedQuery = prepared;
    options.preparedStatement = prepared->ast.get();
    const auto evaluated = engine->plpgsqlQuery(dbname, sql, options);
    if (!evaluated.ok)
        throw DbError(evaluated.sqlState.empty() ? "XX000" : evaluated.sqlState, evaluated.message);
    if (evaluated.columnCount != 1 || evaluated.rowCount > 1 ||
        (evaluated.rowCount && evaluated.firstRow.size() != 1))
        throw DbError("XX000", "SQL-function scalar host returned an invalid result shape");
    if (!evaluated.rowCount) return coerceReturn("", true, udf.returnType);
    return coerceReturn(evaluated.firstRow.front().value_or(""),
        !evaluated.firstRow.front(), evaluated.columnTypes.empty() ? "text" : evaluated.columnTypes.front(),
        evaluated.firstOwningRow && evaluated.firstOwningRow->size()==1
            ? &evaluated.firstOwningRow->front() : nullptr);
    };
    const bool succeeded = body();
    if (ownsTransaction && !succeeded) {
        const auto rolledBack = engine->rollbackTransaction();
        if (rolledBack != DBStatus::OK)
            throw DbError(sqlstateForDBStatus(rolledBack), "function transaction rollback failed");
        transactionScope.owned = false;
    }
    if (ownsTransaction && succeeded) {
        if (!engine->inTransaction() || !engine->finishSqlCommand())
            throw DbError("XX000", "function transaction ended unexpectedly");
        const auto constraints = engine->validateImmediateForeignKeyChecks();
        if (constraints != DBStatus::OK)
            throw DbError(sqlstateForDBStatus(constraints), "function constraint validation failed");
        const auto committed = engine->commitTransaction();
        if (committed != DBStatus::OK)
            throw DbError(sqlstateForDBStatus(committed), "function transaction commit failed");
        transactionScope.owned = false;
    }
    return succeeded;
}

struct ParsedProjectionSubquery {
    ParseResult parsed;
    std::string columns;
    std::string predicate;
};

static std::string projectionIdentifier(std::string name) {
    if (name.size() >= 2 && name.front() == '"' && name.back() == '"') {
        name = name.substr(1, name.size() - 2);
        size_t position = 0;
        while ((position = name.find("\"\"", position)) != std::string::npos) {
            name.erase(position, 1);
            ++position;
        }
    }
    return name;
}

static ParsedProjectionSubquery parseProjectionSubquery(const std::string& sql) {
    auto tokens = SQLParser::tokenize(sql);
    if (!tokens.empty() && tokens.back() == ";") tokens.pop_back();
    const auto join = [&](size_t begin, size_t end) {
        std::string result;
        for (size_t i = begin; i < end; ++i) {
            if (i != begin) result += ' ';
            result += tokens[i];
        }
        return result;
    };
    ParsedProjectionSubquery result;
    SQLParser parser;
    result.parsed = parser.parse(join(0, tokens.size()));
    const auto* select = dynamic_cast<const SelectStmt*>(result.parsed.stmt.get());
    if (!result.parsed.success || !select || select->selectList.empty()) {
        throw DbError("42601", "invalid projection subquery");
    }
    if (!select->fromClause || select->fromClause->type != FromItem::Type::Table ||
        !select->groupBy.empty() || select->having || select->distinct ||
        select->setOp != SetOp::None || !select->ctes.empty() ||
        !select->locking.empty() || !select->windowDefs.empty()) {
        throw DbError("0A000", "unsupported projection subquery shape");
    }
    if (select->withTies && select->orderBy.empty()) {
        throw DbError("42601", "WITH TIES cannot be specified without ORDER BY");
    }
    // Slice complete lexer tokens, not substrings. Quoted text is one token
    // and nested FROM (e.g. EXTRACT) is not a query-clause boundary. Keeping
    // expression tokens also preserves parentheses and existing SQL-function
    // normalization in ExprHelper, which an AST toString round-trip loses.
    size_t from = tokens.size(), where = tokens.size(), endWhere = tokens.size();
    int depth = 0;
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (tokens[i] == "(") { ++depth; continue; }
        if (tokens[i] == ")") { --depth; continue; }
        if (depth != 0) continue;
        const std::string keyword = SQLParser::toLower(tokens[i]);
        if (keyword == "from" && from == tokens.size()) from = i;
        if (keyword == "where" && where == tokens.size()) where = i;
        if (where != tokens.size() && i > where &&
            (keyword == "order" || keyword == "limit" || keyword == "offset" ||
             keyword == "fetch" || keyword == "group" || keyword == "having" ||
             keyword == "for")) {
            endWhere = i;
            break;
        }
    }
    result.columns = join(1, from);
    if (where != tokens.size()) result.predicate = join(where + 1, endWhere);
    return result;
}

// True when a scalar-function argument is SQL NULL for the current row.
// Persisted columns consult the heap bitmap; VIRTUAL columns use the
// evaluator's NULL result.  This distinguishes NULL from an empty string.
static bool scalarArgColumnIsNull(const std::string& arg,
                                  const std::string& rowBuffer,
                                  const TableSchema& tbl,
                                  StorageEngine* engine,
                                  const std::string& dbname) {
    if (arg.empty() || arg.front() == 0x27) return false;  // literal
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName != arg) continue;
        if (!engine || dbname.empty()) return false;
        if (tbl.cols[i].generatedKind == 'v') {
            bool valueIsNull = false;
            (void)engine->extractColumnValue(
                rowBuffer, tbl, i, dbname, true, &valueIsNull);
            return valueIsNull;
        }
        // Condition-scope context (forEachRow scans)...
        if (g_condNullEngine && g_condNullRid >= 0 &&
            tbl.tablename == g_condNullTable)
            return dbms::detail::storedRowColumnIsNull(*engine, dbname, tbl.tablename, tbl,
                                             g_condNullRid, i);
        // ...or the extraction-scope NullRowBinding (rid-keyed agg loops).
        if (g_nullRowEngine && g_nullRowRid >= 0 && i < g_nullRowNatts &&
            tbl.tablename == g_nullRowTable)
            return dbms::detail::storedRowColumnIsNull(*engine, g_nullRowDb, tbl.tablename, tbl,
                                             g_nullRowRid, i);
        return false;
    }
    return false;
}
static std::string applyScalarFunc(const StorageEngine::SelectExpr& expr,
                                    const std::string& rowBuffer,
                                    const TableSchema& tbl,
                                    StorageEngine* engine,
                                    const std::string& dbname,
                                    std::optional<bool>* knownNull,
                                    std::optional<ExprValue>* owningValue,
                                    const DatumMetadataContext* datumMetadata,
                                    DatumTypePtr* owningDeclaration) {
    if (owningDeclaration)owningDeclaration->reset();
    if (knownNull) knownNull->reset();
    if (owningValue) owningValue->reset();
    const auto publishScalarResult = [&](const auto& value) {
        if (owningValue) {
            using Value=std::decay_t<decltype(value)>;
            if constexpr (std::is_same_v<Value,ExprValue>) *owningValue=value;
            else if (value.owningValue) *owningValue=*value.owningValue;
        }
        if(owningDeclaration) {
            using Value=std::decay_t<decltype(value)>;
            if constexpr (!std::is_same_v<Value,ExprValue>)
                *owningDeclaration=value.typeMetadata;
        }
        if (knownNull) *knownNull = value.isNull;
        return value.isNull ? std::string("NULL") : value.value;
    };
    auto scaleOf = [](const std::string& v) -> int {
        size_t dot = v.find('.');
        if (dot == std::string::npos) return -1;
        return static_cast<int>(v.size() - dot - 1);
    };
    auto isNumberLike = [](const std::string& v) -> bool {
        if (v.empty()) return false;
        size_t i = (v[0] == '-' || v[0] == '+') ? 1 : 0;
        if (i >= v.size()) return false;
        bool digit = false, dot = false;
        for (; i < v.size(); ++i) {
            if (v[i] >= '0' && v[i] <= '9') { digit = true; }
            else if (v[i] == '.' && !dot) { dot = true; }
            else return false;
        }
        return digit;
    };
    auto getVal = [&](const std::string& arg) -> std::string {
        if (arg.size() >= 2 && ((arg.front() == '\'' && arg.back() == '\'') || (arg.front() == '"' && arg.back() == '"')))
            return arg.substr(1, arg.size() - 2);
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == arg) {
                if (engine && !dbname.empty()) {
                    bool isNull=false;
                    auto value=engine->extractColumnValue(rowBuffer,tbl,i,dbname,true,&isNull);
                    if(!isNull && tbl.cols[i].generatedKind!='v' &&
                       stored_regtype_detail::columnType(tbl.cols[i].dataType)) {
                        const auto catalog=regtype_detail::metadata(*engine,dbname);
                        value=stored_regtype_detail::output(value,tbl.cols[i].isArray,catalog,currentSession());
                    }
                    return value;
                }
                return StorageEngine::extractColumnValueStatic(rowBuffer, tbl, i);
            }
        }
        // Nested scalar call in an argument (upper(substring(name,1,2))):
        // parse "name(arg,...)" and recurse through applyScalarFunc.
        {
            size_t nlp = arg.find('(');
            if (nlp != std::string::npos && nlp > 0 && arg.back() == ')') {
                std::string nfunc = arg.substr(0, nlp);
                bool nameOk = !nfunc.empty();
                for (char ch : nfunc)
                    if (!std::isalnum(static_cast<unsigned char>(ch)) && ch != '_')
                        { nameOk = false; break; }
                if (nameOk) {
                    std::string inner = arg.substr(nlp + 1, arg.size() - nlp - 2);
                    // Depth-aware comma split (shared shape with the
                    // projection layer's splitFuncArgs).
                    std::vector<std::string> nArgs;
                    std::string cur;
                    int depth = 0;
                    bool inQ = false;
                    for (size_t k = 0; k < inner.size(); ++k) {
                        char ch = inner[k];
                        if (ch == '\'') { inQ = !inQ; cur += ch; continue; }
                        if (!inQ) {
                            if (ch == '(') ++depth;
                            else if (ch == ')') --depth;
                            else if (ch == ',' && depth == 0) {
                                nArgs.push_back(trim(cur)); cur.clear(); continue;
                            }
                        }
                        cur += ch;
                    }
                    if (!trim(cur).empty() || !nArgs.empty()) nArgs.push_back(trim(cur));
                    // cast(v as numeric(4,2)): the nested-call split
                    // yields one arg; split the AS form into [val, type].
                    if (nfunc == "cast" && nArgs.size() == 1) {
                        std::string one = nArgs[0];
                        std::string oneLow;
                        for (char oc : one) oneLow += static_cast<char>(tolower(static_cast<unsigned char>(oc)));
                        size_t asP = oneLow.find(" as ");
                        if (asP != std::string::npos) {
                            std::string cv = trim(one.substr(0, asP));
                            std::string ct = trim(one.substr(asP + 4));
                            nArgs = {cv, ct};
                        }
                    }
                    StorageEngine::SelectExpr sub;
                    sub.isScalar = true;
                    sub.funcName = nfunc;
                    sub.funcArgs = nArgs;
                    sub.sessionUser = expr.sessionUser;
                    return applyScalarFunc(sub, rowBuffer, tbl, engine, dbname);
                }
            }
        }
        // String concatenation on columns ("v || 'q'"): PG || is strict
        // (a NULL operand makes the whole expression NULL); a NULL column
        // reads as empty, so an empty side folds to empty.
        {
            int dep = 0; bool inQ = false; size_t hit = std::string::npos;
            for (size_t i = 0; i + 1 < arg.size(); ++i) {
                char c = arg[i];
                if (c == 39) { inQ = !inQ; continue; }
                if (inQ) continue;
                if (c == '(') ++dep; else if (c == ')') --dep;
                if (dep == 0 && c == '|' && arg[i + 1] == '|' && i > 0) { hit = i; break; }
            }
            if (hit != std::string::npos) {
                std::string lp = trim(arg.substr(0, hit));
                std::string rp = trim(arg.substr(hit + 2));
                auto resolve2 = [&](const std::string& piece) -> std::string {
                    if (piece.size() >= 2 && piece.front() == 39 && piece.back() == 39)
                        return piece.substr(1, piece.size() - 2);
                    for (size_t ci = 0; ci < tbl.len; ++ci) {
                        if (tbl.cols[ci].dataName == piece) {
                            return (engine && !dbname.empty())
                                ? engine->extractColumnValue(rowBuffer, tbl, ci, dbname, true)
                                : StorageEngine::extractColumnValueStatic(rowBuffer, tbl, ci);
                        }
                    }
                    return piece;
                };
                std::string lv = resolve2(lp);
                std::string rv = resolve2(rp);
                if (lv.empty() || rv.empty()) {
                    if (scalarArgColumnIsNull(
                            lp, rowBuffer, tbl, engine, dbname) ||
                        scalarArgColumnIsNull(
                            rp, rowBuffer, tbl, engine, dbname))
                        return "NULL";
                    return "";
                }
                return lv + rv;
            }
        }
        // Bare arithmetic on a column (e.g. "x - 2.8" as a function argument):
        // fold left-to-right on + - * / % with columns resolved via getVal,
        // mirroring the engine arith handler semantics.  A signed operand
        // ("k * -2", "-2 * k") is valid: the leading sign is stripped for
        // the containment check but kept for stod.
        {
            static const char* ops[] = { "+", "-", "*", "/", "%" };
            for (const char* op : ops) {
                size_t p = arg.find(op);
                if (p == std::string::npos || p == 0) continue;
                std::string lhs = arg.substr(0, p);
                std::string rhs = arg.substr(p + 1);
                auto stripSign = [](std::string s) {
                    s = trim(s);
                    if (!s.empty() && (s[0] == '+' || s[0] == '-')) s.erase(0, 1);
                    return s;
                };
                std::string lchk = stripSign(lhs);
                std::string rchk = stripSign(rhs);
                if (lchk.find_first_of("+-*/%") != std::string::npos ||
                    rchk.find_first_of("+-*/%") != std::string::npos ||
                    trim(lhs).empty() || trim(rhs).empty()) continue;
                std::string lv, rv;
                auto resolve = [&](const std::string& piece, std::string& outv) {
                    std::string tp = trim(piece);
                    if (tp.size() >= 2 && tp.front() == 39 && tp.back() == 39) { outv = tp.substr(1, tp.size() - 2); return; }
                    for (size_t ci = 0; ci < tbl.len; ++ci) {
                        if (tbl.cols[ci].dataName == tp) {
                            outv = (engine && !dbname.empty())
                                ? engine->extractColumnValue(rowBuffer, tbl, ci, dbname, true)
                                : StorageEngine::extractColumnValueStatic(rowBuffer, tbl, ci);
                            return;
                        }
                    }
                    outv = tp;
                };
                resolve(lhs, lv);
                resolve(rhs, rv);
                if (lv.find_first_not_of("-+.eE0123456789") != std::string::npos ||
                    rv.find_first_not_of("-+.eE0123456789") != std::string::npos) continue;
                double l = std::stod(lv), r = std::stod(rv);
                double out = 0;
                if (*op == '+') out = l + r;
                else if (*op == '-') out = l - r;
                else if (*op == '*') out = l * r;
                else if (*op == '/') out = (r != 0) ? l / r : 0;
                else out = (r != 0) ? std::fmod(l, r) : 0;
                std::ostringstream os;
                os << out;
                return os.str();
            }
        }
        return arg;
    };
    auto scalarValueIsNull = [&](const std::string& arg,
                                 const std::string& value) {
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == arg) {
                return scalarArgColumnIsNull(
                    arg, rowBuffer, tbl, engine, dbname);
            }
        }
        const bool quoted = arg.size() >= 2 &&
            ((arg.front() == '\'' && arg.back() == '\'') ||
             (arg.front() == '"' && arg.back() == '"'));
        if (quoted || value != "NULL") return false;

        std::string normalizedArg = trim(arg);
        std::string loweredArg;
        loweredArg.reserve(normalizedArg.size());
        for (char c : normalizedArg) {
            loweredArg += static_cast<char>(
                std::tolower(static_cast<unsigned char>(c)));
        }
        if (loweredArg == "null") return true;

        // A nested expression can legitimately produce the four-character
        // text "NULL".  Re-evaluate it through the typed evaluator so its
        // separate NULL bit, rather than its display text, decides strict
        // propagation.
        std::map<std::string, std::string> rowContext;
        std::map<std::string, std::string> typeHints;
        std::set<std::string> nullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool valueIsNull = false;
            const std::string columnValue = engine && !dbname.empty()
                ? engine->extractColumnValue(
                      rowBuffer, tbl, i, dbname, true, &valueIsNull)
                : StorageEngine::extractColumnValueStatic(
                      rowBuffer, tbl, i);
            rowContext[tbl.cols[i].dataName] = columnValue;
            typeHints[tbl.cols[i].dataName] = tbl.cols[i].dataType;
            if (valueIsNull || (!engine && columnValue.empty()))
                nullColumns.insert(tbl.cols[i].dataName);
        }
        const auto evaluated = dbms::ExprHelper::evalStringWithNulls(
            normalizedArg, rowContext, nullColumns, typeHints, dbname,
            expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
        return evaluated.ok ? evaluated.isNull : true;
    };
    auto stringSearchPosition = [](const std::string& haystack,
                                   const std::string& needle) {
        const size_t bytePosition = haystack.find(needle);
        if (bytePosition == std::string::npos) return size_t{0};
        size_t characters = 0;
        for (size_t i = 0; i < bytePosition; ++i) {
            if ((static_cast<unsigned char>(haystack[i]) & 0xc0) != 0x80)
                ++characters;
        }
        return characters + 1;
    };

    if (expr.funcName == "abs" && expr.funcArgs.size() == 1) {
        std::map<std::string, std::string> types;
        for (size_t i = 0; i < tbl.len; ++i)
            types[tbl.cols[i].dataName] = tbl.cols[i].dataType +
                (tbl.cols[i].isArray ? "[]" : "");
        // This is a declaration probe, never a value/effect probe. Keep
        // REAL, NUMERIC and unbound legacy inputs on their existing paths.
        SQLParser parser;
        const auto parsed = parser.parse("SELECT " + expr.funcArgs.front());
        const auto* select = parsed.success
            ? dynamic_cast<const SelectStmt*>(parsed.stmt.get()) : nullptr;
        if (select && select->selectList.size() == 1 &&
            ExprHelper::canonicalResultTypeName(ExprHelper::inferParsedResultType(
                select->selectList.front().expr.get(), types, dbname, engine)) == "double precision") {
            std::map<std::string, std::string> values;
            std::set<std::string> nulls;
            for (size_t i = 0; i < tbl.len; ++i) {
                bool isNull = false;
                const auto value = engine && !dbname.empty()
                    ? engine->extractColumnValue(rowBuffer, tbl, i, dbname, true, &isNull)
                    : StorageEngine::extractColumnValueStatic(rowBuffer, tbl, i);
                values[tbl.cols[i].dataName] = value;
                if (isNull || (!engine && value.empty())) nulls.insert(tbl.cols[i].dataName);
            }
            // The existing typed callback owns FLOAT8 ABS and its output.
            // Handle this call before the legacy strictness pre-read below:
            // typed ABS already owns NULL and evaluates its argument once.
            const auto result = ExprHelper::evalStringWithNulls(
                "abs(" + expr.funcArgs.front() + ")", values, nulls, types,
                dbname, expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
            if (!result.ok) {
                const auto error = plpgsqlScalarResult(result);
                throw DbError(error.sqlState, error.message);
            }
            return publishScalarResult(result);
        }
    }
    // PG strict functions return NULL when any argument is NULL.  Column
    // arguments read as empty for physically-NULL values, so consult the
    // stored null bit before dispatching to the per-function bodies.
    {
        static const char* strictFns[] = {
            "length", "char_length", "character_length", "octet_length",
            "bit_length", "upper", "lower", "initcap", "btrim", "ltrim",
            "rtrim", "reverse", "left", "right", "lpad", "rpad",
            "repeat", "ascii", "chr_code", "md5", "sha256", "hash",
            "abs", "ceil", "ceiling", "floor", "round", "trunc",
            "sqrt", "exp", "ln", "log", "power", "sign", "width_bucket",
            "substring", "substr", "translate", "replace", "split_part",
            "concat_ws_null", "to_char", "to_date", "to_number",
            "to_timestamp", "date_trunc", "extract_",
            "age", "year", "month", "day", "hour", "minute", "second",
            "justify_days", "justify_hours", "network",
            "abbrev", "family", "host", "masklen", "set_masklen"
        };
        for (const char* sf : strictFns) {
            if (expr.funcName != sf) continue;
            for (const auto& arg : expr.funcArgs) {
                const std::string av = getVal(arg);
                if (scalarValueIsNull(arg, av)) {
                    if (knownNull) *knownNull = true;
                    return "NULL";
                }
            }
            break;
        }
    }

    if ((expr.funcName == "current_user" || expr.funcName == "session_user") && !expr.sessionUser.empty()) {
        return expr.sessionUser;
    }

    // EXISTS / NOT EXISTS subquery in a projection item, evaluated
    // per row over a real table ("SELECT EXISTS (SELECT 1 FROM t
    // WHERE ...) FROM u").  funcArgs[0] carries the full inner SQL;
    // uncorrelated inner references resolve against the inner table.
    if (expr.funcName == "exists_sub" && engine && !expr.funcArgs.empty()) {
        auto subquery = parseProjectionSubquery(expr.funcArgs[0]);
        const auto* select = static_cast<const SelectStmt*>(subquery.parsed.stmt.get());
        const std::string innerTbl = projectionIdentifier(select->fromClause->tableName);
        const std::string innerAlias = projectionIdentifier(select->fromClause->alias);
        const std::string& whereSql = subquery.predicate;
        auto& innerLocks = engine->getLockManager();
        innerLocks.setResourceNamespace(dbname);
        const bool innerLocked = engine->inTransaction()
            ? innerLocks.lockIntentShared(innerTbl)
            : innerLocks.lockShared(innerTbl);
        if (!innerLocked) {
            throw DbError("55P03", "could not lock EXISTS subquery relation");
        }
        ResourceUnlockGuard innerLockGuard(innerLocks, innerTbl);
        if (!engine->tableExists(dbname, innerTbl)) {
            throw DbError("42P01", "relation \"" + innerTbl + "\" does not exist");
        }
        TableSchema innerSch = engine->getTableSchema(dbname, innerTbl);
        const bool negate = expr.funcArgs.size() > 1 && expr.funcArgs[1] == "not";
        if(select->signedFetchCount && *select->signedFetchCount<0)
            throw DbError("2201W","FETCH count must not be negative");
        if (select->limit && *select->limit == 0) return negate ? "t" : "f";
        size_t remainingOffset = select->offset.value_or(0);

        std::set<std::string> innerColumnNames;
        for (size_t i = 0; i < innerSch.len; ++i)
            innerColumnNames.insert(innerSch.cols[i].dataName);

        std::map<std::string, std::string> outerContext;
        std::map<std::string, std::string> outerTypes;
        std::set<std::string> outerNulls;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool valueIsNull = false;
            const std::string value = engine->extractColumnValue(
                rowBuffer, tbl, i, dbname, true, &valueIsNull);
            const std::string qualified =
                tbl.tablename + "." + tbl.cols[i].dataName;
            outerContext[qualified] = value;
            outerTypes[qualified] = tbl.cols[i].dataType;
            if (valueIsNull) outerNulls.insert(qualified);
            if (!innerColumnNames.count(tbl.cols[i].dataName)) {
                outerContext[tbl.cols[i].dataName] = value;
                outerTypes[tbl.cols[i].dataName] = tbl.cols[i].dataType;
                if (valueIsNull)
                    outerNulls.insert(tbl.cols[i].dataName);
            }
        }

        bool anyRow = false;
        // Ordering cannot change whether a non-DISTINCT relation has a row
        // after OFFSET. EXISTS need not evaluate the SELECT list or sort keys.
        const auto matchedRow = [&]() {
            if (remainingOffset != 0) --remainingOffset;
            else anyRow = true;
        };
        std::string evaluationError;
        const bool scanned = engine->forEachRow(dbname, innerTbl, [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
            // forEachRow has a void callback and continues the physical
            // scan. Once EXISTS is decided, do not evaluate later rows.
            if (anyRow || !evaluationError.empty()) return;
            if (whereSql.empty()) {
                matchedRow();
                return;
            }
            NullRowBinding nullBinding(
                engine, dbname, innerTbl,
                StorageEngine::encodeRid(pageId, slotId), innerSch.len);
            bool toastOk = false;
            const std::string innerRow = engine->resolveToastValues(
                dbname, innerTbl, std::string(data, len), innerSch, &toastOk);
            if (!toastOk) {
                evaluationError = "EXISTS subquery TOAST value read failed";
                return;
            }
            auto rowContext = outerContext;
            auto typeHints = outerTypes;
            auto nullColumns = outerNulls;
            for (size_t i = 0; i < innerSch.len; ++i) {
                bool valueIsNull = false;
                const std::string value = engine->extractColumnValue(
                    innerRow, innerSch, i, dbname, true, &valueIsNull);
                const std::string bare = innerSch.cols[i].dataName;
                // The alias hides the inner physical relation name. Keeping
                // both would overwrite an outer reference in a self-query.
                const std::string qualified =
                    (innerAlias.empty() ? innerTbl : innerAlias) + "." + bare;
                rowContext[bare] = value;
                rowContext[qualified] = value;
                typeHints[bare] = innerSch.cols[i].dataType;
                typeHints[qualified] = innerSch.cols[i].dataType;
                nullColumns.erase(bare);
                nullColumns.erase(qualified);
                if (valueIsNull) {
                    nullColumns.insert(bare);
                    nullColumns.insert(qualified);
                }
            }
            const auto evaluated = dbms::ExprHelper::evalStringWithNulls(
                whereSql, rowContext, nullColumns, typeHints, dbname,
                expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
            if (!evaluated.ok) {
                evaluationError = evaluated.error.empty()
                    ? "failed to evaluate EXISTS predicate"
                    : evaluated.error;
                return;
            }
            if (evaluated.isNull ||
                (evaluated.value != "t" && evaluated.value != "true" &&
                 evaluated.value != "1")) {
                return;
            }
            matchedRow();
        });
        if (!scanned) {
            throw DbError("58030", "failed to scan EXISTS subquery relation");
        }
        if (!evaluationError.empty())
            throw std::runtime_error(evaluationError);
        return (negate ? !anyRow : anyRow) ? "t" : "f";
    }

    // Internal IS NULL / IS NOT NULL forms (rewritten from postfix syntax
    // by the projection router).
    if (expr.funcName == "is_null" || expr.funcName == "is_not_null") {
        if (expr.funcArgs.empty()) return "f";
        std::string v = getVal(expr.funcArgs[0]);
        bool isNull = scalarValueIsNull(expr.funcArgs[0], v);
        bool wantNull = (expr.funcName == "is_null");
        return (isNull == wantNull) ? "t" : "f";
    }

    // IS DISTINCT FROM / IS NOT DISTINCT FROM (null-safe equality): true
    // when exactly one side is NULL or the values differ; NULL never
    // propagates (the whole point of the operator).
    if (expr.funcName == "isdistinct" || expr.funcName == "isnotdistinct") {
        if (expr.funcArgs.size() < 2) return "f";
        std::map<std::string, std::string> rowContext;
        std::map<std::string, std::string> typeHints;
        std::set<std::string> nullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool valueIsNull = false;
            const std::string value = engine && !dbname.empty()
                ? engine->extractColumnValue(
                      rowBuffer, tbl, i, dbname, true, &valueIsNull)
                : StorageEngine::extractColumnValueStatic(
                      rowBuffer, tbl, i);
            rowContext[tbl.cols[i].dataName] = value;
            typeHints[tbl.cols[i].dataName] = tbl.cols[i].dataType;
            if (valueIsNull || (!engine && value.empty()))
                nullColumns.insert(tbl.cols[i].dataName);
        }
        const std::string operation = expr.funcName == "isdistinct"
            ? " IS DISTINCT FROM "
            : " IS NOT DISTINCT FROM ";
        const auto evaluated = dbms::ExprHelper::evalStringWithNulls(
            "(" + expr.funcArgs[0] + ")" + operation +
                "(" + expr.funcArgs[1] + ")",
            rowContext, nullColumns, typeHints, dbname,
            expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
        if (!evaluated.ok) {
            throw std::runtime_error(
                evaluated.error.empty()
                    ? "failed to evaluate distinct comparison"
                    : evaluated.error);
        }
        return evaluated.value;
    }

    // Math functions with PG-exact presentation semantics live in the expression
    // evaluator (float8 shortest-repr, numeric display scales, banker's rounding).
    // Delegate the whole family there and preserve its SQL errors; falling
    // through to the legacy handlers would turn domain errors into values.
    static const std::set<std::string> kEvaluatorBuiltins = {
        "round", "ceil", "floor", "trunc", "power", "pow", "exp", "ln", "log",
        "log10", "sqrt", "cbrt", "sin", "cos", "tan", "asin", "acos", "atan",
        "atan2", "cot", "degrees", "radians", "pi", "sinh", "cosh", "tanh",
        "asinh", "acosh", "atanh", "mod", "sign", "div", "width_bucket",
        "timezone"
    };
    if (kEvaluatorBuiltins.count(expr.funcName)) {
        std::map<std::string, std::string> rowContext;
        std::map<std::string, std::string> typeHints;
        std::set<std::string> nullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool valueIsNull = false;
            const std::string value = engine && !dbname.empty()
                ? engine->extractColumnValue(
                      rowBuffer, tbl, i, dbname, true, &valueIsNull)
                : StorageEngine::extractColumnValueStatic(
                      rowBuffer, tbl, i);
            rowContext[tbl.cols[i].dataName] = value;
            typeHints[tbl.cols[i].dataName] = tbl.cols[i].dataType;
            if (valueIsNull || (!engine && value.empty()))
                nullColumns.insert(tbl.cols[i].dataName);
        }
        std::string expressionSql = expr.funcName + "(";
        for (size_t i = 0; i < expr.funcArgs.size(); ++i) {
            if (i != 0) expressionSql += ",";
            expressionSql += expr.funcArgs[i];
        }
        expressionSql += ")";
        auto res = dbms::ExprHelper::evalStringWithNulls(
            expressionSql, rowContext, nullColumns, typeHints, dbname,
            expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
        if (res.ok) return publishScalarResult(res);
        throw std::runtime_error(
            res.error.empty() ? "failed to evaluate math function"
                              : res.error);
    }
    // Arithmetic projection: col op val op val ... evaluated left-to-right
    // (no precedence), for + - * / % on numeric operands.  Operands may be
    // bare columns (row-resolved via getVal), integer/float literals, or
    // quoted strings (string concat for '+').
    // expreval: general per-row expression (comparisons, LIKE) routed here
    // by the projection parser; evaluate through ExprHelper with the row
    // bound as column context.
    if (expr.funcName == "expreval" && !expr.funcArgs.empty()) {
        std::map<std::string, std::string> rowCtx;
        const auto typeHints = buildTypeHints(tbl);
        std::set<std::string> nullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool valueIsNull = false;
            std::string v = engine && !dbname.empty()
                ? engine->extractColumnValue(
                      rowBuffer, tbl, i, dbname, true, &valueIsNull)
                : StorageEngine::extractColumnValueStatic(rowBuffer, tbl, i);
            rowCtx[tbl.cols[i].dataName] = v;
            if (valueIsNull || (!engine && v.empty()))
                nullColumns.insert(tbl.cols[i].dataName);
        }
        SQLParser betweenParser;
        const auto parsedBetween = betweenParser.parse("SELECT " + expr.funcArgs[0]);
        const auto* betweenSelect = parsedBetween.success
            ? dynamic_cast<const SelectStmt*>(parsedBetween.stmt.get()) : nullptr;
        if (betweenSelect && betweenSelect->selectList.size() == 1 &&
            containsBetweenExpression(betweenSelect->selectList.front().expr.get())) {
            // BETWEEN's AND is grammar, not a separately rendered boolean
            // arm. Keep the complete typed AST and UNKNOWN input provenance.
            const auto value = ExprHelper::evalStringWithNulls(expr.funcArgs[0],
                rowCtx, nullColumns, typeHints, dbname, expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
            if (!value.ok) {
