                        ++i;
                        while (i < keyPath.size() && keyPath[i] != '\'') { cur.push_back(keyPath[i]); ++i; }
                        if (i < keyPath.size()) ++i; // skip closing '
                    } else {
                        while (i < keyPath.size() && keyPath[i] != ']') { cur.push_back(keyPath[i]); ++i; }
                    }
                    if (i < keyPath.size() && keyPath[i] == ']') ++i;
                    if (!cur.empty()) { keys.push_back(cur); cur.clear(); }
