            } else if (c == '}' || c == ']') {
                out += '\n';
                indent -= 2;
                out.append(indent, ' ');
                out += c;
            } else if (c == ',') {
                out += c;
                out += '\n';
                out.append(indent, ' ');
            } else if (c == ':') {
