            }
            if (scalarRows.empty() || scalarRows.front().second) {
                if (knownNull) *knownNull = true;
                return "NULL";
            }
            if (knownNull) *knownNull = false;
            return scalarRows.front().first;
        }

        if (!projection->orderBy.empty()) {
            throw DbError("0A000", "virtual catalog subquery ordering is not supported");
        }
        auto rows = engine->query(dbname, subTname, {}, subSelectCols);
        const size_t skipped = std::min(projection->offset.value_or(0), rows.size());
        rows.erase(rows.begin(), rows.begin() + skipped);
        if (projection->limit && rows.size() > *projection->limit) rows.resize(*projection->limit);
        if (rows.size() > 1) {
            throw DbError("21000",
                "more than one row returned by a subquery used as an "
                "expression");
        }
        if (rows.empty()) {
            if (knownNull) *knownNull = true;
            return "NULL";
        }
        std::string firstRow = rows.front();
        // query() appends exactly one output-field delimiter. This scalar
        // path selects one column, so removing the first space would truncate
        // a legitimate text value (and trim() would lose boundary spaces).
        if (!firstRow.empty() && firstRow.back() == ' ') firstRow.pop_back();
        return firstRow;
    }
    // Array functions
    if ((expr.funcName == "array_dims" ||
         expr.funcName == "cardinality" ||
         expr.funcName == "array_position") &&
        !expr.funcArgs.empty()) {
        std::map<std::string, std::string> rowContext;
        const auto typeHints = buildTypeHints(tbl);
        std::set<std::string> nullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool valueIsNull = false;
            const std::string value = engine && !dbname.empty()
                ? engine->extractColumnValue(
                      rowBuffer, tbl, i, dbname, true, &valueIsNull)
                : StorageEngine::extractColumnValueStatic(
                      rowBuffer, tbl, i);
            rowContext[tbl.cols[i].dataName] = value;
            if (valueIsNull || (!engine && value.empty()))
                nullColumns.insert(tbl.cols[i].dataName);
        }
        std::string expressionSql = expr.funcName + "(";
        for (size_t i = 0; i < expr.funcArgs.size(); ++i) {
            if (i != 0) expressionSql += ",";
            expressionSql += expr.funcArgs[i];
        }
        expressionSql += ")";
        const auto evaluated = dbms::ExprHelper::evalStringWithNulls(
            expressionSql, rowContext, nullColumns, typeHints, dbname,
            expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
        if (!evaluated.ok) {
            throw std::runtime_error(
                evaluated.error.empty()
                    ? "failed to evaluate array inspection function"
                    : evaluated.error);
        }
        return publishScalarResult(evaluated);
    }
    if (expr.funcName == "array_get" && expr.funcArgs.size() >= 2) {
        std::string arr = getVal(expr.funcArgs[0]);
        try {
            int idx = std::stoi(getVal(expr.funcArgs[1]));
            if (idx <= 0) return "";
            std::vector<std::string> elems;
            if (arr.size() >= 2 && arr.front() == '[' && arr.back() == ']') {
                arr = arr.substr(1, arr.size() - 2);
            }
            size_t i = 0;
            while (i < arr.size()) {
                while (i < arr.size() && isspace(static_cast<unsigned char>(arr[i]))) ++i;
                if (i >= arr.size()) break;
                std::string elem;
                if (arr[i] == '\'' || arr[i] == '"') {
                    char q = arr[i++];
                    while (i < arr.size() && arr[i] != q) elem += arr[i++];
                    if (i < arr.size()) ++i;
                } else {
                    while (i < arr.size() && arr[i] != ',') elem += arr[i++];
                }
                elems.push_back(trim(elem));
                if (i < arr.size() && arr[i] == ',') ++i;
            }
            if (static_cast<size_t>(idx) > elems.size()) return "";
            return elems[idx - 1];
        } catch (...) { return ""; }
    }
    if (expr.funcName == "array_length" && !expr.funcArgs.empty()) {
        std::map<std::string, std::string> rowContext;
        const auto typeHints = buildTypeHints(tbl);
        std::set<std::string> nullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool valueIsNull = false;
            const std::string value = engine && !dbname.empty()
                ? engine->extractColumnValue(
                      rowBuffer, tbl, i, dbname, true, &valueIsNull)
                : StorageEngine::extractColumnValueStatic(
                      rowBuffer, tbl, i);
            rowContext[tbl.cols[i].dataName] = value;
            if (valueIsNull || (!engine && value.empty()))
                nullColumns.insert(tbl.cols[i].dataName);
        }
        std::string expressionSql = "array_length(";
        for (size_t i = 0; i < expr.funcArgs.size(); ++i) {
            if (i != 0) expressionSql += ",";
            expressionSql += expr.funcArgs[i];
        }
        expressionSql += ")";
        const auto evaluated = dbms::ExprHelper::evalStringWithNulls(
            expressionSql, rowContext, nullColumns, typeHints, dbname,
            expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
        if (!evaluated.ok) {
            throw std::runtime_error(
                evaluated.error.empty()
                    ? "failed to evaluate array length"
                    : evaluated.error);
        }
        return publishScalarResult(evaluated);
    }
    if (expr.funcName == "array_contains" && expr.funcArgs.size() >= 2) {
        std::string arr = getVal(expr.funcArgs[0]);
        std::string search = getVal(expr.funcArgs[1]);
        if (arr.size() >= 2 && arr.front() == '[' && arr.back() == ']') {
            arr = arr.substr(1, arr.size() - 2);
        }
        size_t i = 0;
        while (i < arr.size()) {
            while (i < arr.size() && isspace(static_cast<unsigned char>(arr[i]))) ++i;
            if (i >= arr.size()) break;
            std::string elem;
            if (arr[i] == '\'' || arr[i] == '"') {
                char q = arr[i++];
                while (i < arr.size() && arr[i] != q) elem += arr[i++];
                if (i < arr.size()) ++i;
            } else {
                while (i < arr.size() && arr[i] != ',') elem += arr[i++];
            }
            if (trim(elem) == search) return "1";
            if (i < arr.size() && arr[i] == ',') ++i;
        }
        return "0";
    }
    if (expr.funcName == "unnest" && !expr.funcArgs.empty()) {
        // Return raw array value; expansion happens in queryExpr
        return getVal(expr.funcArgs[0]);
    }
    if (expr.funcName == "pg_notify") {
        if (expr.funcArgs.size() != 2) {
            throw DbError("42883",
                          "function pg_notify requires exactly two arguments");
        }
        std::map<std::string, std::string> rowContext;
        std::map<std::string, std::string> typeHints;
        std::set<std::string> nullColumns;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool valueIsNull = false;
            const std::string value = engine && !dbname.empty()
                ? engine->extractColumnValue(
                      rowBuffer, tbl, i, dbname, true, &valueIsNull)
                : StorageEngine::extractColumnValueStatic(rowBuffer, tbl, i);
            rowContext[tbl.cols[i].dataName] = value;
            typeHints[tbl.cols[i].dataName] = tbl.cols[i].dataType;
            if (valueIsNull) nullColumns.insert(tbl.cols[i].dataName);
        }
        std::vector<ExprEvalResult> arguments;
        for (const auto& argument : expr.funcArgs) {
            auto evaluated = ExprHelper::evalStringWithNulls(
                argument, rowContext, nullColumns, typeHints, dbname,
                expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
            if (!evaluated.ok) {
                throw std::runtime_error(evaluated.error);
            }
            arguments.push_back(std::move(evaluated));
        }
        const std::string channel = arguments[0].isNull
            ? "" : arguments[0].value;
        const std::string payload = arguments[1].isNull
            ? "" : arguments[1].value;
        if (channel.empty()) {
            throw DbError("22023", "channel name cannot be empty");
        }
        if (channel.size() >= 64) {
            throw DbError("22023", "channel name too long");
        }
        Session* session = currentSession();
        if (!session) {
            throw DbError("XX000", "pg_notify has no active session");
        }
        if (!notificationManager().publish(
                session->pid, session->currentDB, channel, payload)) {
            throw DbError(
                "22023",
                "notification payload is too long or contains a zero byte");
        }
        return "";
    }
    if (expr.funcName == "pg_notification_queue_usage") {
        if (!expr.funcArgs.empty()) {
            throw DbError(
                "42883",
                "function pg_notification_queue_usage takes no arguments");
        }
        std::ostringstream value;
        value << std::setprecision(17)
              << notificationManager().queueUsage();
        return value.str();
    }
    // Legacy scalar projections still own argument SQL, not evaluated cells.
    // Bind the whole call through the ordinary namespace-aware resolver and
    // evaluate arguments against this actual typed row. A public-only lookup
    // plus getVal() loses search_path, arithmetic, casts and runtime NULLs.
    if (engine && !dbname.empty()) {
        std::map<std::string, std::string> values, types;
        std::set<std::string> nulls;
        for (size_t i = 0; i < tbl.len; ++i) {
            bool isNull = false;
            const auto& column = tbl.cols[i];
            values[column.dataName] = engine->extractColumnValue(
                rowBuffer, tbl, i, dbname, true, &isNull);
            types[column.dataName] = column.isArray
                ? ExprHelper::canonicalResultTypeName(column.dataType + "[]") : column.dataType;
            if (isNull) nulls.insert(column.dataName);
        }
        // SelectExpr dispatch names are already decoded canonical identifiers.
        // Quote that identity once; do not fold a mixed-case routine again.
        std::string call = "\"";
        for (char c : expr.funcName) { call += c; if (c == '"') call += '"'; }
        call += "\"(";
        for (size_t i = 0; i < expr.funcArgs.size(); ++i)
            call += (i ? "," : "") + expr.funcArgs[i];
        call += ')';
        const auto evaluated = ExprHelper::evalStringWithNulls(
            call, values, nulls, types, dbname, expr.sessionUser, engine, {}, (owningValue!=nullptr || owningDeclaration!=nullptr),nullptr,datumMetadata);
        if (!evaluated.ok) {
            const auto failure = plpgsqlScalarResult(evaluated);
            throw DbError(failure.sqlState, failure.message);
        }
        return publishScalarResult(evaluated);
    }
    // PG 42883: undefined function over table columns aborts the
    // statement (previously returned empty silently).
    {
        std::string sig;
        for (size_t ai = 0; ai < expr.funcArgs.size(); ++ai) {
            if (ai) sig += ", ";
            const std::string& an = expr.funcArgs[ai];
            bool isCol = false;
            std::string ct;
            for (size_t ci = 0; ci < tbl.len; ++ci)
                if (tbl.cols[ci].dataName == an) { isCol = true; ct = tbl.cols[ci].dataType; break; }
            if (isCol) {
                for (auto& ch : ct) ch = static_cast<char>(tolower(static_cast<unsigned char>(ch)));
                if (ct == "int" || ct == "int4" || ct == "int2" || ct == "int8" ||
                    ct == "integer" || ct == "bigint" || ct == "smallint") ct = "integer";
                else if (ct == "varchar" || ct == "character varying" || ct == "char" || ct == "text") ct = "text";
                sig += ct;
            } else if (an.size() >= 2 && an.front() == 39 && an.back() == 39) {
                sig += "text";
            } else if (!an.empty() && an.find_first_not_of("0123456789-+") == std::string::npos) {
                sig += "integer";
            } else {
                sig += "unknown";
            }
        }
        throw std::runtime_error(
            "function " + expr.funcName + "(" + sig + ") does not exist (SQLSTATE 42883)");
    }
    return "";
}

namespace {

struct AggregateExpressionState {
    std::unique_ptr<FunctionCallExpr> call;
    std::string name, argumentType, resultType;
    size_t slot = 0;
    bool star = false;
    int64_t count = 0;
    ExprValue value;
    std::set<std::string> distinctValues;
};

struct AggregateExpressionProjection {
    StmtPtr owner;
    SelectStmt* select = nullptr;
    bool hasAggregate = false;
    std::string source;
};

std::string aggregateExpressionName(const FunctionCallExpr* call) {
    if (!call || call->hasOver) return {};
    CatalogManager::QualifiedName name, schema;
    if (!CatalogManager::parseQualifiedName(call->funcName, name, true) || !name.schema.empty()) return {};
    if (!call->schema.empty() &&
        (!CatalogManager::parseQualifiedName(call->schema, schema, true) || schema.name != "pg_catalog")) return {};
    static const std::set<std::string> names = {
        "count", "sum", "avg", "min", "max", "bool_and", "bool_or", "every"
    };
    return names.count(name.name) ? name.name : std::string{};
}

bool aggregateUnknownLiteral(const Expr* expression) {
    const auto* literal = dynamic_cast<const LiteralExpr*>(expression);
    return literal && literal->typeName.empty() &&
        (SQLParser::toLower(literal->value) == "null" ||
         (literal->value.size() >= 2 && literal->value.front() == '\'' && literal->value.back() == '\''));
}

bool containsAggregateExpression(const Expr* expression) {
    if (!expression) return false;
    if (const auto* call = dynamic_cast<const FunctionCallExpr*>(expression)) {
        if (!aggregateExpressionName(call).empty()) return true;
        for (const auto& argument : call->args)
            if (containsAggregateExpression(argument.get())) return true;
        for (const auto& argument : call->namedArgs)
            if (containsAggregateExpression(argument.value.get())) return true;
    } else if (const auto* unary = dynamic_cast<const UnaryOpExpr*>(expression)) {
        return containsAggregateExpression(unary->operand.get());
    } else if (const auto* binary = dynamic_cast<const BinaryOpExpr*>(expression)) {
        return containsAggregateExpression(binary->left.get()) ||
               (binary->op != "::" && containsAggregateExpression(binary->right.get()));
    } else if (const auto* cast = dynamic_cast<const CastExpr*>(expression)) {
        return containsAggregateExpression(cast->operand.get());
    } else if (const auto* conditional = dynamic_cast<const CaseExpr*>(expression)) {
        if (containsAggregateExpression(conditional->switchExpr.get()) ||
            containsAggregateExpression(conditional->elseExpr.get())) return true;
        for (const auto& arm : conditional->whenClauses)
            if (containsAggregateExpression(arm.first.get()) || containsAggregateExpression(arm.second.get())) return true;
    } else if (const auto* array = dynamic_cast<const ArrayExpr*>(expression)) {
        for (const auto& value : array->elements)
            if (containsAggregateExpression(value.get())) return true;
    }
    return false;
}

void collectAggregateInputSlots(const Expr* expression, size_t inputCount,
                               std::set<size_t>& slots) {
    if (!expression) return;
    if (const auto* parameter = dynamic_cast<const ParameterExpr*>(expression)) {
        if (parameter->slot < inputCount) slots.insert(parameter->slot);
    } else if (const auto* call = dynamic_cast<const FunctionCallExpr*>(expression)) {
        for (const auto& argument : call->args) collectAggregateInputSlots(argument.get(), inputCount, slots);
        for (const auto& argument : call->namedArgs) collectAggregateInputSlots(argument.value.get(), inputCount, slots);
        collectAggregateInputSlots(call->filter.get(), inputCount, slots);
    } else if (const auto* unary = dynamic_cast<const UnaryOpExpr*>(expression)) {
        collectAggregateInputSlots(unary->operand.get(), inputCount, slots);
    } else if (const auto* binary = dynamic_cast<const BinaryOpExpr*>(expression)) {
        collectAggregateInputSlots(binary->left.get(), inputCount, slots);
        collectAggregateInputSlots(binary->right.get(), inputCount, slots);
    } else if (const auto* cast = dynamic_cast<const CastExpr*>(expression)) {
        collectAggregateInputSlots(cast->operand.get(), inputCount, slots);
    } else if (const auto* conditional = dynamic_cast<const CaseExpr*>(expression)) {
        collectAggregateInputSlots(conditional->switchExpr.get(), inputCount, slots);
        collectAggregateInputSlots(conditional->elseExpr.get(), inputCount, slots);
        for (const auto& arm : conditional->whenClauses) {
            collectAggregateInputSlots(arm.first.get(), inputCount, slots);
            collectAggregateInputSlots(arm.second.get(), inputCount, slots);
        }
    } else if (const auto* array = dynamic_cast<const ArrayExpr*>(expression)) {
        for (const auto& value : array->elements) collectAggregateInputSlots(value.get(), inputCount, slots);
    }
}

std::string projectionExpressionSql(const StorageEngine::SelectExpr& expression) {
    if (!expression.isScalar) {
        if (expression.colName.find('(') != std::string::npos) return expression.colName;
        std::string quoted = "\"";
        for (char ch : expression.colName) { quoted += ch; if (ch == '"') quoted += ch; }
        return quoted + '"';
    }
    if (expression.funcName == "arith") {
        std::string sql;
        for (const auto& argument : expression.funcArgs) { if (!sql.empty()) sql += ' '; sql += argument; }
        return sql;
    }
    if ((expression.funcName == "expreval" || expression.funcName == "literal") && !expression.funcArgs.empty())
        return expression.funcArgs.front();
    if (expression.funcName == "cast" && expression.funcArgs.size() == 2)
        return "CAST(" + expression.funcArgs[0] + " AS " + expression.funcArgs[1] + ")";
    if (expression.funcName == "extract" && expression.funcArgs.size() == 1)
        return expression.funcArgs.front();
    if(expression.funcArgs.empty() && sql_value_detail::kind(expression.funcName)!=sql_value_detail::Kind::None)
        return expression.funcName; // legacy projection's actual keyword role
    std::string sql = expression.funcName + '(';
    for (const auto& argument : expression.funcArgs) { if (sql.back() != '(') sql += ','; sql += argument; }
    return sql + ')';
}

ExprValue evaluateAggregateBinary(ExprEvaluator& evaluator, const std::string& op,
                                 const ExprValue& left, const ExprValue& right) {
    BinaryOpExpr expression;
    expression.op = op;
    auto first = std::make_unique<ParameterExpr>(); first->slot = 0; first->declaredType = left.typeName;
    auto second = std::make_unique<ParameterExpr>(); second->slot = 1; second->declaredType = right.typeName;
    first->origin = second->origin = ParameterOrigin::RuntimeCell;
    expression.left = std::move(first); expression.right = std::move(second);
    RowContext context;
    context.setParameters({left, right});
    return evaluator.eval(&expression, context);
}

ExprValue coerceAggregateValue(ExprEvaluator& evaluator, const ExprValue& value, const std::string& type) {
    CastExpr expression;
    expression.typeName = type;
    auto parameter = std::make_unique<ParameterExpr>();
    parameter->declaredType = value.typeName;
    parameter->origin = ParameterOrigin::RuntimeCell;
    expression.operand = std::move(parameter);
    RowContext context;
    context.setParameters({value});
    return evaluator.eval(&expression, context);
}

// Scalar AST roots retain aggregate result cells. Input datum slots and
// aggregate slots are disjoint, and carry declared types independently of NULL.
// Bind a genuine input-expression root before lowering its columns to datum
// slots. Its physical catalog OIDs and copied operator/CASE bindings must not
// be rediscovered from a rendered type name or from an evaluated label.
void bindAggregateInputExpression(ExprPtr& expression,
    const std::string& source, const std::string& relationSql,
    StorageEngine* engine, const std::string& database) {
    if (!expression || expression->sourceBegin == std::string::npos ||
        expression->sourceBegin > expression->sourceEnd || expression->sourceEnd > source.size())
        throw DbError("XX000", "aggregate input has no original source provenance");
    auto prepared = engine->prepareBoundQuery(database,
        "SELECT " + source.substr(expression->sourceBegin,
            expression->sourceEnd - expression->sourceBegin) + " FROM " + relationSql);
    auto* select = dynamic_cast<SelectStmt*>(prepared.ast.get());
    if (!select || select->selectList.size() != 1 || !select->selectList.front().expr)
        throw DbError("XX000", "aggregate input has no bound expression root");
    expression = std::move(select->selectList.front().expr);
}

void prepareAggregateExpression(ExprPtr& expression, bool input,
    const TableSchema& table, std::vector<AggregateExpressionState>& states,
    ExprEvaluator& evaluator, StorageEngine* engine, const std::string& database,
    const std::string& source, const std::string& relationSql) {
    if (!expression) return;
    if (const auto* parameter = dynamic_cast<const ParameterExpr*>(expression.get()))
        throw DbError("42P02", "there is no parameter $" + std::to_string(parameter->slot + 1));
    if (const auto* column = dynamic_cast<const ColumnRefExpr*>(expression.get())) {
        size_t index = table.len;
        for (size_t i = 0; i < table.len; ++i) if (table.cols[i].dataName == column->column) { index = i; break; }
        if (index == table.len) {
            if (column->schema.empty() && column->table.empty() &&
                (column->column == "current_user" || column->column == "session_user")) return;
            throw DbError("42703", "column \"" + column->column + "\" does not exist");
        }
        if (!input) throw DbError("42803", "column must appear in GROUP BY or be used in an aggregate function");
        auto parameter = std::make_unique<ParameterExpr>();
        parameter->slot = index;
        parameter->origin = ParameterOrigin::RuntimeCell;
        parameter->declaredType = ExprHelper::canonicalResultTypeName(
            table.cols[index].dataType + (table.cols[index].isArray ? "[]" : ""));
        expression = std::move(parameter);
    } else if (auto* call = dynamic_cast<FunctionCallExpr*>(expression.get())) {
        const std::string aggregate = aggregateExpressionName(call);
        if (!aggregate.empty()) {
            if (input) throw DbError("42803", "aggregate function calls cannot be nested");
            if (call->args.size() != 1 || !call->namedArgs.empty())
                throw DbError("42883", "aggregate function does not exist: " + aggregate);
            const auto* literal = dynamic_cast<const LiteralExpr*>(call->args.front().get());
            const bool star = literal && literal->value == "*";
            if (star && aggregate != "count") throw DbError("42883", "aggregate requires a value argument");
            if (star && call->distinct) throw DbError("42601", "DISTINCT * is not supported");
            if ((aggregate == "sum" || aggregate == "avg") && aggregateUnknownLiteral(call->args.front().get()))
                throw DbError("42725", "aggregate function is not unique for type unknown");
            // Nested reductions keep their existing aggregate-analysis error
            // owner; whole scalar argument binding never resolves SUM/BOOL
            // overloads or invents their result descriptor.
            if (!star && !containsAggregateExpression(call->args.front().get()))
                bindAggregateInputExpression(call->args.front(), source, relationSql, engine, database);
            if (call->filter && !containsAggregateExpression(call->filter.get()))
                bindAggregateInputExpression(call->filter, source, relationSql, engine, database);
            if (!star) prepareAggregateExpression(call->args.front(), true, table, states, evaluator, engine, database, source, relationSql);
            if (call->filter) prepareAggregateExpression(call->filter, true, table, states, evaluator, engine, database, source, relationSql);
            if (call->filter) {
                if (aggregateUnknownLiteral(call->filter.get())) {
                    auto coerced = std::make_unique<CastExpr>();
                    coerced->typeName = "boolean";
                    coerced->operand = std::move(call->filter);
                    call->filter = std::move(coerced);
                }
                const auto filterType = ExprHelper::inferParsedResultType(call->filter.get(), {}, database, engine);
                if (filterType != "boolean" && filterType != "unknown")
                    throw DbError("42804", "argument of FILTER must be type boolean");
            }
            AggregateExpressionState state;
            state.name = aggregate; state.star = star;
            state.argumentType = star ? "" : ExprHelper::inferParsedResultType(call->args.front().get(), {}, database, engine);
            state.resultType = ExprHelper::inferParsedResultType(call, {}, database, engine);
            if ((aggregate == "sum" || aggregate == "avg") &&
                state.argumentType != "smallint" && state.argumentType != "integer" &&
                state.argumentType != "bigint" && state.argumentType != "numeric" &&
                state.argumentType != "real" && state.argumentType != "double precision" &&
                (aggregate != "sum" || state.argumentType != "money") && state.argumentType != "interval")
                throw DbError("42883", "aggregate function does not exist for type " + state.argumentType);
            if ((aggregate == "bool_and" || aggregate == "bool_or" || aggregate == "every") && state.argumentType != "boolean")
                throw DbError("42883", "boolean aggregate requires a boolean argument");
            state.slot = table.len + states.size();
            state.value = ExprValue(state.resultType, "", true);
            auto result = std::make_unique<ParameterExpr>(); result->slot = state.slot; result->declaredType = state.resultType;
            result->origin = ParameterOrigin::RuntimeCell;
            state.call.reset(static_cast<FunctionCallExpr*>(expression.release()));
            expression = std::move(result);
            if (!star) evaluator.bindScalarFunctions(state.call->args.front().get(), engine);
            if (state.call->filter) evaluator.bindScalarFunctions(state.call->filter.get(), engine);
            states.push_back(std::move(state));
        } else {
            if (call->schema.empty() && SQLParser::toLower(call->funcName) == "extract" && !call->args.empty()) {
                const auto* field = dynamic_cast<const ColumnRefExpr*>(call->args.front().get());
                if (field && field->table.empty() && field->schema.empty()) {
                    auto literal = std::make_unique<LiteralExpr>(); literal->typeName = "text";
                    literal->value = "'" + field->column + "'";
                    call->args.front() = std::move(literal);
                }
            }
            for (auto& argument : call->args) prepareAggregateExpression(argument, input, table, states, evaluator, engine, database, source, relationSql);
            for (auto& argument : call->namedArgs) prepareAggregateExpression(argument.value, input, table, states, evaluator, engine, database, source, relationSql);
        }
    } else if (auto* unary = dynamic_cast<UnaryOpExpr*>(expression.get())) {
        prepareAggregateExpression(unary->operand, input, table, states, evaluator, engine, database, source, relationSql);
    } else if (auto* binary = dynamic_cast<BinaryOpExpr*>(expression.get())) {
        prepareAggregateExpression(binary->left, input, table, states, evaluator, engine, database, source, relationSql);
        if (binary->op != "::" && SQLParser::toLower(binary->op) != "collate")
            prepareAggregateExpression(binary->right, input, table, states, evaluator, engine, database, source, relationSql);
    } else if (auto* cast = dynamic_cast<CastExpr*>(expression.get())) {
        prepareAggregateExpression(cast->operand, input, table, states, evaluator, engine, database, source, relationSql);
    } else if (auto* conditional = dynamic_cast<CaseExpr*>(expression.get())) {
        prepareAggregateExpression(conditional->switchExpr, input, table, states, evaluator, engine, database, source, relationSql);
        for (auto& arm : conditional->whenClauses) {
            prepareAggregateExpression(arm.first, input, table, states, evaluator, engine, database, source, relationSql);
            prepareAggregateExpression(arm.second, input, table, states, evaluator, engine, database, source, relationSql);
        }
        prepareAggregateExpression(conditional->elseExpr, input, table, states, evaluator, engine, database, source, relationSql);
    } else if (auto* array = dynamic_cast<ArrayExpr*>(expression.get())) {
        for (auto& value : array->elements) prepareAggregateExpression(value, input, table, states, evaluator, engine, database, source, relationSql);
    }
}

void advanceAggregateExpression(AggregateExpressionState& state,
                               ExprEvaluator& evaluator, const RowContext& context) {
    if (state.call->filter) {
        const auto filtered = evaluator.eval(state.call->filter.get(), context);
        if (!filtered.isNull && ExprHelper::canonicalResultTypeName(filtered.typeName) != "boolean")
            throw DbError("42804", "argument of FILTER must be type boolean");
        if (filtered.isNull || !filtered.asBool()) return;
    }
    ExprValue input;
    if (!state.star) {
        input = evaluator.eval(state.call->args.front().get(), context);
        if (input.isNull) return;
        if (state.call->distinct) {
            Column column; column.dataType = state.argumentType;
            if (column.dataType == "real") column.dataType = "float";
            if (column.dataType == "double precision") column.dataType = "double";
            if (!state.distinctValues.insert(canonicalColumnKeyValue(column, input.value)).second) return;
        }
    }
    if (state.count == std::numeric_limits<int64_t>::max()) throw DbError("22003", "aggregate count out of range");
    ++state.count;
    if (state.name == "count") return;
    if (state.name == "sum" || state.name == "avg") {
        const auto converted = coerceAggregateValue(evaluator, input, state.resultType);
        state.value = state.value.isNull ? converted : evaluateAggregateBinary(evaluator, "+", state.value, converted);
    } else if (state.name == "min" || state.name == "max") {
        if (state.value.isNull || evaluateAggregateBinary(evaluator,
                state.name == "min" ? "<" : ">", input, state.value).asBool()) state.value = input;
    } else {
        state.value = state.value.isNull ? input : evaluateAggregateBinary(evaluator,
            state.name == "bool_or" ? "OR" : "AND", state.value, input);
    }
}

ExprValue finishAggregateExpression(AggregateExpressionState& state, ExprEvaluator& evaluator) {
    if (state.name == "count") return ExprValue("bigint", std::to_string(state.count), false);
    if (state.name == "avg" && state.count)
        return evaluateAggregateBinary(evaluator, "/", state.value,
            coerceAggregateValue(evaluator, ExprValue("bigint", std::to_string(state.count)), state.resultType));
    return state.value;
}

} // namespace

StorageEngine::QueryExprExecutionOptions StorageEngine::defaultQueryExprOptions() {
    return QueryExprExecutionOptions{};
}

std::vector<std::string> StorageEngine::queryExpr(const std::string& dbname,
                                                   const std::string& tablename,
                                                   const std::vector<std::string>& conditions,
                                                   const std::vector<SelectExpr>& exprs,
                                                   const std::vector<OrderBySpec>& orderBy,
                                                   const QueryExprExecutionOptions& options) {
    return queryExpr(dbname, tablename, conditions, exprs, orderBy,
                     nullptr, nullptr, nullptr, options);
}

std::vector<std::string> StorageEngine::queryExpr(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    const std::vector<SelectExpr>& exprs,
    const std::vector<OrderBySpec>& orderBy,
    std::vector<std::vector<std::string>>* structuredRows,
    std::vector<std::vector<bool>>* structuredNulls,
    std::vector<int64_t>* structuredRowIds,
    const QueryExprExecutionOptions& options) {
    const auto status = ensureDatabaseTransactionOwnership(dbname);
    if (status != DBStatus::OK)
        throw DbError(sqlstateForDBStatus(status), "could not acquire database transaction ownership");
    std::vector<std::string> result;
    if (structuredRows) structuredRows->clear();
    if (structuredNulls) structuredNulls->clear();
    if (structuredRowIds) structuredRowIds->clear();
    if (options.owningRows) options.owningRows->clear();
    if (options.owningRowsComplete) *options.owningRowsComplete=true;
    std::vector<bool> declarationObserved;
    if(options.owningDeclarations) {
        options.owningDeclarations->assign(exprs.size(),{});
        declarationObserved.assign(exprs.size(),false);
    }
    const auto publishDeclaration=[&](size_t column,const DatumTypePtr& declaration) {
        if(!options.owningDeclarations || column>=exprs.size())return;
        auto& previous=options.owningDeclarations->at(column);
        if(!declarationObserved[column]) {
            previous=declaration;declarationObserved[column]=true;
        } else if(!previous || !declaration || previous->actualOid!=declaration->actualOid ||
                  previous->codecOid!=declaration->codecOid || previous->codecSize!=declaration->codecSize ||
                  previous->effectiveTypeMod!=declaration->effectiveTypeMod || previous->kind!=declaration->kind ||
                  previous->enumType!=declaration->enumType) {
            // A changing/missing original declaration is unavailable. Never
            // select a new common type or throw a new user-expression error.
            previous.reset();
        }
    };
    const auto publishOwningRow=[&](std::vector<std::optional<ExprValue>> values) {
        if (!options.owningRows) return;
        std::vector<ExprValue> row;row.reserve(values.size());
        for (auto& value:values) {
            if (value) row.push_back(std::move(*value));
            else {
                if (options.owningRowsComplete) *options.owningRowsComplete=false;
                row.emplace_back(); // explicitly unavailable, never rendered text
            }
        }
        options.owningRows->push_back(std::move(row));
    };
    if (transactionContext().inTransaction && dbname == transactionContext().txnDB) {
        if ((transactionContext().txnIsolationLevel == IsolationLevel::READ_COMMITTED ||
             transactionContext().txnIsolationLevel == IsolationLevel::READ_UNCOMMITTED) &&
            !transactionContext().readView.commandIdVisibility) {
            refreshReadView();
        } else {
            ensureTransactionSnapshot();
        }
        transactionContext().hasRead = true;
        transactionContext().querySnapshotUsed = true;
    }
    if (!tableExists(dbname, tablename)) return result;
    if (!lockManager_.lockShared(tablename)) return result;
    ResourceUnlockGuard tableLockGuard(lockManager_, tablename);

    TableSchema tbl = getTableSchema(dbname, tablename);
    DatumMetadataContextPtr outputDatumMetadata;
    const bool storedReferenceColumns=std::any_of(tbl.cols,tbl.cols+tbl.len,
        [](const Column& column){return column.generatedKind!='v' &&
            stored_regtype_detail::columnType(column.dataType);});
    if(options.owningRows || options.owningDeclarations || storedReferenceColumns)
        outputDatumMetadata=prepareDatumMetadataContext(dbname,tablename);
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    std::vector<AggregateExpressionProjection> aggregateProjections;
    bool aggregateProjection = false;
    for (const auto& expression : exprs) {
        SQLParser parser;
        const std::string projectionSql = "SELECT " + projectionExpressionSql(expression);
        auto parsed = parser.parseForBinding(projectionSql);
        AggregateExpressionProjection projection;
        projection.source = projectionSql;
        if (parsed.success) projection.select = dynamic_cast<SelectStmt*>(parsed.stmt.get());
        if (projection.select && projection.select->selectList.size() == 1 && !projection.select->fromClause) {
            if (containsBetweenExpression(projection.select->selectList.front().expr.get()))
                ExprHelper::prepareArrayTypes(projection.select->selectList.front().expr.get(),
                    buildTypeHints(tbl), dbname, this);
            projection.hasAggregate = containsAggregateExpression(projection.select->selectList.front().expr.get());
            aggregateProjection = aggregateProjection || projection.hasAggregate;
        } else projection.select = nullptr;
        projection.owner = std::move(parsed.stmt);
        aggregateProjections.push_back(std::move(projection));
    }
    ExprEvaluator aggregateEvaluator;
    aggregateEvaluator.setCurrentDB(dbname);
    const std::string aggregateUser = currentSession() ? currentSession()->username : "";
    aggregateEvaluator.registerFunction("current_user", [aggregateUser](const std::vector<ExprValue>&) {
        return ExprValue("name", aggregateUser, aggregateUser.empty());
    }, 's');
    aggregateEvaluator.registerFunction("session_user", [aggregateUser](const std::vector<ExprValue>&) {
        return ExprValue("name", aggregateUser, aggregateUser.empty());
    }, 's');
    std::vector<AggregateExpressionState> aggregateStates;
    std::set<size_t> aggregateInputSlots;
    if (aggregateProjection) {
        const auto quoted = [](const std::string& name) {
            std::string result = "\"";
            for (char ch : name) { result += ch; if (ch == '"') result += ch; }
            return result + '"';
        };
        const auto logical = CatalogService::logicalName(tablename);
        const std::string relationSql = quoted(logical.schema.empty() ? "public" : logical.schema) +
            "." + quoted(logical.name) + (options.aggregateSourceAlias.empty() ? "" :
                " AS " + quoted(options.aggregateSourceAlias));
        for (auto& projection : aggregateProjections) {
            if (!projection.select) throw DbError("42601", "invalid aggregate projection");
            auto& root = projection.select->selectList.front().expr;
            prepareAggregateExpression(root, false, tbl, aggregateStates, aggregateEvaluator, this, dbname,
                projection.source, relationSql);
            aggregateEvaluator.bindScalarFunctions(root.get(), this);
            ExprEvaluator::analyzeExplicitResultCollation(root.get());
        }
        for (const auto& state : aggregateStates)
            collectAggregateInputSlots(state.call.get(), tbl.len, aggregateInputSlots);
    }
    auto conds = prepareStoredUnknownBitScalarInputs(tbl, parseConditions(conditions));
    // Receiver caps and OR alternatives constrain execution demand, not
    // schema-owned signature/input admission. Validate before any index or
    // streaming scan, even when zero rows will be requested.
    validateStoredPatternConditions(tbl,conds);
    std::vector<std::vector<Condition>> preparedAlternatives;
    for(const auto& branch:options.conditionAlternatives) {
        preparedAlternatives.push_back(prepareStoredUnknownBitScalarInputs(tbl,parseConditions(branch)));
        validateStoredPatternConditions(tbl,preparedAlternatives.back());
    }
    const auto admitTyped=[&](const std::vector<Condition>& branch) {
        for(const auto& condition:branch) if(condition.op=="typedexpr") {
            SQLParser parser;auto parsed=parser.parseForBinding("SELECT "+condition.value);
            auto* select=parsed.success?dynamic_cast<SelectStmt*>(parsed.stmt.get()):nullptr;
            if(!select || select->selectList.size()!=1 || select->fromClause)
                throw DbError("42601","invalid typed predicate");
            validateNullWhereColumns(select->selectList.front().expr.get(),tbl);
            ExprHelper::prepareArrayTypes(select->selectList.front().expr.get(),buildTypeHints(tbl),dbname,this);
        }
    };
    admitTyped(conds);for(const auto& branch:preparedAlternatives) admitTyped(branch);
    const bool noMatches=options.conditionAlternatives.empty()?nullScalarBranch(conds):
        std::all_of(preparedAlternatives.begin(),preparedAlternatives.end(),nullScalarBranch);
    preparedAlternatives.erase(std::remove_if(preparedAlternatives.begin(),preparedAlternatives.end(),nullScalarBranch),
        preparedAlternatives.end());
    if (options.maxProjectionRows && *options.maxProjectionRows == 0) return result;
    // With no blocking sort, qualification and projection belong to the
    // same demand-driven row receiver. Do not first evaluate WHERE on later
    // rows: those expressions can themselves be volatile or fail.
    const bool streamingQualification = !aggregateProjection && options.maxProjectionRows &&
        orderBy.empty() && !conds.empty();
    std::vector<std::vector<Condition>> qualificationBranches;
    if (streamingQualification) {
        if (options.conditionAlternatives.empty()) qualificationBranches.push_back(conds);
        else qualificationBranches = preparedAlternatives;
    }
    std::vector<std::pair<int64_t, std::string>> matchRows;
    bool scanFailed = false;
    bool indexReadFailed = false;
    if (noMatches) {
        // Keep empty aggregate input semantics; do not evaluate a WHERE or
        // target function merely to discover that this branch cannot be true.
    } else if (conds.empty() || streamingQualification) {
        if (!forEachRow(dbname, tablename, [&](uint32_t pid, uint16_t sid, const char* data, size_t len) {
            matchRows.emplace_back(encodeRid(pid, sid), std::string(data, len));
        })) scanFailed = true;
    } else {
        std::vector<int64_t> ids;
        if (options.conditionAlternatives.empty()) {
            const auto filtered = filterRows(dbname, tablename, conds, nullptr,
                                            &scanFailed, &indexReadFailed);
            ids.assign(filtered.begin(), filtered.end());
        } else {
            std::set<int64_t> seen;
            for (const auto& branchConditions : preparedAlternatives) {
                auto branchIds = filterRows(dbname, tablename, branchConditions,
                    nullptr, &scanFailed, &indexReadFailed);
                if (scanFailed) break;
                for (int64_t rid : branchIds)
                    if (seen.insert(rid).second) ids.push_back(rid);
            }
            ids.assign(seen.begin(), seen.end());
        }
        for (int64_t rid : ids) {
            std::string row;
            if (readRowByRid(pa, rid, row, tbl)) {
                matchRows.emplace_back(rid, std::move(row));
            }
        }
    }
    if (scanFailed) {
        if (indexReadFailed) {
            throw DbError("XX001", "B-tree index read failed for relation \"" +
                tablename + "\"");
        }
        return result;
    }

    if (aggregateProjection) {
        // Capture nullable typed input cells before executing any aggregate
        // argument. Volatile arguments must not change a later cell's bitmap.
        std::vector<std::vector<ExprValue>> inputs;
        inputs.reserve(matchRows.size());
        for (const auto& matched : matchRows) {
            NullRowBinding binding(this, dbname, tablename, matched.first, tbl.len);
            std::vector<ExprValue> cells(tbl.len);
            for (size_t column : aggregateInputSlots) {
                bool isNull = false;
                const auto value = extractColumnValue(matched.second, tbl, column, dbname, true, &isNull);
                cells[column] = ExprValue(ExprHelper::canonicalResultTypeName(
                    tbl.cols[column].dataType + (tbl.cols[column].isArray ? "[]" : "")), value, isNull);
            }
            inputs.push_back(std::move(cells));
        }
        for (auto& cells : inputs) {
            RowContext context;
            context.setParameters(std::move(cells));
            context.set("current_user", ExprValue("name", aggregateUser, aggregateUser.empty()));
            context.set("session_user", ExprValue("name", aggregateUser, aggregateUser.empty()));
            for (auto& state : aggregateStates) advanceAggregateExpression(state, aggregateEvaluator, context);
        }
        std::vector<ExprValue> aggregateCells(tbl.len);
        for (auto& state : aggregateStates) aggregateCells.push_back(finishAggregateExpression(state, aggregateEvaluator));
        RowContext context;
        context.setParameters(std::move(aggregateCells));
        context.set("current_user", ExprValue("name", aggregateUser, aggregateUser.empty()));
        context.set("session_user", ExprValue("name", aggregateUser, aggregateUser.empty()));
        std::string display;
        std::vector<std::string> cells;
        std::vector<bool> nulls;
        std::vector<std::optional<ExprValue>> owning;
        if (options.owningRows) owning.reserve(aggregateProjections.size());
        for (const auto& projection : aggregateProjections) {
            const auto value = aggregateEvaluator.eval(projection.select->selectList.front().expr.get(), context);
            display += (value.isNull ? "NULL" : value.value) + ' ';
            cells.push_back(value.isNull ? std::string{} : value.value);
            nulls.push_back(value.isNull);
            if (options.owningRows) owning.push_back(value);
        }
        result.push_back(std::move(display));
        if (options.owningRows) publishOwningRow(std::move(owning));
        if (structuredRows) structuredRows->push_back(std::move(cells));
        if (structuredNulls) structuredNulls->push_back(std::move(nulls));
        if (structuredRowIds) structuredRowIds->push_back(-1);
        return result;
    }

    // Keep a permutation, not RID identity: partitioned inputs can reuse a
    // page/slot RID. It also lets below-Sort projections retain input order.
    std::vector<size_t> sortedInputPositions;
    // ORDER BY (multi-column)
    if (!orderBy.empty()) {
        struct SortKey {
            size_t inputPosition;
            std::vector<
                std::tuple<std::string, int64_t, double, Date, Numeric>> vals;
            std::vector<bool> isNulls;
        };
        std::vector<SortKey> keys;
        for (size_t input = 0; input < matchRows.size(); ++input) {
            auto& mr = matchRows[input];
            SortKey k{input, {}, {}};
            NullRowBinding nbS(this, dbname, tbl.tablename, mr.first, tbl.len);
            for (const auto& spec : orderBy) {
                size_t sortIdx = tbl.len;
                for (size_t i = 0; i < tbl.len; ++i) {
                    if (tbl.cols[i].dataName == spec.colName) { sortIdx = i; break; }
                }
                if (sortIdx < tbl.len) {
                    std::string val = extractColumnValue(
                        mr.second, tbl, sortIdx, dbname, true);
                    const Column& scol = tbl.cols[sortIdx];
                    k.isNulls.push_back(val.empty());
                    if (scol.dataType == "numeric") {
                        k.vals.emplace_back(
                            "", 0, 0.0, Date{},
                            val.empty() ? Numeric{} : Numeric(val));
                    } else if (scol.dataType == "char" ||
                               scol.isVariableLength) {
                        k.vals.emplace_back(val, 0, 0.0, Date{}, Numeric{});
                    } else if (scol.dataType == "date") {
                        k.vals.emplace_back(
                            "", 0, 0.0,
                            val.empty() ? Date{} : Date(val.c_str()),
                            Numeric{});
                    } else if (scol.dataType == "timestamp" ||
                               scol.dataType == "timestamptz" ||
                               scol.dataType == "datetime") {
                        k.vals.emplace_back(
                            "", val.empty() ? 0 :
                                (scol.storageCodec == Column::StorageCodec::TemporalMicros
                                    ? temporalColumnMicros(scol, val).value_or(0)
                                    : parseTimestampToSeconds(val)),
                            0.0, Date{}, Numeric{});
                    } else if (scol.dataType == "time") {
                        k.vals.emplace_back(
                            "", val.empty() ? 0 :
                                (scol.storageCodec == Column::StorageCodec::TemporalMicros
                                    ? temporalColumnMicros(scol, val).value_or(0)
                                    : parseTimeToSeconds(val)),
                            0.0, Date{}, Numeric{});
                    } else if (scol.dataType == "money") {
                        int64_t minorUnits = 0;
                        if (!val.empty())
                            (void)parseMoneyLiteral(val, minorUnits);
                        k.vals.emplace_back(
                            "", minorUnits, 0.0, Date{}, Numeric{});
                    } else if (scol.dataType == "float") {
                        float parsed = 0.0f;
                        if (!val.empty()) (void)parseFloatLiteral(val, parsed);
                        k.vals.emplace_back(
                            "", 0, static_cast<double>(parsed), Date{},
                            Numeric{});
                    } else if (scol.dataType == "double" ||
                               scol.dataType == "decimal") {
                        double parsed = 0.0;
                        if (!val.empty()) (void)parseDoubleLiteral(val, parsed);
                        k.vals.emplace_back(
                            "", 0, parsed, Date{}, Numeric{});
                    } else {
                        k.vals.emplace_back(
                            "", val.empty() ? 0 : parseInt(val), 0.0,
                            Date{}, Numeric{});
                    }
                } else {
                    k.isNulls.push_back(true);
                    k.vals.emplace_back(
                        "", 0, 0.0, Date{}, Numeric{});
                }
            }
            keys.push_back(std::move(k));
        }
        std::sort(keys.begin(), keys.end(), [&](const SortKey& a, const SortKey& b) {
            for (size_t i = 0; i < orderBy.size(); ++i) {
                const auto& spec = orderBy[i];
                size_t sortIdx = tbl.len;
                for (size_t j = 0; j < tbl.len; ++j) {
                    if (tbl.cols[j].dataName == spec.colName) { sortIdx = j; break; }
                }
                if (sortIdx >= tbl.len) continue;
                bool aNull = a.isNulls[i];
                bool bNull = b.isNulls[i];
                if (aNull && bNull) continue;
                if (aNull) return spec.nullsFirst;
                if (bNull) return !spec.nullsFirst;
                const Column& scol = tbl.cols[sortIdx];
                bool less = false, greater = false;
                if (scol.dataType == "numeric") {
                    less = std::get<4>(a.vals[i]) < std::get<4>(b.vals[i]);
                    greater = std::get<4>(b.vals[i]) < std::get<4>(a.vals[i]);
                } else if (scol.dataType == "char" ||
                           scol.isVariableLength) {
                    less = std::get<0>(a.vals[i]) < std::get<0>(b.vals[i]);
                    greater = std::get<0>(b.vals[i]) < std::get<0>(a.vals[i]);
                } else if (scol.dataType == "date") {
                    less = std::get<3>(a.vals[i]) < std::get<3>(b.vals[i]);
                    greater = std::get<3>(b.vals[i]) < std::get<3>(a.vals[i]);
                } else if (scol.dataType == "float" ||
                           scol.dataType == "double" ||
                           scol.dataType == "decimal") {
                    const int comparison = compareFloatingValues(
                        std::get<2>(a.vals[i]), std::get<2>(b.vals[i]));
                    less = comparison < 0;
                    greater = comparison > 0;
                } else {
                    less = std::get<1>(a.vals[i]) < std::get<1>(b.vals[i]);
                    greater = std::get<1>(b.vals[i]) < std::get<1>(a.vals[i]);
                }
                if (less) return spec.ascending;
                if (greater) return !spec.ascending;
            }
            return false;
        });
        std::vector<std::pair<int64_t, std::string>> sorted;
        sorted.reserve(matchRows.size());
        sortedInputPositions.reserve(matchRows.size());
        for (const auto& k : keys) {
            sortedInputPositions.push_back(k.inputPosition);
            sorted.push_back(std::move(matchRows[k.inputPosition]));
        }
        matchRows = std::move(sorted);
    }

    // Detect unnest in SELECT expressions
    bool hasUnnest = false;
    size_t unnestIdx = 0;
    for (size_t i = 0; i < exprs.size(); ++i) {
        if (exprs[i].isScalar && exprs[i].funcName == "unnest") {
            hasUnnest = true;
            unnestIdx = i;
            break;
        }
    }

    // Aggregate-arithmetic projection ("count(*) - count(v)"):
    // every operand is a table-level aggregate, so the result is a
    // single row regardless of the table's row count (PG semantics).
    bool allAggArith = !exprs.empty();
    {
        static const char* afns3[] = {"count", "sum", "avg", "min", "max",
                                    "bool_and", "bool_or", "every"};
        for (const auto& ex : exprs) {
            bool thisAgg = false;
            if (ex.isScalar && ex.funcName == "arith") {
                for (const auto& a : ex.funcArgs) {
                    for (const char* fn : afns3) {
                        size_t fl = strlen(fn);
                        if (a.size() > fl + 1 && a.compare(0, fl, fn) == 0 && a[fl] == '(' &&
                            a.back() == ')') { thisAgg = true; break; }
                    }
                    if (thisAgg) break;
                }
            }
            if (!thisAgg) { allAggArith = false; break; }
        }
    }
    if (allAggArith && matchRows.size() > 1)
        matchRows.resize(1);
    const auto evaluateCell = [&](const SelectExpr& expr,
                                  const std::pair<int64_t, std::string>& mr,
                                  std::optional<ExprValue>* owningCell = nullptr,
                                  size_t outputColumn = std::numeric_limits<size_t>::max()) {
        if (owningCell) owningCell->reset();
        DatumTypePtr declaration;
        std::string val;
        bool valueIsNull = false;
        if (expr.isScalar) {
            std::optional<bool> knownNull;
            val = applyScalarFunc(expr, mr.second, tbl, this, dbname, &knownNull,owningCell,
                outputDatumMetadata.get(),options.owningDeclarations?&declaration:nullptr);
            if (knownNull.has_value()) valueIsNull = *knownNull;
            if (!knownNull.has_value() && val == "NULL") {
                std::map<std::string, std::string> rowContext;
                const auto typeHints = buildTypeHints(tbl);
                std::set<std::string> nullColumns;
                for (size_t i = 0; i < tbl.len; ++i) {
                    bool columnIsNull = false;
                    const std::string value = extractColumnValue(
                        mr.second, tbl, i, dbname, true, &columnIsNull);
                    rowContext[tbl.cols[i].dataName] = value;
                    if (columnIsNull) nullColumns.insert(tbl.cols[i].dataName);
                }
                std::string expression;
                if (expr.funcName == "expreval") {
                    if (!expr.funcArgs.empty()) expression = expr.funcArgs.front();
                } else if (expr.funcName == "arith") {
                    for (size_t i = 0; i < expr.funcArgs.size(); ++i) {
                        if (i) expression += ' ';
                        expression += expr.funcArgs[i];
                    }
                } else if (expr.funcName == "cast" && expr.funcArgs.size() >= 2) {
                    expression = "cast(" + expr.funcArgs[0] + " as " + expr.funcArgs[1] + ")";
                } else if(expr.funcArgs.empty() && sql_value_detail::kind(expr.funcName)!=sql_value_detail::Kind::None) {
                    expression=expr.funcName;
                } else if (!expr.funcName.empty()) {
                    expression = expr.funcName + "(";
                    for (size_t i = 0; i < expr.funcArgs.size(); ++i) {
                        if (i) expression += ',';
                        expression += expr.funcArgs[i];
                    }
                    expression += ')';
                }
                if (!expression.empty()) {
                    const auto evaluated = ExprHelper::evalStringWithNulls(
                        expression, rowContext, nullColumns, typeHints,
                        dbname, expr.sessionUser, this);
                    valueIsNull = evaluated.ok ? evaluated.isNull : true;
                } else valueIsNull = true;
            }
        } else {
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName != expr.colName) continue;
                val = extractColumnValue(mr.second, tbl, i, dbname, true, &valueIsNull);
                std::optional<ExprValue> storedReference;
                if(tbl.cols[i].generatedKind!='v' &&
                   stored_regtype_detail::columnType(tbl.cols[i].dataType)) {
                    const auto catalog=regtype_detail::metadata(*this,dbname);
                    DatumTypePtr actualDeclaration;
                    if(outputDatumMetadata) {
                        const auto actual=outputDatumMetadata->columns.find(tbl.cols[i].dataName);
                        if(actual!=outputDatumMetadata->columns.end())actualDeclaration=actual->second;
                    }
                    storedReference=stored_regtype_detail::load(val,tbl.cols[i].isArray,valueIsNull,
                        catalog,currentSession(),std::move(actualDeclaration));
                    val=storedReference->value;
                }
                if(options.owningDeclarations && outputDatumMetadata) {
                    const auto actual=outputDatumMetadata->columns.find(tbl.cols[i].dataName);
                    if(actual!=outputDatumMetadata->columns.end())declaration=actual->second;
                }
                if (valueIsNull || (val.empty() && tbl.cols[i].generatedKind != 'v' &&
                    dbms::detail::storedRowColumnIsNull(*this, dbname, tbl.tablename, tbl, mr.first, i))) val = "NULL";
                if (owningCell) {
                    // This is the original raw physical cell, not a display-row
                    // parse. Complex payloads absent in storage stay absent;
                    // this bridge never invents record/array/OID structure.
                    owningCell->emplace(ExprHelper::canonicalResultTypeName(
                        tbl.cols[i].dataType+(tbl.cols[i].isArray?"[]":"")),val,valueIsNull);
                    if(storedReference)owningCell->value()=std::move(*storedReference);
                    owningCell->value().collation=tbl.cols[i].collation;
                    if(tbl.cols[i].isArray && tbl.cols[i].generatedKind!='v' && outputDatumMetadata &&
                       outputDatumMetadata->storedColumns.count(tbl.cols[i].dataName)) {
                        const auto declaration=outputDatumMetadata->columns.find(tbl.cols[i].dataName);
                        if(declaration!=outputDatumMetadata->columns.end())
                            (void)compound_value_detail::decodeArrayStorageInput(
                                owningCell->value(),declaration->second);
                    }
                }
                break;
            }
        }
        publishDeclaration(outputColumn,declaration);
        return std::make_pair(std::move(val), valueIsNull);
    };
    using CachedCell = std::optional<std::pair<std::string, bool>>;
    std::vector<std::vector<CachedCell>> earlySortProjection;
    std::vector<std::vector<std::optional<ExprValue>>> earlyOwningProjection;
    if (options.maxProjectionRows && !orderBy.empty() && !hasUnnest) {
        // Preserve expressions placed below Sort, including their errors,
        // while keeping volatile non-key expressions above it. Cache each
        // early value so a delivered row never evaluates it a second time.
        earlySortProjection.assign(matchRows.size(), std::vector<CachedCell>(exprs.size()));
        if (options.owningRows) earlyOwningProjection.assign(matchRows.size(),
            std::vector<std::optional<ExprValue>>(exprs.size()));
        std::vector<size_t> inputToSorted(sortedInputPositions.size(),
                                        std::numeric_limits<size_t>::max());
        for (size_t row = 0; row < matchRows.size(); ++row)
            inputToSorted[sortedInputPositions[row]] = row;
        for (size_t row : inputToSorted) {
            if (row == std::numeric_limits<size_t>::max()) continue;
            NullRowBinding binding(this, dbname, tbl.tablename,
                                   matchRows[row].first, tbl.len);
            for (size_t col = 0; col < exprs.size(); ++col) {
                if (!options.deferredSortProjections.count(col))
                    earlySortProjection[row][col] = evaluateCell(exprs[col], matchRows[row],
                        options.owningRows ? &earlyOwningProjection[row][col] : nullptr,col);
            }
        }
    }
    for (size_t rowIndex = 0; rowIndex < matchRows.size(); ++rowIndex) {
        if (options.maxProjectionRows && result.size() >= *options.maxProjectionRows) break;
        auto& mr = matchRows[rowIndex];
        // Bind stored-NULL visibility for the row being projected.
        NullRowBinding nbP(this, dbname, tbl.tablename, mr.first, tbl.len);
        if (streamingQualification && !std::any_of(
                qualificationBranches.begin(), qualificationBranches.end(),
                [&](const auto& branch) {
                    return std::all_of(branch.begin(), branch.end(),
                        [&](const auto& condition) {
                            return evalConditionOnRow(condition, mr.second, tbl);
                        });
                })) continue;
        if (hasUnnest) {
            // Compute all column values first
            std::vector<std::string> vals;
            std::vector<bool> valNulls;
            vals.reserve(exprs.size());
            valNulls.reserve(exprs.size());
            for (const auto& expr : exprs) {
                if (expr.isScalar) {
                    std::optional<bool> knownNull;
                    const std::string value =
                        applyScalarFunc(expr, mr.second, tbl, this, dbname,
                                        &knownNull);
                    vals.push_back(value);
                    valNulls.push_back(knownNull.value_or(value == "NULL"));
                } else {
                    std::string v;
                    bool valueIsNull = false;
                    for (size_t ci = 0; ci < tbl.len; ++ci) {
                        if (tbl.cols[ci].dataName == expr.colName) {
                            v = extractColumnValue(
                                mr.second, tbl, ci, dbname, true,
                                &valueIsNull);
                            break;
                        }
                    }
                    vals.push_back(v);
                    valNulls.push_back(valueIsNull);
                }
            }
            // Parse array elements from unnest column
            std::string arr = vals[unnestIdx];
            std::vector<std::string> elems;
            if (arr.size() >= 2 && arr.front() == '[' && arr.back() == ']') {
                arr = arr.substr(1, arr.size() - 2);
            }
            size_t ai = 0;
            while (ai < arr.size()) {
                while (ai < arr.size() && std::isspace(static_cast<unsigned char>(arr[ai]))) ++ai;
                if (ai >= arr.size()) break;
                std::string elem;
                if (arr[ai] == '\'' || arr[ai] == '"') {
                    char q = arr[ai++];
                    while (ai < arr.size() && arr[ai] != q) elem += arr[ai++];
                    if (ai < arr.size()) ++ai;
                } else {
                    while (ai < arr.size() && arr[ai] != ',') elem += arr[ai++];
                }
                elems.push_back(trim(elem));
                if (ai < arr.size() && arr[ai] == ',') ++ai;
            }
            if (elems.empty()) elems.push_back("");
            for (const auto& elem : elems) {
                if (options.maxProjectionRows && result.size() >= *options.maxProjectionRows) break;
                std::string rowStr;
                std::vector<std::string> cells;
                std::vector<bool> nulls;
                for (size_t vi = 0; vi < vals.size(); ++vi) {
                    const std::string& cell =
                        vi == unnestIdx ? elem : vals[vi];
                    rowStr += cell;
                    rowStr += ' ';
                    cells.push_back(cell);
                    nulls.push_back(vi == unnestIdx ? false : valNulls[vi]);
                }
                result.push_back(rowStr);
                if (options.owningRows) {
                    if (options.owningRowsComplete) *options.owningRowsComplete=false;
                    options.owningRows->emplace_back(exprs.size());
                }
                if (structuredRows) structuredRows->push_back(std::move(cells));
                if (structuredNulls) structuredNulls->push_back(std::move(nulls));
                if (structuredRowIds) structuredRowIds->push_back(mr.first);
            }
        } else {
            std::string rowStr;
            std::vector<std::string> cells;
            std::vector<bool> nulls;
            std::vector<std::optional<ExprValue>> owning;
            if (options.owningRows) owning.resize(exprs.size());
            for (size_t col = 0; col < exprs.size(); ++col) {
                const auto cell = !earlySortProjection.empty() && earlySortProjection[rowIndex][col]
                    ? *earlySortProjection[rowIndex][col] : evaluateCell(exprs[col], mr,
                        options.owningRows ? &owning[col] : nullptr,col);
                if (options.owningRows && !earlySortProjection.empty() && earlySortProjection[rowIndex][col])
                    owning[col]=earlyOwningProjection[rowIndex][col];
                const std::string& val = cell.first;
                const bool valueIsNull = cell.second;
                rowStr += val + ' ';
                cells.push_back(valueIsNull ? std::string{} : val);
                nulls.push_back(valueIsNull);
            }
            result.push_back(rowStr);
            if (options.owningRows) publishOwningRow(std::move(owning));
            if (structuredRows) structuredRows->push_back(std::move(cells));
            if (structuredNulls) structuredNulls->push_back(std::move(nulls));
            if (structuredRowIds) structuredRowIds->push_back(mr.first);
        }
    }
    return result;
}

// Aggregate-argument expression support ----------------------------------
// An aggregate argument like "amt * 2" or "price - cost" is not a bare
// column.  Detect it: an operator character (+ - * / %) at depth 0 outside
// quotes, after the first character (so "-5" style leading signs in
// literals do not count).
static bool aggArgIsExpression(const std::string& arg) {
    if (arg.empty()) return false;
    // A bare numeric literal ("10.5", "-3") is a valid constant
    // aggregate argument: treat it as an expression so it resolves via
    // getVal instead of being skipped as an unknown column.
    {
        const std::string a = [&arg] { std::string s = arg; size_t b = s.find_first_not_of(" \t"); size_t e = s.find_last_not_of(" \t"); return (b == std::string::npos) ? std::string() : s.substr(b, e - b + 1); }();
        if (!a.empty()) {
            try {
                size_t pos = 0;
                std::stod(a, &pos);
                if (pos == a.size()) return true;
            } catch (...) {}
        }
    }
    int depth = 0;
    bool inQuote = false;
    char prevCh = 0;
    for (char ch : arg) {
        if (inQuote) {
            if (ch == '\'') inQuote = false;
            prevCh = ch;
            continue;
        }
        if (ch == '\'') { inQuote = true; prevCh = ch; continue; }
        if (ch == '(') { ++depth; prevCh = ch; continue; }
        if (ch == ')') { --depth; prevCh = ch; continue; }
        if (depth == 0 && ch != prevCh &&
            std::string("+-*/%").find(ch) != std::string::npos) {
            // A leading sign of a literal ("col * -2") is still part of an
            // expression; a bare leading sign ("-5" as the whole arg) is not.
            return true;
        }
        prevCh = ch;
    }
    return false;
}

// Evaluate a simple left-to-right (no precedence) arithmetic expression
// over a row.  getVal resolves a bare column name (or literal) to its
// string value for the current row.  Returns "" when not evaluable.
template <typename GetVal>
// Per-row boolean-expression evaluation for bool_and/bool_or/every
// arguments ("v > 5"): substitute column tokens with row values and let
// the expression evaluator resolve the comparison.
static std::string evalBoolAggArg(const std::string& expr, GetVal getVal) {
    std::string synth;
    std::string token;
    auto flush = [&]() {
        if (token.empty()) return;
        std::string v = getVal(token);
        bool numeric = !v.empty() && v.find_first_not_of("-+.eE0123456789") == std::string::npos;
        if (!numeric && v != "true" && v != "false") synth += "'" + v + "'";
        else synth += v;
        token.clear();
    };
    for (char ch : expr) {
        if (ch == ' ') { flush(); synth += ' '; continue; }
        if (std::string("<>=!").find(ch) != std::string::npos && token.empty()) {
            synth += ch;
            continue;
        }
        token += ch;
    }
    flush();
    auto r = dbms::ExprHelper::evalString(synth, {}, {}, "");
    if (!r.ok || r.isNull) return "";
    if (r.value == "t" || r.value == "true" || r.value == "1") return "true";
    if (r.value == "f" || r.value == "false" || r.value == "0") return "false";
    return r.value;
}

template <typename GetVal>
static std::string evalAggArgExpr(const std::string& expr, GetVal getVal) {
    double acc = 0.0;
    bool accSet = false;
    char pendingOp = 0;
    std::string token;
    auto flushToken = [&]() {
        if (token.empty()) return;
        std::string v = getVal(token);
        if (!accSet) {
            try { acc = std::stod(v); } catch (...) { token.clear(); return; }
            accSet = true;
        } else {
            double rhs = 0.0;
            try { rhs = std::stod(v); } catch (...) { token.clear(); return; }
            switch (pendingOp) {
                case '+': acc += rhs; break;
                case '-': acc -= rhs; break;
                case '*': acc *= rhs; break;
                case '/': if (rhs == 0) { token.clear(); return; } acc /= rhs; break;
                case '%': { auto l = static_cast<int64_t>(acc), r = static_cast<int64_t>(rhs);
                           if (r == 0) { token.clear(); return; }
                           acc = static_cast<double>(l % r); break; }
                default: token.clear(); return;
            }
        }
        token.clear();
    };
    for (char ch : expr) {
        if (ch == ' ') { flushToken(); continue; }
        // Operator: the left operand was flushed by the preceding space (or
        // is the accumulated first token).  Record it as pending.
        if (accSet && pendingOp == 0 &&
            std::string("+-*/%").find(ch) != std::string::npos && token.empty()) {
            pendingOp = ch;
            continue;
        }
        token += ch;
    }
    flushToken();
    if (!accSet) return "";
    if (acc == static_cast<double>(static_cast<int64_t>(acc)))
        return std::to_string(static_cast<int64_t>(acc));
    std::string s = std::to_string(acc);
    s.erase(s.find_last_not_of('0') + 1, std::string::npos);
    if (!s.empty() && s.back() == '.') s.pop_back();
    return s;
}

// string_agg(expr, sep): strip the second top-level argument (the
// separator literal) from an aggregate argument and return it; PG
// string_agg joins accumulated values with it.
static std::string extractAggSep(std::string& arg, bool& isDistinct) {
    std::string sep = ",";
    isDistinct = false;
    if (arg.size() > 9 && arg.compare(0, 9, "distinct ") == 0) {
        isDistinct = true;
        arg = trim(arg.substr(9));
    }
    int d = 0; bool q = false;
    for (size_t k = 0; k < arg.size(); ++k) {
        char c = arg[k];
        if (c == 39) { q = !q; continue; }
        if (q) continue;
        if (c == '(') ++d;
        else if (c == ')') --d;
        else if (c == ',' && d == 0) {
            std::string t = trim(arg.substr(k + 1));
            if (t.size() >= 2 && t.front() == 39 && t.back() == 39)
                t = t.substr(1, t.size() - 2);
            sep = t;
            arg = trim(arg.substr(0, k));
            break;
        }
    }
    return sep;
}

std::vector<std::string> StorageEngine::aggregate(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    const std::vector<AggItem>& items) {
    std::vector<std::string> result;
    if (!tableExists(dbname, tablename)) return result;
    if (!lockManager_.lockShared(tablename)) return result;

    TableSchema tbl = getTableSchema(dbname, tablename);
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    const auto logicalValue = [&](const std::string& row, size_t columnIndex,
                                  bool* valueIsNull = nullptr) {
        return extractColumnValue(
            row, tbl, columnIndex, dbname, true, valueIsNull);
    };

    auto conds = parseConditions(conditions);
    bool scanFailed = false;
    bool indexReadFailed = false;
    auto ids = filterRows(dbname, tablename, conds, nullptr, &scanFailed,
                          &indexReadFailed);
    if (scanFailed) {
        lockManager_.unlock(tablename);
        if (indexReadFailed) {
            throw DbError("XX001", "B-tree index read failed for relation \"" +
                tablename + "\"");
        }
        return result;
    }
    std::vector<int64_t> matchIds(ids.begin(), ids.end());

    std::string rowResult;
    for (const auto& item : items) {
        const std::string& func = item.func;
        std::string colName = item.arg;
        bool aggDistinct = false;
        std::string aggSep = (func == "string_agg" || func == "group_concat" || func == "array_agg")
                              ? extractAggSep(colName, aggDistinct) : std::string(",");
        int64_t count = 0, sum = 0;
        bool hasMax = false, hasMin = false;
        std::string maxStr, minStr;
        int64_t maxInt = 0, minInt = 0;
        Date maxDate, minDate;
        bool isInt = false, isDate = false;
        // Exact-decimal accumulation for numeric columns (PG avg/sum of
        // numeric must not lose fraction digits).
        dbms::Numeric exactSum(0);
        bool exactSumOk = true;
        int64_t exactCount = 0;
        size_t colIdx = tbl.len;
        std::string groupConcat;
        std::unordered_set<std::string> groupSeen;
        std::vector<std::pair<std::string, std::string>> groupOrdered;
        std::vector<std::pair<std::string, std::string>> arrayOrderedVals;
        size_t orderKeyIdx = tbl.len;
        bool orderDesc = false;
        if (!item.orderBy.empty()) {
            std::string keyCol = item.orderBy;
            // the captured clause keeps its leading order-by prefix
            if (keyCol.size() > 9 && keyCol.compare(0, 8, "order by") == 0)
                keyCol = trim(keyCol.substr(8));
            if (keyCol.size() > 4 && keyCol.compare(keyCol.size() - 4, 4, "desc") == 0 &&
                isspace(static_cast<unsigned char>(keyCol[keyCol.size() - 5]))) {
                orderDesc = true;
                keyCol = trim(keyCol.substr(0, keyCol.size() - 4));
            }
            if (keyCol.size() > 3 && keyCol.compare(keyCol.size() - 3, 3, "asc") == 0 &&
                isspace(static_cast<unsigned char>(keyCol[keyCol.size() - 4])))
                keyCol = trim(keyCol.substr(0, keyCol.size() - 3));
            for (size_t i = 0; i < tbl.len; ++i)
                if (tbl.cols[i].dataName == keyCol) { orderKeyIdx = i; break; }
        }
        bool groupConcatFirst = true;
        std::vector<std::string> jsonAggVals;
        std::vector<std::string> arrayAggVals;
std::unordered_set<std::string> arraySeen;

        bool isDistinctCount = (func == "count" && colName.size() > 9 && colName.substr(0, 9) == "distinct ");
        std::string actualColName = isDistinctCount ? colName.substr(9) : colName;
        bool isJsonAgg = (func == "json_agg" || func == "jsonb_agg");
        bool isArrayAgg = (func == "array_agg");
        bool isVar = (func == "var_pop" || func == "var_samp" || func == "variance");
        bool isStddev = (func == "stddev_pop" || func == "stddev_samp" || func == "stddev");
        bool isStat = isVar || isStddev;
        bool isModeMedian = (func == "mode" || func == "median");
        bool isPercentile = (func == "percentile_cont" || func == "percentile_disc");
        double pctFraction = 0.5;
        std::string pctColName = colName;
        if (isPercentile) {
            auto comma = colName.find(',');
            if (comma != std::string::npos) {
                pctFraction = std::stod(colName.substr(0, comma));
                pctColName = colName.substr(comma + 1);
            }
        }
        bool isBoolAnd = (func == "bool_and" || func == "every");
        bool isBoolOr = (func == "bool_or");
        bool boolResult = isBoolAnd ? true : false;
        bool boolSeen = false;
        std::vector<std::string> orderedVals;
        std::unordered_map<std::string, int64_t> freqMap;
        // Welford's online algorithm for variance
        double wMean = 0.0, wM2 = 0.0;
        size_t wCount = 0;

        if (func != "count" || actualColName != "*") {
            std::string lookupCol = isPercentile ? pctColName : actualColName;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == lookupCol) {
                    colIdx = i;
                    // Fixed-width numeric storage is obvious, but numeric/
                    // decimal/float columns are string-backed (variable
                    // length) and must still aggregate numerically
                    // (sum/avg), not lexically (min/max only).
                    const std::string& dt = tbl.cols[i].dataType;
                    const std::string dtl = [&dt] { std::string s = dt; for (char& ch : s) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch))); return s; }();
                    const bool numericType = dtl != "char" && dtl != "varchar" &&
                                             dtl != "text" && dtl != "date" && dtl != "time" &&
                                             dtl != "timestamp" && dtl != "timestamptz" &&
                                             dtl.rfind("char(", 0) != 0;
                    isInt = numericType || (!tbl.cols[i].isVariableLength && dtl != "char" && dtl != "date");
                    isDate = (dtl == "date");
                    // isChar removed (unused)
                    break;
                }
            }
        }
        if ((isBoolAnd || isBoolOr) && colIdx >= tbl.len) {
            try {
                aggregate_type_detail::BooleanArgument argument(tbl, this, dbname, actualColName);
                const auto parsedFilters = parseConditions(item.filterConds);
                struct ArgumentRow { std::vector<std::string> values; std::vector<bool> nulls; };
                for (const auto rid : matchIds) {
                    std::string row;
                    if (!readRowByRid(pa, rid, row, tbl)) continue;
                    NullRowBinding binding(this, dbname, tablename, rid, tbl.len);
                    bool passes = true;
                    for (const auto& filter : parsedFilters) {
                        if (!evalConditionOnRow(filter, row, tbl)) { passes = false; break; }
                    }
                    if (!passes) continue;
                    ArgumentRow input;
                    for (size_t i = 0; i < tbl.len; ++i) {
                        bool isNull = false;
                        input.values.push_back(logicalValue(row, i, &isNull));
                        input.nulls.push_back(isNull);
                    }
                    const auto evaluated = argument.evaluate(input);
                    if (evaluated.isNull) continue;
                    boolSeen = true;
                    const bool truth = evaluated.value == "t" || evaluated.value == "true" || evaluated.value == "1";
                    if (isBoolAnd) boolResult = boolResult && truth;
                    else boolResult = boolResult || truth;
                }
                rowResult += boolSeen ? (boolResult ? "t " : "f ") : "NULL ";
                continue;
            } catch (...) {
                lockManager_.unlock(tablename);
                throw;
            }
        }
        // Aggregate over an arithmetic expression ("sum(amt * 2)"):
        // resolve operands per row; numeric aggregation semantics.
        const bool aggArgExpr = (colIdx >= tbl.len) && !isPercentile &&
            (func == "sum" || func == "avg" || func == "min" || func == "max" ||
             func == "count") &&
            aggArgIsExpression(isPercentile ? pctColName : actualColName);
        std::string aggExprText = aggArgExpr ? (isPercentile ? pctColName : actualColName) : "";
        double exprSumDouble = 0.0;
        bool sumFromDouble = false;

        // Parse FILTER (WHERE ...) conditions if present
        auto filterConds = parseConditions(item.filterConds);

        if (isDistinctCount) {
            std::set<std::string> distinctVals;
            for (int64_t rid : matchIds) {
                std::string row;
                if (!readRowByRid(pa, rid, row, tbl)) continue;
                NullRowBinding nbD(this, dbname, tablename, rid, tbl.len);
                // Check FILTER condition
                if (!filterConds.empty()) {
                    bool pass = true;
                    for (const auto& fc : filterConds) {
                        if (!evalConditionOnRow(fc, row, tbl)) { pass = false; break; }
                    }
                    if (!pass) continue;
                }
                if (colIdx >= tbl.len) continue;
                bool valueIsNull = false;
                std::string val = logicalValue(
                    row, colIdx, &valueIsNull);
                if (!valueIsNull)
                    distinctVals.insert(canonicalColumnKeyValue(tbl.cols[colIdx], val));
            }
            count = static_cast<int64_t>(distinctVals.size());
        } else {
            for (int64_t rid : matchIds) {
                std::string row;
                if (!readRowByRid(pa, rid, row, tbl)) continue;
                NullRowBinding nb(this, dbname, tablename, rid, tbl.len);
                // Check FILTER condition
                if (!filterConds.empty()) {
                    bool pass = true;
                    for (const auto& fc : filterConds) {
                        if (!evalConditionOnRow(fc, row, tbl)) { pass = false; break; }
                    }
                    if (!pass) continue;
                }
                if (func == "count") {
                    // PG count(col) skips only NULL rows; an empty string
                    // counts.  The stored null bit is the authoritative test.
                    if (colIdx < tbl.len &&
                        tbl.cols[colIdx].generatedKind != 'v' &&
                        dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, colIdx)) {
                        continue;
                    }
                    if (colName == "*") { count++; continue; }
                    std::string val;
                    bool valueIsNull = false;
                    if (aggArgExpr) {
                        auto getValC = [&](const std::string& tok) -> std::string {
                            for (size_t ci2 = 0; ci2 < tbl.len; ++ci2)
                                if (tbl.cols[ci2].dataName == tok)
                                    return logicalValue(row, ci2);
                            if (tok.size() >= 2 && tok.front() == '\'' && tok.back() == '\'')
                                return tok.substr(1, tok.size() - 2);
                            return tok;
                        };
                        val = evalAggArgExpr(aggExprText, getValC);
                    } else {
                        if (colIdx >= tbl.len) continue;
                        val = logicalValue(row, colIdx, &valueIsNull);
                    }
                    if (valueIsNull) continue;
                    count++;  // null rows were skipped above; empty strings count
                } else if (func == "group_concat" || func == "string_agg") {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    if (val.empty()) continue;
                    if (aggDistinct && groupSeen.count(val)) continue;
                    groupSeen.insert(val);
                    if (orderKeyIdx < tbl.len) {
                        groupOrdered.emplace_back(
                            logicalValue(row, orderKeyIdx), val);
                        groupConcatFirst = false;
                        continue;
                    }
                    if (!groupConcatFirst) groupConcat += aggSep;
                    groupConcat += val;
                    groupConcatFirst = false;
                } else if (isJsonAgg) {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    jsonAggVals.push_back(val);
                } else if (isArrayAgg) {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    if (aggDistinct && arraySeen.count(val)) continue;
                    arraySeen.insert(val);
                    if (orderKeyIdx < tbl.len) {
                        arrayOrderedVals.emplace_back(
                            logicalValue(row, orderKeyIdx), val);
                        continue;
                    }
                    arrayAggVals.push_back(val);
                } else {
                std::string val;
                if (aggArgExpr) {
                    auto getVal = [&](const std::string& tok) -> std::string {
                        for (size_t ci2 = 0; ci2 < tbl.len; ++ci2)
                            if (tbl.cols[ci2].dataName == tok)
                                return logicalValue(row, ci2);
                        if (tok.size() >= 2 && tok.front() == '\'' && tok.back() == '\'')
                            return tok.substr(1, tok.size() - 2);
                        return tok;
                    };
                    val = evalAggArgExpr(aggExprText, getVal);
                } else {
                    if (colIdx >= tbl.len) {
                        // Bare numeric literal aggregate argument (avg(10.5)):
                        // the constant is the value for every row.
                        if (actualColName.empty()) continue;
                        try {
                            size_t pos = 0;
                            std::stod(actualColName, &pos);
                            while (pos < actualColName.size() && isspace(static_cast<unsigned char>(actualColName[pos]))) ++pos;
                            if (pos != actualColName.size()) continue;
                            val = actualColName;
                        } catch (...) { continue; }
                    } else {
                        val = logicalValue(row, colIdx);
                    }
                }
                if (isModeMedian) {
                    if (!val.empty()) {
                        orderedVals.push_back(val);
                        ++freqMap[val];
                    }
                    continue;
                }
                if (isPercentile) {
                    if (!val.empty()) orderedVals.push_back(val);
                    continue;
                }
                if (isBoolAnd || isBoolOr) {
                    if (val.empty()) continue;
                    boolSeen = true;
                    // Accept "t"/"f" (evaluator) and "true"/"false" spellings.
                    const bool falsyT = val == "false" || val == "f" || val == "0";
                    const bool truthyT = val == "true" || val == "t" || val == "1";
                    if (isBoolAnd && falsyT) boolResult = false;
                    if (isBoolOr && truthyT) boolResult = true;
                    continue;
                }
                if (isInt || aggArgExpr) {
                    if (val.empty()) continue;
                    const auto parsed = parseStoredInteger(val);
                    const int64_t num = parsed.value_or(0);
                    if (!parsed) {
                        // Fractional expression value: double fallback for
                        // sum/avg; min/max compare numerically as doubles.
                        double d = 0.0;
                        try { d = val.empty() ? 0.0 : std::stod(val); }
                        catch (...) { continue; }
                        if (func == "sum" || func == "avg") {
                            exprSumDouble += d;
                            ++count;
                            if (func == "sum") sum += static_cast<int64_t>(0); // keep int path inert
                            sumFromDouble = true;
                            if (exactSumOk) {
                                try { exactSum = exactSum + dbms::Numeric(val); ++exactCount; }
                                catch (...) { exactSumOk = false; }
                            }
                        } else if (func == "max") {
                            if (!hasMax || d > static_cast<double>(maxInt)) { maxInt = static_cast<int64_t>(d); hasMax = true; }
                        } else if (func == "min") {
                            if (!hasMin || d < static_cast<double>(minInt)) { minInt = static_cast<int64_t>(d); hasMin = true; }
                        } else { continue; }
                    } else {
                        if (func == "sum") sumFromDouble = false;
                        if (func == "sum" || func == "avg") {
                            ++count;
                            exactSum = exactSum + dbms::Numeric(val);
                            ++exactCount;
                        }
                        if (func == "max") {
                            if (!hasMax || num > maxInt) { maxInt = num; hasMax = true; }
                        }
                        if (func == "min") {
                            if (!hasMin || num < minInt) { minInt = num; hasMin = true; }
                        }
                        if (isStat) {
                            wCount++;
                            double delta = static_cast<double>(num) - wMean;
                            wMean += delta / wCount;
                            wM2 += delta * (static_cast<double>(num) - wMean);
                        }
                    }
                } else if (isDate) {
                    Date d = val.empty() ? Date{} : Date(val.c_str());
                    if (d.year == 0) continue;
                    if (func == "max") {
                        if (!hasMax || d > maxDate) { maxDate = d; hasMax = true; }
                    }
                    if (func == "min") {
                        if (!hasMin || d < minDate) { minDate = d; hasMin = true; }
                    }
                } else {
                    if (val.empty()) continue;
                    if (func == "max") {
                        if (!hasMax || val > maxStr) { maxStr = val; hasMax = true; }
                    }
                    if (func == "min") {
                        if (!hasMin || val < minStr) { minStr = val; hasMin = true; }
                    }
                }
            }
        }
        }

        if (func == "count") rowResult += transstr(count) + ' ';
        else if (func == "sum") {
            if (aggArgExpr && sumFromDouble) {
                std::string s = std::to_string(exprSumDouble);
                s.erase(s.find_last_not_of('0') + 1, std::string::npos);
                if (!s.empty() && s.back() == '.') s.pop_back();
                rowResult += s + ' ';
            } else if (exactSumOk && exactCount == count && count > 0) {
                // exact-decimal sum for numeric columns
                try { rowResult += exactSum.toString() + ' '; }
                catch (...) { rowResult += transstr(sum) + ' '; }
            } else {
                rowResult += transstr(sum) + ' ';
            }
        }
        else if (func == "avg") {
            std::string avgOut = "0";
            if (count > 0) {
                // PG avg(numeric): exact numeric division (select_div_scale).
                if (exactSumOk && exactCount == count) {
                    try { avgOut = (exactSum / dbms::Numeric(count)).toString(); }
                    catch (...) { avgOut = std::to_string(static_cast<double>(sum) / count); }
                } else {
                    avgOut = std::to_string(static_cast<double>(sum) / count);
                }
            }
            rowResult += avgOut + ' ';
        }
        else if (func == "group_concat" || func == "string_agg") {
            if (!groupOrdered.empty()) {
                std::stable_sort(groupOrdered.begin(), groupOrdered.end(),
                    [&orderDesc](const std::pair<std::string, std::string>& a, const std::pair<std::string, std::string>& b) {
                        bool na = !a.first.empty() && a.first.find_first_not_of("0123456789.+-eE") == std::string::npos;
                        bool nb = !b.first.empty() && b.first.find_first_not_of("0123456789.+-eE") == std::string::npos;
                        bool lt = (na && nb) ? (std::stod(a.first) < std::stod(b.first)) : (a.first < b.first);
                        return orderDesc ? (!lt && a.first != b.first) : lt;
                    });
                groupConcat.clear();
                for (size_t qi = 0; qi < groupOrdered.size(); ++qi) {
                    if (qi) groupConcat += aggSep;
                    groupConcat += groupOrdered[qi].second;
                }
            }
            rowResult += (groupConcat.empty() ? "NULL" : groupConcat) + ' ';
        }
        else if (isJsonAgg) {
            std::string json = "[";
            bool first = true;
            for (const auto& v : jsonAggVals) {
                if (!first) json += ",";
                if (v.empty()) {
                    json += "null";
                } else if (isInt || v == "true" || v == "false" || v == "null") {
                    json += v;
                } else {
                    // String: escape quotes and wrap
                    std::string esc;
                    for (char c : v) {
                        if (c == '"' || c == '\\') esc += '\\';
                        esc += c;
                    }
                    json += '"' + esc + '"';
                }
                first = false;
            }
            json += "]";
            rowResult += json + ' ';
        }
        else if (isArrayAgg) {
            if (!arrayOrderedVals.empty()) {
                std::stable_sort(arrayOrderedVals.begin(), arrayOrderedVals.end(),
                    [&orderDesc](const std::pair<std::string, std::string>& a, const std::pair<std::string, std::string>& b) {
                        bool na = !a.first.empty() && a.first.find_first_not_of("0123456789.+-eE") == std::string::npos;
                        bool nb = !b.first.empty() && b.first.find_first_not_of("0123456789.+-eE") == std::string::npos;
                        bool lt = (na && nb) ? (std::stod(a.first) < std::stod(b.first)) : (a.first < b.first);
                        return orderDesc ? (!lt && a.first != b.first) : lt;
                    });
                arrayAggVals.clear();
                for (const auto& kv : arrayOrderedVals) arrayAggVals.push_back(kv.second);
            }
            // PG array_agg(DISTINCT ...) sorts the deduplicated values.
            if (aggDistinct && !arrayAggVals.empty()) {
                bool allNum = true;
                for (const auto& sv : arrayAggVals)
                    if (sv.empty() || sv.find_first_not_of("0123456789.+-eE") != std::string::npos)
                        { allNum = false; break; }
                if (allNum)
                    std::sort(arrayAggVals.begin(), arrayAggVals.end(),
                              [](const std::string& a, const std::string& b) {
                                  double da = 0, db = 0;
                                  try { da = std::stod(a); db = std::stod(b); } catch (...) {}
                                  return da < db;
                              });
                else std::sort(arrayAggVals.begin(), arrayAggVals.end());
            }

            // PG array_agg(DISTINCT ...) sorts the deduplicated values.
            if (aggDistinct && !arrayAggVals.empty()) {
            bool allNum = true;
            for (const auto& sv : arrayAggVals)
            if (sv.empty() || sv.find_first_not_of("0123456789.+-eE") != std::string::npos)
            { allNum = false; break; }
            if (allNum)
            std::sort(arrayAggVals.begin(), arrayAggVals.end(),
            [](const std::string& a, const std::string& b) {
            double da = 0, db = 0;
            try { da = std::stod(a); db = std::stod(b); } catch (...) {}
            return da < db;
            });
            else std::sort(arrayAggVals.begin(), arrayAggVals.end());
            }std::string arr = "{";
            bool first = true;
            for (const auto& v : arrayAggVals) {
                if (!first) arr += ",";
                arr += v;
                first = false;
            }
            arr += "}";
            rowResult += arr + ' ';
        }
        else if (func == "max") {
            if (!hasMax) rowResult += "NULL ";
            else if (isInt || aggArgExpr) rowResult += transstr(maxInt) + ' ';
            else if (isDate) rowResult += str(maxDate) + ' ';
            else rowResult += maxStr + ' ';
        }
        else if (func == "min") {
            if (!hasMin) rowResult += "NULL ";
            else if (isInt || aggArgExpr) rowResult += transstr(minInt) + ' ';
            else if (isDate) rowResult += str(minDate) + ' ';
            else rowResult += minStr + ' ';
        }
        else if (isVar || isStddev) {
            if (wCount == 0) {
                rowResult += "NULL ";
            } else if ((func == "var_samp" || func == "stddev_samp" || func == "variance" || func == "stddev") && wCount < 2) {
                rowResult += "NULL ";
            } else {
                double variance = 0.0;
                if (func == "var_pop" || func == "stddev_pop") {
                    variance = wM2 / wCount;
                } else {
                    variance = wM2 / (wCount - 1);
                }
                // PG renders these aggregates over integer input as
                // numeric with full precision (5.7008771254956899,
                // 32.5000000000000000): shortest round-trip double text.
                // PG stddev over integer input returns numeric from an
                // exact digit-by-digit sqrt_var: match it with Newton-
                // refined long double sqrt, 17 significant digits
                // (5.7008771254956899).  Variance prints shortest form.
                std::string vs;
                if (isStddev) {
                    long double x = static_cast<long double>(variance);
                    long double r = std::sqrt(x);
                    for (int it = 0; it < 4; ++it)
                        r = (r + x / r) / 2.0L;
                    char buf[64];
                    std::snprintf(buf, sizeof(buf), "%.17Lg", r);
                    vs = buf;
                } else {
                    // PG numeric variance from integer input renders
                    // with 16 fraction digits (32.5000000000000000).
                    char vbuf[64];
                    std::snprintf(vbuf, sizeof(vbuf), "%.16f", variance);
                    vs = vbuf;
                }
                if (vs.find(46) == std::string::npos)
                    vs += ".0";
                rowResult += vs + ' ';
            }
        }
        else if (isModeMedian) {
            if (orderedVals.empty()) {
                rowResult += "NULL ";
            } else if (func == "mode") {
                std::string best;
                int64_t bestCount = -1;
                for (const auto& kv : freqMap) {
                    if (kv.second > bestCount || (kv.second == bestCount && kv.first < best)) {
                        bestCount = kv.second;
                        best = kv.first;
                    }
                }
                rowResult += best + ' ';
            } else { // median
                std::sort(orderedVals.begin(), orderedVals.end());
                size_t mid = orderedVals.size() / 2;
                if (orderedVals.size() % 2 == 1) {
                    rowResult += orderedVals[mid] + ' ';
                } else {
                    // average of two middle values if numeric, otherwise lower middle
                    bool numeric = !orderedVals.empty() && std::all_of(orderedVals.begin(), orderedVals.end(),
                        [](const std::string& v) { return !v.empty() && (std::isdigit(static_cast<unsigned char>(v[0])) || v[0] == '-' || v[0] == '+'); });
                    if (numeric) {
                        double a = std::stod(orderedVals[mid - 1]);
                        double b = std::stod(orderedVals[mid]);
                        std::ostringstream oss;
                        oss << ((a + b) / 2.0);
                        rowResult += oss.str() + ' ';
                    } else {
                        rowResult += orderedVals[mid - 1] + ' ';
                    }
                }
            }
        }
        else if (isPercentile) {
            if (orderedVals.empty()) {
                rowResult += "NULL ";
            } else {
                // Sort and compute percentile
                std::sort(orderedVals.begin(), orderedVals.end(),
                    [](const std::string& a, const std::string& b) {
                        bool aNum = !a.empty() && (std::isdigit(static_cast<unsigned char>(a[0])) || a[0] == '-' || a[0] == '+');
                        bool bNum = !b.empty() && (std::isdigit(static_cast<unsigned char>(b[0])) || b[0] == '-' || b[0] == '+');
                        if (aNum && bNum) return std::stod(a) < std::stod(b);
                        return a < b;
                    });
                size_t n = orderedVals.size();
                if (func == "percentile_disc") {
                    // Discrete: return value at ceil(fraction * n) - 1
                    size_t idx = static_cast<size_t>(std::ceil(pctFraction * n));
                    if (idx > 0) idx--;
                    rowResult += orderedVals[idx] + ' ';
                } else {
                    // Continuous: interpolate
                    double idx = pctFraction * (n - 1);
                    size_t lo = static_cast<size_t>(std::floor(idx));
                    size_t hi = static_cast<size_t>(std::ceil(idx));
                    if (lo == hi || hi >= n) {
                        rowResult += orderedVals[lo] + ' ';
                    } else {
                        // Interpolate if numeric, otherwise use lower
                        bool numeric = !orderedVals[lo].empty() && !orderedVals[hi].empty() &&
                            (std::isdigit(static_cast<unsigned char>(orderedVals[lo][0])) || orderedVals[lo][0] == '-' || orderedVals[lo][0] == '+') &&
                            (std::isdigit(static_cast<unsigned char>(orderedVals[hi][0])) || orderedVals[hi][0] == '-' || orderedVals[hi][0] == '+');
                        if (numeric) {
                            double a = std::stod(orderedVals[lo]);
                            double b = std::stod(orderedVals[hi]);
                            double frac = idx - lo;
                            std::ostringstream oss;
                            oss << (a + frac * (b - a));
                            rowResult += oss.str() + ' ';
                        } else {
                            rowResult += orderedVals[lo] + ' ';
                        }
                    }
                }
            }
        }
        else if (isBoolAnd || isBoolOr) {
            rowResult += (boolSeen ? (boolResult ? "t " : "f ") : "NULL ");
        }
    }
    if (!rowResult.empty()) result.push_back(rowResult);
    lockManager_.unlock(tablename);
    return result;
}

// ========================================================================
// Group aggregate: GROUP BY with HAVING
// ========================================================================

std::vector<std::string> StorageEngine::groupAggregate(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    const std::vector<AggItem>& items,
    const std::vector<std::string>& groupByCols,
    const std::vector<std::string>& havingConds) {
    std::vector<std::string> result;
    if (!tableExists(dbname, tablename)) return result;
    if (!lockManager_.lockShared(tablename)) return result;

    TableSchema tbl = getTableSchema(dbname, tablename);

    // Find group-by column indices
    std::vector<size_t> groupIdxs;
    for (const auto& gcol : groupByCols) {
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == gcol) { groupIdxs.push_back(i); break; }
        }
    }
    if (groupIdxs.size() != groupByCols.size()) {
        lockManager_.unlock(tablename);
        return result;
    }

    PageAllocator* pa = getPageAllocator(dbname, tablename);
    const auto logicalValue = [&](const std::string& row, size_t columnIndex,
                                  bool* valueIsNull = nullptr) {
        return extractColumnValue(
            row, tbl, columnIndex, dbname, true, valueIsNull);
    };
    auto conds = parseConditions(conditions);
    std::vector<int64_t> matchIds;
    bool scanFailed = false;
    bool indexReadFailed = false;
    if (conds.empty()) {
        if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId, [[maybe_unused]] const char* data, [[maybe_unused]] size_t len) {
            matchIds.push_back(encodeRid(pageId, slotId));
        })) scanFailed = true;
    } else {
        auto ids = filterRows(dbname, tablename, conds, nullptr, &scanFailed,
                              &indexReadFailed);
        matchIds.assign(ids.begin(), ids.end());
    }
    if (scanFailed) {
        lockManager_.unlock(tablename);
        if (indexReadFailed) {
            throw DbError("XX001", "B-tree index read failed for relation \"" +
                tablename + "\"");
        }
        return result;
    }

    // Read composite group key for each matching row
    auto readGroupKey = [&](int64_t rid) -> std::string {
        std::string row;
        if (!readRowByRid(pa, rid, row, tbl)) return "";
        NullRowBinding nbk(this, dbname, tablename, rid, tbl.len);
        std::string key;
        for (size_t idx : groupIdxs) {
            bool isNull = false;
            const std::string value = logicalValue(row, idx, &isNull);
            key += groupingValueKey(tbl.cols[idx], value, isNull);
        }
        return key;
    };

    // Group rows by group key
    std::map<std::string, std::vector<int64_t>> groups;
    for (int64_t rowIdx : matchIds) {
        groups[readGroupKey(rowIdx)].push_back(rowIdx);
    }

    // Helper: compute aggregate for a group
    auto computeAgg = [&](const std::vector<int64_t>& gids,
                           const std::string& func, const std::string& colNameP,
                           const std::vector<std::string>& filterConds = {}) -> std::string {
    std::string colName = colNameP;
    bool aggDistinct = false;
    std::string aggSep = (func == "string_agg" || func == "group_concat" || func == "array_agg")
                          ? extractAggSep(colName, aggDistinct) : std::string(",");
        bool isDistinctCount = (func == "count" && colName.size() > 9 && colName.substr(0, 9) == "distinct ");
        std::string actualColName = isDistinctCount ? colName.substr(9) : colName;
        bool isJsonAgg = (func == "json_agg" || func == "jsonb_agg");
        bool isArrayAgg = (func == "array_agg");
        bool isModeMedian = (func == "mode" || func == "median");
        bool isPercentile = (func == "percentile_cont" || func == "percentile_disc");
        double pctFraction = 0.5;
        std::string pctColName = colName;
        if (isPercentile) {
            auto comma = colName.find(',');
            if (comma != std::string::npos) {
                pctFraction = std::stod(colName.substr(0, comma));
                pctColName = colName.substr(comma + 1);
            }
        }
        bool isBoolAnd = (func == "bool_and" || func == "every");
        bool isBoolOr = (func == "bool_or");
        bool boolResult = isBoolAnd ? true : false;
        bool boolSeen = false;
        std::vector<std::string> orderedVals;
        std::unordered_map<std::string, int64_t> freqMap;
        size_t colIdx = tbl.len;
        bool isInt = false, isDate = false;
        // Exact-decimal accumulation for numeric columns (PG avg/sum of
        // numeric must not lose fraction digits).
        dbms::Numeric exactSum(0);
        bool exactSumOk = true;
        int64_t exactCount = 0;
        if (func != "count" || actualColName != "*") {
            std::string lookupCol = isPercentile ? pctColName : actualColName;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == lookupCol) {
                    colIdx = i;
                    // Fixed-width numeric storage is obvious, but numeric/
                    // decimal/float columns are string-backed (variable
                    // length) and must still aggregate numerically
                    // (sum/avg), not lexically (min/max only).
                    const std::string& dt = tbl.cols[i].dataType;
                    const std::string dtl = [&dt] { std::string s = dt; for (char& ch : s) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch))); return s; }();
                    const bool numericType = dtl != "char" && dtl != "varchar" &&
                                             dtl != "text" && dtl != "date" && dtl != "time" &&
                                             dtl != "timestamp" && dtl != "timestamptz" &&
                                             dtl.rfind("char(", 0) != 0;
                    isInt = numericType || (!tbl.cols[i].isVariableLength && dtl != "char" && dtl != "date");
                    isDate = (dtl == "date");
                    // isChar removed (unused)
                    break;
                }
            }
        }
        if ((isBoolAnd || isBoolOr) && colIdx >= tbl.len) {
            try {
                aggregate_type_detail::BooleanArgument argument(tbl, this, dbname, actualColName);
                const auto parsedFilters = parseConditions(filterConds);
                struct ArgumentRow { std::vector<std::string> values; std::vector<bool> nulls; };
                for (const auto rid : gids) {
                    std::string row;
                    if (!readRowByRid(pa, rid, row, tbl)) continue;
                    NullRowBinding binding(this, dbname, tablename, rid, tbl.len);
                    bool passes = true;
                    for (const auto& filter : parsedFilters) {
                        if (!evalConditionOnRow(filter, row, tbl)) { passes = false; break; }
                    }
                    if (!passes) continue;
                    ArgumentRow input;
                    for (size_t i = 0; i < tbl.len; ++i) {
                        bool isNull = false;
                        input.values.push_back(logicalValue(row, i, &isNull));
                        input.nulls.push_back(isNull);
                    }
                    const auto evaluated = argument.evaluate(input);
                    if (evaluated.isNull) continue;
                    boolSeen = true;
                    const bool truth = evaluated.value == "t" || evaluated.value == "true" || evaluated.value == "1";
                    if (isBoolAnd) boolResult = boolResult && truth;
                    else boolResult = boolResult || truth;
                }
                return boolSeen ? (boolResult ? "t" : "f") : "NULL";
            } catch (...) {
                lockManager_.unlock(tablename);
                throw;
            }
        }
        // Aggregate over an arithmetic expression (see aggregate()).
        const bool aggArgExpr = (colIdx >= tbl.len) && !isPercentile &&
            (func == "sum" || func == "avg" || func == "min" || func == "max" ||
             func == "count") &&
            aggArgIsExpression(isPercentile ? pctColName : actualColName);
        std::string aggExprText = aggArgExpr ? (isPercentile ? pctColName : actualColName) : "";
        int64_t count = 0, sum = 0;
        bool hasMax = false, hasMin = false;
        std::string maxStr, minStr;
        int64_t maxInt = 0, minInt = 0;
        Date maxDate, minDate;
        std::string groupConcat;
        std::unordered_set<std::string> groupSeen;
        bool groupConcatFirst = true;
        std::vector<std::string> jsonAggVals;
        std::vector<std::string> arrayAggVals;
std::unordered_set<std::string> arraySeen;
        // jsonAggFirst is not needed; JSON aggregation uses jsonAggVals directly.

        if (isDistinctCount) {
            const auto parsedFilters = parseConditions(filterConds);
            std::set<std::string> distinctVals;
            for (int64_t rid : gids) {
                std::string row;
                if (!readRowByRid(pa, rid, row, tbl)) continue;
                NullRowBinding nbD(this, dbname, tablename, rid, tbl.len);
                bool passes = true;
                for (const auto& filter : parsedFilters) {
                    if (!evalConditionOnRow(filter, row, tbl)) {
                        passes = false;
                        break;
                    }
                }
                if (!passes) continue;
                if (colIdx >= tbl.len) continue;
                bool valueIsNull = false;
                std::string val = logicalValue(
                    row, colIdx, &valueIsNull);
                if (!valueIsNull)
                    distinctVals.insert(canonicalColumnKeyValue(tbl.cols[colIdx], val));
            }
            count = static_cast<int64_t>(distinctVals.size());
        } else {
            // Parse FILTER conditions
            auto parsedFilters = parseConditions(filterConds);
            for (int64_t rid : gids) {
                std::string row;
                if (!readRowByRid(pa, rid, row, tbl)) continue;
                NullRowBinding nbG(this, dbname, tablename, rid, tbl.len);
                // Check FILTER condition
                if (!parsedFilters.empty()) {
                    bool pass = true;
                    for (const auto& fc : parsedFilters) {
                        if (!evalConditionOnRow(fc, row, tbl)) { pass = false; break; }
                    }
                    if (!pass) continue;
                }

                if (func == "count") {
                    // PG count(col) skips only NULL rows; an empty string
                    // counts.  The stored null bit is the authoritative test.
                    if (colIdx < tbl.len &&
                        tbl.cols[colIdx].generatedKind != 'v' &&
                        dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, colIdx)) {
                        continue;
                    }
                    // PG count(col) skips only NULL rows; an empty string
                    // counts.  The stored null bit is the authoritative test.
                    if (colIdx < tbl.len &&
                        tbl.cols[colIdx].generatedKind != 'v' &&
                        dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, colIdx)) {
                        continue;
                    }
                    if (colName == "*") { count++; continue; }
                    std::string val;
                    bool valueIsNull = false;
                    if (aggArgExpr) {
                        auto getValC = [&](const std::string& tok) -> std::string {
                            for (size_t ci2 = 0; ci2 < tbl.len; ++ci2)
                                if (tbl.cols[ci2].dataName == tok)
                                    return logicalValue(row, ci2);
                            if (tok.size() >= 2 && tok.front() == '\'' && tok.back() == '\'')
                                return tok.substr(1, tok.size() - 2);
                            return tok;
                        };
                        val = evalAggArgExpr(aggExprText, getValC);
                    } else {
                        if (colIdx >= tbl.len) continue;
                        val = logicalValue(row, colIdx, &valueIsNull);
                    }
                    if (valueIsNull) continue;
                    count++;  // null rows were skipped above; empty strings count
                } else if (func == "group_concat" || func == "string_agg") {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    if (val.empty()) continue;
                    if (aggDistinct && groupSeen.count(val)) continue;
                    groupSeen.insert(val);
                    if (!groupConcatFirst) groupConcat += aggSep;
                    groupConcat += val;
                    groupConcatFirst = false;
                } else if (isJsonAgg) {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    jsonAggVals.push_back(val);
                } else if (isArrayAgg) {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    if (aggDistinct && arraySeen.count(val)) continue;
                    arraySeen.insert(val);
                    arrayAggVals.push_back(val);
                } else {
                std::string val;
                if (aggArgExpr) {
                    auto getVal = [&](const std::string& tok) -> std::string {
                        for (size_t ci2 = 0; ci2 < tbl.len; ++ci2)
                            if (tbl.cols[ci2].dataName == tok)
                                return logicalValue(row, ci2);
                        if (tok.size() >= 2 && tok.front() == '\'' && tok.back() == '\'')
                            return tok.substr(1, tok.size() - 2);
                        return tok;
                    };
                    val = evalAggArgExpr(aggExprText, getVal);
                } else {
                    if (colIdx >= tbl.len) {
                        // Bare numeric literal aggregate argument (avg(10.5)):
                        // the constant is the value for every row.
                        if (actualColName.empty()) continue;
                        try {
                            size_t pos = 0;
                            std::stod(actualColName, &pos);
                            while (pos < actualColName.size() && isspace(static_cast<unsigned char>(actualColName[pos]))) ++pos;
                            if (pos != actualColName.size()) continue;
                            val = actualColName;
                        } catch (...) { continue; }
                    } else {
                        val = logicalValue(row, colIdx);
                    }
                }
                if (isModeMedian) {
                    if (!val.empty()) {
                        orderedVals.push_back(val);
                        ++freqMap[val];
                    }
                    continue;
                }
                if (isPercentile) {
                    if (!val.empty()) orderedVals.push_back(val);
                    continue;
                }
                if (isBoolAnd || isBoolOr) {
                    if (val.empty()) continue;
                    boolSeen = true;
                    // Accept "t"/"f" (evaluator) and "true"/"false" spellings.
                    const bool falsyT = val == "false" || val == "f" || val == "0";
                    const bool truthyT = val == "true" || val == "t" || val == "1";
                    if (isBoolAnd && falsyT) boolResult = false;
                    if (isBoolOr && truthyT) boolResult = true;
                    continue;
                }
                if (isInt || aggArgExpr) {
                    const auto parsed = parseStoredInteger(val);
                    if (!parsed) continue;
                    const int64_t num = *parsed;
                    if (func == "sum" || func == "avg") {
                        ++count;
                        exactSum = exactSum + dbms::Numeric(val);
                        ++exactCount;
                    }
                    if (func == "max") { if (!hasMax || num > maxInt) { maxInt = num; hasMax = true; } }
                    if (func == "min") { if (!hasMin || num < minInt) { minInt = num; hasMin = true; } }
                } else if (isDate) {
                    Date d = val.empty() ? Date{} : Date(val.c_str());
                    if (d.year == 0) continue;
                    if (func == "max") { if (!hasMax || d > maxDate) { maxDate = d; hasMax = true; } }
                    if (func == "min") { if (!hasMin || d < minDate) { minDate = d; hasMin = true; } }
                } else {
                    if (val.empty()) continue;
                    if (func == "max") { if (!hasMax || val > maxStr) { maxStr = val; hasMax = true; } }
                    if (func == "min") { if (!hasMin || val < minStr) { minStr = val; hasMin = true; } }
                }
            }
        }
        }
        if (func == "count") return transstr(count);
        if (func == "sum") {
            if (exactSumOk && exactCount == count && count > 0) {
                try { return exactSum.toString(); } catch (...) {}
            }
            return transstr(sum);
        }
        if (func == "avg") {
            if (count == 0) return "0";
            // PG avg(numeric): exact numeric division (select_div_scale).
            if (exactSumOk && exactCount == count) {
                try { return (exactSum / dbms::Numeric(count)).toString(); }
                catch (...) {}
            }
            return std::to_string(static_cast<double>(sum) / count);
        }
        if (func == "group_concat" || func == "string_agg") return groupConcat.empty() ? "NULL" : groupConcat;
        if (isJsonAgg) {
            std::string json = "[";
            bool first = true;
            for (const auto& v : jsonAggVals) {
                if (!first) json += ",";
                if (v.empty()) {
                    json += "null";
                } else if (isInt || v == "true" || v == "false" || v == "null") {
                    json += v;
                } else {
                    std::string esc;
                    for (char c : v) {
                        if (c == '"' || c == '\\') esc += '\\';
                        esc += c;
                    }
                    json += '"' + esc + '"';
                }
                first = false;
            }
            json += "]";
            return json;
        }
        if (isArrayAgg) {

            // PG array_agg(DISTINCT ...) sorts the deduplicated values.
            if (aggDistinct && !arrayAggVals.empty()) {
            bool allNum = true;
            for (const auto& sv : arrayAggVals)
            if (sv.empty() || sv.find_first_not_of("0123456789.+-eE") != std::string::npos)
            { allNum = false; break; }
            if (allNum)
            std::sort(arrayAggVals.begin(), arrayAggVals.end(),
            [](const std::string& a, const std::string& b) {
            double da = 0, db = 0;
            try { da = std::stod(a); db = std::stod(b); } catch (...) {}
            return da < db;
            });
            else std::sort(arrayAggVals.begin(), arrayAggVals.end());
            }std::string arr = "{";
            bool first = true;
            for (const auto& v : arrayAggVals) {
                if (!first) arr += ",";
                arr += v;
                first = false;
            }
            arr += "}";
            return arr;
        }
        if (isBoolAnd || isBoolOr) return boolSeen ? (boolResult ? "t" : "f") : "NULL";
        if (func == "max") {
            if (!hasMax) return "NULL";
            if (isInt || aggArgExpr) return transstr(maxInt);
            if (isDate) return str(maxDate);
            return maxStr;
        }
        if (func == "min") {
            if (!hasMin) return "NULL";
            if (isInt || aggArgExpr) return transstr(minInt);
            if (isDate) return str(minDate);
            return minStr;
        }
        if (isPercentile) {
            if (orderedVals.empty()) return "NULL";
            std::sort(orderedVals.begin(), orderedVals.end(),
                [](const std::string& a, const std::string& b) {
                    bool aNum = !a.empty() && (std::isdigit(static_cast<unsigned char>(a[0])) || a[0] == '-' || a[0] == '+');
                    bool bNum = !b.empty() && (std::isdigit(static_cast<unsigned char>(b[0])) || b[0] == '-' || b[0] == '+');
                    if (aNum && bNum) return std::stod(a) < std::stod(b);
                    return a < b;
                });
            size_t n = orderedVals.size();
            if (func == "percentile_disc") {
                size_t idx = static_cast<size_t>(std::ceil(pctFraction * n));
                if (idx > 0) idx--;
                return orderedVals[idx];
            } else {
                double idx = pctFraction * (n - 1);
                size_t lo = static_cast<size_t>(std::floor(idx));
                size_t hi = static_cast<size_t>(std::ceil(idx));
                if (lo == hi || hi >= n) return orderedVals[lo];
                bool numeric = !orderedVals[lo].empty() && !orderedVals[hi].empty() &&
                    (std::isdigit(static_cast<unsigned char>(orderedVals[lo][0])) || orderedVals[lo][0] == '-' || orderedVals[lo][0] == '+') &&
                    (std::isdigit(static_cast<unsigned char>(orderedVals[hi][0])) || orderedVals[hi][0] == '-' || orderedVals[hi][0] == '+');
                if (numeric) {
                    double a = std::stod(orderedVals[lo]);
                    double b = std::stod(orderedVals[hi]);
                    double frac = idx - lo;
                    std::ostringstream oss;
                    oss << (a + frac * (b - a));
                    return oss.str();
                }
                return orderedVals[lo];
            }
        }
        return "";
    };

    // Parse HAVING conditions: support "aggFunc(col) op value"
    struct HavingCond {
        std::string func, colName, op, value;
    };
    std::vector<HavingCond> havings;
    struct GroupHavingCond {
        size_t columnIndex;
        std::string op, value;
        bool valueIsNull;
    };
    std::vector<GroupHavingCond> groupHavings;
    for (const auto& hc : havingConds) {
        if (hc.empty()) continue;
        // Format: "func(col) op value" or "op col value" (if already modified)
        std::string s = hc;
        // A parenthesis in a delimited column or a literal is not a function
        // call. Classify the genuine comparison's left AST before consulting
        // the older aggregate-call adapter below.
        SQLParser parser;
        auto parsed = parser.parse("SELECT " + s);
        const auto* select = parsed.success ? dynamic_cast<const SelectStmt*>(parsed.stmt.get()) : nullptr;
        const auto* comparison = select && select->selectList.size() == 1
            ? dynamic_cast<const BinaryOpExpr*>(select->selectList.front().expr.get()) : nullptr;
        const auto* column = comparison
            ? dynamic_cast<const ColumnRefExpr*>(comparison->left.get()) : nullptr;
        // Try parse aggFunc(col) op value
        size_t lp = s.find('(');
        size_t rp = s.find(')');
        if (!column && lp != std::string::npos && rp != std::string::npos && rp > lp + 1) {
            HavingCond h;
            h.func = s.substr(0, lp);
            h.colName = s.substr(lp + 1, rp - lp - 1);
            std::string rest = trim(s.substr(rp + 1));
            // Parse operator and value: may be "> 1" or ">1" (no space)
            size_t opEnd = 0;
            while (opEnd < rest.size() && (rest[opEnd] == '<' || rest[opEnd] == '>' || rest[opEnd] == '=' || rest[opEnd] == '!')) ++opEnd;
            if (opEnd > 0) {
                h.op = rest.substr(0, opEnd);
                h.value = trim(rest.substr(opEnd));
                havings.push_back(h);
            }
        } else {
            // The frontend hands off a structurally bound physical column,
            // quoted as an SQL identifier. Consume its real grammar identity,
            // not rendered quotes or an operator-looking character inside it.
            if (!comparison || (comparison->op != "=" && comparison->op != "<>" &&
                comparison->op != "!=" && comparison->op != "<" && comparison->op != ">" &&
                comparison->op != "<=" && comparison->op != ">=")) continue;
            if (!column || !column->table.empty() || !column->schema.empty()) continue;
            const std::string& colName = column->column;
            if (std::find(groupByCols.begin(), groupByCols.end(), colName) ==
                groupByCols.end()) continue;
            const Expr* input = comparison->right.get();
            std::string sign;
            if (const auto* unary = dynamic_cast<const UnaryOpExpr*>(input)) {
                if (unary->op != "+" && unary->op != "-") continue;
                sign = unary->op;
                input = unary->operand.get();
            }
            const auto* literal = dynamic_cast<const LiteralExpr*>(input);
            if (!literal || literal->preparedSubquery || !literal->typeName.empty()) continue;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName != colName) continue;
                std::string value = sign + literal->value;
                const bool valueIsNull = SQLParser::toLower(value) == "null";
                if (value.size() >= 2 && value.front() == '\'' &&
                    value.back() == '\'') {
                    std::string decoded;
                    for (size_t j = 1; j + 1 < value.size(); ++j) {
                        decoded.push_back(value[j]);
                        if (value[j] == '\'' && j + 2 < value.size() &&
                            value[j + 1] == '\'') ++j;
                    }
                    value = std::move(decoded);
                }
                groupHavings.push_back(
                    {i, comparison->op,
                     std::move(value), valueIsNull});
                break;
            }
        }
    }

    // Evaluate HAVING condition for a group
    auto evalHaving = [&](const HavingCond& h, const std::vector<int64_t>& gids) -> bool {
        std::string aggVal = computeAgg(gids, h.func, h.colName, {});
        if (h.op == "=") return aggVal == h.value;
        if (h.op == "!=") return aggVal != h.value;
        // Numeric comparison
        double a = 0, v = 0;
        try { a = std::stod(aggVal); } catch (...) {}
        try { v = std::stod(h.value); } catch (...) {}
        if (h.op == ">") return a > v;
        if (h.op == "<") return a < v;
        if (h.op == ">=") return a >= v;
        if (h.op == "<=") return a <= v;
        return true;
    };

    // Build result rows
    for (const auto& kv : groups) {
        const auto& gids = kv.second;

        // Apply HAVING
        bool pass = true;
        for (const auto& h : havings) {
            if (!evalHaving(h, gids)) { pass = false; break; }
        }
        if (pass && !groupHavings.empty()) {
            std::string sourceRow;
            if (gids.empty() || !readRowByRid(pa, gids.front(), sourceRow, tbl)) {
                pass = false;
            } else {
                NullRowBinding binding(this, dbname, tablename,
                                       gids.front(), tbl.len);
                for (const auto& h : groupHavings) {
                    bool leftIsNull = false;
                    const std::string left =
                        logicalValue(sourceRow, h.columnIndex, &leftIsNull);
                    if (compareValues(tbl.cols[h.columnIndex], left,
                                      leftIsNull, h.value, h.valueIsNull,
                                      h.op) != PredicateTruth::True) {
                        pass = false;
                        break;
                    }
                }
            }
        }
        if (!pass) continue;

        std::string row;
        // Keys are not display values. Read the first member to preserve its
        // original scale, physical NULL bit, and empty composite cells.
        if (!groupIdxs.empty()) {
            std::string sourceRow;
            if (gids.empty() || !readRowByRid(pa, gids.front(), sourceRow, tbl)) continue;
            NullRowBinding binding(this, dbname, tablename, gids.front(), tbl.len);
            for (size_t i = 0; i < groupIdxs.size(); ++i) {
                if (i > 0) row += ' ';
                bool isNull = false;
                const std::string value = logicalValue(sourceRow, groupIdxs[i], &isNull);
                row += isNull ? "NULL" : value;
            }
        }
        row += ' ';
        for (const auto& item : items) {
            row += computeAgg(gids, item.func, item.arg, item.filterConds) + ' ';
        }
        result.push_back(row);
    }
    lockManager_.unlock(tablename);
    return result;
}

// ========================================================================
// Grouping Sets / ROLLUP / CUBE aggregate
// ========================================================================

std::vector<std::string> StorageEngine::groupAggregateSets(
    const std::string& dbname, const std::string& tablename,
    const std::vector<std::string>& conditions,
    const std::vector<AggItem>& items,
    const std::vector<std::string>& allGroupByCols,
    const std::vector<std::vector<std::string>>& groupingSets,
    const std::vector<std::string>& havingConds) {
    std::vector<std::string> result;
    if (!tableExists(dbname, tablename)) return result;
    if (!lockManager_.lockShared(tablename)) return result;

    TableSchema tbl = getTableSchema(dbname, tablename);

    // Map all GROUP BY columns to indices
    std::vector<size_t> allGroupIdxs;
    for (const auto& gcol : allGroupByCols) {
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == gcol) { allGroupIdxs.push_back(i); break; }
        }
    }
    if (allGroupIdxs.size() != allGroupByCols.size()) {
        lockManager_.unlock(tablename);
        return result;
    }

    PageAllocator* pa = getPageAllocator(dbname, tablename);
    const auto logicalValue = [&](const std::string& row, size_t columnIndex,
                                  bool* valueIsNull = nullptr) {
        return extractColumnValue(
            row, tbl, columnIndex, dbname, true, valueIsNull);
    };
    auto conds = parseConditions(conditions);
    std::vector<int64_t> matchIds;
    bool scanFailed = false;
    bool indexReadFailed = false;
    if (conds.empty()) {
        if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId, [[maybe_unused]] const char* data, [[maybe_unused]] size_t len) {
            matchIds.push_back(encodeRid(pageId, slotId));
        })) scanFailed = true;
    } else {
        auto ids = filterRows(dbname, tablename, conds, nullptr, &scanFailed,
                              &indexReadFailed);
        matchIds.assign(ids.begin(), ids.end());
    }
    if (scanFailed) {
        lockManager_.unlock(tablename);
        if (indexReadFailed) {
            throw DbError("XX001", "B-tree index read failed for relation \"" +
                tablename + "\"");
        }
        return result;
    }

    // Reuse the aggregate implementation for HAVING-style filters.
    auto computeAgg = [&](const std::vector<int64_t>& gids,
                           const std::string& func, const std::string& colNameP,
                           const std::vector<std::string>& filterConds = {}) -> std::string {
    std::string colName = colNameP;
    bool aggDistinct = false;
    std::string aggSep = (func == "string_agg" || func == "group_concat" || func == "array_agg")
                          ? extractAggSep(colName, aggDistinct) : std::string(",");
        bool isDistinctCount = (func == "count" && colName.size() > 9 && colName.substr(0, 9) == "distinct ");
        std::string actualColName = isDistinctCount ? colName.substr(9) : colName;
        bool isJsonAgg = (func == "json_agg" || func == "jsonb_agg");
        bool isArrayAgg = (func == "array_agg");
        bool isPercentile = (func == "percentile_cont" || func == "percentile_disc");
        double pctFraction = 0.5;
        std::string pctColName = colName;
        if (isPercentile) {
            auto comma = colName.find(',');
            if (comma != std::string::npos) {
                pctFraction = std::stod(colName.substr(0, comma));
                pctColName = colName.substr(comma + 1);
            }
        }
        bool isBoolAnd = (func == "bool_and" || func == "every");
        bool isBoolOr = (func == "bool_or");
        bool boolResult = isBoolAnd ? true : false;
        bool boolSeen = false;
        std::vector<std::string> orderedVals;
        std::unordered_map<std::string, int64_t> freqMap;
        size_t colIdx = tbl.len;
        bool isInt = false, isDate = false;
        // Exact-decimal accumulation for numeric columns (PG avg/sum of
        // numeric must not lose fraction digits).
        dbms::Numeric exactSum(0);
        bool exactSumOk = true;
        int64_t exactCount = 0;
        if (func != "count" || actualColName != "*") {
            std::string lookupCol = isPercentile ? pctColName : actualColName;
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == lookupCol) {
                    colIdx = i;
                    // Fixed-width numeric storage is obvious, but numeric/
                    // decimal/float columns are string-backed (variable
                    // length) and must still aggregate numerically
                    // (sum/avg), not lexically (min/max only).
                    const std::string& dt = tbl.cols[i].dataType;
                    const std::string dtl = [&dt] { std::string s = dt; for (char& ch : s) ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch))); return s; }();
                    const bool numericType = dtl != "char" && dtl != "varchar" &&
                                             dtl != "text" && dtl != "date" && dtl != "time" &&
                                             dtl != "timestamp" && dtl != "timestamptz" &&
                                             dtl.rfind("char(", 0) != 0;
                    isInt = numericType || (!tbl.cols[i].isVariableLength && dtl != "char" && dtl != "date");
                    isDate = (dtl == "date");
                    // isChar removed (unused)
                    break;
                }
            }
        }
        // Aggregate over an arithmetic expression (see aggregate()).
        const bool aggArgExpr = (colIdx >= tbl.len) && !isPercentile &&
            (func == "sum" || func == "avg" || func == "min" || func == "max" ||
             func == "count") &&
            aggArgIsExpression(isPercentile ? pctColName : actualColName);
        std::string aggExprText = aggArgExpr ? (isPercentile ? pctColName : actualColName) : "";
        int64_t count = 0, sum = 0;
        bool hasMax = false, hasMin = false;
        std::string maxStr, minStr;
        int64_t maxInt = 0, minInt = 0;
        Date maxDate, minDate;
        std::string groupConcat;
        std::unordered_set<std::string> groupSeen;
        bool groupConcatFirst = true;
        std::vector<std::string> jsonAggVals;
        std::vector<std::string> arrayAggVals;
std::unordered_set<std::string> arraySeen;

        if (isDistinctCount) {
            const auto parsedFilters = parseConditions(filterConds);
            std::set<std::string> distinctVals;
            for (int64_t rid : gids) {
                std::string row;
                if (!readRowByRid(pa, rid, row, tbl)) continue;
                NullRowBinding nbD(this, dbname, tablename, rid, tbl.len);
                bool passes = true;
                for (const auto& filter : parsedFilters) {
                    if (!evalConditionOnRow(filter, row, tbl)) {
                        passes = false;
                        break;
                    }
                }
                if (!passes) continue;
                if (colIdx >= tbl.len) continue;
                bool valueIsNull = false;
                std::string val = logicalValue(
                    row, colIdx, &valueIsNull);
                if (!valueIsNull)
                    distinctVals.insert(canonicalColumnKeyValue(tbl.cols[colIdx], val));
            }
            count = static_cast<int64_t>(distinctVals.size());
        } else {
            auto parsedFilters = parseConditions(filterConds);
            for (int64_t rid : gids) {
                std::string row;
                if (!readRowByRid(pa, rid, row, tbl)) continue;
                NullRowBinding nullBinding(
                    this, dbname, tablename, rid, tbl.len);
                if (!parsedFilters.empty()) {
                    bool pass = true;
                    for (const auto& fc : parsedFilters) {
                        if (!evalConditionOnRow(fc, row, tbl)) { pass = false; break; }
                    }
                    if (!pass) continue;
                }
                if (func == "count") {
                    if (colName == "*") { count++; continue; }
                    if (colIdx >= tbl.len) continue;
                    // PG count(col) skips only NULL rows; empty strings count.
                    if (tbl.cols[colIdx].generatedKind != 'v' &&
                        dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, colIdx)) continue;
                    bool valueIsNull = false;
                    (void)logicalValue(row, colIdx, &valueIsNull);
                    if (valueIsNull) continue;
                    count++;
                } else if (func == "group_concat" || func == "string_agg") {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    if (val.empty()) continue;
                    if (aggDistinct && groupSeen.count(val)) continue;
                    groupSeen.insert(val);
                    if (!groupConcatFirst) groupConcat += aggSep;
                    groupConcat += val;
                    groupConcatFirst = false;
                } else if (isJsonAgg) {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    jsonAggVals.push_back(val);
                } else if (isArrayAgg) {
                    if (colIdx >= tbl.len) continue;
                    std::string val = logicalValue(row, colIdx);
                    if (aggDistinct && arraySeen.count(val)) continue;
                    arraySeen.insert(val);
                    arrayAggVals.push_back(val);
                } else {
                    std::string val;
                    if (aggArgExpr) {
                        auto getVal = [&](const std::string& tok) -> std::string {
                            for (size_t ci2 = 0; ci2 < tbl.len; ++ci2)
                                if (tbl.cols[ci2].dataName == tok)
                                    return logicalValue(row, ci2);
                            if (tok.size() >= 2 && tok.front() == '\'' && tok.back() == '\'')
                                return tok.substr(1, tok.size() - 2);
                            return tok;
                        };
                        val = evalAggArgExpr(aggExprText, getVal);
                    } else {
                        if (colIdx >= tbl.len) continue;
                        val = logicalValue(row, colIdx);
                    }
                    if (isInt || aggArgExpr) {
                        const auto parsed = parseStoredInteger(val);
                        if (!parsed) continue;
                        const int64_t num = *parsed;
                        if (func == "sum" || func == "avg") {
                            ++count;
                            exactSum = exactSum + dbms::Numeric(val);
                            ++exactCount;
                        }
                        if (func == "max") { if (!hasMax || num > maxInt) { maxInt = num; hasMax = true; } }
                        if (func == "min") { if (!hasMin || num < minInt) { minInt = num; hasMin = true; } }
                    } else if (isDate) {
                        Date d = val.empty() ? Date{} : Date(val.c_str());
                        if (d.year == 0) continue;
                        if (func == "max") { if (!hasMax || d > maxDate) { maxDate = d; hasMax = true; } }
                        if (func == "min") { if (!hasMin || d < minDate) { minDate = d; hasMin = true; } }
                    } else {
                        if (val.empty()) continue;
                        if (func == "max") { if (!hasMax || val > maxStr) { maxStr = val; hasMax = true; } }
                        if (func == "min") { if (!hasMin || val < minStr) { minStr = val; hasMin = true; } }
                    }
                }
            }
        }
        if (func == "count") return transstr(count);
        if (func == "sum") {
            if (exactSumOk && exactCount == count && count > 0) {
                try { return exactSum.toString(); } catch (...) {}
            }
            return transstr(sum);
        }
        if (func == "avg") {
            if (count == 0) return "0";
            // PG avg(numeric): exact numeric division (select_div_scale).
            if (exactSumOk && exactCount == count) {
                try { return (exactSum / dbms::Numeric(count)).toString(); }
                catch (...) {}
            }
            return std::to_string(static_cast<double>(sum) / count);
        }
        if (func == "group_concat" || func == "string_agg") return groupConcat.empty() ? "NULL" : groupConcat;
        if (isJsonAgg) {
            std::string json = "[";
            bool first = true;
            for (const auto& v : jsonAggVals) {
                if (!first) json += ",";
                if (v.empty()) {
                    json += "null";
                } else if (isInt || v == "true" || v == "false" || v == "null") {
                    json += v;
                } else {
                    std::string esc;
                    for (char c : v) { if (c == '"' || c == '\\') esc += '\\'; esc += c; }
                    json += '"' + esc + '"';
                }
                first = false;
            }
            json += "]";
            return json;
        }
        if (isArrayAgg) {

            // PG array_agg(DISTINCT ...) sorts the deduplicated values.
            if (aggDistinct && !arrayAggVals.empty()) {
            bool allNum = true;
            for (const auto& sv : arrayAggVals)
            if (sv.empty() || sv.find_first_not_of("0123456789.+-eE") != std::string::npos)
            { allNum = false; break; }
            if (allNum)
            std::sort(arrayAggVals.begin(), arrayAggVals.end(),
            [](const std::string& a, const std::string& b) {
            double da = 0, db = 0;
            try { da = std::stod(a); db = std::stod(b); } catch (...) {}
            return da < db;
            });
            else std::sort(arrayAggVals.begin(), arrayAggVals.end());
            }std::string arr = "{";
            bool first = true;
            for (const auto& v : arrayAggVals) { if (!first) arr += ","; arr += v; first = false; }
            arr += "}";
            return arr;
        }
        if (func == "max") {
            if (!hasMax) return "NULL";
            if (isInt || aggArgExpr) return transstr(maxInt);
            if (isDate) return str(maxDate);
            return maxStr;
        }
        if (func == "min") {
            if (!hasMin) return "NULL";
            if (isInt || aggArgExpr) return transstr(minInt);
            if (isDate) return str(minDate);
            return minStr;
        }
        if (isPercentile) {
            if (orderedVals.empty()) return "NULL";
            std::sort(orderedVals.begin(), orderedVals.end(),
                [](const std::string& a, const std::string& b) {
                    bool aNum = !a.empty() && (std::isdigit(static_cast<unsigned char>(a[0])) || a[0] == '-' || a[0] == '+');
                    bool bNum = !b.empty() && (std::isdigit(static_cast<unsigned char>(b[0])) || b[0] == '-' || b[0] == '+');
                    if (aNum && bNum) return std::stod(a) < std::stod(b);
                    return a < b;
                });
            size_t n = orderedVals.size();
            if (func == "percentile_disc") {
                size_t idx = static_cast<size_t>(std::ceil(pctFraction * n));
                if (idx > 0) idx--;
                return orderedVals[idx];
            } else {
                double idx = pctFraction * (n - 1);
                size_t lo = static_cast<size_t>(std::floor(idx));
                size_t hi = static_cast<size_t>(std::ceil(idx));
                if (lo == hi || hi >= n) return orderedVals[lo];
                bool numeric = !orderedVals[lo].empty() && !orderedVals[hi].empty() &&
                    (std::isdigit(static_cast<unsigned char>(orderedVals[lo][0])) || orderedVals[lo][0] == '-' || orderedVals[lo][0] == '+') &&
                    (std::isdigit(static_cast<unsigned char>(orderedVals[hi][0])) || orderedVals[hi][0] == '-' || orderedVals[hi][0] == '+');
                if (numeric) {
                    double a = std::stod(orderedVals[lo]);
                    double b = std::stod(orderedVals[hi]);
                    double frac = idx - lo;
                    std::ostringstream oss;
                    oss << (a + frac * (b - a));
                    return oss.str();
                }
                return orderedVals[lo];
            }
        }
        return "";
    };

    struct HavingCond {
        std::string func, colName, op, value;
    };
    std::vector<HavingCond> havings;
    for (const auto& hc : havingConds) {
        if (hc.empty()) continue;
        std::string s = hc;
        size_t lp = s.find('(');
        size_t rp = s.find(')');
        if (lp != std::string::npos && rp != std::string::npos && rp > lp + 1) {
            HavingCond h;
            h.func = s.substr(0, lp);
            h.colName = s.substr(lp + 1, rp - lp - 1);
            std::string rest = trim(s.substr(rp + 1));
            size_t opEnd = 0;
            while (opEnd < rest.size() && (rest[opEnd] == '<' || rest[opEnd] == '>' || rest[opEnd] == '=' || rest[opEnd] == '!')) ++opEnd;
            if (opEnd > 0) {
                h.op = rest.substr(0, opEnd);
                h.value = trim(rest.substr(opEnd));
                havings.push_back(h);
            }
        }
    }
    auto evalHaving = [&](const HavingCond& h, const std::vector<int64_t>& gids) -> bool {
        std::string aggVal = computeAgg(gids, h.func, h.colName, {});
        if (h.op == "=") return aggVal == h.value;
        if (h.op == "!=") return aggVal != h.value;
        double a = 0, v = 0;
        try { a = std::stod(aggVal); } catch (...) {}
        try { v = std::stod(h.value); } catch (...) {}
        if (h.op == ">") return a > v;
        if (h.op == "<") return a < v;
        if (h.op == ">=") return a >= v;
        if (h.op == "<=") return a <= v;
        return true;
    };

    // Process each grouping set
    for (const auto& gset : groupingSets) {
        std::vector<size_t> setIdxs;
        for (const auto& col : gset) {
            for (size_t i = 0; i < tbl.len; ++i) {
                if (tbl.cols[i].dataName == col) { setIdxs.push_back(i); break; }
            }
        }

        auto readSetKey = [&](int64_t rid) -> std::string {
            std::string row;
            if (!readRowByRid(pa, rid, row, tbl)) return "";
            NullRowBinding nullBinding(
                this, dbname, tablename, rid, tbl.len);
            std::string key;
            for (size_t idx : setIdxs) {
                bool isNull = false;
                const std::string value = logicalValue(row, idx, &isNull);
                key += groupingValueKey(tbl.cols[idx], value, isNull);
            }
            return key;
        };

        std::map<std::string, std::vector<int64_t>> groups;
        for (int64_t rowIdx : matchIds) {
            groups[readSetKey(rowIdx)].push_back(rowIdx);
        }

        for (const auto& kv : groups) {
            const auto& gids = kv.second;
            bool pass = true;
            for (const auto& h : havings) {
                if (!evalHaving(h, gids)) { pass = false; break; }
            }
            if (!pass) continue;

            // Recover representative cells, never decode the equality key.
            std::map<std::string, std::string> colValues;
            if (!setIdxs.empty()) {
                std::string sourceRow;
                if (gids.empty() || !readRowByRid(pa, gids.front(), sourceRow, tbl)) continue;
                NullRowBinding binding(this, dbname, tablename, gids.front(), tbl.len);
                for (size_t idx : setIdxs) {
                    bool isNull = false;
                    const std::string value = logicalValue(sourceRow, idx, &isNull);
                    colValues[tbl.cols[idx].dataName] = isNull ? "NULL" : value;
                }
            }

            std::string row;
            size_t colPos = 0;
            for (const auto& col : allGroupByCols) {
                // Separator BETWEEN cells (by position, not by accumulated
                // text): an empty first cell keeps its leading slot as a
                // leading space.
                if (colPos > 0) row += ' ';
                auto it = colValues.find(col);
                // A column absent from this grouping set is NULL in PG (ROLLUP/
                // CUBE grand-total rows); emit the NULL token so the wire sends
                // -1 and sorts apply NULLS LAST/FIRST correctly.
                if (it != colValues.end()) row += it->second;
                else row += "NULL";
                ++colPos;
            }
            row += ' ';
            for (const auto& item : items) {
                // grouping(<col>): 1 when the column is absent from this
                // grouping set (rolled up to NULL by the set semantics), 0
                // when it is a real grouping column of this row.
                if (item.func == "grouping" || item.func == "grouping_id") {
                    // Bitmask over comma-separated arguments: bit for arg i
                    // is 1 << (n-1-i) (PG: grouping(a,b) -> a=2, b=1), set
                    // when that column is absent from this grouping set.
                    std::vector<std::string> gargs;
                    {
                        std::stringstream gs_(item.arg);
                        std::string gp_;
                        while (std::getline(gs_, gp_, ',')) {
                            size_t a_ = 0, b_ = gp_.size();
                            while (a_ < b_ && std::isspace(static_cast<unsigned char>(gp_[a_]))) ++a_;
                            while (b_ > a_ && std::isspace(static_cast<unsigned char>(gp_[b_ - 1]))) --b_;
                            gargs.push_back(gp_.substr(a_, b_ - a_));
                        }
                    }
                    int mask = 0;
                    for (size_t gi_ = 0; gi_ < gargs.size(); ++gi_) {
                        if (colValues.find(gargs[gi_]) == colValues.end())
                            mask |= 1 << (gargs.size() - 1 - gi_);
                    }
                    row += std::to_string(mask);
                    row += ' ';
                    continue;
                }
                row += computeAgg(gids, item.func, item.arg, item.filterConds) + ' ';
            }
            result.push_back(row);
        }
    }

    lockManager_.unlock(tablename);
    return result;
}

// ========================================================================
// Post-query ORDER BY expression sorting
// ========================================================================

std::vector<std::string> StorageEngine::sortByExpression(
    const std::string& dbname, const std::string& tablename,
    std::vector<std::string> rows,
    const std::vector<OrderBySpec>& exprSpecs) const {
    if (rows.empty() || exprSpecs.empty()) return rows;
    TableSchema tbl = getTableSchema(dbname, tablename);
    std::map<std::string, std::string> expressionTypeHints;
    for (size_t ci = 0; ci < tbl.len; ++ci)
        expressionTypeHints[tbl.cols[ci].dataName] = tbl.cols[ci].dataType;
    std::vector<int64_t> sliceCounts(exprSpecs.size(), 0);
    for (size_t i = 0; i < exprSpecs.size(); ++i) {
        if (exprSpecs[i].isExpression &&
            (exprSpecs[i].exprFunc == "left" ||
             exprSpecs[i].exprFunc == "right") &&
            !parseTextSortCount(exprSpecs[i].exprArg2, sliceCounts[i]))
            throw DbError("0A000", "non-constant text slice count in ORDER BY");
    }
    std::vector<Column> comparisonColumns;
    comparisonColumns.reserve(exprSpecs.size());
    for (const auto& spec : exprSpecs) {
        Column comparisonColumn;
        comparisonColumn.dataType = "text";
        comparisonColumn.isVariableLength = true;
        if (spec.exprFunc == "upper" || spec.exprFunc == "lower" ||
            spec.exprFunc.empty()) {
            for (size_t columnIndex = 0; columnIndex < tbl.len;
                 ++columnIndex) {
                if (tbl.cols[columnIndex].dataName == spec.exprArg) {
                    comparisonColumn = tbl.cols[columnIndex];
                    break;
                }
            }
        }
        if (isEvaluatedNumericSort(spec)) {
            const std::string resultType = ExprHelper::inferResultType(
                spec.expressionSql, expressionTypeHints);
            comparisonColumn.dataType =
                resultType == "double precision" ? "double" :
                resultType == "real" ? "float" :
                (resultType == "integer" || resultType == "bigint" ||
                 resultType == "smallint") ? "int" : "numeric";
            comparisonColumn.isVariableLength =
                comparisonColumn.dataType == "numeric";
        } else if (isEvaluatedPolymorphicSort(spec)) {
            setPolymorphicSortType(
                comparisonColumn,
                ExprHelper::inferResultType(spec.expressionSql,
                                            expressionTypeHints));
        } else if (!spec.expressionSql.empty() &&
                   (spec.exprFunc == "date_trunc" ||
                    spec.exprFunc == "to_date" ||
                    spec.exprFunc == "to_timestamp")) {
            const std::string resultType = ExprHelper::inferResultType(
                spec.expressionSql, expressionTypeHints);
            if (resultType == "date" ||
                resultType == "timestamp" ||
                resultType == "timestamptz") {
                comparisonColumn.dataType = resultType;
                comparisonColumn.isVariableLength = false;
            }
        }
        if (!spec.collation.empty()) {
            comparisonColumn.collation =
                collation::normalizeName(spec.collation) == "binary"
                    ? "C" : spec.collation;
            TableSchema collationProbe;
            collationProbe.len = 1;
            collationProbe.cols[0] = comparisonColumn;
            if (resolveTableCollations(
                    *this, dbname, collationProbe) != DBStatus::OK) {
                return rows;
            }
            comparisonColumn = std::move(collationProbe.cols[0]);
        }
        comparisonColumns.push_back(std::move(comparisonColumn));
    }

    struct SortRow {
        std::string rowStr;
        std::vector<std::string> exprVals;
        std::vector<bool> exprNulls;
    };
    std::vector<SortRow> sortRows;
    for (const auto& rowStr : rows) {
        SortRow sr;
        sr.rowStr = rowStr;
        // Parse row into column values
        std::map<std::string, std::string> rowData;
        std::stringstream ss(rowStr);
        std::string val;
        for (size_t i = 0; i < tbl.len && ss >> val; ++i) {
            rowData[tbl.cols[i].dataName] = val;
        }
        for (size_t keyIndex = 0; keyIndex < exprSpecs.size(); ++keyIndex) {
            const auto& spec = exprSpecs[keyIndex];
            std::string ev;
            bool expressionIsNull = false;
            auto getCol = [&](const std::string& name) -> std::string {
                auto it = rowData.find(name);
                return (it != rowData.end()) ? it->second : "";
            };
            std::string argVal = getCol(spec.exprArg);
            if (!spec.expressionSql.empty()) {
                const auto evaluated = ExprHelper::evalStringWithNulls(
                    spec.expressionSql, rowData, {}, expressionTypeHints,
                    dbname, "", const_cast<StorageEngine*>(this));
                if (!evaluated.ok) {
                    if (!evaluated.sqlState.empty())
                        throw DbError(evaluated.sqlState, evaluated.error);
                    throw std::runtime_error(evaluated.error.empty()
                        ? "unsupported ORDER BY expression (SQLSTATE 0A000)"
                        : evaluated.error);
                }
                ev = evaluated.value;
                expressionIsNull = evaluated.isNull;
                if (spec.collation.empty() &&
                    !evaluated.collation.empty()) {
                    auto& comparisonColumn = comparisonColumns[keyIndex];
                    if (comparisonColumn.collation.empty()) {
                        comparisonColumn.collation = evaluated.collation;
                        TableSchema collationProbe;
                        collationProbe.len = 1;
                        collationProbe.cols[0] = comparisonColumn;
                        if (resolveTableCollations(
                                *this, dbname, collationProbe) !=
                            DBStatus::OK)
                            return rows;
                        comparisonColumn =
                            std::move(collationProbe.cols[0]);
                    }
                }
            } else if (spec.exprFunc == "length") {
                ev = std::to_string(argVal.size());
            } else if (spec.exprFunc == "upper") {
                ev = argVal;
                for (char& c : ev) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
            } else if (spec.exprFunc == "lower") {
                ev = argVal;
                for (char& c : ev) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            } else if (spec.exprFunc == "left") {
                ev = leftSortTextValue(argVal, sliceCounts[keyIndex]);
            } else if (spec.exprFunc == "right") {
                ev = rightSortTextValue(argVal, sliceCounts[keyIndex]);
            } else if (spec.exprFunc == "reverse") {
                ev = reverseSortTextValue(argVal);
            } else if (spec.exprFunc == "abs") {
                try { ev = std::to_string(std::llabs(std::stoll(argVal))); } catch (...) { ev = "0"; }
            } else if (spec.exprFunc == "add") {
                try {
                    int64_t a = std::stoll(argVal);
                    int64_t b = std::stoll(spec.exprArg2);
                    ev = std::to_string(a + b);
                } catch (...) { ev = argVal; }
            } else if (spec.exprFunc == "sub") {
                try {
                    int64_t a = std::stoll(argVal);
                    int64_t b = std::stoll(spec.exprArg2);
                    ev = std::to_string(a - b);
                } catch (...) { ev = argVal; }
            } else {
                ev = argVal;
            }
            sr.exprVals.push_back(ev);
            sr.exprNulls.push_back(spec.expressionSql.empty()
                                       ? ev.empty() : expressionIsNull);
        }
        sortRows.push_back(std::move(sr));
    }

    std::stable_sort(sortRows.begin(), sortRows.end(),
        [&](const SortRow& a, const SortRow& b) {
            for (size_t i = 0; i < exprSpecs.size(); ++i) {
                const auto& spec = exprSpecs[i];
                const std::string& av = a.exprVals[i];
                const std::string& bv = b.exprVals[i];
                bool aNull = a.exprNulls[i];
                bool bNull = b.exprNulls[i];
                if (aNull && bNull) continue;
                if (aNull) return spec.nullsFirst;
                if (bNull) return !spec.nullsFirst;
                bool less = false, greater = false;
                if (!spec.expressionSql.empty()) {
                    less = compareValues(comparisonColumns[i], av, false,
                                         bv, false, "<") ==
                           PredicateTruth::True;
                    greater = compareValues(comparisonColumns[i], av, false,
                                            bv, false, ">") ==
                              PredicateTruth::True;
                } else if (
                    spec.exprFunc == "left" || spec.exprFunc == "right" ||
                    spec.exprFunc == "reverse" ||
                    !comparisonColumns[i].collation.empty()) {
                    const int comparison = compareTextValues(
                        comparisonColumns[i], av, bv);
                    less = comparison < 0;
                    greater = comparison > 0;
                } else {
                    // Try numeric comparison first.
                    try {
                        int64_t na = std::stoll(av);
                        int64_t nb = std::stoll(bv);
                        less = na < nb;
                        greater = na > nb;
                    } catch (...) {
                        less = av < bv;
                        greater = av > bv;
                    }
                }
                if (less) return spec.ascending;
                if (greater) return !spec.ascending;
            }
            return false;
        });

    std::vector<std::string> result;
    for (auto& sr : sortRows) result.push_back(std::move(sr.rowStr));
    return result;
}

// ========================================================================
// JOIN implementation
// ========================================================================

std::string StorageEngine::joinRangeColumnKey(const std::string& range,
                                              const std::string& column,
                                              bool encoded) {
    if (!encoded) return range + "." + column;
    static constexpr char hex[] = "0123456789abcdef";
    std::string key = range + "._";
    for (unsigned char byte : column) {
        key += hex[byte >> 4];
        key += hex[byte & 15];
    }
    return key;
}

static bool isJoinComparisonOperator(const std::string& op) {
    return op == "=" || op == "!=" || op == "<>" || op == "<" ||
           op == ">" || op == "<=" || op == ">=";
}

// Preserve RHS identity before the legacy decoder removes literal quotes.
// A datum equal to a range-qualified key is still a datum, not a column.
// Keep this carrier private: the ordinary Condition/native API stays intact.
struct JoinCondition : StorageEngine::Condition {
    bool valueIsLiteral = false;
    bool valueIsNull = false;
    struct Binding {
        bool isLeft;
        size_t column;
        std::string key;
        std::string type;
        std::string collation;
    };
    std::shared_ptr<Stmt> expressionOwner;
    Expr* expression = nullptr;
    std::shared_ptr<ExprEvaluator> evaluator;
    std::vector<Binding> bindings;
};

static std::vector<JoinCondition> parseJoinConditions(
    const std::vector<std::string>& inputs) {
    std::vector<JoinCondition> result;
    for (const auto& raw : inputs) {
        auto conditions = StorageEngine::parseConditions({raw});
        for (auto& condition : conditions) {
            JoinCondition parsed;
            static_cast<StorageEngine::Condition&>(parsed) = std::move(condition);
            if (!storedPatternOperator(parsed.op).empty()) {
                parsed.valueIsLiteral=parsed.decodedLiteralRhs;
                parsed.valueIsNull=parsed.patternIsNull;
            }
            if (parsed.op == "typedexpr") {
                SQLParser parser;
                auto expression = parser.parse("SELECT " + parsed.value);
                auto* select = expression.success
                    ? dynamic_cast<SelectStmt*>(expression.stmt.get()) : nullptr;
                if (!select || select->selectList.size() != 1 || select->fromClause ||
                    !select->selectList.front().expr)
                    throw DbError("42601", "invalid typed JOIN predicate");
                parsed.expression = select->selectList.front().expr.get();
                parsed.expressionOwner = std::move(expression.stmt);
            }
            if (isJoinComparisonOperator(parsed.op)) {
                const bool apiValue = raw.rfind("apicond ", 0) == 0;
                const std::string input = apiValue ? raw.substr(8) : raw;
                const size_t space = input.find(' ');
                if (space != std::string::npos) {
                    SQLParser parser;
                    const auto rhs = parser.parse("SELECT " + trim(input.substr(space + 1)));
                    const auto* select = rhs.success
                        ? dynamic_cast<const SelectStmt*>(rhs.stmt.get()) : nullptr;
                    const Expr* operand = select && select->selectList.size() == 1
                        ? select->selectList[0].expr.get() : nullptr;
                    if (const auto* sign = dynamic_cast<const UnaryOpExpr*>(operand)) {
                        if (sign->op == "+" || sign->op == "-") operand = sign->operand.get();
                    }
                    const auto* literal = dynamic_cast<const LiteralExpr*>(operand);
                    parsed.valueIsLiteral = apiValue || literal;
                    parsed.valueIsNull = !apiValue && literal && literal->value == "null";
                }
            }
            result.push_back(std::move(parsed));
        }
    }
    return result;
}

// Prepare value references once, before any row pair is evaluated.  The
// carrier contains resolved range identities; positional keys prevent the
// evaluator's legacy case folding from merging id/"ID" or repeated ranges.
static void prepareJoinExpressions(
    std::vector<JoinCondition>& conditions,
    const TableSchema& left, const TableSchema& right,
    const std::string& leftRange, const std::string& rightRange,
    bool encoded, const std::string& database, StorageEngine* engine) {
    for (auto& condition : conditions) {
        if (!storedPatternOperator(condition.op).empty()) {
            const auto find = [&](const std::string& key) -> const Column* {
                for (int side=0;side<2;++side) {
                    const auto& table=side==0 ? left : right;
                    const auto& range=side==0 ? leftRange : rightRange;
                    for (size_t i=0;i<table.len;++i)
                        if (key==table.cols[i].dataName ||
                            key==StorageEngine::joinRangeColumnKey(range,table.cols[i].dataName,encoded))
                            return &table.cols[i];
                }
                return nullptr;
            };
            const auto* column=find(condition.colName);
            if (!column) throw DbError("42703", "pattern column does not exist");
            if (!condition.valueIsLiteral) if (const auto* pattern=find(condition.value))
                condition.patternType=pattern->dataType+(pattern->isArray ? "[]" : "");
            if (!condition.patternEscapeColumn.empty()) {
                const auto* escape=find(condition.patternEscapeColumn);
                if (!escape) throw DbError("42703", "pattern escape column does not exist");
                condition.patternEscapeType=escape->dataType+(escape->isArray ? "[]" : "");
            }
            validateStoredPatternTypes(*column,condition);
        }
        if (condition.op != "typedexpr") continue;
        condition.evaluator = std::make_shared<ExprEvaluator>();
        condition.evaluator->setCurrentDB(database);
        const std::string username = currentSession() ? currentSession()->username : "";
        condition.evaluator->registerFunction("current_user", [username](const std::vector<ExprValue>&) {
            return ExprValue("name", username, username.empty());
        }, 's');
        condition.evaluator->registerFunction("session_user", [username](const std::vector<ExprValue>&) {
            return ExprValue("name", username, username.empty());
        }, 's');
        std::function<void(Expr*)> bind = [&](Expr* expression) {
            if (!expression) throw DbError("42601", "missing JOIN predicate operand");
            if (auto* reference = dynamic_cast<ColumnRefExpr*>(expression)) {
                if (!reference->schema.empty())
                    throw DbError("42P01", "missing FROM-clause entry for table " + reference->table);
                size_t matches = 0, index = 0;
                bool isLeft = false;
                for (int side = 0; side < 2; ++side) {
                    const auto& table = side == 0 ? left : right;
                    const auto& range = side == 0 ? leftRange : rightRange;
                    for (size_t column = 0; column < table.len; ++column) {
                        const auto& name = table.cols[column].dataName;
                        const bool resolvedCarrier = reference->table.empty() &&
                            reference->column == StorageEngine::joinRangeColumnKey(range, name, encoded);
                        const bool sourceReference = (reference->table.empty() || reference->table == range) &&
                            reference->column == name;
                        if (resolvedCarrier || sourceReference) {
                            ++matches;
                            isLeft = side == 0;
                            index = column;
                        }
                    }
                }
                if (matches > 1) throw DbError("42702", "column reference is ambiguous: " + reference->column);
                if (matches == 0) {
                    if (!reference->table.empty() && reference->table != leftRange && reference->table != rightRange)
                        throw DbError("42P01", "missing FROM-clause entry for table " + reference->table);
                    throw DbError("42703", "column does not exist: " + reference->column);
                }
                const auto& column = (isLeft ? left : right).cols[index];
                const std::string key = "__dbms_join_value_" + std::to_string(condition.bindings.size());
                condition.bindings.push_back({isLeft, index, key,
                    ExprHelper::canonicalResultTypeName(column.dataType + (column.isArray ? "[]" : "")),
                    column.resolvedCollation.empty() ? column.collation : column.resolvedCollation});
                reference->column = key;
                reference->table.clear();
                reference->schema.clear();
            } else if (auto* unary = dynamic_cast<UnaryOpExpr*>(expression)) {
                bind(unary->operand.get());
                // A COLLATE label must be valid during preparation, including
                // zero-row joins; boolean result analysis may not visit it.
                if (unary->op.rfind("COLLATE ", 0) == 0) {
                    const auto name = ExprEvaluator::analyzeExplicitResultCollation(unary);
                    if (!collation::isValid(name))
                        throw DbError("42704", "collation does not exist: " + name);
                }
            } else if (auto* binary = dynamic_cast<BinaryOpExpr*>(expression)) {
                bind(binary->left.get());
                if (binary->op != "::" && binary->op != "COLLATE") bind(binary->right.get());
            } else if (auto* cast = dynamic_cast<CastExpr*>(expression)) {
                bind(cast->operand.get());
            } else if (auto* conditional = dynamic_cast<CaseExpr*>(expression)) {
                if (conditional->switchExpr) bind(conditional->switchExpr.get());
                for (auto& arm : conditional->whenClauses) {
                    bind(arm.first.get());
                    bind(arm.second.get());
                }
                if (conditional->elseExpr) bind(conditional->elseExpr.get());
            } else if (auto* call = dynamic_cast<FunctionCallExpr*>(expression)) {
                if (call->hasOver || call->distinct || call->filter ||
                    !call->orderBy.empty() || !call->namedArgs.empty())
                    throw DbError("0A000", "JOIN predicate requires a scalar function");
                static const std::set<std::string> syntaxFunctions = {"coalesce", "nullif", "greatest", "least"};
                if (!condition.evaluator->hasScalarFunction(call, engine) && !syntaxFunctions.count(call->funcName))
                    throw DbError("42883", "function does not exist: " + call->funcName);
                // The parser stores SQL EXTRACT's field as argument zero.
                // It is a label, unlike date_part's ordinary value argument.
                if (call->schema.empty() && SQLParser::toLower(call->funcName) == "extract" && !call->args.empty()) {
                    if (const auto* field = dynamic_cast<ColumnRefExpr*>(call->args.front().get());
                        field && field->table.empty() && field->schema.empty()) {
                        auto literal = std::make_unique<LiteralExpr>();
                        literal->typeName = "text";
                        literal->value = "'";
                        for (char c : field->column) {
                            literal->value += c;
                            if (c == '\'') literal->value += c;
                        }
                        literal->value += "'";
                        call->args.front() = std::move(literal);
                    }
                }
                for (auto& argument : call->args) bind(argument.get());
            } else if (expression->type != ExprType::Literal) {
                throw DbError("0A000", "unsupported typed JOIN expression");
            }
        };
        bind(condition.expression);
        condition.evaluator->bindScalarFunctions(condition.expression, engine);
        ExprEvaluator::analyzeExplicitResultCollation(condition.expression);
    }
}

template <typename ValueGetter>
static bool evaluateJoinExpression(const JoinCondition& condition, ValueGetter valueAt) {
    RowContext row;
    for (const auto& binding : condition.bindings) {
        bool isNull = false;
        const std::string value = valueAt(binding.isLeft, binding.column, isNull);
        ExprValue datum(binding.type,value,isNull);datum.collation=binding.collation;
        row.set(binding.key,std::move(datum));
    }
    if (const Session* session = currentSession()) {
        row.set("current_user", ExprValue("name", session->username, false));
        row.set("session_user", ExprValue("name", session->username, false));
    }
    ExprValue result;
    try {
        result = condition.evaluator->eval(condition.expression, row);
    } catch (const DbError&) {
        throw;
    } catch (const std::exception& error) {
        ExprEvalResult failure;
        failure.error = error.what();
        const auto mapped = plpgsqlScalarResult(failure);
        std::string message = mapped.message;
        if (mapped.sqlState != "XX000") message.erase(message.rfind("(SQLSTATE "));
        throw DbError(mapped.sqlState, trim(message));
    }
    if (ExprHelper::canonicalResultTypeName(result.typeName) != "boolean")
        throw DbError("42804", "JOIN ON expression must be type boolean");
    return !result.isNull && result.asBool();
}

// Legacy JOIN exits explicitly release their table locks. Typed predicates
// additionally propagate evaluator exceptions; release those locks on stack
// unwinding too, without changing the existing normal-return lock protocol.
class JoinExceptionLockRelease {
    std::function<void()> release_;
    int exceptionCount_ = std::uncaught_exceptions();
public:
    explicit JoinExceptionLockRelease(std::function<void()> release)
        : release_(std::move(release)) {}
    ~JoinExceptionLockRelease() {
        if (std::uncaught_exceptions() > exceptionCount_) release_();
    }
};

static bool joinValuePredicateMatches(
    const StorageEngine::Condition& condition, const Column& column,
    const std::string& value, bool valueIsNull,
    const std::string& comparisonValue, bool comparisonIsNull = false) {
    const std::string& op = condition.op;
    if (op == "isnull") return valueIsNull;
    if (op == "isnotnull") return !valueIsNull;
    if (!storedPatternOperator(op).empty())
        return storedPatternTruth(column,value,valueIsNull,comparisonValue,
                                  comparisonIsNull,condition) == StorageEngine::PredicateTruth::True;
    if (valueIsNull) return false;

    if (isJoinComparisonOperator(op)) {
        return StorageEngine::compareValues(
                   column, value, false, comparisonValue,
                   comparisonIsNull, op) ==
               StorageEngine::PredicateTruth::True;
    }
    if (op == "regexp" || op == "notregexp") {
        const bool matched = regexMatch(value, comparisonValue);
        return op == "notregexp" ? !matched : matched;
    }
    if (op == "contains") {
        std::string needle = comparisonValue;
        for (char& ch : needle) {
            ch = static_cast<char>(
                std::tolower(static_cast<unsigned char>(ch)));
        }
        const auto tokens = tokenizeText(value);
        return std::find(tokens.begin(), tokens.end(), needle) != tokens.end();
    }
    if (op == "between" || op == "notbetween") {
        const size_t separator = comparisonValue.find(' ');
        if (separator == std::string::npos) return false;
        const std::string lower = comparisonValue.substr(0, separator);
        const std::string upper = comparisonValue.substr(separator + 1);
        const auto lowerTruth = StorageEngine::compareValues(
            column, value, false, lower, false, ">=");
        const auto upperTruth = StorageEngine::compareValues(
            column, value, false, upper, false, "<=");
        if (lowerTruth == StorageEngine::PredicateTruth::Unknown ||
            upperTruth == StorageEngine::PredicateTruth::Unknown) {
            return false;
        }
        const bool atLeastLower =
            lowerTruth == StorageEngine::PredicateTruth::True;
        const bool atMostUpper =
            upperTruth == StorageEngine::PredicateTruth::True;
        const bool inRange = atLeastLower && atMostUpper;
        return op == "between" ? inRange : !inRange;
    }
    if (op == "in" || op == "notin") {
        bool matched = false;
        bool sawNull = false;
        std::istringstream values(comparisonValue);
        std::string candidate;
        while (values >> candidate) {
            std::string lowerCandidate = candidate;
            for (char& ch : lowerCandidate) {
                ch = static_cast<char>(
                    std::tolower(static_cast<unsigned char>(ch)));
            }
            if (lowerCandidate == "null" || lowerCandidate == "nil") {
                sawNull = true;
                continue;
            }
            if (StorageEngine::compareValues(
                    column, value, false, candidate, false, "=") ==
                StorageEngine::PredicateTruth::True) {
                matched = true;
                break;
            }
        }
        if (op == "in") return matched;
        return matched ? false : !sawNull;
    }

    // A parsed-but-unsupported predicate must never silently admit every row.
    return false;
}

static std::vector<JoinCondition> parseJoinOnConditions(
    const std::vector<std::string>& onConditions) {
    std::vector<std::string> ordinary;
    std::vector<JoinCondition> constants;
    for (const auto& condition : onConditions) {
        if (condition == "__join_full_once__") continue;
        if (condition == "__join_on_true__" ||
            condition == "__join_on_false__") {
            JoinCondition parsed;
            parsed.op = condition == "__join_on_true__"
                ? "jointrue" : "joinfalse";
            constants.push_back(std::move(parsed));
        } else {
            ordinary.push_back(condition);
        }
    }
    auto parsed = parseJoinConditions(ordinary);
    parsed.insert(parsed.end(), constants.begin(), constants.end());
    return parsed;
}

std::vector<std::string> StorageEngine::join(
    const std::string& dbname,
    const std::string& leftTable,
    const std::string& rightTable,
    const std::string& leftCol,
    const std::string& rightCol,
    const std::vector<std::string>& conditions,
    const std::set<std::string>& selectCols,
    std::vector<std::vector<std::string>>* structuredRows,
    std::vector<std::vector<bool>>* structuredNulls,
    const std::vector<std::string>& onConditions,
    const JoinRangeNames& rangeNames) {
    const std::string& leftRange = rangeNames.first.empty() ? leftTable : rangeNames.first;
    const std::string& rightRange = rangeNames.second.empty() ? rightTable : rangeNames.second;
    std::vector<std::string> result;
    if (structuredRows) structuredRows->clear();
    if (structuredNulls) structuredNulls->clear();
    if (!tableExists(dbname, leftTable) || !tableExists(dbname, rightTable)) return result;
    if (leftCol.empty() && rightCol.empty() && !onConditions.empty()) {
        std::vector<std::string> filters;
        for (const auto& condition : onConditions) {
            if (condition == "__join_on_false__") return result;
            if (condition != "__join_on_true__")
                filters.push_back(condition);
        }
        filters.insert(filters.end(), conditions.begin(), conditions.end());
        return crossJoin(dbname, leftTable, rightTable, filters, selectCols,
                         structuredRows, structuredNulls, rangeNames);
    }

    // Lock both tables in alphabetical order to avoid deadlock
    if (leftTable < rightTable) {
        if (!lockManager_.lockShared(leftTable)) return result;
        if (!lockManager_.lockShared(rightTable)) {
            lockManager_.unlock(leftTable);
            return result;
        }
    } else {
        if (!lockManager_.lockShared(rightTable)) return result;
        if (!lockManager_.lockShared(leftTable)) {
            lockManager_.unlock(rightTable);
            return result;
        }
    }

    JoinExceptionLockRelease exceptionLocks([&] {
        lockManager_.unlock(leftTable);
        lockManager_.unlock(rightTable);
    });
    TableSchema leftTbl = getTableSchema(dbname, leftTable);
    TableSchema rightTbl = getTableSchema(dbname, rightTable);

    struct JoinRow {
        std::string data;
        int64_t rid = 0;
        std::string joinKey;
        bool joinKeyNull = false;
    };

    // Keep the physical row identity with buffered data.  The payload alone
    // cannot distinguish SQL NULL from an empty string after the heap header
    // (and its null bitmap) has been stripped.
    std::vector<JoinRow> leftRows;
    if (!forEachRow(dbname, leftTable, [&](uint32_t pageId, uint16_t slotId,
                                           const char* data, size_t len) {
        leftRows.push_back(
            {std::string(data, len), encodeRid(pageId, slotId), {}, false});
    })) {
        lockManager_.unlock(leftTable);
        lockManager_.unlock(rightTable);
        return result;
    }

    // Read all rows from right table
    std::vector<JoinRow> rightRows;
    if (!forEachRow(dbname, rightTable, [&](uint32_t pageId, uint16_t slotId,
                                            const char* data, size_t len) {
        rightRows.push_back(
            {std::string(data, len), encodeRid(pageId, slotId), {}, false});
    })) {
        lockManager_.unlock(leftTable);
        lockManager_.unlock(rightTable);
        return result;
    }

    const auto logicalValue = [&](const JoinRow& row,
                                  const TableSchema& table,
                                  const std::string& tableName,
                                  size_t columnIndex,
                                  bool* valueIsNull = nullptr) {
        NullRowBinding nullBinding(
            this, dbname, tableName, row.rid, table.len);
        return extractColumnValue(
            row.data, table, columnIndex, dbname, true, valueIsNull);
    };

    // Build column map for condition evaluation: colName -> {isLeft, colIdx}
    struct ColInfo { bool isLeft; size_t colIdx; };
    std::map<std::string, ColInfo> colMap;
    for (size_t i = 0; i < leftTbl.len; ++i) {
        colMap[leftTbl.cols[i].dataName] = {true, i};
        colMap[joinRangeColumnKey(leftRange, leftTbl.cols[i].dataName, rangeNames.encodeColumns)] = {true, i};
    }
    for (size_t i = 0; i < rightTbl.len; ++i) {
        std::string simple = rightTbl.cols[i].dataName;
        if (colMap.find(simple) == colMap.end()) {
            colMap[simple] = {false, i};
        }
        colMap[joinRangeColumnKey(rightRange, simple, rangeNames.encodeColumns)] = {false, i};
    }

    // Evaluate a condition on left/right row pair
    auto evalCond = [&](const JoinCondition& c, const JoinRow& leftRow,
                        const JoinRow& rightRow) -> bool {
        if (c.op == "typedexpr")
            return evaluateJoinExpression(c, [&](bool isLeft, size_t index, bool& isNull) {
                return logicalValue(isLeft ? leftRow : rightRow,
                    isLeft ? leftTbl : rightTbl, isLeft ? leftTable : rightTable, index, &isNull);
            });
        if (c.op == "jointrue" || c.op == "joinfalse")
            return c.op == "jointrue";
        auto it = colMap.find(c.colName);
        if (it == colMap.end()) return false;
        const TableSchema& tbl = it->second.isLeft ? leftTbl : rightTbl;
        const JoinRow& row = it->second.isLeft ? leftRow : rightRow;
        const std::string& tableName =
            it->second.isLeft ? leftTable : rightTable;
        bool valueIsNull = false;
        std::string val = logicalValue(
            row, tbl, tableName, it->second.colIdx, &valueIsNull);
        const Column& col = tbl.cols[it->second.colIdx];
        std::string comparisonValue = c.value;
        bool comparisonIsNull = c.valueIsNull;
        Condition bound=c;
        if ((isJoinComparisonOperator(c.op) || !storedPatternOperator(c.op).empty()) && !c.valueIsLiteral) {
            auto comparison = colMap.find(c.value);
            if (comparison != colMap.end()) {
                const TableSchema& comparisonTable =
                    comparison->second.isLeft ? leftTbl : rightTbl;
                const JoinRow& comparisonRow =
                    comparison->second.isLeft ? leftRow : rightRow;
                const std::string& comparisonTableName =
                    comparison->second.isLeft ? leftTable : rightTable;
                comparisonValue = logicalValue(
                    comparisonRow, comparisonTable, comparisonTableName,
                    comparison->second.colIdx, &comparisonIsNull);
            }
        }
        if (!c.patternEscapeColumn.empty()) {
            const auto escape=colMap.find(c.patternEscapeColumn);
            if (escape==colMap.end()) throw DbError("42703", "pattern escape column does not exist");
            bound.patternEscape=logicalValue(escape->second.isLeft ? leftRow : rightRow,
                escape->second.isLeft ? leftTbl : rightTbl,
                escape->second.isLeft ? leftTable : rightTable,
                escape->second.colIdx,&bound.patternEscapeIsNull);
        }
        return joinValuePredicateMatches(
            bound, col, val, valueIsNull, comparisonValue, comparisonIsNull);
    };

    auto conds = parseJoinConditions(conditions);
    auto extraOnConds = parseJoinOnConditions(onConditions);
    prepareJoinExpressions(conds, leftTbl, rightTbl, leftRange, rightRange,
                           rangeNames.encodeColumns, dbname, this);
    prepareJoinExpressions(extraOnConds, leftTbl, rightTbl, leftRange, rightRange,
                           rangeNames.encodeColumns, dbname, this);
    conds.insert(conds.end(), extraOnConds.begin(), extraOnConds.end());

    // Predicate pushdown: classify conditions by which table they reference
    std::vector<JoinCondition> leftConds, rightConds, joinConds;
    for (const auto& c : conds) {
        bool onLeft = (colMap.find(c.colName) != colMap.end() && colMap.at(c.colName).isLeft);
        bool onRight = false;
        auto it = colMap.find(c.colName);
        if (it != colMap.end()) onRight = !it->second.isLeft;
        // Check if value references a column from the other table
        bool valIsCol = false;
        auto vit = colMap.find(c.value);
        if (!c.valueIsLiteral && vit != colMap.end()) valIsCol = true;
        if (!c.patternEscapeColumn.empty()) valIsCol=true;
        if (onLeft && !valIsCol) leftConds.push_back(c);
        else if (onRight && !valIsCol) rightConds.push_back(c);
        else joinConds.push_back(c);
    }

    // Apply predicate pushdown: filter rows before JOIN
    auto evalSingleCond = [&](const JoinCondition& c, const JoinRow& row,
                               const TableSchema& tbl,
                               const std::string& tableName) -> bool {
        auto it = colMap.find(c.colName);
        if (it == colMap.end()) return false;
        bool valueIsNull = false;
        std::string val = logicalValue(
            row, tbl, tableName, it->second.colIdx, &valueIsNull);
        const Column& col = tbl.cols[it->second.colIdx];
        return joinValuePredicateMatches(
            c, col, val, valueIsNull, c.value, c.valueIsNull);
    };

    if (!leftConds.empty()) {
        leftRows.erase(std::remove_if(leftRows.begin(), leftRows.end(),
            [&](const JoinRow& row) {
                for (const auto& c : leftConds)
                    if (!evalSingleCond(
                            c, row, leftTbl, leftTable)) return true;
                return false;
            }), leftRows.end());
    }
    if (!rightConds.empty()) {
        rightRows.erase(std::remove_if(rightRows.begin(), rightRows.end(),
            [&](const JoinRow& row) {
                for (const auto& c : rightConds)
                    if (!evalSingleCond(
                            c, row, rightTbl, rightTable)) return true;
                return false;
            }), rightRows.end());
    }

    // Find left and right column indices for ON condition
    size_t leftColIdx = leftTbl.len;
    for (size_t i = 0; i < leftTbl.len; ++i) {
        if (leftTbl.cols[i].dataName == leftCol) { leftColIdx = i; break; }
    }
    size_t rightColIdx = rightTbl.len;
    for (size_t i = 0; i < rightTbl.len; ++i) {
        if (rightTbl.cols[i].dataName == rightCol) { rightColIdx = i; break; }
    }

    if (leftColIdx < leftTbl.len) {
        for (auto& row : leftRows) {
            row.joinKey = canonicalColumnKeyValue(
                leftTbl.cols[leftColIdx], logicalValue(
                    row, leftTbl, leftTable, leftColIdx, &row.joinKeyNull));
        }
    }
    if (rightColIdx < rightTbl.len) {
        for (auto& row : rightRows) {
            row.joinKey = canonicalColumnKeyValue(
                rightTbl.cols[rightColIdx], logicalValue(
                    row, rightTbl, rightTable, rightColIdx, &row.joinKeyNull));
        }
    }

    // JOIN optimization: build hash table on right table's join column
    std::unordered_map<std::string, std::vector<const JoinRow*>> rightHash;
    if (rightColIdx < rightTbl.len) {
        for (const auto& rr : rightRows) {
            if (rr.joinKeyNull) continue;
            rightHash[rr.joinKey].push_back(&rr);
        }
    }

    for (const auto& lr : leftRows) {
        // ON condition via hash probe
        if (leftColIdx >= leftTbl.len || rightColIdx >= rightTbl.len) continue;
        if (lr.joinKeyNull) continue;
        auto it = rightHash.find(lr.joinKey);
        if (it == rightHash.end()) continue;

        for (const JoinRow* rr : it->second) {
            // WHERE conditions (only cross-table conditions remain after pushdown)
            bool whereMatch = true;
            for (const auto& c : joinConds) {
                if (!evalCond(c, lr, *rr)) {
                    whereMatch = false;
                    break;
                }
            }
            if (!whereMatch) continue;

            // Format output with SELECT columns
            std::string rowStr;
            std::vector<std::string> cells;
            std::vector<bool> nulls;
            for (size_t i = 0; i < leftTbl.len; ++i) {
                std::string fullName = joinRangeColumnKey(leftRange, leftTbl.cols[i].dataName, rangeNames.encodeColumns);
                bool include = selectCols.empty();
                if (!include) {
                    if (selectCols.find(leftTbl.cols[i].dataName) != selectCols.end() ||
                        selectCols.find(fullName) != selectCols.end()) include = true;
                }
                if (!include) continue;
                bool valueIsNull = false;
                std::string val = logicalValue(
                    lr, leftTbl, leftTable, i, &valueIsNull);
                if (valueIsNull) rowStr += "NULL ";
                else rowStr += val + ' ';
                cells.push_back(valueIsNull ? std::string{} : val);
                nulls.push_back(valueIsNull);
            }
            for (size_t i = 0; i < rightTbl.len; ++i) {
                std::string fullName = joinRangeColumnKey(rightRange, rightTbl.cols[i].dataName, rangeNames.encodeColumns);
                bool include = selectCols.empty();
                if (!include) {
                    if (selectCols.find(rightTbl.cols[i].dataName) != selectCols.end() ||
                        selectCols.find(fullName) != selectCols.end()) include = true;
                }
                if (!include) continue;
                bool valueIsNull = false;
                std::string val = logicalValue(
                    *rr, rightTbl, rightTable, i, &valueIsNull);
                if (valueIsNull) rowStr += "NULL ";
                else rowStr += val + ' ';
                cells.push_back(valueIsNull ? std::string{} : val);
                nulls.push_back(valueIsNull);
            }
            if (!rowStr.empty()) {
                result.push_back(std::move(rowStr));
                if (structuredRows) structuredRows->push_back(std::move(cells));
                if (structuredNulls) structuredNulls->push_back(std::move(nulls));
            }
        }
    }
    lockManager_.unlock(leftTable);
    lockManager_.unlock(rightTable);
    return result;
}

// ========================================================================
// LEFT JOIN: preserve all left rows, NULL for non-matching right
// ========================================================================

std::vector<std::string> StorageEngine::leftJoin(
    const std::string& dbname,
    const std::string& leftTable,
    const std::string& rightTable,
    const std::string& leftCol,
    const std::string& rightCol,
    const std::vector<std::string>& conditions,
    const std::set<std::string>& selectCols,
    std::vector<std::vector<std::string>>* structuredRows,
    std::vector<std::vector<bool>>* structuredNulls,
    const std::vector<std::string>& onConditions,
    const JoinRangeNames& rangeNames) {
    const std::string& leftRange = rangeNames.first.empty() ? leftTable : rangeNames.first;
    const std::string& rightRange = rangeNames.second.empty() ? rightTable : rangeNames.second;
    std::vector<std::string> result;
    if (structuredRows) structuredRows->clear();
    if (structuredNulls) structuredNulls->clear();
    if (!tableExists(dbname, leftTable) || !tableExists(dbname, rightTable)) return result;

    if (leftTable < rightTable) {
        if (!lockManager_.lockShared(leftTable)) return result;
        if (!lockManager_.lockShared(rightTable)) {
            lockManager_.unlock(leftTable);
            return result;
        }
    } else {
        if (!lockManager_.lockShared(rightTable)) return result;
        if (!lockManager_.lockShared(leftTable)) {
            lockManager_.unlock(rightTable);
            return result;
        }
    }

    JoinExceptionLockRelease exceptionLocks([&] {
        lockManager_.unlock(leftTable);
        lockManager_.unlock(rightTable);
    });
    TableSchema leftTbl = getTableSchema(dbname, leftTable);
    TableSchema rightTbl = getTableSchema(dbname, rightTable);

    struct JoinRow {
        std::string data;
        int64_t rid = 0;
        std::string joinKey;
        bool joinKeyNull = false;
    };
    std::vector<JoinRow> leftRows;
    if (!forEachRow(dbname, leftTable, [&](uint32_t pageId, uint16_t slotId,
                                           const char* data, size_t len) {
        leftRows.push_back(
            {std::string(data, len), encodeRid(pageId, slotId), {}, false});
    })) {
        lockManager_.unlock(leftTable);
        lockManager_.unlock(rightTable);
        return result;
    }
    std::vector<JoinRow> rightRows;
    if (!forEachRow(dbname, rightTable, [&](uint32_t pageId, uint16_t slotId,
                                            const char* data, size_t len) {
        rightRows.push_back(
            {std::string(data, len), encodeRid(pageId, slotId), {}, false});
    })) {
        lockManager_.unlock(leftTable);
        lockManager_.unlock(rightTable);
        return result;
    }

    const auto logicalValue = [&](const JoinRow& row,
                                  const TableSchema& table,
                                  const std::string& tableName,
                                  size_t columnIndex,
                                  bool* valueIsNull = nullptr) {
        NullRowBinding nullBinding(
            this, dbname, tableName, row.rid, table.len);
        return extractColumnValue(
            row.data, table, columnIndex, dbname, true, valueIsNull);
    };

    struct ColInfo { bool isLeft; size_t colIdx; };
    std::map<std::string, ColInfo> colMap;
    for (size_t i = 0; i < leftTbl.len; ++i) {
        colMap[leftTbl.cols[i].dataName] = {true, i};
        colMap[joinRangeColumnKey(leftRange, leftTbl.cols[i].dataName, rangeNames.encodeColumns)] = {true, i};
    }
    for (size_t i = 0; i < rightTbl.len; ++i) {
        std::string simple = rightTbl.cols[i].dataName;
        if (colMap.find(simple) == colMap.end()) colMap[simple] = {false, i};
        colMap[joinRangeColumnKey(rightRange, simple, rangeNames.encodeColumns)] = {false, i};
    }

    auto evalCond = [&](const JoinCondition& c, const JoinRow* leftRow,
                        const JoinRow* rightRow) -> bool {
        if (c.op == "typedexpr")
            return evaluateJoinExpression(c, [&](bool isLeft, size_t index, bool& isNull) {
                const JoinRow* row = isLeft ? leftRow : rightRow;
                if (!row) { isNull = true; return std::string{}; }
                return logicalValue(*row, isLeft ? leftTbl : rightTbl,
                    isLeft ? leftTable : rightTable, index, &isNull);
            });
        if (c.op == "jointrue" || c.op == "joinfalse")
            return c.op == "jointrue";
        auto it = colMap.find(c.colName);
        if (it == colMap.end()) return false;
        const TableSchema& tbl = it->second.isLeft ? leftTbl : rightTbl;
        const JoinRow* row = it->second.isLeft ? leftRow : rightRow;
        const Column& col = tbl.cols[it->second.colIdx];
        if (!row) {
            return joinValuePredicateMatches(c, col, {}, true, c.value, c.valueIsNull);
        }
        const std::string& tableName =
            it->second.isLeft ? leftTable : rightTable;
        bool valueIsNull = false;
        std::string val = logicalValue(
            *row, tbl, tableName, it->second.colIdx, &valueIsNull);
        std::string comparisonValue = c.value;
        bool comparisonIsNull = c.valueIsNull;
        Condition bound=c;
        if ((isJoinComparisonOperator(c.op) || !storedPatternOperator(c.op).empty()) && !c.valueIsLiteral) {
            auto comparison = colMap.find(c.value);
            if (comparison != colMap.end()) {
                const JoinRow* comparisonRow = comparison->second.isLeft
                    ? leftRow : rightRow;
                if (!comparisonRow) {
                    comparisonIsNull = true;
                } else {
                    const TableSchema& comparisonTable =
                        comparison->second.isLeft ? leftTbl : rightTbl;
                    const std::string& comparisonTableName =
                        comparison->second.isLeft ? leftTable : rightTable;
                    comparisonValue = logicalValue(
                        *comparisonRow, comparisonTable, comparisonTableName,
                        comparison->second.colIdx, &comparisonIsNull);
                }
            }
        }
        if (!c.patternEscapeColumn.empty()) {
            const auto escape=colMap.find(c.patternEscapeColumn);
            if (escape==colMap.end()) throw DbError("42703", "pattern escape column does not exist");
            const auto* escapeRow=escape->second.isLeft ? leftRow : rightRow;
            if (!escapeRow) bound.patternEscapeIsNull=true;
            else bound.patternEscape=logicalValue(*escapeRow,
                escape->second.isLeft ? leftTbl : rightTbl,
                escape->second.isLeft ? leftTable : rightTable,
                escape->second.colIdx,&bound.patternEscapeIsNull);
        }
        return joinValuePredicateMatches(
            bound, col, val, valueIsNull, comparisonValue, comparisonIsNull);
    };

    auto conds = parseJoinConditions(conditions);
    auto onConds = parseJoinOnConditions(onConditions);
    prepareJoinExpressions(conds, leftTbl, rightTbl, leftRange, rightRange,
                           rangeNames.encodeColumns, dbname, this);
    prepareJoinExpressions(onConds, leftTbl, rightTbl, leftRange, rightRange,
                           rangeNames.encodeColumns, dbname, this);

    size_t leftColIdx = leftTbl.len;
    for (size_t i = 0; i < leftTbl.len; ++i) {
        if (leftTbl.cols[i].dataName == leftCol) { leftColIdx = i; break; }
    }
    size_t rightColIdx = rightTbl.len;
    for (size_t i = 0; i < rightTbl.len; ++i) {
        if (rightTbl.cols[i].dataName == rightCol) { rightColIdx = i; break; }
    }

    if (leftColIdx < leftTbl.len) {
        for (auto& row : leftRows) {
            row.joinKey = canonicalColumnKeyValue(
                leftTbl.cols[leftColIdx], logicalValue(
                    row, leftTbl, leftTable, leftColIdx, &row.joinKeyNull));
        }
    }
    if (rightColIdx < rightTbl.len) {
        for (auto& row : rightRows) {
            row.joinKey = canonicalColumnKeyValue(
                rightTbl.cols[rightColIdx], logicalValue(
                    row, rightTbl, rightTable, rightColIdx, &row.joinKeyNull));
        }
    }

    const bool preserveRight = std::find(onConditions.begin(), onConditions.end(),
        "__join_full_once__") != onConditions.end();
    std::vector<bool> rightMatched(preserveRight ? rightRows.size() : 0, false);
    auto formatRow = [&](const JoinRow* lr, const JoinRow* rr,
                         bool rightNull, std::vector<std::string>& cells,
                         std::vector<bool>& nulls) -> std::string {
        std::string rowStr;
        for (size_t i = 0; i < leftTbl.len; ++i) {
            std::string fullName = joinRangeColumnKey(leftRange, leftTbl.cols[i].dataName, rangeNames.encodeColumns);
            bool include = selectCols.empty() || selectCols.find(leftTbl.cols[i].dataName) != selectCols.end() || selectCols.find(fullName) != selectCols.end();
            if (!include) continue;
            if (!lr) {
                rowStr += "NULL ";
                cells.emplace_back();
                nulls.push_back(true);
                continue;
            }
            bool valueIsNull = false;
            std::string val = logicalValue(
                *lr, leftTbl, leftTable, i, &valueIsNull);
            if (valueIsNull) rowStr += "NULL ";
            else rowStr += val + ' ';
            cells.push_back(valueIsNull ? std::string{} : val);
            nulls.push_back(valueIsNull);
        }
        for (size_t i = 0; i < rightTbl.len; ++i) {
            std::string fullName = joinRangeColumnKey(rightRange, rightTbl.cols[i].dataName, rangeNames.encodeColumns);
            bool include = selectCols.empty() || selectCols.find(rightTbl.cols[i].dataName) != selectCols.end() || selectCols.find(fullName) != selectCols.end();
            if (!include) continue;
            if (rightNull) {
                rowStr += "NULL ";
                cells.emplace_back();
                nulls.push_back(true);
                continue;
            }
            bool valueIsNull = false;
            std::string val = logicalValue(
                *rr, rightTbl, rightTable, i, &valueIsNull);
            if (valueIsNull) rowStr += "NULL ";
            else rowStr += val + ' ';
            cells.push_back(valueIsNull ? std::string{} : val);
            nulls.push_back(valueIsNull);
        }
        return rowStr;
    };

    for (const auto& lr : leftRows) {
        bool hasOnMatch = false;
        for (const auto& rr : rightRows) {
            if (!leftCol.empty() && !rightCol.empty()) {
                if (leftColIdx >= leftTbl.len || rightColIdx >= rightTbl.len) continue;
                if (lr.joinKeyNull || rr.joinKeyNull) continue;
                if (lr.joinKey != rr.joinKey) continue;
            } else if (onConds.empty()) continue;
            bool matchesOn = true;
            for (const auto& condition : onConds) {
                if (!evalCond(condition, &lr, &rr)) {
                    matchesOn = false;
                    break;
                }
            }
            if (!matchesOn) continue;
            hasOnMatch = true;
            // Preserve match identity by input occurrence, before WHERE.
            // Equal-valued duplicate rows are separate FULL JOIN inputs.
            if (preserveRight) rightMatched[static_cast<size_t>(&rr - rightRows.data())] = true;
            bool whereMatch = true;
            for (const auto& c : conds) {
                if (!evalCond(c, &lr, &rr)) {
                    whereMatch = false;
                    break;
                }
            }
            if (!whereMatch) continue;
            std::vector<std::string> cells;
            std::vector<bool> nulls;
            std::string rowStr = formatRow(&lr, &rr, false, cells, nulls);
            if (!rowStr.empty()) {
                result.push_back(std::move(rowStr));
                if (structuredRows) structuredRows->push_back(std::move(cells));
                if (structuredNulls) structuredNulls->push_back(std::move(nulls));
            }
        }
        if (!hasOnMatch) {
            bool whereMatch = true;
            for (const auto& c : conds) {
                if (!evalCond(c, &lr, nullptr)) {
                    whereMatch = false;
                    break;
                }
            }
            if (!whereMatch) continue;
            std::vector<std::string> cells;
            std::vector<bool> nulls;
            std::string rowStr = formatRow(&lr, nullptr, true, cells, nulls);
            if (!rowStr.empty()) {
                result.push_back(std::move(rowStr));
                if (structuredRows) structuredRows->push_back(std::move(cells));
                if (structuredNulls) structuredNulls->push_back(std::move(nulls));
            }
        }
    }
    if (preserveRight) {
        for (size_t i = 0; i < rightRows.size(); ++i) {
            if (rightMatched[i]) continue;
            const auto& row = rightRows[i];
            bool whereMatch = true;
            for (const auto& condition : conds) {
                if (!evalCond(condition, nullptr, &row)) {
                    whereMatch = false;
                    break;
                }
            }
            if (!whereMatch) continue;
            std::vector<std::string> cells;
            std::vector<bool> nulls;
            std::string rowStr = formatRow(nullptr, &row, false, cells, nulls);
            if (!rowStr.empty()) {
                result.push_back(std::move(rowStr));
                if (structuredRows) structuredRows->push_back(std::move(cells));
                if (structuredNulls) structuredNulls->push_back(std::move(nulls));
            }
        }
    }
    lockManager_.unlock(leftTable);
    lockManager_.unlock(rightTable);
    return result;
}

// ========================================================================
// RIGHT JOIN: preserve all right rows, NULL for non-matching left
// ========================================================================

std::vector<std::string> StorageEngine::rightJoin(
    const std::string& dbname,
    const std::string& leftTable,
    const std::string& rightTable,
    const std::string& leftCol,
    const std::string& rightCol,
    const std::vector<std::string>& conditions,
    const std::set<std::string>& selectCols,
    std::vector<std::vector<std::string>>* structuredRows,
    std::vector<std::vector<bool>>* structuredNulls,
    const std::vector<std::string>& onConditions,
    const JoinRangeNames& rangeNames) {
    const std::string& leftRange = rangeNames.first.empty() ? leftTable : rangeNames.first;
    const std::string& rightRange = rangeNames.second.empty() ? rightTable : rangeNames.second;
    std::vector<std::string> result;
