// Transaction logging helpers
// ========================================================================

bool StorageEngine::ssiIndexPredicateMatches(const SsiIndexPredicate& predicate,
                                             const SsiIndexKey& key) {
    if (predicate.dbname != key.dbname || predicate.tablename != key.tablename ||
        predicate.indexName != key.indexName) {
        return false;
    }
    const std::string lhs = BPTree::normalizeKeyForComparison(key.value);
    const std::string rhs = BPTree::normalizeKeyForComparison(predicate.value);
    if (predicate.op == "=") return lhs == rhs;
    if (predicate.op == ">") return lhs > rhs;
    if (predicate.op == ">=") return lhs >= rhs;
    if (predicate.op == "<") return lhs < rhs;
    if (predicate.op == "<=") return lhs <= rhs;
    return false;
}

bool StorageEngine::recordSsiIndexPredicate(const std::string& dbname,
                                            const std::string& tablename,
                                            const Condition& condition,
                                            const TableSchema& tbl) {
    if (!transactionContext().inTransaction ||
        transactionContext().txnDB != dbname ||
        transactionContext().txnIsolationLevel != IsolationLevel::SERIALIZABLE ||
        (condition.op != "=" && condition.op != ">" && condition.op != ">=" &&
         condition.op != "<" && condition.op != "<=")) {
        return false;
    }

    size_t columnIndex = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == condition.colName) {
            columnIndex = i;
            break;
        }
    }
    if (columnIndex >= tbl.len ||
        !columnUsesBinaryCollation(tbl.cols[columnIndex])) {
        return false;
    }

    std::vector<std::string> indexNames;
    if (tbl.pkColIndices.size() == 1 && tbl.pkColIndices.front() == columnIndex) {
        indexNames.push_back("pk:" + condition.colName);
    }
    if (getSecondaryIndex(dbname, tablename, condition.colName)) {
        indexNames.push_back("idx:" + condition.colName);
    }
    const std::string predicateValue = canonicalColumnKeyValue(
        tbl.cols[columnIndex], condition.value);
    if (indexNames.empty() || predicateValue.empty()) return false;

    const SsiIndexPredicate predicateBase{
        dbname, tablename, "", condition.op, predicateValue};
    std::lock_guard<std::mutex> lock(ssiMutex_);
    for (const auto& indexName : indexNames) {
        SsiIndexPredicate predicate = predicateBase;
        predicate.indexName = indexName;
        transactionContext().txnReadIndexPredicates.insert(predicate);
        ssiReadIndexPredicates_[transactionContext().currentTxnId].insert(std::move(predicate));
    }
    return !indexNames.empty();
}

void StorageEngine::recordSsiIndexKeys(const std::string& dbname,
                                       const std::string& tablename,
                                       const std::string& rowData,
                                       const TableSchema& tbl) {
    if (!transactionContext().inTransaction ||
        transactionContext().txnIsolationLevel != IsolationLevel::SERIALIZABLE) {
        return;
    }

    std::vector<std::pair<std::string, std::string>> keys;
    if (tbl.pkColIndices.size() == 1) {
        const size_t columnIndex = tbl.pkColIndices.front();
        if (columnIndex < tbl.len) {
            const std::string value = canonicalColumnKeyValue(
                tbl.cols[columnIndex], extractColumnValue(
                    rowData, tbl, columnIndex, dbname));
            if (!value.empty()) {
                keys.emplace_back("pk:" + tbl.cols[columnIndex].dataName, value);
            }
        }
    }
    for (const auto& columnName : getIndexedColumns(dbname, tablename)) {
        BPTree* index = getSecondaryIndex(dbname, tablename, columnName);
        if (!index) continue;
        size_t columnIndex = tbl.len;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == columnName) {
                columnIndex = i;
                break;
            }
        }
        if (columnIndex >= tbl.len) continue;
        const std::string value = canonicalColumnKeyValue(
            tbl.cols[columnIndex], extractColumnValue(
                rowData, tbl, columnIndex, dbname));
        if (!value.empty()) keys.emplace_back("idx:" + columnName, value);
    }

    if (keys.empty()) return;
    std::lock_guard<std::mutex> lock(ssiMutex_);
    for (const auto& [indexName, value] : keys) {
        SsiIndexKey key{dbname, tablename, indexName, value};
        transactionContext().txnWrittenIndexKeys.insert(key);
        ssiWriteIndexKeys_[transactionContext().currentTxnId].insert(std::move(key));
    }
}

void StorageEngine::logTxnInsert(const std::string& tableName, int64_t rowIdx,
                                 const std::string& rowData) {
    // Executor-owned CTE/derived relations are dropped before the outer SQL
    // command returns.  They must not leave undo entries that point at files
    // which no longer exist when an explicit transaction later rolls back.
    if (transactionContext().commandInternalRelations.count(tableName) != 0) {
        return;
    }
    TxnLogEntry entry;
    entry.op = TxnLogEntry::Op::Insert;
    entry.tableName = tableName;
    entry.rowIdx = rowIdx;
    entry.rowData = rowData;
    transactionContext().txnLog.push_back(std::move(entry));
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(rowIdx, pageId, slotId);
    (void)slotId;
    transactionContext().txnHeapWritebackPages.insert({tableName, pageId});
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        TableSchema tbl = getTableSchema(transactionContext().txnDB, tableName);
        recordSsiIndexKeys(
            transactionContext().txnDB, tableName, rowData, tbl);
        std::string key = ssiRidKey(transactionContext().txnDB, tableName, rowIdx);
        std::string relation = ssiRelationKey(transactionContext().txnDB, tableName);
        std::string page = ssiPageKey(
            transactionContext().txnDB, tableName, pageId);
        transactionContext().txnWrittenRids.insert(key);
        transactionContext().txnWrittenRelations.insert(relation);
        transactionContext().txnWrittenPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiWriteSets_[transactionContext().currentTxnId].insert(std::move(key));
        ssiWriteRelations_[transactionContext().currentTxnId].insert(std::move(relation));
        ssiWritePages_[transactionContext().currentTxnId].insert(std::move(page));
    }
}

void StorageEngine::logTxnUpdate(const std::string& tableName, int64_t rowIdx,
                                  const std::string& oldRowData) {
    if (transactionContext().commandInternalRelations.count(tableName) != 0) {
        return;
    }
    TxnLogEntry entry;
    entry.op = TxnLogEntry::Op::Update;
    entry.tableName = tableName;
    entry.rowIdx = rowIdx;
    entry.rowData = oldRowData;
    transactionContext().txnLog.push_back(std::move(entry));
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(rowIdx, pageId, slotId);
    (void)slotId;
    transactionContext().txnHeapWritebackPages.insert({tableName, pageId});
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        TableSchema tbl = getTableSchema(transactionContext().txnDB, tableName);
        recordSsiIndexKeys(transactionContext().txnDB, tableName, oldRowData, tbl);
        std::string key = ssiRidKey(transactionContext().txnDB, tableName, rowIdx);
        std::string relation = ssiRelationKey(transactionContext().txnDB, tableName);
        std::string page = ssiPageKey(
            transactionContext().txnDB, tableName, pageId);
        transactionContext().txnWrittenRids.insert(key);
        transactionContext().txnWrittenRelations.insert(relation);
        transactionContext().txnWrittenPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiWriteSets_[transactionContext().currentTxnId].insert(std::move(key));
        ssiWriteRelations_[transactionContext().currentTxnId].insert(std::move(relation));
        ssiWritePages_[transactionContext().currentTxnId].insert(std::move(page));
    }
}

void StorageEngine::logTxnDelete(const std::string& tableName, int64_t rowIdx,
                                  const std::string& oldRowData) {
    if (transactionContext().commandInternalRelations.count(tableName) != 0) {
        return;
    }
    TxnLogEntry entry;
    entry.op = TxnLogEntry::Op::Delete;
    entry.tableName = tableName;
    entry.rowIdx = rowIdx;
    entry.rowData = oldRowData;
    transactionContext().txnLog.push_back(std::move(entry));
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(rowIdx, pageId, slotId);
    (void)slotId;
    transactionContext().txnHeapWritebackPages.insert({tableName, pageId});
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        TableSchema tbl = getTableSchema(transactionContext().txnDB, tableName);
        recordSsiIndexKeys(transactionContext().txnDB, tableName, oldRowData, tbl);
        std::string key = ssiRidKey(transactionContext().txnDB, tableName, rowIdx);
        std::string relation = ssiRelationKey(transactionContext().txnDB, tableName);
        std::string page = ssiPageKey(
            transactionContext().txnDB, tableName, pageId);
        transactionContext().txnWrittenRids.insert(key);
        transactionContext().txnWrittenRelations.insert(relation);
        transactionContext().txnWrittenPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiWriteSets_[transactionContext().currentTxnId].insert(std::move(key));
        ssiWriteRelations_[transactionContext().currentTxnId].insert(std::move(relation));
        ssiWritePages_[transactionContext().currentTxnId].insert(std::move(page));
    }
}

bool StorageEngine::restoreDeletedRowIndexes(
    const std::string& dbname, const std::string& tablename,
    const TableSchema& tbl, const std::string& rowData, int64_t rid,
    std::set<BloomIndex*>& bloomUndoIndexes) {
    std::string heapRow;
    std::vector<bool> nullColumns;
    readRowByRid(getPageAllocator(dbname, tablename), rid,
                 heapRow, tbl, &nullColumns);
    BufferedNullRowBinding nullBinding(tbl, nullColumns);
    bool ok = true;
    const auto containsRid = [rid](const std::vector<int64_t>& values) {
        return std::find(values.begin(), values.end(), rid) != values.end();
    };

    if (tbl.hasPrimaryKey()) {
        BPTree* primary = getPKIndex(dbname, tablename);
        const std::string key = extractPKValue(rowData, tbl, dbname);
        if (!primary || key.empty()) {
            ok = false;
        } else {
            int64_t indexedRid = -1;
            if (primary->search(key, indexedRid)) {
                if (indexedRid != rid) ok = false;
            } else if (!primary->insert(key, rid)) {
                ok = false;
            }
        }
    }

    for (const auto& metadata : getIndexMetadata(dbname, tablename)) {
        EvaluatedIndexEntry entry;
        if (!secondaryIndexEntryFromBuffer(
                *this, metadata, tbl, rowData, dbname, entry)) {
            ok = false;
            continue;
        }
        if (!entry.included || entry.key.empty()) continue;
        BPTree* index = getSecondaryIndex(
            dbname, tablename, metadata.name);
        if (!index) {
            ok = false;
            continue;
        }
        if (!containsRid(index->searchMulti(entry.key)) &&
            !index->insertMulti(entry.key, rid)) {
            ok = false;
        }
    }

    for (const auto& metadata : getCompositeIndexes(dbname, tablename)) {
        EvaluatedIndexEntry entry;
        if (!compositeIndexEntryFromBuffer(
                *this, metadata, tbl, rowData, dbname, entry)) {
            ok = false;
            continue;
        }
        if (!entry.included || entry.key.empty()) continue;
        BPTree* index = getCompositeIndexTree(
            dbname, tablename, metadata.name);
        if (!index) {
            ok = false;
            continue;
        }
        if (!containsRid(index->searchMulti(entry.key)) &&
            !index->insertMulti(entry.key, rid)) {
            ok = false;
        }
    }

    for (const auto& columnName :
         getHashIndexedColumns(dbname, tablename)) {
        size_t columnIndex = tbl.len;
        for (size_t index = 0; index < tbl.len; ++index) {
            if (tbl.cols[index].dataName == columnName) {
                columnIndex = index;
                break;
            }
        }
        if (columnIndex >= tbl.len) {
            ok = false;
            continue;
        }
        bool isNull = false;
        const std::string value = canonicalColumnKeyValue(
            tbl.cols[columnIndex], extractColumnValue(
                rowData, tbl, columnIndex, dbname, false, &isNull));
        if (!hashKeyIncluded(tbl.cols[columnIndex], value, isNull)) continue;
        HashIndex* index = getHashIndex(dbname, tablename, columnName);
        if (!index) {
            ok = false;
            continue;
        }
        if (!containsRid(index->search(value)) && !index->insert(value, rid)) {
            ok = false;
        }
    }

    for (const auto& columnName :
         getBloomIndexedColumns(dbname, tablename)) {
        size_t columnIndex = tbl.len;
        for (size_t index = 0; index < tbl.len; ++index) {
            if (tbl.cols[index].dataName == columnName) {
                columnIndex = index;
                break;
            }
        }
        if (columnIndex >= tbl.len) {
            ok = false;
            continue;
        }
        const std::string value = canonicalColumnKeyValue(
            tbl.cols[columnIndex], extractColumnValue(
                rowData, tbl, columnIndex, dbname));
        if (value.empty()) continue;
        BloomIndex* index = getBloomIndex(dbname, tablename, columnName);
        if (!index) {
            ok = false;
            continue;
        }
        bloomUndoIndexes.insert(index);
        if (!containsRid(index->search(value)) && !index->insert(value, rid)) {
            ok = false;
        }
    }
    return ok;
}

bool StorageEngine::undoDeletedRow(
    const TxnLogEntry& entry,
    std::set<BloomIndex*>& bloomUndoIndexes) {
    if (entry.op != TxnLogEntry::Op::Delete || entry.rowIdx < 0 ||
        entry.rowData.empty() || transactionContext().txnDB.empty()) {
        return false;
    }

    const std::string& dbname = transactionContext().txnDB;
    const std::string& tablename = entry.tableName;
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    const TableSchema tbl = getTableSchema(dbname, tablename);
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(entry.rowIdx, pageId, slotId);

    bool heapOk = false;
    bool pageLocked = false;
    if (pa) {
        pageLocked = lockManager_.pageLockExclusive(
            dbname, tablename, pageId);
    }
    if (pa && pageLocked) {
        char* pageBuffer = pa->fetchPage(pageId);
        if (pageBuffer) {
            PageWrapper page(
                pageBuffer, pa->pageSize(), tbl.formatVersion);
            const char* currentData = nullptr;
            size_t currentLength = 0;
            if (page.isValid() &&
                page.read(slotId, currentData, currentLength) &&
                currentLength >=
                    rowHeaderSize(tbl.formatVersion, tbl.len) &&
                stripRowHeader(
                    currentData, currentLength, tbl.formatVersion,
                    tbl.len) == entry.rowData) {
                std::vector<char> stagedBuffer(
                    pageBuffer, pageBuffer + pa->pageSize());
                PageWrapper staged(
                    stagedBuffer.data(), pa->pageSize(),
                    tbl.formatVersion);
                std::string restored = replaceRowData(
                    std::string(currentData, currentLength),
                    entry.rowData, tbl.formatVersion, tbl.len);
                setRowXmax(
                    restored.data(), restored.size(), tbl.formatVersion, 0);
                uint16_t restoredSlot = slotId;
                const bool stagedOk = staged.update(
                    slotId, restored.data(), restored.size(), restoredSlot);
                const Lsn beforeLsn = stagedOk && restoredSlot == slotId
                    ? walPageImage(
                          dbname, tablename, pageId, pageBuffer,
                          pa->pageSize(), true)
                    : INVALID_LSN;
                const Lsn afterLsn = beforeLsn != INVALID_LSN
                    ? walPageImage(
                          dbname, tablename, pageId,
                          stagedBuffer.data(), pa->pageSize(), false)
                    : INVALID_LSN;
                WALManager* wal = getWAL(dbname);
                if (afterLsn != INVALID_LSN && wal &&
                    wal->XLogFlush(afterLsn)) {
                    std::memcpy(
                        pageBuffer, stagedBuffer.data(), pa->pageSize());
                    setPageLsnAndChecksum(pageBuffer, afterLsn);
                    pa->markDirty(pageId);
                    const size_t freePercent =
                        staged.freeSpace() * 100 / pa->pageSize();
                    getFSM(dbname, tablename)->setFreePercent(
                        pageId, static_cast<uint8_t>(freePercent));
                    getVM(dbname, tablename)->setAllVisible(pageId, false);
                    heapOk = pa->flush();
                }
            }
            pa->unpinPage(pageId);
        }
        lockManager_.pageUnlock(dbname, tablename, pageId);
    }

    // DELETE may have failed after removing only a prefix of its indexes.
    // Restore every missing exact key/RID pair even when the heap page is
    // unreadable; the logged OLD image is independent of that page.
    const bool indexesOk = restoreDeletedRowIndexes(
        dbname, tablename, tbl, entry.rowData, entry.rowIdx,
        bloomUndoIndexes);
    return heapOk && indexesOk;
}

