std::vector<std::string> StorageEngine::readSecidxLines(const std::string& dbname,
                                                        const std::string& tablename) const {
    const std::string key = dbname + "/" + tablename;
    {
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        auto it = secidxLinesCache_.find(key);
        if (it != secidxLinesCache_.end()) return it->second;
    }
    std::vector<std::string> lines;
    std::ifstream in(secondaryIndexMetaPath(dbname, tablename));
    if (in) {
        std::string line;
        while (std::getline(in, line)) {
            if (!line.empty()) lines.push_back(std::move(line));
        }
    }
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    // First writer wins; both see identical file content (writers hold the
    // table metadata lock while rewriting).
    secidxLinesCache_.emplace(key, lines);
    return lines;
}

void StorageEngine::invalidateSecidxCache(const std::string& dbname,
                                          const std::string& tablename) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    secidxLinesCache_.erase(dbname + "/" + tablename);
}

std::vector<std::string> StorageEngine::getIndexedColumns(const std::string& dbname,
                                                           const std::string& tablename) const {
    std::vector<std::string> cols;
    for (const std::string& storedLine :
         readSecidxLines(dbname, tablename)) {
        std::string line = storedLine;
        (void)consumeUniqueIndexMetadataPrefix(line);
        if (line.size() > 2 && line[0] == 'C' && line[1] == ':') {
            // Composite indexes have their own physical tree and are
            // maintained through getCompositeIndexes().  Treating their
            // component names as standalone indexes creates phantom files
            // and can insert the same RID twice when a real single-column
            // index exists on one of those columns.
            continue;
        } else if (line.substr(0, 5) == "EXPR:") {
            // Expression indexes are maintained from getIndexMetadata();
            // their expression text is not the name of a physical column.
            continue;
        } else {
            // Strip :DESC, :INCLUDE, and :WHERE suffixes
            size_t wherePos = line.find(":WHERE:");
            std::string base = (wherePos != std::string::npos) ? line.substr(0, wherePos) : line;
            size_t includePos = base.find(":INCLUDE");
            base = (includePos != std::string::npos) ? base.substr(0, includePos) : base;
            size_t descPos = base.find(":DESC");
            if (descPos != std::string::npos) {
                cols.push_back(base.substr(0, descPos));
            } else {
                cols.push_back(base);
            }
        }
    }
    return cols;
}

bool StorageEngine::isDescendingIndex(const std::string& dbname, const std::string& tablename,
                                      const std::string& colname) const {
    for (const std::string& storedLine :
         readSecidxLines(dbname, tablename)) {
        std::string line = storedLine;
        (void)consumeUniqueIndexMetadataPrefix(line);
        if (line.substr(0, 5) == "EXPR:") continue;
        size_t wherePos = line.find(":WHERE:");
        std::string base = (wherePos != std::string::npos) ? line.substr(0, wherePos) : line;
        size_t incPos = base.find(":INCLUDE");
        base = (incPos != std::string::npos) ? base.substr(0, incPos) : base;
        if (base == colname + ":DESC") return true;
    }
    return false;
}

std::vector<std::string> StorageEngine::getIndexIncludeColumns(const std::string& dbname,
                                                               const std::string& tablename,
                                                               const std::string& colname) const {
    std::vector<std::string> result;
    for (const std::string& storedLine :
         readSecidxLines(dbname, tablename)) {
        std::string line = storedLine;
        (void)consumeUniqueIndexMetadataPrefix(line);
        size_t incPos = line.find(":INCLUDE:");
        if (incPos == std::string::npos) continue;
        // For single-column index: colname[:DESC][:WHERE:...]:INCLUDE:...
        // For expression index: EXPR:expr[:WHERE:...]:INCLUDE:...
        std::string base = line.substr(0, incPos);
        std::string idxCol;
        if (base.substr(0, 5) == "EXPR:") {
            idxCol = base.substr(5);
            size_t wherePos = idxCol.find(":WHERE:");
            if (wherePos != std::string::npos) idxCol = idxCol.substr(0, wherePos);
        } else {
            size_t descPos = base.find(":DESC");
            idxCol = (descPos != std::string::npos) ? base.substr(0, descPos) : base;
        }
        if (idxCol == colname) {
            std::string incStr = line.substr(incPos + 9); // after ":INCLUDE:"
            size_t p = 0;
            while (p < incStr.size()) {
                size_t comma = incStr.find(',', p);
                std::string c = trim((comma == std::string::npos) ? incStr.substr(p) : incStr.substr(p, comma - p));
                if (!c.empty()) result.push_back(c);
                if (comma == std::string::npos) break;
                p = comma + 1;
            }
            return result;
        }
    }
    return result;
}

std::vector<StorageEngine::IndexMetadata> StorageEngine::getIndexMetadata(
    const std::string& dbname, const std::string& tablename) const {
    std::vector<IndexMetadata> result;
    for (const std::string& storedLine :
         readSecidxLines(dbname, tablename)) {
        std::string line = storedLine;
        IndexMetadata info;
        info.isUnique = consumeUniqueIndexMetadataPrefix(line);
        // Composite index lines start with "C:"
        if (line.size() > 2 && line[0] == 'C' && line[1] == ':') continue;

        // Check for EXPR prefix
        if (line.substr(0, 5) == "EXPR:") {
            info.isExpression = true;
            size_t pos = 5;
            // Extract expression, stopping at :INCLUDE or :WHERE
            size_t incPos = line.find(":INCLUDE:", pos);
            size_t wherePos = line.find(":WHERE:", pos);
            size_t endPos = std::min(
                incPos != std::string::npos ? incPos : line.size(),
                wherePos != std::string::npos ? wherePos : line.size());
            info.name = line.substr(pos, endPos - pos);
            // Extract function from expression like "UPPER(col)"
            size_t lp = info.name.find('(');
            if (lp != std::string::npos) {
                info.exprFunc = info.name.substr(0, lp);
                for (char& ch : info.exprFunc) {
                    ch = static_cast<char>(
                        std::toupper(static_cast<unsigned char>(ch)));
                }
            }
            pos = endPos;
            if (incPos != std::string::npos && pos == incPos) {
                size_t wPos = line.find(":WHERE:", incPos + 9);
                std::string incStr = (wPos != std::string::npos)
                    ? line.substr(incPos + 9, wPos - incPos - 9)
                    : line.substr(incPos + 9);
                std::stringstream ss(incStr);
                std::string c;
                while (getline(ss, c, ',')) {
                    c = trim(c);
                    if (!c.empty()) info.includeCols.push_back(c);
                }
                if (wPos != std::string::npos) pos = wPos;
            }
            if (wherePos != std::string::npos && pos == wherePos) {
                info.whereCondition = line.substr(wherePos + 7);
            }
            result.push_back(std::move(info));
            continue;
        }

        // Regular single-column index: colname[:DESC][:INCLUDE:...][:WHERE:...]
        size_t wherePos = line.find(":WHERE:");
        size_t incPos = line.find(":INCLUDE:");
        size_t descPos = line.find(":DESC");

        std::string base;
        if (wherePos != std::string::npos) {
            base = line.substr(0, wherePos);
            info.whereCondition = line.substr(wherePos + 7);
        } else {
            base = line;
        }

        std::string colPart = base;
        if (incPos != std::string::npos && incPos < base.size()) {
            std::string incStr = base.substr(incPos + 9);
            colPart = base.substr(0, incPos);
            std::stringstream ss(incStr);
            std::string c;
            while (getline(ss, c, ',')) {
                c = trim(c);
                if (!c.empty()) info.includeCols.push_back(c);
            }
        }

        if (descPos != std::string::npos && descPos < colPart.size()) {
            info.name = colPart.substr(0, descPos);
            info.descending = true;
        } else {
            info.name = colPart;
        }
        result.push_back(std::move(info));
    }
    return result;
}

std::vector<StorageEngine::CompositeIndexInfo> StorageEngine::getCompositeIndexes(
    const std::string& dbname, const std::string& tablename) const {
    std::vector<CompositeIndexInfo> result;
    for (const std::string& storedLine :
         readSecidxLines(dbname, tablename)) {
        std::string line = storedLine;
        const bool isUnique = consumeUniqueIndexMetadataPrefix(line);
        if (line.size() > 2 && line[0] == 'C' && line[1] == ':') {
            const size_t nameEnd = line.find(':', 2);
            if (nameEnd == std::string::npos) continue;
            CompositeIndexInfo info;
            info.name = line.substr(2, nameEnd - 2);
            info.isUnique = isUnique;

            const size_t includePos = line.find(":INCLUDE:", nameEnd);
            const size_t wherePos = line.find(":WHERE:", nameEnd);
            const size_t columnsEnd = std::min(
                includePos != std::string::npos ? includePos : line.size(),
                wherePos != std::string::npos ? wherePos : line.size());
            std::stringstream columns(line.substr(
                nameEnd + 1, columnsEnd - nameEnd - 1));
            std::string column;
            while (std::getline(columns, column, ':')) {
                column = trim(column);
                if (!column.empty()) info.columns.push_back(column);
            }

            if (wherePos != std::string::npos) {
                info.whereCondition = line.substr(wherePos + 7);
            }
            if (!info.columns.empty()) result.push_back(std::move(info));
        }
    }
    return result;
}

BPTree* StorageEngine::getSecondaryIndex(const std::string& dbname,
                                          const std::string& tablename,
                                          const std::string& colname) const {
    return loadBtreeIndex(secondaryIndexCache_,
                          dbname + "/" + tablename + "/" + colname,
                          secondaryIndexPath(dbname, tablename, colname), false);
}

BPTree* StorageEngine::getCompositeIndexTree(const std::string& dbname,
                                              const std::string& tablename,
                                              const std::string& indexName) const {
    return loadBtreeIndex(secondaryIndexCache_,
                          dbname + "/" + tablename + "/C/" + indexName,
                          relationDir(dbname, tablename) /
                              (tablename + ".idx_" + indexName), false);
}

// ========================================================================
// MAC address (macaddr / macaddr8) helpers
// Storage: fixed 6 bytes (macaddr) or 8 bytes (macaddr8), raw network order.
// The shared codec validates each PostgreSQL notation, including grouping,
// octet widths and MAC48-to-EUI64 expansion. It never discards arbitrary
// separators. Canonical output is lowercase colon-separated.
// ========================================================================
static bool normalizeMacAddr(const std::string& in, int numBytes, uint8_t* out) {
    std::array<uint8_t, 8> bytes{};
    if (!dbms::parseMacAddress(in, static_cast<size_t>(numBytes), bytes))
        return false;
    std::memcpy(out, bytes.data(), static_cast<size_t>(numBytes));
    return true;
}

static std::string formatMacAddr(const uint8_t* bytes, int numBytes) {
    return dbms::formatMacAddress(bytes, static_cast<size_t>(numBytes));
}

// ========================================================================
// UUID helper
// New relations store the UUID's 16 RFC bytes.  The text helper also keeps
// pre-migration 36-byte schemas readable.
// ========================================================================
static bool normalizeUuid(const std::string& in, std::string& out) {
    UuidValue uuid;
    if (!UuidValue::parse(in, uuid)) return false;
    out = uuid.toString();
    return true;
}

static bool parseUuidValue(const std::string& input, UuidValue& output) {
    return UuidValue::parse(input, output);
}

static bool writeUuidStorage(const std::string& input, char* destination,
                             size_t length) {
    std::memset(destination, 0, length);
    if (input.empty()) return true;
    UuidValue uuid;
    if (!UuidValue::parse(input, uuid)) return false;
    if (length == uuid.bytes().size()) {
        std::memcpy(destination, uuid.bytes().data(), uuid.bytes().size());
        return true;
    }
    // Old schema files used a 36-byte canonical text datum.  Preserve their
    // physical layout until ALTER/rewrite migrates the relation.
    const std::string canonical = uuid.toString();
    if (canonical.size() > length) return false;
    std::memcpy(destination, canonical.data(), canonical.size());
    return true;
}

// ========================================================================
// bytea helper
// Accepts PostgreSQL hex format (\xDEADBEEF) or escape format (literal bytes
// with \\ and \ooo octal escapes), decodes to raw bytes, and re-emits the
// canonical lowercase hex form "\xhh...". Whitespace inside hex is ignored.
// ========================================================================
static bool normalizeBytea(const std::string& in, std::string& out) {
    ByteaValue value;
    if (!ByteaValue::parse(in, value)) return false;
    out = value.toString();
    return true;
}

// ========================================================================
// inet / cidr address parser
// Parses a dotted-quad IPv4 or an IPv6 address (with :: zero compression) plus
// an optional /prefix into family (2=IPv4, 3=IPv6), prefix length and a 16-byte
// address buffer. Returns false on any malformed octet/group or out-of-range
// prefix. Mirrors the on-disk layout used by buildRowBuffer/extractColumnValue.
// ========================================================================
static bool parseInetAddr(const std::string& in, uint8_t& family,
                          uint8_t& prefix, uint8_t addr[16],
                          bool requireNetworkAddress = false) {
    dbms::NetworkAddressValue parsed;
    if (!dbms::parseNetworkAddress(in, parsed, requireNetworkAddress))
        return false;
    family = parsed.family;
    prefix = parsed.bits;
    std::memcpy(addr, parsed.address.data(), parsed.address.size());
    return true;
}

// ========================================================================
// Bit string (bit / bit varying) helper
// Storage: the literal '0'/'1' string (variable-length). `declaredLen` carries
// the declared bit length n (Column::dsize). For "bit" the value must be
// exactly n bits; for "bit varying" at
// most n bits. Accepts an optional B'...'/b'...' wrapper or plain quotes and
// writes the canonical bare 0/1 string to `out`.
// ========================================================================
static bool normalizeBitString(const std::string& in, const std::string& dataType,
                               size_t declaredLen, std::string& out) {
    std::string s = in;
    if (s.size() >= 3 && (s[0] == 'B' || s[0] == 'b') && s[1] == '\'' && s.back() == '\'')
        s = s.substr(2, s.size() - 3);
    else if (s.size() >= 2 && s.front() == '\'' && s.back() == '\'')
        s = s.substr(1, s.size() - 2);
    for (char ch : s) {
        if (ch != '0' && ch != '1') return false;
    }
    if (dataType == "bit") {
        if (s.size() != declaredLen) return false;
    } else {  // bit varying
        if (s.size() > declaredLen) return false;
    }
    out = s;
    return true;
}

// ========================================================================
// Geometric types (line / lseg / box / path / polygon / circle)
// Stored as the canonical PG text form (variable-length). `point` is handled
// separately as packed binary. Validation extracts coordinate numbers, checks
// the count/structure per type, and re-emits the canonical bracketed form.
// ========================================================================
static bool isGeometricTextType(const std::string& dt) {
    return dt == "line" || dt == "lseg" || dt == "box" ||
           dt == "path" || dt == "polygon" || dt == "circle";
}

static bool normalizeGeometry(const std::string& in, const std::string& type, std::string& out) {
    return dbms::normalizeGeometryText(in, type, out, true);
}

// ========================================================================
// Range types (int4range / int8range / numrange / tsrange / tstzrange /
// daterange). Stored as canonical PG text. Validates the literal grammar
// (`empty` or `[/(` lower `,` upper `]/)` with optional infinite bounds),
// parses bounds per element type, enforces lower <= upper, and canonicalizes:
// infinite bounds become exclusive; discrete integer ranges fold to `[)` form;
// degenerate ranges become `empty`.
// ========================================================================
static bool isRangeType(const std::string& dt) {
    return dt == "int4range" || dt == "int8range" || dt == "numrange" ||
           dt == "tsrange" || dt == "tstzrange" || dt == "daterange";
}

static bool parseRangeTimestampMicros(const std::string& input,
                                      bool withTimeZone,
                                      int64_t& result) {
    std::string text = trim(input);
    std::string lowered = text;
    for (char& c : lowered)
        c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    if (lowered == "infinity") {
        result = std::numeric_limits<int64_t>::max();
        return true;
    }
    if (lowered == "-infinity") {
        result = std::numeric_limits<int64_t>::min();
        return true;
    }

    size_t separator = text.find_first_of(" Tt");
    if (separator != std::string::npos && text[separator] != ' ')
        text[separator] = ' ';
    const size_t timeStart = separator == std::string::npos
        ? text.size() : separator + 1;
    size_t zonePosition = std::string::npos;
    for (size_t i = timeStart; i < text.size(); ++i) {
        if (text[i] == '+' || text[i] == '-') {
            zonePosition = i;
            break;
        }
    }
    const bool hasZulu = !text.empty() &&
        (text.back() == 'Z' || text.back() == 'z');
    const size_t fractionEnd = zonePosition != std::string::npos
        ? zonePosition : (hasZulu ? text.size() - 1 : text.size());
    const size_t dot = text.find('.', timeStart);

    int64_t micros = 0;
    if (dot != std::string::npos) {
        if (dot >= fractionEnd || dot + 1 == fractionEnd) return false;
        size_t digits = 0;
        for (size_t i = dot + 1; i < fractionEnd; ++i) {
            if (text[i] < '0' || text[i] > '9') return false;
            if (digits < 6) micros = micros * 10 + (text[i] - '0');
            ++digits;
        }
        while (digits < 6) {
            micros *= 10;
            ++digits;
        }
        if (digits > 6) {
            bool trailingNonzero = false;
            for (size_t i = dot + 8; i < fractionEnd; ++i) {
                if (text[i] != '0') {
                    trailingNonzero = true;
                    break;
                }
            }
            const bool roundUp = text[dot + 7] > '5' ||
                (text[dot + 7] == '5' &&
                 (trailingNonzero || micros % 2 != 0));
            if (roundUp) ++micros;
        }
        text.erase(dot, fractionEnd - dot);
    }

    if (!withTimeZone) {
        zonePosition = std::string::npos;
        for (size_t i = timeStart; i < text.size(); ++i) {
            if (text[i] == '+' || text[i] == '-') {
                zonePosition = i;
                break;
            }
        }
        if (zonePosition != std::string::npos) text.erase(zonePosition);
        else if (!text.empty() &&
                 (text.back() == 'Z' || text.back() == 'z')) text.pop_back();
    }

    int64_t seconds = parseTimestampToSeconds(text);
    if (seconds == 0 || isInfiniteTimestamp(seconds)) return false;
    if (micros == 1000000) {
        ++seconds;
        micros = 0;
    }
    result = seconds * 1000000LL + micros;
    return true;
}

static bool normalizeRange(const std::string& in, const std::string& type, std::string& out) {
    std::string s = trim(in);
    if (s.size() == 5) {
        std::string lc;
        for (char c : s) lc += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        if (lc == "empty") { out = "empty"; return true; }
    }
    if (s.size() < 3) return false;
    char lb = s.front(), ub = s.back();
    if ((lb != '[' && lb != '(') || (ub != ']' && ub != ')')) return false;
    std::string body = s.substr(1, s.size() - 2);

    // Split at the top-level comma (quotes protect commas inside bounds).
    size_t commaPos = std::string::npos;
    bool inq = false;
    for (size_t i = 0; i < body.size(); ++i) {
        if (body[i] == '"') inq = !inq;
        else if (!inq && body[i] == ',') { commaPos = i; break; }
    }
    if (commaPos == std::string::npos) return false;
    auto unq = [](std::string v) -> std::string {
        v = trim(v);
        if (v.size() >= 2 && v.front() == '"' && v.back() == '"') v = v.substr(1, v.size() - 2);
        return v;
    };
    std::string lo = unq(body.substr(0, commaPos));
    std::string hi = unq(body.substr(commaPos + 1));
    bool loInf = lo.empty(), hiInf = hi.empty();

    double loV = 0, hiV = 0;
    int64_t loI = 0, hiI = 0;
    std::optional<Numeric> loNumeric, hiNumeric;
    const bool discrete = (type == "int4range" || type == "int8range");
    const bool discreteDate = type == "daterange";
    const bool timestampRange = type == "tsrange" || type == "tstzrange";
    auto parseBound = [&](const std::string& b, double& dv, int64_t& iv) -> bool {
        if (discrete) {
            try { size_t p = 0; long long v = std::stoll(b, &p); if (p != b.size()) return false;
                  if (type == "int4range" &&
                      (v < std::numeric_limits<int32_t>::min() ||
                       v > std::numeric_limits<int32_t>::max())) return false;
                  iv = v; dv = static_cast<double>(v); return true; }
            catch (...) { return false; }
        } else if (type == "daterange") {
            Date d(b.c_str());
            if (d.year == 0) return false;
            iv = d.convert();
            dv = static_cast<double>(iv);
            return true;
        }
        int64_t v = 0;
        if (!parseRangeTimestampMicros(b, type == "tstzrange", v))
            return false;
        iv = v;
        dv = static_cast<double>(v);
        return true;
    };
    if (type == "numrange") {
        try {
            if (!loInf) loNumeric.emplace(lo);
            if (!hiInf) hiNumeric.emplace(hi);
        } catch (...) {
            return false;
        }
    } else {
        if (!loInf && !parseBound(lo, loV, loI)) return false;
        if (!hiInf && !parseBound(hi, hiV, hiI)) return false;
    }
    if (!loInf && !hiInf) {
        if (discrete) {
            if (loI > hiI) return false;
            if (loI == hiI && !(lb == '[' && ub == ']')) {
                out = "empty";
                return true;
            }
        } else if (type == "numrange") {
            if (*loNumeric > *hiNumeric) return false;
        } else if (timestampRange) {
            if (loI > hiI) return false;
        } else if (loV > hiV) {
            return false;
        }
    }

    // Discrete integer ranges canonicalize to inclusive-lower / exclusive-upper.
    if (discrete) {
        const int64_t maximum = type == "int4range"
            ? std::numeric_limits<int32_t>::max()
            : std::numeric_limits<int64_t>::max();
        if (!loInf) {
            if (lb == '(') {
                if (loI == maximum) return false;
                ++loI;
            }
            lb = '[';
            loV = static_cast<double>(loI);
        }
        if (!hiInf) {
            if (ub == ']') {
                if (hiI == maximum) return false;
                ++hiI;
            }
            ub = ')';
            hiV = static_cast<double>(hiI);
        }
    } else if (discreteDate) {
        if (!loInf) {
            Date lowerDate(lo.c_str());
            if (lb == '(') {
                lowerDate = lowerDate + 1;
                if (lowerDate.year == 0) {
                    out = "empty";
                    return true;
                }
            }
            lb = '[';
            loI = lowerDate.convert();
            loV = static_cast<double>(loI);
            lo = str(lowerDate);
        }
        if (!hiInf) {
            Date upperDate(hi.c_str());
            if (ub == ']') {
                upperDate = upperDate + 1;
                if (upperDate.year == 0) {
                    hiInf = true;
                    hi.clear();
                } else {
                    hiI = upperDate.convert();
                    hiV = static_cast<double>(hiI);
                    hi = str(upperDate);
                }
            } else {
                hi = str(upperDate);
            }
            ub = ')';
        }
    }
    if (loInf) lb = '(';   // infinite bounds are always exclusive
    if (hiInf) ub = ')';

    if (!loInf && !hiInf) {
        if (discrete) {
            if (loI >= hiI) {
                out = "empty";
                return true;
            }
        } else if (type == "numrange") {
            if (*loNumeric > *hiNumeric) return false;
            if (*loNumeric == *hiNumeric && !(lb == '[' && ub == ']')) {
                out = "empty";
                return true;
            }
        } else if (timestampRange) {
            if (loI > hiI) return false;
            if (loI == hiI && !(lb == '[' && ub == ']')) {
                out = "empty";
                return true;
            }
        } else {
            if (loV > hiV) {
                // Equal original date bounds can cross after canonicalizing
                // an exclusive lower bound; the represented set is empty.
                if (discreteDate) { out = "empty"; return true; }
                return false;
            }
            if (loV == hiV) {
                bool bothInclusive = (lb == '[' && ub == ']');
                if (!bothInclusive) { out = "empty"; return true; }
            }
        }
    }

    auto emit = [](const std::string& b) -> std::string {
        if (b.empty()) return "";
        if (b.find_first_of(" ,") != std::string::npos) return "\"" + b + "\"";
        return b;
    };
    std::string loStr = loInf ? "" : (discrete ? std::to_string(loI) : emit(lo));
    std::string hiStr = hiInf ? "" : (discrete ? std::to_string(hiI) : emit(hi));
    out = std::string(1, lb) + loStr + "," + hiStr + std::string(1, ub);
    return true;
}

// ========================================================================
// Array literals ({1,2,3}, {{1,2},{3,4}}, {"a,b","c"}, NULL elements).
// Stored as canonical PG text. Validates brace structure, that siblings are
// uniformly scalars or equal-length sub-arrays (rectangular dimensions), and
// that scalar elements parse for numeric element types; re-emits with
// insignificant whitespace removed and elements quoted only where required.
// ========================================================================
static bool arrayElemIsNumeric(const std::string& t) {
    return t == "int" || t == "integer" || t == "int2" || t == "int4" || t == "int8" ||
           t == "smallint" || t == "bigint" || t == "tinyint" || t == "long" ||
           t == "serial" || t == "bigserial" || t == "smallserial";
}
static bool arrayElemIsFloat(const std::string& t) {
    return t == "numeric" || t == "decimal" || t == "float" || t == "float4" ||
           t == "float8" || t == "double" || t == "real";
}
static bool validateArrayScalar(const std::string& tok, const std::string& elemType) {
    if (arrayElemIsNumeric(elemType)) {
        try { size_t p = 0; std::stoll(tok, &p); return p == tok.size(); } catch (...) { return false; }
    }
    if (arrayElemIsFloat(elemType)) {
        try { size_t p = 0; std::stod(tok, &p); return p == tok.size(); } catch (...) { return false; }
    }
    if (elemType == "money") {
        int64_t minorUnits = 0;
        return parseMoneyLiteral(tok, minorUnits);
    }
    if (elemType == "uuid") {
        UuidValue uuid;
        return UuidValue::parse(tok, uuid);
    }
    return true;  // text-like element types accept any contents
}

struct ArrayParser {
    const std::string& s;
    const std::string& elemType;
    std::function<std::string(const std::string&)> convertScalar;
    size_t i = 0;
    bool ok = true;
    explicit ArrayParser(const std::string& str, const std::string& et,
                         std::function<std::string(const std::string&)> converter = {})
        : s(str), elemType(et), convertScalar(std::move(converter)) {}
    void skipWs() { while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i; }

    // Returns nesting depth (0 = scalar, >=1 = array) and, for arrays, the child
    // element count via `count`. Appends canonical text to `out`.
    int parseValue(std::string& out, size_t& count) {
        skipWs();
        if (i >= s.size()) { ok = false; return -1; }
        if (s[i] == '{') return parseArray(out, count);
        return parseScalar(out);
    }
    int parseScalar(std::string& out) {
        skipWs();
        std::string tok;
        bool quoted = false;
        if (i < s.size() && s[i] == '"') {
            quoted = true; ++i;
            while (i < s.size() && s[i] != '"') {
                if (s[i] == '\\' && i + 1 < s.size()) { tok += s[i + 1]; i += 2; }
                else { tok += s[i]; ++i; }
            }
            if (i >= s.size()) { ok = false; return -1; }
            ++i;  // closing quote
        } else {
            while (i < s.size() && s[i] != ',' && s[i] != '}' && s[i] != '{') { tok += s[i]; ++i; }
            tok = trim(tok);
        }
        if (!quoted) {
            std::string up;
            for (char c : tok) up += static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
            if (up == "NULL") { out += "NULL"; return 0; }
            if (tok.empty()) { ok = false; return -1; }  // bare empty element is invalid
        }
        if (convertScalar) {
            tok = convertScalar(tok);
            quoted = false;
        } else if (!validateArrayScalar(tok, elemType)) { ok = false; return -1; }
        bool needQuote = quoted || tok.empty() ||
                         tok.find_first_of(" ,{}\"\\") != std::string::npos;
        std::string lower;
        for (unsigned char ch : tok) lower += static_cast<char>(std::tolower(ch));
        needQuote = needQuote || lower == "null";
        if (needQuote) {
            std::string q = "\"";
            for (char c : tok) { if (c == '"' || c == '\\') q += '\\'; q += c; }
            q += "\"";
            out += q;
        } else {
            out += tok;
        }
        return 0;
    }
    int parseArray(std::string& out, size_t& count) {
        skipWs();
        if (i >= s.size() || s[i] != '{') { ok = false; return -1; }
        ++i;
        out += '{';
        count = 0;
        skipWs();
        if (i < s.size() && s[i] == '}') { ++i; out += '}'; return 1; }  // empty array
        int childDepth = -2;
        size_t childCount = 0;  // for rectangular check among sibling sub-arrays
        while (true) {
            std::string child;
            size_t cc = 0;
            int d = parseValue(child, cc);
            if (!ok) return -1;
            if (childDepth == -2) { childDepth = d; childCount = cc; }
            else {
                if (d != childDepth) { ok = false; return -1; }       // mixed scalar/array
                if (d >= 1 && cc != childCount) { ok = false; return -1; }  // ragged dims
            }
            out += child;
            ++count;
            skipWs();
            if (i >= s.size()) { ok = false; return -1; }
            if (s[i] == ',') { ++i; out += ','; continue; }
            if (s[i] == '}') { ++i; out += '}'; break; }
            ok = false; return -1;
        }
        return childDepth + 1;
    }
};

static bool normalizeArray(const std::string& in, const std::string& elemType, std::string& out) {
    try {
        auto literal = sql_array_text::parse(in);
        ExprEvaluator evaluator;
        CastExpr cast;cast.typeName=ExprHelper::canonicalResultTypeName(elemType);
        // Older embedded schemas persisted the public full array spelling.
        // Their scalar elements still cast to the element, never to an array.
        if (cast.typeName.size() >= 2 && cast.typeName.compare(cast.typeName.size()-2,2,"[]") == 0)
            cast.typeName.resize(cast.typeName.size()-2);
        auto parameter=std::make_unique<ParameterExpr>();parameter->declaredType="unknown";
        parameter->origin=ParameterOrigin::RuntimeCell;
        cast.operand=std::move(parameter);
        const auto convert=[&](const std::string& value) {
            RowContext row;row.setParameters({ExprValue("unknown",value,false)});
            return evaluator.eval(&cast,row).value;
        };
        ArrayParser parser(literal.body,elemType,convert);
        std::string result;size_t count=0;
        parser.parseValue(result,count);parser.skipWs();
        if(!parser.ok || parser.i!=literal.body.size())return false;
        literal.body=std::move(result);out=sql_array_text::render(literal);
        return true;
    } catch(const DbError&) {return false;}
}

// ========================================================================
// Full-text search types.
// tsvector: parse `lexeme[:poslist]` entries (quoted or bare), validate, and
//   canonicalize — lexemes sorted (length-first then bytewise, as PG does),
//   deduplicated with merged positions, positions sorted/deduped, default
//   weight D omitted, lexemes single-quoted on output.
// tsquery: validate the boolean grammar (! > <-> > & > |, parentheses, quoted
//   or bare lexemes with optional :weight/* flags); stored verbatim.
// ========================================================================
static bool normalizeTsVectorImpl(const std::string& in, std::string& out) {
    std::map<std::string, std::set<std::pair<int, char>>> positions;
    std::map<std::string, bool> present;  // lexeme seen (even without positions)
    size_t i = 0, n = in.size();
    auto skipWs = [&]() { while (i < n && std::isspace(static_cast<unsigned char>(in[i]))) ++i; };
    while (true) {
        skipWs();
        if (i >= n) break;
        std::string lex;
        if (in[i] == '\'') {
            ++i;
            bool closed = false;
            while (i < n) {
                if (in[i] == '\'') {
                    if (i + 1 < n && in[i + 1] == '\'') { lex += '\''; i += 2; }
                    else { ++i; closed = true; break; }
                } else if (in[i] == '\\' && i + 1 < n) { lex += in[i + 1]; i += 2; }
                else { lex += in[i]; ++i; }
            }
            if (!closed) return false;
        } else {
            while (i < n && !std::isspace(static_cast<unsigned char>(in[i])) && in[i] != ':') {
                if (in[i] == '\\' && i + 1 < n) { lex += in[i + 1]; i += 2; }
                else { lex += in[i]; ++i; }
            }
        }
        if (lex.empty()) return false;
        present[lex];  // ensure key exists
        if (i < n && in[i] == ':') {
            ++i;
            while (true) {
                if (i >= n || !std::isdigit(static_cast<unsigned char>(in[i]))) return false;
                int p = 0;
                while (i < n && std::isdigit(static_cast<unsigned char>(in[i]))) { p = p * 10 + (in[i] - '0'); ++i; }
                if (p <= 0) return false;
                char w = 'D';
                if (i < n && in[i] >= 'A' && in[i] <= 'D') { w = in[i]; ++i; }
                positions[lex].insert({p, w});
                if (i < n && in[i] == ',') { ++i; continue; }
                break;
            }
        }
        if (i < n && !std::isspace(static_cast<unsigned char>(in[i]))) return false;  // junk after entry
    }
    std::vector<std::string> keys;
    for (auto& kv : present) keys.push_back(kv.first);
    std::sort(keys.begin(), keys.end(), [](const std::string& a, const std::string& b) {
        if (a.size() != b.size()) return a.size() < b.size();
        return a < b;
    });
    std::string result;
    for (const auto& k : keys) {
        if (!result.empty()) result += ' ';
        result += '\'';
        for (char c : k) { if (c == '\'') result += "''"; else if (c == '\\') result += "\\\\"; else result += c; }
        result += '\'';
        auto it = positions.find(k);
        if (it != positions.end() && !it->second.empty()) {
            result += ':';
            bool first = true;
            for (const auto& pw : it->second) {
                if (!first) result += ',';
                first = false;
                result += std::to_string(pw.first);
                if (pw.second != 'D') result += pw.second;
            }
        }
    }
    out = result;
    return true;
}

struct TsQueryValidator {
    const std::vector<int>& toks;
    size_t p = 0;
    explicit TsQueryValidator(const std::vector<int>& t) : toks(t) {}
    enum { LEX, AND, OR, NOT, PHRASE, LP, RP };
    bool primary() {
        if (p < toks.size() && toks[p] == LP) {
            ++p;
            if (!orExpr()) return false;
            if (p >= toks.size() || toks[p] != RP) return false;
            ++p; return true;
        }
        if (p < toks.size() && toks[p] == LEX) { ++p; return true; }
        return false;
    }
    bool notExpr() {
        if (p < toks.size() && toks[p] == NOT) { ++p; return notExpr(); }
        return primary();
    }
    bool phraseExpr() {
        if (!notExpr()) return false;
        while (p < toks.size() && toks[p] == PHRASE) { ++p; if (!notExpr()) return false; }
        return true;
    }
    bool andExpr() {
        if (!phraseExpr()) return false;
        while (p < toks.size() && toks[p] == AND) { ++p; if (!phraseExpr()) return false; }
        return true;
    }
    bool orExpr() {
        if (!andExpr()) return false;
        while (p < toks.size() && toks[p] == OR) { ++p; if (!andExpr()) return false; }
        return true;
    }
};

static bool isValidTsQuery(const std::string& in) {
    enum { LEX, AND, OR, NOT, PHRASE, LP, RP };
    std::vector<int> toks;
    size_t i = 0, n = in.size();
    auto skipWs = [&]() { while (i < n && std::isspace(static_cast<unsigned char>(in[i]))) ++i; };
    while (true) {
        skipWs();
        if (i >= n) break;
        char c = in[i];
        if (c == '(') { toks.push_back(LP); ++i; }
        else if (c == ')') { toks.push_back(RP); ++i; }
        else if (c == '&') { toks.push_back(AND); ++i; }
        else if (c == '|') { toks.push_back(OR); ++i; }
        else if (c == '!') { toks.push_back(NOT); ++i; }
        else if (c == '<') {
            if (i + 2 < n && in[i + 1] == '-' && in[i + 2] == '>') { toks.push_back(PHRASE); i += 3; }
            else {
                size_t j = i + 1;
                if (j >= n || !std::isdigit(static_cast<unsigned char>(in[j]))) return false;
                while (j < n && std::isdigit(static_cast<unsigned char>(in[j]))) ++j;
                if (j >= n || in[j] != '>') return false;
                toks.push_back(PHRASE); i = j + 1;
            }
        } else if (c == '\'') {
            ++i; bool closed = false;
            while (i < n) {
                if (in[i] == '\'') { if (i + 1 < n && in[i + 1] == '\'') i += 2; else { ++i; closed = true; break; } }
                else if (in[i] == '\\' && i + 1 < n) i += 2;
                else ++i;
            }
            if (!closed) return false;
            if (i < n && in[i] == ':') { ++i; while (i < n && (std::isalnum(static_cast<unsigned char>(in[i])) || in[i] == '*')) ++i; }
            toks.push_back(LEX);
        } else if (std::isalnum(static_cast<unsigned char>(c)) || static_cast<unsigned char>(c) >= 128) {
            while (i < n && (std::isalnum(static_cast<unsigned char>(in[i])) || in[i] == '_' || static_cast<unsigned char>(in[i]) >= 128)) ++i;
            if (i < n && in[i] == ':') { ++i; while (i < n && (std::isalnum(static_cast<unsigned char>(in[i])) || in[i] == '*')) ++i; }
            toks.push_back(LEX);
        } else {
            return false;
        }
    }
    if (toks.empty()) return false;
    TsQueryValidator v(toks);
    if (!v.orExpr()) return false;
    return v.p == toks.size();
}

// ========================================================================
// jsonpath structural validation. Not a full SQL/JSON path grammar parser;
// a pragmatic structural check (low false-rejection risk): optional strict/lax
// mode, balanced () and [], no empty [] subscripts, no ".." or trailing ".",
// a valid starting token, and no unterminated string. Stored verbatim.
// ========================================================================
static bool isValidJsonPath(const std::string& in) {
    std::string s = trim(in);
    auto startsWord = [&](const char* w) {
        size_t l = std::strlen(w);
        return s.size() >= l && s.compare(0, l, w) == 0 &&
               (s.size() == l || std::isspace(static_cast<unsigned char>(s[l])));
    };
    if (startsWord("strict") || startsWord("lax")) {
        size_t sp = s.find_first_of(" \t");
        s = (sp == std::string::npos) ? "" : trim(s.substr(sp));
    }
    if (s.empty()) return false;

    // First significant char must begin a primary, not a dangling operator/accessor.
    char f = s[0];
    if (std::strchr(".,)]?&|*/%<>=", f) != nullptr) return false;

    int paren = 0, brack = 0;
    bool inStr = false; char q = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (inStr) {
            if (c == '\\' && i + 1 < s.size()) { ++i; continue; }
            if (c == q) inStr = false;
            continue;
        }
        if (c == '"' || c == '\'') { inStr = true; q = c; continue; }
        if (c == '(') { ++paren; continue; }
        if (c == ')') { if (--paren < 0) return false; continue; }
        if (c == '[') {
            ++brack;
            size_t j = i + 1;
            while (j < s.size() && std::isspace(static_cast<unsigned char>(s[j]))) ++j;
            if (j < s.size() && s[j] == ']') return false;  // empty subscript
            continue;
        }
        if (c == ']') { if (--brack < 0) return false; continue; }
        if (c == '.') {
            if (i + 1 >= s.size()) return false;            // trailing dot
            if (s[i + 1] == '.') return false;              // ".."
            continue;
        }
    }
    if (inStr) return false;                                 // unterminated string
    return paren == 0 && brack == 0;
}

// ========================================================================
// interval input parsing + canonicalization to PostgreSQL "postgres" style:
//   [N year[s]] [N mon[s]] [N day[s]] [[-]HH:MM:SS[.ffff]]
// Supports the verbose form (number+unit pairs: year/mon/week/day/hour/min/sec
// and common abbreviations), HH:MM:SS time, the SQL year-month shorthand
// "Y-M", a bare number (seconds), and a trailing "ago" (negates all). Fractional
// field values cascade down (PG: 1 month = 30 days, 1 day = 24 h). Storage
// and typed expression inputs share checked integral calendar/time fields.
// ========================================================================
static bool normalizeInterval(const std::string& value, std::string& normalized) {
    const auto parsed = parseIntervalInput(value);
    if (!parsed.ok) return false;
    normalized = formatIntervalInput(parsed.months, parsed.days, parsed.micros, true);
    return true;
}

// One real runtime datum, never interpolated into SQL. Scalar/array input
// and every storage writer use the same declaration-owned datum cast.
static bool normalizeModifiedColumn(const Column& column, const std::string& value,
                                    std::string& normalized) {
    try {
        CastExpr cast;
        cast.typeName = column.dataType + std::string(column.isArray ? "[]" : "");
        cast.typeMods = column.dataType == "numeric" ? numeric_type_detail::unpack(column.typeMod)
                                                   : interval_type_detail::unpack(column.typeMod);
        auto parameter = std::make_unique<ParameterExpr>();
        parameter->origin = ParameterOrigin::RuntimeCell;
        parameter->declaredType = "unknown";
        cast.operand = std::move(parameter);
        RowContext context;
        context.setParameters({ExprValue("unknown", value, false)});
        ExprEvaluator evaluator;
        normalized = evaluator.eval(&cast, context).value;
        if (column.isArray) {
            std::string canonical;
            if (!normalizeArray(normalized, column.dataType, canonical)) return false;
            normalized = std::move(canonical);
        }
        return true;
    } catch (const DbError&) { return false; }
}

// ========================================================================
// Composite-type row literal: "(v1,v2,...)". Validates the field count against
// the composite type definition, checks numeric fields parse, and re-emits the
// canonical form (whitespace trimmed, fields quoted only where required). An
// empty field is treated as NULL.
// ========================================================================
static bool normalizeComposite(const std::string& in, const StorageEngine::CompositeType& ct,
                               std::string& out) {
    std::string s = trim(in);
    if (s.size() < 2 || s.front() != '(' || s.back() != ')') return false;
    std::string body = s.substr(1, s.size() - 2);

    std::vector<std::string> vals;
    std::string cur;
    bool inq = false;
    for (size_t i = 0; i < body.size(); ++i) {
        char c = body[i];
        if (inq) {
            if (c == '"') {
                if (i + 1 < body.size() && body[i + 1] == '"') { cur += '"'; ++i; }
                else inq = false;
            } else if (c == '\\' && i + 1 < body.size()) { cur += body[i + 1]; ++i; }
            else cur += c;
        } else {
            if (c == '"') inq = true;
            else if (c == ',') { vals.push_back(cur); cur.clear(); }
            else cur += c;
        }
    }
    vals.push_back(cur);
    if (inq) return false;
    if (vals.size() != ct.fields.size()) return false;

    std::string result = "(";
    for (size_t k = 0; k < vals.size(); ++k) {
        std::string v = trim(vals[k]);
        std::string ftype = toLowerUtf8(ct.fields[k].second);
        size_t par = ftype.find('(');
        if (par != std::string::npos) ftype = ftype.substr(0, par);
        ftype = trim(ftype);
        if (!v.empty()) {
            bool ok = true;
            if (ftype == "int" || ftype == "integer" || ftype == "int2" || ftype == "int4" ||
                ftype == "int8" || ftype == "smallint" || ftype == "bigint") {
                try { size_t p = 0; std::stoll(v, &p); ok = (p == v.size()); } catch (...) { ok = false; }
            } else if (ftype == "numeric" || ftype == "decimal" || ftype == "real" ||
                       ftype == "float" || ftype == "float4" || ftype == "float8" ||
                       ftype == "double" || ftype == "double precision") {
                try { size_t p = 0; std::stod(v, &p); ok = (p == v.size()); } catch (...) { ok = false; }
            }
            if (!ok) return false;
        }
        if (k) result += ",";
        bool needQuote = !v.empty() && v.find_first_of(",()\"\\") != std::string::npos;
        if (needQuote) {
            result += '"';
            for (char c : v) { if (c == '"') result += "\"\""; else result += c; }
            result += '"';
        } else {
            result += v;
        }
    }
    result += ")";
    out = result;
    return true;
}

// ---------------------------------------------------------------------
// Stored-NULL row binding: scan loops bind the current row (engine, rid,
// table) so extractColumnValue can consult the heap null bitmap for the
// row being projected. Unbound paths keep raw extraction.
// ---------------------------------------------------------------------
static thread_local const StorageEngine* g_nullRowEngine = nullptr;
static thread_local int64_t g_nullRowRid = -1;
static thread_local size_t g_nullRowNatts = 0;
static thread_local std::string g_nullRowTable;
static thread_local std::string g_nullRowDb;


void StorageEngine::bindNullRow(const StorageEngine* eng, const std::string& db,
                                const std::string& table, int64_t rid, size_t natts) {
    if (!eng || rid < 0) return;
    g_nullRowEngine = eng; g_nullRowRid = rid;
    g_nullRowNatts = natts; g_nullRowTable = table; g_nullRowDb = db;
}

void StorageEngine::unbindNullRow() {
    g_nullRowEngine = nullptr; g_nullRowRid = -1;
    g_nullRowNatts = 0; g_nullRowTable.clear(); g_nullRowDb.clear();
}

StorageEngine::NullRowBindingState StorageEngine::captureNullRowBinding() {
    return {g_nullRowEngine, g_nullRowDb, g_nullRowTable, g_nullRowRid, g_nullRowNatts};
}

void StorageEngine::restoreNullRowBinding(NullRowBindingState&& state) noexcept {
    g_nullRowEngine = state.engine; g_nullRowRid = state.rid; g_nullRowNatts = state.natts;
    g_nullRowDb.swap(state.database); g_nullRowTable.swap(state.table);
}

class NullRowBinding {
public:
    NullRowBinding(const StorageEngine* eng, const std::string& db,
                   const std::string& table, int64_t rid, size_t natts) {
        if (!eng || rid < 0) return;
        saved_ = (g_nullRowEngine != nullptr);
        if (saved_) { oldEng_ = g_nullRowEngine; oldRid_ = g_nullRowRid;
                      oldNatts_ = g_nullRowNatts; oldTable_ = g_nullRowTable; oldDb_ = g_nullRowDb; }
        g_nullRowEngine = eng; g_nullRowRid = rid;
        g_nullRowNatts = natts; g_nullRowTable = table; g_nullRowDb = db;
        active_ = true;
    }
    ~NullRowBinding() {
        if (!active_) return;
        if (saved_) {
            g_nullRowEngine = oldEng_; g_nullRowRid = oldRid_;
            g_nullRowNatts = oldNatts_; g_nullRowTable = oldTable_; g_nullRowDb = oldDb_;
        } else {
            g_nullRowEngine = nullptr; g_nullRowRid = -1;
            g_nullRowNatts = 0; g_nullRowTable.clear(); g_nullRowDb.clear();
        }
    }
private:
    bool active_ = false;
    bool saved_ = false;
    const StorageEngine* oldEng_ = nullptr;
    int64_t oldRid_ = -1;
    size_t oldNatts_ = 0;
    std::string oldTable_;
    std::string oldDb_;
};

// Materialized OLD/NEW images have no live RID (DELETE can already have
// removed the tuple). Keep their own v2 NULL bitmap attached while decoding,
// rather than reusing another scan row's bitmap or the legacy int sentinel.
class BufferedNullRowBinding {
public:
    BufferedNullRowBinding(const TableSchema& schema,
                           const std::vector<bool>& nulls)
        : oldSchema_(g_bufferedConditionSchema),
          oldNulls_(g_bufferedConditionNulls),
          active_(usesHeapTupleHeader(schema.formatVersion) &&
                  nulls.size() == schema.len) {
        if (active_) {
            g_bufferedConditionSchema = &schema;
            g_bufferedConditionNulls = &nulls;
        }
    }
    ~BufferedNullRowBinding() {
        if (active_) {
            g_bufferedConditionSchema = oldSchema_;
            g_bufferedConditionNulls = oldNulls_;
        }
    }
    BufferedNullRowBinding(const BufferedNullRowBinding&) = delete;
    BufferedNullRowBinding& operator=(const BufferedNullRowBinding&) = delete;
private:
    const TableSchema* oldSchema_;
    const std::vector<bool>* oldNulls_;
    bool active_;
};

void detail::decodeStoredRowValues(StorageEngine& engine,
                                  const std::string& database,
                                  const std::string& raw,
                                  const TableSchema& schema,
                                  const std::vector<bool>& storedNulls,
                                  std::vector<std::string>& values,
                                  std::vector<bool>& nulls) {
    if (storedNulls.size() != schema.len)
        throw DbError("XX000", "stored row NULL bitmap width mismatch");
    BufferedNullRowBinding binding(schema, storedNulls);
    values.clear(); nulls.clear();
    values.reserve(schema.len); nulls.reserve(schema.len);
    for (size_t i = 0; i < schema.len; ++i) {
        bool computedNull = false;
        values.push_back(engine.extractColumnValue(raw, schema, i,
                                                   database, true, &computedNull));
        nulls.push_back(computedNull ||
            (schema.cols[i].generatedKind != 'v' && storedNulls[i]));
    }
}


std::string StorageEngine::extractColumnValueStatic(const std::string& rowBuffer,
                                                     const TableSchema& tbl, size_t colIdx) {
    if (colIdx >= tbl.len) return "";
    const Column& col = tbl.cols[colIdx];

    // Stored-NULL visibility (see NullRowBinding above): when a scan
    // loop bound the current row, physically-NULL columns read as "".
    bool storedNullKnown = false;
    if (g_bufferedConditionSchema == &tbl && g_bufferedConditionNulls) {
        if (colIdx < g_bufferedConditionNulls->size()) {
            storedNullKnown = true;
            if ((*g_bufferedConditionNulls)[colIdx]) return "";
        }
    } else if (g_nullRowEngine && g_nullRowRid >= 0 && colIdx < g_nullRowNatts &&
        tbl.tablename == g_nullRowTable) {
        if (detail::storedRowColumnIsNull(*g_nullRowEngine, g_nullRowDb,
                tbl.tablename, tbl, g_nullRowRid, colIdx)) {
            return "";
        }
        storedNullKnown = usesHeapTupleHeader(tbl.formatVersion);
    } else if (g_condNullEngine && g_condNullRid >= 0 &&
               tbl.tablename == g_condNullTable) {
        if (detail::storedRowColumnIsNull(*g_condNullEngine,
                g_condNullDb, tbl.tablename, tbl, g_condNullRid, colIdx)) {
            return "";
        }
        storedNullKnown = usesHeapTupleHeader(tbl.formatVersion);
    }

    if (col.isVariableLength) {
        // Variable-length column: look up in var offset array
        size_t varIdx = tbl.getVarColIndex(colIdx);
        uint32_t resolvedOffset = 0;
        uint32_t resolvedLength = 0;
        if (resolvedToastEntry(rowBuffer, tbl, varIdx, &resolvedOffset,
                               &resolvedLength)) {
            return rowBuffer.substr(resolvedOffset, resolvedLength);
        }
        size_t fixedSize = tbl.fixedDataSize();
        size_t arrPos = fixedSize + varIdx * 4;
        if (arrPos + 4 > rowBuffer.size()) return "";
        uint16_t dataOffset = 0, dataLen = 0;
        std::memcpy(&dataOffset, rowBuffer.data() + arrPos, sizeof(uint16_t));
        std::memcpy(&dataLen, rowBuffer.data() + arrPos + 2, sizeof(uint16_t));
        if (dataOffset + dataLen > rowBuffer.size()) return "";
        return rowBuffer.substr(dataOffset, dataLen);
    }

    // Fixed-length column
    size_t offset = 0;
    for (size_t i = 0; i < colIdx; ++i) {
        if (!tbl.cols[i].isVariableLength) offset += tbl.cols[i].dsize;
    }
    if (offset + col.dsize > rowBuffer.size()) return "";
    if (col.dataType == "uuid") {
        if (col.dsize == UuidValue::Bytes{}.size()) {
            UuidValue::Bytes bytes{};
            std::memcpy(bytes.data(), rowBuffer.data() + offset,
                        bytes.size());
            return UuidValue(bytes).toString();
        }
        std::string legacy(col.dsize, '\0');
        std::memcpy(legacy.data(), rowBuffer.data() + offset, col.dsize);
        const size_t nul = legacy.find('\0');
        if (nul != std::string::npos) legacy.resize(nul);
        std::string canonical;
        return normalizeUuid(legacy, canonical) ? canonical : legacy;
    }
    if (col.dataType == "char" || col.dataType == "nchar" ||
        col.dataType == "binary") {
        std::string val(col.dsize, '\0');
        std::memcpy(val.data(), rowBuffer.data() + offset, col.dsize);
        auto nul = val.find('\0');
        if (nul != std::string::npos) val.resize(nul);
        return val;
    } else if (col.dataType == "date") {
        Date d;
        std::memcpy(&d, rowBuffer.data() + offset, DATE_SIZE);
        return (d.year == 0) ? "" : str(d);
    } else if (col.storageCodec == Column::StorageCodec::TemporalMicros) {
        int64_t value = 0;
        std::memcpy(&value, rowBuffer.data() + offset, sizeof(value));
        if (col.dataType == "time")
            return value == -1 ? "" : temporal_storage_detail::formatTimeMicros(value);
        return value == INF ? "" : temporal_storage_detail::formatTimestampMicros(
            value, col.dataType == "timestamptz");
    } else if (col.dataType == "timestamp" || col.dataType == "timestamptz" || col.dataType == "datetime") {
        int64_t val = 0;
        std::memcpy(&val, rowBuffer.data() + offset, TIMESTAMP_SIZE);
        if (val == INF) {
            // Releases before the dedicated timestamp sentinel encoded
            // -infinity as INF.  A v2 heap null bitmap can distinguish those
            // rows from SQL NULL, so keep existing databases readable.
            if (usesHeapTupleHeader(tbl.formatVersion)) {
                if (g_nullRowEngine && g_nullRowRid >= 0 &&
                    colIdx < g_nullRowNatts && tbl.tablename == g_nullRowTable) {
                    return "-infinity";  // a true NULL returned at function entry
                }
                if (g_condNullEngine && g_condNullRid >= 0 &&
                    tbl.tablename == g_condNullTable &&
                    !detail::storedRowColumnIsNull(*g_condNullEngine,
                        g_condNullDb, tbl.tablename, tbl, g_condNullRid, colIdx)) {
                    return "-infinity";
                }
            }
            return "";
        }
        return val == 0 ? "" : formatTimestampSeconds(val);
    } else if (col.dataType == "time") {
        int32_t val = 0;
        std::memcpy(&val, rowBuffer.data() + offset, sizeof(int32_t));
        return (val < 0) ? "" : formatTimeSeconds(val);
    } else if (col.dataType == "float") {
        float val = 0.0f;
        std::memcpy(&val, rowBuffer.data() + offset, sizeof(float));
        return formatFloatingValue(val);
    } else if (col.dataType == "money") {
        int64_t minorUnits = 0;
        std::memcpy(&minorUnits, rowBuffer.data() + offset,
                    sizeof(minorUnits));
        return Money(minorUnits).format(StorageEngine::getMoneyLocale());
    } else if (col.dataType == "double" || col.dataType == "decimal" || col.dataType == "numeric") {
        double val = 0.0;
        std::memcpy(&val, rowBuffer.data() + offset, sizeof(double));
        return col.dataType == "double" ? float8_output_detail::format(val)
                                        : formatFloatingValue(val);
    } else if (col.dataType == "point") {
        double x = 0.0, y = 0.0;
        std::memcpy(&x, rowBuffer.data() + offset, sizeof(double));
        std::memcpy(&y, rowBuffer.data() + offset + sizeof(double), sizeof(double));
        return formatPointCoordinate(x) + "," + formatPointCoordinate(y);
    } else if (col.dataType == "inet" || col.dataType == "cidr") {
        // Format: 1B family | 1B prefix_len | 1B is_cidr | 1B reserved | 16B addr
        dbms::NetworkAddressValue address;
        address.family = static_cast<uint8_t>(rowBuffer[offset]);
        address.bits = static_cast<uint8_t>(rowBuffer[offset + 1]);
        std::memcpy(address.address.data(), rowBuffer.data() + offset + 4,
                    address.address.size());
        return address.toString(col.dataType == "cidr");
    } else if (col.dataType == "macaddr" || col.dataType == "macaddr8") {
        int n = (col.dataType == "macaddr8") ? 8 : 6;
        uint8_t bytes[8] = {0};
        for (int i = 0; i < n; ++i)
            bytes[i] = static_cast<uint8_t>(rowBuffer[offset + i]);
        return formatMacAddr(bytes, n);
    } else if (!col.isArray && col.dataType == "regtype") {
        // REGTYPE is persisted as the complete unsigned OID datum.  This
        // identity does not depend on the legacy schema unsigned suffix.
        if (col.dsize != sizeof(uint32_t)) {
            throw DbError("XX001", "invalid persisted regtype object width");
        }
        uint32_t oid = 0;
        std::memcpy(&oid, rowBuffer.data() + offset, sizeof(oid));
        return std::to_string(oid);
    } else if (col.dataType == "boolean") {
        int8_t val = 0;
        std::memcpy(&val, rowBuffer.data() + offset, sizeof(int8_t));
        if (val == INT8_MIN) return "";
        return postgresBooleanOutput(val != 0);
    } else {
        int64_t val = 0;
        size_t n = std::min(col.dsize, sizeof(val));
        std::memcpy(&val, rowBuffer.data() + offset, n);
        if (col.isUnsigned) {
            return std::to_string(static_cast<uint64_t>(val));
        }
        // Sign-extend sub-8-byte integers: -7 stored in 4 bytes must
        // decode as -7, not 4294967289.
        if (n == 4 && (val & 0x80000000LL)) val |= 0xFFFFFFFF00000000LL;
        else if (n == 2 && (val & 0x8000LL)) val |= 0xFFFFFFFFFFFF0000LL;
        else if (n == 1 && (val & 0x80LL)) val |= 0xFFFFFFFFFFFFFF00LL;
        // The tuple bitmap, not the numeric payload, determines SQL NULL.
        // Keep sentinel fallback for legacy nullable buffers without a bitmap.
        return (val == INF && col.isNull && !storedNullKnown) ? "" : transstr(val);
    }
}


std::string StorageEngine::extractColumnValue(const std::string& rowBuffer,
                                               const TableSchema& tbl, size_t colIdx,
                                               const std::string& dbname,
                                               bool computeVirtual) {
    return extractColumnValue(
        rowBuffer, tbl, colIdx, dbname, computeVirtual, nullptr);
}

std::string StorageEngine::extractColumnValue(const std::string& rowBuffer,
                                               const TableSchema& tbl,
                                               size_t colIdx,
                                               const std::string& dbname,
                                               bool computeVirtual,
                                               bool* valueIsNull) {
    return extractColumnValue(rowBuffer,tbl,colIdx,dbname,computeVirtual,
                              valueIsNull,nullptr);
}

std::string StorageEngine::extractColumnValue(const std::string& rowBuffer,
                                               const TableSchema& tbl,
                                               size_t colIdx,
                                               const std::string& dbname,
                                               bool computeVirtual,
                                               bool* valueIsNull,
                                               std::optional<ExprValue>* owningValue) {
    if (owningValue) owningValue->reset();
    if (valueIsNull) *valueIsNull = false;
    if (colIdx >= tbl.len) return "";
    const Column& col = tbl.cols[colIdx];

    // Stored-NULL visibility: when a scan loop has bound the current
    // row's identity (rid + engine), consult the heap null bitmap so a
    // physically-NULL column reads as "" instead of its zero value.
    // Paths that don't bind a row (constant evaluation, index keys,
    // condition evaluation) keep the raw behavior.
    const bool bufferedNullKnown = g_bufferedConditionSchema == &tbl &&
        g_bufferedConditionNulls && colIdx < g_bufferedConditionNulls->size() &&
        (col.generatedKind != 'v' || !computeVirtual);
    if (bufferedNullKnown) {
        if ((*g_bufferedConditionNulls)[colIdx]) {
            if (valueIsNull) *valueIsNull = true;
            return "";
        }
    } else if (g_nullRowEngine && g_nullRowRid >= 0 && colIdx < g_nullRowNatts &&
        tbl.tablename == g_nullRowTable &&
        (col.generatedKind != 'v' || !computeVirtual)) {
        if (detail::storedRowColumnIsNull(*g_nullRowEngine, g_nullRowDb,
                tbl.tablename, tbl, g_nullRowRid, colIdx)) {
            if (valueIsNull) *valueIsNull = true;
            return "";
        }
    }
    if (!bufferedNullKnown && g_condNullEngine && g_condNullRid >= 0 &&
        tbl.tablename == g_condNullTable &&
        (col.generatedKind != 'v' || !computeVirtual) &&
        detail::storedRowColumnIsNull(*g_condNullEngine,
            g_condNullDb, tbl.tablename, tbl, g_condNullRid, colIdx)) {
        if (valueIsNull) *valueIsNull = true;
        return "";
    }

    StorageEngine* valueEngine = this;
    std::string valueDb = dbname;
    if (valueDb.empty() && g_condNullEngine && tbl.tablename == g_condNullTable) {
        valueEngine = const_cast<StorageEngine*>(g_condNullEngine);
        valueDb = g_condNullDb;
    } else if (valueDb.empty() && g_nullRowEngine &&
               tbl.tablename == g_nullRowTable) {
        valueEngine = const_cast<StorageEngine*>(g_nullRowEngine);
        valueDb = g_nullRowDb;
    }

    // Compute VIRTUAL generated columns on demand at query time.
    if (computeVirtual && !valueDb.empty() && col.generatedKind == 'v' && !col.generatedExpr.empty()) {
        std::map<std::string, std::string> rowValues;
        std::set<std::string> nullColumns;
        const bool hasBoundNullMetadata =
            (g_bufferedConditionSchema == &tbl && g_bufferedConditionNulls &&
             g_bufferedConditionNulls->size() == tbl.len) ||
            (g_nullRowEngine && g_nullRowRid >= 0 &&
             tbl.tablename == g_nullRowTable) ||
            (g_condNullEngine && g_condNullRid >= 0 &&
             tbl.tablename == g_condNullTable);
        for (size_t i = 0; i < tbl.len; ++i) {
            bool sourceIsNull = false;
            rowValues[tbl.cols[i].dataName] =
                valueEngine->extractColumnValue(
                    rowBuffer, tbl, i, valueDb, false, &sourceIsNull);
            if (tbl.cols[i].generatedKind != 'v' &&
                (sourceIsNull || (!hasBoundNullMetadata &&
                                  rowValues[tbl.cols[i].dataName].empty()))) {
                nullColumns.insert(tbl.cols[i].dataName);
            }
        }
        // Compute all VIRTUAL columns in column order so later columns can reference earlier ones.
        auto typeHints = buildTypeHints(tbl);
        // Metadata belongs to the same real relation; only actual captured
        // generated values enter the existing helper's owning datum slots.
        DatumMetadataContextPtr generatedMetadata;
        std::unique_ptr<OwningSqlRow> generatedValues;
        if (owningValue) {
            generatedMetadata=valueEngine->prepareDatumMetadataContext(valueDb,tbl.tablename);
            generatedValues=std::make_unique<OwningSqlRow>();
        }
        bool targetEvaluated = false;
        bool targetIsNull = false;
        for (size_t i = 0; i < tbl.len; ++i) {
            const Column& vc = tbl.cols[i];
            if (vc.generatedKind != 'v' || vc.generatedExpr.empty()) continue;
            std::string computed;
            bool computedIsNull = false;
            std::optional<ExprValue> computedValue;
            const bool ok = evalExpressionSqlValue(
                vc.generatedExpr, rowValues, typeHints, valueDb,
                computed, computedIsNull, &nullColumns, const_cast<StorageEngine*>(this),
                false,nullptr,owningValue?&computedValue:nullptr,
                generatedValues.get(),generatedMetadata.get());
            if (ok) {
                rowValues[vc.dataName] = computed;
                if (generatedValues && computedValue)
                    (*generatedValues)[vc.dataName]=*computedValue;
                if (computedIsNull) nullColumns.insert(vc.dataName);
                else nullColumns.erase(vc.dataName);
            }
            if (i == colIdx) {
                targetEvaluated = ok;
                targetIsNull = !ok || computedIsNull;
                if (owningValue && computedValue) *owningValue=std::move(computedValue);
            }
        }
        if (targetEvaluated) {
            if (valueIsNull) *valueIsNull = targetIsNull;
            return rowValues[col.dataName];
        }
        if (valueIsNull) *valueIsNull = true;
        return "";
    }

    std::string val = extractColumnValueStatic(rowBuffer, tbl, colIdx);
    uint32_t ignoredResolvedOffset = 0;
    uint32_t ignoredResolvedLength = 0;
    if (col.isVariableLength &&
        resolvedToastEntry(rowBuffer, tbl, 0, &ignoredResolvedOffset,
                           &ignoredResolvedLength)) {
        return val;
    }
    if (!valueDb.empty() && col.isVariableLength) {
        uint64_t toastId = 0;
        if (parseToastMarker(val, toastId)) {
            std::string resolved;
            if (!valueEngine->readToast(
                    valueDb, tbl.tablename, toastId,
                    characterColumnByteLimit(col), resolved))
                return "";
            return resolved;
        }
    }
    return val;
}

std::string StorageEngine::buildCompositeKey(const std::string& rowBuffer,
                                               const TableSchema& tbl,
                                               const std::vector<std::string>& colNames) {
    std::string key;
    for (const auto& cname : colNames) {
        size_t colIdx = tbl.len;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == cname) { colIdx = i; break; }
        }
        if (colIdx < tbl.len) {
            if (!key.empty()) key += '\x01';
            if (g_condNullEngine && tbl.tablename == g_condNullTable) {
                key += const_cast<StorageEngine*>(g_condNullEngine)->extractColumnValue(
                    rowBuffer, tbl, colIdx, g_condNullDb);
            } else {
                key += extractColumnValueStatic(rowBuffer, tbl, colIdx);
            }
        }
    }
    return key;
}

std::string StorageEngine::buildCompositeKey(
    const std::string& rowBuffer, const TableSchema& tbl,
    const std::vector<std::string>& colNames, const std::string& dbname) {
    std::map<std::string, std::string> values;
    for (size_t i = 0; i < tbl.len; ++i) {
        values[tbl.cols[i].dataName] =
            extractColumnValue(rowBuffer, tbl, i, dbname);
    }
    return buildCompositeKeyFromRowMap(values, tbl, colNames);
}

// ========================================================================
// Trigger support
// ========================================================================
namespace {

constexpr uint32_t TRIGGER_FILE_MAGIC = 0x32475254u;  // 'TRG2'
constexpr uint32_t TRIGGER_FILE_VERSION = 1;
constexpr size_t MAX_TRIGGER_COUNT = 10000;
constexpr size_t MAX_TRIGGER_STRING = 100000;
constexpr size_t MAX_TRIGGER_TRANSITIONS = 64;
constexpr size_t MAX_TRIGGER_TRANSITION_STRING = 256;
constexpr uintmax_t MAX_TRIGGER_FILE_SIZE = 64ULL * 1024 * 1024;

uint64_t triggerMetadataChecksum(const char* data, size_t size) {
    uint64_t hash = 1469598103934665603ULL;
    for (size_t i = 0; i < size; ++i) {
        hash ^= static_cast<unsigned char>(data[i]);
        hash *= 1099511628211ULL;
    }
    return hash;
}

template <typename T>
void appendTriggerPod(std::string& bytes, const T& value) {
    bytes.append(reinterpret_cast<const char*>(&value), sizeof(value));
}

class TriggerMetadataReader {
public:
    TriggerMetadataReader(const std::string& bytes, size_t limit)
        : bytes_(bytes), limit_(std::min(limit, bytes.size())) {}

    template <typename T>
    bool read(T& value) {
        if (position_ > limit_ || limit_ - position_ < sizeof(value)) return false;
        std::memcpy(&value, bytes_.data() + position_, sizeof(value));
        position_ += sizeof(value);
        return true;
    }

    bool readString(std::string& value, size_t length, size_t maximum) {
        if (length > maximum || length > remaining()) return false;
        value.assign(bytes_.data() + position_, length);
        position_ += length;
        return true;
    }

    size_t remaining() const {
        return position_ <= limit_ ? limit_ - position_ : 0;
    }

private:
    const std::string& bytes_;
    size_t limit_ = 0;
    size_t position_ = 0;
};

bool validTriggerRecord(const StorageEngine::Trigger& trigger) {
    if (trigger.name.empty() || trigger.tableName.empty() ||
        trigger.timing.empty() || trigger.event.empty() ||
        trigger.name.size() > MAX_TRIGGER_STRING ||
        trigger.timing.size() > MAX_TRIGGER_STRING ||
        trigger.event.size() > MAX_TRIGGER_STRING ||
        trigger.tableName.size() > MAX_TRIGGER_STRING ||
        trigger.action.size() > MAX_TRIGGER_STRING ||
        trigger.whenCondition.size() > MAX_TRIGGER_STRING ||
        trigger.transitions.size() > MAX_TRIGGER_TRANSITIONS) {
        return false;
    }
    return std::all_of(trigger.transitions.begin(), trigger.transitions.end(),
        [](const std::string& transition) {
            return transition.size() <= MAX_TRIGGER_TRANSITION_STRING;
        });
}

std::vector<StorageEngine::Trigger> filterTriggers(
        const std::vector<StorageEngine::Trigger>& all,
        const std::string& table, const std::string& timing,
        const std::string& event) {
    std::vector<StorageEngine::Trigger> result;
    for (const auto& trigger : all) {
        if (trigger.tableName == table && trigger.timing == timing &&
            trigger.event == event && trigger.enabled) {
            result.push_back(trigger);
        }
    }
    return result;
}

struct TriggerRowAssignment {
    std::string column;
    std::string expression;
};

// Evaluate the storage API's explicit row-assignment RHS as SQL over typed
// datums. Textual NEW/OLD replacement changes literals and prefix column names,
// loses SQL NULL, and reparses ordinary text as code. Bind each row image instead.
static bool evalTriggerRowAssignment(
        StorageEngine& engine, const std::string& database,
        const TableSchema& table, const std::string& expression,
        const std::map<std::string, std::string>& newValues,
        const std::set<std::string>& newNulls,
        const std::map<std::string, std::string>* oldValues,
        const std::set<std::string>* oldNulls,
        std::string& value, bool& isNull) {
    std::map<std::string, std::string> values, types, collations;
    std::set<std::string> nulls;
    for (size_t i = 0; i < table.len; ++i) {
        const auto& column = table.cols[i];
        const auto bind = [&](const std::string& prefix,
                              const std::map<std::string, std::string>* row,
                              const std::set<std::string>* rowNulls) {
            const auto key = prefix + column.dataName;
            const bool missing = !row || row->count(column.dataName) == 0;
            values[key] = missing ? std::string{} : row->at(column.dataName);
            types[key] = column.dataType + (column.isArray ? "[]" : "");
            collations[key] = column.resolvedCollation.empty()
                ? column.collation : column.resolvedCollation;
            if (missing || (rowNulls && rowNulls->count(column.dataName)))
                nulls.insert(key);
        };
        bind("", &newValues, &newNulls);
        bind("new.", &newValues, &newNulls);
        bind("old.", oldValues, oldNulls);
    }
    const auto result = ExprHelper::evalStringWithNulls(expression, values,
        nulls, types, database, "", &engine, collations);
    if (!result.ok) return false;
    value = result.value;
    isNull = result.isNull;
    return true;
}

bool triggerTokenEquals(std::string_view token, std::string_view expected) {
    if (token.size() != expected.size()) return false;
    for (size_t i = 0; i < token.size(); ++i) {
        if (std::tolower(static_cast<unsigned char>(token[i])) !=
            std::tolower(static_cast<unsigned char>(expected[i]))) {
            return false;
        }
    }
    return true;
}

// The storage layer supports a deliberately small row-rewrite form for
// BEFORE triggers: "SET col = expression" (and "NEW.col = expression").
// Trigger actions may otherwise be arbitrary SQL, so an equals sign inside an
// INSERT/UPDATE statement or a string literal must never be treated as a row
// assignment.
std::vector<TriggerRowAssignment> parseTriggerRowAssignments(
        const std::string& action) {
    std::vector<TriggerRowAssignment> assignments;
    size_t statementStart = 0;
    while (statementStart < action.size()) {
        size_t statementEnd = statementStart;
        char quote = '\0';
        for (; statementEnd < action.size(); ++statementEnd) {
            const char c = action[statementEnd];
            if (quote != '\0') {
                if (c == quote) {
                    if (statementEnd + 1 < action.size() &&
                        action[statementEnd + 1] == quote) {
                        ++statementEnd;
                    } else {
                        quote = '\0';
                    }
                }
                continue;
            }
            if (c == '\'' || c == '"') {
                quote = c;
            } else if (c == ';') {
                break;
            }
        }

        const std::string statement = trim(
            action.substr(statementStart, statementEnd - statementStart));
        statementStart = statementEnd < action.size()
            ? statementEnd + 1 : action.size();
        if (statement.empty()) continue;

        size_t lhsStart = 0;
        bool hasSetKeyword = false;
        if (statement.size() >= 3 &&
            triggerTokenEquals(std::string_view(statement).substr(0, 3),
                               "set") &&
            (statement.size() == 3 ||
             std::isspace(static_cast<unsigned char>(statement[3])))) {
            hasSetKeyword = true;
            lhsStart = 3;
            while (lhsStart < statement.size() &&
                   std::isspace(static_cast<unsigned char>(statement[lhsStart]))) {
                ++lhsStart;
            }
        }

        size_t equals = std::string::npos;
        quote = '\0';
        for (size_t i = lhsStart; i < statement.size(); ++i) {
            const char c = statement[i];
            if (quote != '\0') {
                if (c == quote) {
                    if (i + 1 < statement.size() && statement[i + 1] == quote) {
                        ++i;
                    } else {
                        quote = '\0';
                    }
                }
                continue;
            }
            if (c == '\'' || c == '"') {
                quote = c;
            } else if (c == '=') {
                equals = i;
                break;
            }
        }
        if (equals == std::string::npos) continue;

        std::string column = trim(
            statement.substr(lhsStart, equals - lhsStart));
        const bool hasNewQualifier =
            column.size() > 4 &&
            triggerTokenEquals(std::string_view(column).substr(0, 4), "new.");
        if (hasNewQualifier) column.erase(0, 4);
        if (!hasSetKeyword && !hasNewQualifier) continue;
        if (column.empty() ||
            !std::all_of(column.begin(), column.end(), [](unsigned char c) {
                return std::isalnum(c) || c == '_';
            })) {
            continue;
        }

        std::string expression = trim(statement.substr(equals + 1));
        if (!expression.empty()) {
            assignments.push_back({std::move(column), std::move(expression)});
        }
    }
    return assignments;
}

}  // namespace

std::filesystem::path StorageEngine::triggerPath(const std::string& dbname) const {
    return dbPath(dbname) / ".triggers";
}

bool StorageEngine::loadTriggers(
        const std::string& dbname, std::vector<Trigger>& triggers) const {
    triggers.clear();
    const auto path = triggerPath(dbname);
    std::error_code ec;
    if (!std::filesystem::exists(path, ec)) return !ec;
    const uintmax_t fileSize = std::filesystem::file_size(path, ec);
    if (ec || fileSize == 0 || fileSize > MAX_TRIGGER_FILE_SIZE) return false;

    std::ifstream in(path, std::ios::binary);
    if (!in) return false;
    try {
        std::string bytes(static_cast<size_t>(fileSize), '\0');
        if (!in.read(bytes.data(), static_cast<std::streamsize>(bytes.size())) ||
            in.peek() != std::char_traits<char>::eof()) {
            return false;
        }

        std::vector<Trigger> parsed;
        std::set<std::pair<std::string, std::string>> identities;
        uint32_t firstWord = 0;
        if (bytes.size() >= sizeof(firstWord))
            std::memcpy(&firstWord, bytes.data(), sizeof(firstWord));

        if (firstWord == TRIGGER_FILE_MAGIC) {
            if (bytes.size() < sizeof(uint32_t) * 3 + sizeof(uint64_t)) return false;
            const size_t payloadSize = bytes.size() - sizeof(uint64_t);
            uint64_t storedChecksum = 0;
            std::memcpy(&storedChecksum, bytes.data() + payloadSize,
                        sizeof(storedChecksum));
            if (storedChecksum != triggerMetadataChecksum(bytes.data(), payloadSize))
                return false;

            TriggerMetadataReader reader(bytes, payloadSize);
            uint32_t magic = 0;
            uint32_t version = 0;
            uint32_t count = 0;
            if (!reader.read(magic) || !reader.read(version) || !reader.read(count) ||
                magic != TRIGGER_FILE_MAGIC || version != TRIGGER_FILE_VERSION ||
                count > MAX_TRIGGER_COUNT) {
                return false;
            }
            parsed.reserve(count);
            for (uint32_t i = 0; i < count; ++i) {
                Trigger trigger;
                auto readString = [&](std::string& value, size_t maximum) {
                    uint32_t length = 0;
                    return reader.read(length) &&
                           reader.readString(value, length, maximum);
                };
                if (!readString(trigger.name, MAX_TRIGGER_STRING) ||
                    !readString(trigger.timing, MAX_TRIGGER_STRING) ||
                    !readString(trigger.event, MAX_TRIGGER_STRING) ||
                    !readString(trigger.tableName, MAX_TRIGGER_STRING) ||
                    !readString(trigger.action, MAX_TRIGGER_STRING) ||
                    !readString(trigger.whenCondition, MAX_TRIGGER_STRING)) {
                    return false;
                }
                uint8_t forEachRow = 0;
                uint8_t enabled = 0;
                uint32_t transitionCount = 0;
                if (!reader.read(forEachRow) || !reader.read(enabled) ||
                    forEachRow > 1 || enabled > 1 ||
                    !reader.read(transitionCount) ||
                    transitionCount > MAX_TRIGGER_TRANSITIONS) {
                    return false;
                }
                trigger.forEachRow = (forEachRow != 0);
                trigger.enabled = (enabled != 0);
                trigger.transitions.reserve(transitionCount);
                for (uint32_t j = 0; j < transitionCount; ++j) {
                    std::string transition;
                    if (!readString(transition, MAX_TRIGGER_TRANSITION_STRING)) return false;
                    trigger.transitions.push_back(std::move(transition));
                }
                if (!validTriggerRecord(trigger) ||
                    !identities.emplace(trigger.tableName, trigger.name).second)
                    return false;
                parsed.push_back(std::move(trigger));
            }
            if (reader.remaining() != 0) return false;
            triggers = std::move(parsed);
            return true;
        }

        // Legacy native-size_t layout.  It had no checksum, so require an
        // exact structural parse and reject any partial record or suffix.
        TriggerMetadataReader reader(bytes, bytes.size());
        size_t count = 0;
        if (!reader.read(count) || count > MAX_TRIGGER_COUNT) return false;
        parsed.reserve(count);
        for (size_t i = 0; i < count; ++i) {
            Trigger trigger;
            auto readString = [&](std::string& value, size_t maximum) {
                size_t length = 0;
                return reader.read(length) &&
                       reader.readString(value, length, maximum);
            };
            if (!readString(trigger.name, MAX_TRIGGER_STRING) ||
                !readString(trigger.timing, MAX_TRIGGER_STRING) ||
                !readString(trigger.event, MAX_TRIGGER_STRING) ||
                !readString(trigger.tableName, MAX_TRIGGER_STRING) ||
                !readString(trigger.action, MAX_TRIGGER_STRING) ||
                !readString(trigger.whenCondition, MAX_TRIGGER_STRING)) {
                return false;
            }
            uint8_t forEachRow = 0;
            uint8_t enabled = 0;
            if (!reader.read(forEachRow) || !reader.read(enabled) ||
                forEachRow > 1 || enabled > 1) {
                return false;
            }
            trigger.forEachRow = (forEachRow != 0);
            trigger.enabled = (enabled != 0);

            // Very old one-record sidecars ended after the flags.  This is
            // unambiguous only for the final record.
            if (!(i + 1 == count && reader.remaining() == 0)) {
                size_t transitionCount = 0;
                if (!reader.read(transitionCount) ||
                    transitionCount > MAX_TRIGGER_TRANSITIONS) {
                    return false;
                }
                trigger.transitions.reserve(transitionCount);
                for (size_t j = 0; j < transitionCount; ++j) {
                    std::string transition;
                    if (!readString(transition, MAX_TRIGGER_TRANSITION_STRING))
                        return false;
                    trigger.transitions.push_back(std::move(transition));
                }
            }
            if (!validTriggerRecord(trigger) ||
                !identities.emplace(trigger.tableName, trigger.name).second)
                return false;
            parsed.push_back(std::move(trigger));
        }
        if (reader.remaining() != 0) return false;
        triggers = std::move(parsed);
        return true;
    } catch (const std::bad_alloc&) {
        triggers.clear();
        return false;
    } catch (const std::length_error&) {
        triggers.clear();
        return false;
    }
}

DBStatus StorageEngine::persistTriggers(
        const std::string& dbname, const std::vector<Trigger>& triggers) const {
    if (triggers.size() > MAX_TRIGGER_COUNT) return DBStatus::INVALID_VALUE;
    try {
        std::set<std::pair<std::string, std::string>> identities;
        std::string bytes;
        const size_t payloadLimit =
            static_cast<size_t>(MAX_TRIGGER_FILE_SIZE) - sizeof(uint64_t);
        auto appendPod = [&](const auto& value) {
            if (bytes.size() > payloadLimit ||
                sizeof(value) > payloadLimit - bytes.size()) {
                return false;
            }
            appendTriggerPod(bytes, value);
            return true;
        };
        auto appendString = [&](const std::string& value) {
            const uint32_t length = static_cast<uint32_t>(value.size());
            if (!appendPod(length) || value.size() > payloadLimit - bytes.size())
                return false;
            bytes.append(value);
            return true;
        };

        const uint32_t count = static_cast<uint32_t>(triggers.size());
        if (!appendPod(TRIGGER_FILE_MAGIC) || !appendPod(TRIGGER_FILE_VERSION) ||
            !appendPod(count)) {
            return DBStatus::INVALID_VALUE;
        }
        for (const auto& trigger : triggers) {
            if (!validTriggerRecord(trigger) ||
                !identities.emplace(trigger.tableName, trigger.name).second)
                return DBStatus::INVALID_VALUE;
            if (!appendString(trigger.name) || !appendString(trigger.timing) ||
                !appendString(trigger.event) || !appendString(trigger.tableName) ||
                !appendString(trigger.action) ||
                !appendString(trigger.whenCondition)) {
                return DBStatus::INVALID_VALUE;
            }
            const uint8_t forEachRow = trigger.forEachRow ? 1 : 0;
            const uint8_t enabled = trigger.enabled ? 1 : 0;
            const uint32_t transitionCount =
                static_cast<uint32_t>(trigger.transitions.size());
            if (!appendPod(forEachRow) || !appendPod(enabled) ||
                !appendPod(transitionCount)) {
                return DBStatus::INVALID_VALUE;
            }
            for (const auto& transition : trigger.transitions) {
                if (!appendString(transition)) return DBStatus::INVALID_VALUE;
            }
        }
        const uint64_t checksum = triggerMetadataChecksum(bytes.data(), bytes.size());
        appendTriggerPod(bytes, checksum);
        return persistMetadata(triggerPath(dbname), bytes);
    } catch (const std::bad_alloc&) {
        return DBStatus::IO_ERROR;
    } catch (const std::length_error&) {
        return DBStatus::IO_ERROR;
    }
}

DBStatus StorageEngine::createTrigger(const std::string& dbname, const Trigger& trg) {
    std::lock_guard<std::recursive_mutex> triggerLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    std::vector<Trigger> existing;
    if (!loadTriggers(dbname, existing)) return DBStatus::CORRUPTED_DATA;
    for (const auto& t : existing) {
        if (t.name == trg.name && t.tableName == trg.tableName) {
            return DBStatus::TABLE_ALREADY_EXISTS;
        }
    }
    existing.push_back(trg);
    return persistTriggers(dbname, existing);
}

DBStatus StorageEngine::dropTrigger(const std::string& dbname,
                                    const std::string& trgName,
                                    const std::string& tableName) {
    std::lock_guard<std::recursive_mutex> triggerLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    std::vector<Trigger> existing;
    if (!loadTriggers(dbname, existing)) return DBStatus::CORRUPTED_DATA;
    const auto newEnd = std::remove_if(existing.begin(), existing.end(),
        [&](const Trigger& trigger) {
            return trigger.name == trgName &&
                   (tableName.empty() || trigger.tableName == tableName);
        });
    if (newEnd == existing.end()) return DBStatus::TABLE_NOT_FOUND;
    existing.erase(newEnd, existing.end());
    return persistTriggers(dbname, existing);
}

std::vector<StorageEngine::Trigger> StorageEngine::getTriggers(
    const std::string& dbname, const std::string& tablename,
    const std::string& timing, const std::string& event) const {
    std::vector<Trigger> result;
    if (!tryGetTriggers(dbname, tablename, timing, event, result)) return {};
    return result;
}

bool StorageEngine::tryGetTriggers(
        const std::string& dbname, const std::string& tablename,
        const std::string& timing, const std::string& event,
        std::vector<Trigger>& result) const {
    std::lock_guard<std::recursive_mutex> triggerLock(cacheMutex_);
    std::vector<Trigger> all;
    if (!loadTriggers(dbname, all)) {
        result.clear();
        return false;
    }
    result = filterTriggers(all, tablename, timing, event);
    return true;
}

std::vector<StorageEngine::Trigger> StorageEngine::getAllTriggers(
        const std::string& dbname) const {
    std::vector<Trigger> result;
    if (!tryGetAllTriggers(dbname, result)) return {};
    return result;
}

bool StorageEngine::tryGetAllTriggers(
        const std::string& dbname, std::vector<Trigger>& result) const {
    std::lock_guard<std::recursive_mutex> triggerLock(cacheMutex_);
    return loadTriggers(dbname, result);
}

DBStatus StorageEngine::enableTrigger(const std::string& dbname,
                                      const std::string& trgName,
                                      const std::string& tableName) {
    std::lock_guard<std::recursive_mutex> triggerLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    std::vector<Trigger> existing;
    if (!loadTriggers(dbname, existing)) return DBStatus::CORRUPTED_DATA;
    bool found = false;
    for (auto& trigger : existing) {
        if (trigger.name == trgName &&
            (tableName.empty() || trigger.tableName == tableName)) {
            trigger.enabled = true;
            found = true;
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return persistTriggers(dbname, existing);
}

DBStatus StorageEngine::disableTrigger(const std::string& dbname,
                                       const std::string& trgName,
                                       const std::string& tableName) {
    std::lock_guard<std::recursive_mutex> triggerLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    std::vector<Trigger> existing;
    if (!loadTriggers(dbname, existing)) return DBStatus::CORRUPTED_DATA;
    bool found = false;
    for (auto& trigger : existing) {
        if (trigger.name == trgName &&
            (tableName.empty() || trigger.tableName == tableName)) {
            trigger.enabled = false;
            found = true;
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return persistTriggers(dbname, existing);
}

// ========================================================================
// Exclusion constraint support
// ========================================================================
std::filesystem::path StorageEngine::exclusionPath(const std::string& dbname) const {
    return dbPath(dbname) / ".exclusions";
}

void StorageEngine::writeExclusion(std::ostream& out, const ExclusionConstraint& ec) const {
    auto writeStr = [&](const std::string& s) {
        size_t n = s.size();
        out.write(reinterpret_cast<const char*>(&n), sizeof(size_t));
        out.write(s.data(), static_cast<std::streamsize>(n));
    };
    writeStr(ec.name);
    writeStr(ec.tableName);
    writeStr(ec.accessMethod);
    writeStr(ec.wherePredicate);
    size_t count = ec.elements.size();
    out.write(reinterpret_cast<const char*>(&count), sizeof(size_t));
    for (const auto& e : ec.elements) {
        writeStr(e.first);
        writeStr(e.second);
    }
}

StorageEngine::ExclusionConstraint StorageEngine::readExclusion(std::istream& in) const {
    ExclusionConstraint ec;
    auto readStr = [&](std::string& s) {
        size_t n = 0;
        in.read(reinterpret_cast<char*>(&n), sizeof(size_t));
        if (!in || n > 100000) return;
        s.resize(n);
        in.read(s.data(), static_cast<std::streamsize>(n));
    };
    readStr(ec.name);
    readStr(ec.tableName);
    readStr(ec.accessMethod);
    readStr(ec.wherePredicate);
    size_t count = 0;
    in.read(reinterpret_cast<char*>(&count), sizeof(size_t));
    if (!in || count > 1000) return ec;
    for (size_t i = 0; i < count && in; ++i) {
        std::string col, op;
        readStr(col);
        readStr(op);
        if (!col.empty()) ec.elements.push_back({col, op});
    }
    return ec;
}

DBStatus StorageEngine::createExclusionConstraint(const std::string& dbname, const ExclusionConstraint& ec) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto existing = getExclusionConstraints(dbname, "");
    for (const auto& e : existing) {
        if (e.name == ec.name) return DBStatus::OK; // already exists
    }
    existing.push_back(ec);
    std::ofstream out(exclusionPath(dbname), std::ios::binary | std::ios::trunc);
    if (!out) return DBStatus::INVALID_VALUE;
    size_t count = existing.size();
    out.write(reinterpret_cast<const char*>(&count), sizeof(size_t));
    for (const auto& e : existing) writeExclusion(out, e);
    if (!out) return DBStatus::INVALID_VALUE;
    invalidateExclusionCache(dbname);
    return DBStatus::OK;
}

DBStatus StorageEngine::dropExclusionConstraint(const std::string& dbname, const std::string& name) {
    auto existing = getExclusionConstraints(dbname, "");
    bool found = false;
    {
        std::ofstream out(exclusionPath(dbname), std::ios::binary | std::ios::trunc);
        size_t count = 0;
        for (const auto& e : existing) {
            if (e.name != name) ++count;
        }
        out.write(reinterpret_cast<const char*>(&count), sizeof(size_t));
        for (const auto& e : existing) {
            if (e.name != name) writeExclusion(out, e);
            else found = true;
        }
    }
    invalidateExclusionCache(dbname);
    return found ? DBStatus::OK : DBStatus::TABLE_NOT_FOUND;
}

std::vector<StorageEngine::ExclusionConstraint> StorageEngine::getExclusionConstraints(
    const std::string& dbname, const std::string& tablename) const {
    bool haveCached = false;
    {
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        auto it = exclusionCache_.find(dbname);
        if (it != exclusionCache_.end()) {
            if (tablename.empty()) return it->second;
            std::vector<ExclusionConstraint> result;
            for (const auto& ec : it->second) {
                if (ec.tableName == tablename) result.push_back(ec);
            }
            return result;
        }
        haveCached = true;
    }
    (void)haveCached;
    std::vector<ExclusionConstraint> all;
    {
        std::ifstream in(exclusionPath(dbname), std::ios::binary);
        if (in) {
            size_t count = 0;
            in.read(reinterpret_cast<char*>(&count), sizeof(size_t));
            if (in && count <= 10000) {
                for (size_t i = 0; i < count && in; ++i) {
                    ExclusionConstraint ec = readExclusion(in);
                    if (!ec.name.empty()) all.push_back(std::move(ec));
                }
            }
        }
    }
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    exclusionCache_.emplace(dbname, all);
    if (tablename.empty()) return all;
    std::vector<ExclusionConstraint> result;
    for (const auto& ec : all) {
        if (ec.tableName == tablename) result.push_back(ec);
    }
    return result;
}

void StorageEngine::invalidateExclusionCache(const std::string& dbname) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    exclusionCache_.erase(dbname);
}

// Parse canonicalized int4range bounds (e.g. [1,5) or empty).
static bool parseInt4RangeBounds(const std::string& s, int64_t& lo, int64_t& hi,
                                  bool& loInc, bool& hiInc, bool& empty) {
    empty = false;
    std::string t = trim(s);
    if (t.size() == 5) {
        std::string lc;
        for (char c : t) lc += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        if (lc == "empty") { empty = true; return true; }
    }
    if (t.size() < 3) return false;
    char lb = t.front(), ub = t.back();
    if ((lb != '[' && lb != '(') || (ub != ']' && ub != ')')) return false;
    std::string body = t.substr(1, t.size() - 2);
    size_t comma = body.find(',');
    if (comma == std::string::npos) return false;
    std::string loStr = trim(body.substr(0, comma));
    std::string hiStr = trim(body.substr(comma + 1));
    loInc = (lb == '[');
    hiInc = (ub == ']');
    if (loStr.empty()) lo = INT64_MIN; else {
        try { lo = std::stoll(loStr); } catch (...) { return false; }
    }
    if (hiStr.empty()) hi = INT64_MAX; else {
        try { hi = std::stoll(hiStr); } catch (...) { return false; }
    }
    return true;
}

static bool rangesOverlap(const std::string& a, const std::string& b) {
    int64_t loA, hiA, loB, hiB;
    bool loIncA, hiIncA, loIncB, hiIncB, emptyA, emptyB;
    if (!parseInt4RangeBounds(a, loA, hiA, loIncA, hiIncA, emptyA)) return false;
    if (!parseInt4RangeBounds(b, loB, hiB, loIncB, hiIncB, emptyB)) return false;
    if (emptyA || emptyB) return false;
    if (hiA < loB) return false;
    if (hiA == loB && !(hiIncA && loIncB)) return false;
    if (hiB < loA) return false;
    if (hiB == loA && !(hiIncB && loIncA)) return false;
    return true;
}

bool StorageEngine::checkExclusionConflict(const std::string& dbname, const std::string& tablename,
                                            const ExclusionConstraint& ec, const std::string& newRowBuffer,
                                            int64_t excludeRid, bool* scanFailed) const {
    if (scanFailed) *scanFailed = false;
    if (ec.elements.empty()) return false;
    TableSchema tbl = getTableSchema(dbname, tablename);
    std::map<std::string, std::string> newValues;
    for (size_t i = 0; i < tbl.len; ++i) {
        newValues[tbl.cols[i].dataName] =
            const_cast<StorageEngine*>(this)->extractColumnValue(
                newRowBuffer, tbl, i, dbname);
    }
    // If the new row doesn't satisfy the partial predicate, no conflict.
    if (!ec.wherePredicate.empty()) {
        std::string err;
        if (!dbms::ExprHelper::evalBool(ec.wherePredicate, newValues, buildTypeHints(tbl), &err, dbname, "", const_cast<StorageEngine*>(this))) {
            return false;
        }
    }
    std::vector<size_t> colIdxs;
    for (const auto& elem : ec.elements) {
        size_t idx = tbl.len;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == elem.first) { idx = i; break; }
        }
        if (idx >= tbl.len) return false;
        colIdxs.push_back(idx);
    }

    bool conflict = false;
    // Constraints must include this transaction's earlier writes from the
    // current command. Keep the statement snapshot unchanged for ordinary
    // SELECT/source scans, and retain its other MVCC/isolation fields.
    ReadView constraintView;
    const ReadView* constraintReadView = nullptr;
    const auto& context = transactionContext();
    if (context.inTransaction && context.txnDB == dbname &&
        context.readView.commandIdVisibility) {
        constraintView = context.readView;
        constraintView.commandIdVisibility = false;
        constraintReadView = &constraintView;
    }
    const bool scanOk = const_cast<StorageEngine*>(this)->forEachRow(dbname, tablename, [&](uint32_t pid, uint16_t sid, const char* data, size_t len) {
        if (conflict) return;
        int64_t rid = static_cast<int64_t>(encodeRid(pid, sid));
        if (rid == excludeRid) return;
        std::string row(data, len);
        std::map<std::string, std::string> oldValues;
        for (size_t i = 0; i < tbl.len; ++i) {
            oldValues[tbl.cols[i].dataName] =
                const_cast<StorageEngine*>(this)->extractColumnValue(
                    row, tbl, i, dbname);
        }
        if (!ec.wherePredicate.empty()) {
            std::string err;
            if (!dbms::ExprHelper::evalBool(ec.wherePredicate, oldValues, buildTypeHints(tbl), &err, dbname, "", const_cast<StorageEngine*>(this))) {
                return;
            }
        }
        bool allMatch = true;
        for (size_t ei = 0; ei < ec.elements.size(); ++ei) {
            const auto& elem = ec.elements[ei];
            size_t ci = colIdxs[ei];
            std::string newVal = newValues[tbl.cols[ci].dataName];
            std::string oldVal = oldValues[tbl.cols[ci].dataName];
            if (newVal.empty() || oldVal.empty()) { allMatch = false; break; }
            const std::string& op = elem.second;
            if (op == "=" || op == "==") {
                if (newVal != oldVal) { allMatch = false; break; }
            } else if (op == "<>" || op == "!=") {
                if (newVal == oldVal) { allMatch = false; break; }
            } else if (op == "<") {
                try { if (!(std::stoll(newVal) < std::stoll(oldVal))) { allMatch = false; break; } }
                catch (...) { allMatch = false; break; }
            } else if (op == ">") {
                try { if (!(std::stoll(newVal) > std::stoll(oldVal))) { allMatch = false; break; } }
                catch (...) { allMatch = false; break; }
            } else if (op == "<=") {
                try { if (!(std::stoll(newVal) <= std::stoll(oldVal))) { allMatch = false; break; } }
                catch (...) { allMatch = false; break; }
            } else if (op == ">=") {
                try { if (!(std::stoll(newVal) >= std::stoll(oldVal))) { allMatch = false; break; } }
                catch (...) { allMatch = false; break; }
            } else if (op == "&&") {
                if (!rangesOverlap(newVal, oldVal)) { allMatch = false; break; }
            } else {
                allMatch = false; break;
            }
        }
        if (allMatch) conflict = true;
    }, constraintReadView);
    if (!scanOk) {
        if (scanFailed) *scanFailed = true;
        return false;
    }
    return conflict;
}

// ========================================================================
// Deferred constraint support (SET CONSTRAINTS / DEFERRABLE)
// ========================================================================
DBStatus StorageEngine::setConstraintMode(
    const std::vector<std::string>& names, bool deferred) {
    auto& context = transactionContext();

    // PostgreSQL emits a warning and otherwise has no effect outside an
    // explicit transaction. Most importantly, such a command must not leak
    // its mode into the next transaction on this backend.
    if (!context.inTransaction) return DBStatus::OK;

    const bool all = std::find(names.begin(), names.end(), "all") != names.end();
    const auto matches = [&](const DeferredCheck& check) {
        return all || std::find(names.begin(), names.end(),
                                check.constraintName) != names.end();
    };

    auto queued = context.deferredChecks.find(context.currentTxnId);
    if (!deferred && queued != context.deferredChecks.end()) {
        // DEFERRED -> IMMEDIATE is retroactive. Validate first without
        // mutating any state: if one event fails, SET CONSTRAINTS itself
        // fails and every selected constraint remains in its previous mode.
        for (const auto& check : queued->second) {
            if (!matches(check) || runDeferredCheck(check)) continue;
            if (check.kind == DeferredCheck::Kind::Unique)
                return DBStatus::UNIQUE_VIOLATION;
            if (check.kind == DeferredCheck::Kind::ForeignKey)
                return DBStatus::FOREIGN_KEY_VIOLATION;
            if (check.kind == DeferredCheck::Kind::Exclude)
                return DBStatus::EXCLUSION_VIOLATION;
            return DBStatus::CHECK_VIOLATION;
        }

        auto& events = queued->second;
        if (std::any_of(events.begin(), events.end(), matches)) {
            // Savepoints normally keep only an O(1) queue watermark. A drain
            // is the exceptional operation that can delete an older prefix,
            // so materialize that prefix lazily before changing the queue.
            for (const auto& savepoint : context.savepoints) {
                if (!savepoint.deferredCheckSnapshot.has_value() &&
                    savepoint.deferredCheckSize > events.size()) {
                    return DBStatus::CORRUPTED_DATA;
                }
            }
            for (auto& savepoint : context.savepoints) {
                if (savepoint.deferredCheckSnapshot.has_value() ||
                    savepoint.deferredCheckSize == 0) {
                    continue;
                }
                savepoint.deferredCheckSnapshot.emplace(
                    events.begin(),
                    events.begin() + static_cast<std::ptrdiff_t>(
                        savepoint.deferredCheckSize));
            }
        }
        events.erase(
            std::remove_if(events.begin(), events.end(), matches),
            events.end());
        if (events.empty()) context.deferredChecks.erase(queued);
    }

    if (all) {
        // A later ALL command supersedes earlier per-constraint overrides.
        context.constraintMode.clear();
        context.constraintMode["all"] = deferred;
    } else {
        for (const auto& name : names) context.constraintMode[name] = deferred;
    }
    return DBStatus::OK;
}

bool StorageEngine::isConstraintDeferred(const std::string& name, bool defaultDeferred) const {
    auto it = transactionContext().constraintMode.find(name);
    if (it != transactionContext().constraintMode.end()) return it->second;
    auto allIt = transactionContext().constraintMode.find("all");
    if (allIt != transactionContext().constraintMode.end()) return allIt->second;
    return defaultDeferred;
}

bool StorageEngine::isConstraintCurrentlyDeferred(const std::string& dbname,
                                                 const std::string& tablename,
                                                 const std::string& constraintName) const {
    if (constraintName.empty()) return false;
    TableSchema tbl = getTableSchema(dbname, tablename);
    std::string dkey = "constraint." + constraintName + ".deferrable";
    std::string ikey = "constraint." + constraintName + ".initially_deferred";
    auto it = tbl.storageParams.find(dkey);
    bool deferrable = (it != tbl.storageParams.end() && it->second == "1");
    if (!deferrable) return false;
    auto it2 = tbl.storageParams.find(ikey);
    bool initiallyDeferred = (it2 != tbl.storageParams.end() && it2->second == "1");
    return isConstraintDeferred(constraintName, initiallyDeferred);
}

bool StorageEngine::runDeferredCheck(const DeferredCheck& dc) const {
    if (dc.kind == DeferredCheck::Kind::Unique) {
        // Re-read the row at commit time. It may have been updated again or
        // deleted since this check was queued, so the captured payload/RID is
        // not authoritative for the transaction's final state.
        if (!tableExists(dc.dbname, dc.tablename)) return true;
        const TableSchema tbl = getTableSchema(dc.dbname, dc.tablename);
        int colIdx = -1;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == dc.uniqueCol) { colIdx = static_cast<int>(i); break; }
        }
        if (colIdx < 0) return false;

        int64_t currentRid = dc.rid;
        std::string currentRow;
        bool readFailed = false;
        if (!readCurrentRowByRid(
                dc.dbname, dc.tablename, dc.rid, tbl, currentRid,
                currentRow, readFailed)) {
            // A deleted row no longer participates in the constraint. I/O or
            // corrupt-page failures must not be mistaken for an empty table.
            return !readFailed;
        }
        if (tbl.cols[static_cast<size_t>(colIdx)].isNull &&
            dbms::detail::storedRowColumnIsNull(*this, dc.dbname, dc.tablename, tbl, currentRid,
                              static_cast<size_t>(colIdx))) {
            return true;
        }
        const Column& uniqueColumn =
            tbl.cols[static_cast<size_t>(colIdx)];
        const std::string payloadValue =
            const_cast<StorageEngine*>(this)->extractColumnValue(
                currentRow, tbl, static_cast<size_t>(colIdx), dc.dbname);
        int matches = 0;
        const bool scanOk = forEachRow(
            dc.dbname, dc.tablename,
            [&](uint32_t pageId, uint16_t slot, const char* data, size_t len) {
            if (matches > 0) return;
            const int64_t rid = encodeRid(pageId, slot);
            if (rid == currentRid) return;
            if (uniqueColumn.isNull &&
                dbms::detail::storedRowColumnIsNull(
                    *this, dc.dbname, dc.tablename, tbl, rid,
                    static_cast<size_t>(colIdx))) {
                return;
            }
            std::string row(data, len);
            if (constraintColumnValuesEqual(
                    uniqueColumn,
                    const_cast<StorageEngine*>(this)->extractColumnValue(
                        row, tbl, static_cast<size_t>(colIdx), dc.dbname),
                    payloadValue)) {
                ++matches;
            }
        });
        return scanOk && matches == 0;
    }
    if (dc.kind == DeferredCheck::Kind::Exclude) {
        // Re-run the exclusion conflict scan at commit time against the
        // row's CURRENT version.  The row may have been updated after the
        // check was queued (possibly moved to a new slot by a HOT update,
        // with the old line pointer redirected), so resolve the redirect
        // chain and read the live row; its current slot is excluded from
        // the scan.  This matches PostgreSQL: the constraint must hold for
        // the final table state at commit.
        TableSchema tbl = getTableSchema(dc.dbname, dc.tablename);
        PageAllocator* pa = getPageAllocator(dc.dbname, dc.tablename);
        if (!pa) return false;
        int64_t curRid = dc.rid;
        std::string row;
        {
            uint32_t rpage = 0; uint16_t rslot = 0;
            decodeRid(dc.rid, rpage, rslot);
            char* buf = pa->fetchPage(rpage);
            if (!buf) return true;  // page gone: row vanished, check passes
            {
                PgPage page(buf);
                // internal line pointers are 1-based
                for (int hops = 0; hops < 64; ++hops) {
                    const PgPage::ItemIdData* id = page.itemId(rslot + 1);
                    if (!id) break;
                    uint16_t flags = id->lp_len >> PgPage::LP_FLAG_SHIFT;
                    if (flags != PgPage::LP_REDIRECT) break;
                    uint16_t target = id->lp_off & PgPage::LP_OFF_MASK;
                    if (target == 0 || target == rslot + 1) break;
                    rslot = target - 1;
                }
            }
            pa->unpinPage(rpage);
            curRid = encodeRid(rpage, rslot);
        }
        bool readFailed = false;
        if (!readVisibleRowByRid(dc.dbname, pa, curRid, row, tbl,
                                 nullptr, &readFailed)) {
            // Row deleted or no longer visible: nothing to check.
            return !readFailed;
        }
        if (row.empty()) return true;
        ExclusionConstraint ec;
        ec.name = dc.constraintName;
        ec.tableName = dc.tablename;
        ec.elements = dc.excludeElements;
        ec.wherePredicate = dc.excludeWhere;
        bool scanFailed = false;
        bool conflict = checkExclusionConflict(dc.dbname, dc.tablename, ec,
                                               row, curRid, &scanFailed);
        if (scanFailed) return false;
        return !conflict;
    }
    if (dc.kind == DeferredCheck::Kind::ForeignKey) {
        // Validate the local row's final version. A stale queued payload can
        // otherwise reject a value fixed later in the same transaction, and
        // an inserted-then-deleted child would still require a parent.
        if (!tableExists(dc.dbname, dc.tablename)) return true;
        const TableSchema localTbl =
            getTableSchema(dc.dbname, dc.tablename);
        int64_t currentRid = dc.rid;
        std::string currentRow;
        bool readFailed = false;
        if (!readCurrentRowByRid(
                dc.dbname, dc.tablename, dc.rid, localTbl, currentRid,
                currentRow, readFailed)) {
            return !readFailed;
        }

        const std::vector<std::string> localNames =
            dc.fkLocalCols.empty()
                ? std::vector<std::string>{dc.uniqueCol}
                : dc.fkLocalCols;
        const std::vector<std::string> referencedNames =
            dc.fkRefCols.empty()
                ? std::vector<std::string>{dc.refCol}
                : dc.fkRefCols;
        if (localNames.empty() ||
            localNames.size() != referencedNames.size()) {
            return false;
        }

        std::vector<std::string> payloadValues;
        payloadValues.reserve(localNames.size());
        for (const auto& name : localNames) {
            size_t columnIndex = localTbl.len;
            for (size_t candidate = 0; candidate < localTbl.len; ++candidate) {
                if (localTbl.cols[candidate].dataName == name) {
                    columnIndex = candidate;
                    break;
                }
            }
            if (columnIndex >= localTbl.len) return false;
            if (dbms::detail::storedRowColumnIsNull(*this, dc.dbname, dc.tablename, localTbl, currentRid, columnIndex)) {
                return true; // MATCH SIMPLE ignores real SQL NULL, not empty text.
            }
            payloadValues.push_back(
                const_cast<StorageEngine*>(this)->extractColumnValue(
                    currentRow, localTbl, columnIndex, dc.dbname));
        }
        // The referenced key must exist by commit time.
        if (!tableExists(dc.dbname, dc.refTable)) return false;
        const TableSchema refTbl = getTableSchema(dc.dbname, dc.refTable);
        std::vector<size_t> referencedColumns;
        referencedColumns.reserve(referencedNames.size());
        for (const auto& name : referencedNames) {
            size_t columnIndex = refTbl.len;
            for (size_t candidate = 0; candidate < refTbl.len; ++candidate) {
                if (refTbl.cols[candidate].dataName == name) {
                    columnIndex = candidate;
                    break;
                }
            }
            if (columnIndex >= refTbl.len) return false;
            referencedColumns.push_back(columnIndex);
        }

        bool found = false;
        const bool scanOk = forEachRow(
            dc.dbname, dc.refTable,
            [&](uint32_t pageId, uint16_t slotId, const char* data, size_t len) {
                if (found) return;
                const std::string row(data, len);
                for (size_t valueIndex = 0;
                     valueIndex < referencedColumns.size(); ++valueIndex) {
                    if (dbms::detail::storedRowColumnIsNull(*this, dc.dbname, dc.refTable, refTbl,
                            encodeRid(pageId, slotId), referencedColumns[valueIndex])) {
                        return;
                    }
                    const Column& referencedColumn =
                        refTbl.cols[referencedColumns[valueIndex]];
                    if (canonicalColumnKeyValue(referencedColumn,
                            const_cast<StorageEngine*>(this)->extractColumnValue(
                                row, refTbl, referencedColumns[valueIndex], dc.dbname)) !=
                        canonicalColumnKeyValue(referencedColumn, payloadValues[valueIndex])) {
                        return;
                    }
                }
                found = true;
            });
        return scanOk && found;
    }
    // CHECK constraint evaluation
    if (!tableExists(dc.dbname, dc.tablename)) return true;
    const TableSchema tbl = getTableSchema(dc.dbname, dc.tablename);
    std::string expression = dc.checkExpr;
    if (!expression.empty()) {
        const auto current = std::find_if(
            tbl.additionalCheckConstraints.begin(),
            tbl.additionalCheckConstraints.end(),
            [&](const CheckConstraint& check) {
                return (!dc.constraintName.empty() &&
                        check.name == dc.constraintName) ||
                       check.expression == dc.checkExpr;
            });
        if (current == tbl.additionalCheckConstraints.end()) {
            // The constraint was dropped after this row queued its check.
            return true;
        }
        expression = current->expression;
    } else {
        if (dc.colIdx >= tbl.len) return true;
        expression = tbl.cols[dc.colIdx].checkExpr;
    }
    if (expression.empty()) return true;

    int64_t currentRid = dc.rid;
    std::string row;
    bool readFailed = false;
    if (!readCurrentRowByRid(
            dc.dbname, dc.tablename, dc.rid, tbl, currentRid, row,
            readFailed)) {
        // Deleted rows no longer need validation, while storage failures
        // must fail closed instead of silently bypassing the constraint.
        return !readFailed;
    }
    std::map<std::string, std::string> rowValues;
    for (size_t i = 0; i < tbl.len; ++i) {
        rowValues[tbl.cols[i].dataName] =
            const_cast<StorageEngine*>(this)->extractColumnValue(
                row, tbl, i, dc.dbname);
    }
    std::string err;
    return dbms::ExprHelper::evalCheck(
        expression, rowValues, buildTypeHints(tbl), &err, dc.dbname, "",
        const_cast<StorageEngine*>(this));
}

// TableSchema PK helpers (defined here because they use StorageEngine::extractColumnValue)
std::string TableSchema::columnIndexKey(const std::string& column,
                                        const std::string& value) const {
    for (size_t i = 0; i < len; ++i) {
        if (cols[i].dataName == column) {
            return canonicalColumnKeyValue(cols[i], value);
        }
    }
    return value;
}

bool TableSchema::hasPrimaryKey() const {
    if (!pkColIndices.empty()) return true;
    for (size_t i = 0; i < len; ++i) if (cols[i].isPrimaryKey) return true;
    return false;
}

std::string TableSchema::buildPKValue(const std::string& rowBuffer) const {
    std::string key;
    if (!pkColIndices.empty()) {
        for (size_t idx : pkColIndices) {
            if (idx < len) {
                key += canonicalColumnKeyValue(
                    cols[idx], StorageEngine::extractColumnValueStatic(
                                   rowBuffer, *this, idx)) + "\x01";
            }
        }
    } else {
        // Collect all columns marked as primary key (composite PK support)
        bool first = true;
        size_t primaryColumnCount = 0;
        for (size_t i = 0; i < len; ++i) {
            if (cols[i].isPrimaryKey) {
                ++primaryColumnCount;
                if (!first) key += "\x01";
                key += canonicalColumnKeyValue(
                    cols[i], StorageEngine::extractColumnValueStatic(
                                 rowBuffer, *this, i));
                first = false;
            }
        }
        // Legacy inline single-column keys do not carry a separator.  Keep
        // their established non-empty encoding unchanged, but give a real
        // empty string a non-empty internal key so index maintenance does not
        // mistake it for an absent/NULL primary key.
        if (primaryColumnCount == 1 && key.empty()) {
            key.assign(1, '\0');
        }
    }
    return key;
}

std::string TableSchema::buildPKValue(const std::map<std::string, std::string>& values) const {
    std::string key;
    if (!pkColIndices.empty()) {
        for (size_t idx : pkColIndices) {
            if (idx < len) {
                auto it = values.find(cols[idx].dataName);
                key += canonicalColumnKeyValue(
                    cols[idx], it != values.end() ? it->second : "") +
                    "\x01";
            }
        }
    } else {
        bool first = true;
        size_t primaryColumnCount = 0;
        for (size_t i = 0; i < len; ++i) {
            if (cols[i].isPrimaryKey) {
                ++primaryColumnCount;
                if (!first) key += "\x01";
                auto it = values.find(cols[i].dataName);
                key += canonicalColumnKeyValue(
                    cols[i], it != values.end() ? it->second : "");
                first = false;
            }
        }
        if (primaryColumnCount == 1 && key.empty()) {
            key.assign(1, '\0');
        }
    }
    return key;
}

// Helper: evaluate simple expression (UPPER/LOWER) on a column value
static std::string evalExpr(const std::string& val, const std::string& exprFunc) {
    std::string normalizedFunc = exprFunc;
    for (char& ch : normalizedFunc) {
        ch = static_cast<char>(
            std::toupper(static_cast<unsigned char>(ch)));
    }
    if (normalizedFunc == "UPPER") {
        std::string result = val;
        for (char& c : result) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
        return result;
    }
    if (normalizedFunc == "LOWER") {
        std::string result = val;
        for (char& c : result) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        return result;
    }
    return val;
}

struct EvaluatedIndexEntry {
    std::string name;
    bool included = false;
    std::string key;
};

static bool partialIndexIncludes(
    const std::string& predicate,
    const TableSchema& table,
    const std::map<std::string, std::string>& values,
    const std::string& dbname,
    bool& included,
    StorageEngine* functionEngine) {
    included = true;
    if (predicate.empty()) return true;

    std::string error;
    included = dbms::ExprHelper::evalBool(
        predicate, values, buildTypeHints(table), &error, dbname, "",
        functionEngine);
    return error.empty();
}

static bool expressionIndexEntry(
    const StorageEngine::IndexMetadata& metadata,
    const TableSchema& table,
    const std::map<std::string, std::string>& values,
    const std::string& dbname,
    bool& included,
    std::string& key,
    StorageEngine* functionEngine) {
    included = false;
    key.clear();
    if (!metadata.isExpression) return false;

    const size_t leftParen = metadata.name.find('(');
    const size_t rightParen = metadata.name.rfind(')');
    if (leftParen == std::string::npos || rightParen == std::string::npos ||
        rightParen <= leftParen + 1 ||
        !trim(metadata.name.substr(rightParen + 1)).empty()) {
        return false;
    }
    std::string function = trim(metadata.name.substr(0, leftParen));
    for (char& ch : function) {
        ch = static_cast<char>(
            std::toupper(static_cast<unsigned char>(ch)));
    }
    if (function != "UPPER" && function != "LOWER") return false;

    const std::string columnName = trim(metadata.name.substr(
        leftParen + 1, rightParen - leftParen - 1));
    bool columnExists = false;
    for (size_t i = 0; i < table.len; ++i) {
        if (table.cols[i].dataName == columnName) {
            columnExists = true;
            break;
        }
    }
    if (!columnExists) return false;

    if (!partialIndexIncludes(metadata.whereCondition, table, values,
                              dbname, included, functionEngine)) return false;
    if (!included) return true;

    const std::string value = valueFromRowMap(values, columnName);
    if (value.empty()) {
        included = false;
        return true;
    }
    key = evalExpr(value, function);
    return true;
}

static bool secondaryIndexEntry(
    const StorageEngine::IndexMetadata& metadata,
    const TableSchema& table,
    const std::map<std::string, std::string>& values,
    const std::string& dbname,
    EvaluatedIndexEntry& entry,
    StorageEngine* functionEngine) {
    entry = {};
    entry.name = metadata.name;
    if (metadata.isExpression) {
        return expressionIndexEntry(metadata, table, values, dbname,
                                    entry.included, entry.key, functionEngine);
    }

    const Column* column = nullptr;
    for (size_t i = 0; i < table.len; ++i) {
        if (table.cols[i].dataName == metadata.name) {
            column = &table.cols[i];
            break;
        }
    }
    if (!column ||
        !partialIndexIncludes(metadata.whereCondition, table, values,
                              dbname, entry.included, functionEngine)) {
        return false;
    }
    if (!entry.included) return true;
    entry.key = canonicalColumnKeyValue(
        *column, valueFromRowMap(values, metadata.name));
    if (entry.key.empty()) entry.included = false;
    return true;
}

static bool compositeIndexEntry(
    const StorageEngine::CompositeIndexInfo& metadata,
    const TableSchema& table,
    const std::map<std::string, std::string>& values,
    const std::string& dbname,
    EvaluatedIndexEntry& entry,
    StorageEngine* functionEngine) {
    entry = {};
    entry.name = metadata.name;
    if (!partialIndexIncludes(metadata.whereCondition, table, values,
                              dbname, entry.included, functionEngine)) {
        return false;
    }
    if (!entry.included) return true;
    entry.key = buildCompositeKeyFromRowMap(values, table, metadata.columns);
    if (entry.key.empty()) entry.included = false;
    return true;
}

static std::map<std::string, std::string> indexRowValuesFromBuffer(
    StorageEngine& engine,
    const TableSchema& table,
    const std::string& rowBuffer,
    const std::string& dbname) {
    std::map<std::string, std::string> values;
    for (size_t i = 0; i < table.len; ++i) {
        values[table.cols[i].dataName] = engine.extractColumnValue(
            rowBuffer, table, i, dbname, true);
    }
    return values;
}

static bool secondaryIndexEntryFromBuffer(
    StorageEngine& engine,
    const StorageEngine::IndexMetadata& metadata,
    const TableSchema& table,
    const std::string& rowBuffer,
    const std::string& dbname,
    EvaluatedIndexEntry& entry) {
    const auto values = indexRowValuesFromBuffer(
        engine, table, rowBuffer, dbname);
    return secondaryIndexEntry(
        metadata, table, values, dbname, entry, &engine);
}

static bool compositeIndexEntryFromBuffer(
    StorageEngine& engine,
    const StorageEngine::CompositeIndexInfo& metadata,
    const TableSchema& table,
    const std::string& rowBuffer,
    const std::string& dbname,
    EvaluatedIndexEntry& entry) {
    const auto values = indexRowValuesFromBuffer(
        engine, table, rowBuffer, dbname);
    return compositeIndexEntry(
        metadata, table, values, dbname, entry, &engine);
}

DBStatus StorageEngine::createIndex(const std::string& dbname, const std::string& tablename,
                                     const std::string& colname, bool ascending,
                                     const std::vector<std::string>& includeCols,
                                     const std::string& whereCondition,
                                     const std::string& expression,
                                     bool concurrently,
                                     bool unique) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    // Concurrent validation and partial/expression uniqueness need predicate
    // locking and expression-specific equality metadata that this access path
    // does not yet persist. Reject them rather than publishing a non-enforcing
    // UNIQUE index.
    if (unique && (concurrently || !whereCondition.empty() ||
                   !expression.empty())) {
        return DBStatus::INVALID_VALUE;
    }
    if (concurrently) {
        if (!lockManager_.lockShared(tablename)) return DBStatus::LOCK_CONFLICT;
    } else {
        if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    }
    TableSchema tbl = getTableSchema(dbname, tablename);
    if (unique &&
        tbl.partitionType != TableSchema::PartitionType::None) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    bool isExpression = !expression.empty();
    std::string actualColname = colname;
    std::string exprFunc;
    size_t colIdx = tbl.len;

    if (isExpression) {
        // Parse expression like "UPPER(name)"
        size_t lp = expression.find('(');
        size_t rp = expression.rfind(')');
        if (lp == std::string::npos || rp == std::string::npos ||
            rp <= lp + 1 || !trim(expression.substr(rp + 1)).empty()) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        exprFunc = trim(expression.substr(0, lp));
        for (char& ch : exprFunc) {
            ch = static_cast<char>(
                std::toupper(static_cast<unsigned char>(ch)));
        }
        if (exprFunc != "UPPER" && exprFunc != "LOWER") {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        actualColname = trim(expression.substr(lp + 1, rp - lp - 1));
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == actualColname) { colIdx = i; break; }
        }
    } else {
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
        }
    }
    if (colIdx >= tbl.len) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    if (unique && tbl.cols[colIdx].generatedKind == 'v') {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    IndexMetadata candidateMetadata;
    candidateMetadata.name = isExpression ? expression : actualColname;
    candidateMetadata.isExpression = isExpression;
    candidateMetadata.isUnique = unique;
    candidateMetadata.exprFunc = exprFunc;
    candidateMetadata.whereCondition = whereCondition;
    std::map<std::string, std::string> nullValues;
    for (size_t i = 0; i < tbl.len; ++i) {
        nullValues[tbl.cols[i].dataName] = "";
    }
    bool ignoredMembership = false;
    if (!partialIndexIncludes(whereCondition, tbl, nullValues, dbname,
                              ignoredMembership, this)) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Already indexed? If direction differs, drop and recreate
    auto existing = getIndexedColumns(dbname, tablename);
    bool alreadyIndexed = false;
    for (const auto& c : existing) {
        if (c == actualColname) { alreadyIndexed = true; break; }
    }
    if (alreadyIndexed && !isExpression) {
        if (unique) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        bool currentDesc = isDescendingIndex(dbname, tablename, actualColname);
        if (currentDesc == !ascending) {
            lockManager_.unlock(tablename);
            return DBStatus::OK; // same direction, nothing to do
        }
        if (dropIndex(dbname, tablename, actualColname) != DBStatus::OK) {
            lockManager_.unlock(tablename);
            return DBStatus::IO_ERROR;
        }
    }

    // Build index from existing data using page-based iteration
    const std::string physicalIndexKey = isExpression ? expression : actualColname;
    BPTree* idx = loadBtreeIndex(
        secondaryIndexCache_, dbname + "/" + tablename + "/" + physicalIndexKey,
        secondaryIndexPath(dbname, tablename, physicalIndexKey), true);
    if (!idx) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    const auto discardPhysicalIndex = [&]() {
        idx->close();
        {
            std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
            secondaryIndexCache_.erase(dbname + "/" + tablename + "/" + physicalIndexKey);
        }
        std::error_code error;
        std::filesystem::remove(secondaryIndexPath(dbname, tablename, physicalIndexKey), error);
    };

    const std::vector<size_t> uniqueColumns{colIdx};
    const bool needsCollationScan = unique &&
        constraintNeedsCollationScan(tbl, uniqueColumns);
    std::set<std::string> seenBinaryKeys;
    std::vector<std::string> seenCollatedKeys;
    bool duplicate = false;
    bool entriesValid = true;
    bool indexWriteFailed = false;
    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId,
                                       const char* data, size_t len) {
        if (!entriesValid || duplicate || indexWriteFailed) return;
        std::string row(data, len);
        EvaluatedIndexEntry entry;
        if (!secondaryIndexEntryFromBuffer(
                *this, candidateMetadata, tbl, row, dbname, entry)) {
            entriesValid = false;
            return;
        }
        if (unique) {
            const int64_t rid = encodeRid(pageId, slotId);
            if (!(tbl.cols[colIdx].isNull && dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, colIdx))) {
                const std::string value = extractColumnValue(
                    row, tbl, colIdx, dbname, true);
                if (needsCollationScan) {
                    duplicate = std::any_of(
                        seenCollatedKeys.begin(), seenCollatedKeys.end(),
                        [&](const std::string& existingValue) {
                            return constraintColumnValuesEqual(
                                tbl.cols[colIdx], existingValue, value);
                        });
                    if (!duplicate) seenCollatedKeys.push_back(value);
                } else {
                    duplicate = !seenBinaryKeys.insert(
                        canonicalColumnKeyValue(
                            tbl.cols[colIdx], value)).second;
                }
            }
        }
        if (entry.included && !entry.key.empty()) {
            indexWriteFailed = !idx->insertMulti(
                entry.key, encodeRid(pageId, slotId));
        }
    })) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (duplicate) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::DUPLICATE_KEY;
    }
    if (!entriesValid) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::CORRUPTED_DATA;
    }
    if (indexWriteFailed || !idx->flush()) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }

    // Record in metadata
    std::filesystem::path meta = secondaryIndexMetaPath(dbname, tablename);
    std::string existingMetadata;
    if (!readIndexMetadata(meta, existingMetadata)) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    std::ostringstream serialized;
    if (unique) serialized << UNIQUE_INDEX_METADATA_PREFIX;
    if (isExpression) {
        serialized << "EXPR:" << expression;
    } else {
        serialized << actualColname << (ascending ? "" : ":DESC");
    }
    if (!includeCols.empty()) {
        serialized << ":INCLUDE:";
        for (size_t i = 0; i < includeCols.size(); ++i) {
            if (i > 0) serialized << ",";
            serialized << includeCols[i];
        }
    }
    if (!whereCondition.empty()) {
        serialized << ":WHERE:" << whereCondition;
    }
    serialized << '\n';
    if (!writeIndexMetadata(meta, existingMetadata + serialized.str())) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    invalidateSecidxCache(dbname, tablename);
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::dropIndexByAccessMethod(
    const std::string& dbname, const std::string& tablename,
    const std::string& key, const std::string& accessMethod) {
    std::string am;
    for (char c : accessMethod) {
        am += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }
    if (am == "composite") return dropCompositeIndex(dbname, tablename, key);
    if (am == "hash") return dropHashIndex(dbname, tablename, key);
    if (am == "bloom") return dropBloomIndex(dbname, tablename, key);
    if (am == "gin") return dropGinIndex(dbname, tablename, key);
    if (am == "gist") return dropGiSTIndex(dbname, tablename, key);
    if (am == "brin") return dropBrinIndex(dbname, tablename, key);
    if (am == "spgist") return dropSPGiSTIndex(dbname, tablename, key);
    if (am == "fulltext") return dropFullTextIndex(dbname, tablename, key);
    // "" and "btree" both mean the plain secondary B-tree.
    return dropIndex(dbname, tablename, key);
}

DBStatus StorageEngine::dropIndex(const std::string& dbname, const std::string& tablename,
                                   const std::string& colname) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);

    // Update metadata: remove lines matching this column/expression
    std::filesystem::path meta = secondaryIndexMetaPath(dbname, tablename);
    std::string existingMetadata;
    if (!readIndexMetadata(meta, existingMetadata)) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    std::vector<std::string> lines;
    bool found = false;
    std::istringstream in(existingMetadata);
    std::string line;
    while (std::getline(in, line)) {
        if (line.empty()) continue;
        std::string definition = line;
        (void)consumeUniqueIndexMetadataPrefix(definition);
        bool match = false;
        if (definition.substr(0, 5) == "EXPR:") {
            // Expression index: match "EXPR:colname" or "EXPR:expression"
            size_t exprEnd = definition.find(":INCLUDE:");
            if (exprEnd == std::string::npos) {
                exprEnd = definition.find(":WHERE:");
            }
            if (exprEnd == std::string::npos) exprEnd = definition.size();
            std::string expr = definition.substr(5, exprEnd - 5);
            if (expr == colname) match = true;
        } else {
            // Regular index: extract column name (before :DESC, :INCLUDE, :WHERE)
            size_t wherePos = definition.find(":WHERE:");
            std::string base = (wherePos != std::string::npos)
                ? definition.substr(0, wherePos) : definition;
            size_t includePos = base.find(":INCLUDE");
            base = (includePos != std::string::npos) ? base.substr(0, includePos) : base;
            size_t descPos = base.find(":DESC");
            std::string idxCol = (descPos != std::string::npos) ? base.substr(0, descPos) : base;
            if (idxCol == colname) match = true;
        }
        if (match) found = true;
        else lines.push_back(line);
    }
    if (!found) {
        lockManager_.unlock(tablename);
        return DBStatus::TABLE_NOT_FOUND;
    }

    std::ostringstream retained;
    for (const auto& retainedLine : lines) retained << retainedLine << '\n';
    if (!writeIndexMetadata(meta, retained.str())) {
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    invalidateSecidxCache(dbname, tablename);

    const auto physicalPath = secondaryIndexPath(dbname, tablename, colname);
    std::error_code error;
    if (std::filesystem::exists(physicalPath, error) &&
        !std::filesystem::is_regular_file(physicalPath, error)) {
        writeIndexMetadata(meta, existingMetadata);
        invalidateSecidxCache(dbname, tablename);
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    std::filesystem::remove(physicalPath, error);
    if (error) {
        writeIndexMetadata(meta, existingMetadata);
        invalidateSecidxCache(dbname, tablename);
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    // Remove from cache
    std::string key = dbname + "/" + tablename + "/" + colname;
    secondaryIndexCache_.erase(key);
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::createCompositeIndex(const std::string& dbname,
                                              const std::string& tablename,
                                              const std::vector<std::string>& colnames,
                                              const std::string& indexName,
                                              const std::vector<std::string>& includeCols,
                                              const std::string& whereCondition,
                                              bool concurrently,
                                              bool unique) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (unique && (concurrently || !whereCondition.empty())) {
        return DBStatus::INVALID_VALUE;
    }
    if (concurrently) {
        if (!lockManager_.lockShared(tablename)) return DBStatus::LOCK_CONFLICT;
    } else {
        if (!lockManager_.lockMetadata(tablename)) return DBStatus::LOCK_CONFLICT;
    }
    TableSchema tbl = getTableSchema(dbname, tablename);
    if (unique &&
        tbl.partitionType != TableSchema::PartitionType::None) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Validate all columns exist and no key component is repeated.
    std::vector<size_t> columnIndices;
    std::set<size_t> distinctColumns;
    for (const auto& cname : colnames) {
        size_t found = tbl.len;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == cname) { found = i; break; }
        }
        if (found >= tbl.len || !distinctColumns.insert(found).second ||
            (unique && tbl.cols[found].generatedKind == 'v')) {
            lockManager_.unlock(tablename);
            return DBStatus::INVALID_VALUE;
        }
        columnIndices.push_back(found);
    }
    if (columnIndices.empty()) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Check name collision with existing composite indexes
    auto existingComp = getCompositeIndexes(dbname, tablename);
    for (const auto& ci : existingComp) {
        if (ci.name == indexName) {
            lockManager_.unlock(tablename);
            return ci.isUnique == unique
                ? DBStatus::OK : DBStatus::INVALID_VALUE;
        }
    }

    CompositeIndexInfo candidateMetadata;
    candidateMetadata.name = indexName;
    candidateMetadata.columns = colnames;
    candidateMetadata.whereCondition = whereCondition;
    candidateMetadata.isUnique = unique;
    std::map<std::string, std::string> nullValues;
    for (size_t i = 0; i < tbl.len; ++i) {
        nullValues[tbl.cols[i].dataName] = "";
    }
    bool ignoredMembership = false;
    if (!partialIndexIncludes(whereCondition, tbl, nullValues, dbname,
                              ignoredMembership, this)) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }

    // Build index from existing data
    BPTree* idx = loadBtreeIndex(
        secondaryIndexCache_, dbname + "/" + tablename + "/C/" + indexName,
        relationDir(dbname, tablename) / (tablename + ".idx_" + indexName), true);
    if (!idx) {
        lockManager_.unlock(tablename);
        return DBStatus::INVALID_VALUE;
    }
    const std::string physicalIndexKey = dbname + "/" + tablename + "/C/" + indexName;
    const auto discardPhysicalIndex = [&]() {
        idx->close();
        {
            std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
            secondaryIndexCache_.erase(physicalIndexKey);
        }
        std::error_code error;
        std::filesystem::remove(relationDir(dbname, tablename) /
                                (tablename + ".idx_" + indexName), error);
    };

    const bool needsCollationScan = unique &&
        constraintNeedsCollationScan(tbl, columnIndices);
    std::set<std::vector<std::string>> seenBinaryKeys;
    std::vector<std::vector<std::string>> seenCollatedKeys;
    bool duplicate = false;
    bool entriesValid = true;
    bool indexWriteFailed = false;
    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId,
                                       const char* data, size_t len) {
        if (!entriesValid || duplicate || indexWriteFailed) return;
        std::string row(data, len);
        EvaluatedIndexEntry entry;
        if (!compositeIndexEntryFromBuffer(
                *this, candidateMetadata, tbl, row, dbname, entry)) {
            entriesValid = false;
            return;
        }
        if (unique) {
            const int64_t rid = encodeRid(pageId, slotId);
            std::vector<std::string> key;
            key.reserve(columnIndices.size());
            bool containsNull = false;
            for (const size_t columnIndex : columnIndices) {
                if (tbl.cols[columnIndex].isNull && dbms::detail::storedRowColumnIsNull(*this, dbname, tablename, tbl, rid, columnIndex)) {
                    containsNull = true;
                    break;
                }
                key.push_back(extractColumnValue(
                    row, tbl, columnIndex, dbname, true));
            }
            if (!containsNull && needsCollationScan) {
                duplicate = std::any_of(
                    seenCollatedKeys.begin(), seenCollatedKeys.end(),
                    [&](const std::vector<std::string>& existingKey) {
                        return constraintKeyValuesEqual(
                            tbl, columnIndices, existingKey, key);
                    });
                if (!duplicate) {
                    seenCollatedKeys.push_back(std::move(key));
                }
            } else if (!containsNull) {
                for (size_t valueIndex = 0;
                     valueIndex < columnIndices.size(); ++valueIndex) {
                    key[valueIndex] = canonicalColumnKeyValue(
                        tbl.cols[columnIndices[valueIndex]],
                        key[valueIndex]);
                }
                duplicate =
                    !seenBinaryKeys.insert(std::move(key)).second;
            }
        }
        if (entry.included && !entry.key.empty()) {
            indexWriteFailed = !idx->insertMulti(
                entry.key, encodeRid(pageId, slotId));
        }
    })) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    if (duplicate) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::DUPLICATE_KEY;
    }
    if (!entriesValid) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::CORRUPTED_DATA;
    }
    if (indexWriteFailed || !idx->flush()) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }

    // Record in metadata: C:indexName:col1:col2:...:INCLUDE:inc1,inc2[:WHERE:cond]
    std::filesystem::path meta = secondaryIndexMetaPath(dbname, tablename);
    std::string existingMetadata;
    if (!readIndexMetadata(meta, existingMetadata)) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    std::ostringstream serialized;
    if (unique) serialized << UNIQUE_INDEX_METADATA_PREFIX;
    serialized << "C:" << indexName;
    for (const auto& c : colnames) serialized << ":" << c;
    if (!includeCols.empty()) {
        serialized << ":INCLUDE:";
        for (size_t i = 0; i < includeCols.size(); ++i) {
            if (i > 0) serialized << ",";
            serialized << includeCols[i];
        }
    }
    if (!whereCondition.empty()) {
        serialized << ":WHERE:" << whereCondition;
    }
    serialized << '\n';
    if (!writeIndexMetadata(meta, existingMetadata + serialized.str())) {
        discardPhysicalIndex();
        lockManager_.unlock(tablename);
        return DBStatus::IO_ERROR;
    }
    invalidateSecidxCache(dbname, tablename);
    lockManager_.unlock(tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::dropCompositeIndex(const std::string& dbname,
                                            const std::string& tablename,
                                            const std::string& indexName) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    const std::filesystem::path meta = secondaryIndexMetaPath(dbname, tablename);
    std::string existingMetadata;
    if (!readIndexMetadata(meta, existingMetadata)) return DBStatus::IO_ERROR;
    // Verify the composite index actually exists
    auto compIdxs = getCompositeIndexes(dbname, tablename);
    bool found = false;
    for (const auto& ci : compIdxs) {
        if (ci.name == indexName) { found = true; break; }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;

    // Preserve every remaining metadata line, including INCLUDE/WHERE
    // options, instead of reconstructing a lossy subset from parsed fields.
    std::ostringstream retained;
    std::istringstream input(existingMetadata);
    std::string line;
    bool removedMetadata = false;
    while (std::getline(input, line)) {
        std::string definition = line;
        (void)consumeUniqueIndexMetadataPrefix(definition);
        const std::string prefix = "C:" + indexName;
        const bool isTarget = definition.rfind(prefix, 0) == 0 &&
            (definition.size() == prefix.size() ||
             definition[prefix.size()] == ':');
        if (isTarget) {
            removedMetadata = true;
            continue;
        }
        if (!line.empty()) retained << line << '\n';
    }
    if (!removedMetadata || !writeIndexMetadata(meta, retained.str())) {
        return removedMetadata ? DBStatus::IO_ERROR : DBStatus::TABLE_NOT_FOUND;
    }
    invalidateSecidxCache(dbname, tablename);

    const auto physicalPath = relationDir(dbname, tablename) /
                              (tablename + ".idx_" + indexName);
    std::error_code error;
    if (std::filesystem::exists(physicalPath, error) &&
        !std::filesystem::is_regular_file(physicalPath, error)) {
        writeIndexMetadata(meta, existingMetadata);
        invalidateSecidxCache(dbname, tablename);
        return DBStatus::IO_ERROR;
    }
    std::filesystem::remove(physicalPath, error);
    if (error) {
        writeIndexMetadata(meta, existingMetadata);
        invalidateSecidxCache(dbname, tablename);
        return DBStatus::IO_ERROR;
    }
    // Remove from cache
    std::string key = dbname + "/" + tablename + "/C/" + indexName;
    secondaryIndexCache_.erase(key);
    return DBStatus::OK;
}

DBStatus StorageEngine::reindex(const std::string& dbname,
                                 const std::string& tablename) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (!lockManager_.lockMetadata(tablename)) {
        return DBStatus::LOCK_CONFLICT;
    }
    ResourceUnlockGuard tableLockGuard(lockManager_, tablename);
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!tableExists(dbname, tablename)) {
        return DBStatus::TABLE_NOT_FOUND;
    }
    const std::filesystem::path reindexRelationRoot =
        relationDir(dbname, tablename);

    struct PendingIndex {
        ReindexSwapEntry swap;
        std::string cacheKey;
        bool primary = false;
        std::unique_ptr<BPTree> tree;
    };

    static std::atomic<uint64_t> temporarySequence{0};
    std::vector<PendingIndex> pending;
    const std::filesystem::path swapMarker =
        dbPath(dbname) /
        ("." + tablename + std::string(kReindexSwapMarkerSuffix));
    bool swapMarkerPublished = false;
    const auto cleanupPending = [&]() {
        for (auto& index : pending) {
            if (index.tree) index.tree->close();
            removeRegularFileIfPresent(index.swap.temporary);
            removeRegularFileIfPresent(reindexSidecar(index.swap.temporary));
        }
    };
    const auto evictLiveCaches = [&]() {
        for (const auto& index : pending) {
            if (index.primary) pkIndexCache_.erase(index.cacheKey);
            else secondaryIndexCache_.erase(index.cacheKey);
        }
    };
    const auto finishFailure = [&](DBStatus status) {
        if (swapMarkerPublished) {
            // Recovery may publish a replacement even when the marker's
            // directory fsync was the operation that failed. Never leave a
            // cached descriptor pointing at the generation recovery replaced.
            evictLiveCaches();
            std::vector<ReindexSwapEntry> entries;
            entries.reserve(pending.size());
            for (const auto& index : pending) entries.push_back(index.swap);
            if (!recoverReindexSwapPlan(entries, swapMarker)) {
                status = DBStatus::IO_ERROR;
            }
        } else {
            cleanupPending();
        }
        return status;
    };
    const auto createPending = [&](const std::filesystem::path& target,
                                   std::string cacheKey,
                                   bool primary) -> BPTree* {
        PendingIndex index;
        if (!normalizedAbsolutePath(target, index.swap.target)) return nullptr;
        const uint64_t sequence = temporarySequence.fetch_add(1);
        const std::string uniqueSuffix =
            std::to_string(static_cast<unsigned long long>(::getpid())) + "." +
            std::to_string(sequence);
        index.swap.temporary = std::filesystem::path(
            index.swap.target.string() + ".reindex.tmp." + uniqueSuffix);
        index.swap.backup = std::filesystem::path(
            index.swap.target.string() + ".reindex.old." + uniqueSuffix);
        index.cacheKey = std::move(cacheKey);
        index.primary = primary;

        if (!validReindexSwapEntry(
                index.swap, reindexRelationRoot, tablename) ||
            !removeRegularFileIfPresent(index.swap.temporary) ||
            !removeRegularFileIfPresent(
                reindexSidecar(index.swap.temporary)) ||
            !removeRegularFileIfPresent(index.swap.backup) ||
            !removeRegularFileIfPresent(reindexSidecar(index.swap.backup))) {
            return nullptr;
        }
        index.tree = std::make_unique<BPTree>(index.swap.temporary);
        if (!index.tree->open()) {
            index.tree->close();
            removeRegularFileIfPresent(index.swap.temporary);
            removeRegularFileIfPresent(
                reindexSidecar(index.swap.temporary));
            return nullptr;
        }
        pending.push_back(std::move(index));
        return pending.back().tree.get();
    };
    const auto finishTree = [&](BPTree* tree) {
        if (!tree || !tree->flush()) return false;
        tree->close();
        return true;
    };

    const TableSchema tbl = getTableSchema(dbname, tablename);
    const auto secondaryIndexes = getIndexMetadata(dbname, tablename);
    const auto compositeIndexes = getCompositeIndexes(dbname, tablename);
    const std::string tableKey = dbname + "/" + tablename;

    // Build every replacement beside the live files. The metadata lock keeps
    // DML and rollback maintenance out of the scan; the physical-index view
    // deliberately includes active INSERT versions and excludes versions
    // removed by active UPDATE/DELETE operations. A later COMMIT requires no
    // extra index write, while a later ROLLBACK repairs the replacement in the
    // same way it repaired the old tree.
    // Keep row-major dispatch away from SQL-expression evaluation: partial
    // predicates and virtual columns can have observable effects. Their old
    // index-major build below remains the owner of those evaluations.
    // Bound simultaneously open new buffer pools; larger index sets retain
    // the old successful low-fanout resource policy without attempting and
    // retrying a partially built fast path.
    constexpr size_t maxSinglePassTrees = 8;
    bool singlePassEligible = secondaryIndexes.size() < maxSinglePassTrees &&
        compositeIndexes.size() < maxSinglePassTrees &&
        1 + secondaryIndexes.size() + compositeIndexes.size() <= maxSinglePassTrees &&
        (!secondaryIndexes.empty() || !compositeIndexes.empty());
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].generatedKind == 'v') singlePassEligible = false;
    }
    for (const auto& metadata : secondaryIndexes) {
        if (metadata.isExpression || !metadata.whereCondition.empty())
            singlePassEligible = false;
    }
    for (const auto& metadata : compositeIndexes) {
        if (!metadata.whereCondition.empty()) singlePassEligible = false;
    }

    if (singlePassEligible) {
        BPTree* primary = createPending(
            indexPath(dbname, tablename), tableKey, true);
        if (!primary) return finishFailure(DBStatus::IO_ERROR);
        std::vector<BPTree*> secondaryTrees;
        secondaryTrees.reserve(secondaryIndexes.size());
        for (const auto& metadata : secondaryIndexes) {
            BPTree* tree = createPending(
                secondaryIndexPath(dbname, tablename, metadata.name),
                tableKey + "/" + metadata.name, false);
            if (!tree) return finishFailure(DBStatus::IO_ERROR);
            secondaryTrees.push_back(tree);
        }
        std::vector<BPTree*> compositeTrees;
        compositeTrees.reserve(compositeIndexes.size());
        for (const auto& metadata : compositeIndexes) {
            BPTree* tree = createPending(
                reindexRelationRoot / (tablename + ".idx_" + metadata.name),
                tableKey + "/C/" + metadata.name, false);
            if (!tree) return finishFailure(DBStatus::IO_ERROR);
            compositeTrees.push_back(tree);
        }

        bool primaryWriteFailed = false;
        std::vector<DBStatus> secondaryStatus(secondaryIndexes.size(), DBStatus::OK);
        std::vector<DBStatus> compositeStatus(compositeIndexes.size(), DBStatus::OK);
        if (!forEachRow(dbname, tablename,
                        [&](uint32_t pageId, uint16_t slotId,
                            const char* data, size_t len) {
            const std::string row(data, len);
            const int64_t rid = encodeRid(pageId, slotId);
            if (tbl.hasPrimaryKey() && !primaryWriteFailed) {
                const std::string key = extractPKValue(row, tbl);
                if (!key.empty()) primaryWriteFailed = !primary->insert(key, rid);
            }
            if (primaryWriteFailed) return;
            // One owning logical map is valid only during this genuine heap
            // callback and its existing NULL binding. Keep no row/context
            // between callbacks and pass the original schema/key builders.
            const auto values = indexRowValuesFromBuffer(*this, tbl, row, dbname);
            for (size_t i = 0; i < secondaryIndexes.size(); ++i) {
                if (secondaryStatus[i] != DBStatus::OK) return;
                EvaluatedIndexEntry entry;
                if (!secondaryIndexEntry(
                        secondaryIndexes[i], tbl, values, dbname, entry, this)) {
                    secondaryStatus[i] = DBStatus::CORRUPTED_DATA;
                    return;
                } else if (entry.included && !entry.key.empty() &&
                           !secondaryTrees[i]->insertMulti(entry.key, rid)) {
                    secondaryStatus[i] = DBStatus::IO_ERROR;
                    return;
                }
            }
            for (size_t i = 0; i < compositeIndexes.size(); ++i) {
                if (compositeStatus[i] != DBStatus::OK) return;
                EvaluatedIndexEntry entry;
                if (!compositeIndexEntry(
                        compositeIndexes[i], tbl, values, dbname, entry, this)) {
                    compositeStatus[i] = DBStatus::CORRUPTED_DATA;
                    return;
                } else if (entry.included && !entry.key.empty() &&
                           !compositeTrees[i]->insertMulti(entry.key, rid)) {
                    compositeStatus[i] = DBStatus::IO_ERROR;
                    return;
                }
            }
        }, nullptr, {}, false, true)) {
            return finishFailure(DBStatus::IO_ERROR);
        }
        // Resolve failures/flush in the old index order. No replacement is
        // published until every private tree is complete and closed.
        if (primaryWriteFailed || !finishTree(primary))
            return finishFailure(DBStatus::IO_ERROR);
        for (size_t i = 0; i < secondaryTrees.size(); ++i) {
            if (secondaryStatus[i] != DBStatus::OK)
                return finishFailure(secondaryStatus[i]);
            if (!finishTree(secondaryTrees[i]))
                return finishFailure(DBStatus::IO_ERROR);
        }
        for (size_t i = 0; i < compositeTrees.size(); ++i) {
            if (compositeStatus[i] != DBStatus::OK)
                return finishFailure(compositeStatus[i]);
            if (!finishTree(compositeTrees[i]))
                return finishFailure(DBStatus::IO_ERROR);
        }
    } else {
    BPTree* primary = createPending(
        indexPath(dbname, tablename), tableKey, true);
    if (!primary) return finishFailure(DBStatus::IO_ERROR);
    bool primaryWriteFailed = false;
    if (tbl.hasPrimaryKey() &&
        !forEachRow(dbname, tablename,
                    [&](uint32_t pageId, uint16_t slotId,
                        const char* data, size_t len) {
            if (primaryWriteFailed) return;
            const std::string row(data, len);
            const std::string key = extractPKValue(row, tbl);
            if (!key.empty()) {
                primaryWriteFailed = !primary->insert(
                    key, encodeRid(pageId, slotId));
            }
        }, nullptr, {}, false, true)) {
        return finishFailure(DBStatus::IO_ERROR);
    }
    if (primaryWriteFailed || !finishTree(primary)) {
        return finishFailure(DBStatus::IO_ERROR);
    }

    // Ordinary and expression secondary indexes recompute partial-index
    // membership for every row instead of inferring it from the key alone.
    for (const auto& metadata : secondaryIndexes) {
        const std::string cacheKey =
            tableKey + "/" + metadata.name;
        BPTree* tree = createPending(
            secondaryIndexPath(dbname, tablename, metadata.name),
            cacheKey, false);
        if (!tree) return finishFailure(DBStatus::IO_ERROR);

        bool metadataValid = true;
        bool writeFailed = false;
        if (!forEachRow(dbname, tablename,
                        [&](uint32_t pageId, uint16_t slotId,
                            const char* data, size_t len) {
            if (!metadataValid || writeFailed) return;
            const std::string row(data, len);
            EvaluatedIndexEntry entry;
            if (!secondaryIndexEntryFromBuffer(
                    *this, metadata, tbl, row, dbname, entry)) {
                metadataValid = false;
                return;
            }
            if (entry.included && !entry.key.empty()) {
                writeFailed = !tree->insertMulti(
                    entry.key, encodeRid(pageId, slotId));
            }
        }, nullptr, {}, false, true)) {
            return finishFailure(DBStatus::IO_ERROR);
        }
        if (!metadataValid) {
            return finishFailure(DBStatus::CORRUPTED_DATA);
        }
        if (writeFailed || !finishTree(tree)) {
            return finishFailure(DBStatus::IO_ERROR);
        }
    }

    for (const auto& metadata : compositeIndexes) {
        const std::string cacheKey =
            tableKey + "/C/" + metadata.name;
        BPTree* tree = createPending(
            reindexRelationRoot /
                (tablename + ".idx_" + metadata.name),
            cacheKey, false);
        if (!tree) return finishFailure(DBStatus::IO_ERROR);

        bool metadataValid = true;
        bool writeFailed = false;
        if (!forEachRow(dbname, tablename,
                        [&](uint32_t pageId, uint16_t slotId,
                            const char* data, size_t len) {
            if (!metadataValid || writeFailed) return;
            const std::string row(data, len);
            EvaluatedIndexEntry entry;
            if (!compositeIndexEntryFromBuffer(
                    *this, metadata, tbl, row, dbname, entry)) {
                metadataValid = false;
                return;
            }
            if (entry.included && !entry.key.empty()) {
                writeFailed = !tree->insertMulti(
                    entry.key, encodeRid(pageId, slotId));
            }
        }, nullptr, {}, false, true)) {
            return finishFailure(DBStatus::IO_ERROR);
        }
        if (!metadataValid) {
            return finishFailure(DBStatus::CORRUPTED_DATA);
        }
        if (writeFailed || !finishTree(tree)) {
            return finishFailure(DBStatus::IO_ERROR);
        }
    }

    }

    // A B+ tree and its TDE authentication sidecar are one logical file. Keep
    // the old pair as a rollback generation and publish a durable swap plan
    // before the first rename. Startup can then repair a crash at any point
    // between the individual filesystem operations.
    std::vector<ReindexSwapEntry> swapEntries;
    swapEntries.reserve(pending.size());
    std::set<std::filesystem::path> uniqueTargets;
    for (auto& index : pending) {
        index.tree.reset();

        BPTree* cached = nullptr;
        if (index.primary) {
            const auto existing = pkIndexCache_.find(index.cacheKey);
            if (existing != pkIndexCache_.end()) cached = existing->second.get();
        } else {
            const auto existing = secondaryIndexCache_.find(index.cacheKey);
            if (existing != secondaryIndexCache_.end()) {
                cached = existing->second.get();
            }
        }
        // A rollback generation is useful only if every dirty main/sidecar
        // page has reached disk before its path is renamed into the backup.
        // A closed cache has no resident pages to persist; REINDEX must still
        // be able to replace its corrupt or otherwise failed generation.
        if (cached && cached->isOpen() && !cached->flush()) {
            return finishFailure(DBStatus::IO_ERROR);
        }

        bool targetExists = false;
        bool targetSidecarExists = false;
        bool temporaryExists = false;
        bool temporarySidecarExists = false;
        bool backupExists = false;
        bool backupSidecarExists = false;
        if (!inspectRegularFile(index.swap.target, targetExists) ||
            !inspectRegularFile(
                reindexSidecar(index.swap.target), targetSidecarExists) ||
            !inspectRegularFile(index.swap.temporary, temporaryExists) ||
            !inspectRegularFile(
                reindexSidecar(index.swap.temporary),
                temporarySidecarExists) ||
            !inspectRegularFile(index.swap.backup, backupExists) ||
            !inspectRegularFile(
                reindexSidecar(index.swap.backup), backupSidecarExists) ||
            (targetExists && !targetSidecarExists) || !temporaryExists ||
            !temporarySidecarExists || backupExists || backupSidecarExists ||
            !validReindexSwapEntry(
                index.swap, reindexRelationRoot, tablename) ||
            !uniqueTargets.insert(index.swap.target).second) {
            return finishFailure(DBStatus::IO_ERROR);
        }
        swapEntries.push_back(index.swap);
    }

    // fsync on each tree makes its bytes durable, but a newly created temp
    // filename is not crash-stable until its containing directory is synced.
    // The marker must never outlive the only recoverable replacement files.
    if (!syncDirectoryDurably(reindexRelationRoot)) {
        return finishFailure(DBStatus::IO_ERROR);
    }

    bool existingMarker = false;
    if (!inspectRegularFile(swapMarker, existingMarker) || existingMarker) {
        return finishFailure(DBStatus::IO_ERROR);
    }
    std::string serializedSwapPlan;
    if (!serializeReindexSwapPlan(swapEntries, serializedSwapPlan) ||
        !index_file::writeAtomically(swapMarker, serializedSwapPlan)) {
        bool markerExists = false;
        if (inspectRegularFile(swapMarker, markerExists) && markerExists) {
            swapMarkerPublished = true;
        }
        return finishFailure(DBStatus::IO_ERROR);
    }
    swapMarkerPublished = true;

    // No reader can hold a table lock while the metadata lock is held. Close
    // every descriptor for the live generations before renaming them.
    evictLiveCaches();

    for (const auto& entry : swapEntries) {
        std::error_code error;
        bool targetExists = false;
        bool targetSidecarExists = false;
        if (!inspectRegularFile(entry.target, targetExists) ||
            !inspectRegularFile(
                reindexSidecar(entry.target), targetSidecarExists)) {
            return finishFailure(DBStatus::IO_ERROR);
        }
        if (targetExists) {
            std::filesystem::rename(entry.target, entry.backup, error);
            if (error) return finishFailure(DBStatus::IO_ERROR);
        }
        if (targetSidecarExists) {
            std::filesystem::rename(
                reindexSidecar(entry.target),
                reindexSidecar(entry.backup), error);
            if (error) return finishFailure(DBStatus::IO_ERROR);
        }
        std::filesystem::rename(entry.temporary, entry.target, error);
        if (error) return finishFailure(DBStatus::IO_ERROR);
        std::filesystem::rename(
            reindexSidecar(entry.temporary), reindexSidecar(entry.target),
            error);
        if (error) return finishFailure(DBStatus::IO_ERROR);
    }

    std::set<std::filesystem::path> parentDirectories;
    for (const auto& entry : swapEntries) {
        parentDirectories.insert(entry.target.parent_path());
    }
    for (const auto& directory : parentDirectories) {
        if (!syncDirectoryDurably(directory)) {
            return finishFailure(DBStatus::IO_ERROR);
        }
    }

    // Removing the main backup commits this individual pair. Remove it before
    // the sidecar backup so crash recovery never restores an old main file
    // beside a new sidecar.
    for (const auto& entry : swapEntries) {
        if (!removeRegularFileIfPresent(entry.backup) ||
            !removeRegularFileIfPresent(reindexSidecar(entry.backup))) {
            return finishFailure(DBStatus::IO_ERROR);
        }
    }
    for (const auto& directory : parentDirectories) {
        if (!syncDirectoryDurably(directory)) {
            return finishFailure(DBStatus::IO_ERROR);
        }
    }
    if (!removeRegularFileIfPresent(swapMarker) ||
        !syncDirectoryDurably(swapMarker.parent_path())) {
        return finishFailure(DBStatus::IO_ERROR);
    }
    swapMarkerPublished = false;

    return DBStatus::OK;
}

// ========================================================================
// Full-text index (simplified inverted index)
// ========================================================================

std::filesystem::path StorageEngine::fullTextIndexPath(const std::string& dbname,
                                                        const std::string& tablename,
                                                        const std::string& colname) const {
    return relationDir(dbname, tablename) / (tablename + "_" + colname + ".fti");
}

static std::vector<std::string> tokenizeText(const std::string& text) {
    std::vector<std::string> tokens;
    std::string current;
    for (char c : text) {
        if (std::isalnum(static_cast<unsigned char>(c))) {
            current += static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
        } else {
            if (!current.empty()) {
                tokens.push_back(current);
                current.clear();
            }
        }
    }
    if (!current.empty()) tokens.push_back(current);
    return tokens;
}

DBStatus StorageEngine::createFullTextIndex(const std::string& dbname,
                                             const std::string& tablename,
                                             const std::string& colname) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t colIdx = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
    }
    if (colIdx >= tbl.len) return DBStatus::INVALID_VALUE;

    std::map<std::string, std::set<int64_t>> inverted;
    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId,
                                       const char* data, size_t len) {
        std::string row(data, len);
        std::string val = extractColumnValue(
            row, tbl, colIdx, dbname, true);
        auto tokens = tokenizeText(val);
        int64_t rid = encodeRid(pageId, slotId);
        for (const auto& tok : tokens) {
            inverted[tok].insert(rid);
        }
    })) return DBStatus::IO_ERROR;

    auto path = fullTextIndexPath(dbname, tablename, colname);
    std::ostringstream out;
    for (const auto& kv : inverted) {
        out << kv.first;
        for (int64_t rid : kv.second) {
            out << ' ' << rid;
        }
        out << '\n';
    }
    if (!index_file::writeAtomically(path, out.str())) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

DBStatus StorageEngine::dropFullTextIndex(const std::string& dbname,
                                           const std::string& tablename,
                                           const std::string& colname) {
    auto path = fullTextIndexPath(dbname, tablename, colname);
    if (std::filesystem::exists(path)) {
        std::filesystem::remove(path);
    }
    return DBStatus::OK;
}

bool StorageEngine::hasFullTextIndex(const std::string& dbname,
                                      const std::string& tablename,
                                      const std::string& colname) const {
    return std::filesystem::exists(fullTextIndexPath(dbname, tablename, colname));
}

bool StorageEngine::specializedIndexesNeedHeapFallback(
    const std::string& dbname, const std::string& tablename) const {
    if (specializedIndexesAreDirty(*this, dbname, tablename)) return true;
    std::lock_guard<std::mutex> lock(globalTxnMutex());
    return std::any_of(
        activeTransactionDatabases().begin(),
        activeTransactionDatabases().end(),
        [&](const auto& active) { return active.second == dbname; });
}

std::vector<int64_t> StorageEngine::fullTextSearch(const std::string& dbname,
                                                     const std::string& tablename,
                                                     const std::string& colname,
                                                     const std::string& word) const {
    std::vector<int64_t> result;
    auto path = fullTextIndexPath(dbname, tablename, colname);
    std::error_code pathError;
    if (!std::filesystem::is_regular_file(path, pathError) || pathError)
        return result;
    std::string searchWord = word;
    for (char& c : searchWord) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    if (specializedIndexesNeedHeapFallback(dbname, tablename)) {
        const TableSchema table = getTableSchema(dbname, tablename);
        size_t columnIndex = table.len;
        for (size_t i = 0; i < table.len; ++i) {
            if (table.cols[i].dataName == colname) {
                columnIndex = i;
                break;
            }
        }
        if (columnIndex >= table.len) return result;
        const bool scanned = forEachRow(
            dbname, tablename,
            [&](uint32_t pageId, uint16_t slotId,
                const char* data, size_t length) {
                const std::string value =
                    const_cast<StorageEngine*>(this)->extractColumnValue(
                        std::string(data, length), table, columnIndex,
                        dbname, true);
                const auto tokens = tokenizeText(value);
                if (std::find(tokens.begin(), tokens.end(), searchWord) !=
                    tokens.end()) {
                    result.push_back(encodeRid(pageId, slotId));
                }
            });
        if (!scanned) result.clear();
        return result;
    }
    std::ifstream in(path);
    if (!in) return result;
    std::string line;
    while (std::getline(in, line)) {
        size_t sp = line.find(' ');
        std::string tok = (sp == std::string::npos) ? line : line.substr(0, sp);
        if (tok == searchWord) {
            if (sp != std::string::npos) {
                std::string rest = line.substr(sp + 1);
                std::stringstream ss(rest);
                int64_t rid;
                while (ss >> rid) result.push_back(rid);
            }
            break;
        }
    }
    return result;
}

std::vector<std::string> StorageEngine::getFullTextIndexedColumns(const std::string& dbname,
                                                                   const std::string& tablename) const {
    std::vector<std::string> result;
    auto dir = relationDir(dbname, tablename);
    if (!std::filesystem::exists(dir)) return result;
    std::string prefix = tablename + "_";
    for (const auto& entry : std::filesystem::directory_iterator(dir)) {
        if (!entry.is_regular_file()) continue;
        std::string name = entry.path().filename().string();
        if (name.size() > 4 && name.substr(name.size() - 4) == ".fti" &&
            name.substr(0, prefix.size()) == prefix) {
            std::string colname = name.substr(prefix.size(), name.size() - prefix.size() - 4);
            result.push_back(colname);
        }
    }
    return result;
}

// ========================================================================
// GIN index (Generalized Inverted Index)
// ========================================================================

std::filesystem::path StorageEngine::ginIndexPath(const std::string& dbname,
                                                  const std::string& tablename,
                                                  const std::string& colname) const {
    return relationDir(dbname, tablename) / (tablename + "_" + colname + ".gin");
}

// Extract keys from a column value for GIN indexing
static std::vector<std::string> extractGinKeys(const std::string& value, const std::string& dataType) {
    std::vector<std::string> keys;
    if (dataType == "text" || dataType == "varchar" || dataType == "char") {
        // Text: tokenize (same as full-text)
        keys = tokenizeText(value);
    } else if (dataType == "json" || dataType == "jsonb") {
        // JSON: extract all string/number leaf values
        // Simple parser: find "..." or numeric values outside quotes
        size_t i = 0;
        while (i < value.size()) {
            // Skip whitespace and structural chars
            while (i < value.size() && (std::isspace(static_cast<unsigned char>(value[i])) ||
                                         value[i] == '{' || value[i] == '}' ||
                                         value[i] == '[' || value[i] == ']' ||
                                         value[i] == ':' || value[i] == ',')) ++i;
            if (i >= value.size()) break;
            if (value[i] == '"') {
                // String value
                size_t end = value.find('"', i + 1);
                if (end == std::string::npos) break;
                std::string s = value.substr(i + 1, end - i - 1);
                // Skip keys (strings followed by ':')
                size_t after = end + 1;
                while (after < value.size() && std::isspace(static_cast<unsigned char>(value[after]))) ++after;
                if (after < value.size() && value[after] == ':') {
                    // This is a key, skip it
                } else {
                    keys.push_back(s);
                }
                i = end + 1;
            } else if (std::isdigit(static_cast<unsigned char>(value[i])) || value[i] == '-') {
                // Number value
                size_t j = i + 1;
                while (j < value.size() && (std::isdigit(static_cast<unsigned char>(value[j])) ||
                                             value[j] == '.' || value[j] == 'e' || value[j] == 'E' ||
                                             value[j] == '+' || value[j] == '-')) ++j;
                keys.push_back(value.substr(i, j - i));
                i = j;
            } else {
                // true/false/null
                if (value.substr(i, 4) == "true") { keys.push_back("true"); i += 4; }
                else if (value.substr(i, 5) == "false") { keys.push_back("false"); i += 5; }
                else if (value.substr(i, 4) == "null") { keys.push_back("null"); i += 4; }
                else { ++i; }
            }
        }
    } else if (dataType.find("[") != std::string::npos || dataType == "array") {
        // Array: split by comma, strip brackets
        std::string trimmed = value;
        if (!trimmed.empty() && trimmed.front() == '{') trimmed = trimmed.substr(1);
        if (!trimmed.empty() && trimmed.back() == '}') trimmed.pop_back();
        size_t cp = 0;
        while (cp < trimmed.size()) {
            size_t c = trimmed.find(',', cp);
            std::string v = trim(trimmed.substr(cp, c - cp));
            if (!v.empty()) keys.push_back(v);
            if (c == std::string::npos) break;
            cp = c + 1;
        }
    } else {
        // Other types: value itself as single key
        keys.push_back(value);
    }
    return keys;
}

static std::string serializeGinIndex(
        const std::map<std::string, std::set<int64_t>>& inverted) {
    using namespace gin_index_format;
    std::string output;
    output.append(kMagic.data(), kMagic.size());
    appendU32(output, kVersion);
    appendU64(output, static_cast<uint64_t>(inverted.size()));
    for (const auto& [key, rids] : inverted) {
        appendU64(output, static_cast<uint64_t>(key.size()));
        output.append(key);
        appendU64(output, static_cast<uint64_t>(rids.size()));
        for (int64_t rid : rids) {
            appendU64(output, static_cast<uint64_t>(rid));
        }
    }
    appendU32(output, index_checksum::crc32c(output.data(), output.size()));
    return output;
}

DBStatus StorageEngine::createGinIndex(const std::string& dbname,
                                        const std::string& tablename,
                                        const std::string& colname) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t colIdx = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
    }
    if (colIdx >= tbl.len) return DBStatus::INVALID_VALUE;

    std::map<std::string, std::set<int64_t>> inverted;
    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId,
                                       const char* data, size_t len) {
        std::string row(data, len);
        std::string val = extractColumnValue(
            row, tbl, colIdx, dbname, true);
        auto keys = extractGinKeys(val, tbl.cols[colIdx].dataType);
        int64_t rid = encodeRid(pageId, slotId);
        for (const auto& k : keys) {
            if (!k.empty()) inverted[k].insert(rid);
        }
    })) return DBStatus::IO_ERROR;

    auto path = ginIndexPath(dbname, tablename, colname);
    const std::string bytes = serializeGinIndex(inverted);
    if (!index_file::writeAtomically(path, bytes)) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

DBStatus StorageEngine::dropGinIndex(const std::string& dbname,
                                      const std::string& tablename,
                                      const std::string& colname) {
    auto path = ginIndexPath(dbname, tablename, colname);
    std::error_code ec;
    if (std::filesystem::exists(path, ec) && !std::filesystem::remove(path, ec)) {
        return DBStatus::IO_ERROR;
    }
    if (ec) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

bool StorageEngine::hasGinIndex(const std::string& dbname,
                                 const std::string& tablename,
                                 const std::string& colname) const {
    return std::filesystem::exists(ginIndexPath(dbname, tablename, colname));
}

static bool readGinIndexForKey(const std::filesystem::path& path,
                               const std::string& key,
                               std::vector<int64_t>& result) {
    using namespace gin_index_format;
    std::ifstream in(path, std::ios::binary);
    if (!in) return false;
    in.seekg(0, std::ios::end);
    const std::streamoff streamBytes = in.tellg();
    if (streamBytes < 0) return false;
    const uint64_t fileBytes = static_cast<uint64_t>(streamBytes);
    in.clear();
    in.seekg(0, std::ios::beg);

    std::array<char, kMagic.size()> probe{};
    const size_t probeBytes = static_cast<size_t>(
        std::min<uint64_t>(fileBytes, probe.size()));
    if (probeBytes != 0) {
        in.read(probe.data(), static_cast<std::streamsize>(probeBytes));
        if (in.gcount() != static_cast<std::streamsize>(probeBytes))
            return false;
    }
    if (containsBinaryMarker(probe.data(), probeBytes)) {
        if (probeBytes != kMagic.size() ||
            !std::equal(probe.begin(), probe.end(), kMagic.begin()) ||
            fileBytes < kHeaderBytes + kChecksumBytes) {
            return false;
        }

        const uint64_t payloadBytes = fileBytes - kChecksumBytes;
        std::array<char, kChecksumBytes> checksumBytes{};
        in.clear();
        in.seekg(static_cast<std::streamoff>(payloadBytes), std::ios::beg);
        in.read(checksumBytes.data(), checksumBytes.size());
        if (in.gcount() != static_cast<std::streamsize>(checksumBytes.size()))
            return false;
        const uint32_t storedChecksum = decodeU32(checksumBytes.data());

        in.clear();
        in.seekg(0, std::ios::beg);
        uint64_t remainingForChecksum = payloadBytes;
        uint32_t checksumState = 0xFFFFFFFFu;
        std::array<char, 64 * 1024> checksumChunk{};
        while (remainingForChecksum > 0) {
            const size_t amount = static_cast<size_t>(
                std::min<uint64_t>(remainingForChecksum,
                                   checksumChunk.size()));
            in.read(checksumChunk.data(), static_cast<std::streamsize>(amount));
            if (in.gcount() != static_cast<std::streamsize>(amount))
                return false;
            checksumState = index_checksum::crc32cUpdate(
                checksumState, checksumChunk.data(), amount);
            remainingForChecksum -= amount;
        }
        if (index_checksum::crc32cFinish(checksumState) != storedChecksum)
            return false;

        uint64_t consumed = 0;
        const auto readPayload = [&](char* destination, uint64_t length) {
            if (length > payloadBytes - consumed ||
                length > static_cast<uint64_t>(
                    std::numeric_limits<std::streamsize>::max())) {
                return false;
            }
            if (length != 0) {
                in.read(destination, static_cast<std::streamsize>(length));
                if (in.gcount() != static_cast<std::streamsize>(length))
                    return false;
            }
            consumed += length;
            return true;
        };
        const auto skipPayload = [&](uint64_t length) {
            if (length > payloadBytes - consumed ||
                length > static_cast<uint64_t>(
                    std::numeric_limits<std::streamoff>::max())) {
                return false;
            }
            in.seekg(static_cast<std::streamoff>(length), std::ios::cur);
            if (!in) return false;
            consumed += length;
            return true;
        };
        const auto readU32 = [&](uint32_t& value) {
            std::array<char, sizeof(uint32_t)> bytes{};
            if (!readPayload(bytes.data(), bytes.size())) return false;
            value = decodeU32(bytes.data());
            return true;
        };
        const auto readU64 = [&](uint64_t& value) {
            std::array<char, sizeof(uint64_t)> bytes{};
            if (!readPayload(bytes.data(), bytes.size())) return false;
            value = decodeU64(bytes.data());
            return true;
        };

        in.clear();
        in.seekg(0, std::ios::beg);
        std::array<char, kMagic.size()> magic{};
        uint32_t version = 0;
        uint64_t entryCount = 0;
        if (!readPayload(magic.data(), magic.size()) || magic != kMagic ||
            !readU32(version) || version != kVersion ||
            !readU64(entryCount) ||
            entryCount > (payloadBytes - consumed) / kMinimumEntryBytes) {
            return false;
        }

        bool matched = false;
        for (uint64_t entry = 0; entry < entryCount; ++entry) {
            uint64_t keyLength = 0;
            if (!readU64(keyLength) || keyLength == 0 ||
                keyLength > payloadBytes - consumed) {
                return false;
            }

            bool keyMatches = keyLength == key.size();
            if (keyMatches) {
                std::array<char, 4096> keyChunk{};
                size_t keyOffset = 0;
                uint64_t remaining = keyLength;
                bool equal = true;
                while (remaining > 0) {
                    const size_t amount = static_cast<size_t>(
                        std::min<uint64_t>(remaining, keyChunk.size()));
                    if (!readPayload(keyChunk.data(), amount)) return false;
                    if (std::memcmp(keyChunk.data(), key.data() + keyOffset,
                                    amount) != 0) equal = false;
                    remaining -= amount;
                    keyOffset += amount;
                }
                keyMatches = equal;
            } else if (!skipPayload(keyLength)) {
                return false;
            }

            uint64_t ridCount = 0;
            if (!readU64(ridCount) || ridCount == 0 ||
                ridCount > (payloadBytes - consumed) / sizeof(uint64_t) ||
                (keyMatches && matched)) {
                return false;
            }
            if (keyMatches) {
                matched = true;
                if (ridCount > result.max_size()) return false;
                result.reserve(static_cast<size_t>(ridCount));
            }
            for (uint64_t ridIndex = 0; ridIndex < ridCount; ++ridIndex) {
                if (keyMatches) {
                    uint64_t rid = 0;
                    if (!readU64(rid) ||
                        rid > static_cast<uint64_t>(
                            std::numeric_limits<int64_t>::max())) {
                        return false;
                    }
                    result.push_back(static_cast<int64_t>(rid));
                } else if (!skipPayload(sizeof(uint64_t))) {
                    return false;
                }
            }
        }
        return consumed == payloadBytes;
    }

    // V1 GIN sidecars are whitespace-delimited text. Keep them readable for
    // compatibility; keys containing whitespace were not representable.
    in.clear();
    in.seekg(0, std::ios::beg);
    std::string line;
    while (std::getline(in, line)) {
        if (line.empty()) return false;
        const size_t separator = line.find(' ');
        const std::string token = separator == std::string::npos
            ? line : line.substr(0, separator);
        if (token.empty() || separator == std::string::npos) return false;
        std::stringstream values(line.substr(separator + 1));
        std::vector<int64_t> parsed;
        int64_t rid = 0;
        while (values >> rid) parsed.push_back(rid);
        if (!values.eof()) return false;
        if (token == key) {
            result = std::move(parsed);
            break;
        }
    }
    return !in.bad();
}

std::vector<int64_t> StorageEngine::ginSearch(const std::string& dbname,
                                               const std::string& tablename,
                                               const std::string& colname,
                                               const std::string& key) const {
    std::vector<int64_t> result;
    auto path = ginIndexPath(dbname, tablename, colname);
    std::error_code pathError;
    if (!std::filesystem::is_regular_file(path, pathError) || pathError)
        return result;
    if (specializedIndexesNeedHeapFallback(dbname, tablename)) {
        const TableSchema table = getTableSchema(dbname, tablename);
        size_t columnIndex = table.len;
        for (size_t i = 0; i < table.len; ++i) {
            if (table.cols[i].dataName == colname) {
                columnIndex = i;
                break;
            }
        }
        if (columnIndex >= table.len) return result;
        const bool scanned = forEachRow(
            dbname, tablename,
            [&](uint32_t pageId, uint16_t slotId,
                const char* data, size_t length) {
                const std::string value =
                    const_cast<StorageEngine*>(this)->extractColumnValue(
                        std::string(data, length), table, columnIndex,
                        dbname, true);
                const auto keys = extractGinKeys(
                    value, table.cols[columnIndex].dataType);
                if (std::find(keys.begin(), keys.end(), key) != keys.end()) {
                    result.push_back(encodeRid(pageId, slotId));
                }
            });
        if (!scanned) result.clear();
        return result;
    }
    if (!readGinIndexForKey(path, key, result)) return {};
    return result;
}

std::vector<std::string> StorageEngine::getGinIndexedColumns(const std::string& dbname,
                                                              const std::string& tablename) const {
    std::vector<std::string> result;
    auto dir = relationDir(dbname, tablename);
    if (!std::filesystem::exists(dir)) return result;
    std::string prefix = tablename + "_";
    for (const auto& entry : std::filesystem::directory_iterator(dir)) {
        if (!entry.is_regular_file()) continue;
        std::string name = entry.path().filename().string();
        if (name.size() > 4 && name.substr(name.size() - 4) == ".gin" &&
            name.substr(0, prefix.size()) == prefix) {
            std::string colname = name.substr(prefix.size(), name.size() - prefix.size() - 4);
            result.push_back(colname);
        }
    }
    return result;
}

// ========================================================================
// GiST index (Generalized Search Tree) - simplified range/spatial index
// ========================================================================

std::filesystem::path StorageEngine::giSTIndexPath(const std::string& dbname,
                                                   const std::string& tablename,
                                                   const std::string& colname) const {
    return relationDir(dbname, tablename) / (tablename + "_" + colname + ".gist");
}

std::filesystem::path StorageEngine::spGiSTIndexPath(const std::string& dbname,
                                                     const std::string& tablename,
                                                     const std::string& colname) const {
    return relationDir(dbname, tablename) / (tablename + "_" + colname + ".spgist");
}

DBStatus StorageEngine::createGiSTIndex(const std::string& dbname,
                                         const std::string& tablename,
                                         const std::string& colname) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t colIdx = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
    }
    if (colIdx >= tbl.len) return DBStatus::INVALID_VALUE;

    auto path = giSTIndexPath(dbname, tablename, colname);
    std::string entryPayload;
    uint64_t entryCount = 0;

    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId,
                                       const char* data, size_t len) {
        std::string row(data, len);
        std::string val = extractColumnValue(
            row, tbl, colIdx, dbname, true);
        int64_t rid = encodeRid(pageId, slotId);
        // For GiST we store each row's value range.
        // For single scalar values, min=max=val.
        // For multi-value (array), min=min element, max=max element.
        // For text, we store the value itself (prefix containment).
        if (!val.empty()) {
            gist_index_format::appendEntryPayload(
                entryPayload, static_cast<uint64_t>(rid), val, val);
            ++entryCount;
        }
    })) return DBStatus::IO_ERROR;
    if (!index_file::writeAtomically(
            path, gist_index_format::encodeV2(entryCount, entryPayload))) {
        return DBStatus::IO_ERROR;
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::dropGiSTIndex(const std::string& dbname,
                                       const std::string& tablename,
                                       const std::string& colname) {
    auto path = giSTIndexPath(dbname, tablename, colname);
    if (std::filesystem::exists(path)) std::filesystem::remove(path);
    return DBStatus::OK;
}

bool StorageEngine::hasGiSTIndex(const std::string& dbname,
                                  const std::string& tablename,
                                  const std::string& colname) const {
    return std::filesystem::exists(giSTIndexPath(dbname, tablename, colname));
}

enum class GistKeyOrdering { Text, ExactNumeric, FloatingPoint };

static GistKeyOrdering gistKeyOrdering(const Column& column) {
    std::string typeName = column.dataType;
    std::transform(typeName.begin(), typeName.end(), typeName.begin(),
                   [](unsigned char c) {
                       return static_cast<char>(std::tolower(c));
                   });
    if (typeName == "float" || typeName == "float4" ||
        typeName == "real" || typeName == "double" ||
        typeName == "float8" || typeName == "double precision") {
        return GistKeyOrdering::FloatingPoint;
    }
    if (typeName == "tinyint" || typeName == "smallint" ||
        typeName == "int" || typeName == "integer" ||
        typeName == "bigint" || typeName == "int2" ||
        typeName == "int4" || typeName == "int8" ||
        typeName == "numeric" || typeName == "decimal" ||
        typeName == "smallserial" || typeName == "serial" ||
        typeName == "bigserial" ||
        typeName.find(" unsigned") != std::string::npos) {
        return GistKeyOrdering::ExactNumeric;
    }
    const TypeEntry* type =
        TypeRegistry::instance().findType(column.dataType);
    if (!type || type->category != TypeCategory::Numeric) {
        return GistKeyOrdering::Text;
    }
    return type->canonicalName == "real" ||
                   type->canonicalName == "double precision"
        ? GistKeyOrdering::FloatingPoint
        : GistKeyOrdering::ExactNumeric;
}

static bool gistCompare(GistKeyOrdering ordering, const std::string& left,
                        const std::string& right, int& comparison) {
    if (ordering == GistKeyOrdering::Text) {
        comparison = left < right ? -1 : (left > right ? 1 : 0);
        return true;
    }
    if (ordering == GistKeyOrdering::FloatingPoint) {
        double lhs = 0.0;
        double rhs = 0.0;
        if (!parseFiniteDouble(left, lhs) ||
            !parseFiniteDouble(right, rhs)) {
            return false;
        }
        comparison = lhs < rhs ? -1 : (lhs > rhs ? 1 : 0);
        return true;
    }
    if (trim(left).empty() || trim(right).empty()) return false;
    try {
        const Numeric lhs(left);
        const Numeric rhs(right);
        if (!lhs.isFinite() || !rhs.isFinite()) return false;
        comparison = lhs < rhs ? -1 : (lhs > rhs ? 1 : 0);
        return true;
    } catch (...) {
        return false;
    }
}

static bool gistHighIsUnbounded(const std::string& high) {
    // GiSTScanOp uses a lone DEL byte as +infinity. A DEL suffix on a longer
    // text key is handled separately as a prefix ceiling.
    return high.empty() || high == "\x7f";
}

static bool gistValueExceedsHigh(GistKeyOrdering ordering,
                                 const std::string& value,
                                 const std::string& high) {
    if (gistHighIsUnbounded(high)) return false;
    if (ordering == GistKeyOrdering::Text && high.back() == '\x7f') {
        // prefix + DEL is the planner's inclusive prefix ceiling. UTF-8
        // continuation bytes can sort above ASCII DEL, so a raw string
        // comparison would incorrectly discard valid non-ASCII suffixes.
        const std::string prefix = high.substr(0, high.size() - 1);
        if (value.compare(0, prefix.size(), prefix) == 0) return false;
        int comparison = 0;
        return gistCompare(ordering, value, prefix, comparison) &&
               comparison > 0;
    }
    int comparison = 0;
    return gistCompare(ordering, value, high, comparison) &&
           comparison > 0;
}

static bool gistQueryRangeIsValid(GistKeyOrdering ordering,
                                  const std::string& low,
                                  const std::string& high) {
    const bool hasLow = !low.empty();
    const bool hasHigh = !gistHighIsUnbounded(high);
    int comparison = 0;
    if (hasLow && !gistCompare(ordering, low, low, comparison)) return false;
    const bool prefixHigh = ordering == GistKeyOrdering::Text &&
                            hasHigh && high.back() == '\x7f';
    if (hasHigh && !prefixHigh &&
        !gistCompare(ordering, high, high, comparison)) {
        return false;
    }
    return !hasLow || !hasHigh ||
           !gistValueExceedsHigh(ordering, low, high);
}

static bool gistEntryRangeIsValid(GistKeyOrdering ordering,
                                  const std::string& entryLow,
                                  const std::string& entryHigh) {
    if (entryLow.empty() || entryHigh.empty()) return false;
    int comparison = 0;
    return gistCompare(ordering, entryLow, entryHigh, comparison) &&
           comparison <= 0;
}

template <typename Visitor>
static bool forEachGiSTEntry(
    const std::filesystem::path& path, GistKeyOrdering ordering,
    Visitor&& visit) {
    using namespace gist_index_format;
    std::ifstream input(path, std::ios::binary);
    if (!input) return false;

    auto readExactly = [&](char* destination, size_t bytes) {
        if (bytes > static_cast<size_t>(
                        std::numeric_limits<std::streamsize>::max())) {
            return false;
        }
        input.read(destination, static_cast<std::streamsize>(bytes));
        return static_cast<size_t>(input.gcount()) == bytes;
    };

    std::array<char, kMagic.size()> probe{};
    input.read(probe.data(), static_cast<std::streamsize>(probe.size()));
    const size_t probed = static_cast<size_t>(input.gcount());
    const bool checksummed = probed == probe.size() &&
        std::equal(probe.begin(), probe.end(), kMagic.begin());

    std::unordered_set<int64_t> seenRids;
    if (checksummed) {
        std::array<char, sizeof(uint32_t) + sizeof(uint64_t)> header{};
        if (!readExactly(header.data(), header.size())) return false;
        size_t headerOffset = 0;
        uint32_t version = 0;
        uint64_t entryCount = 0;
        if (!readU32(std::string_view(header.data(), header.size()),
                     headerOffset, version) ||
            version != kVersion ||
            !readU64(std::string_view(header.data(), header.size()),
                     headerOffset, entryCount)) {
            return false;
        }

        input.clear();
        input.seekg(0, std::ios::end);
        const std::streampos end = input.tellg();
        if (end < 0) return false;
        const auto signedBytes = static_cast<std::streamoff>(end);
        if (signedBytes < 0) return false;
        const uint64_t fileBytes = static_cast<uint64_t>(signedBytes);
        if (fileBytes < kHeaderBytes + kChecksumBytes) return false;
        const uint64_t payloadBytes = fileBytes - kChecksumBytes;
        if (entryCount > (payloadBytes - kHeaderBytes) /
                             kMinimumEntryBytes) {
            return false;
        }

        std::array<char, kChecksumBytes> checksumBytes{};
        input.seekg(static_cast<std::streamoff>(payloadBytes), std::ios::beg);
        if (!input || !readExactly(checksumBytes.data(),
                                   checksumBytes.size())) {
            return false;
        }
        size_t checksumOffset = 0;
        uint32_t storedChecksum = 0;
        if (!readU32(std::string_view(checksumBytes.data(),
                                      checksumBytes.size()),
                     checksumOffset, storedChecksum)) {
            return false;
        }

        input.clear();
        input.seekg(0, std::ios::beg);
        if (!input) return false;
        uint64_t remainingForChecksum = payloadBytes;
        uint32_t checksumState = 0xFFFFFFFFu;
        std::array<char, 64 * 1024> chunk{};
        while (remainingForChecksum > 0) {
            const size_t amount = static_cast<size_t>(
                std::min<uint64_t>(remainingForChecksum, chunk.size()));
            if (!readExactly(chunk.data(), amount)) return false;
            checksumState = index_checksum::crc32cUpdate(
                checksumState, chunk.data(), amount);
            remainingForChecksum -= amount;
        }
        if (index_checksum::crc32cFinish(checksumState) != storedChecksum)
            return false;

        input.clear();
        input.seekg(static_cast<std::streamoff>(kHeaderBytes), std::ios::beg);
        if (!input) return false;
        uint64_t remaining = payloadBytes - kHeaderBytes;
        for (uint64_t i = 0; i < entryCount; ++i) {
            if (remaining < kMinimumEntryBytes) return false;
            std::array<char, kMinimumEntryBytes> fixed{};
            if (!readExactly(fixed.data(), fixed.size())) return false;
            size_t fixedOffset = 0;
            uint64_t rid = 0;
            uint64_t lowLength = 0;
            uint64_t highLength = 0;
            const std::string_view fixedView(fixed.data(), fixed.size());
            if (!readU64(fixedView, fixedOffset, rid) ||
                !readU64(fixedView, fixedOffset, lowLength) ||
                !readU64(fixedView, fixedOffset, highLength) ||
                rid == 0 || rid > static_cast<uint64_t>(INT64_MAX) ||
                lowLength > std::numeric_limits<size_t>::max() ||
                highLength > std::numeric_limits<size_t>::max()) {
                return false;
            }
            remaining -= kMinimumEntryBytes;
            if (lowLength > remaining ||
                highLength > remaining - lowLength) {
                return false;
            }
            std::string entryLow;
            std::string entryHigh;
            try {
                entryLow.resize(static_cast<size_t>(lowLength));
                entryHigh.resize(static_cast<size_t>(highLength));
            } catch (...) {
                return false;
            }
            if ((!entryLow.empty() &&
                 !readExactly(entryLow.data(), entryLow.size())) ||
                (!entryHigh.empty() &&
                 !readExactly(entryHigh.data(), entryHigh.size()))) {
                return false;
            }
            remaining -= lowLength + highLength;
            const int64_t signedRid = static_cast<int64_t>(rid);
            if (!seenRids.insert(signedRid).second ||
                !gistEntryRangeIsValid(ordering, entryLow, entryHigh)) {
                return false;
            }
            visit(signedRid, entryLow, entryHigh);
        }
        return remaining == 0;
    }

    input.clear();
    input.seekg(0, std::ios::beg);
    if (!input) return false;
    std::string line;
    while (std::getline(input, line)) {
        std::stringstream parser(line);
        int64_t rid = -1;
        std::string entryLow;
        std::string entryHigh;
        if (!(parser >> rid >> std::quoted(entryLow) >>
              std::quoted(entryHigh))) {
            return false;
        }
        parser >> std::ws;
        if (!parser.eof() || rid <= 0 || !seenRids.insert(rid).second ||
            !gistEntryRangeIsValid(ordering, entryLow, entryHigh)) {
            return false;
        }
        visit(rid, entryLow, entryHigh);
    }
    return input.eof() && !input.bad();
}

static bool gistEntryOverlaps(GistKeyOrdering ordering,
                              const std::string& low,
                              const std::string& high,
                              const std::string& entryLow,
                              const std::string& entryHigh) {
    int comparison = 0;
    if (!low.empty() &&
        (!gistCompare(ordering, entryHigh, low, comparison) ||
         comparison < 0)) {
        return false;
    }
    if (gistValueExceedsHigh(ordering, entryLow, high)) {
        return false;
    }
    return true;
}

static bool gistEntryContained(GistKeyOrdering ordering,
                               const std::string& low,
                               const std::string& high,
                               const std::string& entryLow,
                               const std::string& entryHigh) {
    int comparison = 0;
    if (!low.empty() &&
        (!gistCompare(ordering, low, entryLow, comparison) ||
         comparison > 0)) {
        return false;
    }
    if (gistValueExceedsHigh(ordering, entryHigh, high)) {
        return false;
    }
    return true;
}

std::vector<int64_t> StorageEngine::giSTSearchOverlap(const std::string& dbname,
                                                       const std::string& tablename,
                                                       const std::string& colname,
                                                       const std::string& low,
                                                       const std::string& high) const {
    std::vector<int64_t> result;
    const TableSchema table = getTableSchema(dbname, tablename);
    size_t columnIndex = table.len;
    for (size_t i = 0; i < table.len; ++i) {
        if (table.cols[i].dataName == colname) {
            columnIndex = i;
            break;
        }
    }
    if (columnIndex >= table.len) return result;
    const GistKeyOrdering ordering =
        gistKeyOrdering(table.cols[columnIndex]);
    if (!gistQueryRangeIsValid(ordering, low, high)) return result;

    const auto scanHeap = [&]() -> std::vector<int64_t> {
        result.clear();
        bool valuesValid = true;
        const bool scanned = forEachRow(
            dbname, tablename,
            [&](uint32_t pageId, uint16_t slotId,
                const char* data, size_t length) {
                if (!valuesValid) return;
                const std::string value =
                    const_cast<StorageEngine*>(this)->extractColumnValue(
                        std::string(data, length), table, columnIndex,
                        dbname, true);
                if (value.empty()) return;
                if (!gistEntryRangeIsValid(ordering, value, value)) {
                    valuesValid = false;
                    return;
                }
                if (gistEntryOverlaps(
                        ordering, low, high, value, value)) {
                    result.push_back(encodeRid(pageId, slotId));
                }
            });
        if (!scanned || !valuesValid) result.clear();
        return result;
    };

    auto path = giSTIndexPath(dbname, tablename, colname);
    std::error_code pathError;
    const bool isIndexFile =
        std::filesystem::is_regular_file(path, pathError);
    if (specializedIndexesNeedHeapFallback(dbname, tablename)) {
        return scanHeap();
    }
    if (pathError) return scanHeap();
    if (!isIndexFile) return result;
    const bool valid = forEachGiSTEntry(
        path, ordering,
        [&](int64_t rid, const std::string& entryLow,
            const std::string& entryHigh) {
            // Overlap: entry range [entryLow, entryHigh] intersects
            // [low, high].
            if (gistEntryOverlaps(
                    ordering, low, high, entryLow, entryHigh)) {
                result.push_back(rid);
            }
        });
    if (!valid) return scanHeap();
    return result;
}

std::vector<int64_t> StorageEngine::giSTSearchContainedBy(const std::string& dbname,
                                                           const std::string& tablename,
                                                           const std::string& colname,
                                                           const std::string& low,
                                                           const std::string& high) const {
    std::vector<int64_t> result;
    const TableSchema table = getTableSchema(dbname, tablename);
    size_t columnIndex = table.len;
    for (size_t i = 0; i < table.len; ++i) {
        if (table.cols[i].dataName == colname) {
            columnIndex = i;
            break;
        }
    }
    if (columnIndex >= table.len) return result;
    const GistKeyOrdering ordering =
        gistKeyOrdering(table.cols[columnIndex]);
    if (!gistQueryRangeIsValid(ordering, low, high)) return result;

    const auto scanHeap = [&]() -> std::vector<int64_t> {
        result.clear();
        bool valuesValid = true;
        const bool scanned = forEachRow(
            dbname, tablename,
            [&](uint32_t pageId, uint16_t slotId,
                const char* data, size_t length) {
                if (!valuesValid) return;
                const std::string value =
                    const_cast<StorageEngine*>(this)->extractColumnValue(
                        std::string(data, length), table, columnIndex,
                        dbname, true);
                if (value.empty()) return;
                if (!gistEntryRangeIsValid(ordering, value, value)) {
                    valuesValid = false;
                    return;
                }
                if (gistEntryContained(
                        ordering, low, high, value, value)) {
                    result.push_back(encodeRid(pageId, slotId));
                }
            });
        if (!scanned || !valuesValid) result.clear();
        return result;
    };

    auto path = giSTIndexPath(dbname, tablename, colname);
    std::error_code pathError;
    const bool isIndexFile =
        std::filesystem::is_regular_file(path, pathError);
    if (specializedIndexesNeedHeapFallback(dbname, tablename)) {
        return scanHeap();
    }
    if (pathError) return scanHeap();
    if (!isIndexFile) return result;
    const bool valid = forEachGiSTEntry(
        path, ordering,
        [&](int64_t rid, const std::string& entryLow,
            const std::string& entryHigh) {
            // Contained by: entry range is fully within [low, high].
            if (gistEntryContained(
                    ordering, low, high, entryLow, entryHigh)) {
                result.push_back(rid);
            }
        });
    if (!valid) return scanHeap();
    return result;
}

std::vector<std::string> StorageEngine::getGiSTIndexedColumns(const std::string& dbname,
                                                               const std::string& tablename) const {
    std::vector<std::string> result;
    auto dir = relationDir(dbname, tablename);
    if (!std::filesystem::exists(dir)) return result;
    std::string prefix = tablename + "_";
    for (const auto& entry : std::filesystem::directory_iterator(dir)) {
        if (!entry.is_regular_file()) continue;
        std::string name = entry.path().filename().string();
        if (name.size() > 5 && name.substr(name.size() - 5) == ".gist" &&
            name.substr(0, prefix.size()) == prefix) {
            std::string colname = name.substr(prefix.size(), name.size() - prefix.size() - 5);
            result.push_back(colname);
        }
    }
    return result;
}

// ========================================================================
// SP-GiST index (Space-Partitioned GiST) - quadtree for POINT type
// ========================================================================

DBStatus StorageEngine::createSPGiSTIndex(const std::string& dbname,
                                           const std::string& tablename,
                                           const std::string& colname) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t colIdx = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
    }
    if (colIdx >= tbl.len || tbl.cols[colIdx].dataType != "point")
        return DBStatus::INVALID_VALUE;

    auto path = spGiSTIndexPath(dbname, tablename, colname);
    std::string entryPayload;
    uint64_t entryCount = 0;
    bool valuesValid = true;

    if (!forEachRow(dbname, tablename, [&](uint32_t pageId, uint16_t slotId,
                                       const char* data, size_t len) {
        std::string row(data, len);
        std::string val = extractColumnValue(
            row, tbl, colIdx, dbname, true);
        if (val.empty()) return;
        double x = 0.0;
        double y = 0.0;
        std::string canonical;
        if (!normalizePointLiteral(val, canonical, &x, &y)) {
            valuesValid = false;
            return;
        }
        spgist_index_format::appendEntryPayload(
            entryPayload, static_cast<uint64_t>(encodeRid(pageId, slotId)),
            x, y);
        ++entryCount;
    })) return DBStatus::IO_ERROR;
    if (!valuesValid) return DBStatus::INVALID_VALUE;
    if (!index_file::writeAtomically(
            path,
            spgist_index_format::encodeV2(entryCount, entryPayload))) {
        return DBStatus::IO_ERROR;
    }
    {
        std::lock_guard<std::mutex> lock(spGiSTMutex_);
        spGiSTCache_.erase(dbname + "/" + tablename + "/" + colname);
    }
    return DBStatus::OK;
}

DBStatus StorageEngine::dropSPGiSTIndex(const std::string& dbname,
                                         const std::string& tablename,
                                         const std::string& colname) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    auto path = spGiSTIndexPath(dbname, tablename, colname);
    if (std::filesystem::exists(path)) std::filesystem::remove(path);
    spGiSTCache_.erase(dbname + "/" + tablename + "/" + colname);
    return DBStatus::OK;
}

bool StorageEngine::hasSPGiSTIndex(const std::string& dbname,
                                    const std::string& tablename,
                                    const std::string& colname) const {
    return std::filesystem::exists(spGiSTIndexPath(dbname, tablename, colname));
}

template <typename Visitor>
static bool forEachSPGiSTPoint(
    const std::filesystem::path& path, Visitor&& visit) {
    using namespace spgist_index_format;
    std::ifstream input(path, std::ios::binary);
    if (!input) return false;

    auto readExactly = [&](char* destination, size_t bytes) {
        if (bytes > static_cast<size_t>(
                        std::numeric_limits<std::streamsize>::max())) {
            return false;
        }
        input.read(destination, static_cast<std::streamsize>(bytes));
        return static_cast<size_t>(input.gcount()) == bytes;
    };

    std::array<char, kMagic.size()> probe{};
    input.read(probe.data(), static_cast<std::streamsize>(probe.size()));
    const size_t probed = static_cast<size_t>(input.gcount());
    const bool checksummed = probed == probe.size() &&
        std::equal(probe.begin(), probe.end(), kMagic.begin());

    std::unordered_set<int64_t> seenRids;
    if (checksummed) {
        std::array<char, sizeof(uint32_t) + sizeof(uint64_t)> header{};
        if (!readExactly(header.data(), header.size())) return false;
        const std::string_view headerView(header.data(), header.size());
        size_t headerOffset = 0;
        uint32_t version = 0;
        uint64_t entryCount = 0;
        if (!readU32(headerView, headerOffset, version) ||
            version != kVersion ||
            !readU64(headerView, headerOffset, entryCount)) {
            return false;
        }

        input.clear();
        input.seekg(0, std::ios::end);
        const std::streampos end = input.tellg();
        if (end < 0) return false;
        const auto signedBytes = static_cast<std::streamoff>(end);
        if (signedBytes < 0) return false;
        const uint64_t fileBytes = static_cast<uint64_t>(signedBytes);
        if (fileBytes < kHeaderBytes + kChecksumBytes) return false;
        const uint64_t payloadBytes = fileBytes - kChecksumBytes;
        const uint64_t entryPayloadBytes = payloadBytes - kHeaderBytes;
        if (entryPayloadBytes % kEntryBytes != 0 ||
            entryCount != entryPayloadBytes / kEntryBytes) {
            return false;
        }

        std::array<char, kChecksumBytes> checksumBytes{};
        input.seekg(static_cast<std::streamoff>(payloadBytes), std::ios::beg);
        if (!input || !readExactly(checksumBytes.data(),
                                   checksumBytes.size())) {
            return false;
        }
        size_t checksumOffset = 0;
        uint32_t storedChecksum = 0;
        if (!readU32(std::string_view(checksumBytes.data(),
                                      checksumBytes.size()),
                     checksumOffset, storedChecksum)) {
            return false;
        }

        input.clear();
        input.seekg(0, std::ios::beg);
        if (!input) return false;
        uint64_t remainingForChecksum = payloadBytes;
        uint32_t checksumState = 0xFFFFFFFFu;
        std::array<char, 64 * 1024> chunk{};
        while (remainingForChecksum > 0) {
            const size_t amount = static_cast<size_t>(
                std::min<uint64_t>(remainingForChecksum, chunk.size()));
            if (!readExactly(chunk.data(), amount)) return false;
            checksumState = index_checksum::crc32cUpdate(
                checksumState, chunk.data(), amount);
            remainingForChecksum -= amount;
        }
        if (index_checksum::crc32cFinish(checksumState) != storedChecksum)
            return false;

        input.clear();
        input.seekg(static_cast<std::streamoff>(kHeaderBytes), std::ios::beg);
        if (!input) return false;
        for (uint64_t i = 0; i < entryCount; ++i) {
            std::array<char, kEntryBytes> fixed{};
            if (!readExactly(fixed.data(), fixed.size())) return false;
            const std::string_view fixedView(fixed.data(), fixed.size());
            size_t fixedOffset = 0;
            uint64_t rid = 0;
            uint64_t xBits = 0;
            uint64_t yBits = 0;
            if (!readU64(fixedView, fixedOffset, rid) ||
                !readU64(fixedView, fixedOffset, xBits) ||
                !readU64(fixedView, fixedOffset, yBits) ||
                rid == 0 || rid > static_cast<uint64_t>(
                    std::numeric_limits<int64_t>::max())) {
                return false;
            }
            const int64_t signedRid = static_cast<int64_t>(rid);
            const double x = bitsDouble(xBits);
            const double y = bitsDouble(yBits);
            if (!seenRids.insert(signedRid).second ||
                !std::isfinite(x) || !std::isfinite(y)) {
                return false;
            }
            visit(signedRid, x, y);
        }
        return true;
    }

    input.clear();
    input.seekg(0, std::ios::beg);
    if (!input) return false;
    std::string line;
    while (std::getline(input, line)) {
        std::stringstream parser(line);
        int64_t rid = 0;
        std::string point;
        if (!(parser >> rid >> point)) return false;
        parser >> std::ws;
        if (!parser.eof() || rid <= 0 || !seenRids.insert(rid).second)
            return false;
        double x = 0.0;
        double y = 0.0;
        std::string canonical;
        if (!normalizePointLiteral(point, canonical, &x, &y)) return false;
        visit(rid, x, y);
    }
    return input.eof() && !input.bad();
}

std::vector<int64_t> StorageEngine::spGiSTSearch(const std::string& dbname,
                                                  const std::string& tablename,
                                                  const std::string& colname,
                                                  const std::string& op,
                                                  const std::string& value) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::vector<int64_t> result;
    auto path = spGiSTIndexPath(dbname, tablename, colname);
    std::error_code pathError;
    if (!std::filesystem::is_regular_file(path, pathError) || pathError)
        return result;

    const auto searchIndex = [&](SPGiSTIndex& index) {
        // Parse value as "x,y" for point, or "x" / "y" for directional
        // queries.
        if (op == "=") {
            double qx = 0.0, qy = 0.0;
            std::string canonical;
            if (normalizePointLiteral(value, canonical, &qx, &qy))
                result = index.searchEquals(qx, qy);
        } else if (op == "<<") {
            double x = 0.0;
            if (parseFiniteDouble(value, x)) result = index.searchLeftOf(x);
        } else if (op == ">>") {
            double x = 0.0;
            if (parseFiniteDouble(value, x)) result = index.searchRightOf(x);
        } else if (op == "<^") {
            double y = 0.0;
            if (parseFiniteDouble(value, y)) result = index.searchBelow(y);
        } else if (op == ">^") {
            double y = 0.0;
            if (parseFiniteDouble(value, y)) result = index.searchAbove(y);
        } else if (op == "<@") {
            // Contained within circle: "cx,cy,radius".
            double cx = 0.0, cy = 0.0, radius = 0.0;
            const size_t comma1 = value.find(',');
            const size_t comma2 = value.find(
                ',', comma1 == std::string::npos ? 0 : comma1 + 1);
            if (comma1 != std::string::npos &&
                comma2 != std::string::npos &&
                value.find(',', comma2 + 1) == std::string::npos &&
                parseFiniteDouble(value.substr(0, comma1), cx) &&
                parseFiniteDouble(
                    value.substr(comma1 + 1, comma2 - comma1 - 1), cy) &&
                parseFiniteDouble(value.substr(comma2 + 1), radius) &&
                radius >= 0.0) {
                result = index.searchWithin(cx, cy, radius);
            }
        }
    };

    const auto scanHeap = [&]() {
        const TableSchema table = getTableSchema(dbname, tablename);
        size_t columnIndex = table.len;
        for (size_t i = 0; i < table.len; ++i) {
            if (table.cols[i].dataName == colname) {
                columnIndex = i;
                break;
            }
        }
        if (columnIndex >= table.len ||
            table.cols[columnIndex].dataType != "point") return result;
        SPGiSTIndex heapIndex(-1e9, -1e9, 1e9, 1e9);
        bool valid = true;
        const bool scanned = forEachRow(
            dbname, tablename,
            [&](uint32_t pageId, uint16_t slotId,
                const char* data, size_t length) {
                if (!valid) return;
                const std::string point =
                    const_cast<StorageEngine*>(this)->extractColumnValue(
                        std::string(data, length), table, columnIndex,
                        dbname, true);
                if (point.empty()) return;
                double x = 0.0, y = 0.0;
                std::string canonical;
                if (!normalizePointLiteral(point, canonical, &x, &y)) {
                    valid = false;
                    return;
                }
                heapIndex.insert(x, y, encodeRid(pageId, slotId));
            });
        if (!scanned || !valid) return result;
        searchIndex(heapIndex);
        return result;
    };

    if (specializedIndexesNeedHeapFallback(dbname, tablename))
        return scanHeap();

    // Build or retrieve cached quadtree
    std::string cacheKey = dbname + "/" + tablename + "/" + colname;
    SPGiSTIndex* idx = nullptr;
    {
        std::lock_guard<std::mutex> lock(spGiSTMutex_);
        auto it = spGiSTCache_.find(cacheKey);
        if (it != spGiSTCache_.end()) {
            idx = it->second.get();
        } else {
            auto newIdx = std::make_unique<SPGiSTIndex>(-1e9, -1e9, 1e9, 1e9);
            const bool valid = forEachSPGiSTPoint(
                path, [&](int64_t rid, double x, double y) {
                    newIdx->insert(x, y, rid);
                });
            if (!valid) return scanHeap();
            idx = newIdx.get();
            spGiSTCache_[cacheKey] = std::move(newIdx);
        }
    }

    if (!idx) return result;

    searchIndex(*idx);
    return result;
}

std::vector<std::string> StorageEngine::getSPGiSTIndexedColumns(const std::string& dbname,
                                                                 const std::string& tablename) const {
    std::vector<std::string> result;
    auto dir = relationDir(dbname, tablename);
    if (!std::filesystem::exists(dir)) return result;
    std::string prefix = tablename + "_";
    const std::string suffix = ".spgist";
    for (const auto& entry : std::filesystem::directory_iterator(dir)) {
        if (!entry.is_regular_file()) continue;
        std::string name = entry.path().filename().string();
        if (name.size() > prefix.size() + suffix.size() &&
            name.compare(name.size() - suffix.size(), suffix.size(), suffix) == 0 &&
            name.substr(0, prefix.size()) == prefix) {
            std::string colname = name.substr(
                prefix.size(), name.size() - prefix.size() - suffix.size());
            result.push_back(colname);
        }
    }
    return result;
}

// ========================================================================
// BRIN index (Block Range Index) - per-block min/max summary
// ========================================================================

namespace {
constexpr uint32_t STORAGE_BRIN_MAGIC = brin_index_format::kMagic;

struct StorageBrinRange {
    uint32_t pageStart = 0;
    uint32_t pageEnd = 0;
    std::string minValue;
    std::string maxValue;
};

template <typename T>
bool readStorageBrinBytes(const std::string& data, size_t& offset, T& value) {
    if (offset > data.size() || data.size() - offset < sizeof(T)) return false;
    std::memcpy(&value, data.data() + offset, sizeof(T));
    offset += sizeof(T);
    return true;
}

bool readLegacyStorageBrinString(const std::string& data, size_t& offset,
                                 std::string& value) {
    uint64_t length = 0;
    if (!readStorageBrinBytes(data, offset, length) || length > data.size() - offset)
        return false;
    value.assign(data.data() + offset, static_cast<size_t>(length));
    offset += static_cast<size_t>(length);
    return true;
}
}

std::filesystem::path StorageEngine::brinIndexPath(const std::string& dbname,
                                                   const std::string& tablename,
                                                   const std::string& colname) const {
    return relationDir(dbname, tablename) / (tablename + "_" + colname + ".brin");
}

DBStatus StorageEngine::createBrinIndex(const std::string& dbname,
                                         const std::string& tablename,
                                         const std::string& colname,
                                         size_t pagesPerRange) {
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;
    if (pagesPerRange == 0) pagesPerRange = 64;
    if (pagesPerRange > std::numeric_limits<uint32_t>::max()) return DBStatus::INVALID_VALUE;
    TableSchema tbl = getTableSchema(dbname, tablename);
    size_t colIdx = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == colname) { colIdx = i; break; }
    }
    if (colIdx >= tbl.len) return DBStatus::INVALID_VALUE;

    auto path = brinIndexPath(dbname, tablename, colname);
    std::vector<StorageBrinRange> ranges;
    const uint32_t rangeWidth = static_cast<uint32_t>(pagesPerRange);

    ReadView autocommitView;
    const ReadView* indexReadView = nullptr;
    if (transactionContext().inTransaction &&
        transactionContext().txnDB == dbname) {
        indexReadView = &transactionContext().readView;
    } else {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        autocommitView.creatorTxnId = 0;
        autocommitView.lowLimitId =
            TxnIdGenerator::instance().maxCommittedTxId() + 1;
        autocommitView.upLimitId = activeTransactions().empty()
            ? autocommitView.lowLimitId : *activeTransactions().begin();
        autocommitView.activeTxnIds = activeTransactions();
        autocommitView.subTxnIds.clear();
        autocommitView.commitLog = getCommitLog(dbname);
        indexReadView = &autocommitView;
    }

    auto scanAllocator = [&](PageAllocator& allocator, const TableSchema& t) -> bool {
        const uint32_t np = allocator.numPages();
        for (uint64_t start = 1; start < np; start += rangeWidth) {
            const uint32_t blockStart = static_cast<uint32_t>(start);
            const uint32_t blockEnd = static_cast<uint32_t>(std::min<uint64_t>(
                start + rangeWidth - 1, static_cast<uint64_t>(np - 1)));
            bool hasValue = false;
            std::string rangeMin;
            std::string rangeMax;
            for (uint32_t pid = blockStart; pid <= blockEnd; ++pid) {
                char* buf = allocator.fetchPage(pid);
                if (!buf) return false;
                PageWrapper page(buf, allocator.pageSize(), t.formatVersion);
                page.forEachLive([&](uint16_t, const char* data, size_t len) {
                    if (usesHeapTupleHeader(t.formatVersion) &&
                        indexReadView &&
                        !indexReadView->isVisible(
                            data, len, t.formatVersion)) {
                        return;
                    }
                    if (len < rowHeaderSize(t.formatVersion, t.len)) return;
                    std::string row = stripRowHeader(data, len, t.formatVersion, t.len);
                    if (row.empty()) return;
                    std::string val = extractColumnValue(
                        row, t, colIdx, dbname, true);
                    if (!hasValue) {
                        rangeMin = rangeMax = std::move(val);
                        hasValue = true;
                    } else {
                        if (val < rangeMin) rangeMin = val;
                        if (val > rangeMax) rangeMax = val;
                    }
                });
                allocator.unpinPage(pid);
                if (pid == blockEnd) break;
            }
            if (hasValue) ranges.push_back({blockStart, blockEnd,
                                             std::move(rangeMin), std::move(rangeMax)});
        }
        return true;
    };

    // If table is partitioned, scan partition files; otherwise scan main data file
    auto scanTable = [&](const std::string& actualTableName) -> bool {
        TableSchema t = getTableSchema(dbname, actualTableName);
        if (t.partitionType != TableSchema::PartitionType::None) {
            std::vector<std::string> partNames;
            if (t.partitionType == TableSchema::PartitionType::Range) {
                for (const auto& rp : t.rangePartitions) partNames.push_back(rp.first);
            } else if (t.partitionType == TableSchema::PartitionType::List) {
                for (const auto& lp : t.listPartitions) partNames.push_back(lp.first);
            } else if (t.partitionType == TableSchema::PartitionType::Hash) {
                for (size_t i = 0; i < t.hashPartitions; ++i) partNames.push_back("p" + std::to_string(i));
            }
            for (const auto& pname : partNames) {
                auto ppa = acquireSharedHeap(
                    dbname, partitionDataPath(dbname, actualTableName, pname), t.rowSize(), pageSizeForFormatVersion(t.formatVersion), t.formatVersion,
                    dbname + "/" + actualTableName + "#" + pname);
                if (!ppa || !scanAllocator(*ppa, t)) return false;
            }
        } else {
            // Use the shared allocator so CREATE INDEX observes dirty heap
            // pages that have not reached the relation file yet.
            PageAllocator* pa = getPageAllocator(dbname, actualTableName);
            if (!pa || !scanAllocator(*pa, t)) return false;
        }
        return true;
    };

    if (!scanTable(tablename)) return DBStatus::IO_ERROR;
    std::string bytes;
    using namespace brin_index_format;
    appendU32(bytes, STORAGE_BRIN_MAGIC);
    appendU32(bytes, kChecksumVersion);
    const uint64_t rangeCount = ranges.size();
    appendU64(bytes, rangeCount);
    for (const auto& range : ranges) {
        appendU32(bytes, range.pageStart);
        appendU32(bytes, range.pageEnd);
        appendU64(bytes, range.minValue.size());
        bytes.append(range.minValue);
        appendU64(bytes, range.maxValue.size());
        bytes.append(range.maxValue);
    }
    appendU32(bytes, index_checksum::crc32c(bytes.data(), bytes.size()));
    if (!index_file::writeAtomically(path, bytes)) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

DBStatus StorageEngine::dropBrinIndex(const std::string& dbname,
                                       const std::string& tablename,
                                       const std::string& colname) {
    auto path = brinIndexPath(dbname, tablename, colname);
    std::error_code ec;
    if (std::filesystem::exists(path, ec) && !std::filesystem::remove(path, ec)) {
        return DBStatus::IO_ERROR;
    }
    if (ec) return DBStatus::IO_ERROR;
    return DBStatus::OK;
}

bool StorageEngine::hasBrinIndex(const std::string& dbname,
                                  const std::string& tablename,
                                  const std::string& colname) const {
    return std::filesystem::exists(brinIndexPath(dbname, tablename, colname));
}

std::vector<std::pair<uint32_t, uint32_t>> StorageEngine::brinSearchRange(
    const std::string& dbname, const std::string& tablename, const std::string& colname,
    const std::string& op, const std::string& value) const {
    std::vector<std::pair<uint32_t, uint32_t>> result;
    auto path = brinIndexPath(dbname, tablename, colname);
    std::error_code pathError;
    if (!std::filesystem::is_regular_file(path, pathError) || pathError)
        return result;
    if (specializedIndexesNeedHeapFallback(dbname, tablename)) {
        const TableSchema table = getTableSchema(dbname, tablename);
        size_t columnIndex = table.len;
        for (size_t i = 0; i < table.len; ++i) {
            if (table.cols[i].dataName == colname) {
                columnIndex = i;
                break;
            }
        }
        if (columnIndex >= table.len) return result;
        std::set<uint32_t> matchingPages;
        const bool scanned = forEachRow(
            dbname, tablename,
            [&](uint32_t pageId, uint16_t, const char* data, size_t length) {
                const std::string row(data, length);
                const std::string candidate =
                    const_cast<StorageEngine*>(this)->extractColumnValue(
                    row, table, columnIndex, dbname, true);
                bool matches = false;
                if (op == "=") matches = candidate == value;
                else if (op == "<") matches = candidate < value;
                else if (op == "<=") matches = candidate <= value;
                else if (op == ">") matches = candidate > value;
                else if (op == ">=") matches = candidate >= value;
                if (matches) matchingPages.insert(pageId);
            });
        if (!scanned || matchingPages.empty()) return result;
        uint32_t rangeStart = *matchingPages.begin();
        uint32_t rangeEnd = rangeStart;
        for (auto it = std::next(matchingPages.begin());
             it != matchingPages.end(); ++it) {
            if (*it == rangeEnd + 1) {
                rangeEnd = *it;
            } else {
                result.push_back({rangeStart, rangeEnd});
                rangeStart = rangeEnd = *it;
            }
        }
        result.push_back({rangeStart, rangeEnd});
        return result;
    }
    std::ifstream in(path, std::ios::binary);
    if (!in) return result;
    const std::string data((std::istreambuf_iterator<char>(in)),
                           std::istreambuf_iterator<char>());
    if (in.bad()) return {};
    using namespace brin_index_format;
    size_t headerOffset = 0;
    uint32_t littleEndianMagic = 0;
    uint32_t littleEndianVersion = 0;
    const bool hasLittleEndianHeader =
        readU32(data, headerOffset, littleEndianMagic) &&
        readU32(data, headerOffset, littleEndianVersion) &&
        littleEndianMagic == kMagic;
    if (hasLittleEndianHeader &&
        littleEndianVersion == kChecksumVersion) {
        if (data.size() < sizeof(uint32_t) * 2 + sizeof(uint64_t) +
                              kChecksumBytes) return {};
        const size_t payloadBytes = data.size() - kChecksumBytes;
        size_t checksumOffset = payloadBytes;
        uint32_t storedChecksum = 0;
        if (!readU32(data, checksumOffset, storedChecksum) ||
            checksumOffset != data.size() ||
            index_checksum::crc32c(data.data(), payloadBytes) !=
                storedChecksum) {
            return {};
        }

        const std::string_view payload(data.data(), payloadBytes);
        size_t offset = 0;
        uint32_t magic = 0;
        uint32_t version = 0;
        uint64_t rangeCount = 0;
        constexpr uint64_t minimumRangeBytes =
            sizeof(uint32_t) * 2 + sizeof(uint64_t) * 2;
        if (!readU32(payload, offset, magic) ||
            !readU32(payload, offset, version) ||
            !readU64(payload, offset, rangeCount) || magic != kMagic ||
            version != kChecksumVersion ||
            rangeCount > (payloadBytes - offset) / minimumRangeBytes) {
            return {};
        }
        for (uint64_t i = 0; i < rangeCount; ++i) {
            uint32_t pstart = 0;
            uint32_t pend = 0;
            std::string rangeMin;
            std::string rangeMax;
            if (!readU32(payload, offset, pstart) ||
                !readU32(payload, offset, pend) ||
                !readString(payload, offset, rangeMin) ||
                !readString(payload, offset, rangeMax) ||
                pstart == 0 || pend < pstart) return {};
            bool mayMatch = false;
            if (op == "=") {
                mayMatch = (rangeMin <= value && value <= rangeMax);
            } else if (op == "<") {
                mayMatch = (rangeMin < value);
            } else if (op == "<=") {
                mayMatch = (rangeMin <= value);
            } else if (op == ">") {
                mayMatch = (rangeMax > value);
            } else if (op == ">=") {
                mayMatch = (rangeMax >= value);
            }
            if (mayMatch) result.push_back({pstart, pend});
        }
        if (offset != payload.size()) return {};
        return result;
    }

    // V1 used native byte order and has no checksum.
    size_t offset = 0;
    uint32_t magic = 0;
    uint32_t version = 0;
    uint64_t rangeCount = 0;
    if (!readStorageBrinBytes(data, offset, magic) ||
        !readStorageBrinBytes(data, offset, version) ||
        !readStorageBrinBytes(data, offset, rangeCount) ||
        magic != STORAGE_BRIN_MAGIC || version != kLegacyVersion ||
        rangeCount > data.size() / 24) return {};
    for (uint64_t i = 0; i < rangeCount; ++i) {
        uint32_t pstart = 0;
        uint32_t pend = 0;
        std::string rangeMin;
        std::string rangeMax;
        if (!readStorageBrinBytes(data, offset, pstart) ||
            !readStorageBrinBytes(data, offset, pend) ||
            !readLegacyStorageBrinString(data, offset, rangeMin) ||
            !readLegacyStorageBrinString(data, offset, rangeMax) ||
            pstart == 0 || pend < pstart) return {};
        bool mayMatch = false;
        if (op == "=") {
            mayMatch = (rangeMin <= value && value <= rangeMax);
        } else if (op == "<") {
            mayMatch = (rangeMin < value);
        } else if (op == "<=") {
            mayMatch = (rangeMin <= value);
        } else if (op == ">") {
            mayMatch = (rangeMax > value);
        } else if (op == ">=") {
            mayMatch = (rangeMax >= value);
        }
        if (mayMatch) result.push_back({pstart, pend});
    }
    if (offset != data.size()) return {};
    return result;
}

std::vector<std::string> StorageEngine::getBrinIndexedColumns(const std::string& dbname,
                                                               const std::string& tablename) const {
    std::vector<std::string> result;
    auto dir = relationDir(dbname, tablename);
    if (!std::filesystem::exists(dir)) return result;
    std::string prefix = tablename + "_";
    for (const auto& entry : std::filesystem::directory_iterator(dir)) {
        if (!entry.is_regular_file()) continue;
        std::string name = entry.path().filename().string();
        if (name.size() > 5 && name.substr(name.size() - 5) == ".brin" &&
            name.substr(0, prefix.size()) == prefix) {
            std::string colname = name.substr(prefix.size(), name.size() - prefix.size() - 5);
            result.push_back(colname);
        }
    }
    return result;
}

bool StorageEngine::rebuildSpecializedIndexes(
    const std::string& dbname, const std::string& tablename,
    bool clearDirtyState) {
    lockManager_.setResourceNamespace(dbname);
    if (!lockManager_.lockIntentExclusive(tablename)) return false;
    const auto finish = [&](bool result) {
        lockManager_.unlock(tablename);
        return result;
    };

    try {
        if (!tableExists(dbname, tablename)) return finish(false);
        // These simplified access methods use their sidecar filename as the
        // durable definition. Capture all names before replacing any file.
        const auto fullTextColumns =
            getFullTextIndexedColumns(dbname, tablename);
        const auto ginColumns = getGinIndexedColumns(dbname, tablename);
        const auto gistColumns = getGiSTIndexedColumns(dbname, tablename);
        const auto spgistColumns =
            getSPGiSTIndexedColumns(dbname, tablename);
        const auto brinColumns = getBrinIndexedColumns(dbname, tablename);
        if (fullTextColumns.empty() && ginColumns.empty() &&
            gistColumns.empty() && spgistColumns.empty() &&
            brinColumns.empty()) {
            return finish(!clearDirtyState || clearSpecializedIndexDirty(
                *this, dbname, tablename));
        }

        // Publish invalidity before replacing the first sidecar. Readers use
        // snapshot-aware heap candidates while this file exists instead of
        // trusting a mixed generation.
        if (!index_file::writeAtomically(
                specializedIndexDirtyPath(*this, dbname, tablename),
                "DBMS_SPECIALIZED_INDEX_DIRTY_V1\n")) {
            return finish(false);
        }

        bool rebuilt = true;
        for (const auto& column : fullTextColumns) {
            if (createFullTextIndex(dbname, tablename, column) !=
                DBStatus::OK) {
                rebuilt = false;
                break;
            }
        }
        for (const auto& column : ginColumns) {
            if (rebuilt && createGinIndex(dbname, tablename, column) !=
                               DBStatus::OK) {
                rebuilt = false;
            }
        }
        for (const auto& column : gistColumns) {
            if (rebuilt && createGiSTIndex(dbname, tablename, column) !=
                               DBStatus::OK) {
                rebuilt = false;
            }
        }
        for (const auto& column : spgistColumns) {
            if (rebuilt && createSPGiSTIndex(dbname, tablename, column) !=
                               DBStatus::OK) {
                rebuilt = false;
            }
        }
        for (const auto& column : brinColumns) {
            if (rebuilt && createBrinIndex(
                               dbname, tablename, column, 64) !=
                               DBStatus::OK) {
                rebuilt = false;
            }
        }
        if (!rebuilt) return finish(false);
        return finish(!clearDirtyState || clearSpecializedIndexDirty(
            *this, dbname, tablename));
    } catch (const std::exception& error) {
        std::cerr << "[index] specialized index rebuild failed for "
                  << dbname << "/" << tablename << ": "
                  << error.what() << std::endl;
        return finish(false);
    } catch (...) {
        std::cerr << "[index] specialized index rebuild failed for "
                  << dbname << "/" << tablename << std::endl;
        return finish(false);
    }
}

bool StorageEngine::rebuildAllSpecializedIndexes(
    const std::string& dbname) {
    try {
        for (const auto& tableName : getTableNames(dbname)) {
            // Session temporary relations are discarded by startup cleanup
            // after WAL recovery. Their catalog name can outlive an
            // interrupted CREATE before the schema marker is complete, so
            // there is no valid table schema from which to rebuild an index.
            if (isSessionTempPhysicalName(tableName)) continue;
            if (!rebuildSpecializedIndexes(dbname, tableName)) return false;
        }
        return true;
    } catch (...) {
        return false;
    }
}

bool StorageEngine::markSpecializedIndexesBeforeMutation(
    const std::string& dbname, const std::string& tablename) {
    try {
        const auto dirtyPath =
            specializedIndexDirtyPath(*this, dbname, tablename);
        std::error_code error;
        const bool alreadyDirty = std::filesystem::exists(dirtyPath, error);
        if (error) return false;

        bool hasSpecializedIndex = alreadyDirty;
        if (!hasSpecializedIndex) {
            hasSpecializedIndex =
                !getFullTextIndexedColumns(dbname, tablename).empty() ||
                !getGinIndexedColumns(dbname, tablename).empty() ||
                !getGiSTIndexedColumns(dbname, tablename).empty() ||
                !getSPGiSTIndexedColumns(dbname, tablename).empty() ||
                !getBrinIndexedColumns(dbname, tablename).empty();
        }
        if (!hasSpecializedIndex) return true;

        if (transactionContext().inTransaction &&
            transactionContext().txnDB == dbname) {
            transactionContext().specializedIndexTables.insert(tablename);
        }
        if (alreadyDirty) return true;

        // This durable marker is the cross-backend publication barrier. It
        // must reach disk before the heap changes, otherwise another process
        // could trust a stale sidecar during the subsequent rebuild window.
        return index_file::writeAtomically(
            dirtyPath, "DBMS_SPECIALIZED_INDEX_DIRTY_V1\n");
    } catch (const std::exception& error) {
        std::cerr << "[index] could not mark specialized indexes dirty for "
                  << dbname << "/" << tablename << ": "
                  << error.what() << std::endl;
        return false;
    } catch (...) {
        return false;
    }
}

bool StorageEngine::maintainSpecializedIndexesAfterMutation(
    const std::string& dbname, const std::string& tablename) {
    if (transactionContext().inTransaction &&
        transactionContext().txnDB == dbname) {
        transactionContext().specializedIndexTables.insert(tablename);
        return true;
    }
    return rebuildSpecializedIndexes(dbname, tablename);
}

static bool pathEntryExists(const std::filesystem::path& path,
                            std::error_code& ec) {
    const auto status = std::filesystem::symlink_status(path, ec);
    if (ec == std::errc::no_such_file_or_directory) {
        ec.clear();
        return false;
    }
    return !ec && status.type() != std::filesystem::file_type::not_found;
}

bool StorageEngine::databaseExists(const std::string& dbname) const {
    if (dbname.empty() || !validStoredIdentifier(dbname, MAX_TABLE_NAME_LEN)) return false;
    // Existence is a name-generation check, not table/catalog access. In
    // particular, checking a deferred transaction must not promote it.
    const auto path = std::filesystem::path(dbname);
    std::error_code ec;
    if (std::filesystem::is_symlink(path, ec) || ec ||
        !std::filesystem::is_directory(path, ec) || ec) {
        return false;
    }
    const auto list = path / "tlist.lst";
    if (std::filesystem::is_symlink(list, ec) || ec ||
        !std::filesystem::is_regular_file(list, ec) || ec) {
        return false;
    }
    return !std::filesystem::exists(path / kPhysicalBackupMarker, ec) && !ec;
}

std::vector<std::string> StorageEngine::getDatabaseNames() const {
    std::vector<std::string> result;
    if (!std::filesystem::exists(".") || !std::filesystem::is_directory(".")) return result;
    for (const auto& entry : std::filesystem::directory_iterator(".", std::filesystem::directory_options::skip_permission_denied)) {
        try {
            if (!entry.is_directory()) continue;
        } catch (...) { continue; }
        std::string dbname;
        try { dbname = entry.path().filename().string(); } catch (...) { continue; }
        // Physical snapshots carry a backup marker; WAL archives have no
        // table list. Name substrings alone also reject valid quoted names.
        if (!databaseExists(dbname)) continue;
        result.push_back(dbname);
    }
    return result;
}

bool StorageEngine::tableExists(const std::string& dbname,
                                 const std::string& tablename) const {
    if (dbname.empty() || !validStoredIdentifier(dbname, MAX_TABLE_NAME_LEN) ||
        tablename.empty() || !validStoredRelationName(tablename)) {
        return false;
    }
    lockManager_.setResourceNamespace(dbname);
    return std::filesystem::exists(schemaPath(dbname, tablename));
}

DBStatus StorageEngine::createDatabase(const std::string& dbname, const std::string& charset) {
    if (dbname.empty() || !validStoredIdentifier(dbname, MAX_TABLE_NAME_LEN)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    std::string normalizedCharset;
    normalizedCharset.reserve(charset.size());
    for (unsigned char c : charset) {
        if (std::isalnum(c)) {
            normalizedCharset += static_cast<char>(std::tolower(c));
        }
    }
    if (normalizedCharset != "utf8" && normalizedCharset != "unicode") {
        return DBStatus::INVALID_VALUE;
    }
    // An already-existing name is a duplicate even if its current users
    // hold shared transaction locks. Recheck after taking the name lock to
    // close the concurrent CREATE/DROP race for absent names.
    std::error_code collisionEc;
    if (pathEntryExists(dbPath(dbname), collisionEc)) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    if (collisionEc) return DBStatus::IO_ERROR;
    const auto databaseMutex = databaseTxnLockFor(dbname);
    std::unique_lock<std::shared_mutex> databaseLock(
        *databaseMutex, std::try_to_lock);
    if (!databaseLock.owns_lock()) return DBStatus::DATABASE_IN_USE;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    collisionEc.clear();
    if (pathEntryExists(dbPath(dbname), collisionEc)) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    if (collisionEc) return DBStatus::IO_ERROR;
    // Embedded callers and tests may remove a database directory directly.
    // Drop every file-backed cache before reusing the name; otherwise the
    // background WAL writer keeps stale descriptors and the new database can
    // inherit in-memory pages from its predecessor.
    pruneMissingDatabaseCaches();
    if (catalogService_) catalogService_->evict(dbname);
    resetRuntimeDatabaseStats(dbname);
    resetSqlDatabaseStats(dbname);
    std::error_code ec;
    if (!std::filesystem::create_directory(dbPath(dbname), ec) || ec) {
        return DBStatus::IO_ERROR;
    }
    const auto databasePath = dbPath(dbname);
    const auto databaseParent = databasePath.parent_path().empty()
        ? std::filesystem::path(".") : databasePath.parent_path();
    auto failCreateDatabase = [&]() {
        std::error_code cleanupEc;
        std::filesystem::remove_all(databasePath, cleanupEc);
        if (!cleanupEc) (void)index_file::syncDirectory(databaseParent);
        return DBStatus::IO_ERROR;
    };
    if (!index_file::writeAtomically(tableListPath(dbname), "") ||
        !index_file::writeAtomically(dbPath(dbname) / ".charset", "utf8\n")) {
        return failCreateDatabase();
    }
    // Every database has the PostgreSQL-compatible public schema. Persist it
    // as a normal schema marker so schema validation is consistent for DDL,
    // default privileges, and future catalog-backed namespace operations.
    if (!index_file::writeAtomically(dbPath(dbname) / ".schema_public", "")) {
        return failCreateDatabase();
    }
    // The creating engine is already running.  Publishing this state with
    // the database makes a process death before normal destruction visible
    // even when the database has never emitted a WAL record.
    if (!writeUnloggedLifecycle(
            dbPath(dbname), kUnloggedLifecycleRunning)) {
        return failCreateDatabase();
    }
    // The per-file writes synced entries inside the database directory, but
    // the database directory itself was created in its parent. Persist that
    // final namespace link before reporting CREATE DATABASE success.
    if (!index_file::syncDirectory(databaseParent)) {
        return failCreateDatabase();
    }
    return DBStatus::OK;
}

std::string StorageEngine::getDatabaseCharset(const std::string& dbname) const {
    auto cpath = dbPath(dbname) / ".charset";
    if (!std::filesystem::exists(cpath)) return "utf8";
    std::ifstream f(cpath);
    std::string cs;
    if (f >> cs) return cs;
    return "utf8";
}

DBStatus StorageEngine::dropDatabase(const std::string& dbname) {
    if (dbname.empty() || !validStoredIdentifier(dbname, MAX_TABLE_NAME_LEN)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    const auto& context = transactionContext();
    if (context.inTransaction && context.txnDB == dbname) {
        return DBStatus::DATABASE_IN_USE;
    }
    const auto activeUserTransaction = [&] {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        for (const auto& [xid, database] : activeTransactionDatabases()) {
            (void)xid;
            if (database == dbname) return true;
        }
        return false;
    };
    if (activeUserTransaction()) return DBStatus::DATABASE_IN_USE;
    auto maintenance = maintenanceStateFor(dbname);
    {
        std::unique_lock<std::mutex> lock(maintenance->mutex);
        if (maintenance->running != MaintenanceKind::None &&
            maintenance->owner == std::this_thread::get_id()) return DBStatus::DATABASE_IN_USE;
        while (maintenance->running != MaintenanceKind::None) {
            maintenance->finished.wait_for(lock, std::chrono::milliseconds(20));
            // BEGIN may hold globalTxnMutex while acquiring cacheMutex_.
            // The writer completing this maintenance pass can hold the
            // cache lock, so release the coordinator before inspecting xids.
            lock.unlock();
            checkForQueryInterrupt();
            const bool active = activeUserTransaction();
            lock.lock();
            if (active) return DBStatus::DATABASE_IN_USE;
        }
        maintenance->running = MaintenanceKind::Drop;
        maintenance->owner = std::this_thread::get_id();
    }
    // Background writeback/vacuum is not a live application session. Wait
    // for that bounded ownership and reserve the name against the next pass
    // while keeping the existing refusal for user/physical transaction locks.
    MaintenanceCompletion completion{maintenance, MaintenanceKind::Drop, this};
    // BEGIN holds this mutex until commit/rollback completes. Take it before
    // cacheMutex_ so DROP cannot remove files under an active transaction or
    // race with a newly starting one. A busy database is not dropped.
    const auto databaseMutex = databaseTxnLockFor(dbname);
    std::unique_lock<std::shared_mutex> databaseLock(
        *databaseMutex, std::try_to_lock);
    if (!databaseLock.owns_lock()) return DBStatus::DATABASE_IN_USE;
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;

    // Release database-owned caches before removing the directory. This
    // prevents a later same-name database from inheriting stale CLOG/WAL or
    // page/index objects, and lets file-backed destructors flush while their
    // directory still exists.
    if (catalogService_) catalogService_->evict(dbname);
    closeDatabaseCaches(dbname);
    resetRuntimeDatabaseStats(dbname);
    resetSqlDatabaseStats(dbname);
    bool cleanupOk = true;
    const auto removeStatFile = [&](const std::filesystem::path& path) {
        std::error_code ec;
        std::filesystem::remove(path, ec);
        if (ec) cleanupOk = false;
    };
    removeStatFile(dbPath(dbname) / ".runtime_stats");
    removeStatFile(dbPath(dbname) / ".runtime_stats.lock");
    removeStatFile(dbPath(dbname) / ".sql_stats");
    removeStatFile(dbPath(dbname) / ".sql_stats.lock");
    std::error_code removeEc;
    std::filesystem::remove_all(dbPath(dbname), removeEc);
    if (!cleanupOk || removeEc) return DBStatus::IO_ERROR;
    const auto databaseParent = dbPath(dbname).parent_path().empty()
        ? std::filesystem::path(".") : dbPath(dbname).parent_path();
    // Removing the database directory changes its parent, not just the
    // contents that remove_all traversed. Do not report durable DROP success
    // until the cluster directory records the removal.
    return index_file::syncDirectory(databaseParent)
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::renameDatabase(const std::string& oldName,
                                       const std::string& newName) {
    if (oldName.empty() || newName.empty() ||
        !validStoredIdentifier(oldName, MAX_TABLE_NAME_LEN) ||
        !validStoredIdentifier(newName, MAX_TABLE_NAME_LEN)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    if (oldName == newName) return DBStatus::TABLE_ALREADY_EXISTS;
    const auto& context = transactionContext();
    if (context.inTransaction &&
        (context.txnDB == oldName || context.txnDB == newName)) {
        return DBStatus::DATABASE_IN_USE;
    }
    const auto ownershipStatus = ensureDatabaseTransactionOwnership();
    if (ownershipStatus != DBStatus::OK) return ownershipStatus;

    // Rename owns both names. Acquire them in a stable order before the
    // cache lock so CREATE/DROP/BEGIN cannot observe a half-moved database.
    const auto first = databaseTxnLockFor(std::min(oldName, newName));
    const auto second = databaseTxnLockFor(std::max(oldName, newName));
    std::unique_lock<std::shared_mutex> firstLock(*first, std::try_to_lock);
    if (!firstLock.owns_lock()) return DBStatus::DATABASE_IN_USE;
    std::unique_lock<std::shared_mutex> secondLock(*second, std::defer_lock);
    if (first != second && !secondLock.try_lock()) return DBStatus::DATABASE_IN_USE;
    const auto oldNameMutex = oldName < newName ? first : second;
    auto& oldNameLock = first == second || oldName < newName ? firstLock : secondLock;
    PhysicalCatalogOwnership catalogOwnership(
        transactionContext(), oldNameMutex, oldNameLock);
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(oldName)) return DBStatus::DATABASE_NOT_FOUND;
    std::error_code targetEc;
    if (pathEntryExists(dbPath(newName), targetEc)) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    if (targetEc) return DBStatus::IO_ERROR;
    const auto oldArchive = std::filesystem::path(
        dbPath(oldName).string() + ".archive");
    const auto newArchive = std::filesystem::path(
        dbPath(newName).string() + ".archive");
    targetEc.clear();
    const bool archiveExists = pathEntryExists(oldArchive, targetEc);
    if (targetEc) return DBStatus::IO_ERROR;
    // The target archive name is reserved even if the source has no archive.
    // Otherwise the renamed database silently inherits unrelated WAL files.
    targetEc.clear();
    if (pathEntryExists(newArchive, targetEc)) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    if (targetEc) return DBStatus::IO_ERROR;
    if (catalogService_ && !catalogService_->persistAll()) {
        return DBStatus::IO_ERROR;
    }
    if (!flushDatabaseCaches(oldName)) return DBStatus::IO_ERROR;
    if (catalogService_) {
        catalogService_->evict(oldName);
        catalogService_->evict(newName);
    }
    closeDatabaseCaches(oldName);
    closeDatabaseCaches(newName);
    resetRuntimeDatabaseStats(oldName);
    resetSqlDatabaseStats(oldName);

    std::error_code ec;
    const auto databaseParent = dbPath(oldName).parent_path().empty()
        ? std::filesystem::path(".") : dbPath(oldName).parent_path();
    if (archiveExists) {
        std::filesystem::rename(oldArchive, newArchive, ec);
        if (ec) return DBStatus::IO_ERROR;
    }
    std::filesystem::rename(dbPath(oldName), dbPath(newName), ec);
    if (ec) {
        if (archiveExists) {
            std::error_code rollbackEc;
            std::filesystem::rename(newArchive, oldArchive, rollbackEc);
        }
        (void)index_file::syncDirectory(databaseParent);
        return DBStatus::IO_ERROR;
    }
    if (!index_file::syncDirectory(databaseParent)) {
        // Both names moved but publication was not confirmed durable. Restore
        // the original database/archive names and persist that rollback.
        std::error_code rollbackDatabaseEc;
        std::filesystem::rename(dbPath(newName), dbPath(oldName),
                                rollbackDatabaseEc);
        if (archiveExists) {
            std::error_code rollbackArchiveEc;
            std::filesystem::rename(newArchive, oldArchive,
                                    rollbackArchiveEc);
        }
        (void)index_file::syncDirectory(databaseParent);
        return DBStatus::IO_ERROR;
    }
    return DBStatus::OK;
}

constexpr int32_t SCHEMA_FORMAT_VERSION = 0x44420009;  // "DB" + 64-byte identifier fields
constexpr int32_t SCHEMA_PHYSICAL_ID_FORMAT_VERSION = 0x4442000A;
constexpr int32_t SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION = 0x4442000B;
constexpr int32_t SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION = 0x4442000C;
constexpr int32_t SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION = 0x4442000D;
// E widens only persisted FK relation identities, never SQL identifier fields.
constexpr int32_t SCHEMA_LONG_RELATION_FORMAT_VERSION = 0x4442000E;
constexpr uint32_t SCHEMA_TEMPORAL_CODEC_MAGIC = 0x314D4354; // "TCM1"
constexpr uint32_t SCHEMA_COLUMN_TYPEMOD_MAGIC = 0x314D5449; // "ITM1"
constexpr uint32_t SCHEMA_PHYSICAL_ID_MAGIC = 0x31444952;  // "RID1"
constexpr uint32_t SCHEMA_DEFAULT_ORIGIN_MAGIC = 0x314F5344; // "DSO1"
constexpr int32_t MAX_PERSISTED_COLUMN_SIZE = 65535;
constexpr uint32_t SCHEMA_ADDITIONAL_CHECK_MAGIC = 0x324B4843;  // "CHK2"
constexpr uint32_t SCHEMA_IDENTITY_KIND_MAGIC = 0x314E4449;     // "IDN1"
constexpr uint32_t SCHEMA_LONG_DEFAULT_MAGIC = 0x31544644;      // "DFT1"
constexpr uint32_t SCHEMA_RANGE_LOWER_BOUNDS_MAGIC = 0x31424C52;  // "RLB1"
constexpr int32_t MAX_ADDITIONAL_CHECK_CONSTRAINTS = 1024;
constexpr uint32_t MAX_PERSISTED_CHECK_EXPRESSION = 1024 * 1024;
constexpr uint32_t MAX_PERSISTED_DEFAULT_EXPRESSION = 1024 * 1024;
// Physical restore uses the retained transaction layout while its directory
// generation changes. Logical defaults are not inputs to that byte operation.
static thread_local const StorageEngine* physicalSchemaReader = nullptr;

static bool isValidTemporalColumnModifier(const Column& column) {
    std::string type = column.dataType;
    if (type.size() >= 2 && type.compare(type.size() - 2, 2, "[]") == 0)
        type.resize(type.size() - 2);
    return (type == "time" || type == "timetz" || type == "timestamp" ||
            type == "timestamptz") && column.typeMod >= 0 && column.typeMod <= 6;
}

static bool isValidColumnStorageCodec(const Column& column) {
    if (column.storageCodec == Column::StorageCodec::Legacy) return true;
    return column.storageCodec == Column::StorageCodec::TemporalMicros &&
        !column.isArray && !column.isVariableLength && !column.isUnsigned &&
        column.dsize == sizeof(int64_t) &&
        (column.dataType == "time" || column.dataType == "timestamp" ||
         column.dataType == "timestamptz" || column.dataType == "datetime");
}

void StorageEngine::writeSchema(std::ostream& out, const TableSchema& tbl) {
    if (tbl.len > MAX_COLUMNS) {
        out.setstate(std::ios::failbit);
        return;
    }
    if (tbl.rangePartitions.size() > MAX_COLUMNS) {
        out.setstate(std::ios::failbit);
        return;
    }
    if (!tbl.rangePartitionLowerBounds.empty() &&
        tbl.rangePartitionLowerBounds.size() != tbl.rangePartitions.size()) {
        out.setstate(std::ios::failbit);
        return;
    }
    for (size_t index = 0; index < tbl.rangePartitions.size(); ++index) {
        const std::string inferredLower = index == 0
            ? "MINVALUE" : tbl.rangePartitions[index - 1].second;
        const std::string& lower = tbl.rangePartitionLowerBounds.empty()
            ? inferredLower : tbl.rangePartitionLowerBounds[index];
        if (lower.empty() || lower.size() > MAX_COL_NAME_LEN ||
            lower.find('\0') != std::string::npos ||
            comparePartitionValues(
                tbl, lower, tbl.rangePartitions[index].second, true, true) >= 0 ||
            (index > 0 && comparePartitionValues(
                tbl, lower, tbl.rangePartitions[index - 1].second,
                true, true) < 0)) {
            out.setstate(std::ios::failbit);
            return;
        }
    }
    for (size_t i = 0; i < tbl.len; ++i) {
        const auto& expression = tbl.cols[i].defaultValue;
        if (expression.size() > MAX_PERSISTED_DEFAULT_EXPRESSION ||
            expression.find('\0') != std::string::npos) {
            out.setstate(std::ios::failbit);
            return;
        }
    }
    bool longReferences = false;
    for (size_t i = 0; i < tbl.fkLen; ++i) {
        if (!validStoredRelationName(tbl.fks[i].refTable)) {
            out.setstate(std::ios::failbit); return;
        }
        longReferences = longReferences || tbl.fks[i].refTable.size() >= MAX_TABLE_NAME_LEN;
    }
    bool hasDefaultOrigins = false;
    bool hasColumnTypeMods = false;
    bool hasTemporalCodecs = false;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (!isValidColumnStorageCodec(tbl.cols[i])) {
            out.setstate(std::ios::failbit); return;
        }
        hasTemporalCodecs = hasTemporalCodecs ||
            tbl.cols[i].storageCodec != Column::StorageCodec::Legacy;
        if (tbl.cols[i].typeMod != -1) {
            try {
                if (tbl.cols[i].dataType == "interval") (void)interval_type_detail::unpack(tbl.cols[i].typeMod);
                else if (tbl.cols[i].dataType == "numeric") (void)numeric_type_detail::unpack(tbl.cols[i].typeMod);
                else if (!isValidTemporalColumnModifier(tbl.cols[i])) { out.setstate(std::ios::failbit); return; }
            }
            catch (const DbError&) { out.setstate(std::ios::failbit); return; }
            hasColumnTypeMods = true;
        }
        const auto origin = tbl.cols[i].defaultOrigin;
        if (origin != Column::DefaultOrigin::LegacyFrozen && origin != Column::DefaultOrigin::Column && origin != Column::DefaultOrigin::Domain) {
            out.setstate(std::ios::failbit); return;
        }
        if (origin == Column::DefaultOrigin::Column && tbl.cols[i].defaultValue.empty()) {
            out.setstate(std::ios::failbit); return;
        }
        if (origin == Column::DefaultOrigin::Domain && tbl.cols[i].domainName.empty()) {
            out.setstate(std::ios::failbit); return;
        }
        hasDefaultOrigins = hasDefaultOrigins || origin == Column::DefaultOrigin::Domain ||
            (origin == Column::DefaultOrigin::Column && !tbl.cols[i].domainName.empty());
    }
    // Old readers reject B before consuming it rather than treating an
    // implicit domain default as a frozen SQL column expression.
    const int32_t schemaFormat = longReferences ? SCHEMA_LONG_RELATION_FORMAT_VERSION : hasTemporalCodecs ? SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION : hasColumnTypeMods ? SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION : hasDefaultOrigins ? SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION : tbl.physicalRelationId == 0
        ? SCHEMA_FORMAT_VERSION : SCHEMA_PHYSICAL_ID_FORMAT_VERSION;
    out.write(reinterpret_cast<const char*>(&schemaFormat), sizeof(schemaFormat));
    int32_t len = static_cast<int32_t>(tbl.len);
    out.write(reinterpret_cast<const char*>(&len), 4);
    for (size_t i = 0; i < tbl.len; ++i) {
        uint8_t flags = (tbl.cols[i].isNull ? 1 : 0) | (tbl.cols[i].isPrimaryKey ? 2 : 0) | (tbl.cols[i].isVariableLength ? 4 : 0) | (tbl.cols[i].isUnique ? 8 : 0) | (!tbl.cols[i].defaultValue.empty() ? 16 : 0) | (tbl.cols[i].isAutoIncrement ? 32 : 0) | (!tbl.cols[i].checkExpr.empty() ? 64 : 0) | (!tbl.cols[i].generatedExpr.empty() ? 128 : 0);
        out.write(reinterpret_cast<const char*>(&flags), 1);
        writeFixedString(out, tbl.cols[i].dataType, MAX_TYPE_NAME_LEN);
        writeFixedString(out, tbl.cols[i].dataName, MAX_COL_NAME_LEN);
        int32_t dsize = static_cast<int32_t>(tbl.cols[i].dsize);
        out.write(reinterpret_cast<const char*>(&dsize), 4);
        if (!tbl.cols[i].defaultValue.empty()) {
            writeFixedString(out, tbl.cols[i].defaultValue, MAX_COL_NAME_LEN);
        }
        if (!tbl.cols[i].checkExpr.empty()) {
            uint16_t checkLen = static_cast<uint16_t>(tbl.cols[i].checkExpr.size());
            out.write(reinterpret_cast<const char*>(&checkLen), 2);
            out.write(tbl.cols[i].checkExpr.data(), checkLen);
            // New in version 6: persist CHECK constraint name and deferrability.
            writeFixedString(out, tbl.cols[i].checkConstraintName, MAX_COL_NAME_LEN);
            uint8_t deferFlags = (tbl.cols[i].deferrable ? 1 : 0) | (tbl.cols[i].initiallyDeferred ? 2 : 0);
            out.write(reinterpret_cast<const char*>(&deferFlags), 1);
        }
        if (!tbl.cols[i].generatedExpr.empty()) {
            uint16_t genLen = static_cast<uint16_t>(tbl.cols[i].generatedExpr.size());
            out.write(reinterpret_cast<const char*>(&genLen), 2);
            out.write(tbl.cols[i].generatedExpr.data(), genLen);
            // New in version 5: persist whether the generated column is STORED or VIRTUAL.
            uint8_t genKind = tbl.cols[i].generatedKind == 'v' ? 'v' : 's';
            out.write(reinterpret_cast<const char*>(&genKind), 1);
        }
        // Write enum values
        uint16_t enumCount = static_cast<uint16_t>(tbl.cols[i].enumValues.size());
        out.write(reinterpret_cast<const char*>(&enumCount), 2);
        for (const auto& ev : tbl.cols[i].enumValues) {
            writeFixedString(out, ev, MAX_COL_NAME_LEN);
        }
        // Write array flag (new in version 2)
        uint8_t arrFlag = tbl.cols[i].isArray ? 1 : 0;
        out.write(reinterpret_cast<const char*>(&arrFlag), 1);
    }
    // Write foreign keys (multi-column support: version 1 format)
    int32_t fkLen = static_cast<int32_t>(tbl.fkLen);
    out.write(reinterpret_cast<const char*>(&fkLen), 4);
    for (size_t i = 0; i < tbl.fkLen; ++i) {
        int32_t numCols = static_cast<int32_t>(tbl.fks[i].colNames.size());
        out.write(reinterpret_cast<const char*>(&numCols), 4);
        for (int32_t ci = 0; ci < numCols; ++ci) {
            writeFixedString(out, tbl.fks[i].colNames[ci], MAX_COL_NAME_LEN);
            writeFixedString(out, tbl.fks[i].refCols[ci], MAX_COL_NAME_LEN);
        }
        writeFixedString(out, tbl.fks[i].refTable, longReferences ? relation_name_codec::storageWidth : MAX_TABLE_NAME_LEN);
        writeFixedString(out, tbl.fks[i].onDelete, 10);
        writeFixedString(out, tbl.fks[i].onUpdate, 10);
    }
    // Write composite primary key column indices (0 = use legacy isPrimaryKey)
    int32_t pkCount = static_cast<int32_t>(tbl.pkColIndices.size());
    out.write(reinterpret_cast<const char*>(&pkCount), 4);
    for (size_t idx : tbl.pkColIndices) {
        int32_t cidx = static_cast<int32_t>(idx);
        out.write(reinterpret_cast<const char*>(&cidx), 4);
    }
    // Write composite UNIQUE constraints
    int32_t ucCount = static_cast<int32_t>(tbl.uniqueConstraints.size());
    out.write(reinterpret_cast<const char*>(&ucCount), 4);
    for (const auto& uc : tbl.uniqueConstraints) {
        int32_t cc = static_cast<int32_t>(uc.size());
        out.write(reinterpret_cast<const char*>(&cc), 4);
        for (size_t idx : uc) {
            int32_t cidx = static_cast<int32_t>(idx);
            out.write(reinterpret_cast<const char*>(&cidx), 4);
        }
    }
    // Write partitioning info in the current schema format.
    int32_t ptype = static_cast<int32_t>(tbl.partitionType);
    out.write(reinterpret_cast<const char*>(&ptype), 4);
    writeFixedString(out, tbl.partitionKey, MAX_COL_NAME_LEN);
    if (tbl.partitionType == TableSchema::PartitionType::Range) {
        int32_t rpCount = static_cast<int32_t>(tbl.rangePartitions.size());
        out.write(reinterpret_cast<const char*>(&rpCount), 4);
        for (const auto& rp : tbl.rangePartitions) {
            writeFixedString(out, rp.first, MAX_TABLE_NAME_LEN);
            writeFixedString(out, rp.second, MAX_COL_NAME_LEN);
        }
    } else if (tbl.partitionType == TableSchema::PartitionType::List) {
        int32_t lpCount = static_cast<int32_t>(tbl.listPartitions.size());
        out.write(reinterpret_cast<const char*>(&lpCount), 4);
        for (const auto& lp : tbl.listPartitions) {
            writeFixedString(out, lp.first, MAX_TABLE_NAME_LEN);
            int32_t vcount = static_cast<int32_t>(lp.second.size());
            out.write(reinterpret_cast<const char*>(&vcount), 4);
            for (const auto& v : lp.second) {
                writeFixedString(out, v, MAX_COL_NAME_LEN);
            }
        }
    } else if (tbl.partitionType == TableSchema::PartitionType::Hash) {
        int32_t hcount = static_cast<int32_t>(tbl.hashPartitions);
        out.write(reinterpret_cast<const char*>(&hcount), 4);
    }

    // Write subpartitioning info in the current schema format.
    int32_t sptype = static_cast<int32_t>(tbl.subPartitionType);
    out.write(reinterpret_cast<const char*>(&sptype), 4);
    if (tbl.subPartitionType != TableSchema::PartitionType::None) {
        writeFixedString(out, tbl.subPartitionKey, MAX_COL_NAME_LEN);
        if (tbl.subPartitionType == TableSchema::PartitionType::Hash) {
            int32_t shcount = static_cast<int32_t>(tbl.subHashPartitions);
            out.write(reinterpret_cast<const char*>(&shcount), 4);
        }
    }

    // Named constraint names.
    int32_t namedCheckCount = 0;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (!tbl.cols[i].checkConstraintName.empty()) namedCheckCount++;
    }
    out.write(reinterpret_cast<const char*>(&namedCheckCount), 4);
    for (size_t i = 0; i < tbl.len; ++i) {
        if (!tbl.cols[i].checkConstraintName.empty()) {
            int32_t cidx = static_cast<int32_t>(i);
            out.write(reinterpret_cast<const char*>(&cidx), 4);
            writeFixedString(out, tbl.cols[i].checkConstraintName, MAX_COL_NAME_LEN);
        }
    }

    int32_t namedUniqueCount = static_cast<int32_t>(tbl.uniqueConstraintNames.size());
    out.write(reinterpret_cast<const char*>(&namedUniqueCount), 4);
    for (const auto& name : tbl.uniqueConstraintNames) {
        writeFixedString(out, name, MAX_TABLE_NAME_LEN);
    }

    int32_t namedFkCount = 0;
    for (size_t i = 0; i < tbl.fkLen; ++i) {
        if (!tbl.fks[i].name.empty()) namedFkCount++;
    }
    out.write(reinterpret_cast<const char*>(&namedFkCount), 4);
    for (size_t i = 0; i < tbl.fkLen; ++i) {
        if (!tbl.fks[i].name.empty()) {
            int32_t fidx = static_cast<int32_t>(i);
            out.write(reinterpret_cast<const char*>(&fidx), 4);
            writeFixedString(out, tbl.fks[i].name, MAX_TABLE_NAME_LEN);
        }
    }
    // UNLOGGED flag.
    uint8_t unloggedFlag = tbl.isUnlogged ? 1 : 0;
    out.write(reinterpret_cast<const char*>(&unloggedFlag), 1);
    // Row-Level Security flags.
    uint8_t rlsFlags = (tbl.rowLevelSecurity ? 1 : 0) | (tbl.forceRowLevelSecurity ? 2 : 0);
    out.write(reinterpret_cast<const char*>(&rlsFlags), 1);
    // Default partition name.
    writeFixedString(out, tbl.defaultPartitionName, MAX_TABLE_NAME_LEN);
    // Storage format version (new in version 4)
    out.write(reinterpret_cast<const char*>(&tbl.formatVersion), 4);
    // Tablespace.
    uint16_t tsLen = static_cast<uint16_t>(tbl.tablespace.size());
    out.write(reinterpret_cast<const char*>(&tsLen), 2);
    if (tsLen > 0) out.write(tbl.tablespace.data(), tsLen);
    // Column collations: count + (cidx, name-len, name).
    int32_t collCount = 0;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (!tbl.cols[i].collation.empty()) collCount++;
    }
    out.write(reinterpret_cast<const char*>(&collCount), 4);
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].collation.empty()) continue;
        int32_t cidx = static_cast<int32_t>(i);
        out.write(reinterpret_cast<const char*>(&cidx), 4);
        uint16_t clLen = static_cast<uint16_t>(tbl.cols[i].collation.size());
        out.write(reinterpret_cast<const char*>(&clLen), 2);
        out.write(tbl.cols[i].collation.data(), clLen);
    }
    // Relation owner is part of the canonical schema metadata. Old schema
    // files are intentionally rejected by the version marker above.
    uint16_t ownerLen = static_cast<uint16_t>(std::min<size_t>(tbl.owner.size(), UINT16_MAX));
    out.write(reinterpret_cast<const char*>(&ownerLen), 2);
    if (ownerLen > 0) out.write(tbl.owner.data(), ownerLen);

    // Optional trailing extension: independent CHECK constraints that could
    // not fit the legacy one-per-column representation.  Keeping this after
    // the old payload lets the current reader accept existing schema files
    // that end immediately after owner.
    out.write(reinterpret_cast<const char*>(&SCHEMA_ADDITIONAL_CHECK_MAGIC),
              sizeof(SCHEMA_ADDITIONAL_CHECK_MAGIC));
    const int32_t additionalCheckCount = static_cast<int32_t>(
        tbl.additionalCheckConstraints.size());
    out.write(reinterpret_cast<const char*>(&additionalCheckCount),
              sizeof(additionalCheckCount));
    for (const auto& check : tbl.additionalCheckConstraints) {
        writeFixedString(out, check.name, MAX_TABLE_NAME_LEN);
        const uint32_t expressionLength =
            static_cast<uint32_t>(check.expression.size());
        out.write(reinterpret_cast<const char*>(&expressionLength),
                  sizeof(expressionLength));
        if (expressionLength > 0) {
            out.write(check.expression.data(), expressionLength);
        }
        const uint8_t flags = (check.deferrable ? 1 : 0) |
                              (check.initiallyDeferred ? 2 : 0);
        out.write(reinterpret_cast<const char*>(&flags), sizeof(flags));
    }

    // Optional trailing extension: preserve the distinction between
    // GENERATED ALWAYS and GENERATED BY DEFAULT.  isAutoIncrement remains
    // the physical sequence flag and is also used by SERIAL/extensions.
    out.write(reinterpret_cast<const char*>(&SCHEMA_IDENTITY_KIND_MAGIC),
              sizeof(SCHEMA_IDENTITY_KIND_MAGIC));
    const uint16_t identityKindCount = static_cast<uint16_t>(tbl.len);
    out.write(reinterpret_cast<const char*>(&identityKindCount),
              sizeof(identityKindCount));
    for (size_t columnIndex = 0; columnIndex < tbl.len; ++columnIndex) {
        const char kind = tbl.cols[columnIndex].identityKind;
        out.write(&kind, sizeof(kind));
    }
    // Keep the existing fixed-width payload and short-default files intact.
    // An optional extension carries full SQL expressions that do not fit it.
    uint16_t longDefaultCount = 0;
    for (size_t i = 0; i < tbl.len; ++i)
        if (tbl.cols[i].defaultValue.size() > MAX_COL_NAME_LEN) ++longDefaultCount;
    if (longDefaultCount != 0 || !tbl.rangePartitions.empty() || tbl.physicalRelationId != 0 || hasDefaultOrigins || hasColumnTypeMods || hasTemporalCodecs || longReferences) {
        out.write(reinterpret_cast<const char*>(&SCHEMA_LONG_DEFAULT_MAGIC),
                  sizeof(SCHEMA_LONG_DEFAULT_MAGIC));
        out.write(reinterpret_cast<const char*>(&longDefaultCount),
                  sizeof(longDefaultCount));
        for (uint16_t i = 0; i < tbl.len; ++i) {
            const auto& expression = tbl.cols[i].defaultValue;
            if (expression.size() <= MAX_COL_NAME_LEN) continue;
            const uint32_t length = static_cast<uint32_t>(expression.size());
            out.write(reinterpret_cast<const char*>(&i), sizeof(i));
            out.write(reinterpret_cast<const char*>(&length), sizeof(length));
            out.write(expression.data(), length);
        }
    }

    // Persist lower endpoints without changing the legacy schema prefix. Old
    // schemas infer them as MINVALUE followed by the preceding upper bound.
    if (!tbl.rangePartitions.empty() || tbl.physicalRelationId != 0 || hasDefaultOrigins || hasColumnTypeMods || hasTemporalCodecs || longReferences) {
        out.write(reinterpret_cast<const char*>(&SCHEMA_RANGE_LOWER_BOUNDS_MAGIC),
                  sizeof(SCHEMA_RANGE_LOWER_BOUNDS_MAGIC));
        const int32_t lowerBoundCount =
            static_cast<int32_t>(tbl.rangePartitions.size());
        out.write(reinterpret_cast<const char*>(&lowerBoundCount),
                  sizeof(lowerBoundCount));
        for (size_t index = 0; index < tbl.rangePartitions.size(); ++index) {
            const std::string inferredLower = index == 0
                ? "MINVALUE" : tbl.rangePartitions[index - 1].second;
            const std::string& lower = tbl.rangePartitionLowerBounds.empty()
                ? inferredLower : tbl.rangePartitionLowerBounds[index];
            writeFixedString(out, lower, MAX_COL_NAME_LEN);
        }
    }
    if (tbl.physicalRelationId != 0 || hasDefaultOrigins || hasColumnTypeMods || hasTemporalCodecs || longReferences) {
        out.write(reinterpret_cast<const char*>(&SCHEMA_PHYSICAL_ID_MAGIC),
                  sizeof(SCHEMA_PHYSICAL_ID_MAGIC));
        out.write(reinterpret_cast<const char*>(&tbl.physicalRelationId),
                  sizeof(tbl.physicalRelationId));
    }
    if (hasDefaultOrigins || hasColumnTypeMods || hasTemporalCodecs || longReferences) {
        out.write(reinterpret_cast<const char*>(&SCHEMA_DEFAULT_ORIGIN_MAGIC),sizeof(SCHEMA_DEFAULT_ORIGIN_MAGIC));
        const uint16_t count = static_cast<uint16_t>(tbl.len);
        out.write(reinterpret_cast<const char*>(&count),sizeof(count));
        for (size_t i = 0; i < tbl.len; ++i) {
            const auto origin = static_cast<uint8_t>(tbl.cols[i].defaultOrigin);
            const uint16_t length = static_cast<uint16_t>(tbl.cols[i].domainName.size());
            if (tbl.cols[i].domainName.size() > 256 || tbl.cols[i].domainName.find('\0') != std::string::npos) {
                out.setstate(std::ios::failbit); return;
            }
            out.write(reinterpret_cast<const char*>(&origin),sizeof(origin));
            out.write(reinterpret_cast<const char*>(&length),sizeof(length));
            out.write(tbl.cols[i].domainName.data(),length);
        }
    }
    if (hasColumnTypeMods || hasTemporalCodecs || longReferences) {
        out.write(reinterpret_cast<const char*>(&SCHEMA_COLUMN_TYPEMOD_MAGIC), sizeof(SCHEMA_COLUMN_TYPEMOD_MAGIC));
        const uint16_t count = static_cast<uint16_t>(tbl.len);
        out.write(reinterpret_cast<const char*>(&count), sizeof(count));
        for (size_t i = 0; i < tbl.len; ++i)
            out.write(reinterpret_cast<const char*>(&tbl.cols[i].typeMod), sizeof(tbl.cols[i].typeMod));
    }
    if (hasTemporalCodecs || longReferences) {
        out.write(reinterpret_cast<const char*>(&SCHEMA_TEMPORAL_CODEC_MAGIC), sizeof(SCHEMA_TEMPORAL_CODEC_MAGIC));
        const uint16_t count = static_cast<uint16_t>(tbl.len);
        out.write(reinterpret_cast<const char*>(&count), sizeof(count));
        for (size_t i = 0; i < tbl.len; ++i) {
            const auto codec = static_cast<uint8_t>(tbl.cols[i].storageCodec);
            out.write(reinterpret_cast<const char*>(&codec), sizeof(codec));
        }
    }
}

TableSchema StorageEngine::readSchema(std::istream& in, const std::string& tablename) const {
    TableSchema tbl;
    tbl.tablename = tablename;
    int32_t firstInt = 0;
    in.read(reinterpret_cast<char*>(&firstInt), 4);
    if (!in) return {};

    if (firstInt != SCHEMA_FORMAT_VERSION && firstInt != SCHEMA_PHYSICAL_ID_FORMAT_VERSION && firstInt != SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION && firstInt != SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION && firstInt != SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION && firstInt != SCHEMA_LONG_RELATION_FORMAT_VERSION) {
        std::cerr << "[catalog] unsupported schema format for table " << tablename
                  << "; recreate the database with the current binary" << std::endl;
        return {};
    }
    int32_t len = 0;
    in.read(reinterpret_cast<char*>(&len), 4);
    if (!in || len < 0 || len > static_cast<int32_t>(MAX_COLUMNS)) return {};
    tbl.len = static_cast<size_t>(len);
    for (size_t i = 0; i < tbl.len; ++i) {
        uint8_t flags = 0;
        in.read(reinterpret_cast<char*>(&flags), 1);
        tbl.cols[i].isNull = (flags & 1) != 0;
        tbl.cols[i].isPrimaryKey = (flags & 2) != 0;
        tbl.cols[i].isVariableLength = (flags & 4) != 0;
        tbl.cols[i].isUnique = (flags & 8) != 0;
        bool hasDefault = (flags & 16) != 0;
        tbl.cols[i].isAutoIncrement = (flags & 32) != 0;
        bool hasCheck = (flags & 64) != 0;
        bool hasGenerated = (flags & 128) != 0;
        tbl.cols[i].dataType = readFixedString(in, MAX_TYPE_NAME_LEN);
        constexpr std::string_view unsignedSuffix = " unsigned";
        tbl.cols[i].isUnsigned =
            tbl.cols[i].dataType.size() >= unsignedSuffix.size() &&
            tbl.cols[i].dataType.compare(
                tbl.cols[i].dataType.size() - unsignedSuffix.size(),
                unsignedSuffix.size(), unsignedSuffix) == 0;
        tbl.cols[i].dataName = readFixedString(in, MAX_COL_NAME_LEN);
        int32_t dsize = 0;
        in.read(reinterpret_cast<char*>(&dsize), 4);
        if (!in || dsize < 0) return {};
        const bool largeVarlena = tbl.cols[i].dataType == "blob" ||
                                  tbl.cols[i].dataType == "bytea" ||
                                  tbl.cols[i].dataType == "bit varying";
        if (!largeVarlena && dsize > MAX_PERSISTED_COLUMN_SIZE) return {};
        tbl.cols[i].dsize = static_cast<size_t>(dsize);
        if (hasDefault) {
            tbl.cols[i].defaultValue = readFixedString(in, MAX_COL_NAME_LEN);
        }
        if (hasCheck) {
            uint16_t checkLen = 0;
            in.read(reinterpret_cast<char*>(&checkLen), 2);
            if (in && checkLen > 0) {
                std::string checkExpr(checkLen, '\0');
                in.read(checkExpr.data(), checkLen);
                tbl.cols[i].checkExpr = checkExpr;
            }
            tbl.cols[i].checkConstraintName = readFixedString(in, MAX_COL_NAME_LEN);
            uint8_t deferFlags = 0;
            in.read(reinterpret_cast<char*>(&deferFlags), 1);
            if (in) {
                tbl.cols[i].deferrable = (deferFlags & 1) != 0;
                tbl.cols[i].initiallyDeferred = (deferFlags & 2) != 0;
            }
        }
        if (hasGenerated) {
            uint16_t genLen = 0;
            in.read(reinterpret_cast<char*>(&genLen), 2);
            if (in && genLen > 0) {
                std::string genExpr(genLen, '\0');
                in.read(genExpr.data(), genLen);
                tbl.cols[i].generatedExpr = genExpr;
            }
            uint8_t genKind = 's';
            in.read(reinterpret_cast<char*>(&genKind), 1);
            if (in) tbl.cols[i].generatedKind = static_cast<char>(genKind);
        }
        // Read enum values.
        uint16_t enumCount = 0;
        in.read(reinterpret_cast<char*>(&enumCount), 2);
        if (in && enumCount > 0 && enumCount <= 1000) {
            for (uint16_t ei = 0; ei < enumCount; ++ei) {
                std::string ev = readFixedString(in, MAX_COL_NAME_LEN);
                // A zero-byte string is a legal enum label, not padding or
                // an absent entry. Keep every counted label in declaration
                // order, including empty labels, across schema reloads.
                tbl.cols[i].enumValues.push_back(std::move(ev));
            }
        }
        uint8_t arrFlag = 0;
        in.read(reinterpret_cast<char*>(&arrFlag), 1);
        if (in) tbl.cols[i].isArray = (arrFlag != 0);
    }
    // Read foreign keys
    int32_t fkLen = 0;
    in.read(reinterpret_cast<char*>(&fkLen), 4);
    if (!in || fkLen < 0 || fkLen > static_cast<int32_t>(MAX_COLUMNS)) return {};
    if (fkLen > 0) {
        tbl.fkLen = static_cast<size_t>(fkLen);
        for (size_t i = 0; i < tbl.fkLen; ++i) {
            int32_t numCols = 0;
            in.read(reinterpret_cast<char*>(&numCols), 4);
            if (!in || numCols <= 0 || numCols > static_cast<int32_t>(MAX_COLUMNS)) return {};
            tbl.fks[i].colNames.reserve(numCols);
            tbl.fks[i].refCols.reserve(numCols);
            for (int32_t ci = 0; ci < numCols; ++ci) {
                tbl.fks[i].colNames.push_back(readFixedString(in, MAX_COL_NAME_LEN));
                tbl.fks[i].refCols.push_back(readFixedString(in, MAX_COL_NAME_LEN));
            }
            tbl.fks[i].refTable = readFixedString(in, firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION
                ? relation_name_codec::storageWidth : MAX_TABLE_NAME_LEN);
            if (!in || !validStoredRelationName(tbl.fks[i].refTable)) return {};
            tbl.fks[i].onDelete = readFixedString(in, 10);
            tbl.fks[i].onUpdate = readFixedString(in, 10);
        }
    }
    // Read composite primary key column indices.
    int32_t pkCount = 0;
    in.read(reinterpret_cast<char*>(&pkCount), 4);
    if (!in || pkCount < 0 || pkCount > static_cast<int32_t>(MAX_COLUMNS)) return {};
    if (pkCount > 0) {
        tbl.pkColIndices.reserve(pkCount);
        for (int32_t i = 0; i < pkCount; ++i) {
            int32_t cidx = 0;
            in.read(reinterpret_cast<char*>(&cidx), 4);
            if (in && cidx >= 0 && cidx < static_cast<int32_t>(tbl.len)) {
                tbl.pkColIndices.push_back(static_cast<size_t>(cidx));
            }
        }
    }
    // Read composite UNIQUE constraints.
    int32_t ucCount = 0;
    in.read(reinterpret_cast<char*>(&ucCount), 4);
    if (!in || ucCount < 0 || ucCount > static_cast<int32_t>(MAX_COLUMNS)) return {};
    if (ucCount > 0) {
        tbl.uniqueConstraints.reserve(ucCount);
        for (int32_t i = 0; i < ucCount; ++i) {
            int32_t cc = 0;
            in.read(reinterpret_cast<char*>(&cc), 4);
            if (!in || cc <= 0 || cc > static_cast<int32_t>(MAX_COLUMNS)) break;
            std::vector<size_t> constraint;
            constraint.reserve(cc);
            for (int32_t j = 0; j < cc; ++j) {
                int32_t cidx = 0;
                in.read(reinterpret_cast<char*>(&cidx), 4);
                if (in && cidx >= 0 && cidx < static_cast<int32_t>(tbl.len)) {
                    constraint.push_back(static_cast<size_t>(cidx));
                }
            }
            if (!constraint.empty()) tbl.uniqueConstraints.push_back(std::move(constraint));
        }
    }
    // Read partitioning info.
    int32_t ptype = 0;
    in.read(reinterpret_cast<char*>(&ptype), 4);
    if (!in || ptype < static_cast<int32_t>(TableSchema::PartitionType::None) ||
        ptype > static_cast<int32_t>(TableSchema::PartitionType::Hash)) return {};
    {
        tbl.partitionType = static_cast<TableSchema::PartitionType>(ptype);
        tbl.partitionKey = readFixedString(in, MAX_COL_NAME_LEN);
        if (tbl.partitionType == TableSchema::PartitionType::Range) {
            int32_t rpCount = 0;
            in.read(reinterpret_cast<char*>(&rpCount), 4);
            if (!in || rpCount < 0 || rpCount > static_cast<int32_t>(MAX_COLUMNS)) return {};
            if (rpCount > 0) {
                for (int32_t i = 0; i < rpCount; ++i) {
                    std::string pname = readFixedString(in, MAX_TABLE_NAME_LEN);
                    std::string bound = readFixedString(in, MAX_COL_NAME_LEN);
                    const std::string inferredLower =
                        tbl.rangePartitions.empty()
                            ? "MINVALUE" : tbl.rangePartitions.back().second;
                    tbl.rangePartitions.push_back({pname, bound});
                    tbl.rangePartitionLowerBounds.push_back(inferredLower);
                }
            }
        } else if (tbl.partitionType == TableSchema::PartitionType::List) {
            int32_t lpCount = 0;
            in.read(reinterpret_cast<char*>(&lpCount), 4);
            if (!in || lpCount < 0 || lpCount > static_cast<int32_t>(MAX_COLUMNS)) return {};
            if (lpCount > 0) {
                for (int32_t i = 0; i < lpCount; ++i) {
                    std::string pname = readFixedString(in, MAX_TABLE_NAME_LEN);
                    int32_t vcount = 0;
                    in.read(reinterpret_cast<char*>(&vcount), 4);
                    if (!in || vcount < 0 || vcount > static_cast<int32_t>(MAX_COLUMNS)) return {};
                    std::vector<std::string> values;
                    for (int32_t j = 0; j < vcount; ++j) {
                        values.push_back(readFixedString(in, MAX_COL_NAME_LEN));
                    }
                    tbl.listPartitions.push_back({pname, values});
                }
            }
        } else if (tbl.partitionType == TableSchema::PartitionType::Hash) {
            int32_t hcount = 0;
            in.read(reinterpret_cast<char*>(&hcount), 4);
            if (!in || hcount < 0 || hcount > static_cast<int32_t>(MAX_COLUMNS * MAX_COLUMNS)) return {};
            if (hcount > 0) tbl.hashPartitions = static_cast<size_t>(hcount);
        }
    }

    // Read subpartitioning info.
    int32_t sptype = 0;
    in.read(reinterpret_cast<char*>(&sptype), 4);
    if (!in || sptype < static_cast<int32_t>(TableSchema::PartitionType::None) ||
        sptype > static_cast<int32_t>(TableSchema::PartitionType::Hash)) return {};
    {
        tbl.subPartitionType = static_cast<TableSchema::PartitionType>(sptype);
        if (tbl.subPartitionType != TableSchema::PartitionType::None) {
            tbl.subPartitionKey = readFixedString(in, MAX_COL_NAME_LEN);
            if (tbl.subPartitionType == TableSchema::PartitionType::Hash) {
                int32_t shcount = 0;
                in.read(reinterpret_cast<char*>(&shcount), 4);
                if (!in || shcount < 0 || shcount > static_cast<int32_t>(MAX_COLUMNS * MAX_COLUMNS)) return {};
                if (shcount > 0) tbl.subHashPartitions = static_cast<size_t>(shcount);
            }
        }
    }

    // Read named CHECK constraints.
    int32_t namedCheckCount = 0;
    in.read(reinterpret_cast<char*>(&namedCheckCount), 4);
    if (!in || namedCheckCount < 0 || namedCheckCount > static_cast<int32_t>(MAX_COLUMNS)) return {};
    if (namedCheckCount > 0) {
        for (int32_t i = 0; i < namedCheckCount; ++i) {
            int32_t cidx = 0;
            in.read(reinterpret_cast<char*>(&cidx), 4);
            if (in && cidx >= 0 && cidx < static_cast<int32_t>(tbl.len)) {
                tbl.cols[cidx].checkConstraintName = readFixedString(in, MAX_COL_NAME_LEN);
            } else if (in) {
                readFixedString(in, MAX_COL_NAME_LEN); // skip
            }
        }
    }

    // Read named UNIQUE constraints.
    int32_t namedUniqueCount = 0;
    in.read(reinterpret_cast<char*>(&namedUniqueCount), 4);
    if (!in || namedUniqueCount < 0 || namedUniqueCount > static_cast<int32_t>(MAX_COLUMNS)) return {};
    {
        tbl.uniqueConstraintNames.reserve(namedUniqueCount);
        for (int32_t i = 0; i < namedUniqueCount; ++i) {
            tbl.uniqueConstraintNames.push_back(readFixedString(in, MAX_TABLE_NAME_LEN));
        }
    }

    // Read named FK constraints.
    int32_t namedFkCount = 0;
    in.read(reinterpret_cast<char*>(&namedFkCount), 4);
    if (!in || namedFkCount < 0 || namedFkCount > static_cast<int32_t>(MAX_COLUMNS)) return {};
    if (namedFkCount > 0) {
        for (int32_t i = 0; i < namedFkCount; ++i) {
            int32_t fidx = 0;
            in.read(reinterpret_cast<char*>(&fidx), 4);
            if (in && fidx >= 0 && fidx < static_cast<int32_t>(tbl.fkLen)) {
                tbl.fks[fidx].name = readFixedString(in, MAX_TABLE_NAME_LEN);
            } else if (in) {
                readFixedString(in, MAX_TABLE_NAME_LEN); // skip
            }
        }
    }
    // UNLOGGED flag.
    uint8_t unloggedFlag = 0;
    in.read(reinterpret_cast<char*>(&unloggedFlag), 1);
    if (!in) return {};
    tbl.isUnlogged = (unloggedFlag != 0);
    // Row-Level Security flags.
    uint8_t rlsFlags = 0;
    in.read(reinterpret_cast<char*>(&rlsFlags), 1);
    if (!in) return {};
    tbl.rowLevelSecurity = (rlsFlags & 1) != 0;
    tbl.forceRowLevelSecurity = (rlsFlags & 2) != 0;
    // Default partition name.
    std::string dpName = readFixedString(in, MAX_TABLE_NAME_LEN);
    if (!in) return {};
    tbl.defaultPartitionName = dpName;
    // Storage format version and tablespace.
    uint32_t fv = 0;
    in.read(reinterpret_cast<char*>(&fv), 4);
    if (!in || fv != DATA_FILE_FORMAT_VERSION) return {};
    tbl.formatVersion = fv;
    uint16_t tsLen = 0;
    in.read(reinterpret_cast<char*>(&tsLen), 2);
    if (!in || tsLen > MAX_TABLE_NAME_LEN) return {};
    if (tsLen > 0) {
        std::string ts(tsLen, '\0');
        in.read(ts.data(), tsLen);
        if (in) tbl.tablespace = std::move(ts);
    }
    // Column collations.
    int32_t collCount = 0;
    in.read(reinterpret_cast<char*>(&collCount), 4);
    if (!in || collCount < 0 || collCount > static_cast<int32_t>(MAX_COLUMNS)) return {};
    if (collCount > 0) {
        for (int32_t i = 0; i < collCount; ++i) {
            int32_t cidx = 0;
            in.read(reinterpret_cast<char*>(&cidx), 4);
            if (!in) break;
            uint16_t clLen = 0;
            in.read(reinterpret_cast<char*>(&clLen), 2);
            if (!in) break;
            std::string cname(clLen, '\0');
            in.read(cname.data(), clLen);
            if (!in) break;
            if (cidx >= 0 && cidx < static_cast<int32_t>(tbl.len)) {
                tbl.cols[cidx].collation = std::move(cname);
            }
        }
    }

    uint16_t ownerLen = 0;
    in.read(reinterpret_cast<char*>(&ownerLen), 2);
    if (!in || ownerLen > 255) return {};
    if (ownerLen > 0) {
        tbl.owner.resize(ownerLen);
        in.read(tbl.owner.data(), ownerLen);
        if (!in) return {};
    }

    if (!in) return {};
    if (in.peek() == std::char_traits<char>::eof()) {
        if (!in.eof()) return {};
        if (firstInt == SCHEMA_PHYSICAL_ID_FORMAT_VERSION || firstInt == SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION || firstInt == SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION || firstInt == SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION || firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION) return {};
        in.clear();
        return tbl;
    }

    uint32_t additionalCheckMagic = 0;
    in.read(reinterpret_cast<char*>(&additionalCheckMagic),
            sizeof(additionalCheckMagic));
    if (!in || additionalCheckMagic != SCHEMA_ADDITIONAL_CHECK_MAGIC) {
        return {};
    }
    int32_t additionalCheckCount = 0;
    in.read(reinterpret_cast<char*>(&additionalCheckCount),
            sizeof(additionalCheckCount));
    if (!in || additionalCheckCount < 0 ||
        additionalCheckCount > MAX_ADDITIONAL_CHECK_CONSTRAINTS) {
        return {};
    }
    tbl.additionalCheckConstraints.reserve(
        static_cast<size_t>(additionalCheckCount));
    for (int32_t checkIndex = 0; checkIndex < additionalCheckCount;
         ++checkIndex) {
        CheckConstraint check;
        check.name = readFixedString(in, MAX_TABLE_NAME_LEN);
        uint32_t expressionLength = 0;
        in.read(reinterpret_cast<char*>(&expressionLength),
                sizeof(expressionLength));
        if (!in || expressionLength == 0 ||
            expressionLength > MAX_PERSISTED_CHECK_EXPRESSION) {
            return {};
        }
        check.expression.resize(expressionLength);
        in.read(check.expression.data(), expressionLength);
        uint8_t flags = 0;
        in.read(reinterpret_cast<char*>(&flags), sizeof(flags));
        if (!in) return {};
        check.deferrable = (flags & 1) != 0;
        check.initiallyDeferred = (flags & 2) != 0;
        tbl.additionalCheckConstraints.push_back(std::move(check));
    }

    // Schema files written before identity generation modes were persisted
    // legitimately end after the additional CHECK extension.  Keep accepting
    // them as SERIAL-like auto-increment columns (identityKind == 0).
    if (in.peek() == std::char_traits<char>::eof()) {
        if (!in.eof()) return {};
        if (firstInt == SCHEMA_PHYSICAL_ID_FORMAT_VERSION || firstInt == SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION || firstInt == SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION || firstInt == SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION || firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION) return {};
        in.clear();
        return tbl;
    }
    uint32_t identityKindMagic = 0;
    in.read(reinterpret_cast<char*>(&identityKindMagic),
            sizeof(identityKindMagic));
    if (!in || identityKindMagic != SCHEMA_IDENTITY_KIND_MAGIC) return {};
    uint16_t identityKindCount = 0;
    in.read(reinterpret_cast<char*>(&identityKindCount),
            sizeof(identityKindCount));
    if (!in || identityKindCount != tbl.len) return {};
    for (size_t columnIndex = 0; columnIndex < tbl.len; ++columnIndex) {
        char kind = 0;
        in.read(&kind, sizeof(kind));
        if (!in || (kind != 0 && kind != 'a' && kind != 'd')) return {};
        if (kind != 0 && !tbl.cols[columnIndex].isAutoIncrement) return {};
        tbl.cols[columnIndex].identityKind = kind;
    }
    if (in.peek() == std::char_traits<char>::eof()) {
        if (!in.eof()) return {};
        if (firstInt == SCHEMA_PHYSICAL_ID_FORMAT_VERSION || firstInt == SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION || firstInt == SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION || firstInt == SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION || firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION) return {};
        in.clear();
        return tbl;
    }
    uint32_t defaultMagic = 0;
    uint16_t defaultCount = 0;
    in.read(reinterpret_cast<char*>(&defaultMagic), sizeof(defaultMagic));
    in.read(reinterpret_cast<char*>(&defaultCount), sizeof(defaultCount));
    if (!in || defaultMagic != SCHEMA_LONG_DEFAULT_MAGIC ||
        defaultCount > tbl.len) return {};
    std::set<uint16_t> defaultColumns;
    for (uint16_t i = 0; i < defaultCount; ++i) {
        uint16_t column = 0;
        uint32_t length = 0;
        in.read(reinterpret_cast<char*>(&column), sizeof(column));
        in.read(reinterpret_cast<char*>(&length), sizeof(length));
        if (!in || column >= tbl.len || !defaultColumns.insert(column).second ||
            length <= MAX_COL_NAME_LEN || length > MAX_PERSISTED_DEFAULT_EXPRESSION)
            return {};
        std::string expression(length, '\0');
        in.read(expression.data(), length);
        if (!in || expression.find('\0') != std::string::npos ||
            expression.substr(0, MAX_COL_NAME_LEN) != tbl.cols[column].defaultValue)
            return {};
        tbl.cols[column].defaultValue = std::move(expression);
    }
    if (in.peek() == std::char_traits<char>::eof()) {
        if (!in.eof()) return {};
        if (firstInt == SCHEMA_PHYSICAL_ID_FORMAT_VERSION || firstInt == SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION || firstInt == SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION || firstInt == SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION || firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION) return {};
        // A zero-entry DFT1 block is emitted only with the new RANGE-bound
        // extension; an EOF here therefore means a truncated new schema.
        if (defaultCount == 0 && !tbl.rangePartitions.empty()) return {};
        in.clear();
        return tbl;
    }
    uint32_t rangeLowerBoundsMagic = 0;
    in.read(reinterpret_cast<char*>(&rangeLowerBoundsMagic),
            sizeof(rangeLowerBoundsMagic));
    int32_t rangeLowerBoundsCount = 0;
    in.read(reinterpret_cast<char*>(&rangeLowerBoundsCount),
            sizeof(rangeLowerBoundsCount));
    if (!in || rangeLowerBoundsMagic != SCHEMA_RANGE_LOWER_BOUNDS_MAGIC ||
        rangeLowerBoundsCount !=
            static_cast<int32_t>(tbl.rangePartitions.size())) {
        return {};
    }
    std::vector<std::string> persistedLowerBounds;
    persistedLowerBounds.reserve(static_cast<size_t>(rangeLowerBoundsCount));
    for (int32_t index = 0; index < rangeLowerBoundsCount; ++index) {
        std::string lower = readFixedString(in, MAX_COL_NAME_LEN);
        const auto& upper =
            tbl.rangePartitions[static_cast<size_t>(index)].second;
        if (!in || lower.empty() ||
            comparePartitionValues(tbl, lower, upper, true, true) >= 0) {
            return {};
        }
        if (index > 0) {
            const auto& previousUpper =
                tbl.rangePartitions[static_cast<size_t>(index - 1)].second;
            if (comparePartitionValues(
                    tbl, lower, previousUpper, true, true) < 0) {
                return {};
            }
        }
        persistedLowerBounds.push_back(std::move(lower));
    }
    if (firstInt == SCHEMA_PHYSICAL_ID_FORMAT_VERSION || firstInt == SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION || firstInt == SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION || firstInt == SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION || firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION) {
        uint32_t physicalIdMagic = 0;
        in.read(reinterpret_cast<char*>(&physicalIdMagic), sizeof(physicalIdMagic));
        in.read(reinterpret_cast<char*>(&tbl.physicalRelationId), sizeof(tbl.physicalRelationId));
        if (!in || physicalIdMagic != SCHEMA_PHYSICAL_ID_MAGIC ||
            (firstInt == SCHEMA_PHYSICAL_ID_FORMAT_VERSION && tbl.physicalRelationId == 0))
            return {};
    }
    if (firstInt == SCHEMA_DEFAULT_ORIGIN_FORMAT_VERSION || firstInt == SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION || firstInt == SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION || firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION) {
        uint32_t magic = 0; uint16_t count = 0;
        in.read(reinterpret_cast<char*>(&magic),sizeof(magic));
        in.read(reinterpret_cast<char*>(&count),sizeof(count));
        if (!in || magic != SCHEMA_DEFAULT_ORIGIN_MAGIC || count != tbl.len) return {};
        for (size_t i = 0; i < tbl.len; ++i) {
            uint8_t origin = 0; uint16_t length = 0;
            in.read(reinterpret_cast<char*>(&origin),sizeof(origin));
            in.read(reinterpret_cast<char*>(&length),sizeof(length));
            if (!in || origin > static_cast<uint8_t>(Column::DefaultOrigin::Domain) || length > 256) return {};
            tbl.cols[i].defaultOrigin = static_cast<Column::DefaultOrigin>(origin);
            tbl.cols[i].domainName.resize(length);
            in.read(tbl.cols[i].domainName.data(),length);
            if (!in || tbl.cols[i].domainName.find('\0') != std::string::npos ||
                (tbl.cols[i].defaultOrigin == Column::DefaultOrigin::Column && tbl.cols[i].defaultValue.empty()) ||
                (tbl.cols[i].defaultOrigin == Column::DefaultOrigin::Domain && tbl.cols[i].domainName.empty())) return {};
            if (!tbl.cols[i].domainName.empty()) {
                CatalogManager::QualifiedName domain;
                if (!CatalogManager::parseQualifiedName(tbl.cols[i].domainName,domain,true) || domain.name.empty()) return {};
            }
        }
    }
    if (firstInt == SCHEMA_COLUMN_TYPEMOD_FORMAT_VERSION || firstInt == SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION || firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION) {
        uint32_t magic = 0; uint16_t count = 0;
        in.read(reinterpret_cast<char*>(&magic), sizeof(magic));
        in.read(reinterpret_cast<char*>(&count), sizeof(count));
        if (!in || magic != SCHEMA_COLUMN_TYPEMOD_MAGIC || count != tbl.len) return {};
        for (size_t i = 0; i < tbl.len; ++i) {
            in.read(reinterpret_cast<char*>(&tbl.cols[i].typeMod), sizeof(tbl.cols[i].typeMod));
            if (!in) return {};
            if (tbl.cols[i].typeMod != -1) {
                try {
                    if (tbl.cols[i].dataType == "interval") (void)interval_type_detail::unpack(tbl.cols[i].typeMod);
                    else if (tbl.cols[i].dataType == "numeric") (void)numeric_type_detail::unpack(tbl.cols[i].typeMod);
                    else if (!isValidTemporalColumnModifier(tbl.cols[i])) return {};
                }
                catch (const DbError&) { return {}; }
            }
        }
    }
    if (firstInt == SCHEMA_TEMPORAL_CODEC_FORMAT_VERSION || firstInt == SCHEMA_LONG_RELATION_FORMAT_VERSION) {
        uint32_t magic = 0; uint16_t count = 0;
        in.read(reinterpret_cast<char*>(&magic), sizeof(magic));
        in.read(reinterpret_cast<char*>(&count), sizeof(count));
        if (!in || magic != SCHEMA_TEMPORAL_CODEC_MAGIC || count != tbl.len) return {};
        bool hasTemporalCodec = false;
        for (size_t i = 0; i < tbl.len; ++i) {
            uint8_t codec = 0;
            in.read(reinterpret_cast<char*>(&codec), sizeof(codec));
            if (!in) return {};
            tbl.cols[i].storageCodec = static_cast<Column::StorageCodec>(codec);
            if (!isValidColumnStorageCodec(tbl.cols[i])) return {};
            hasTemporalCodec = hasTemporalCodec ||
                tbl.cols[i].storageCodec != Column::StorageCodec::Legacy;
        }
        if (!hasTemporalCodec && firstInt != SCHEMA_LONG_RELATION_FORMAT_VERSION) return {};
    }
    if (in.peek() != std::char_traits<char>::eof() || !in.eof()) return {};
    tbl.rangePartitionLowerBounds = std::move(persistedLowerBounds);
    in.clear();
    return tbl;
}

// ========================================================================
// Storage parameters (WITH clause)
// ========================================================================
std::map<std::string, std::string> StorageEngine::getStorageParams(
    const std::string& dbname, const std::string& tablename) const {
    std::map<std::string, std::string> params;
    auto pp = paramsPath(dbname, tablename);
    std::ifstream ifs(pp);
    if (!ifs) return params;
    std::string line;
    while (std::getline(ifs, line)) {
        size_t eq = line.find('=');
        if (eq != std::string::npos) {
            params[trim(line.substr(0, eq))] = trim(line.substr(eq + 1));
        }
    }
    return params;
}

DBStatus StorageEngine::setStorageParams(
    const std::string& dbname, const std::string& tablename,
    const std::map<std::string, std::string>& params) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!tableExists(dbname, tablename)) return DBStatus::TABLE_NOT_FOUND;

    std::ostringstream serialized;
    for (const auto& kv : params) {
        if (kv.first.empty() || kv.first.find('\0') != std::string::npos ||
            kv.second.find('\0') != std::string::npos ||
            kv.first.find_first_of("=\r\n") != std::string::npos ||
            kv.second.find_first_of("\r\n") != std::string::npos) {
            return DBStatus::INVALID_ARGUMENT;
        }
        serialized << kv.first << "=" << kv.second << "\n";
    }
    if (!index_file::writeAtomically(
            paramsPath(dbname, tablename), serialized.str())) {
        return DBStatus::IO_ERROR;
    }
    // storageParams are folded into the cached table schema.
    invalidateCatalogSchema(dbname, tablename);
    return DBStatus::OK;
}

DBStatus StorageEngine::updateStorageParams(
    const std::string& dbname, const std::string& tablename,
    const std::map<std::string, std::string>& changes) {
    auto params = getStorageParams(dbname, tablename);
    for (const auto& change : changes) {
        if (change.second.empty()) params.erase(change.first);
        else params[change.first] = change.second;
    }
    return setStorageParams(dbname, tablename, params);
}

static uint8_t getFillFactor(const TableSchema& tbl) {
    auto it = tbl.storageParams.find("fillfactor");
    if (it == tbl.storageParams.end()) return 100;
    try {
        int ff = std::stoi(it->second);
        if (ff < 10) ff = 10;
        if (ff > 100) ff = 100;
        return static_cast<uint8_t>(ff);
    } catch (...) {
        return 100;
    }
}

static bool pageFitsWithFillfactor(const PageWrapper& page, size_t rowSize,
                                    size_t pageSize, uint8_t fillfactor) {
    if (fillfactor >= 100) return true;
    size_t reserve = pageSize * (100 - fillfactor) / 100;
    size_t free = page.freeSpace();
    // Need enough free space for the row plus the fillfactor reserve.
    return free >= rowSize + reserve;
}

// ========================================================================
// TOAST (The Oversized-Attribute Storage Technique)
// ========================================================================

namespace {

constexpr size_t TOAST_CHUNK_HEADER_SIZE = sizeof(uint64_t) + sizeof(uint32_t) +
                                           sizeof(uint8_t) + sizeof(uint64_t);
constexpr uint8_t TOAST_FLAG_COMPRESSED = 0x01;
constexpr uint32_t TOAST_COUNTER_MAGIC = 0x31444954u;  // 'TID1'
constexpr uint32_t TOAST_COUNTER_VERSION = 1;
constexpr size_t TOAST_COUNTER_LEGACY_SIZE = sizeof(uint64_t);
constexpr size_t TOAST_COUNTER_PAYLOAD_SIZE = sizeof(uint32_t) * 2 + sizeof(uint64_t);
constexpr size_t TOAST_COUNTER_SIZE = TOAST_COUNTER_PAYLOAD_SIZE + sizeof(uint64_t);

class ToastCounterFileLock {
public:
    explicit ToastCounterFileLock(const std::filesystem::path& counterPath) {
        std::filesystem::path lockPath = counterPath;
        lockPath += ".lock";
        fd_ = ::open(lockPath.c_str(), O_RDWR | O_CREAT | O_CLOEXEC, 0600);
        if (fd_ < 0) return;
        while (::flock(fd_, LOCK_EX) != 0) {
            if (errno == EINTR) continue;
            ::close(fd_);
            fd_ = -1;
            return;
        }
    }

    ~ToastCounterFileLock() {
        if (fd_ >= 0) {
            (void)::flock(fd_, LOCK_UN);
            (void)::close(fd_);
        }
    }

    ToastCounterFileLock(const ToastCounterFileLock&) = delete;
    ToastCounterFileLock& operator=(const ToastCounterFileLock&) = delete;
    bool ok() const { return fd_ >= 0; }

private:
    int fd_ = -1;
};

static uint64_t toastCounterChecksum(const char* data, size_t size) {
    uint64_t hash = 1469598103934665603ULL;
    for (size_t i = 0; i < size; ++i) {
        hash ^= static_cast<unsigned char>(data[i]);
        hash *= 1099511628211ULL;
    }
    return hash;
}

template <typename T>
static void appendToastCounter(std::string& bytes, const T& value) {
    bytes.append(reinterpret_cast<const char*>(&value), sizeof(value));
}

static bool persistToastCounter(const std::filesystem::path& path,
                                uint64_t nextId) {
    if (nextId == 0) return false;
    std::string bytes;
    bytes.reserve(TOAST_COUNTER_SIZE);
    appendToastCounter(bytes, TOAST_COUNTER_MAGIC);
    appendToastCounter(bytes, TOAST_COUNTER_VERSION);
    appendToastCounter(bytes, nextId);
    const uint64_t checksum = toastCounterChecksum(bytes.data(), bytes.size());
    appendToastCounter(bytes, checksum);
    return index_file::writeAtomically(path, bytes);
}

// Reserve IDs only after the unchanged atomic file+directory durability
// barrier. One reservation per thread bounds memory/FD use and avoids any
// process-global mutex (including an inherited locked mutex after fork).
class ToastIdReservation {
public:
    ~ToastIdReservation() { clear(); }
    ToastIdReservation() = default;
    ToastIdReservation(const ToastIdReservation&) = delete;
    ToastIdReservation& operator=(const ToastIdReservation&) = delete;

    void clear() {
        if (fd_ >= 0) (void)::close(fd_);
        fd_ = -1;
        next_ = limit_ = 0;
    }

    bool take(const std::filesystem::path& path, uint64_t durableLimit,
              uint64_t& allocated) {
        if (fd_ < 0 || process_ != ::getpid() || next_ >= limit_ ||
            durableLimit != limit_) return false;
        struct stat current {}, held {};
        // Pin the reserved inode until invalidation: unlink/recreate cannot
        // recycle its inode and accidentally validate a stale reservation.
        // Counter replacement by another writer, restore or TRUNCATE burns
        // any remaining IDs rather than applying them to the new generation.
        if (::stat(path.c_str(), &current) != 0 ||
            ::fstat(fd_, &held) != 0 || !S_ISREG(current.st_mode) ||
            current.st_dev != held.st_dev || current.st_ino != held.st_ino)
            return false;
        allocated = next_++;
        return true;
    }

    void remember(const std::filesystem::path& path, uint64_t next,
                  uint64_t limit) {
        clear();
        const int descriptor = ::open(path.c_str(), O_RDONLY | O_CLOEXEC);
        if (descriptor < 0) return; // The first ID is still durably covered.
        struct stat identity {};
        if (::fstat(descriptor, &identity) != 0 || !S_ISREG(identity.st_mode)) {
            (void)::close(descriptor);
            return;
        }
        fd_ = descriptor;
        process_ = ::getpid();
        next_ = next;
        limit_ = limit;
    }

private:
    int fd_ = -1;
    pid_t process_ = 0;
    uint64_t next_ = 0;
    uint64_t limit_ = 0;
};

thread_local ToastIdReservation toastIdReservation;
constexpr uint64_t TOAST_ID_RESERVATION_SIZE = 128;

constexpr uint32_t PHYSICAL_RELATION_COUNTER_MAGIC = 0x31444947u;  // GID1

static DBStatus readPhysicalRelationCounterChecked(const std::filesystem::path& path,
                                                   uint64_t& nextId) {
    nextId = 1;
    std::error_code ec;
    if (!std::filesystem::exists(path, ec))
        return ec ? DBStatus::IO_ERROR : DBStatus::OK;
    if (!std::filesystem::is_regular_file(path, ec) || ec)
        return DBStatus::IO_ERROR;
    std::ifstream input(path, std::ios::binary);
    if (!input) return DBStatus::IO_ERROR;
    std::string bytes;
    try { bytes.assign(std::istreambuf_iterator<char>(input), {}); }
    catch (const std::ios_base::failure&) { return DBStatus::IO_ERROR; }
    if (input.bad()) return DBStatus::IO_ERROR;
    if (bytes.size() != TOAST_COUNTER_SIZE) return DBStatus::CORRUPTED_DATA;
    uint32_t magic = 0, version = 0;
    uint64_t checksum = 0;
    std::memcpy(&magic, bytes.data(), sizeof(magic));
    std::memcpy(&version, bytes.data() + sizeof(magic), sizeof(version));
    std::memcpy(&nextId, bytes.data() + sizeof(magic) + sizeof(version), sizeof(nextId));
    std::memcpy(&checksum, bytes.data() + TOAST_COUNTER_PAYLOAD_SIZE, sizeof(checksum));
    return magic == PHYSICAL_RELATION_COUNTER_MAGIC && version == 1 && nextId != 0 &&
        checksum == toastCounterChecksum(bytes.data(), TOAST_COUNTER_PAYLOAD_SIZE)
        ? DBStatus::OK : DBStatus::CORRUPTED_DATA;
}

static bool readPhysicalRelationCounter(const std::filesystem::path& path,
                                        uint64_t& nextId) {
    return readPhysicalRelationCounterChecked(path, nextId) == DBStatus::OK;
}

static bool persistPhysicalRelationCounter(const std::filesystem::path& path,
                                           uint64_t nextId) {
    if (nextId == 0) return false;
    std::string bytes;
    appendToastCounter(bytes, PHYSICAL_RELATION_COUNTER_MAGIC);
    appendToastCounter(bytes, uint32_t{1});
    appendToastCounter(bytes, nextId);
    appendToastCounter(bytes, toastCounterChecksum(bytes.data(), bytes.size()));
    return index_file::writeAtomically(path, bytes);
}

static DBStatus allocatePhysicalRelationId(StorageEngine& engine,
                                       const std::string& dbname,
                                       uint64_t& relationId) {
    // This file is outside database snapshots and is never rolled back.
    // Burn IDs before publishing any schema. The backed-up database floors
    // also prevent reuse when an older cluster counter accompanies a restore.
    const std::filesystem::path counter = ".physical_relation_ids";
    ToastCounterFileLock lock(counter);
    if (!lock.ok()) return DBStatus::IO_ERROR;
    uint64_t nextId = 0;
    const auto clusterStatus = readPhysicalRelationCounterChecked(counter, nextId);
    if (clusterStatus != DBStatus::OK) return clusterStatus;
    for (const auto& database : engine.getDatabaseNames()) {
        uint64_t floor = 0;
        const auto floorStatus = readPhysicalRelationCounterChecked(
            engine.dbPath(database) / ".physical_relation_id_highwater", floor);
        if (floorStatus != DBStatus::OK) return floorStatus;
        nextId = std::max(nextId, floor);
        for (const auto& tableName : engine.getTableNames(database)) {
            const auto table = engine.getTableSchema(database, tableName);
            if (table.tablename != tableName) return DBStatus::CORRUPTED_DATA;
            if (table.physicalRelationId == std::numeric_limits<uint64_t>::max())
                return DBStatus::INVALID_VALUE;
            nextId = std::max(nextId, table.physicalRelationId + 1);
        }
    }
    if (nextId == std::numeric_limits<uint64_t>::max()) return DBStatus::INVALID_VALUE;
    if (!persistPhysicalRelationCounter(counter, nextId + 1) ||
        !persistPhysicalRelationCounter(
            engine.dbPath(dbname) / ".physical_relation_id_highwater", nextId + 1))
        return DBStatus::IO_ERROR;
    relationId = nextId;
    return DBStatus::OK;
}

static std::string compressToastPayload(const std::string& data, uint8_t& flags) {
    flags = 0;
    if (data.empty() || data.size() > std::numeric_limits<uLong>::max()) return data;

    uLongf bound = compressBound(static_cast<uLong>(data.size()));
    std::string compressed(static_cast<size_t>(bound), '\0');
    uLongf compressedSize = bound;
    const int status = compress2(
        reinterpret_cast<Bytef*>(compressed.data()), &compressedSize,
        reinterpret_cast<const Bytef*>(data.data()), static_cast<uLong>(data.size()),
        Z_DEFAULT_COMPRESSION);
    if (status != Z_OK || compressedSize >= data.size()) return data;

    compressed.resize(static_cast<size_t>(compressedSize));
    flags = TOAST_FLAG_COMPRESSED;
    return compressed;
}

