// WAL helpers
// ========================================================================

WALManager* StorageEngine::getWAL(const std::string& dbname) const {
    requireDatabaseTransactionOwnership(dbname);
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    auto& context = transactionContext();
    const bool ownsDatabaseLock =
        (context.databaseExclusiveLock && context.databaseExclusiveLock->owns_lock()) ||
        (context.databaseSharedLock && context.databaseSharedLock->owns_lock());
    if (context.inTransaction && context.txnDB == dbname && ownsDatabaseLock &&
        context.transactionWalOwner) {
        // Public namespace validity gates new ownership, not the terminal
        // work of an owner whose open physical directory is unchanged.
        // Reject a different inode rather than redirecting this xid to it.
        return context.transactionWalOwner->isOpen()
            ? context.transactionWalOwner.get() : nullptr;
    }
    // A peer's cached background work can outlive DROP DATABASE. It must
    // not recreate that database merely to initialize a WAL directory.
    if (!databaseExists(dbname)) return nullptr;
    const auto path = walPath(dbname);
    std::error_code error;
    std::filesystem::create_directory(path, error);
    if (error) return nullptr;
    struct stat directory {};
    if (::stat(path.c_str(), &directory) != 0 || !S_ISDIR(directory.st_mode))
        return nullptr;
    const auto key = canonicalStoragePath(path) + ":" +
        std::to_string(directory.st_dev) + ":" + std::to_string(directory.st_ino);
    const auto slot = physicalStorageSlot<WALManager>(key);
    std::lock_guard<std::mutex> ownerLock(slot->mutex);
    auto wal = slot->owner.lock();
    if (wal && !wal->refersToCurrentDirectory()) wal.reset();
    if (!wal) {
        wal = std::make_shared<WALManager>(canonicalStoragePath(path));
        if (!wal->ensureOpen(false)) return nullptr;
        struct stat opened {};
        if (::stat(path.c_str(), &opened) != 0 ||
            opened.st_dev != directory.st_dev || opened.st_ino != directory.st_ino)
            return nullptr;
        slot->owner = wal;
    }
    WALManager* ptr = wal.get();
    if (context.inTransaction && context.txnDB == dbname && ownsDatabaseLock)
        context.transactionWalOwner = wal;
    walManagers_[dbname] = std::move(wal);
    return ptr;
}

const CatalogService& StorageEngine::catalogService() const {
    if (!catalogService_) throw DbError("55000", "catalog service is not initialized");
    return *catalogService_;
}

CatalogService& StorageEngine::catalogService() {
    const auto status = ensureDatabaseTransactionOwnership();
    if (status != DBStatus::OK)
        throw DbError(sqlstateForDBStatus(status), "could not acquire database transaction ownership");
    if (!catalogService_) {
        catalogService_ = std::make_unique<CatalogService>(*this);
    }
    return *catalogService_;
}

void StorageEngine::closeAllWALs() {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    // PageAllocator writeback barriers capture WALManager pointers.
    // Destroy their owners before invalidating those callbacks.
    pageAllocators_.clear();
    walManagers_.clear();
}

static std::vector<char> encodeHeapPayload(const std::string& tableName,
                                           uint32_t pageId,
                                           uint32_t forkNum,
                                           uint16_t slotId) {
    std::vector<char> payload;
    uint32_t nameLen = static_cast<uint32_t>(tableName.size());
    payload.reserve(sizeof(uint32_t) + nameLen + sizeof(uint32_t) + sizeof(uint32_t) + sizeof(uint16_t));
    payload.insert(payload.end(), reinterpret_cast<const char*>(&nameLen),
                   reinterpret_cast<const char*>(&nameLen) + sizeof(nameLen));
    payload.insert(payload.end(), tableName.begin(), tableName.end());
    payload.insert(payload.end(), reinterpret_cast<const char*>(&pageId),
                   reinterpret_cast<const char*>(&pageId) + sizeof(pageId));
    payload.insert(payload.end(), reinterpret_cast<const char*>(&forkNum),
                   reinterpret_cast<const char*>(&forkNum) + sizeof(forkNum));
    payload.insert(payload.end(), reinterpret_cast<const char*>(&slotId),
                   reinterpret_cast<const char*>(&slotId) + sizeof(slotId));
    return payload;
}

Lsn StorageEngine::walPageImage(const std::string& dbname, const std::string& tablename,
                                uint32_t pageId, const char* pageBuf, size_t pageSize,
                                bool beforeImage, uint32_t forkNum) {
    const TableSchema table = getTableSchema(dbname, tablename);
    if (!usesHeapTupleHeader(table.formatVersion)) {
        return INVALID_LSN;
    }
    WALManager* wal = getWAL(dbname);
    if (!wal) return INVALID_LSN;
    // UNLOGGED heap contents must not enter WAL (and therefore physical or
    // logical replication). Callers still need a valid page LSN for checksum
    // and writeback ordering, so retain the current WAL boundary without
    // inserting a page image. Crash recovery discards the main fork from its
    // init fork before the database becomes available.
    if (table.isUnlogged) return wal->currentWriteLsn();
    const uint64_t xid =
        transactionContext().inTransaction ? transactionContext().currentTxnId : 0;
    // Before-image dedup: recovery's undo pass applies uncommitted
    // before-images newest-to-oldest, ending at the earliest image of each
    // page, which already restores the pre-transaction state. Logging the
    // same page again in one transaction only inflates the WAL. Records with
    // xid 0 are non-transactional maintenance pairs replayed in WAL order,
    // so they keep their exact before/after pairing and are not deduped.
    char pageKey[32];
    std::snprintf(pageKey, sizeof(pageKey), "%u", pageId);
    const std::string key = tablename + "/" + std::to_string(forkNum) +
                            "/" + pageKey;
    if (beforeImage && xid != 0) {
        auto& logged = transactionContext().txnLoggedBeforePages;
        auto it = logged.find(key);
        if (it != logged.end() && it->second.first == xid) {
            return it->second.second;  // covered by the earliest image
        }
    }
    std::vector<char> payload =
        encodeHeapPayload(tablename, pageId, forkNum, 0);
    uint32_t pageLen = static_cast<uint32_t>(pageSize);
    payload.insert(payload.end(), reinterpret_cast<const char*>(&pageLen),
                   reinterpret_cast<const char*>(&pageLen) + sizeof(pageLen));
    payload.insert(payload.end(), pageBuf, pageBuf + pageSize);
    heap_wal_identity::appendImage(payload, table.physicalRelationId);
    uint8_t info = beforeImage ? XLOG_HEAP_PAGE_BEFORE : XLOG_HEAP_PAGE_AFTER;
    const Lsn lsn = wal->XLogInsert(RM_HEAP_ID, info, xid, payload);
    // Do not suppress a retry after a failed insert: only a WAL record that
    // actually entered the stream covers this page's pre-transaction image.
    if (beforeImage && xid != 0 && lsn != INVALID_LSN) {
        transactionContext().txnLoggedBeforePages[key] = {xid, lsn};
    }
    return lsn;
}

Lsn StorageEngine::walIndexFileImage(const std::string& dbname,
                                     const std::filesystem::path& indexPath,
                                     const std::vector<char>& image,
                                     bool beforeImage) {
    constexpr size_t kMaxIndexWalImage = 256ULL * 1024ULL * 1024ULL;
    WALManager* wal = getWAL(dbname);
    if (!wal || indexPath.empty() || image.size() > kMaxIndexWalImage) {
        return INVALID_LSN;
    }
    const std::string pathText = indexPath.string();
    if (pathText.size() > std::numeric_limits<uint32_t>::max()) return INVALID_LSN;

    std::vector<char> payload;
    const uint32_t pathLen = static_cast<uint32_t>(pathText.size());
    const uint64_t imageLen = static_cast<uint64_t>(image.size());
    payload.reserve(sizeof(pathLen) + pathText.size() + sizeof(imageLen) + image.size());
    payload.insert(payload.end(), reinterpret_cast<const char*>(&pathLen),
                   reinterpret_cast<const char*>(&pathLen) + sizeof(pathLen));
    payload.insert(payload.end(), pathText.begin(), pathText.end());
    payload.insert(payload.end(), reinterpret_cast<const char*>(&imageLen),
                   reinterpret_cast<const char*>(&imageLen) + sizeof(imageLen));
    payload.insert(payload.end(), image.begin(), image.end());
    return wal->XLogInsert(
        RM_INDEX_ID,
        beforeImage ? XLOG_INDEX_FILE_BEFORE : XLOG_INDEX_FILE_AFTER,
        transactionContext().inTransaction && transactionContext().txnDB == dbname
            ? transactionContext().currentTxnId
            : 0,
        payload);
}

static void setPageLsnAndChecksum(char* buf, Lsn lsn) {
    if (!buf) return;
    std::memcpy(buf, &lsn, sizeof(lsn));
    PgPage pg(buf);
    pg.writeChecksum();
}

Lsn StorageEngine::walXactCommit(const std::string& dbname, uint64_t xid) {
    WALManager* wal = getWAL(dbname);
    if (!wal) return INVALID_LSN;
    std::vector<char> payload;
    payload.insert(payload.end(), reinterpret_cast<const char*>(&xid),
                   reinterpret_cast<const char*>(&xid) + sizeof(xid));
    // Commit timestamp (seconds since epoch) for PITR: recovery stops
    // treating commits newer than the recovery target as committed.
    // v1 records carry only the xid; readers treat missing timestamp as 0
    // (= always allowed), so old WAL segments replay unchanged.
    const uint64_t commitEpoch = static_cast<uint64_t>(
        std::chrono::duration_cast<std::chrono::seconds>(
            std::chrono::system_clock::now().time_since_epoch()).count());
    payload.insert(payload.end(), reinterpret_cast<const char*>(&commitEpoch),
                   reinterpret_cast<const char*>(&commitEpoch) + sizeof(commitEpoch));
    return wal->XLogInsert(RM_XACT_ID, XLOG_XACT_COMMIT, xid, payload);
}

static uint64_t commitEpochOf(const XLogRecord& rec) {
    // v2 commit records: [xid (8)][epoch (8)]. v1: xid only -> 0.
    if (rec.rmid() != RM_XACT_ID || rec.info() != XLOG_XACT_COMMIT) return 0;
    if (rec.data.size() < sizeof(uint64_t) * 2) return 0;
    uint64_t epoch = 0;
    std::memcpy(&epoch, rec.data.data() + sizeof(uint64_t), sizeof(epoch));
    return epoch;
}

static bool decodeXactWalRecord(const XLogRecord& record, uint64_t& xid) {
    if (record.rmid() != RM_XACT_ID) return false;
    const auto encodedDataSize = [](size_t logicalSize) {
        const size_t total = sizeof(XLogRecHeader) + logicalSize;
        return ((total + MAXALIGN - 1) / MAXALIGN) * MAXALIGN -
               sizeof(XLogRecHeader);
    };
    const uint8_t info = record.info();
    size_t logicalSize = sizeof(uint64_t);
    if (info == XLOG_XACT_COMMIT) {
        // v1 stores xid only; v2 appends the commit epoch used by PITR.
        if (record.data.size() == encodedDataSize(sizeof(uint64_t) * 2)) {
            logicalSize = sizeof(uint64_t) * 2;
        } else if (record.data.size() != encodedDataSize(sizeof(uint64_t))) {
            return false;
        }
    } else if (info == XLOG_XACT_ABORT || info == XLOG_XACT_PREPARE) {
        if (record.data.size() != encodedDataSize(sizeof(uint64_t))) {
            return false;
        }
    } else {
        return false;
    }
    if (!std::all_of(
            record.data.begin() + static_cast<std::ptrdiff_t>(logicalSize),
            record.data.end(), [](char byte) { return byte == '\0'; })) {
        return false;
    }
    std::memcpy(&xid, record.data.data(), sizeof(xid));
    return xid != 0 && record.header.xl_xid == xid;
}

Lsn StorageEngine::walXactAbort(const std::string& dbname, uint64_t xid) {
    WALManager* wal = getWAL(dbname);
    if (!wal) return INVALID_LSN;
    std::vector<char> payload;
    payload.insert(payload.end(), reinterpret_cast<const char*>(&xid),
                   reinterpret_cast<const char*>(&xid) + sizeof(xid));
    return wal->XLogInsert(RM_XACT_ID, XLOG_XACT_ABORT, xid, payload);
}

Lsn StorageEngine::walXactPrepare(const std::string& dbname, uint64_t xid) {
    WALManager* wal = getWAL(dbname);
    if (!wal) return INVALID_LSN;
    std::vector<char> payload;
    payload.insert(payload.end(), reinterpret_cast<const char*>(&xid),
                   reinterpret_cast<const char*>(&xid) + sizeof(xid));
    return wal->XLogInsert(RM_XACT_ID, XLOG_XACT_PREPARE, xid, payload);
}

Lsn StorageEngine::walCheckpoint(const std::string& dbname, uint64_t nextXid) {
    WALManager* wal = getWAL(dbname);
    if (!wal) return INVALID_LSN;
    std::vector<char> payload;
    payload.insert(payload.end(), reinterpret_cast<const char*>(&nextXid),
                   reinterpret_cast<const char*>(&nextXid) + sizeof(nextXid));
    uint64_t timestamp = static_cast<uint64_t>(std::time(nullptr));
    payload.insert(payload.end(), reinterpret_cast<const char*>(&timestamp),
                   reinterpret_cast<const char*>(&timestamp) + sizeof(timestamp));
    return wal->XLogInsert(RM_CHECKPOINT_ID, XLOG_CHECKPOINT_SHUTDOWN,
                           transactionContext().inTransaction ? transactionContext().currentTxnId : 0, payload);
}

Lsn StorageEngine::walSmgrTruncate(const std::string& dbname,
                                   const std::string& tablename) {
    WALManager* wal = getWAL(dbname);
    if (!wal || tablename.empty() ||
        !validStoredRelationName(tablename)) {
        return INVALID_LSN;
    }
    const uint32_t length = static_cast<uint32_t>(tablename.size());
    std::vector<char> payload;
    payload.reserve(sizeof(length) + tablename.size());
    payload.insert(payload.end(), reinterpret_cast<const char*>(&length),
                   reinterpret_cast<const char*>(&length) + sizeof(length));
    payload.insert(payload.end(), tablename.begin(), tablename.end());
    heap_wal_identity::appendImage(payload, getTableSchema(dbname, tablename).physicalRelationId);
    // TRUNCATE is currently an immediate storage operation (the SQL DDL
    // bridge commits first), so its redo boundary is non-transactional.
    return wal->XLogInsert(
        RM_SMGR_ID, XLOG_SMGR_TRUNCATE, 0, payload);
}

Lsn StorageEngine::walCatalogChange(const std::string& dbname, uint8_t info,
                                    const std::string& objType,
                                    const std::string& objName) {
    WALManager* wal = getWAL(dbname);
    if (!wal) return INVALID_LSN;
    std::vector<char> payload;
    uint8_t typeLen = static_cast<uint8_t>(std::min<size_t>(objType.size(), 255));
    uint8_t nameLen = static_cast<uint8_t>(std::min<size_t>(objName.size(), 255));
    payload.push_back(typeLen);
    payload.insert(payload.end(), objType.data(), objType.data() + typeLen);
    payload.push_back(nameLen);
    payload.insert(payload.end(), objName.data(), objName.data() + nameLen);
    return wal->XLogInsert(RM_CATALOG_ID, info, transactionContext().inTransaction ? transactionContext().currentTxnId : 0, payload);
}

void StorageEngine::markPageDirtyAndLsn(PageAllocator* pa, uint32_t pageId, Lsn lsn,
                                        uint32_t formatVersion) {
    if (!pa || lsn == INVALID_LSN) return;
    pa->markDirty(pageId);
    if (!usesHeapTupleHeader(formatVersion)) return;
    char* buf = pa->fetchPage(pageId);
    if (!buf) return;
    std::memcpy(buf, &lsn, sizeof(lsn));
    PgPage pg(buf);
    pg.writeChecksum();
    pa->markDirty(pageId);
    pa->unpinPage(pageId);
}

bool StorageEngine::redoPageImage(const std::string& dbname, const std::string& tablename,
                                  uint32_t pageId, const char* pageData, size_t pageLen,
                                  Lsn recordLsn, bool force,
                                  uint32_t forkNum) {
    const TableSchema table = getTableSchema(dbname, tablename);
    PageAllocator* pa = nullptr;
    if (forkNum == 0) {
        // Older releases incorrectly emitted partition page images as fork
        // zero.  A partitioned parent never owns data pages, so replaying
        // those legacy records would pollute its otherwise-empty heap.
        if (table.partitionType != TableSchema::PartitionType::None) {
            return true;
        }
        pa = getPageAllocator(dbname, tablename);
    } else {
        if (table.partitionType == TableSchema::PartitionType::None) {
            return false;
        }
        PartitionLeaf leaf;
        bool collision = false;
        if (!resolvePartitionFork(table, forkNum, leaf, collision)) {
            if (collision) {
                std::cerr << "[recovery] partition fork collision for "
                          << dbname << "/" << tablename << std::endl;
                return false;
            }
            // WAL for a durably detached partition can remain in retained
            // segments.  As with a dropped relation, it has no replay target.
            return true;
        }
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        const std::string physicalName = tablename + "#" + leaf.partition +
            (leaf.subPartition.empty() ? "" : "#" + leaf.subPartition);
        const std::string key = dbname + "/" + physicalName;
        auto cached = pageAllocators_.find(key);
        if (cached != pageAllocators_.end()) {
            pa = cached->second.get();
        } else {
            const std::filesystem::path path = leaf.subPartition.empty()
                ? partitionDataPath(dbname, tablename, leaf.partition)
                : partitionDataPath(dbname, tablename, leaf.partition,
                                    leaf.subPartition);
            auto allocator = acquireSharedHeap(
                dbname, path, table.rowSize(),
                pageSizeForFormatVersion(table.formatVersion),
                table.formatVersion);
            if (!allocator) return false;
            pa = allocator.get();
            pageAllocators_[key] = std::move(allocator);
        }
    }
    if (!pa) return false;
    if (pageId == 0 || pa->pageSize() != pageLen || !pageData) return false;
    PgPage image(const_cast<char*>(pageData));
    if (!image.isValid()) return false;

    // Skip if page already has a newer or equal LSN, unless forced (undo).
    if (!force && pageId < pa->numPages()) {
        char* buf = pa->fetchPage(pageId);
        if (buf) {
            Lsn currentLsn = 0;
            std::memcpy(&currentLsn, buf, sizeof(currentLsn));
            pa->unpinPage(pageId);
            // A freshly initialized page carries INVALID_LSN.  It must not
            // compare as a newer page now that LSN 0 is a valid WAL position.
            if (currentLsn != INVALID_LSN && currentLsn >= recordLsn) return true;
        }
    }

    // WAL page images are emitted by the sequential allocator.  A gap would
    // require an unbounded allocation loop and indicates missing/corrupt WAL.
    if (pageId > pa->numPages()) return false;
    if (pageId == pa->numPages() && pa->allocPage() != pageId) {
        return false;
    }

    // Write the page image directly through the buffer pool.
    char* buf = pa->fetchPage(pageId);
    if (!buf) return false;
    std::memcpy(buf, pageData, pageLen);
    pa->markDirty(pageId);
    pa->unpinPage(pageId);
    return true;
}

bool StorageEngine::redoIndexFileImage(const std::filesystem::path& indexPath,
                                       const char* image, size_t imageLen) {
    if (indexPath.empty() || (!image && imageLen != 0)) return false;
    if (imageLen == 0) {
        std::error_code ec;
        const bool removed = !std::filesystem::exists(indexPath, ec) ||
                              std::filesystem::remove(indexPath, ec);
        return removed && !ec;
    }
    return index_file::writeAtomically(indexPath, std::string(image, imageLen));
}

bool StorageEngine::redoXactCommit(uint64_t xid) {
    CommitLog* clog = getCommitLog("");
    (void)clog; (void)xid;
    return true;
}

