struct PreparedTransactionRecord {
    static constexpr int CURRENT_FORMAT = 6;
    static constexpr int MINIMUM_FORMAT = 2;
    int format = 0;
    uint64_t txnId = 0;
    std::string dbname;
    IsolationLevel isolation = IsolationLevel::REPEATABLE_READ;
    struct LogEntry {
        enum class Op { Insert, Update, Delete } op;
        std::string tableName;
        int64_t rowIdx = 0;
        std::string rowData;
        std::string newRowData;
        int64_t previousRowIdx = -1;
    };
    std::vector<LogEntry> log;
    std::vector<LogicalChange> logicalChanges;
    std::vector<LockManager::PreparedLockInfo> locks;
};

static bool readPreparedRecord(const std::filesystem::path& path,
                               PreparedTransactionRecord& record);
static bool removePreparedFileDurably(const std::filesystem::path& target);

static std::string preparedHexEncode(const std::string& value) {
    if (value.empty()) return "-";
    static constexpr char hex[] = "0123456789abcdef";
    std::string result;
    result.reserve(value.size() * 2);
    for (const unsigned char byte : value) {
        result.push_back(hex[byte >> 4]);
        result.push_back(hex[byte & 0x0f]);
    }
    return result;
}

static bool preparedHexDecode(const std::string& value, std::string& result) {
    if (value == "-") {
        result.clear();
        return true;
    }
    if ((value.size() & 1U) != 0) return false;
    result.clear();
    result.reserve(value.size() / 2);
    const auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
        return -1;
    };
    for (size_t i = 0; i < value.size(); i += 2) {
        const int high = nibble(value[i]);
        const int low = nibble(value[i + 1]);
        if (high < 0 || low < 0) return false;
        result.push_back(static_cast<char>((high << 4) | low));
    }
    return true;
}

static void publishLogicalChanges(
    const std::string& database, const std::vector<LogicalChange>& changes,
    uint64_t xid,
    uint64_t commitLsn) {
    if (changes.empty()) return;

    LogicalChangeBatch batch;
    batch.xid = xid;
    batch.commitLsn = commitLsn;
    batch.changes.reserve(changes.size());
    for (auto change : changes) {
        change.xid = xid;
        change.commitLsn = commitLsn;
        batch.changes.push_back(std::move(change));
    }
    ReplicationManager::instance().publishLogicalBatch(database, batch);
}

static const char* preparedLockModeName(LockManager::LockMode mode) {
    switch (mode) {
        case LockManager::LockMode::Shared: return "shared";
        case LockManager::LockMode::Exclusive: return "exclusive";
        case LockManager::LockMode::IntentShared: return "IS";
        case LockManager::LockMode::IntentExclusive: return "IX";
        case LockManager::LockMode::Metadata: return "MDL";
    }
    return nullptr;
}

static bool parsePreparedLockMode(const std::string& value,
                                  LockManager::LockMode& mode) {
    if (value == "shared") mode = LockManager::LockMode::Shared;
    else if (value == "exclusive") mode = LockManager::LockMode::Exclusive;
    else if (value == "IS") mode = LockManager::LockMode::IntentShared;
    else if (value == "IX") mode = LockManager::LockMode::IntentExclusive;
    else if (value == "MDL") mode = LockManager::LockMode::Metadata;
    else return false;
    return true;
}

static bool validPhysicalBackupSource(
    const std::filesystem::path& source, std::string& sourceDatabase);

bool StorageEngine::recoverAllDatabases() {
    // A second embedded backend is not a process restart. It must not replay
    // an incomplete owner's image while that owner still retains its graph.
    if (anyDatabaseRollbackPending()) return false;
    if (!std::filesystem::exists(".") || !std::filesystem::is_directory(".")) {
        return true;
    }

    // A DDL snapshot is created before file-backed changes and is named with
    // its transaction ID. If the process dies before COMMIT cleanup, recover
    // it before opening relation caches: committed snapshots are disposable,
    // while in-progress/aborted snapshots restore the pre-DDL database.
    // DDL snapshots hold the database-wide exclusive transaction lock while
    // alive, so restoring one cannot erase a concurrent committed transaction.
    struct RecoveryForkState {
        uint64_t targetEpoch = 0;
        uint32_t sourceTimeline = 0;
        uint32_t targetTimeline = 0;
    };

    std::map<std::string, std::set<uint64_t>> committedXidsByDb;
    std::map<std::string, std::set<uint64_t>> abortedXidsByDb;
    std::map<std::string, std::set<uint64_t>> pitrExcludedXidsByDb;
    std::map<std::string, std::set<uint64_t>> preparedWalXidsByDb;
    std::map<std::string, std::map<uint64_t, uint8_t>> xactWalStateByDb;
    std::map<std::string, uint64_t> recoveryTargetsByDb;
    std::map<std::string, RecoveryForkState> recoveryForksByDb;
    std::map<std::string, bool> resetUnloggedByDb;
    std::set<std::pair<std::string, uint64_t>> inDoubtPreparedXids;
    std::map<std::pair<std::string, uint64_t>, std::filesystem::path> preparedFiles;
    std::map<std::pair<std::string, uint64_t>,
             std::vector<LockManager::PreparedLockInfo>> preparedLocksByTxn;
    // Use the same structural database check as DDL and enumeration. Backup
    // images have a physical-backup marker, whereas a quoted database name
    // may legitimately contain ".archive", ".txn_backup" or start with '.'.
    auto isDatabaseDirectory = [this](const std::string& name) {
        return databaseExists(name);
    };

    for (const auto& entry : std::filesystem::directory_iterator(
             ".", std::filesystem::directory_options::skip_permission_denied)) {
        std::string dbname;
        try {
            if (!entry.is_directory()) continue;
            dbname = entry.path().filename().string();
        } catch (...) { continue; }
        if (!isDatabaseDirectory(dbname)) continue;

        // Consume the previous process state before any recovery-side file
        // mutation. Missing state belongs to an older build and is treated
        // conservatively as an unclean stop. A malformed present marker is
        // corruption: guessing CLEAN could expose stale UNLOGGED rows.
        const UnloggedLifecycleState lifecycle =
            readUnloggedLifecycle(dbPath(dbname));
        if (lifecycle == UnloggedLifecycleState::Invalid) {
            std::cerr << "[recovery] invalid UNLOGGED lifecycle state for "
                      << dbname << std::endl;
            return false;
        }
        resetUnloggedByDb[dbname] =
            lifecycle != UnloggedLifecycleState::Clean;
        if (!writeUnloggedLifecycle(
                dbPath(dbname), kUnloggedLifecycleRunning)) {
            std::cerr << "[recovery] cannot publish running state for "
                      << dbname << std::endl;
            return false;
        }

        // REINDEX publishes each B+ tree together with its TDE sidecar. A
        // durable marker makes the multi-rename exchange recoverable before
        // WAL or any relation cache opens the potentially interrupted pair.
        std::vector<std::filesystem::path> reindexMarkers;
        std::vector<std::pair<std::string, std::filesystem::path>>
            orphanMarkerTemps;
        std::error_code markerScanError;
        for (std::filesystem::directory_iterator markerIt(
                 dbPath(dbname),
                 std::filesystem::directory_options::skip_permission_denied,
                 markerScanError), markerEnd;
             !markerScanError && markerIt != markerEnd;
             markerIt.increment(markerScanError)) {
            const std::string filename =
                markerIt->path().filename().string();
            const std::string suffix(kReindexSwapMarkerSuffix);
            if (filename.size() > suffix.size() + 1 && filename.front() == '.' &&
                filename.compare(
                    filename.size() - suffix.size(), suffix.size(), suffix) == 0) {
                reindexMarkers.push_back(markerIt->path());
            } else if (!filename.empty() && filename.front() == '.') {
                const size_t temporarySuffix =
                    filename.find(suffix + ".tmp.");
                if (temporarySuffix > 1 &&
                    temporarySuffix != std::string::npos) {
                    orphanMarkerTemps.emplace_back(
                        filename.substr(1, temporarySuffix - 1),
                        markerIt->path());
                }
            }
        }
        if (markerScanError) {
            std::cerr << "[recovery] cannot inspect REINDEX swaps for "
                      << dbname << std::endl;
            return false;
        }
        for (const auto& marker : reindexMarkers) {
            const std::string filename = marker.filename().string();
            const size_t tableLength =
                filename.size() - 1 - kReindexSwapMarkerSuffix.size();
            const std::string tableName = filename.substr(1, tableLength);
            lockManager_.setResourceNamespace(dbname);
            if (tableName.empty() ||
                !lockManager_.lockMetadata(tableName)) {
                std::cerr << "[recovery] invalid or unrecoverable REINDEX swap for "
                          << dbname << "/" << tableName << std::endl;
                return false;
            }
            ResourceUnlockGuard markerLockGuard(lockManager_, tableName);
            bool markerExists = false;
            const bool markerValid =
                inspectRegularFile(marker, markerExists);
            if (!markerValid ||
                (markerExists &&
                 (!tableExists(dbname, tableName) ||
                  !recoverReindexSwapMarker(
                      marker, relationDir(dbname, tableName), tableName)))) {
                std::cerr << "[recovery] invalid or unrecoverable REINDEX swap for "
                          << dbname << "/" << tableName << std::endl;
                return false;
            }
        }
        bool removedMarkerTemp = false;
        for (const auto& [tableName, temporary] : orphanMarkerTemps) {
            lockManager_.setResourceNamespace(dbname);
            if (!lockManager_.lockMetadata(tableName)) {
                std::cerr << "[recovery] cannot lock REINDEX marker temp "
                          << temporary << std::endl;
                return false;
            }
            ResourceUnlockGuard markerLockGuard(lockManager_, tableName);
            if (!removeRegularFileIfPresent(temporary)) {
                std::cerr << "[recovery] cannot remove REINDEX marker temp "
                          << temporary << std::endl;
                return false;
            }
            removedMarkerTemp = true;
        }
        if (removedMarkerTemp && !syncDirectoryDurably(dbPath(dbname))) {
            std::cerr << "[recovery] cannot sync REINDEX cleanup for "
                      << dbname << std::endl;
            return false;
        }

        const auto walPath = dbPath(dbname) / "pg_wal";
        const auto targetPath = walPath / "recovery_target";
        const auto forkPath = walPath / "recovery_fork";
        std::error_code targetError;
        bool hasTarget =
            std::filesystem::exists(targetPath, targetError);
        if (targetError) {
            std::cerr << "[recovery] cannot inspect PITR target for "
                      << dbname << std::endl;
            return false;
        }
        uint64_t targetEpoch = 0;
        if (hasTarget) {
            if (!std::filesystem::is_regular_file(targetPath, targetError) ||
                targetError) {
                std::cerr << "[recovery] PITR target is not a regular file for "
                          << dbname << std::endl;
                return false;
            }
            std::ifstream targetInput(targetPath);
            std::string targetToken;
            std::string trailingToken;
            if (!(targetInput >> targetToken) ||
                (targetInput >> trailingToken) || targetInput.bad() ||
                targetToken.empty() ||
                !std::all_of(targetToken.begin(), targetToken.end(),
                             [](unsigned char c) {
                                 return std::isdigit(c) != 0;
                             })) {
                std::cerr << "[recovery] invalid PITR target for "
                          << dbname << std::endl;
                return false;
            }
            try {
                size_t consumed = 0;
                targetEpoch = std::stoull(targetToken, &consumed);
                if (consumed != targetToken.size() || targetEpoch == 0)
                    throw std::invalid_argument("invalid target");
            } catch (...) {
                std::cerr << "[recovery] invalid PITR target for "
                          << dbname << std::endl;
                return false;
            }
        }

        WALManager* wal = getWAL(dbname);
        if (!wal) {
            std::cerr << "[recovery] cannot open WAL for " << dbname
                      << std::endl;
            return false;
        }

        std::error_code forkError;
        const bool hasFork = std::filesystem::exists(forkPath, forkError);
        if (forkError) {
            std::cerr << "[recovery] cannot inspect PITR fork state for "
                      << dbname << std::endl;
            return false;
        }
        if (hasFork) {
            if (!std::filesystem::is_regular_file(forkPath, forkError) ||
                forkError) {
                std::cerr << "[recovery] PITR fork state is not a regular file for "
                          << dbname << std::endl;
                return false;
            }
            std::ifstream forkInput(forkPath);
            std::string magic;
            std::string trailingToken;
            uint64_t forkTarget = 0;
            uint64_t sourceTimeline = 0;
            uint64_t targetTimeline = 0;
            if (!(forkInput >> magic >> forkTarget >> sourceTimeline >>
                  targetTimeline) ||
                (forkInput >> trailingToken) || forkInput.bad() ||
                magic != "DBMS_PITR_FORK_V1" || forkTarget == 0 ||
                sourceTimeline == 0 ||
                sourceTimeline > std::numeric_limits<uint32_t>::max() ||
                targetTimeline <= sourceTimeline ||
                targetTimeline > std::numeric_limits<uint32_t>::max()) {
                std::cerr << "[recovery] invalid PITR fork state for "
                          << dbname << std::endl;
                return false;
            }
            RecoveryForkState forkState{
                forkTarget, static_cast<uint32_t>(sourceTimeline),
                static_cast<uint32_t>(targetTimeline)};
            if (hasTarget && targetEpoch != forkState.targetEpoch) {
                std::cerr << "[recovery] PITR target and fork state disagree for "
                          << dbname << std::endl;
                return false;
            }

            if (wal->timelineId() == forkState.targetTimeline) {
                // Recovery reached the durable timeline switch and crashed
                // while consuming its marker(s).  Heap, CLOG and indexes were
                // flushed before the switch, so only idempotent cleanup is
                // left; replaying the abandoned source timeline would revive
                // transactions beyond the target.
                if (hasTarget && !removePreparedFileDurably(targetPath)) {
                    std::cerr << "[recovery] failed to consume completed PITR target for "
                              << dbname << std::endl;
                    return false;
                }
                if (!removePreparedFileDurably(forkPath)) {
                    std::cerr << "[recovery] failed to clear completed PITR fork state for "
                              << dbname << std::endl;
                    return false;
                }
                hasTarget = false;
                targetEpoch = 0;
            } else if (!hasTarget ||
                       wal->timelineId() != forkState.sourceTimeline) {
                std::cerr << "[recovery] PITR fork state has an unexpected timeline for "
                          << dbname << std::endl;
                return false;
            } else {
                recoveryForksByDb.emplace(dbname, forkState);
            }
        }

        if (hasTarget) recoveryTargetsByDb.emplace(dbname, targetEpoch);

        if (wal->currentWriteLsn() == 0) {
            if (hasTarget) {
                std::cerr << "[recovery] PITR target has no recoverable WAL for "
                          << dbname << std::endl;
                return false;
            }
            continue;
        }
        Lsn lsn = wal->earliestAvailableLsn();
        while (true) {
            auto recOpt = wal->ReadRecord(lsn);
            if (!recOpt || recOpt->header.xl_tot_len == 0) break;
            const XLogRecord& rec = *recOpt;
            if (rec.rmid() == RM_XACT_ID) {
                uint64_t xid = 0;
                if (!decodeXactWalRecord(rec, xid)) {
                    std::cerr << "[recovery] malformed transaction WAL record in "
                              << dbname << " at LSN " << lsn << std::endl;
                    return false;
                }
                auto& walState = xactWalStateByDb[dbname][xid];
                if (rec.info() == XLOG_XACT_PREPARE) {
                    if (walState != 0) {
                        std::cerr << "[recovery] duplicate or out-of-order PREPARE WAL for "
                                  << dbname << ":" << xid << std::endl;
                        return false;
                    }
                    walState = 0x01;
                    preparedWalXidsByDb[dbname].insert(xid);
                } else if (rec.info() == XLOG_XACT_COMMIT) {
                    if ((walState & 0x04) != 0 || (walState & 0x02) != 0) {
                        std::cerr << "[recovery] contradictory COMMIT WAL for "
                              << dbname << ":" << xid << std::endl;
                        return false;
                    }
                    walState |= 0x02;
                    const uint64_t targetEpoch =
                        recoveryTargetsByDb.count(dbname)
                            ? recoveryTargetsByDb[dbname]
                            : 0;
                    const uint64_t commitEpoch = commitEpochOf(rec);
                    const bool excludedByTarget =
                        targetEpoch != 0 && commitEpoch != 0 &&
                        commitEpoch > targetEpoch;
                    if (excludedByTarget) {
                        pitrExcludedXidsByDb[dbname].insert(xid);
                        committedXidsByDb[dbname].erase(xid);
                        abortedXidsByDb[dbname].insert(xid);
                    } else {
                        committedXidsByDb[dbname].insert(xid);
                        abortedXidsByDb[dbname].erase(xid);
                    }
                    preparedWalXidsByDb[dbname].erase(xid);
                } else {
                    // PREPARE -> ABORT is a valid two-phase decision.  Once a
                    // COMMIT record is durable, however, no later ABORT is
                    // legal for either a normal or a prepared transaction.
                    if ((walState & 0x04) != 0 ||
                        (walState & 0x02) != 0) {
                        std::cerr << "[recovery] contradictory ABORT WAL for "
                              << dbname << ":" << xid << std::endl;
                        return false;
                    }
                    walState |= 0x04;
                    abortedXidsByDb[dbname].insert(xid);
                    committedXidsByDb[dbname].erase(xid);
                    preparedWalXidsByDb[dbname].erase(xid);
                }
            }
            lsn += rec.header.xl_tot_len;
        }
    }

    const std::filesystem::path preparedDirPath = std::filesystem::path("info") / ".prepared";
    if (std::filesystem::exists(preparedDirPath)) {
        for (const auto& entry : std::filesystem::directory_iterator(preparedDirPath)) {
            if (!entry.is_regular_file()) {
                std::cerr << "[recovery] non-file entry in prepared directory: "
                          << entry.path() << std::endl;
                return false;
            }
            const std::string filename = entry.path().filename().string();
            // A crash between fsync(temp) and rename leaves an unreferenced
            // temporary file. It cannot represent a prepared transaction:
            // the target name is the durable transaction identifier.
            if (filename.find(".tmp.") != std::string::npos) {
                std::error_code ec;
                if (!std::filesystem::remove(entry.path(), ec) || ec) return false;
                continue;
            }
            if (filename.empty() || filename.size() > 200 ||
                !std::all_of(filename.begin(), filename.end(), [](unsigned char c) {
                    return std::isalnum(c) || c == '_' || c == '-' || c == '.' || c == ':';
                })) {
                std::cerr << "[recovery] invalid prepared transaction filename: "
                          << entry.path() << std::endl;
                return false;
            }
            PreparedTransactionRecord record;
            if (!readPreparedRecord(entry.path(), record) ||
                !isDatabaseDirectory(record.dbname)) {
                std::cerr << "[recovery] invalid prepared metadata: "
                          << entry.path() << std::endl;
                return false;
            }
            const uint64_t xid = record.txnId;
            const std::string dbname = record.dbname;
            const auto key = std::make_pair(dbname, xid);
            if (!preparedFiles.emplace(key, entry.path()).second) {
                std::cerr << "[recovery] duplicate prepared transaction metadata for xid "
                          << xid << std::endl;
                return false;
            }
            preparedLocksByTxn.emplace(key, std::move(record.locks));
        }
    }

    // A durable PREPARE WAL record without a durable prepared description is
    // not recoverable: the data must neither be silently committed nor
    // silently undone. Conversely, every prepared description must have a
    // matching PREPARE WAL record. Terminal COMMIT/ABORT records are allowed
    // to coexist with metadata because cleanup may have been interrupted.
    for (const auto& [dbname, xids] : preparedWalXidsByDb) {
        for (uint64_t xid : xids) {
            if (!preparedFiles.count({dbname, xid})) {
                std::cerr << "[recovery] PREPARE WAL has no prepared metadata for "
                          << dbname << ":" << xid << std::endl;
                return false;
            }
        }
    }
    for (const auto& [key, path] : preparedFiles) {
        (void)path;
        const auto& dbname = key.first;
        const uint64_t xid = key.second;
        const bool hasCommit = committedXidsByDb[dbname].count(xid) != 0;
        const bool hasAbort = abortedXidsByDb[dbname].count(xid) != 0;
        const bool hasPrepare = preparedWalXidsByDb[dbname].count(xid) != 0;
        if (hasCommit && hasAbort) {
            std::cerr << "[recovery] prepared transaction has both COMMIT and ABORT WAL: "
                      << dbname << ":" << xid << std::endl;
            return false;
        }
        if (hasPrepare && (hasCommit || hasAbort)) {
            std::cerr << "[recovery] prepared transaction has contradictory WAL state: "
                      << dbname << ":" << xid << std::endl;
            return false;
        }
        if (!hasCommit && !hasAbort) {
            // The prepared metadata remains authoritative after the PREPARE
            // WAL segment has been recycled by a checkpoint. Keep all page
            // before-images untouched until an explicit completion command.
            inDoubtPreparedXids.emplace(dbname, xid);
        }
    }

    // Prepared transactions survive backend/process restart. Keep their xids
    // in the same global active set used by ReadView construction so an old
    // prepared xid cannot be classified as committed merely because it is
    // below the next transaction boundary. Completion removes this entry.
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        for (const auto& [dbname, xid] : inDoubtPreparedXids) {
            activeTransactions().insert(xid);
            activeTransactionDatabases()[xid] = dbname;
        }
    }

    // Rebuild local and process-wide lock ownership before opening service
    // traffic. The prepared file is the durable source of truth after the
    // original backend/process has exited; failure to reacquire every lock is
    // unsafe because another backend could have modified the in-doubt data.
    for (const auto& [key, path] : preparedFiles) {
        (void)path;
        if (!inDoubtPreparedXids.count(key)) continue;
        const auto lockIt = preparedLocksByTxn.find(key);
        if (lockIt == preparedLocksByTxn.end() ||
            !lockManager_.restorePreparedLocks(key.second, key.first, lockIt->second)) {
            std::cerr << "[recovery] failed to restore prepared locks for "
                      << key.first << ":" << key.second << std::endl;
            return false;
        }
    }

    for (const auto& entry : std::filesystem::directory_iterator(
             ".", std::filesystem::directory_options::skip_permission_denied)) {
        std::string name;
        try {
            if (!entry.is_directory()) continue;
            name = entry.path().filename().string();
        } catch (...) { continue; }
        constexpr const char* marker = ".txn_backup.";
        const size_t markerPos = name.rfind(marker);
        if (markerPos == std::string::npos) continue;
        const std::string dbname = name.substr(0, markerPos);
        const std::string xidText = name.substr(markerPos + std::strlen(marker));
        if (!isDatabaseDirectory(dbname) || xidText.empty() ||
            !std::all_of(xidText.begin(), xidText.end(),
                         [](unsigned char c) { return std::isdigit(c) != 0; })) continue;
        uint64_t xid = 0;
        try { xid = std::stoull(xidText); } catch (...) { continue; }
        if (inDoubtPreparedXids.count({dbname, xid})) continue;

        const auto backup = entry.path();
        std::string backupDatabase;
        if (!validPhysicalBackupSource(backup, backupDatabase) ||
            backupDatabase != dbname) {
            // A user database can legitimately have a backup-shaped quoted
            // name. Never delete or restore it based on its name alone.
            continue;
        }
        // An explicit ABORT record is written and flushed after undo is
        // durable. A snapshot left behind after that terminal record is
        // disposable too: restoring it on a later startup can erase newer
        // non-transactional sequence advances. A commit excluded by PITR is
        // different and still needs its pre-transaction image restored.
        if (committedXidsByDb[dbname].count(xid) ||
            (abortedXidsByDb[dbname].count(xid) &&
             !pitrExcludedXidsByDb[dbname].count(xid))) {
            std::error_code ec;
            std::filesystem::remove_all(backup, ec);
            continue;
        }

        closeDatabaseCaches(dbname);
        if (physicalRestore(dbname, backup.string())) {
            std::error_code ec;
            std::filesystem::remove_all(backup, ec);
        }
    }

    // A statement image is only a nested atomicity aid. After a process
    // crash the transaction image above is authoritative, so a completely
    // published auxiliary generation is now stale and may be removed.
    for (const auto& entry : std::filesystem::directory_iterator(
             ".", std::filesystem::directory_options::skip_permission_denied)) {
        try {
            if (!entry.is_directory()) continue;
            const std::string name = entry.path().filename().string();
            constexpr const char* marker = ".ddl_statement_backup.";
            const size_t markerPos = name.rfind(marker);
            if (markerPos == std::string::npos || markerPos == 0) continue;
            const std::string dbname = name.substr(0, markerPos);
            const std::string suffix =
                name.substr(markerPos + std::strlen(marker));
            const size_t separator = suffix.find('.');
            if (separator == std::string::npos || separator == 0 ||
                separator + 1 >= suffix.size() ||
                suffix.find('.', separator + 1) != std::string::npos ||
                !std::all_of(suffix.begin(), suffix.begin() + separator,
                    [](unsigned char c) { return std::isdigit(c) != 0; }) ||
                !std::all_of(suffix.begin() + separator + 1, suffix.end(),
                    [](unsigned char c) { return std::isdigit(c) != 0; })) {
                continue;
            }
            std::string sourceDatabase;
            if (!validPhysicalBackupSource(
                    entry.path(), sourceDatabase) ||
                sourceDatabase != dbname) {
                continue;
            }
            std::error_code cleanupError;
            std::filesystem::remove_all(entry.path(), cleanupError);
        } catch (...) {
            continue;
        }
    }

    for (const auto& entry : std::filesystem::directory_iterator(".", std::filesystem::directory_options::skip_permission_denied)) {
        try {
            if (!entry.is_directory()) continue;
        } catch (...) { continue; }
        std::string dbname;
        try { dbname = entry.path().filename().string(); } catch (...) { continue; }
        if (!isDatabaseDirectory(dbname)) continue;

        WALManager* wal = getWAL(dbname);
        if (!wal) continue;
        const auto preparedForDatabase = inDoubtPreparedXids.lower_bound(
            {dbname, 0});
        const bool preservePreparedIndexState =
            preparedForDatabase != inDoubtPreparedXids.end() &&
            preparedForDatabase->first == dbname;
        const bool resetUnlogged =
            !resetUnloggedByDb.count(dbname) || resetUnloggedByDb.at(dbname);
        const auto prepareUnloggedTables = [&]() -> bool {
            try {
                for (const auto& tableName : getTableNames(dbname)) {
                    if (isSessionTempPhysicalName(tableName)) continue;
                    const TableSchema table =
                        getTableSchema(dbname, tableName);
                    if (!table.isUnlogged) continue;
                    if (!ensureUnloggedInitForks(dbname, tableName)) {
                        std::cerr
                            << "[recovery] failed to prepare UNLOGGED init forks for "
                            << dbname << "/" << tableName << std::endl;
                        return false;
                    }
                    if (resetUnlogged &&
                        !resetTableStorage(dbname, tableName)) {
                        std::cerr
                            << "[recovery] failed to reset UNLOGGED table "
                            << dbname << "/" << tableName << std::endl;
                        return false;
                    }
                }
                return true;
            } catch (const std::exception& error) {
                std::cerr
                    << "[recovery] failed to enumerate unlogged tables for "
                    << dbname << ": " << error.what() << std::endl;
                return false;
            } catch (...) {
                std::cerr
                    << "[recovery] failed to enumerate unlogged tables for "
                    << dbname << std::endl;
                return false;
            }
        };
        if (wal->currentWriteLsn() == 0) {
            if (!prepareUnloggedTables()) return false;
            if (!preservePreparedIndexState &&
                !rebuildAllSpecializedIndexes(dbname)) {
                std::cerr
                    << "[recovery] failed to rebuild specialized indexes for "
                    << dbname << std::endl;
                return false;
            }
            continue; // no WAL to replay
        }

        // A persisted PITR target (written by pitrRestore in the previous
        // process) gates this database's commit replay. Target parsing and
        // validation happened before the transaction-state pre-scan.
        const uint64_t recoveryTarget =
            recoveryTargetsByDb.count(dbname)
                ? recoveryTargetsByDb.at(dbname)
                : 0;
        if (recoveryTarget != 0) {
            recoveryTargetEpoch_.store(recoveryTarget);
            std::cerr << "[recovery] " << dbname
                      << ": PITR target epoch " << recoveryTarget << std::endl;
        }

        auto checkpointLsnOpt = wal->findLastCheckpointLsn();
        // The newest archived checkpoint may itself be later than a PITR
        // target. Start from the oldest retained WAL in target mode so every
        // post-target transaction still has its before-image available for
        // undo. Ordinary crash recovery keeps the checkpoint fast path.
        Lsn redoLsn = recoveryTarget != 0
            ? wal->earliestAvailableLsn()
            : checkpointLsnOpt.value_or(wal->earliestAvailableLsn());
        // Pass 1: collect committed transaction IDs and update CLOG.
        std::set<uint64_t> committedXids = committedXidsByDb[dbname];
        std::vector<Lsn> redoRecordLsns;
        std::map<std::string, Lsn> latestTruncateLsns;
        std::map<uint64_t, Lsn> latestIdentityTruncateLsns;
        bool needsIndexRebuild = false;
        {
            Lsn lsn = redoLsn;
            while (true) {
                auto recOpt = wal->ReadRecord(lsn);
                if (!recOpt || recOpt->header.xl_tot_len == 0) break;
                const XLogRecord& rec = *recOpt;
                redoRecordLsns.push_back(lsn);
                uint8_t rmid = rec.rmid();
                uint8_t info = rec.info();
                if (rmid == RM_XACT_ID) {
                    uint64_t xid = 0;
                    if (!decodeXactWalRecord(rec, xid)) {
                        std::cerr
                            << "[recovery] malformed transaction WAL record in "
                            << dbname << " at LSN " << lsn << std::endl;
                        return false;
                    }
                    CommitLog* clog = getCommitLog(dbname);
                    if (info == XLOG_XACT_COMMIT) {
                        if (pitrExcludedXidsByDb[dbname].count(xid)) {
                            committedXids.erase(xid);
                            if (clog) {
                                clog->setStatus(
                                    xid, CommitLog::Status::Aborted);
                            }
                        } else {
                            committedXids.insert(xid);
                            if (clog) {
                                clog->setStatus(
                                    xid, CommitLog::Status::Committed);
                            }
                        }
                    } else if (info == XLOG_XACT_ABORT) {
                        committedXids.erase(xid);
                        if (clog) {
                            clog->setStatus(xid, CommitLog::Status::Aborted);
                        }
                    }
                } else if (rmid == RM_CHECKPOINT_ID) {
                    {
                        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
                        lastCheckpointLsns_[dbname] = lsn;
                    }
                } else if (rmid == RM_SMGR_ID &&
                           info == XLOG_SMGR_TRUNCATE) {
                    std::string tableName;
                    std::optional<uint64_t> identity;
                    if (rec.header.xl_xid != 0 ||
                        !decodeTruncateWalPayload(rec.data, tableName, identity)) {
                        std::cerr
                            << "[recovery] malformed TRUNCATE WAL record in "
                            << dbname << " at LSN " << lsn << std::endl;
                        return false;
                    }
                    if (identity) latestIdentityTruncateLsns[*identity] = lsn;
                    else latestTruncateLsns[tableName] = lsn;
                    needsIndexRebuild = true;
                }
                if (rec.header.xl_xid != 0 &&
                    (rmid == RM_HEAP_ID || rmid == RM_INDEX_ID) &&
                    !committedXidsByDb[dbname].count(rec.header.xl_xid) &&
                    ((!abortedXidsByDb[dbname].count(rec.header.xl_xid) &&
                      !inDoubtPreparedXids.count(
                          {dbname, rec.header.xl_xid})) ||
                     pitrExcludedXidsByDb[dbname].count(
                         rec.header.xl_xid))) {
                    needsIndexRebuild = true;
                }
                lsn += rec.header.xl_tot_len;
            }
        }
        // Make the visibility decisions durable before replaying heap/index
        // images. Recovery must fail closed if CLOG cannot be persisted.
        if (CommitLog* clog = getCommitLog(dbname); clog && !clog->flush()) {
            std::cerr << "[recovery] failed to persist CLOG for database "
                      << dbname << std::endl;
            return false;
        }

        // Relation names are mutable and can be reused. Resolve new images
        // through the current durable schema identity, never through a
        // guessed old basename. Retained lifecycle WAL is the only authority
        // for discarding images whose physical generation no longer exists.
        std::map<uint64_t, std::string> physicalRelations;
        for (const auto& name : getTableNames(dbname)) {
            // Stale session TEMP names/forks are removed only after recovery.
            // Their schemas may never have become durable; they have no
            // persistent relation generation to replay or index to rebuild.
            if (isSessionTempPhysicalName(name)) continue;
            const TableSchema schema = getTableSchema(dbname, name);
            if (schema.tablename != name) return false;
            if (schema.physicalRelationId != 0 &&
                !physicalRelations.emplace(schema.physicalRelationId, name).second) {
                std::cerr << "[recovery] duplicate physical relation identity in "
                          << dbname << '\n';
                return false;
            }
        }
        std::map<uint64_t, std::pair<uint64_t, Lsn>> relationBirths;
        struct RetirementIntent {
            uint64_t xid;
            Lsn lsn;
            std::string name;
        };
        std::map<uint64_t, RetirementIntent> retirementIntents;
        std::map<uint64_t, Lsn> committedRetirements;
        uint64_t relationHighwater = 1;
        for (const auto& [identity, name] : physicalRelations) {
            (void)name;
            if (identity == std::numeric_limits<uint64_t>::max()) return false;
            relationHighwater = std::max(relationHighwater, identity + 1);
        }
        for (Lsn historyLsn = wal->earliestAvailableLsn();;) {
            auto record = wal->ReadRecord(historyLsn);
            if (!record || record->header.xl_tot_len == 0) break;
            if (record->rmid() == RM_SMGR_ID &&
                (record->info() == XLOG_SMGR_RELATION_CREATE ||
                 record->info() == XLOG_SMGR_RELATION_RETIRE ||
                 record->info() == XLOG_SMGR_RELATION_RETIRE_COMPLETE)) {
                heap_wal_identity::Event event;
                if (!heap_wal_identity::event(*record, event) ||
                    !validStoredRelationName(event.name) ||
                    event.relationId == std::numeric_limits<uint64_t>::max()) {
                    std::cerr << "[recovery] invalid relation identity event in "
                              << dbname << " at LSN " << historyLsn << '\n';
                    return false;
                }
                relationHighwater = std::max(relationHighwater, event.relationId + 1);
                if (record->info() == XLOG_SMGR_RELATION_CREATE) {
                    if (!relationBirths.emplace(event.relationId,
                            std::make_pair(record->header.xl_xid, historyLsn)).second)
                        return false;
                } else if (record->info() == XLOG_SMGR_RELATION_RETIRE) {
                    retirementIntents[event.relationId] = {
                        record->header.xl_xid, historyLsn, event.name};
                } else {
                    const auto intent = retirementIntents.find(event.relationId);
                    if (intent == retirementIntents.end() ||
                        intent->second.xid != record->header.xl_xid ||
                        intent->second.name != event.name ||
                        intent->second.lsn >= historyLsn) {
                        std::cerr << "[recovery] retirement completion without matching intent in "
                                  << dbname << " at LSN " << historyLsn << '\n';
                        return false;
                    }
                    if (record->header.xl_xid == 0 ||
                        committedXids.count(record->header.xl_xid)) {
                        committedRetirements[event.relationId] = historyLsn;
                    }
                }
            }
            historyLsn += record->header.xl_tot_len;
        }
        if (relationHighwater > 1) {
            const std::filesystem::path counter = ".physical_relation_ids";
            ToastCounterFileLock identityLock(counter);
            uint64_t clusterFloor = 0, databaseFloor = 0;
            const auto databaseCounter = dbPath(dbname) / ".physical_relation_id_highwater";
            if (!identityLock.ok() || !readPhysicalRelationCounter(counter, clusterFloor) ||
                !readPhysicalRelationCounter(databaseCounter, databaseFloor) ||
                (relationHighwater > clusterFloor &&
                 !persistPhysicalRelationCounter(counter, relationHighwater)) ||
                (relationHighwater > databaseFloor &&
                !persistPhysicalRelationCounter(databaseCounter, relationHighwater))) return false;
        }
        for (const auto& [name, boundary] : latestTruncateLsns) {
            (void)boundary;
            if (getTableSchema(dbname, name).physicalRelationId != 0) return false;
        }
        for (const auto& [identity, truncateLsn] : latestIdentityTruncateLsns) {
            const auto live = physicalRelations.find(identity);
            if (live != physicalRelations.end()) {
                auto& boundary = latestTruncateLsns[live->second];
                boundary = std::max(boundary, truncateLsn);
            } else {
                const auto retirement = committedRetirements.find(identity);
                if (retirement == committedRetirements.end() ||
                    retirement->second <= truncateLsn) return false;
            }
        }

        // A truncate record is write-ahead of the multi-file reset.  The
        // durable sidecar is published only after every heap/index/TOAST
        // file and the relation directory have been synced.  Missing or
        // older state therefore means startup must finish the interrupted
        // reset before applying records newer than the truncate boundary.
        for (const auto& [tableName, truncateLsn] : latestTruncateLsns) {
            if (!tableExists(dbname, tableName)) continue;
            Lsn appliedLsn = INVALID_LSN;
            const TruncateStateRead state = readTruncateState(
                *this, dbname, tableName, appliedLsn);
            if (state == TruncateStateRead::Invalid) {
                std::cerr << "[recovery] invalid TRUNCATE state for "
                          << dbname << "/" << tableName << std::endl;
                return false;
            }
            if (state == TruncateStateRead::Missing ||
                appliedLsn < truncateLsn) {
                if (!resetTableStorage(dbname, tableName) ||
                    !persistTruncateState(
                        *this, dbname, tableName, truncateLsn)) {
                    std::cerr
                        << "[recovery] could not complete TRUNCATE for "
                        << dbname << "/" << tableName << std::endl;
                    return false;
                }
            }
        }

        // Pass 2: replay committed/non-transactional images in WAL order.
        // Uncommitted before-images are intentionally deferred to the reverse
        // pass below. If one transaction changes a page more than once, its
        // before-images must be applied newest-to-oldest to restore the state
        // that existed before the transaction began.
        auto applyImageRecord = [&](const XLogRecord& rec, Lsn recordLsn,
                                    bool undoUncommitted) -> bool {
            const uint8_t rmid = rec.rmid();
            const uint8_t info = rec.info();
            const uint64_t recXid = rec.header.xl_xid;
            std::string resolvedHeapName;
            if (rmid == RM_HEAP_ID) {
                std::string tableName;
                if (!decodeHeapWalTableName(rec, tableName)) {
                    std::cerr << "[recovery] " << dbname << " LSN "
                              << recordLsn
                              << ": malformed heap relation name\n";
                    return false;
                }
                resolvedHeapName = tableName;
                if (info == XLOG_HEAP_PAGE_BEFORE || info == XLOG_HEAP_PAGE_AFTER) {
                    std::optional<uint64_t> identity;
                    if (!heap_wal_identity::image(rec, identity)) return false;
                    if (identity) {
                        const auto live = physicalRelations.find(*identity);
                        if (live != physicalRelations.end()) {
                            resolvedHeapName = live->second;
                        } else {
                            const auto retirement = committedRetirements.find(*identity);
                            if (retirement != committedRetirements.end() &&
                                recordLsn < retirement->second) return true;
                            const auto birth = relationBirths.find(*identity);
                            if (birth != relationBirths.end() && birth->second.first != 0 &&
                                birth->second.first == recXid && birth->second.second < recordLsn &&
                                !committedXids.count(recXid) &&
                                !inDoubtPreparedXids.count({dbname, recXid})) return true;
                            std::cerr << "[recovery] missing live physical relation identity "
                                      << *identity << " in " << dbname << '\n';
                            return false;
                        }
                    } else if (getTableSchema(dbname, tableName).physicalRelationId != 0) {
                        // A name-only image cannot be safely assigned to a
                        // later generation which happens to reuse its name.
                        return false;
                    }
                }
                const auto truncate = latestTruncateLsns.find(resolvedHeapName);
                if (truncate != latestTruncateLsns.end() &&
                    recordLsn <= truncate->second) {
                    return true;
                }
            }
            bool shouldApply = false;
            if (undoUncommitted) {
                shouldApply = recXid != 0 && !committedXids.count(recXid) &&
                              !inDoubtPreparedXids.count({dbname, recXid}) &&
                              ((rmid == RM_HEAP_ID && info == XLOG_HEAP_PAGE_BEFORE) ||
                               (rmid == RM_INDEX_ID && info == XLOG_INDEX_FILE_BEFORE));
            } else if (rmid == RM_HEAP_ID) {
                if (info == XLOG_HEAP_PAGE_AFTER) {
                    shouldApply = recXid == 0 || committedXids.count(recXid);
                } else if (info == XLOG_HEAP_PAGE_BEFORE) {
                    // xid 0 is used by non-transactional maintenance. Its
                    // before/after pair is replayed in WAL order.
                    shouldApply = recXid == 0;
                }
            } else if (rmid == RM_INDEX_ID) {
                if (info == XLOG_INDEX_FILE_AFTER) {
                    shouldApply = recXid == 0 || committedXids.count(recXid);
                } else if (info == XLOG_INDEX_FILE_BEFORE) {
                    shouldApply = recXid == 0;
                }
            }
            if (!shouldApply) return true;

            if (rmid == RM_INDEX_ID) {
                const char* p = rec.data.data();
                const char* end = p + rec.data.size();
                uint32_t pathLen = 0;
                uint64_t imageLen = 0;
                constexpr uint32_t kMaxIndexPathLen = 4096;
                constexpr uint64_t kMaxIndexWalImage = 256ULL * 1024ULL * 1024ULL;
                auto fail = [&](const char* reason) {
                    std::cerr << "[recovery] " << dbname << " LSN " << recordLsn
                              << ": invalid index WAL image (" << reason << ")\n";
                    return false;
                };
                if (static_cast<size_t>(end - p) < sizeof(pathLen)) {
                    return fail("missing path length");
                }
                std::memcpy(&pathLen, p, sizeof(pathLen));
                p += sizeof(pathLen);
                if (pathLen == 0 || pathLen > kMaxIndexPathLen ||
                    static_cast<size_t>(end - p) < pathLen) {
                    return fail("invalid path length");
                }
                const std::string pathText(p, pathLen);
                p += pathLen;
                if (static_cast<size_t>(end - p) < sizeof(imageLen)) {
                    return fail("missing image length");
                }
                std::memcpy(&imageLen, p, sizeof(imageLen));
                p += sizeof(imageLen);
                const size_t trailingBytes = static_cast<size_t>(end - p) -
                    std::min<uint64_t>(imageLen, static_cast<uint64_t>(end - p));
                const char* trailing = p + static_cast<size_t>(
                    std::min<uint64_t>(imageLen, static_cast<uint64_t>(end - p)));
                const bool paddingIsZero = std::all_of(
                    trailing, end, [](char byte) { return byte == 0; });
                if (imageLen > kMaxIndexWalImage ||
                    imageLen > static_cast<uint64_t>(end - p) ||
                    trailingBytes > 7 || !paddingIsZero) {
                    return fail("invalid image length");
                }

                const std::filesystem::path indexPath(pathText);
                std::error_code pathEc;
                const auto canonicalPath = std::filesystem::weakly_canonical(
                    indexPath, pathEc);
                if (pathEc) {
                    return fail("path cannot be canonicalized");
                }
                std::error_code rootEc;
                const auto databaseRoot = std::filesystem::weakly_canonical(
                    dbPath(dbname), rootEc);
                auto isWithinRoot = [](const std::filesystem::path& child,
                                       const std::filesystem::path& root) {
                    const auto relative = child.lexically_relative(root);
                    if (relative.empty() || relative == ".") return false;
                    const auto first = relative.begin();
                    return first == relative.end() || first->string() != "..";
                };
                bool pathAllowed = !rootEc && isWithinRoot(canonicalPath, databaseRoot);
                if (!pathAllowed && !rootEc) {
                    const auto markerDir = dbPath(dbname) / "pg_tblspc";
                    std::error_code markerEc;
                    if (std::filesystem::exists(markerDir, markerEc) && !markerEc) {
                        for (const auto& marker : std::filesystem::directory_iterator(
                                 markerDir, std::filesystem::directory_options::skip_permission_denied)) {
                            if (marker.path().extension() != ".path") continue;
                            std::filesystem::path location;
                            if (!readTablespaceMarker(marker.path(), location)) {
                                return fail("invalid tablespace marker");
                            }
                            std::error_code tablespaceEc;
                            const auto tablespaceRoot = std::filesystem::weakly_canonical(
                                location / dbname, tablespaceEc);
                            if (!tablespaceEc && isWithinRoot(canonicalPath, tablespaceRoot)) {
                                pathAllowed = true;
                                break;
                            }
                        }
                    }
                }
                if (!pathAllowed) {
                    return fail("path escapes database directory");
                }
                const std::string filename = canonicalPath.filename().string();
                const std::string extension = canonicalPath.extension().string();
                const bool isIndexFile = extension == ".idx" ||
                    extension == ".hidx" || extension == ".bidx" ||
                    extension == ".fti" ||
                    extension == ".gin" || extension == ".gist" ||
                    extension == ".spgist" || extension == ".brin" ||
                    extension.rfind(".idx_", 0) == 0;
                if (filename.empty() || !isIndexFile) {
                    return fail("path is not an index relation");
                }
                // Indexes are derived data and commit/prepare fsyncs them
                // before publishing the terminal WAL record.  An image is a
                // checkpoint-epoch baseline rather than a per-transaction
                // state: replaying it can overwrite commits made later in the
                // same epoch.  Validate every applicable legacy image here,
                // retain the newest physical file for terminal transactions,
                // and rebuild below if an abandoned xid may have dirtied it.
                return true;
            }

            const bool force = info == XLOG_HEAP_PAGE_BEFORE;
            const bool applied = RedoApplyRecord(rec,
                [&, force, recordLsn](const std::string& tableName, uint32_t blockNum,
                                      uint32_t forkNum, const char* pageData,
                                      size_t pageLen) {
                    return redoPageImage(dbname,
                                         resolvedHeapName.empty() ? tableName : resolvedHeapName,
                                         blockNum, pageData,
                                         pageLen, recordLsn, force, forkNum);
                },
                [](const std::string&, uint32_t, uint32_t, uint16_t,
                   const char*, size_t) { return true; },
                [](const std::string&, uint32_t, uint32_t, uint16_t,
                   uint64_t) { return true; },
                [](const std::string&, uint32_t, uint32_t, uint16_t,
                   uint32_t, uint32_t, uint16_t, const char*, size_t) {
                    return true;
                });
            if (!applied) {
                std::cerr << "[recovery] " << dbname << " LSN " << recordLsn
                          << ": heap WAL image could not be parsed or applied\n";
            }
            return applied;
        };

        bool recoveryOk = true;
        for (Lsn recordLsn : redoRecordLsns) {
            auto recOpt = wal->ReadRecord(recordLsn);
            if (!recOpt || !applyImageRecord(*recOpt, recordLsn, false)) {
                recoveryOk = false;
                break;
            }
        }
        if (recoveryOk) {
            for (auto it = redoRecordLsns.rbegin(); it != redoRecordLsns.rend(); ++it) {
                auto recOpt = wal->ReadRecord(*it);
                if (!recOpt || !applyImageRecord(*recOpt, *it, true)) {
                    recoveryOk = false;
                    break;
                }
            }
        }
        if (recoveryOk) {
            // A loser's full-page before-image can predate a later committed
            // transaction on the same heap page. The reverse undo pass
            // necessarily restores that older image, so replay winners once
            // more in WAL order to retain every later durable commit.
            for (Lsn recordLsn : redoRecordLsns) {
                auto recOpt = wal->ReadRecord(recordLsn);
                if (!recOpt ||
                    !applyImageRecord(*recOpt, recordLsn, false)) {
                    recoveryOk = false;
                    break;
                }
            }
        }
        if (!recoveryOk) {
            std::cerr << "[recovery] startup aborted for database " << dbname
                      << " because WAL replay was incomplete\n";
            return false;
        }

        // COMMIT/ROLLBACK PREPARED may have made its terminal WAL record
        // durable immediately before a crash, but failed before deleting the
        // prepared metadata. Once redo/undo is complete, remove only those
        // terminal records. In-doubt records remain discoverable for an
        // explicit administrative decision.
        for (const auto& [key, preparedPath] : preparedFiles) {
            if (key.first != dbname) continue;
            if (!committedXidsByDb[dbname].count(key.second) &&
                !abortedXidsByDb[dbname].count(key.second)) continue;
            if (!removePreparedFileDurably(preparedPath)) {
                std::cerr << "[recovery] failed to remove terminal prepared metadata: "
                          << preparedPath << std::endl;
                return false;
            }
        }

        // Flush recovered pages.
        for (const auto& [key, pa] : pageAllocators_) {
            if (key.rfind(dbname + "/", 0) == 0) {
                if (!pa->flush()) {
                    std::cerr << "[recovery] failed to flush recovered heap for "
                              << key << std::endl;
                    return false;
                }
            }
        }
        if (needsIndexRebuild &&
            !rebuildIndexesAfterRecovery(
                dbname, preservePreparedIndexState)) {
            std::cerr << "[recovery] failed to rebuild indexes for database "
                      << dbname << std::endl;
            return false;
        }

        // A clean restart preserves UNLOGGED main forks. After an unclean
        // stop, restore every heap from its durable empty init fork and reset
        // indexes/TOAST together so no access method retains a stale RID.
        if (!prepareUnloggedTables()) return false;
        // Specialized indexes are derivable whole-file sidecars and do not
        // emit per-row WAL. Rebuild them on every startup to close both an
        // interrupted replacement and a crash after heap WAL became durable.
        // An in-doubt prepared xid can own a suspended table lock, so leave
        // its phase-one sidecar state untouched until phase two decides it.
        if (!preservePreparedIndexState &&
            !rebuildAllSpecializedIndexes(dbname)) {
            std::cerr
                << "[recovery] failed to rebuild specialized indexes for "
                << dbname << std::endl;
            return false;
        }

        // A recovery target is single-use, but the source timeline still
        // contains COMMIT records beyond that target.  Fork a new timeline
        // before consuming the target so later crash recovery cannot replay
        // those records and resurrect discarded rows.  The durable fork
        // marker makes both sides of the two-file transition retryable.
        if (recoveryTarget != 0) {
            const auto targetPath =
                dbPath(dbname) / "pg_wal" / "recovery_target";
            const auto forkPath =
                dbPath(dbname) / "pg_wal" / "recovery_fork";
            RecoveryForkState forkState;
            if (const auto existing = recoveryForksByDb.find(dbname);
                existing != recoveryForksByDb.end()) {
                forkState = existing->second;
            } else {
                const uint32_t sourceTimeline = wal->timelineId();
                uint32_t highestTimeline = sourceTimeline;
                std::error_code timelineError;
                for (const auto& entry : std::filesystem::directory_iterator(
                         targetPath.parent_path(),
                         std::filesystem::directory_options::skip_permission_denied,
                         timelineError)) {
                    if (timelineError) break;
                    std::error_code entryError;
                    if (!entry.is_regular_file(entryError) || entryError)
                        continue;
                    const std::string name = entry.path().filename().string();
                    if (name.size() != 24) continue;
                    try {
                        size_t consumed = 0;
                        const unsigned long parsed = std::stoul(
                            name.substr(0, 8), &consumed, 16);
                        if (consumed == 8 &&
                            parsed <= std::numeric_limits<uint32_t>::max()) {
                            highestTimeline = std::max(
                                highestTimeline,
                                static_cast<uint32_t>(parsed));
                        }
                    } catch (...) {
                        continue;
                    }
                }
                if (timelineError ||
                    highestTimeline == std::numeric_limits<uint32_t>::max()) {
                    std::cerr << "[recovery] cannot allocate a PITR timeline for "
                              << dbname << std::endl;
                    return false;
                }
                forkState = {recoveryTarget, sourceTimeline,
                             static_cast<uint32_t>(highestTimeline + 1)};
            }
            if (forkState.targetEpoch != recoveryTarget ||
                wal->timelineId() != forkState.sourceTimeline) {
                std::cerr << "[recovery] PITR fork state changed unexpectedly for "
                          << dbname << std::endl;
                return false;
            }
            std::ostringstream forkContents;
            forkContents << "DBMS_PITR_FORK_V1\n"
                         << forkState.targetEpoch << ' '
                         << forkState.sourceTimeline << ' '
                         << forkState.targetTimeline << '\n';
            if (!index_file::writeAtomically(forkPath,
                                             forkContents.str())) {
                std::cerr << "[recovery] failed to persist PITR fork state for "
                          << dbname << std::endl;
                return false;
            }
            if (!wal->setTimeline(forkState.targetTimeline)) {
                std::cerr << "[recovery] failed to fork WAL timeline for "
                          << dbname << std::endl;
                return false;
            }
            if (!removePreparedFileDurably(targetPath)) {
                std::cerr << "[recovery] failed to consume PITR target for "
                          << dbname << std::endl;
                return false;
            }
            if (!removePreparedFileDurably(forkPath)) {
                std::cerr << "[recovery] failed to clear PITR fork state for "
                          << dbname << std::endl;
                return false;
            }
            recoveryTargetEpoch_.store(0);
        }
    }
    return true;
}

// ========================================================================
// ReadView refresh (READ COMMITTED and its READ UNCOMMITTED alias)
// ========================================================================
void StorageEngine::refreshReadView() const {
    if (!transactionContext().inTransaction) return;
    std::lock_guard<std::mutex> lock(globalTxnMutex());
    transactionContext().readView.creatorTxnId = transactionContext().currentTxnId;
    transactionContext().readView.upLimitId = activeTransactions().empty() ? transactionContext().currentTxnId : *activeTransactions().begin();
    transactionContext().readView.lowLimitId = TxnIdGenerator::instance().maxCommittedTxId() + 1;
    transactionContext().readView.activeTxnIds = activeTransactions();
    transactionContext().readView.activeTxnIds.erase(transactionContext().currentTxnId);
    transactionContext().readView.subTxnIds.clear();
    transactionContext().readView.subTxnIds.insert(transactionContext().txnSubTxnIds.begin(), transactionContext().txnSubTxnIds.end());
    transactionContext().readView.commitLog = transactionContext().databaseOwnershipDeferred
        ? nullptr : getCommitLog(transactionContext().txnDB);
    transactionContext().snapshotAcquired = true;
}

void StorageEngine::ensureTransactionSnapshot() const {
    if (transactionContext().inTransaction &&
        !transactionContext().snapshotAcquired) {
        refreshReadView();
    }
}

// ========================================================================
// Snapshot export/import
// ========================================================================
std::string StorageEngine::exportSnapshot() const {
    auto& context = transactionContext();
    if (!context.inTransaction || context.txnDB.empty() ||
        (context.txnIsolationLevel != IsolationLevel::REPEATABLE_READ &&
         context.txnIsolationLevel != IsolationLevel::SERIALIZABLE)) return "";
    ensureTransactionSnapshot();
    Snapshot snap;
    snap.version = 2;
    snap.database = context.txnDB;
    snap.xmin = context.readView.upLimitId;
    snap.xmax = context.readView.lowLimitId;
    snap.curCid = context.currentCommandId;
    snap.activeXids.assign(context.readView.activeTxnIds.begin(), context.readView.activeTxnIds.end());
    // Own writes are visible in the live view, but the exporter was in
    // progress for every importing owner. XIDs beyond this retained xmax
    // (for example when re-exporting an imported snapshot) are excluded already.
    if (context.currentTxnId < snap.xmax) {
        const auto position = std::lower_bound(snap.activeXids.begin(), snap.activeXids.end(), context.currentTxnId);
        if (position == snap.activeXids.end() || *position != context.currentTxnId)
            snap.activeXids.insert(position, context.currentTxnId);
    }
    snap.subxip.assign(context.readView.subTxnIds.begin(), context.readView.subTxnIds.end());
    return snap.exportToBytes();
}

bool StorageEngine::importSnapshot(const std::string& bytes) {
    auto& context = transactionContext();
    if (!context.inTransaction || context.txnDB.empty() || context.snapshotImported ||
        context.hasRead || context.hasWrite || !context.txnLog.empty() ||
        !context.ddlUndoActions.empty() || !context.txnBackupPath.empty() ||
        (context.txnIsolationLevel != IsolationLevel::REPEATABLE_READ &&
         context.txnIsolationLevel != IsolationLevel::SERIALIZABLE)) return false;
    auto snapOpt = Snapshot::importFromBytes(bytes);
    if (!snapOpt) return false;
    const Snapshot& snap = *snapOpt;
    if (snap.database != context.txnDB) return false;
    context.readView.creatorTxnId = context.currentTxnId;
    context.readView.upLimitId = snap.xmin;
    context.readView.lowLimitId = snap.xmax;
    context.readView.activeTxnIds.clear();
    context.readView.activeTxnIds.insert(snap.activeXids.begin(), snap.activeXids.end());
    context.readView.subTxnIds.clear();
    context.readView.subTxnIds.insert(snap.subxip.begin(), snap.subxip.end());
    context.readView.commitLog = getCommitLog(context.txnDB);
    context.snapshotImported = true;
    context.snapshotAcquired = true;
    context.querySnapshotUsed = true;
    return true;
}

// ========================================================================
// Catalog snapshot: lazy cache for consistent schema/table list view
// ========================================================================
void StorageEngine::captureCatalogSnapshot() {
    std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
    transactionContext().catalogSnapshot.emplace();
    transactionContext().catalogSnapshot->schemas.clear();
    transactionContext().catalogSnapshot->tableNames.clear();
}

void StorageEngine::clearCatalogSnapshot() {
    std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
    transactionContext().catalogSnapshot.reset();
}

void StorageEngine::invalidateCatalogSchema(const std::string& dbname,
                                            const std::string& tablename) {
    invalidateCachedSchema(dbname, tablename);
    std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
    if (transactionContext().catalogSnapshot) {
        transactionContext().catalogSnapshot->schemas.erase(std::make_pair(dbname, tablename));
    }
}

// Serialize first, then atomically publish the complete table schema. All DDL
// schema rewrites must go through here: a partial file or stale parsed-schema
// cache would expose the wrong table definition to subsequent statements.
bool StorageEngine::writeSchemaFile(const std::string& dbname,
                                    const std::string& tablename,
                                    const TableSchema& tbl) {
    std::ostringstream output(std::ios::out | std::ios::binary);
    writeSchema(output, tbl);
    if (!output) return false;
    if (!index_file::writeAtomically(
            schemaPath(dbname, tablename), output.str())) {
        return false;
    }
    invalidateCatalogSchema(dbname, tablename);
    return true;
}

void StorageEngine::invalidateCatalogTableList(const std::string& dbname) {
    std::lock_guard<std::mutex> lock(catalogSnapshotMutex_);
    if (transactionContext().catalogSnapshot) {
        transactionContext().catalogSnapshot->tableNames.erase(dbname);
    }
}

// ========================================================================
// Checkpoint: flush all dirty pages and persist a checkpoint record.
// ========================================================================
namespace {
std::shared_ptr<std::shared_mutex> databaseTxnLockFor(
    const std::string& dbname);
}

bool StorageEngine::checkpoint(const std::string& dbname) {
    if (!databaseExists(dbname)) return false;

    // Transactions hold this mutex in shared mode from before xid
    // registration until their terminal cleanup. Acquire it exclusively
    // before checking the active set, so a new BEGIN cannot enter in the gap
    // between that check and cache/WAL checkpointing. Never recursively try
    // to upgrade this thread's own transaction lock.
    const auto& context = transactionContext();
    if (context.inTransaction && context.txnDB == dbname) return false;
    if (ensureDatabaseTransactionOwnership() != DBStatus::OK) return false;
    const auto activeUserTransaction = [&] {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        for (const auto& [xid, database] : activeTransactionDatabases()) {
            (void)xid;
            if (database == dbname) return true;
        }
        return false;
    };
    if (activeUserTransaction()) return false;
    auto maintenance = maintenanceStateFor(dbname);
    {
        std::unique_lock<std::mutex> lock(maintenance->mutex);
        if (maintenance->running != MaintenanceKind::None &&
            maintenance->owner == std::this_thread::get_id()) return false;
        const auto completed = maintenance->completedCheckpoints;
        while (maintenance->running != MaintenanceKind::None) {
            maintenance->finished.wait_for(lock, std::chrono::milliseconds(20));
            const bool completedHere = maintenance->completedCheckpoints != completed &&
                maintenance->lastCheckpointOwner == this;
            const bool succeeded = maintenance->lastCheckpointSucceeded;
            lock.unlock();
            checkForQueryInterrupt();
            const bool active = activeUserTransaction();
            lock.lock();
            if (completedHere) return succeeded;
            if (active) return false;
        }
        maintenance->running = MaintenanceKind::Checkpoint;
        maintenance->owner = std::this_thread::get_id();
    }
    // Coalesce overlapping checkpoints and wait for background vacuum's
    // shared database ownership. Active user transactions retain the normal
    // nonblocking refusal below; no durability failure is converted to OK.
    MaintenanceCompletion completion{maintenance, MaintenanceKind::Checkpoint, this};
    const auto databaseMutex = databaseTxnLockFor(dbname);
    std::unique_lock<std::shared_mutex> checkpointDatabaseLock(
        *databaseMutex, std::try_to_lock);
    if (!checkpointDatabaseLock.owns_lock() || !databaseExists(dbname)) {
        return false;
    }
    PhysicalCatalogOwnership catalogOwnership(
        transactionContext(), databaseMutex, checkpointDatabaseLock);

    // Do not advance the recovery start point while a transaction for this
    // database is active.  A checkpoint must not make an uncommitted heap or
    // index image unreachable from recovery; the background checkpointer can
    // retry after the transaction ends.
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        for (const auto& [xid, activeDb] : activeTransactionDatabases()) {
            (void)xid;
            if (activeDb == dbname) return false;
        }
    }

    // A checkpoint starts a new index-image epoch: the next dirty-index
    // flush re-baselines its whole-file WAL image pair (see
    // flushWalLoggedIndex).  Entries committed since the last epoch ride on
    // the physical flush that already happened at their commit.
    {
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        ++indexImageEpoch_;
    }

    // Flush all loaded heap and index caches through the WAL-aware path.
    if (!flushDatabaseCaches(dbname)) {
        std::cerr << "[checkpoint] heap/index flush failed for " << dbname << std::endl;
        return false;
    }

    WALManager* wal = getWAL(dbname);
    if (!wal) return false;
    uint64_t nextXid = TxnIdGenerator::instance().maxCommittedTxId() + 1;
    const Lsn checkpointLsn = walCheckpoint(dbname, nextXid);
    if (checkpointLsn == INVALID_LSN || !wal->XLogFlush(checkpointLsn)) return false;

    // Mark all fully-written segments before the checkpoint as ready for
    // archiving. The current segment still contains the checkpoint record
    // and is kept for recovery.
    if (!wal->markSegmentsReadyBefore(checkpointLsn)) return false;
    {
        // Archive freshly-eligible segments immediately at the checkpoint
        // boundary (the background loop retries anything this pass misses).
        const auto archiveDir = archiveDestinationFromConfig();
        if (!archiveDir.empty()) (void)wal->archivePendingSegments(archiveDir);
    }
    {
        // Guard against the background pruner reading this map under
        // cacheMutex_ (TSAN: data race, pruneMissingDatabaseCaches vs
        // checkpoint's unsynchronized store).
        std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
        lastCheckpointLsns_[dbname] = checkpointLsn;
    }

    // Persist checkpoint LSN for fast recovery startup.
    auto cpPath = checkpointPath(dbname);
    uint64_t timestamp = static_cast<uint64_t>(std::time(nullptr));
    uint64_t maxTxId = TxnIdGenerator::instance().maxCommittedTxId();
    uint64_t ckptLsnU64 = checkpointLsn;
    std::string checkpointBytes(sizeof(timestamp) + sizeof(maxTxId) + sizeof(ckptLsnU64), '\0');
    size_t offset = 0;
    std::memcpy(checkpointBytes.data() + offset, &timestamp, sizeof(timestamp));
    offset += sizeof(timestamp);
    std::memcpy(checkpointBytes.data() + offset, &maxTxId, sizeof(maxTxId));
    offset += sizeof(maxTxId);
    std::memcpy(checkpointBytes.data() + offset, &ckptLsnU64, sizeof(ckptLsnU64));
    if (!index_file::writeAtomically(cpPath, checkpointBytes)) return false;

    // Persist catalog metadata so it matches the checkpoint.
    if (catalogService_ && !catalogService_->persistAll()) return false;
    if (!persistRuntimeStats(dbname, dbPath(dbname) / ".runtime_stats")) return false;
    if (!persistSqlStats(dbname, dbPath(dbname) / ".sql_stats")) return false;

    // Archive WAL before truncation
    if (!archiveWal(dbname)) {
        std::cerr << "[checkpoint] archive publication failed for " << dbname << std::endl;
        return false;
    }
    // Only archived segments strictly before the checkpoint are reclaimable;
    // the segment containing the checkpoint remains the recovery start.
    completion.succeeded = wal->truncateBefore(checkpointLsn);
    return completion.succeeded;
}

// ========================================================================
// WAL archiving
// ========================================================================

bool StorageEngine::archiveWal(const std::string& dbname) {
    WALManager* wal = getWAL(dbname);
    if (!wal) return false;
    auto archiveDir = walArchiveDir(dbname);
    // An archive sidecar name is also a legal quoted database name. Serialize
    // against CREATE of that name, then refuse any directory with a table
    // list instead of placing WAL segments inside a live database.
    const auto archiveNameMutex = databaseTxnLockFor(
        archiveDir.filename().string());
    std::unique_lock<std::shared_mutex> archiveNameLock(
        *archiveNameMutex, std::try_to_lock);
    if (!archiveNameLock.owns_lock()) return false;
    std::error_code ec;
    if (pathEntryExists(archiveDir / "tlist.lst", ec) || ec) return false;
    std::filesystem::create_directories(archiveDir, ec);
    if (ec) return false;
    // Archive all segments that are marked .ready but not yet .done.
    return wal->archivePendingSegments(archiveDir);
}

// ========================================================================
// Physical backup / restore
// ========================================================================

static bool restorePathContains(const std::filesystem::path& parent,
                                const std::filesystem::path& child) {
    auto parentPart = parent.begin();
    auto childPart = child.begin();
    for (; parentPart != parent.end(); ++parentPart, ++childPart) {
        if (childPart == child.end() || *parentPart != *childPart) {
            return false;
        }
    }
    return true;
}

static bool restorePathsOverlap(const std::filesystem::path& first,
                                const std::filesystem::path& second) {
    const auto normalizedFirst = std::filesystem::weakly_canonical(
        std::filesystem::absolute(first));
    const auto normalizedSecond = std::filesystem::weakly_canonical(
        std::filesystem::absolute(second));
    return restorePathContains(normalizedFirst, normalizedSecond) ||
           restorePathContains(normalizedSecond, normalizedFirst);
}

struct PhysicalBackupFileEntry {
    uintmax_t size = 0;
    std::string digest;

    bool operator==(const PhysicalBackupFileEntry& other) const {
        return size == other.size && digest == other.digest;
    }
};

using PhysicalBackupDirectories = std::set<std::string>;
using PhysicalBackupFiles =
    std::map<std::string, PhysicalBackupFileEntry>;

static std::string encodeBackupPath(const std::string& path) {
    static constexpr char digits[] = "0123456789abcdef";
    std::string encoded;
    encoded.reserve(path.size() * 2);
    for (const unsigned char byte : path) {
        encoded.push_back(digits[byte >> 4]);
        encoded.push_back(digits[byte & 0x0f]);
    }
    return encoded;
}

static bool decodeBackupPath(const std::string& encoded,
                             std::string& path) {
    path.clear();
    if (encoded.empty() || encoded.size() % 2 != 0) return false;
    const auto nibble = [](char c) -> int {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        return -1;
    };
    path.reserve(encoded.size() / 2);
    for (size_t i = 0; i < encoded.size(); i += 2) {
        const int high = nibble(encoded[i]);
        const int low = nibble(encoded[i + 1]);
        if (high < 0 || low < 0) return false;
        const char value = static_cast<char>((high << 4) | low);
        if (value == '\0') return false;
        path.push_back(value);
    }
    return true;
}

static bool validBackupRelativePath(const std::string& value) {
    if (value.empty()) return false;
    const std::filesystem::path path(value);
    if (path.is_absolute() || path.generic_string() != value) return false;
    for (const auto& component : path) {
        if (component.empty() || component == "." || component == "..") {
            return false;
        }
    }
    return value != kPhysicalBackupMarker &&
           value != kPhysicalBackupManifest;
}

static bool digestBackupFile(const std::filesystem::path& path,
                             PhysicalBackupFileEntry& entry) {
    std::error_code error;
    if (!std::filesystem::is_regular_file(path, error) || error) return false;
    entry.size = std::filesystem::file_size(path, error);
    if (error) return false;

    std::ifstream input(path, std::ios::binary);
    if (!input) return false;
    SHA256 digest;
    std::array<char, 64 * 1024> buffer{};
    while (input) {
        input.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
        const auto count = input.gcount();
        if (count > 0) {
            digest.append(buffer.data(), static_cast<size_t>(count));
        }
    }
    if (!input.eof()) return false;
    entry.digest = digest.finishHex();
    return true;
}

static bool syncPhysicalBackupFile(const std::filesystem::path& path) {
    const int fd = ::open(path.c_str(), O_RDONLY | O_CLOEXEC);
    if (fd < 0) return false;
    int result;
    do {
        result = ::fsync(fd);
    } while (result != 0 && errno == EINTR);
    const bool closeOk = (::close(fd) == 0);
    return result == 0 && closeOk;
}

static bool syncPhysicalBackupTree(const std::filesystem::path& root) {
    std::vector<std::filesystem::path> directories{root};
    std::error_code error;
    std::filesystem::recursive_directory_iterator iterator(root, error);
    const std::filesystem::recursive_directory_iterator end;
    if (error) return false;
    for (; iterator != end; iterator.increment(error)) {
        if (error) return false;
        const auto& entry = *iterator;
        if (entry.is_symlink(error) || error) return false;
        if (entry.is_directory(error) && !error) {
            directories.push_back(entry.path());
            continue;
        }
        if (error || !entry.is_regular_file(error) || error ||
            !syncPhysicalBackupFile(entry.path())) {
            return false;
        }
    }
    if (error) return false;
    std::sort(directories.begin(), directories.end(),
              [](const auto& left, const auto& right) {
                  return std::distance(left.begin(), left.end()) >
                         std::distance(right.begin(), right.end());
              });
    for (const auto& directory : directories) {
        if (!index_file::syncDirectory(directory)) return false;
    }
    return true;
}

static bool exchangePhysicalBackupDirectories(
    const std::filesystem::path& first,
    const std::filesystem::path& second) {
#ifdef SYS_renameat2
    constexpr unsigned kRenameExchange = 2;
    return ::syscall(SYS_renameat2, AT_FDCWD, first.c_str(), AT_FDCWD,
                     second.c_str(), kRenameExchange) == 0;
#else
    (void)first;
    (void)second;
    errno = ENOTSUP;
    return false;
#endif
}

struct DurableDirectoryReplacement {
    std::filesystem::path target;
    std::filesystem::path staging;
    bool targetExisted = false;
    bool published = false;
};

static std::filesystem::path directoryParent(
    const std::filesystem::path& path) {
    return path.parent_path().empty()
        ? std::filesystem::path(".") : path.parent_path();
}

static bool rollbackDirectoryReplacement(
    DurableDirectoryReplacement& replacement) {
    if (!replacement.published) return true;
    const auto parent = directoryParent(replacement.target);
    if (replacement.targetExisted) {
        if (!exchangePhysicalBackupDirectories(
                replacement.staging, replacement.target)) {
            return false;
        }
    } else {
        std::error_code error;
        std::filesystem::rename(
            replacement.target, replacement.staging, error);
        if (error) return false;
    }
    replacement.published = false;
    return index_file::syncDirectory(parent);
}

static bool publishDirectoryReplacement(
    DurableDirectoryReplacement& replacement) {
    std::error_code error;
    replacement.targetExisted =
        std::filesystem::exists(replacement.target, error);
    if (error) return false;
    if (replacement.targetExisted) {
        if (!exchangePhysicalBackupDirectories(
                replacement.staging, replacement.target)) {
            return false;
        }
    } else {
        std::filesystem::rename(
            replacement.staging, replacement.target, error);
        if (error) return false;
    }
    replacement.published = true;
    if (index_file::syncDirectory(
            directoryParent(replacement.target))) {
        return true;
    }
    (void)rollbackDirectoryReplacement(replacement);
    return false;
}

static bool makeDiscardableDirectoryTree(
    const std::filesystem::path& root) {
    std::error_code error;
    if (!std::filesystem::is_directory(
            std::filesystem::symlink_status(root, error)) || error) {
        return false;
    }
    // A successful exchange can leave the old database generation at the
    // staging path with read-only directory permissions. Only this retired
    // generation is made writable; never change the published target or a
    // symlink that could point outside the data directory.
    std::filesystem::permissions(
        root, std::filesystem::perms::owner_all,
        std::filesystem::perm_options::add, error);
    if (error) return false;
    std::filesystem::recursive_directory_iterator it(root, error), end;
    if (error) return false;
    while (it != end) {
        const auto status = it->symlink_status(error);
        if (error) return false;
        if (std::filesystem::is_directory(status)) {
            std::filesystem::permissions(
                it->path(), std::filesystem::perms::owner_all,
                std::filesystem::perm_options::add, error);
            if (error) return false;
        }
        it.increment(error);
        if (error) return false;
    }
    return true;
}

static bool discardDirectoryReplacement(
    DurableDirectoryReplacement& replacement) {
    if (replacement.staging.empty()) return true;
    std::error_code error;
    const bool exists = std::filesystem::exists(
        replacement.staging, error);
    if (error) return false;
    if (exists) {
        std::filesystem::remove_all(replacement.staging, error);
        if (error == std::errc::permission_denied &&
            makeDiscardableDirectoryTree(replacement.staging)) {
            error.clear();
            std::filesystem::remove_all(replacement.staging, error);
        }
        if (error ||
            !index_file::syncDirectory(
                directoryParent(replacement.staging))) {
            return false;
        }
    }
    replacement.staging.clear();
    return true;
}

static bool stageDirectoryReplacement(
    const std::filesystem::path* source,
    const std::filesystem::path& target,
    std::string_view purpose,
    DurableDirectoryReplacement& replacement) {
    replacement = {};
    replacement.target = target;
    if (source) {
        std::error_code sourceError;
        if (!std::filesystem::is_directory(*source, sourceError) ||
            sourceError) {
            return false;
        }
    }

    static std::atomic<uint64_t> sequence{0};
    const auto parent = directoryParent(target);
    std::error_code error;
    std::filesystem::create_directories(parent, error);
    if (error) return false;
    for (size_t attempt = 0; attempt < 1000; ++attempt) {
        const auto candidate = parent / std::filesystem::path(
            "." + target.filename().string() + "." +
            std::string(purpose) + "." + std::to_string(::getpid()) + "." +
            std::to_string(sequence.fetch_add(1, std::memory_order_relaxed)));
        error.clear();
        if (std::filesystem::create_directory(candidate, error)) {
            replacement.staging = candidate;
            break;
        }
        if (error && !std::filesystem::exists(candidate)) return false;
    }
    if (replacement.staging.empty()) return false;

    try {
        if (source) {
            for (const auto& entry :
                 std::filesystem::directory_iterator(*source)) {
                const auto destination =
                    replacement.staging / entry.path().filename();
                if (entry.is_directory()) {
                    std::filesystem::copy(
                        entry.path(), destination,
                        std::filesystem::copy_options::recursive);
                } else {
                    std::filesystem::copy_file(
                        entry.path(), destination,
                        std::filesystem::copy_options::overwrite_existing);
                }
            }
        }
        if (syncPhysicalBackupTree(replacement.staging)) return true;
    } catch (...) {
    }
    (void)discardDirectoryReplacement(replacement);
    return false;
}

static bool collectPhysicalBackupEntries(
    const std::filesystem::path& root,
    PhysicalBackupDirectories& directories,
    PhysicalBackupFiles& files) {
    directories.clear();
    files.clear();
    std::error_code error;
    if (!std::filesystem::is_directory(root, error) || error) return false;

    std::filesystem::recursive_directory_iterator iterator(root, error);
    const std::filesystem::recursive_directory_iterator end;
    if (error) return false;
    for (; iterator != end; iterator.increment(error)) {
        if (error) return false;
        const auto& entry = *iterator;
        if (entry.is_symlink(error) || error) return false;
        const auto relative =
            std::filesystem::relative(entry.path(), root, error);
        if (error) return false;
        const std::string name = relative.generic_string();
        if (name == kPhysicalBackupMarker ||
            name == kPhysicalBackupManifest) {
            if (entry.is_directory(error) || error) return false;
            continue;
        }
        if (!validBackupRelativePath(name)) return false;
        if (entry.is_directory(error) && !error) {
            if (!directories.insert(name).second) return false;
            continue;
        }
        if (error || !entry.is_regular_file(error) || error) return false;
        PhysicalBackupFileEntry file;
        if (!digestBackupFile(entry.path(), file) ||
            !files.emplace(name, std::move(file)).second) {
            return false;
        }
    }
    return !error;
}

static bool writePhysicalBackupManifest(const std::filesystem::path& root,
                                        const std::string& database) {
    PhysicalBackupDirectories directories;
    PhysicalBackupFiles files;
    if (!collectPhysicalBackupEntries(root, directories, files)) return false;

    std::ostringstream output;
    output << "DBMS_PHYSICAL_BACKUP_MANIFEST_V2\n";
    output << "S\t" << encodeBackupPath(database) << '\n';
    for (const auto& directory : directories) {
        output << "D\t" << encodeBackupPath(directory) << '\n';
    }
    for (const auto& [name, entry] : files) {
        output << "F\t" << entry.size << '\t' << entry.digest << '\t'
               << encodeBackupPath(name) << '\n';
    }
    return output.good() && index_file::writeAtomically(
        root / kPhysicalBackupManifest, output.str());
}

static bool readPhysicalBackupManifest(
    const std::filesystem::path& root,
    std::string& sourceDatabase,
    PhysicalBackupDirectories& directories,
    PhysicalBackupFiles& files) {
    sourceDatabase.clear();
    directories.clear();
    files.clear();
    const auto path = root / kPhysicalBackupManifest;
    std::error_code error;
    if (!std::filesystem::is_regular_file(path, error) || error) return false;
    const auto manifestSize = std::filesystem::file_size(path, error);
    if (error || manifestSize > 64ULL * 1024ULL * 1024ULL) return false;

    std::ifstream input(path, std::ios::binary);
    std::string line;
    if (!std::getline(input, line) ||
        line != "DBMS_PHYSICAL_BACKUP_MANIFEST_V2") {
        return false;
    }
    if (!std::getline(input, line) || line.rfind("S\t", 0) != 0 ||
        line.find('\t', 2) != std::string::npos ||
        !decodeBackupPath(line.substr(2), sourceDatabase) ||
        !validStoredIdentifier(sourceDatabase, MAX_TABLE_NAME_LEN)) {
        return false;
    }
    while (std::getline(input, line)) {
        if (line.empty()) return false;
        std::vector<std::string> fields;
        size_t begin = 0;
        for (;;) {
            const size_t separator = line.find('\t', begin);
            fields.push_back(line.substr(begin, separator - begin));
            if (separator == std::string::npos) break;
            begin = separator + 1;
        }
        std::string name;
        if (fields.size() == 2 && fields[0] == "D") {
            if (!decodeBackupPath(fields[1], name) ||
                !validBackupRelativePath(name) ||
                !directories.insert(name).second) {
                return false;
            }
            continue;
        }
        if (fields.size() != 4 || fields[0] != "F" ||
            !decodeBackupPath(fields[3], name) ||
            !validBackupRelativePath(name)) {
            return false;
        }
        uintmax_t size = 0;
        const auto converted = std::from_chars(
            fields[1].data(), fields[1].data() + fields[1].size(), size, 10);
        if (converted.ec != std::errc{} ||
            converted.ptr != fields[1].data() + fields[1].size() ||
            fields[2].size() != 64 ||
            !std::all_of(fields[2].begin(), fields[2].end(), [](char c) {
                return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
            }) ||
            !files.emplace(name, PhysicalBackupFileEntry{size, fields[2]}).second) {
            return false;
        }
    }
    return input.eof() && !input.bad();
}

static bool validPhysicalBackupSource(const std::filesystem::path& source,
                                      std::string& sourceDatabase) {
    sourceDatabase.clear();
    if (!std::filesystem::is_directory(source)) return false;
    const auto marker = source / kPhysicalBackupMarker;
    if (!std::filesystem::is_regular_file(marker)) return false;
    std::ifstream input(marker, std::ios::binary);
    if (!input) return false;
    const std::string contents{
        std::istreambuf_iterator<char>(input),
        std::istreambuf_iterator<char>()};
    if (contents != "DBMS_PHYSICAL_BACKUP_V3\n") return false;

    PhysicalBackupDirectories expectedDirectories;
    PhysicalBackupFiles expectedFiles;
    PhysicalBackupDirectories actualDirectories;
    PhysicalBackupFiles actualFiles;
    return readPhysicalBackupManifest(
               source, sourceDatabase, expectedDirectories, expectedFiles) &&
           collectPhysicalBackupEntries(
               source, actualDirectories, actualFiles) &&
           expectedDirectories == actualDirectories &&
           expectedFiles == actualFiles;
}

struct SavepointImageGeneration {
    dev_t device = 0;
    ino_t inode = 0;
    mode_t mode = 0;
    off_t size = 0;
    timespec modified{};
    timespec changed{};
    bool operator==(const SavepointImageGeneration& other) const {
        return device == other.device && inode == other.inode &&
            mode == other.mode && size == other.size &&
            modified.tv_sec == other.modified.tv_sec &&
            modified.tv_nsec == other.modified.tv_nsec &&
            changed.tv_sec == other.changed.tv_sec &&
            changed.tv_nsec == other.changed.tv_nsec;
    }
};

struct SavepointImageReceipt {
    using Generations = std::map<std::string, SavepointImageGeneration>;
    std::string database;
    std::string backup;
    Generations sourceGenerations;
    Generations backupGenerations;
    PhysicalBackupFiles files;
    CatalogManager::MetadataSnapshot catalog;
    Lsn walLsn = INVALID_LSN;
};

// Exactly the runtime coordination names already omitted by physicalBackup.
// Everything else, including unknown sidecars, participates in the proof.
static bool savepointRuntimeCoordinationName(const std::string& name) {
    return name == ".lockmgr" || name == ".runtime_stats.lock" ||
        name == ".sql_stats.lock" || name.rfind(".runtime_stats.tmp.", 0) == 0 ||
        name.rfind(".sql_stats.tmp.", 0) == 0;
}

static bool collectSavepointGenerations(
    const std::filesystem::path& root,
    SavepointImageReceipt::Generations& result, bool activeDatabase) {
    result.clear();
    const auto add = [&](const std::filesystem::path& path,
                         const std::string& name) {
        struct stat value{};
        if (::lstat(path.c_str(), &value) != 0 ||
            (!S_ISREG(value.st_mode) && !S_ISDIR(value.st_mode))) return false;
        result.emplace(name, SavepointImageGeneration{
            value.st_dev, value.st_ino, value.st_mode, value.st_size,
            value.st_mtim, value.st_ctim});
        return true;
    };
    if (!add(root, ".") || !S_ISDIR(result.at(".").mode)) return false;
    std::error_code error;
    std::filesystem::recursive_directory_iterator it(root, error), end;
    if (error) return false;
    for (; it != end; it.increment(error)) {
        if (error) return false;
        const auto relative = it->path().lexically_relative(root).generic_string();
        if (!validBackupRelativePath(relative) &&
            (activeDatabase ||
             (relative != kPhysicalBackupMarker && relative != kPhysicalBackupManifest)))
            return false;
        if (activeDatabase && relative.find('/') == std::string::npos &&
            savepointRuntimeCoordinationName(relative)) {
            struct stat coordination{};
            if (::lstat(it->path().c_str(), &coordination) != 0) return false;
            if (relative == ".lockmgr" && S_ISDIR(coordination.st_mode)) {
                // physicalBackup omits the whole runtime lock directory.
                // Savepoint lock state is independently restored from its
                // checkpoint; these files are not snapshot payload.
                it.disable_recursion_pending();
            } else if (!S_ISREG(coordination.st_mode)) return false;
            continue;
        }
        if (!add(it->path(), relative)) return false;
    }
    return !error;
}

template<class Row, class Fields>
static bool sameSavepointCatalogRows(const std::vector<Row>& first,
                                    const std::vector<Row>& second,
                                    const Fields& fields) {
    if (first.size() != second.size()) return false;
    for (size_t i = 0; i < first.size(); ++i)
        if (fields(first[i]) != fields(second[i])) return false;
    return true;
}

// Include fields not present in the current on-disk bootstrap prefix too.
// A direct cached-row edit must invalidate the optimization, not disappear
// just because its field does not have a persistence encoding yet.
static bool sameSavepointCatalog(const CatalogManager::MetadataSnapshot& a,
                                 const CatalogManager::MetadataSnapshot& b) {
    return sameSavepointCatalogRows(a.namespaces, b.namespaces, [](const PgNamespaceRow& r) {
        return std::tie(r.oid, r.nspname, r.nspowner);
    }) && sameSavepointCatalogRows(a.relations, b.relations, [](const PgClassRow& r) {
        return std::tie(r.oid, r.relname, r.relnamespace, r.reltype, r.reloftype,
            r.relowner, r.relam, r.relfilenode, r.reltablespace, r.relpages,
            r.reltuples, r.relallvisible, r.reltoastrelid, r.relhasindex,
            r.relisshared, r.relpersistence, r.relkind, r.relnatts, r.relchecks,
            r.relhasrules, r.relhastriggers, r.relhassubclass, r.relrowsecurity,
            r.relforcerowsecurity, r.relispopulated, r.relreplident,
            r.relispartition, r.relrewrite, r.relfrozenxid, r.relminmxid);
    }) && sameSavepointCatalogRows(a.attributes, b.attributes, [](const PgAttributeRow& r) {
        return std::tie(r.attrelid, r.attname, r.atttypid, r.attstattarget,
            r.attlen, r.attnum, r.attndims, r.attcacheoff, r.atttypmod,
            r.attbyval, r.attstorage, r.attalign, r.attnotnull, r.atthasdef,
            r.attidentity, r.attgenerated, r.attisdropped, r.attislocal,
            r.attinhcount, r.attcollation);
    }) && sameSavepointCatalogRows(a.types, b.types, [](const PgTypeRow& r) {
        return std::tie(r.oid, r.typname, r.typnamespace, r.typowner, r.typlen,
            r.typbyval, r.typtype, r.typcategory, r.typispreferred, r.typisdefined,
            r.typdelim, r.typrelid, r.typelem, r.typarray, r.typinput,
            r.typoutput, r.typreceive, r.typsend, r.typmodin, r.typmodout,
            r.typanalyze, r.typalign, r.typstorage, r.typnotnull, r.typbasetype,
            r.typtypmod, r.typndims, r.typcollation);
    }) && sameSavepointCatalogRows(a.routines, b.routines, [](const PgProcRow& r) {
        return std::tie(r.oid, r.proname, r.pronamespace, r.proowner, r.prolang,
            r.procost, r.prorows, r.provariadic, r.prokind, r.prosecdef,
            r.proleakproof, r.proisstrict, r.proretset, r.provolatile,
            r.proparallel, r.pronargs, r.pronargdefaults, r.prorettype,
            r.proargtypes, r.proallargtypes, r.proargmodes, r.proargnames,
            r.prosrc, r.probin);
    });
}

static std::shared_ptr<SavepointImageReceipt> captureSavepointImageReceipt(
    const std::string& database, const std::string& backup,
    const std::filesystem::path& source,
    const CatalogManager::MetadataSnapshot& catalog, Lsn walLsn) {
    std::string imageDatabase;
    if (std::filesystem::is_symlink(backup) ||
        !validPhysicalBackupSource(backup, imageDatabase) || imageDatabase != database)
        return {};
    PhysicalBackupDirectories directories;
    PhysicalBackupFiles files;
    if (!readPhysicalBackupManifest(backup, imageDatabase, directories, files)) return {};
    auto receipt = std::make_shared<SavepointImageReceipt>();
    receipt->database = database;
    receipt->backup = backup;
    receipt->catalog = catalog;
    receipt->walLsn = walLsn;
    receipt->files = files;
    if (!collectSavepointGenerations(source, receipt->sourceGenerations, true) ||
        !collectSavepointGenerations(backup, receipt->backupGenerations, false)) return {};
    PhysicalBackupDirectories sourceDirectories;
    PhysicalBackupFiles sourceFiles;
    for (const auto& [name, generation] : receipt->sourceGenerations) {
        if (name == ".") continue;
        if (S_ISDIR(generation.mode)) sourceDirectories.insert(name);
        else {
            PhysicalBackupFileEntry value;
            if (!digestBackupFile(source / name, value)) return {};
            sourceFiles.emplace(name, std::move(value));
        }
    }
    // External tablespace/archive layouts are never approximated as local
    // files: a non-identical layout simply retains the complete restore path.
    if (sourceDirectories != directories || sourceFiles != files) return {};
    SavepointImageReceipt::Generations sourceAfter, backupAfter;
    if (!collectSavepointGenerations(source, sourceAfter, true) ||
        !collectSavepointGenerations(backup, backupAfter, false) ||
        sourceAfter != receipt->sourceGenerations ||
        backupAfter != receipt->backupGenerations) return {};
    return receipt;
}

static bool savepointSequenceRuntimeFile(const std::string& name) {
    static const std::string prefix = std::string(SEQUENCE_RUNTIME_DIRECTORY) + "/";
    return name.rfind(prefix, 0) == 0 &&
        validSequenceGeneration(name.substr(prefix.size()));
}

// SQL rollback deliberately preserves the current nontransactional runtime
// forks. Validate them before treating their changes as a reusable preimage;
// declarations, fork names and every other file still require the old proof.
static bool validSavepointSequenceRuntime(const std::filesystem::path& database) {
    // Do not introduce a blocking cache-mutex -> sequence-mutex dependency.
    std::unique_lock<std::mutex> sequenceLock(g_sequenceMutex, std::try_to_lock);
    if (!sequenceLock.owns_lock()) return false;
    const auto runtime = database / SEQUENCE_RUNTIME_DIRECTORY;
    std::error_code error;
    const auto status = std::filesystem::symlink_status(runtime, error);
    if (error || !std::filesystem::is_directory(status)) return false;
    for (const auto& entry : std::filesystem::directory_iterator(runtime)) {
        const auto generation = entry.path().filename().string();
        int64_t next = 0, allocated = 0;
        bool exhausted = false;
        if (!readSequenceRuntime(entry.path(), generation, next, allocated, exhausted))
            return false;
    }
    // Parsing the runtime header alone is insufficient: active forks must
    // also satisfy their declaration's generation, range and call-state rules.
    for (const auto& entry : std::filesystem::directory_iterator(database)) {
        const auto extension = entry.path().extension();
        if (!entry.is_regular_file() || (extension != ".seq" && extension != ".seqv2"))
            continue;
        if (extension == ".seq") {
            std::ifstream input(entry.path());
            std::string magic;
            // Legacy per-table AUTO_INCREMENT files are not SQL sequences.
            if (!(input >> magic) || magic.rfind("DBMSSEQ", 0) != 0) continue;
        }
        SequenceInfo info;
        int64_t next = 0, allocated = 0;
        bool exhausted = false;
        std::string generation;
        if (!readSequenceFile(entry.path(), info, next, allocated, &exhausted, &generation) ||
            generation.empty()) return false;
    }
    return true;
}

static bool matchesSavepointImageReceipt(
    const SavepointImageReceipt& receipt, const std::string& database,
    const std::string& backup, const std::filesystem::path& source,
    const CatalogManager::MetadataSnapshot& catalog, Lsn walLsn) {
    if (receipt.database != database || receipt.backup != backup ||
        receipt.walLsn != walLsn || !sameSavepointCatalog(receipt.catalog, catalog))
        return false;
    SavepointImageReceipt::Generations current, image;
    if (!collectSavepointGenerations(source, current, true) ||
        !collectSavepointGenerations(backup, image, false) ||
        image != receipt.backupGenerations || current.size() != receipt.sourceGenerations.size())
        return false;
    bool sequenceRuntimeChanged = false;
    for (const auto& [name, previous] : receipt.sourceGenerations) {
        const auto now = current.find(name);
        if (now == current.end()) return false;
        if (now->second == previous) continue;
        if ((name == SEQUENCE_RUNTIME_DIRECTORY && S_ISDIR(previous.mode) &&
             S_ISDIR(now->second.mode) && now->second.device == previous.device &&
             now->second.inode == previous.inode && now->second.mode == previous.mode) ||
            (savepointSequenceRuntimeFile(name) && S_ISREG(previous.mode) &&
             S_ISREG(now->second.mode) && now->second.device == previous.device &&
             now->second.mode == previous.mode)) {
            sequenceRuntimeChanged = true;
            continue;
        }
        // OidGenerator currently rewrites its unchanged counter on persist.
        // Require the same physical file and the actual complete preimage,
        // not a value-shaped/epoch-based exemption for any other catalog file.
        if (name != "pg_catalog/.oid_counter" ||
            now->second.device != previous.device || now->second.inode != previous.inode ||
            now->second.mode != previous.mode) return false;
        const auto expected = receipt.files.find(name);
        PhysicalBackupFileEntry bytes;
        if (expected == receipt.files.end() || !digestBackupFile(source / name, bytes) ||
            !(bytes == expected->second)) return false;
    }
    if (sequenceRuntimeChanged && !validSavepointSequenceRuntime(source)) return false;
    SavepointImageReceipt::Generations sourceAfter, imageAfter;
    return collectSavepointGenerations(source, sourceAfter, true) &&
        collectSavepointGenerations(backup, imageAfter, false) &&
        sourceAfter == current && imageAfter == image;
}

static bool replaceablePhysicalBackupDestination(
    const std::filesystem::path& destination,
    const std::string& expectedDatabase) {
    // Rebuilding a damaged backup is valid, so its payload need not match
    // the manifest. Its own marker and manifest must still identify it as a
    // backup of this database before we replace the directory.
    if (!std::filesystem::is_directory(destination) ||
        std::filesystem::is_symlink(destination)) return false;
    const auto marker = destination / kPhysicalBackupMarker;
    const auto manifest = destination / kPhysicalBackupManifest;
    if (std::filesystem::is_symlink(marker) ||
        std::filesystem::is_symlink(manifest) ||
        !std::filesystem::is_regular_file(marker)) return false;
    std::ifstream input(marker, std::ios::binary);
    if (!input) return false;
    const std::string contents{
        std::istreambuf_iterator<char>(input),
        std::istreambuf_iterator<char>()};
    if (contents != "DBMS_PHYSICAL_BACKUP_V3\n") return false;
    std::string sourceDatabase;
    PhysicalBackupDirectories directories;
    PhysicalBackupFiles files;
    return readPhysicalBackupManifest(
               destination, sourceDatabase, directories, files) &&
           sourceDatabase == expectedDatabase;
}

static bool discardOwnedPhysicalBackup(
    const std::filesystem::path& backup,
    const std::string& database) {
    if (backup.empty() || backup.parent_path() != std::filesystem::path{}) {
        return false;
    }
    const auto nameMutex = databaseTxnLockFor(backup.filename().string());
    std::unique_lock<std::shared_mutex> nameLock(
        *nameMutex, std::try_to_lock);
    if (!nameLock.owns_lock() ||
        !replaceablePhysicalBackupDestination(backup, database)) {
        return false;
    }
    std::error_code error;
    std::filesystem::remove_all(backup, error);
    return !error;
}

static uint64_t maintenancePathBytes(const std::filesystem::path& path) {
    std::error_code error;
    if (std::filesystem::is_regular_file(path, error)) {
        const auto bytes = std::filesystem::file_size(path, error);
        return error ? 0 : bytes;
    }
    if (error || !std::filesystem::is_directory(path, error) || error)
        return 0;
    uint64_t total = 0;
    std::filesystem::recursive_directory_iterator iterator(
        path, std::filesystem::directory_options::skip_permission_denied,
        error);
    const std::filesystem::recursive_directory_iterator end;
    while (!error && iterator != end) {
        if (iterator->is_regular_file(error) && !error) {
            const auto bytes = iterator->file_size(error);
            if (!error && UINT64_MAX - total >= bytes) total += bytes;
        }
        iterator.increment(error);
    }
    return total;
}

bool StorageEngine::physicalBackup(const std::string& dbname,
                                   const std::string& backupPath,
                                   const MaintenanceProgress& progress) {
    // A public backup is a database-wide snapshot operation.  Refuse to run
    // from inside the caller's transaction (which already owns a shared lock
    // and may contain uncommitted state), then exclude new transactions for
    // the complete flush-and-copy interval.
    if (transactionContext().inTransaction) return false;
    const auto databaseMutex = databaseTxnLockFor(dbname);
    std::unique_lock<std::shared_mutex> databaseLock(*databaseMutex);
    if (!databaseExists(dbname)) return false;
    PhysicalCatalogOwnership catalogOwnership(
        transactionContext(), databaseMutex, databaseLock);
    if (catalogService_ && !catalogService_->persistAll()) return false;
    if (!flushDatabaseCaches(dbname)) return false;
    WALManager* wal = getWAL(dbname);
    if (!wal || !wal->XLogFlush(wal->currentWriteLsn())) return false;
    return physicalBackupLocked(dbname, backupPath, progress);
}

bool StorageEngine::physicalBackupLocked(
    const std::string& dbname, const std::string& backupPath,
    const MaintenanceProgress& progress, bool includeUnloggedMain) {
    const auto destination = std::filesystem::path(backupPath);
    const auto destinationParent = destination.parent_path().empty()
        ? std::filesystem::path(".") : destination.parent_path();
    std::error_code clusterPathError;
    const bool clusterName = std::filesystem::equivalent(
        destinationParent, std::filesystem::path("."), clusterPathError);
    std::shared_ptr<std::shared_mutex> destinationNameMutex;
    std::unique_lock<std::shared_mutex> destinationNameLock;
    if (clusterName && destination.filename().string() != dbname) {
        // CREATE/DROP/RENAME DATABASE use this process-wide name lock. Hold
        // it from the first destination check through backup publication, so
        // another StorageEngine cannot claim the name during the copy. Use a
        // nonblocking attempt because the source name lock is already held.
        destinationNameMutex = databaseTxnLockFor(
            destination.filename().string());
        destinationNameLock = std::unique_lock<std::shared_mutex>(
            *destinationNameMutex, std::try_to_lock);
        if (!destinationNameLock.owns_lock()) return false;
    }
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) return false;
    // The lock lives outside the replaceable database generation, so marker
    // creation/drop and relation placement cannot change underneath the
    // snapshot even when another backend is serving the same cluster.
    TablespaceCatalogLock tablespaceLock(
        tablespaceCatalogLockPath(*this, dbname), false);
    if (!tablespaceLock.acquired()) return false;
    const auto backupTables = getTableNames(dbname);
    for (const auto& tableName : backupTables) {
        const TableSchema table = getTableSchema(dbname, tableName);
        if (table.isUnlogged &&
            !ensureUnloggedInitForks(dbname, tableName)) {
            // A backup that lacks a usable init fork could expose stale main
            // data after restore, so refuse it rather than silently copying
            // an approximation of PostgreSQL backup semantics.
            return false;
        }
    }
    auto src = dbPath(dbname);
    auto dst = std::filesystem::path(backupPath);
    std::filesystem::path stagedBackup;
    const auto discardStagedBackup = [&]() {
        if (stagedBackup.empty()) return;
        std::error_code cleanupError;
        std::filesystem::remove_all(stagedBackup, cleanupError);
        stagedBackup.clear();
    };
    try {
        const auto archiveDir = walArchiveDir(dbname);
        if (restorePathsOverlap(src, dst) ||
            restorePathsOverlap(archiveDir, dst)) {
            return false;
        }
        const auto validExistingDestination = [&]() {
            std::error_code destinationError;
            if (!pathEntryExists(dst, destinationError)) {
                return !destinationError;
            }
            if (destinationError ||
                std::filesystem::is_symlink(dst, destinationError) ||
                destinationError) return false;
            return replaceablePhysicalBackupDestination(dst, dbname);
        };
        // A backup path can spell another live database or unrelated user
        // directory. Only a valid backup of this source may be replaced.
        if (!validExistingDestination()) return false;

        static std::atomic<uint64_t> backupSequence{0};
        const auto siblingPath = [&](std::string_view purpose) {
            const auto siblingParent = dst.parent_path().empty()
                ? std::filesystem::path(".") : dst.parent_path();
            return siblingParent / std::filesystem::path(
                "." + dst.filename().string() + "." +
                std::string(purpose) + "." +
                std::to_string(::getpid()) + "." +
                std::to_string(backupSequence.fetch_add(
                    1, std::memory_order_relaxed)));
        };
        std::error_code fileError;
        const auto parent = dst.parent_path().empty()
            ? std::filesystem::path(".") : dst.parent_path();
        std::filesystem::create_directories(parent, fileError);
        if (fileError) return false;
        for (size_t attempt = 0; attempt < 1000; ++attempt) {
            auto candidate = siblingPath("backup_staging");
            fileError.clear();
            if (std::filesystem::create_directory(candidate, fileError)) {
                stagedBackup = std::move(candidate);
                break;
            }
            if (fileError &&
                !std::filesystem::exists(candidate)) {
                return false;
            }
        }
        if (stagedBackup.empty()) return false;
        if (progress && !progress(0)) {
            discardStagedBackup();
            return false;
        }

        for (const auto& entry : std::filesystem::directory_iterator(src)) {
            // Advisory lock and interrupted temporary files are runtime
            // coordination state, not database contents. Never copy them
            // into a backup snapshot.
            const auto filename = entry.path().filename().string();
            if (filename == kPhysicalBackupMarker ||
                filename == kPhysicalBackupManifest || filename == ".lockmgr" ||
                filename == ".runtime_stats.lock" ||
                filename == ".sql_stats.lock" ||
                filename.rfind(".runtime_stats.tmp.", 0) == 0 ||
                filename.rfind(".sql_stats.tmp.", 0) == 0) {
                continue;
            }
            auto destPath = stagedBackup / entry.path().filename();
            if (entry.is_directory()) {
                std::filesystem::copy(entry.path(), destPath,
                    std::filesystem::copy_options::overwrite_existing |
                    std::filesystem::copy_options::recursive);
            } else {
                std::filesystem::copy_file(entry.path(), destPath,
                    std::filesystem::copy_options::overwrite_existing);
            }
            if (progress && !progress(maintenancePathBytes(entry.path()))) {
                discardStagedBackup();
                return false;
            }
        }
        // Also backup WAL archive if exists
        if (std::filesystem::exists(archiveDir)) {
            auto destArchive = stagedBackup / "wal_archive";
            std::filesystem::copy(archiveDir, destArchive,
                std::filesystem::copy_options::overwrite_existing |
                std::filesystem::copy_options::recursive);
            if (progress && !progress(maintenancePathBytes(archiveDir))) {
                discardStagedBackup();
                return false;
            }
        }

        // A database directory only contains tablespace markers for external
        // relations. Include the database's subdirectory from every marker so
        // physical backup/transaction snapshots are complete.
        auto tablespaceBackup = stagedBackup / "tablespaces";
        auto markerSourceDir = src / "pg_tblspc";
        if (std::filesystem::exists(markerSourceDir)) {
            for (const auto& marker : std::filesystem::directory_iterator(markerSourceDir)) {
                if (marker.path().extension() != ".path") continue;
                std::filesystem::path location;
                if (!readTablespaceMarker(marker.path(), location)) {
                    discardStagedBackup();
                    return false;
                }
                auto relationRoot = location / dbname;
                if (restorePathsOverlap(relationRoot, dst)) {
                    discardStagedBackup();
                    return false;
                }
                auto destination = tablespaceBackup / marker.path().stem();
                std::filesystem::create_directories(tablespaceBackup);
                if (std::filesystem::exists(relationRoot)) {
                    std::filesystem::create_directories(destination);
                    for (const auto& relationEntry :
                         std::filesystem::directory_iterator(relationRoot)) {
                        const auto relationDestination =
                            destination / relationEntry.path().filename();
                        if (relationEntry.is_directory()) {
                            std::filesystem::copy(relationEntry.path(), relationDestination,
                                std::filesystem::copy_options::recursive |
                                std::filesystem::copy_options::overwrite_existing);
                        } else {
                            std::filesystem::copy_file(relationEntry.path(), relationDestination,
                                std::filesystem::copy_options::overwrite_existing);
                        }
                        if (progress &&
                            !progress(maintenancePathBytes(
                                relationEntry.path()))) {
                            discardStagedBackup();
                            return false;
                        }
                    }
                } else {
                    // A newly-created tablespace may not have a database
                    // subdirectory until its first relation is created.
                    std::filesystem::create_directories(destination);
                }
            }
        }

        // PostgreSQL base backups retain UNLOGGED init forks but exclude the
        // mutable main, TOAST, and index contents. Simplified specialized
        // indexes encode their definition in the filename, so retain an
        // empty sidecar for discovery while removing every stored RID.
        // Apply the same rule to default and external tablespaces before the
        // exact-file manifest is computed.
        if (!includeUnloggedMain) {
            for (const auto& tableName : backupTables) {
                const TableSchema table = getTableSchema(dbname, tableName);
                if (!table.isUnlogged) continue;
                std::filesystem::path relationBackup = stagedBackup;
                if (!table.tablespace.empty() &&
                    table.tablespace != "pg_default") {
                    relationBackup /= "tablespaces";
                    relationBackup /= table.tablespace;
                }
                std::error_code filterError;
                if (!std::filesystem::exists(relationBackup, filterError)) {
                    if (filterError) {
                        discardStagedBackup();
                        return false;
                    }
                    continue;
                }
                for (std::filesystem::directory_iterator iterator(
                         relationBackup,
                         std::filesystem::directory_options::skip_permission_denied,
                         filterError), end;
                     !filterError && iterator != end;
                     iterator.increment(filterError)) {
                    const std::string filename =
                        iterator->path().filename().string();
                    const bool initFork = filename.size() > 5 &&
                        filename.compare(
                            filename.size() - 5, 5, ".init") == 0;
                    if (isRelationPhysicalFileName(filename, tableName) &&
                        !initFork) {
                        if (isDefinitionBearingSpecializedIndexFileName(
                                filename, tableName)) {
                            if (!index_file::writeAtomically(
                                    iterator->path(), "")) {
                                filterError = std::make_error_code(
                                    std::errc::io_error);
                            }
                        } else {
                            std::filesystem::remove_all(
                                iterator->path(), filterError);
                        }
                    }
                }
                if (filterError) {
                    discardStagedBackup();
                    return false;
                }
            }
        }
        if (!writePhysicalBackupManifest(stagedBackup, dbname)) {
            discardStagedBackup();
            return false;
        }
        const auto marker = stagedBackup / kPhysicalBackupMarker;
        if (!index_file::writeAtomically(marker, "DBMS_PHYSICAL_BACKUP_V3\n")) {
            discardStagedBackup();
            return false;
        }
        if (!syncPhysicalBackupTree(stagedBackup)) {
            discardStagedBackup();
            return false;
        }
        if (progress && !progress(0)) {
            discardStagedBackup();
            return false;
        }

        // Publish only after every copied file and directory is durable. If a
        // generation already exists, Linux rename-exchange keeps one complete
        // generation at the canonical path through the entire replacement.
        if (!validExistingDestination()) {
            discardStagedBackup();
            return false;
        }
        fileError.clear();
        const bool destinationExists = std::filesystem::exists(dst, fileError);
        if (fileError) {
            discardStagedBackup();
            return false;
        }
        if (destinationExists) {
            if (!exchangePhysicalBackupDirectories(stagedBackup, dst)) {
                discardStagedBackup();
                return false;
            }
            if (!index_file::syncDirectory(parent)) {
                // The exchange is visible but not durably published. Swap it
                // back, persist the rollback, and then discard the failed new
                // generation now held at the staging name.
                if (exchangePhysicalBackupDirectories(stagedBackup, dst) &&
                    index_file::syncDirectory(parent)) {
                    discardStagedBackup();
                } else {
                    std::cerr << "[storage] backup publication sync failed; "
                              << "retained recoverable generations at " << dst
                              << " and " << stagedBackup << std::endl;
                    stagedBackup.clear();
                }
                return false;
            }
            const std::filesystem::path oldBackup = stagedBackup;
            stagedBackup.clear();
            fileError.clear();
            std::filesystem::remove_all(oldBackup, fileError);
            if (fileError || !index_file::syncDirectory(parent)) {
                std::cerr << "[storage] published backup but could not durably "
                          << "remove the previous generation: " << oldBackup
                          << std::endl;
            }
        } else {
            fileError.clear();
            std::filesystem::rename(stagedBackup, dst, fileError);
            if (fileError) {
                discardStagedBackup();
                return false;
            }
            if (!index_file::syncDirectory(parent)) {
                std::error_code rollbackError;
                std::filesystem::rename(dst, stagedBackup, rollbackError);
                if (!rollbackError) {
                    (void)index_file::syncDirectory(parent);
                    discardStagedBackup();
                } else {
                    stagedBackup.clear();
                    std::cerr << "[storage] backup publication sync failed and "
                              << "the new generation could not be moved back"
                              << std::endl;
                }
                return false;
            }
            stagedBackup.clear();
        }
        return true;
    } catch (const std::exception& e) {
        discardStagedBackup();
        std::cerr << "[storage] physical backup failed for " << dbname
                  << ": " << e.what() << std::endl;
        return false;
    }
}

bool StorageEngine::physicalRestore(const std::string& dbname,
                                    const std::string& backupPath,
                                    const MaintenanceProgress& progress) {
    // Replacing a live database directory must not race a transaction or
    // leave open allocators/indexes/WAL managers attached to the displaced
    // files. A caller already inside any transaction cannot safely acquire
    // this database-wide exclusive lock.
    if (transactionContext().inTransaction) return false;
    const auto databaseMutex = databaseTxnLockFor(dbname);
    std::unique_lock<std::shared_mutex> databaseLock(*databaseMutex);
    PhysicalCatalogOwnership catalogOwnership(
        transactionContext(), databaseMutex, databaseLock);
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    TablespaceCatalogLock tablespaceLock(
        tablespaceCatalogLockPath(*this, dbname), true);
    if (!tablespaceLock.acquired()) return false;
    closeDatabaseCaches(dbname);
    return physicalRestoreLocked(dbname, backupPath, progress);
}

bool StorageEngine::physicalRestoreLocked(
    const std::string& dbname, const std::string& backupPath,
    const MaintenanceProgress& progress) {
    struct PhysicalSchemaReadScope {
        const StorageEngine* prior = physicalSchemaReader;
        explicit PhysicalSchemaReadScope(const StorageEngine* owner) { physicalSchemaReader = owner; }
        ~PhysicalSchemaReadScope() { physicalSchemaReader = prior; }
    } physicalSchemas(this);
    auto src = std::filesystem::path(backupPath);
    auto dst = dbPath(dbname);
    std::filesystem::path stagedDatabase;
    std::vector<DurableDirectoryReplacement> restoreReplacements;
    bool restoredCachesOpened = false;
    try {
        // Validate the complete source and every destructive destination
        // before removing the current database. In particular, aliases and
        // parent/child paths must not let remove_all(dst) erase the only
        // backup copy before directory iteration begins.
        std::string sourceDatabase;
        if (!validPhysicalBackupSource(src, sourceDatabase) ||
            sourceDatabase != dbname ||
            restorePathsOverlap(src, dst) ||
            restorePathsOverlap(src, walArchiveDir(dbname))) {
            return false;
        }

        const auto markerSourceDir = src / "pg_tblspc";
        const auto tablespaceBackup = src / "tablespaces";
        std::error_code tablespaceBackupError;
        const bool tablespaceBackupExists = std::filesystem::exists(
            tablespaceBackup, tablespaceBackupError);
        if (tablespaceBackupError ||
            (tablespaceBackupExists &&
             !std::filesystem::is_directory(
                 tablespaceBackup, tablespaceBackupError)) ||
            tablespaceBackupError) {
            return false;
        }
        std::vector<std::pair<std::filesystem::path, std::filesystem::path>>
            tablespaceSources;
        if (std::filesystem::exists(markerSourceDir)) {
            if (!std::filesystem::is_directory(markerSourceDir)) return false;
            for (const auto& marker :
                 std::filesystem::directory_iterator(markerSourceDir)) {
                if (marker.path().extension() != ".path") continue;
                std::filesystem::path location;
                if (!readTablespaceMarker(marker.path(), location)) {
                    return false;
                }
                const auto source =
                    tablespaceBackup / marker.path().stem();
                if (!std::filesystem::is_directory(source)) return false;
                const auto relationRoot = location / dbname;
                if (restorePathsOverlap(src, relationRoot) ||
                    restorePathsOverlap(dst, relationRoot) ||
                    restorePathsOverlap(walArchiveDir(dbname), relationRoot)) {
                    return false;
                }
                for (const auto& [existingSource, existingTarget] :
                     tablespaceSources) {
                    (void)existingSource;
                    if (restorePathsOverlap(existingTarget, relationRoot)) {
                        return false;
                    }
                }
                tablespaceSources.emplace_back(source, relationRoot);
            }
        }

        // Materialize the complete replacement beside the destination before
        // touching the live database. A marker-bearing backup can still
        // contain an unreadable/truncated entry; copying directly into dst
        // after remove_all(dst) turned that ordinary restore error into data
        // loss.
        static std::atomic<uint64_t> restoreSequence{0};
        const auto siblingPath = [&](std::string_view purpose) {
            return std::filesystem::path(
                dst.string() + "." + std::string(purpose) + "." +
                std::to_string(::getpid()) + "." +
                std::to_string(restoreSequence.fetch_add(
                    1, std::memory_order_relaxed)));
        };
        std::error_code fileError;
        const auto parent = dst.parent_path().empty()
            ? std::filesystem::path(".") : dst.parent_path();
        std::filesystem::create_directories(parent, fileError);
        if (fileError) return false;
        for (size_t attempt = 0; attempt < 1000; ++attempt) {
            auto candidate = siblingPath("restore_staging");
            fileError.clear();
            if (std::filesystem::create_directory(candidate, fileError)) {
                stagedDatabase = std::move(candidate);
                break;
            }
            if (fileError &&
                !std::filesystem::exists(candidate)) {
                return false;
            }
        }
        if (stagedDatabase.empty()) return false;
        const auto discardStagedDatabase = [&]() {
            if (stagedDatabase.empty()) return;
            std::error_code cleanupError;
            std::filesystem::remove_all(stagedDatabase, cleanupError);
            stagedDatabase.clear();
        };
        if (progress && !progress(0)) {
            discardStagedDatabase();
            return false;
        }

        for (const auto& entry : std::filesystem::directory_iterator(src)) {
            const auto filename = entry.path().filename().string();
            if (filename == kPhysicalBackupMarker ||
                filename == kPhysicalBackupManifest || filename == ".lockmgr" ||
                filename == ".runtime_stats.lock" || filename == ".sql_stats.lock" ||
                filename.rfind(".runtime_stats.tmp.", 0) == 0 ||
                filename.rfind(".sql_stats.tmp.", 0) == 0) {
                continue;
            }
            auto destPath = stagedDatabase / entry.path().filename();
            if (entry.is_directory() &&
                (entry.path().filename() == "wal_archive" ||
                 entry.path().filename() == "tablespaces")) {
                // Backup-only containers are restored to their external
                // destinations, never copied into the active database root.
                continue;
            }
            if (entry.is_directory()) {
                std::filesystem::copy(entry.path(), destPath,
                    std::filesystem::copy_options::recursive);
            } else {
                std::filesystem::copy_file(entry.path(), destPath,
                    std::filesystem::copy_options::overwrite_existing);
            }
            if (progress && !progress(maintenancePathBytes(entry.path()))) {
                discardStagedDatabase();
                return false;
            }
        }
        if (sequenceRollbackDatabase && *sequenceRollbackDatabase == dbname &&
            !preserveSequenceRuntimeForks(dst, stagedDatabase)) {
            discardStagedDatabase();
            return false;
        }
        if (!syncPhysicalBackupTree(stagedDatabase)) {
            discardStagedDatabase();
            return false;
        }

        restoreReplacements.push_back({dst, stagedDatabase});
        stagedDatabase.clear();

        const auto discardUnpublished = [&]() {
            for (auto& replacement : restoreReplacements) {
                if (!replacement.published) {
                    (void)discardDirectoryReplacement(replacement);
                }
            }
        };
        const auto rollbackPublished = [&]() {
            if (restoredCachesOpened) {
                closeDatabaseCaches(dbname);
                if (catalogService_) catalogService_->evict(dbname);
                restoredCachesOpened = false;
            }
            bool ok = true;
            for (auto it = restoreReplacements.rbegin();
                 it != restoreReplacements.rend(); ++it) {
                if (it->published && !rollbackDirectoryReplacement(*it)) {
                    ok = false;
                }
            }
            discardUnpublished();
            return ok;
        };

        const auto srcArchive = src / "wal_archive";
        const auto dstArchive = walArchiveDir(dbname);
        std::error_code archiveError;
        const bool sourceArchiveExists =
            std::filesystem::exists(srcArchive, archiveError);
        if (archiveError ||
            (sourceArchiveExists &&
             !std::filesystem::is_directory(srcArchive, archiveError)) ||
            archiveError) {
            discardUnpublished();
            return false;
        }
        const bool targetArchiveExists =
            std::filesystem::exists(dstArchive, archiveError);
        if (archiveError) {
            discardUnpublished();
            return false;
        }
        if (sourceArchiveExists || targetArchiveExists) {
            DurableDirectoryReplacement archiveReplacement;
            const std::filesystem::path* archiveSource =
                sourceArchiveExists ? &srcArchive : nullptr;
            if (!stageDirectoryReplacement(
                    archiveSource, dstArchive, "restore_archive",
                    archiveReplacement)) {
                discardUnpublished();
                return false;
            }
            restoreReplacements.push_back(std::move(archiveReplacement));
        }

        for (const auto& [source, target] : tablespaceSources) {
            DurableDirectoryReplacement tablespaceReplacement;
            if (!stageDirectoryReplacement(
                    &source, target, "restore_tablespace",
                    tablespaceReplacement)) {
                discardUnpublished();
                return false;
            }
            restoreReplacements.push_back(
                std::move(tablespaceReplacement));
        }

        // Detect a backup source changed while its files were staged. The
        // staged generations are fixed now; no live target has been touched.
        std::string revalidatedDatabase;
        if (!validPhysicalBackupSource(src, revalidatedDatabase) ||
            revalidatedDatabase != dbname) {
            discardUnpublished();
            return false;
        }
        if (progress && !progress(0)) {
            discardUnpublished();
            return false;
        }

        // Staging still leaves the live directory and its catalog generation
        // unchanged. Keep that committed generation readable by foreign
        // metadata observers; invalid/cancelled staging must not evict it.
        // Invalidate only at the actual physical publication boundary.
        if (catalogService_) catalogService_->evict(dbname);
        for (auto& replacement : restoreReplacements) {
            if (!publishDirectoryReplacement(replacement)) {
                if (!rollbackPublished()) {
                    std::cerr << "[storage] restore rollback incomplete; "
                              << "retained recovery generations beside targets"
                              << std::endl;
                }
                return false;
            }
        }

        // Public physical backups omit mutable UNLOGGED forks, while
        // transaction snapshots deliberately include them. Distinguish the
        // two from the restored heap files: reset omitted forks from their
        // init images and rebuild every index, but preserve transaction
        // snapshots' rows and reindex their B-trees. Keep displaced
        // generations until this work succeeds so a rebuild failure can
        // still roll the restore back.
        restoredCachesOpened = true;
        for (const auto& tableName : getTableNames(dbname)) {
            const TableSchema table = getTableSchema(dbname, tableName);
            if (!table.isUnlogged) continue;

            std::set<std::filesystem::path> mainHeapForks;
            if (table.partitionType == TableSchema::PartitionType::None) {
                mainHeapForks.insert(dataPath(dbname, tableName));
            } else {
                for (const auto& leaf : partitionLeaves(table)) {
                    mainHeapForks.insert(partitionDataPath(
                        dbname, tableName, leaf.partition));
                    if (!leaf.subPartition.empty()) {
                        mainHeapForks.insert(partitionDataPath(
                            dbname, tableName, leaf.partition,
                            leaf.subPartition));
                    }
                }
            }

            bool anyMainFork = false;
            bool allMainForks = true;
            for (const auto& path : mainHeapForks) {
                std::error_code forkError;
                const bool exists = std::filesystem::exists(path, forkError);
                if (forkError ||
                    (exists &&
                     !std::filesystem::is_regular_file(path, forkError)) ||
                    forkError) {
                    allMainForks = false;
                    anyMainFork = true;
                    break;
                }
                anyMainFork = anyMainFork || exists;
                allMainForks = allMainForks && exists;
            }
            if (anyMainFork && !allMainForks) {
                if (!rollbackPublished()) {
                    std::cerr << "[storage] restore fork validation rollback "
                                 "incomplete; retained recovery generations"
                              << std::endl;
                }
                return false;
            }

            const bool initialized = !anyMainFork
                ? resetTableStorage(dbname, tableName)
                : reindex(dbname, tableName) == DBStatus::OK;
            if (!initialized) {
                if (!rollbackPublished()) {
                    std::cerr << "[storage] restore index initialization rollback "
                                 "incomplete; retained recovery generations"
                              << std::endl;
                }
                return false;
            }
            if (anyMainFork && std::any_of(
                    table.cols, table.cols + table.len,
                    [](const Column& column) {
                        return column.isVariableLength;
                    })) {
                BPTree toastIndex(toastIndexPath(dbname, tableName));
                if (!toastIndex.open() || !toastIndex.flush()) {
                    if (!rollbackPublished()) {
                        std::cerr << "[storage] restore TOAST index rollback "
                                     "incomplete; retained recovery generations"
                                  << std::endl;
                    }
                    return false;
                }
            }
        }

        for (auto& replacement : restoreReplacements) {
            if (!discardDirectoryReplacement(replacement)) {
                std::cerr << "[storage] restore completed but an old generation "
                          << "could not be durably removed beside "
                          << replacement.target << std::endl;
            }
        }
        return true;
    } catch (...) {
        if (restoredCachesOpened) {
            closeDatabaseCaches(dbname);
            if (catalogService_) catalogService_->evict(dbname);
        }
        bool rollbackOk = true;
        for (auto it = restoreReplacements.rbegin();
             it != restoreReplacements.rend(); ++it) {
            if (it->published && !rollbackDirectoryReplacement(*it)) {
                rollbackOk = false;
            }
        }
        for (auto& replacement : restoreReplacements) {
            if (!replacement.published) {
                (void)discardDirectoryReplacement(replacement);
            }
        }
        if (!stagedDatabase.empty()) {
            std::error_code cleanupError;
            std::filesystem::remove_all(stagedDatabase, cleanupError);
        }
        if (!rollbackOk) {
            std::cerr << "[storage] restore exception left recovery "
                         "generations beside their targets" << std::endl;
        }
        return false;
    }
}

Lsn StorageEngine::switchWal(const std::string& dbname) {
    WALManager* wal = getWAL(dbname);
    if (!wal) return INVALID_LSN;
    return wal->switchWal();
}

// ========================================================================
// PITR: point-in-time recovery
// ========================================================================

static bool pitrSegmentNumber(const std::string& name,
                              uint32_t timeline, uint32_t& segment) {
    if (name.size() != 24) return false;
    uint32_t parts[3]{};
    for (size_t i = 0; i < 3; ++i) {
        const char* begin = name.data() + i * 8;
        const char* end = begin + 8;
        const auto parsed = std::from_chars(begin, end, parts[i], 16);
        if (parsed.ec != std::errc{} || parsed.ptr != end) return false;
    }
    // This WAL format uses the final eight digits as its segment number;
    // the middle log field is always zero (see WALManager::segmentPath).
    if (parts[0] != timeline || parts[1] != 0) return false;
    segment = parts[2];
    return true;
}

bool StorageEngine::pitrRestore(const std::string& dbname,
                                const std::string& backupPath,
                                const std::string& archiveDir,
                                uint64_t targetEpoch,
                                const MaintenanceProgress& progress) {
    if (targetEpoch == 0) {
        std::cerr << "[pitr] recovery target epoch is required" << std::endl;
        return false;
    }
    if (!physicalRestore(dbname, backupPath, progress)) return false;

    // Roll-forward material: archived segments of this database's timeline
    // that are newer than the backup. The backup carries its own pg_wal up
    // to the backup checkpoint; the archive holds everything after that.
    const auto srcArchive = std::filesystem::path(archiveDir);
    std::error_code ec;
    if (!std::filesystem::is_directory(srcArchive, ec) || ec) {
        std::cerr << "[pitr] archive directory not found: " << archiveDir
                  << std::endl;
        return false;
    }
    auto walDir = dbPath(dbname) / "pg_wal";
    std::filesystem::create_directories(walDir, ec);
    if (ec) return false;

    // A base backup can itself follow an earlier PITR fork. Recover the
    // timeline selected by that image, not timeline 1 or the highest-named
    // unrelated segment. Opening the restored WAL uses the same durable
    // selector/inference and content validation as ordinary startup.
    uint32_t backupTimeline = 0;
    {
        WALManager restoredWal(walDir);
        if (!restoredWal.ensureOpen(false)) return false;
        backupTimeline = restoredWal.timelineId();
    }

    // Only the selected stream determines the overlap boundary. Older
    // abandoned timelines can retain numerically much newer segments.
    uint32_t backupMaxSeg = 0;
    {
        std::error_code iterEc;
        std::filesystem::directory_iterator it(walDir, iterEc), end;
        if (iterEc) return false;
        for (; it != end; it.increment(iterEc)) {
            if (iterEc) return false;
            const auto& entry = *it;
            const std::string name = entry.path().filename().string();
            uint32_t segNo = 0;
            if (!pitrSegmentNumber(name, backupTimeline, segNo)) continue;
            if (!entry.is_regular_file(iterEc) || iterEc) return false;
            backupMaxSeg = std::max(backupMaxSeg, segNo);
        }
        if (iterEc) return false;
    }

    size_t copied = 0;
    {
        std::error_code iterEc;
        std::filesystem::directory_iterator it(srcArchive, iterEc), end;
        if (iterEc) return false;
        for (; it != end; it.increment(iterEc)) {
            if (iterEc) return false;
            const auto& entry = *it;
            const std::string name = entry.path().filename().string();
            uint32_t segNo = 0;
            if (!pitrSegmentNumber(name, backupTimeline, segNo)) continue;
            if (segNo < backupMaxSeg) continue;
            if (!entry.is_regular_file(iterEc) || iterEc) return false;
            std::error_code copyEc;
            std::filesystem::copy_file(
                entry.path(), walDir / name,
                std::filesystem::copy_options::overwrite_existing, copyEc);
            if (copyEc) {
                std::cerr << "[pitr] failed to restore archived segment " << name
                          << ": " << copyEc.message() << std::endl;
                return false;
            }
            if (progress && !progress(maintenancePathBytes(entry.path())))
                return false;
            ++copied;
        }
        if (iterEc) return false;
    }
    // Archived history replaces the ready/done bookkeeping of the backup;
    // recovery decides from content, not markers.
    std::filesystem::remove_all(walDir / "archive_status", ec);

    // Persist the target so the NEXT process startup (where recovery
    // actually replays) sees it — the restore command runs in a different
    // process than the roll-forward.
    const auto targetPath = walDir / "recovery_target";
    if (!index_file::writeAtomically(
            targetPath, std::to_string(targetEpoch) + "\n")) {
        std::cerr << "[pitr] cannot persist recovery target" << std::endl;
        return false;
    }
    std::cerr << "[pitr] restored " << copied
              << " archived segment(s) for " << dbname
              << "; recovery target epoch " << targetEpoch << std::endl;
    setRecoveryTargetEpoch(targetEpoch);
    return true;
}

// ========================================================================
// VACUUM: reclaim space from deleted rows
// ========================================================================
size_t StorageEngine::vacuum(const std::string& dbname,
                             const std::string& tablename,
                             bool concurrent,
                             int workers) {
    if (!databaseExists(dbname) || !tableExists(dbname, tablename)) return 0;
    const auto locksBeforeVacuum = lockManager_.captureCheckpoint();
    struct RestoreVacuumLocks {
        LockManager& manager;
        const LockManager::LockCheckpoint& before;
        ~RestoreVacuumLocks() { manager.rollbackToCheckpoint(before); }
    } restoreVacuumLocks{lockManager_, locksBeforeVacuum};
    if (concurrent) {
        if (!lockManager_.lockShared(tablename)) return 0;
    } else {
        if (!lockManager_.lockExclusive(tablename)) return 0;
    }

    TableSchema tbl = getTableSchema(dbname, tablename);
    PageAllocator* pa = getPageAllocator(dbname, tablename);
    if (!pa) return 0;

    uint32_t np = pa->numPages();
    size_t freedPages = 0;

    // Compact one page: returns true when the page was returned to the
    // allocator's free list.  Disjoint page ranges run concurrently; every
    // storage primitive below (buffer pool pins, FSM/VM updates, page
    // frees) is internally serialized.
    auto vacuumPage = [&](uint32_t pid) -> bool {
        checkForQueryInterrupt();
        // A buffer pin prevents eviction, not concurrent tuple changes.
        // Preserve a caller's pre-existing page mode as well as its locks
        // on other resources; page locks themselves have no nesting count.
        const auto locksBeforePage = lockManager_.captureCheckpoint();
        RestoreVacuumLocks restorePageLocks{lockManager_, locksBeforePage};
        if (!lockManager_.pageLockExclusive(dbname, tablename, pid))
            throw DbError("55P03", "could not obtain heap page lock during VACUUM");
        char* buf = pa->fetchPage(pid);
        if (!buf) throw DbError("58030", "could not read heap page during VACUUM");
        struct PagePinGuard {
            PageAllocator& allocator;
            uint32_t pageId;
            bool pinned = true;
            void unpin() { if (pinned) { allocator.unpinPage(pageId); pinned = false; } }
            ~PagePinGuard() { unpin(); }
        } pinGuard{*pa, pid};
        PageWrapper page(buf, pa->pageSize(), tbl.formatVersion);

        // Skip pages that are already empty or fully live
        uint16_t beforeLive = page.liveCount();
        uint16_t beforeSlots = page.slotCount();
        if (beforeSlots == 0 || beforeLive == beforeSlots) return false;

        // Compact: move live records together, keep slotIds stable
        page.compact();
        pa->markDirty(pid);

        // Update FSM with reclaimed free space
        size_t freePct = page.freeSpace() * 100 / pa->pageSize();
        FreeSpaceMap* fsm = getFSM(dbname, tablename);
        if (!fsm) throw DbError("58030", "could not open free space map during VACUUM");
        fsm->setFreePercent(pid, static_cast<uint8_t>(freePct));

        // LP_NORMAL only describes line-pointer state; it does not prove
        // that every tuple is visible to every active snapshot. This compact
        // VACUUM path has no OldestXmin/visibility-horizon check, so claiming
        // AllVisible here can hide an older tuple version from a snapshot
        // reader. Stay conservative until VACUUM proves that horizon.
        VisibilityMap* vm = getVM(dbname, tablename);
        if (!vm) throw DbError("58030", "could not open visibility map during VACUUM");
        vm->setAllVisible(pid, false);

        // If page is now empty, return it to the free list
        if (page.liveCount() == 0) {
            pinGuard.unpin();
            pa->freePage(pid);
            return true;
        }
        return false;
    };

    const uint32_t heapPages = np > 1 ? np - 1 : 0;
    int nWorkers = workers > 1 ? workers : 1;
    if (nWorkers > static_cast<int>(heapPages)) nWorkers = static_cast<int>(heapPages);
    if (nWorkers > 1) {
        // Shard [1, np) into contiguous ranges; each worker vacuums its own
        // slice so no two threads ever pin the same page.
        std::vector<std::thread> pool;
        std::atomic<size_t> freed{0};
        std::atomic<bool> stop{false};
        std::mutex failureMutex;
        std::exception_ptr failure;
        const auto interruptState = currentQueryInterruptState();
        const int lockTimeout = lockManager_.getLockTimeout();
        const auto recordFailure = [&] {
            std::lock_guard<std::mutex> guard(failureMutex);
            if (!failure) failure = std::current_exception();
            stop.store(true, std::memory_order_release);
        };
        uint32_t chunk = (heapPages + nWorkers - 1) / nWorkers;
        try {
            pool.reserve(static_cast<size_t>(nWorkers));
            for (int w = 0; w < nWorkers && !stop.load(std::memory_order_acquire); ++w) {
                uint32_t lo = 1 + static_cast<uint32_t>(w) * chunk;
                uint32_t hi = std::min(lo + chunk, np);
                if (lo >= hi) break;
                pool.emplace_back([&, interruptState](uint32_t a, uint32_t b) {
                    bool lockSettingsReady = false;
                    try {
                        setCurrentQueryInterruptState(interruptState);
                        lockManager_.setLockTimeout(lockTimeout);
                        lockSettingsReady = true;
                        lockManager_.setInterruptHandler([&] {
                            checkForQueryInterrupt();
                            if (stop.load(std::memory_order_acquire))
                                throw DbError("57014", "parallel VACUUM stopped after worker failure");
                        });
                        for (uint32_t pid = a; pid < b && !stop.load(std::memory_order_acquire); ++pid) {
                            if (vacuumPage(pid)) freed.fetch_add(1);
                        }
                    } catch (...) {
                        recordFailure();
                    }
                    if (lockSettingsReady) lockManager_.clearInterruptHandler();
                    setCurrentQueryInterruptState(nullptr);
                }, lo, hi);
            }
        } catch (...) {
            // std::thread construction may fail after earlier workers were
            // launched. Stop and join them before propagating that failure.
            recordFailure();
        }
        for (auto& t : pool) t.join();
        if (failure) std::rethrow_exception(failure);
        freedPages = freed.load();
    } else {
        for (uint32_t pid = 1; pid < np; ++pid) {
            if (vacuumPage(pid)) freedPages++;
        }
    }

    lockManager_.unlock(tablename);

    // Reset dead tuple count after successful vacuum
    if (freedPages > 0) {
        auto key = std::make_pair(dbname, tablename);
        std::lock_guard<std::mutex> lock(deadTupleMutex_);
        deadTupleCounts_[key] = 0;
    }

    // Clean up orphaned TOAST entries
    vacuumToast(dbname, tablename);

    return freedPages;
}

// ========================================================================
// VACUUM TOAST: remove orphaned toast files not referenced by any row
// ========================================================================
size_t StorageEngine::vacuumToast(const std::string& dbname,
                                   const std::string& tablename) {
    if (!databaseExists(dbname) || !tableExists(dbname, tablename)) return 0;

    // UPDATE can replace a tuple in place, so its old TOAST marker is no
    // longer discoverable by scanning the current heap.  An older snapshot
    // may still need that value, however.  Defer reclamation while any
    // transaction on this database is active; a transaction that begins
    // after this check cannot see versions retired by an earlier commit.
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        for (const auto& [transactionId, activeDatabase] :
             activeTransactionDatabases()) {
            (void)transactionId;
            if (activeDatabase == dbname) return 0;
        }
    }
    // Acquiring a stronger mode converts an existing caller token; it
    // does not necessarily add an acquisition. Do not blindly unlock it.
    const auto locksBeforeToast = lockManager_.captureCheckpoint();
    struct RestoreToastLocks {
        LockManager& manager;
        const LockManager::LockCheckpoint& before;
        ~RestoreToastLocks() { manager.rollbackToCheckpoint(before); }
    } restoreToastLocks{lockManager_, locksBeforeToast};
    if (!lockManager_.lockExclusive(tablename)) return 0;

    const TableSchema tbl = getTableSchema(dbname, tablename);
    std::set<uint64_t> activeToastIds;

    // A tuple can be invisible to the vacuuming transaction while an older
    // snapshot can still read it.  Scan every physical live slot, rather than
    // forEachRow's MVCC-visible subset, so TOAST is never reclaimed ahead of
    // the heap tuple that references it.
    std::vector<std::filesystem::path> heapRelations;
    if (tbl.partitionType == TableSchema::PartitionType::None) {
        heapRelations.push_back(dataPath(dbname, tablename));
    } else {
        std::vector<std::string> partitionNames;
        if (tbl.partitionType == TableSchema::PartitionType::Range) {
            for (const auto& partition : tbl.rangePartitions)
                partitionNames.push_back(partition.first);
        } else if (tbl.partitionType == TableSchema::PartitionType::List) {
            for (const auto& partition : tbl.listPartitions)
                partitionNames.push_back(partition.first);
        } else if (tbl.partitionType == TableSchema::PartitionType::Hash) {
            for (size_t i = 0; i < tbl.hashPartitions; ++i)
                partitionNames.push_back("p" + std::to_string(i));
        }
        if (!tbl.defaultPartitionName.empty() &&
            std::find(partitionNames.begin(), partitionNames.end(),
                      tbl.defaultPartitionName) == partitionNames.end()) {
            partitionNames.push_back(tbl.defaultPartitionName);
        }
        for (const auto& partition : partitionNames) {
            if (tbl.subPartitionType == TableSchema::PartitionType::Hash) {
                for (size_t i = 0; i < tbl.subHashPartitions; ++i) {
                    heapRelations.push_back(partitionDataPath(
                        dbname, tablename, partition,
                        "sp" + std::to_string(i)));
                }
            } else {
                heapRelations.push_back(partitionDataPath(
                    dbname, tablename, partition));
            }
        }
    }

    auto collectReferences = [&](PageAllocator& allocator) -> bool {
        const uint32_t pageCount = allocator.numPages();
        for (uint32_t pageId = 1; pageId < pageCount; ++pageId) {
            const auto locksBeforePage = lockManager_.captureCheckpoint();
            RestoreToastLocks restorePageLocks{lockManager_, locksBeforePage};
            if (!lockManager_.pageLockShared(dbname, tablename, pageId))
                return false;
            char* buffer = allocator.fetchPage(pageId);
            if (!buffer) return false;
            struct PagePinGuard {
                PageAllocator& owner;
                uint32_t pageId;
                ~PagePinGuard() { owner.unpinPage(pageId); }
            } pinGuard{allocator, pageId};
            PageWrapper page(buffer, allocator.pageSize(), tbl.formatVersion);
            bool valid = page.isValid();
            if (valid) {
                page.forEachLive([&](uint16_t, const char* tuple, size_t length) {
                    if (!valid || length < sizeof(HeapTupleHeaderData)) {
                        valid = false;
                        return;
                    }
                    const auto* header = castHeapHeader(tuple);
                    const size_t minimumHeader = rowHeaderSize(
                        tbl.formatVersion, tbl.len);
                    if (header->t_hoff < minimumHeader ||
                        header->t_hoff > length) {
                        valid = false;
                        return;
                    }
                    const std::string row(
                        tuple + header->t_hoff, length - header->t_hoff);
                    for (size_t i = 0; i < tbl.len; ++i) {
                        if (!tbl.cols[i].isVariableLength) continue;
                        uint64_t toastId = 0;
                        if (parseToastMarker(
                                extractColumnValueStatic(row, tbl, i),
                                toastId)) {
                            activeToastIds.insert(toastId);
                        }
                    }
                });
            }
            if (!valid) return false;
        }
        return true;
    };

    for (const auto& relation : heapRelations) {
        std::error_code pathError;
        if (!std::filesystem::exists(relation, pathError)) {
            // DEFAULT partitions are created lazily and may have no file yet.
            if (!pathError && !tbl.defaultPartitionName.empty() &&
                relation.string().find("#" + tbl.defaultPartitionName) !=
                    std::string::npos) {
                continue;
            }
            return 0;
        }
        if (pathError || !std::filesystem::is_regular_file(relation, pathError) ||
            pathError) {
            return 0;
        }
        if (tbl.partitionType == TableSchema::PartitionType::None) {
            PageAllocator* allocator = getPageAllocator(dbname, tablename);
            if (!allocator || !collectReferences(*allocator)) return 0;
        } else {
            PageAllocator allocator(
                relation.string(), tbl.rowSize(),
                pageSizeForFormatVersion(tbl.formatVersion),
                tbl.formatVersion);
            if (!allocator.open() || !collectReferences(allocator)) return 0;
            allocator.close();
        }
    }

    const auto toastHeapPath = toastDataPath(dbname, tablename);
    const auto toastTreePath = toastIndexPath(dbname, tablename);
    std::error_code toastPathError;
    const bool heapExists = std::filesystem::exists(
        toastHeapPath, toastPathError);
    if (toastPathError) return 0;
    const bool indexExists = std::filesystem::exists(
        toastTreePath, toastPathError);
    if (toastPathError || heapExists != indexExists) return 0;
    if (!heapExists) return 0;
    if (!std::filesystem::is_regular_file(toastHeapPath, toastPathError) ||
        toastPathError ||
        !std::filesystem::is_regular_file(toastTreePath, toastPathError) ||
        toastPathError) {
        return 0;
    }

    PageAllocator* toastPages = getToastPageAllocator(dbname, tablename);
    BPTree* toastIndex = getToastIndex(dbname, tablename);
    if (!toastPages || !toastIndex) return 0;

    struct ToastChunkRef {
        uint64_t toastId = 0;
        uint32_t sequence = 0;
        uint32_t pageId = 0;
        uint16_t slotId = 0;
        int64_t rid = -1;
        std::string key;
    };
    std::map<uint64_t, std::vector<ToastChunkRef>> chunksById;
    std::set<std::string> seenKeys;
    std::vector<int64_t> heapRids;
    bool toastValid = true;
    const uint32_t toastPageCount = toastPages->numPages();
    for (uint32_t pageId = 1; pageId < toastPageCount; ++pageId) {
        if (!lockManager_.pageLockShared(
                dbname, tablename + ".toast", pageId)) {
            return 0;
        }
        char* buffer = toastPages->fetchPage(pageId);
        if (!buffer) {
            lockManager_.pageUnlock(
                dbname, tablename + ".toast", pageId);
            return 0;
        }
        PageWrapper page(
            buffer, toastPages->pageSize(), DATA_FILE_FORMAT_VERSION);
        toastValid = page.isValid();
        if (toastValid) {
            page.forEachLive([&](uint16_t slotId, const char* row,
                                 size_t rowLength) {
                if (!toastValid || rowLength < TOAST_CHUNK_HEADER_SIZE) {
                    toastValid = false;
                    return;
                }
                uint64_t toastId = 0;
                uint32_t sequence = 0;
                std::memcpy(&toastId, row, sizeof(toastId));
                std::memcpy(&sequence, row + sizeof(toastId),
                            sizeof(sequence));
                if (toastId == 0) {
                    toastValid = false;
                    return;
                }
                const std::string key = toastIndexKey(toastId, sequence);
                const int64_t rid = encodeRid(pageId, slotId);
                int64_t indexedRid = -1;
                if (!seenKeys.insert(key).second ||
                    !toastIndex->search(key, indexedRid) ||
                    indexedRid != rid) {
                    toastValid = false;
                    return;
                }
                chunksById[toastId].push_back(
                    {toastId, sequence, pageId, slotId, rid, key});
                heapRids.push_back(rid);
            });
        }
        toastPages->unpinPage(pageId);
        lockManager_.pageUnlock(dbname, tablename + ".toast", pageId);
        if (!toastValid) return 0;
    }

    auto indexedRids = toastIndex->allValues();
    std::sort(heapRids.begin(), heapRids.end());
    std::sort(indexedRids.begin(), indexedRids.end());
    if (heapRids != indexedRids) return 0;

    // A referenced object must have a contiguous sequence beginning at zero.
    // If it is corrupt, fail closed instead of deleting unrelated objects.
    for (uint64_t toastId : activeToastIds) {
        auto it = chunksById.find(toastId);
        if (it == chunksById.end()) return 0;
        auto& chunks = it->second;
        std::sort(chunks.begin(), chunks.end(),
                  [](const ToastChunkRef& left,
                     const ToastChunkRef& right) {
                      return left.sequence < right.sequence;
                  });
        for (size_t i = 0; i < chunks.size(); ++i) {
            if (chunks[i].sequence != i) return 0;
        }
    }

    size_t removedObjects = 0;
    for (auto& [toastId, chunks] : chunksById) {
        if (activeToastIds.count(toastId) != 0) continue;
        bool removedObject = true;
        for (const auto& chunk : chunks) {
            if (!lockManager_.pageLockExclusive(
                    dbname, tablename + ".toast", chunk.pageId)) {
                removedObject = false;
                break;
            }
            char* buffer = toastPages->fetchPage(chunk.pageId);
            if (!buffer) {
                lockManager_.pageUnlock(
                    dbname, tablename + ".toast", chunk.pageId);
                removedObject = false;
                break;
            }
            PageWrapper page(
                buffer, toastPages->pageSize(), DATA_FILE_FORMAT_VERSION);
            const char* row = nullptr;
            size_t rowLength = 0;
            uint64_t storedId = 0;
            uint32_t storedSequence = 0;
            const bool sameChunk =
                page.read(chunk.slotId, row, rowLength) &&
                rowLength >= TOAST_CHUNK_HEADER_SIZE;
            if (sameChunk) {
                std::memcpy(&storedId, row, sizeof(storedId));
                std::memcpy(&storedSequence, row + sizeof(storedId),
                            sizeof(storedSequence));
            }
            if (!sameChunk || storedId != chunk.toastId ||
                storedSequence != chunk.sequence ||
                !page.remove(chunk.slotId)) {
                toastPages->unpinPage(chunk.pageId);
                lockManager_.pageUnlock(
                    dbname, tablename + ".toast", chunk.pageId);
                removedObject = false;
                break;
            }
            toastPages->markDirty(chunk.pageId);
            if (!toastIndex->removeMulti(chunk.key, chunk.rid)) {
                page.restore(chunk.slotId);
                toastPages->markDirty(chunk.pageId);
                toastPages->unpinPage(chunk.pageId);
                lockManager_.pageUnlock(
                    dbname, tablename + ".toast", chunk.pageId);
                removedObject = false;
                break;
            }
            toastPages->unpinPage(chunk.pageId);
            lockManager_.pageUnlock(
                dbname, tablename + ".toast", chunk.pageId);
        }
        if (!removedObject) break;
        ++removedObjects;
    }
    if (!toastPages->flush() || !toastIndex->flush()) return 0;
    return removedObjects;
}

// ========================================================================
// VACUUM FULL: completely rewrite table, reclaiming all dead space
// ========================================================================
size_t StorageEngine::vacuumFull(const std::string& dbname,
                                 const std::string& tablename,
                                 bool* succeeded) {
    if (succeeded) *succeeded = false;
    if (!databaseExists(dbname) || !tableExists(dbname, tablename)) return 0;
    // VACUUM is not transaction-safe and PostgreSQL rejects it inside an
    // explicit transaction.  Rewriting here would otherwise escape rollback.
    if (transactionContext().inTransaction) return 0;
    if (!lockManager_.lockExclusive(tablename)) return 0;
    std::unique_ptr<int, std::function<void(int*)>> tableLockGuard(
        reinterpret_cast<int*>(1),
        [&](int*) { lockManager_.unlock(tablename); });
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);

    const TableSchema tbl = getTableSchema(dbname, tablename);
    const std::string tableKey = dbname + "/" + tablename;
    const std::string secondaryPrefix = tableKey + "/";
    const std::string hashPrefix = dbname + "." + tablename + ".";

    struct RewriteRelation {
        std::filesystem::path path;
        std::vector<std::string> tuples;
    };
    std::vector<RewriteRelation> relations;
    const auto addRelation = [&](const std::filesystem::path& path) {
        if (std::none_of(relations.begin(), relations.end(),
                         [&](const RewriteRelation& relation) {
                             return relation.path == path;
                         })) {
            relations.push_back({path, {}});
        }
    };

    if (tbl.partitionType == TableSchema::PartitionType::None) {
        addRelation(dataPath(dbname, tablename));
    } else {
        std::vector<std::string> partitionNames;
        if (tbl.partitionType == TableSchema::PartitionType::Range) {
            for (const auto& partition : tbl.rangePartitions)
                partitionNames.push_back(partition.first);
        } else if (tbl.partitionType == TableSchema::PartitionType::List) {
            for (const auto& partition : tbl.listPartitions)
                partitionNames.push_back(partition.first);
        } else if (tbl.partitionType == TableSchema::PartitionType::Hash) {
            for (size_t i = 0; i < tbl.hashPartitions; ++i)
                partitionNames.push_back("p" + std::to_string(i));
        }
        if (!tbl.defaultPartitionName.empty() &&
            std::find(partitionNames.begin(), partitionNames.end(),
                      tbl.defaultPartitionName) == partitionNames.end()) {
            partitionNames.push_back(tbl.defaultPartitionName);
        }
        for (const auto& partition : partitionNames) {
            if (tbl.subPartitionType == TableSchema::PartitionType::Hash) {
                for (size_t i = 0; i < tbl.subHashPartitions; ++i) {
                    addRelation(partitionDataPath(
                        dbname, tablename, partition,
                        "sp" + std::to_string(i)));
                }
            } else {
                addRelation(partitionDataPath(
                    dbname, tablename, partition));
            }
        }
    }
    if (relations.empty()) {
        return 0;
    }

    // Capture access-method definitions while their files still exist.  Some
    // simplified access methods currently use the sidecar itself as their
    // catalog, so deleting first would lose the information needed to rebuild.
    const auto secondaryIndexes = getIndexMetadata(dbname, tablename);
    const auto compositeIndexes = getCompositeIndexes(dbname, tablename);
    const auto hashColumns = getHashIndexedColumns(dbname, tablename);
    const auto bloomColumns = getBloomIndexedColumns(dbname, tablename);
    const auto fullTextColumns = getFullTextIndexedColumns(dbname, tablename);
    const auto ginColumns = getGinIndexedColumns(dbname, tablename);
    const auto gistColumns = getGiSTIndexedColumns(dbname, tablename);
    const auto spgistColumns = getSPGiSTIndexedColumns(dbname, tablename);
    const auto brinColumns = getBrinIndexedColumns(dbname, tablename);

    ReadView readView;
    {
        std::lock_guard<std::mutex> lock(globalTxnMutex());
        readView.creatorTxnId = 0;
        readView.lowLimitId = TxnIdGenerator::instance().maxCommittedTxId() + 1;
        readView.upLimitId = activeTransactions().empty()
            ? readView.lowLimitId : *activeTransactions().begin();
        readView.activeTxnIds = activeTransactions();
        readView.subTxnIds.clear();
        readView.commitLog = getCommitLog(dbname);
    }

    // Read full tuples, not reconstructed SQL maps.  This preserves the null
    // bitmap, exact binary encodings and existing TOAST object identifiers.
    auto scanRelation = [&](RewriteRelation& relation,
                            PageAllocator& allocator) -> bool {
        const uint32_t pageCount = allocator.numPages();
        for (uint32_t pageId = 1; pageId < pageCount; ++pageId) {
            if (!lockManager_.pageLockShared(dbname, tablename, pageId))
                return false;
            char* buffer = allocator.fetchPage(pageId);
            if (!buffer) {
                lockManager_.pageUnlock(dbname, tablename, pageId);
                return false;
            }
            PageWrapper page(buffer, allocator.pageSize(), tbl.formatVersion);
            bool valid = page.isValid();
            if (valid) {
                page.forEachLive([&](uint16_t, const char* tuple, size_t length) {
                    if (!valid) return;
                    if (length < sizeof(HeapTupleHeaderData)) {
                        valid = false;
                        return;
                    }
                    const auto* header = castHeapHeader(tuple);
                    const size_t minimumHeader = rowHeaderSize(
                        tbl.formatVersion, tbl.len);
                    if (header->t_hoff < minimumHeader ||
                        header->t_hoff > length) {
                        valid = false;
                        return;
                    }
                    if (readView.isVisible(
                            tuple, length, tbl.formatVersion)) {
                        relation.tuples.emplace_back(tuple, length);
                    }
                });
            }
            allocator.unpinPage(pageId);
            lockManager_.pageUnlock(dbname, tablename, pageId);
            if (!valid) return false;
        }
        return true;
    };

    size_t rowCount = 0;
    for (auto& relation : relations) {
        std::error_code existsError;
        if (!std::filesystem::is_regular_file(relation.path, existsError) ||
            existsError) {
            return 0;
        }
        if (tbl.partitionType == TableSchema::PartitionType::None) {
            PageAllocator* allocator = getPageAllocator(dbname, tablename);
            if (!allocator || !scanRelation(relation, *allocator)) {
                return 0;
            }
        } else {
            PageAllocator allocator(
                relation.path.string(), tbl.rowSize(),
                pageSizeForFormatVersion(tbl.formatVersion),
                tbl.formatVersion);
            if (!allocator.open() || !scanRelation(relation, allocator)) {
                return 0;
            }
            if (!allocator.flush()) {
                return 0;
            }
            allocator.close();
        }
        rowCount += relation.tuples.size();
    }

    // Make the backup a faithful image of every cached relation fork.
    if (!flushDatabaseCaches(dbname)) {
        return 0;
    }
    if (auto it = fsmCache_.find(tableKey); it != fsmCache_.end() && it->second)
        it->second->flush();
    if (auto it = vmCache_.find(tableKey); it != vmCache_.end() && it->second)
        it->second->flush();
    for (const auto& column : bloomColumns) {
        BloomIndex* index = getBloomIndex(dbname, tablename, column);
        if (!index || !index->flush()) {
            return 0;
        }
    }

    std::set<std::filesystem::path> physicalPaths;
    for (const auto& relation : relations) physicalPaths.insert(relation.path);
    physicalPaths.insert(fsmPath(dbname, tablename));
    physicalPaths.insert(vmPath(dbname, tablename));
    physicalPaths.insert(indexPath(dbname, tablename));
    for (const auto& index : secondaryIndexes) {
        physicalPaths.insert(secondaryIndexPath(
            dbname, tablename, index.name));
    }
    for (const auto& index : compositeIndexes) {
        physicalPaths.insert(relationDir(dbname, tablename) /
                             (tablename + ".idx_" + index.name));
    }
    for (const auto& column : hashColumns)
        physicalPaths.insert(hashIndexPath(dbname, tablename, column));
    for (const auto& column : bloomColumns)
        physicalPaths.insert(bloomIndexPath(dbname, tablename, column));
    for (const auto& column : fullTextColumns)
        physicalPaths.insert(fullTextIndexPath(dbname, tablename, column));
    for (const auto& column : ginColumns)
        physicalPaths.insert(ginIndexPath(dbname, tablename, column));
    for (const auto& column : gistColumns)
        physicalPaths.insert(giSTIndexPath(dbname, tablename, column));
    for (const auto& column : spgistColumns)
        physicalPaths.insert(spGiSTIndexPath(dbname, tablename, column));
    for (const auto& column : brinColumns)
        physicalPaths.insert(brinIndexPath(dbname, tablename, column));
    // TDE keeps authentication/encryption state beside each protected file.
    // It must participate in the same backup/swap boundary as its owner.
    std::vector<std::filesystem::path> tdeSidecars;
    for (const auto& path : physicalPaths) {
        const auto sidecar = std::filesystem::path(path.string() + ".tde");
        tdeSidecars.push_back(sidecar);
    }
    physicalPaths.insert(tdeSidecars.begin(), tdeSidecars.end());

    const auto relationRoot = relationDir(dbname, tablename);
    std::filesystem::path backupDirectory;
    std::error_code fileError;
    for (size_t attempt = 0; attempt < 1000; ++attempt) {
        const auto candidate = relationRoot /
            ("." + tablename + ".vacuum_full_backup." +
             std::to_string(attempt));
        if (std::filesystem::create_directory(candidate, fileError)) {
            backupDirectory = candidate;
            break;
        }
        if (fileError) {
            fileError.clear();
            if (!std::filesystem::exists(candidate)) break;
        }
    }
    if (backupDirectory.empty()) {
        return 0;
    }

    std::vector<std::pair<std::filesystem::path, std::filesystem::path>> backups;
    size_t backupNumber = 0;
    bool backupValid = true;
    for (const auto& path : physicalPaths) {
        fileError.clear();
        if (!std::filesystem::exists(path, fileError)) {
            if (fileError) {
                backupValid = false;
                break;
            }
            continue;
        }
        if (!std::filesystem::is_regular_file(path, fileError) || fileError) {
            backupValid = false;
            break;
        }
        const auto backup = backupDirectory /
            (std::to_string(backupNumber++) + ".bak");
        if (!std::filesystem::copy_file(path, backup,
                                         std::filesystem::copy_options::none,
                                         fileError) || fileError) {
            backupValid = false;
            break;
        }
        backups.emplace_back(path, backup);
    }
    if (!backupValid) {
        std::error_code cleanupError;
        std::filesystem::remove_all(backupDirectory, cleanupError);
        return 0;
    }

    const auto evictTableCaches = [&]() {
        pageAllocators_.erase(tableKey);
        fsmCache_.erase(tableKey);
        vmCache_.erase(tableKey);
        pkIndexCache_.erase(tableKey);
        secidxLinesCache_.erase(tableKey);
        hashidxLinesCache_.erase(tableKey);
        for (auto it = secondaryIndexCache_.begin();
             it != secondaryIndexCache_.end();) {
            if (it->first.rfind(secondaryPrefix, 0) == 0)
                it = secondaryIndexCache_.erase(it);
            else
                ++it;
        }
        for (auto it = hashIndexCache_.begin();
             it != hashIndexCache_.end();) {
            if (it->first.rfind(hashPrefix, 0) == 0)
                it = hashIndexCache_.erase(it);
            else
                ++it;
        }
        for (auto it = bloomIndexCache_.begin();
             it != bloomIndexCache_.end();) {
            if (it->first.rfind(hashPrefix, 0) == 0)
                it = bloomIndexCache_.erase(it);
            else
                ++it;
        }
        std::lock_guard<std::mutex> lock(spGiSTMutex_);
        for (auto it = spGiSTCache_.begin(); it != spGiSTCache_.end();) {
            if (it->first.rfind(secondaryPrefix, 0) == 0)
                it = spGiSTCache_.erase(it);
            else
                ++it;
        }
    };

    std::map<std::string, std::unique_ptr<PageAllocator>> destinations;
    bool mutationStarted = false;
    const auto restoreBackup = [&]() {
        evictTableCaches();
        bool restored = true;
        for (const auto& path : physicalPaths) {
            std::error_code removeError;
            std::filesystem::remove(path, removeError);
            if (removeError) restored = false;
        }
        for (const auto& [target, backup] : backups) {
            std::error_code restoreError;
            if (!std::filesystem::copy_file(
                    backup, target,
                    std::filesystem::copy_options::overwrite_existing,
                    restoreError) || restoreError) {
                restored = false;
            }
        }
        if (restored) {
            std::error_code cleanupError;
            std::filesystem::remove_all(backupDirectory, cleanupError);
        } else {
            std::cerr << "[vacuum full] restore failed; recovery copies remain in "
                      << backupDirectory << std::endl;
        }
        return restored;
    };
    const auto failRewrite = [&]() -> size_t {
        // Close private rewrite descriptors before restoring their paths;
        // otherwise a destructor flush could race the restored files.
        destinations.clear();
        if (mutationStarted) restoreBackup();
        else {
            std::error_code cleanupError;
            std::filesystem::remove_all(backupDirectory, cleanupError);
        }
        return 0;
    };

    try {
        evictTableCaches();
        mutationStarted = true;
        for (const auto& path : physicalPaths) {
        fileError.clear();
        std::filesystem::remove(path, fileError);
        if (fileError) return failRewrite();
        }

    // Create one fresh heap per physical partition and copy visible tuples to
    // the same partition.  No SQL INSERT is executed, so triggers, sequences,
    // constraints and TOAST allocation are not spuriously invoked.
    for (const auto& relation : relations) {
        auto allocator = std::make_unique<PageAllocator>(
            relation.path.string(), tbl.rowSize(),
            pageSizeForFormatVersion(tbl.formatVersion), tbl.formatVersion);
        if (!allocator->open()) return failRewrite();
        destinations.emplace(relation.path.string(), std::move(allocator));
    }

    const auto appendTuple = [&](PageAllocator& allocator,
                                 const std::string& sourceTuple) -> bool {
        std::string tuple = sourceTuple;
        for (uint32_t pageId = 1; pageId < allocator.numPages(); ++pageId) {
            char* buffer = allocator.fetchPage(pageId);
            if (!buffer) return false;
            PageWrapper page(buffer, allocator.pageSize(), tbl.formatVersion);
            uint16_t slotId = 0;
            bool inserted = false;
            if (page.canFit(tuple.size()) &&
                page.insert(tuple.data(), tuple.size(), slotId)) {
                setRowCtid(tuple.data(), tuple.size(), tbl.formatVersion,
                           ItemPointer{pageId,
                                       static_cast<OffsetNumber>(slotId + 1)});
                uint16_t updatedSlot = slotId;
                inserted = page.update(slotId, tuple.data(), tuple.size(),
                                       updatedSlot) && updatedSlot == slotId;
                if (inserted) {
                    allocator.markDirty(pageId);
                } else {
                    page.remove(slotId);
                    allocator.markDirty(pageId);
                }
            }
            allocator.unpinPage(pageId);
            if (inserted) return true;
        }

        const uint32_t pageId = allocator.allocPage();
        if (pageId == 0) return false;
        char* buffer = allocator.fetchPage(pageId);
        if (!buffer) return false;
        PageWrapper page(buffer, allocator.pageSize(), tbl.formatVersion);
        uint16_t slotId = 0;
        bool inserted = page.insert(tuple.data(), tuple.size(), slotId);
        if (inserted) {
            setRowCtid(tuple.data(), tuple.size(), tbl.formatVersion,
                       ItemPointer{pageId,
                                   static_cast<OffsetNumber>(slotId + 1)});
            uint16_t updatedSlot = slotId;
            inserted = page.update(slotId, tuple.data(), tuple.size(),
                                   updatedSlot) && updatedSlot == slotId;
            if (inserted) {
                allocator.markDirty(pageId);
            } else {
                page.remove(slotId);
                allocator.markDirty(pageId);
            }
        }
        allocator.unpinPage(pageId);
        return inserted;
    };

    for (const auto& relation : relations) {
        auto destination = destinations.find(relation.path.string());
        if (destination == destinations.end()) return failRewrite();
        for (const auto& tuple : relation.tuples) {
            if (!appendTuple(*destination->second, tuple))
                return failRewrite();
        }
    }
    for (auto& [_, allocator] : destinations) {
        if (!allocator->flush()) return failRewrite();
        allocator->close();
    }
    destinations.clear();

    // Rebuild every RID-bearing access method before making the new heap
    // observable.  The physical backups make any failure recoverable.
    if (reindex(dbname, tablename) != DBStatus::OK)
        return failRewrite();

    bool auxiliaryValid = true;
    for (const auto& column : hashColumns) {
        HashIndex* index = getHashIndexForBuild(dbname, tablename, column);
        if (!index) return failRewrite();
        index->clear();
        if (!forEachRow(dbname, tablename,
                [&](uint32_t pageId, uint16_t slotId,
                    const char* data, size_t length) {
                    if (!auxiliaryValid) return;
                    const std::string row(data, length);
                    size_t columnIndex = tbl.len;
                    for (size_t i = 0; i < tbl.len; ++i) {
                        if (tbl.cols[i].dataName == column) {
                            columnIndex = i;
                            break;
                        }
                    }
                    if (columnIndex >= tbl.len) {
                        auxiliaryValid = false;
                        return;
                    }
                    bool isNull = false;
                    const std::string value = canonicalColumnKeyValue(
                        tbl.cols[columnIndex], extractColumnValue(
                            row, tbl, columnIndex, dbname, true, &isNull));
                    if (hashKeyIncluded(tbl.cols[columnIndex], value, isNull) &&
                        !index->insert(value, encodeRid(pageId, slotId))) {
                        auxiliaryValid = false;
                    }
                }) || !auxiliaryValid || !index->flush()) {
            return failRewrite();
        }
    }
    for (const auto& column : bloomColumns) {
        BloomIndex* index = getBloomIndexForBuild(dbname, tablename, column);
        if (!index) return failRewrite();
        index->clear();
        auxiliaryValid = true;
        if (!forEachRow(dbname, tablename,
                [&](uint32_t pageId, uint16_t slotId,
                    const char* data, size_t length) {
                    if (!auxiliaryValid) return;
                    const std::string row(data, length);
                    size_t columnIndex = tbl.len;
                    for (size_t i = 0; i < tbl.len; ++i) {
                        if (tbl.cols[i].dataName == column) {
                            columnIndex = i;
                            break;
                        }
                    }
                    if (columnIndex >= tbl.len) {
                        auxiliaryValid = false;
                        return;
                    }
                    const std::string value = canonicalColumnKeyValue(
                        tbl.cols[columnIndex], extractColumnValue(
                            row, tbl, columnIndex, dbname, true));
                    if (!value.empty() &&
                        !index->insert(value, encodeRid(pageId, slotId))) {
                        auxiliaryValid = false;
                    }
                }) || !auxiliaryValid || !index->flush()) {
            return failRewrite();
        }
    }
    for (const auto& column : fullTextColumns) {
        if (createFullTextIndex(dbname, tablename, column) != DBStatus::OK)
            return failRewrite();
    }
    for (const auto& column : ginColumns) {
        if (createGinIndex(dbname, tablename, column) != DBStatus::OK)
            return failRewrite();
    }
    for (const auto& column : gistColumns) {
        if (createGiSTIndex(dbname, tablename, column) != DBStatus::OK)
            return failRewrite();
    }
    for (const auto& column : spgistColumns) {
        if (createSPGiSTIndex(dbname, tablename, column) != DBStatus::OK)
            return failRewrite();
    }
    for (const auto& column : brinColumns) {
        if (createBrinIndex(dbname, tablename, column, 64) != DBStatus::OK)
            return failRewrite();
    }
    if (!clearSpecializedIndexDirty(*this, dbname, tablename))
        return failRewrite();

    if (!flushDatabaseCaches(dbname)) return failRewrite();
    std::error_code cleanupError;
    std::filesystem::remove_all(backupDirectory, cleanupError);
    if (cleanupError) {
        std::cerr << "[vacuum full] could not remove completed backup "
                  << backupDirectory << ": " << cleanupError.message()
                  << std::endl;
    }

    {
        const auto deadTupleKey = std::make_pair(dbname, tablename);
        std::lock_guard<std::mutex> lock(deadTupleMutex_);
        deadTupleCounts_[deadTupleKey] = 0;
    }
    if (succeeded) *succeeded = true;
    return rowCount;
    } catch (const std::exception& error) {
        std::cerr << "[vacuum full] rewrite failed: " << error.what()
                  << std::endl;
        return failRewrite();
    } catch (...) {
        std::cerr << "[vacuum full] rewrite failed with an unknown error"
                  << std::endl;
        return failRewrite();
    }
}

// ========================================================================
// Transaction logging helpers
// ========================================================================

bool StorageEngine::ssiIndexPredicateMatches(const SsiIndexPredicate& predicate,
                                             const SsiIndexKey& key) {
    if (predicate.dbname != key.dbname || predicate.tablename != key.tablename ||
        predicate.indexName != key.indexName) {
        return false;
    }
    const std::string lhs = BPTree::normalizeKeyForComparison(key.value);
    const std::string rhs = BPTree::normalizeKeyForComparison(predicate.value);
    if (predicate.op == "=") return lhs == rhs;
    if (predicate.op == ">") return lhs > rhs;
    if (predicate.op == ">=") return lhs >= rhs;
    if (predicate.op == "<") return lhs < rhs;
    if (predicate.op == "<=") return lhs <= rhs;
    return false;
}

bool StorageEngine::recordSsiIndexPredicate(const std::string& dbname,
                                            const std::string& tablename,
                                            const Condition& condition,
                                            const TableSchema& tbl) {
    if (!transactionContext().inTransaction ||
        transactionContext().txnDB != dbname ||
        transactionContext().txnIsolationLevel != IsolationLevel::SERIALIZABLE ||
        (condition.op != "=" && condition.op != ">" && condition.op != ">=" &&
         condition.op != "<" && condition.op != "<=")) {
        return false;
    }

    size_t columnIndex = tbl.len;
    for (size_t i = 0; i < tbl.len; ++i) {
        if (tbl.cols[i].dataName == condition.colName) {
            columnIndex = i;
            break;
        }
    }
    if (columnIndex >= tbl.len ||
        !columnUsesBinaryCollation(tbl.cols[columnIndex])) {
        return false;
    }

    std::vector<std::string> indexNames;
    if (tbl.pkColIndices.size() == 1 && tbl.pkColIndices.front() == columnIndex) {
        indexNames.push_back("pk:" + condition.colName);
    }
    if (getSecondaryIndex(dbname, tablename, condition.colName)) {
        indexNames.push_back("idx:" + condition.colName);
    }
    const std::string predicateValue = canonicalColumnKeyValue(
        tbl.cols[columnIndex], condition.value);
    if (indexNames.empty() || predicateValue.empty()) return false;

    const SsiIndexPredicate predicateBase{
        dbname, tablename, "", condition.op, predicateValue};
    std::lock_guard<std::mutex> lock(ssiMutex_);
    for (const auto& indexName : indexNames) {
        SsiIndexPredicate predicate = predicateBase;
        predicate.indexName = indexName;
        transactionContext().txnReadIndexPredicates.insert(predicate);
        ssiReadIndexPredicates_[transactionContext().currentTxnId].insert(std::move(predicate));
    }
    return !indexNames.empty();
}

void StorageEngine::recordSsiIndexKeys(const std::string& dbname,
                                       const std::string& tablename,
                                       const std::string& rowData,
                                       const TableSchema& tbl) {
    if (!transactionContext().inTransaction ||
        transactionContext().txnIsolationLevel != IsolationLevel::SERIALIZABLE) {
        return;
    }

    std::vector<std::pair<std::string, std::string>> keys;
    if (tbl.pkColIndices.size() == 1) {
        const size_t columnIndex = tbl.pkColIndices.front();
        if (columnIndex < tbl.len) {
            const std::string value = canonicalColumnKeyValue(
                tbl.cols[columnIndex], extractColumnValue(
                    rowData, tbl, columnIndex, dbname));
            if (!value.empty()) {
                keys.emplace_back("pk:" + tbl.cols[columnIndex].dataName, value);
            }
        }
    }
    for (const auto& columnName : getIndexedColumns(dbname, tablename)) {
        BPTree* index = getSecondaryIndex(dbname, tablename, columnName);
        if (!index) continue;
        size_t columnIndex = tbl.len;
        for (size_t i = 0; i < tbl.len; ++i) {
            if (tbl.cols[i].dataName == columnName) {
                columnIndex = i;
                break;
            }
        }
        if (columnIndex >= tbl.len) continue;
        const std::string value = canonicalColumnKeyValue(
            tbl.cols[columnIndex], extractColumnValue(
                rowData, tbl, columnIndex, dbname));
        if (!value.empty()) keys.emplace_back("idx:" + columnName, value);
    }

    if (keys.empty()) return;
    std::lock_guard<std::mutex> lock(ssiMutex_);
    for (const auto& [indexName, value] : keys) {
        SsiIndexKey key{dbname, tablename, indexName, value};
        transactionContext().txnWrittenIndexKeys.insert(key);
        ssiWriteIndexKeys_[transactionContext().currentTxnId].insert(std::move(key));
    }
}

void StorageEngine::logTxnInsert(const std::string& tableName, int64_t rowIdx,
                                 const std::string& rowData) {
    // Executor-owned CTE/derived relations are dropped before the outer SQL
    // command returns.  They must not leave undo entries that point at files
    // which no longer exist when an explicit transaction later rolls back.
    if (transactionContext().commandInternalRelations.count(tableName) != 0) {
        return;
    }
    TxnLogEntry entry;
    entry.op = TxnLogEntry::Op::Insert;
    entry.tableName = tableName;
    entry.rowIdx = rowIdx;
    entry.rowData = rowData;
    transactionContext().txnLog.push_back(std::move(entry));
    uint32_t pageId = 0;
    uint16_t slotId = 0;
    decodeRid(rowIdx, pageId, slotId);
    (void)slotId;
    transactionContext().txnHeapWritebackPages.insert({tableName, pageId});
    if (transactionContext().txnIsolationLevel == IsolationLevel::SERIALIZABLE) {
        TableSchema tbl = getTableSchema(transactionContext().txnDB, tableName);
        recordSsiIndexKeys(
            transactionContext().txnDB, tableName, rowData, tbl);
        std::string key = ssiRidKey(transactionContext().txnDB, tableName, rowIdx);
        std::string relation = ssiRelationKey(transactionContext().txnDB, tableName);
        std::string page = ssiPageKey(
            transactionContext().txnDB, tableName, pageId);
        transactionContext().txnWrittenRids.insert(key);
        transactionContext().txnWrittenRelations.insert(relation);
        transactionContext().txnWrittenPages.insert(page);
        std::lock_guard<std::mutex> lock(ssiMutex_);
        ssiWriteSets_[transactionContext().currentTxnId].insert(std::move(key));
        ssiWriteRelations_[transactionContext().currentTxnId].insert(std::move(relation));
        ssiWritePages_[transactionContext().currentTxnId].insert(std::move(page));
    }
}

