static void applySessionTempTableCommitActions(StorageEngine& engine,
                                               Session& session,
                                               const std::string& dbname) {
    std::vector<std::string> names;
    names.reserve(session.tempTableOnCommit.size());
    for (const auto& entry : session.tempTableOnCommit) names.push_back(entry.first);

    for (const auto& logicalName : names) {
        if (!session.tempTables.count(logicalName)) {
            session.tempTableOnCommit.erase(logicalName);
            continue;
        }
        const auto actionIt = session.tempTableOnCommit.find(logicalName);
        if (actionIt == session.tempTableOnCommit.end()) continue;
        const std::string physicalName = tempTablePrefix(session, logicalName);
        if (actionIt->second == "delete") {
            engine.truncateTable(dbname, physicalName);
        } else if (actionIt->second == "drop") {
            engine.dropSessionTemporaryTable(dbname, session.pid, logicalName);
            session.tempTables.erase(logicalName);
            session.tempTableOnCommit.erase(logicalName);
        }
    }
    session.tempTablesCreatedInTransaction.clear();
}

static void rollbackSessionTempTables(StorageEngine& engine,
                                      Session& session,
                                      const std::string& dbname,
                                      const std::set<std::string>& preexisting) {
    const auto created = session.tempTablesCreatedInTransaction;
    for (const auto& logicalName : created) {
        // A transaction may DROP and recreate an existing temp table under
        // the same name. The DDL snapshot has restored the original heap;
        // dropping by name here would destroy that recovered table.
        if (preexisting.count(logicalName) == 0) {
            engine.dropTable(dbname, tempTablePrefix(session, logicalName));
        }
        session.tempTables.erase(logicalName);
        session.tempTableOnCommit.erase(logicalName);
    }
    session.tempTablesCreatedInTransaction.clear();
}

namespace {

struct DatabaseTransactionLockRegistry {
    std::mutex mutex;
    std::map<std::string, std::shared_ptr<std::shared_mutex>> locks;
    std::map<std::string, std::set<uint64_t>> pendingRollbacks;
};

DatabaseTransactionLockRegistry& databaseTransactionLockRegistry() {
    // The global StorageEngine can restore transaction images from its
    // constructor, before this translation unit's dynamic initializers run.
    // Initialize the mutex and map together on first use, thread-safely.
    // Keep the registry alive through global-engine/background-worker teardown
    // as well: a function-local object first used after main starts would
    // otherwise be destroyed before that global engine stops its workers.
    static auto* const registry = new DatabaseTransactionLockRegistry;
    return *registry;
}

std::shared_ptr<std::shared_mutex> databaseTxnLockFor(const std::string& dbname) {
    auto& registry = databaseTransactionLockRegistry();
    // Namespace/physical snapshots must share their owner for lexical aliases
    // of the same database, not only identical caller strings.
    std::error_code error;
    auto canonical = std::filesystem::weakly_canonical(dbname, error);
    if (error) canonical = std::filesystem::absolute(dbname).lexically_normal();
    std::lock_guard<std::mutex> guard(registry.mutex);
    auto& lock = registry.locks[canonical.string()];
    if (!lock) lock = std::make_shared<std::shared_mutex>();
    return lock;
}

bool databaseRollbackPending(const std::string& dbname) {
    auto& registry = databaseTransactionLockRegistry();
    std::lock_guard<std::mutex> guard(registry.mutex);
    const auto found = registry.pendingRollbacks.find(dbname);
    if (found == registry.pendingRollbacks.end()) return false;
    return true;
}

void setDatabaseRollbackPending(const std::string& dbname, uint64_t xid, bool pending) {
    auto& registry = databaseTransactionLockRegistry();
    std::lock_guard<std::mutex> guard(registry.mutex);
    if (pending) registry.pendingRollbacks[dbname].insert(xid);
    else {
        const auto found = registry.pendingRollbacks.find(dbname);
        if (found != registry.pendingRollbacks.end()) {
            found->second.erase(xid);
            if (found->second.empty()) registry.pendingRollbacks.erase(found);
        }
    }
}

bool anyDatabaseRollbackPending() {
    auto& registry = databaseTransactionLockRegistry();
    std::lock_guard<std::mutex> guard(registry.mutex);
    return !registry.pendingRollbacks.empty();
}

std::filesystem::path transactionBackupPath(const std::string& dbname, uint64_t xid) {
    return std::filesystem::path(dbname + ".txn_backup." + std::to_string(xid));
}

std::filesystem::path ddlStatementBackupPath(const std::string& dbname,
                                             uint64_t xid) {
    static std::atomic<uint64_t> sequence{0};
    return std::filesystem::path(
        dbname + ".ddl_statement_backup." + std::to_string(xid) + "." +
        std::to_string(sequence.fetch_add(1, std::memory_order_relaxed)));
}

