static bool parseSecurityLabelRecord(const std::string& line,
                                     std::string& objectType,
                                     std::string& objectName,
                                     std::string& label) {
    if (line.rfind("S2|", 0) == 0) {
        const size_t typeEnd = line.find('|', 3);
        if (typeEnd == std::string::npos) return false;
        const size_t nameEnd = line.find('|', typeEnd + 1);
        if (nameEnd == std::string::npos ||
            line.find('|', nameEnd + 1) != std::string::npos) {
            return false;
        }
        return decodeCommentField(
                   line.substr(3, typeEnd - 3), objectType) &&
               decodeCommentField(
                   line.substr(typeEnd + 1, nameEnd - typeEnd - 1),
                   objectName) &&
               decodeCommentField(line.substr(nameEnd + 1), label) &&
               !objectType.empty() && !objectName.empty();
    }

    const size_t typeEnd = line.find(' ');
    if (typeEnd == std::string::npos || typeEnd == 0) return false;
    const size_t nameEnd = line.find(' ', typeEnd + 1);
    if (nameEnd == std::string::npos || nameEnd == typeEnd + 1) return false;
    objectType = line.substr(0, typeEnd);
    objectName = line.substr(typeEnd + 1, nameEnd - typeEnd - 1);
    label = line.substr(nameEnd + 1);
    return true;
}

static DBStatus readSecurityLabels(const std::filesystem::path& path,
                                   SecurityLabelMap& labels) {
    std::error_code error;
    const bool exists = std::filesystem::exists(path, error);
    if (error) return DBStatus::IO_ERROR;
    if (!exists) return DBStatus::OK;
    if (!std::filesystem::is_regular_file(path, error) || error) {
        return DBStatus::IO_ERROR;
    }

    std::ifstream input(path, std::ios::binary);
    if (!input) return DBStatus::IO_ERROR;
    std::string line;
    while (std::getline(input, line)) {
        if (line.empty()) continue;
        std::string objectType;
        std::string objectName;
        std::string label;
        if (!parseSecurityLabelRecord(
                line, objectType, objectName, label)) {
            return DBStatus::CORRUPTED_DATA;
        }
        labels[{std::move(objectType), std::move(objectName)}] =
            std::move(label);
    }
    return input.bad() ? DBStatus::IO_ERROR : DBStatus::OK;
}

static DBStatus writeSecurityLabels(const std::filesystem::path& path,
                                    const SecurityLabelMap& labels) {
    std::ostringstream contents;
    for (const auto& entry : labels) {
        contents << "S2|" << encodeCommentField(entry.first.first) << '|'
                 << encodeCommentField(entry.first.second) << '|'
                 << encodeCommentField(entry.second) << '\n';
    }
    return persistMetadata(path, contents.str());
}

static bool securityLabelTypeIs(const std::string& value,
                                const char* expected) {
    size_t index = 0;
    for (; index < value.size() && expected[index] != '\0'; ++index) {
        if (std::tolower(static_cast<unsigned char>(value[index])) !=
            expected[index]) {
            return false;
        }
    }
    return index == value.size() && expected[index] == '\0';
}

static bool rewriteSecurityLabelsForTable(
    SecurityLabelMap& labels, const std::string& oldName,
    const std::optional<std::string>& newName) {
    SecurityLabelMap rewritten;
    bool changed = false;
    const std::string oldColumnPrefix = oldName + ".";
    const std::string newColumnPrefix =
        newName ? *newName + "." : std::string();

    for (const auto& entry : labels) {
        const std::string& type = entry.first.first;
        const std::string& name = entry.first.second;
        const bool tableLabel = securityLabelTypeIs(type, "table");
        const bool columnLabel = securityLabelTypeIs(type, "column");
        const bool sourceTable = tableLabel && name == oldName;
        const bool sourceColumn =
            columnLabel && name.rfind(oldColumnPrefix, 0) == 0;
        const bool destinationTable =
            newName && tableLabel && name == *newName;
        const bool destinationColumn =
            newName && columnLabel && name.rfind(newColumnPrefix, 0) == 0;

        if (sourceTable || sourceColumn) {
            changed = true;
            if (newName) {
                const std::string movedName = sourceTable
                    ? *newName
                    : newColumnPrefix + name.substr(oldColumnPrefix.size());
                rewritten[{type, movedName}] = entry.second;
            }
            continue;
        }
        if (destinationTable || destinationColumn) {
            changed = true;
            continue;
        }
        rewritten.insert(entry);
    }
    labels = std::move(rewritten);
    return changed;
}

static bool rewriteSecurityLabelForColumn(SecurityLabelMap& labels,
                                          const std::string& tablename,
                                          const std::string& oldName,
                                          const std::string& newName) {
    const std::string oldObjectName = tablename + "." + oldName;
    const std::string newObjectName = tablename + "." + newName;
    SecurityLabelMap rewritten;
    bool changed = false;
    for (const auto& entry : labels) {
        const bool columnLabel =
            securityLabelTypeIs(entry.first.first, "column");
        if (columnLabel && entry.first.second == oldObjectName) {
            rewritten[{entry.first.first, newObjectName}] = entry.second;
            changed = true;
            continue;
        }
        if (columnLabel && entry.first.second == newObjectName) {
            changed = true;
            continue;
        }
        rewritten.insert(entry);
    }
    labels = std::move(rewritten);
    return changed;
}

SecurityLabelRewriteGuard::SecurityLabelRewriteGuard(
    std::filesystem::path path, SecurityLabelMap original,
    SecurityLabelMap rewritten, bool changed)
    : path_(std::move(path)), original_(std::move(original)),
      rewritten_(std::move(rewritten)), changed_(changed) {}

DBStatus SecurityLabelRewriteGuard::publish() {
    if (!changed_) return DBStatus::OK;
    rollbackNeeded_ = true;
    return writeSecurityLabels(path_, rewritten_);
}

void SecurityLabelRewriteGuard::commit() {
    rollbackNeeded_ = false;
}

SecurityLabelRewriteGuard::~SecurityLabelRewriteGuard() {
    if (rollbackNeeded_) {
        (void)writeSecurityLabels(path_, original_);
    }
}

DBStatus StorageEngine::setSecurityLabel(
    const std::string& dbname, const std::string& objType,
    const std::string& objName, const std::string& label) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    (void)objType;
    (void)objName;
    (void)label;
    // A stored string is not a security label unless a provider validates it
    // and the object-access hook enforces it.  No provider exists yet, so a
    // successful write would be a dangerous false claim of MAC enforcement.
    // Legacy files remain readable and participate in rename/drop cleanup,
    // but no new inert policy metadata may be published.
    return DBStatus::FEATURE_NOT_SUPPORTED;
}

std::string StorageEngine::getSecurityLabel(const std::string& dbname, const std::string& objType,
                                            const std::string& objName) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    SecurityLabelMap labels;
    if (readSecurityLabels(seclabelPath(dbname), labels) != DBStatus::OK) {
        return "";
    }
    auto it = labels.find({objType, objName});
    return it == labels.end() ? "" : it->second;
}

std::vector<std::tuple<std::string, std::string, std::string>> StorageEngine::getAllSecurityLabels(
    const std::string& dbname) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::vector<std::tuple<std::string, std::string, std::string>> result;
    SecurityLabelMap labels;
    if (readSecurityLabels(seclabelPath(dbname), labels) != DBStatus::OK) {
        return result;
    }
    result.reserve(labels.size());
    for (const auto& entry : labels) {
        result.emplace_back(
            entry.first.first, entry.first.second, entry.second);
    }
    return result;
}

// ========================================================================
// Default Privileges
// ========================================================================
static std::filesystem::path defaultPrivPath(const std::filesystem::path& dbPath) {
    return dbPath / ".default_privs";
}

void StorageEngine::addDefaultPrivilege(const std::string& dbname, const std::string& owner,
                                        const std::string& schema, const std::string& objType,
                                        const std::string& privilege, const std::string& grantee) {
    auto dpp = defaultPrivPath(dbPath(dbname));
    {
        std::ifstream ifs(dpp);
        std::string line;
        while (std::getline(ifs, line)) {
            std::stringstream ss(line);
            std::string o, s, t, p, g;
            ss >> o >> s >> t >> p >> g;
            if (o == owner && s == schema && t == objType && p == privilege && g == grantee) {
                return;
            }
        }
    }
    std::ofstream ofs(dpp, std::ios::app);
    ofs << owner << " " << schema << " " << objType << " " << privilege << " " << grantee << "\n";
}

void StorageEngine::removeDefaultPrivilege(const std::string& dbname, const std::string& owner,
                                           const std::string& schema, const std::string& objType,
                                           const std::string& privilege, const std::string& grantee) {
    auto dpp = defaultPrivPath(dbPath(dbname));
    if (!std::filesystem::exists(dpp)) return;
    std::vector<std::string> remaining;
    {
        std::ifstream ifs(dpp);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string o, s, t, p, g;
            ss >> o >> s >> t >> p >> g;
            if (o == owner && s == schema && t == objType && p == privilege && g == grantee) continue;
            remaining.push_back(line);
        }
    }
    std::ofstream ofs(dpp);
    for (const auto& r : remaining) ofs << r << "\n";
}

void StorageEngine::applyDefaultPrivileges(const std::string& dbname, const std::string& schema,
                                           const std::string& objType, const std::string& objName,
                                           const std::string& owner) const {
    auto dpp = defaultPrivPath(dbPath(dbname));
    if (!std::filesystem::exists(dpp)) return;
    std::ifstream ifs(dpp);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string o, s, t, p, g;
        ss >> o >> s >> t >> p >> g;
        if (o != owner || s != schema || t != objType) continue;
        TablePrivilege priv;
        if (p == "select") priv = TablePrivilege::Select;
        else if (p == "insert") priv = TablePrivilege::Insert;
        else if (p == "update") priv = TablePrivilege::Update;
        else if (p == "delete") priv = TablePrivilege::Delete;
        else if (p == "all") priv = TablePrivilege::All;
        else if (p == "usage") priv = TablePrivilege::Usage;
        else if (p == "execute") priv = TablePrivilege::Execute;
        else continue;
        const_cast<StorageEngine*>(this)->grant(dbname, objName, g, priv, {}, false, owner);
    }
}

std::vector<std::tuple<std::string, std::string, std::string, std::string, std::string>>
StorageEngine::getDefaultPrivileges(const std::string& dbname) const {
    std::vector<std::tuple<std::string, std::string, std::string, std::string, std::string>> result;
    auto dpp = defaultPrivPath(dbPath(dbname));
    if (!std::filesystem::exists(dpp)) return result;
    std::ifstream ifs(dpp);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string o, s, t, p, g;
        ss >> o >> s >> t >> p >> g;
        result.emplace_back(o, s, t, p, g);
    }
    return result;
}

int64_t StorageEngine::readNextSeq(const std::string& dbname, const std::string& tablename, const std::string& colname) {
    const std::string key = dbname + "/" + tablename;
    std::lock_guard<std::mutex> lock(seqCacheMutex_);
    auto& state = seqFileCache_[key];
    if (!state.loaded) {
        auto path = seqPath(dbname, tablename);
        if (std::filesystem::exists(path)) {
            std::ifstream ifs(path);
            if (ifs) {
                std::string line;
                while (std::getline(ifs, line)) {
                    size_t sp = line.find(' ');
                    if (sp == std::string::npos) continue;
                    try {
                        state.values[line.substr(0, sp)] = std::stoll(line.substr(sp + 1));
                    } catch (...) {}
                }
            }
        }
        state.loaded = true;
    }
    auto it = state.values.find(colname);
    return it == state.values.end() ? 1 : it->second;
}

void StorageEngine::writeNextSeq(const std::string& dbname, const std::string& tablename, const std::string& colname, int64_t val) {
    const std::string key = dbname + "/" + tablename;
    std::lock_guard<std::mutex> lock(seqCacheMutex_);
    auto& state = seqFileCache_[key];
    if (!state.loaded) {
        // Preserve other columns' counters on first touch of this table.
        auto path = seqPath(dbname, tablename);
        if (std::filesystem::exists(path)) {
            std::ifstream ifs(path);
            if (ifs) {
                std::string line;
                while (std::getline(ifs, line)) {
                    size_t sp = line.find(' ');
                    if (sp == std::string::npos) continue;
                    try {
                        state.values[line.substr(0, sp)] = std::stoll(line.substr(sp + 1));
                    } catch (...) {}
                }
            }
        }
        state.loaded = true;
    }
    state.values[colname] = val;
    state.dirty = true;
}

// Persist every dirty sequence file. Called at transaction boundaries so a
// multi-row INSERT rewrites <table>.seq once instead of twice per row.
void StorageEngine::flushDeferredSequences() {
    std::lock_guard<std::mutex> lock(seqCacheMutex_);
    for (auto& [key, state] : seqFileCache_) {
        if (!state.dirty) continue;
        const size_t slash = key.find('/');
        if (slash == std::string::npos) { state.dirty = false; continue; }
        const std::string dbname = key.substr(0, slash);
        const std::string tablename = key.substr(slash + 1);
        auto path = seqPath(dbname, tablename);
        std::error_code ec;
        std::filesystem::create_directories(path.parent_path(), ec);
        std::ofstream ofs(path);
        for (const auto& p : state.values) {
            ofs << p.first << ' ' << p.second << '\n';
        }
        state.dirty = false;
    }
}

void StorageEngine::removeSeq(const std::string& dbname, const std::string& tablename) {
    {
        std::lock_guard<std::mutex> lock(seqCacheMutex_);
        seqFileCache_.erase(dbname + "/" + tablename);
    }
    auto path = seqPath(dbname, tablename);
    if (std::filesystem::exists(path)) {
        std::filesystem::remove(path);
    }
}

void StorageEngine::resetSequence(const std::string& dbname, const std::string& tablename,
                                  const std::string& colname, int64_t val) {
    writeNextSeq(dbname, tablename, colname, val);
}

// ========================================================================
// Domain support
// ========================================================================
static std::filesystem::path domainPath(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".domains";
}

static std::string domainHex(const std::string& value) {
    static constexpr char digits[] = "0123456789abcdef";
    std::string out;
    for (unsigned char byte : value) {
        out += digits[byte >> 4]; out += digits[byte & 15];
    }
    return out;
}

static bool domainUnhex(const std::string& value, std::string& out) {
    if (value.size() % 2) return false;
    const auto digit = [](char c) {
        if (c >= '0' && c <= '9') return c - '0';
        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
        return -1;
    };
    out.clear();
    for (size_t i = 0; i < value.size(); i += 2) {
        const int a = digit(value[i]), b = digit(value[i + 1]);
        if (a < 0 || b < 0) return false;
        out += static_cast<char>((a << 4) | b);
    }
    return true;
}

static bool parseDomainRecord(const std::string& line, StorageEngine::DomainInfo& info) {
    std::vector<std::string> fields;
    size_t start = 0;
    for (;;) {
        const auto end = line.find('|', start);
        fields.push_back(line.substr(start, end == std::string::npos ? end : end - start));
        if (end == std::string::npos) break;
        start = end + 1;
    }
    info = {};
    if (fields[0] == "@D2" || fields[0] == "@D3") {
        if (fields.size() != 8 || (fields[6] != "0" && fields[6] != "1") ||
            (fields[7] != "0" && fields[7] != "1")) return false;
        if (!domainUnhex(fields[1], info.name) || !domainUnhex(fields[2], info.baseType) ||
            !domainUnhex(fields[3], info.defaultValue) || !domainUnhex(fields[4], info.checkExpr) ||
            !domainUnhex(fields[5], info.constraintName)) return false;
        info.hasDefault = fields[6] == "1";
        info.notNull = fields[7] == "1";
        info.defaultResolved = fields[0] == "@D3";
        if ((!info.hasDefault && !info.defaultValue.empty()) ||
            (info.hasDefault && info.defaultValue.empty())) return false;
    } else {
        // Original five-field metadata remains readable, without guessing
        // NOT NULL from a CHECK expression or rewriting unrelated records.
        if (fields.size() != 5) return false;
        info.name = fields[0]; info.baseType = fields[1]; info.defaultValue = fields[2];
        info.checkExpr = fields[3]; info.constraintName = fields[4];
        info.hasDefault = !info.defaultValue.empty();
    }
    CatalogManager::QualifiedName name;
    return !info.name.empty() && !info.baseType.empty() &&
        info.name.find('\0') == std::string::npos && info.baseType.find('\0') == std::string::npos &&
        info.defaultValue.find('\0') == std::string::npos && info.checkExpr.find('\0') == std::string::npos &&
        info.constraintName.find('\0') == std::string::npos &&
        CatalogManager::parseQualifiedName(info.name, name, true) && !name.name.empty();
}

static std::string serializeDomainRecord(const StorageEngine::DomainInfo& info) {
    return std::string(info.defaultResolved ? "@D3|" : "@D2|") + domainHex(info.name) + "|" + domainHex(info.baseType) + "|" +
        domainHex(info.defaultValue) + "|" + domainHex(info.checkExpr) + "|" +
        domainHex(info.constraintName) + "|" + (info.hasDefault || !info.defaultValue.empty() ? "1" : "0") +
        "|" + (info.notNull ? "1" : "0");
}

static std::pair<std::string, std::string> domainIdentity(const std::string& raw) {
    CatalogManager::QualifiedName name;
    if (!CatalogManager::parseQualifiedName(raw, name, true) || name.name.empty())
        throw DbError("42601", "invalid domain name: " + raw);
    return {name.schema.empty() ? "public" : name.schema, name.name};
}

DBStatus StorageEngine::createDomain(const std::string& dbname, const DomainInfo& info) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    DomainInfo declaration = info;
    if (!declaration.hasDefault && declaration.defaultValue.empty()) {
        const auto parent = resolveDomainAncestry(dbname,SQLParser::parseTypeSpecification(info.baseType).typeName);
        declaration.hasDefault = parent.hasDefault;
        declaration.defaultValue = parent.defaultValue;
    }
    declaration.defaultResolved = true;
    DomainInfo checked;
    if (!parseDomainRecord(serializeDomainRecord(declaration), checked)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    auto path = domainPath(dbname);
    if (std::filesystem::exists(path) && !std::filesystem::is_regular_file(path))
        return DBStatus::IO_ERROR;
    auto existing = getDomain(dbname, info.name);
    if (!existing.name.empty()) return DBStatus::TABLE_ALREADY_EXISTS;

    std::vector<std::string> lines;
    if (std::filesystem::exists(path)) {
        std::ifstream input(path);
        if (!input) return DBStatus::IO_ERROR;
        std::string line;
        while (std::getline(input, line)) lines.push_back(std::move(line));
        if (input.bad()) return DBStatus::IO_ERROR;
    }
    std::ostringstream serialized;
    for (const auto& line : lines) serialized << line << '\n';
    serialized << serializeDomainRecord(declaration) << '\n';
    return index_file::writeAtomically(path, serialized.str())
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::alterDomain(const std::string& dbname, const std::string& name,
                                    const DomainInfo& info) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = domainPath(dbname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    if (!std::filesystem::is_regular_file(path)) return DBStatus::IO_ERROR;
    const auto requested = getDomain(dbname, name);
    if (requested.name.empty()) return DBStatus::TABLE_NOT_FOUND;
    DomainInfo replacement = info;
    // A caller may retain its original pre-CREATE struct. That must not
    // downgrade a durable D3 default barrier back to legacy parent fallback.
    replacement.defaultResolved = replacement.defaultResolved || requested.defaultResolved ||
        replacement.hasDefault != requested.hasDefault || replacement.defaultValue != requested.defaultValue;
    if (domainIdentity(info.name) != domainIdentity(requested.name) && !getDomain(dbname, info.name).name.empty()) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    std::ifstream ifs(path);
    if (!ifs) return DBStatus::IO_ERROR;
    std::vector<std::string> domains;
    std::string line;
    bool found = false;
    while (std::getline(ifs, line)) {
        DomainInfo current;
        if (!parseDomainRecord(line, current)) return DBStatus::INVALID_VALUE;
        if (domainIdentity(current.name) == domainIdentity(requested.name)) {
            DomainInfo checked;
            if (!parseDomainRecord(serializeDomainRecord(replacement), checked)) return DBStatus::INVALID_ARGUMENT;
            domains.push_back(serializeDomainRecord(replacement));
            found = true;
        } else {
            domains.push_back(line);
        }
    }
    if (ifs.bad()) return DBStatus::IO_ERROR;
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    std::ostringstream serialized;
    for (const auto& d : domains) {
        serialized << d << '\n';
    }
    return index_file::writeAtomically(path, serialized.str())
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::dropDomain(const std::string& dbname, const std::string& name) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    auto path = domainPath(dbname);
    if (!std::filesystem::exists(path)) return DBStatus::TABLE_NOT_FOUND;
    if (!std::filesystem::is_regular_file(path)) return DBStatus::IO_ERROR;
    const auto requested = getDomain(dbname, name);
    if (requested.name.empty()) return DBStatus::TABLE_NOT_FOUND;
    std::ifstream ifs(path);
    if (!ifs) return DBStatus::IO_ERROR;
    std::vector<std::string> lines;
    std::string line;
    bool found = false;
    while (std::getline(ifs, line)) {
        DomainInfo current;
        if (!parseDomainRecord(line, current)) return DBStatus::INVALID_VALUE;
        if (!requested.name.empty() && domainIdentity(current.name) == domainIdentity(requested.name)) {
            found = true;
        } else {
            lines.push_back(line);
        }
    }
    if (ifs.bad()) return DBStatus::IO_ERROR;
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    std::ostringstream serialized;
    for (const auto& retained : lines) serialized << retained << '\n';
    return index_file::writeAtomically(path, serialized.str())
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

StorageEngine::DomainInfo StorageEngine::getDomain(const std::string& dbname, const std::string& name) const {
    DomainInfo result;
    auto path = domainPath(dbname);
    if (!std::filesystem::exists(path)) return result;
    std::ifstream ifs(path);
    if (!ifs) throw DbError("58030", "could not read domain metadata");
    CatalogManager::QualifiedName requested;
    if (!CatalogManager::parseQualifiedName(name, requested, true) || requested.name.empty()) return result;
    std::vector<std::string> schemas;
    if (!requested.schema.empty()) schemas.push_back(requested.schema);
    else {
        const Session* session = currentSession();
        std::string canonical;
        if (!session || !parseSessionSearchPath(session->searchPath, schemas, canonical)) schemas = {"public"};
        for (auto& schema : schemas)
            schema = expandSessionSearchPathEntry(schema, session ? session->username : "");
    }
    std::vector<DomainInfo> candidates;
    std::string line;
    while (std::getline(ifs, line)) {
        DomainInfo candidate;
        if (!parseDomainRecord(line, candidate)) throw DbError("XX001", "invalid domain metadata record");
        if (domainIdentity(candidate.name).second == requested.name) candidates.push_back(std::move(candidate));
    }
    if (ifs.bad()) throw DbError("58030", "could not read domain metadata");
    for (const auto& schema : schemas)
        for (const auto& candidate : candidates)
            if (domainIdentity(candidate.name).first == schema) return candidate;
    return result;
}

std::vector<std::string> StorageEngine::getDomainNames(const std::string& dbname) const {
    std::vector<std::string> result;
    auto path = domainPath(dbname);
    if (!std::filesystem::exists(path)) return result;
    std::ifstream ifs(path);
    std::string line;
    while (std::getline(ifs, line)) {
        DomainInfo info;
        if (!parseDomainRecord(line, info)) throw DbError("XX001", "invalid domain metadata record");
        result.push_back(info.name);
    }
    return result;
}

StorageEngine::DomainAncestry StorageEngine::resolveDomainAncestry(
    const std::string& dbname, const std::string& name) const {
    DomainAncestry result;
    DomainInfo current = getDomain(dbname, name);
    if (current.name.empty()) return result;
    result.name = current.name;
    bool mayInheritDefault = true;
    std::set<std::pair<std::string, std::string>> visited;
    for (;;) {
        if (result.domains.size() >= 64)
            throw DbError("54001", "domain ancestry exceeds the supported depth of 64");
        if (!visited.insert(domainIdentity(current.name)).second)
            throw DbError("XX001", "cyclic domain ancestry");
        result.notNull = result.notNull || current.notNull;
        if (mayInheritDefault && !result.hasDefault && (current.hasDefault || !current.defaultValue.empty())) {
            result.hasDefault = true;
            result.defaultValue = current.defaultValue;
        }
        if (current.defaultResolved) mayInheritDefault = false;
        result.domains.push_back(current);
        const auto base = SQLParser::parseTypeSpecification(current.baseType);
        DomainInfo parent = getDomain(dbname, base.typeName);
        if (parent.name.empty()) {
            result.baseType = current.baseType;
            return result;
        }
        if (!base.typeMods.empty() || base.isArray)
            throw DbError("42601", "domain parent cannot have modifiers or array suffix");
        current = std::move(parent);
    }
}

// ========================================================================
// Composite types (ROW types)
// ========================================================================
static std::filesystem::path compositeTypePath(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".types";
}

static bool validCompositeTypeDefinition(
    const StorageEngine::CompositeType& type) {
    if (!validMetadataObjectName(type.name) || type.fields.empty() ||
        type.fields.size() > MAX_COLUMNS) {
        return false;
    }
    if (type.schema.empty() != type.localName.empty()) return false;
    if (!type.schema.empty() &&
        (!validMetadataObjectName(type.schema) ||
         !validMetadataObjectName(type.localName) ||
         type.name != (type.schema == "public" ? type.localName
             : type.schema + "." + type.localName))) return false;
    for (const auto& field : type.fields) {
        if (!validMetadataObjectName(field.first) || field.second.empty() ||
            field.second.find('|') != std::string::npos ||
            field.second.find('\n') != std::string::npos ||
            field.second.find('\r') != std::string::npos) {
            return false;
        }
    }
    return true;
}

// ':' cannot occur in an old physical name, so no valid V1 record can
// accidentally claim this version marker. Owner and fields share one atomic
// file; a rewrite preserves every V1 record's unavailable owner as unavailable.
static constexpr const char* COMPOSITE_METADATA_V2_PREFIX = "DBMS_COMPOSITE_V2:";

static DBStatus loadCompositeTypes(
    const std::filesystem::path& path,
    std::vector<StorageEngine::CompositeType>& types) {
    types.clear();
    std::error_code error;
    const bool exists = std::filesystem::exists(path, error);
    if (error) return DBStatus::IO_ERROR;
    if (!exists) return DBStatus::OK;
    if (!std::filesystem::is_regular_file(path, error) || error)
        return DBStatus::IO_ERROR;
    std::ifstream input(path);
    if (!input) return DBStatus::IO_ERROR;
    std::set<std::string> physicalNames;
    std::set<std::pair<std::string,std::string>> owners;
    std::string line;
    while (std::getline(input, line)) {
        if (line.empty()) continue;
        StorageEngine::CompositeType type;
        const bool version2 = line.rfind(COMPOSITE_METADATA_V2_PREFIX,0) == 0;
        // Atomic V2 writers always terminate records. Do not accept a torn
        // last line merely because its surviving hex bytes happen to parse.
        if (version2 && input.eof()) return DBStatus::CORRUPTED_DATA;
        size_t position = version2 ? std::char_traits<char>::length(COMPOSITE_METADATA_V2_PREFIX) : 0;
        const auto header = [&](std::string& value) {
            const auto separator = line.find('|',position);
            if (separator == std::string::npos || separator == position) return false;
            const auto encoded = line.substr(position,separator-position);
            position = separator+1;
            if (version2) return domainUnhex(encoded,value);
            value = encoded;return true;
        };
        if (!header(type.name) || (version2 &&
            (!header(type.schema) || !header(type.localName))))
            return DBStatus::CORRUPTED_DATA;
        while (position < line.size()) {
            const size_t nextSeparator = line.find('|', position);
            const std::string field = nextSeparator == std::string::npos
                ? line.substr(position)
                : line.substr(position, nextSeparator - position);
            const size_t colon = field.find(':');
            if (colon == std::string::npos || colon == 0 ||
                colon + 1 >= field.size()) {
                return DBStatus::CORRUPTED_DATA;
            }
            std::string fieldName=field.substr(0,colon),fieldType=field.substr(colon+1);
            if (version2) {
                std::string decodedName,decodedType;
                if (!domainUnhex(fieldName,decodedName) || !domainUnhex(fieldType,decodedType))
                    return DBStatus::CORRUPTED_DATA;
                fieldName=std::move(decodedName);fieldType=std::move(decodedType);
            }
            type.fields.emplace_back(std::move(fieldName),std::move(fieldType));
            if (nextSeparator != std::string::npos && nextSeparator+1 == line.size())
                return DBStatus::CORRUPTED_DATA;
            position = nextSeparator == std::string::npos
                ? line.size() : nextSeparator + 1;
        }
        if (!validCompositeTypeDefinition(type) ||
            !physicalNames.insert(type.name).second ||
            (version2 && !owners.emplace(type.schema,type.localName).second))
            return DBStatus::CORRUPTED_DATA;
        types.push_back(std::move(type));
    }
    return input.bad() ? DBStatus::IO_ERROR : DBStatus::OK;
}

static std::string serializeCompositeTypes(
    const std::vector<StorageEngine::CompositeType>& types) {
    std::ostringstream serialized;
    for (const auto& type : types) {
        const bool version2 = !type.schema.empty();
        if (version2)
            serialized << COMPOSITE_METADATA_V2_PREFIX << domainHex(type.name)
                       << '|' << domainHex(type.schema) << '|' << domainHex(type.localName);
        else serialized << type.name;
        for (const auto& field : type.fields) {
            serialized << '|' << (version2 ? domainHex(field.first) : field.first)
                       << ':' << (version2 ? domainHex(field.second) : field.second);
        }
        serialized << '\n';
    }
    return serialized.str();
}

DBStatus StorageEngine::createCompositeType(const std::string& dbname, const CompositeType& ct) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validCompositeTypeDefinition(ct)) return DBStatus::INVALID_ARGUMENT;
    if (!ct.schema.empty() && !schemaExists(dbname,ct.schema))
        return DBStatus::TABLE_NOT_FOUND;
    const auto path = compositeTypePath(dbname);
    std::vector<CompositeType> types;
    const auto loaded = loadCompositeTypes(path,types);
    if (loaded != DBStatus::OK) return loaded;
    for (const auto& existing : types) {
        if (existing.name == ct.name) return DBStatus::TABLE_ALREADY_EXISTS;
    }
    types.push_back(ct);
    return index_file::writeAtomically(path, serializeCompositeTypes(types))
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::alterCompositeType(const std::string& dbname, const std::string& name,
                                           const CompositeType& ct) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(name) ||
        !validCompositeTypeDefinition(ct)) {
        return DBStatus::INVALID_ARGUMENT;
    }
    const auto path = compositeTypePath(dbname);
    std::vector<CompositeType> types;
    const auto loaded = loadCompositeTypes(path,types);
    if (loaded != DBStatus::OK) return loaded;
    if (ct.name != name &&
        std::any_of(types.begin(), types.end(), [&](const CompositeType& type) {
            return type.name == ct.name;
        })) {
        return DBStatus::TABLE_ALREADY_EXISTS;
    }
    bool found = false;
    for (auto& type : types) {
        if (type.name == name) {
            auto replacement=ct;
            if (!type.schema.empty()) {
                if (replacement.schema.empty()) {
                    if (replacement.name != name) return DBStatus::INVALID_ARGUMENT;
                    replacement.schema=type.schema;replacement.localName=type.localName;
                } else if (replacement.schema != type.schema)
                    return DBStatus::FEATURE_NOT_SUPPORTED;
            } else if (!replacement.schema.empty() &&
                       (name.find('.') != std::string::npos || replacement.schema != "public"))
                return DBStatus::CORRUPTED_DATA;
            if (!replacement.schema.empty() && !schemaExists(dbname,replacement.schema))
                return DBStatus::TABLE_NOT_FOUND;
            if (!validCompositeTypeDefinition(replacement)) return DBStatus::INVALID_ARGUMENT;
            type = std::move(replacement);
            found = true;
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return index_file::writeAtomically(path, serializeCompositeTypes(types))
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::dropCompositeType(const std::string& dbname, const std::string& name) {
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(name)) return DBStatus::INVALID_ARGUMENT;
    const auto path = compositeTypePath(dbname);
    std::vector<CompositeType> types;
    const auto loaded = loadCompositeTypes(path,types);
    if (loaded != DBStatus::OK) return loaded;
    bool found = false;
    std::vector<CompositeType> retained;
    retained.reserve(types.size());
    for (auto& type : types) {
        if (type.name == name) {
            found = true;
        } else {
            retained.push_back(std::move(type));
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return index_file::writeAtomically(
               path, serializeCompositeTypes(retained))
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

StorageEngine::CompositeType StorageEngine::getCompositeType(const std::string& dbname, const std::string& name) const {
    CompositeType result;
    std::vector<CompositeType> types;
    const auto loaded=loadCompositeTypes(compositeTypePath(dbname),types);
    // This old physical-key probe is also used inside existing row writers'
    // manual table locks. Keep its no-throw absence contract; destructive SQL
    // consumers first use checked getCompositeTypeNames, outside those locks.
    if (loaded != DBStatus::OK) return result;
    for (auto& type : types) {
        if (type.name == name) return type;
    }
    return result;
}

std::vector<std::string> StorageEngine::getCompositeTypeNames(const std::string& dbname) const {
    std::vector<std::string> result;
    std::vector<CompositeType> types;
    const auto loaded=loadCompositeTypes(compositeTypePath(dbname),types);
    if (loaded != DBStatus::OK)
        throw DbError(loaded==DBStatus::CORRUPTED_DATA?"XX001":"58030",
                      "could not read composite type metadata");
    for (const auto& type : types) result.push_back(type.name);
    return result;
}

bool StorageEngine::isCompositeType(const std::string& dbname, const std::string& name) const {
    return !getCompositeType(dbname, name).name.empty();
}

// ========================================================================
// Enum type support
// ========================================================================
static std::filesystem::path enumPath(const std::string& dbname) {
    return std::filesystem::path(dbname) / ".enums";
}

// The legacy format stored labels verbatim separated by '|'.  Both '|' and
// newlines are valid enum-label bytes, so one label could corrupt subsequent
// definitions.  V2 hex-encodes every field while keeping legacy files
// readable; every successful mutation rewrites the whole file as V2.
static constexpr const char* ENUM_METADATA_V2_PREFIX = "DBMS_ENUM_V2:";

static bool validEnumTypeDefinition(const StorageEngine::EnumType& type) {
    if (!validMetadataObjectName(type.name) || type.labels.empty()) return false;
    std::unordered_set<std::string> labels;
    for (const auto& label : type.labels) {
        if (label.find('\0') != std::string::npos ||
            !labels.insert(label).second) {
            return false;
        }
    }
    return true;
}

static bool parseEnumTypeRecord(
    const std::string& line, StorageEngine::EnumType& type) {
    type = {};
    size_t position = 0;
    if (line.rfind(ENUM_METADATA_V2_PREFIX, 0) == 0) {
        position = std::char_traits<char>::length(ENUM_METADATA_V2_PREFIX);
        const size_t nameEnd = line.find('|', position);
        if (nameEnd == std::string::npos ||
            !decodeCommentField(
                line.substr(position, nameEnd - position), type.name)) {
            return false;
        }
        position = nameEnd + 1;
        while (true) {
            const size_t labelEnd = line.find('|', position);
            std::string label;
            if (!decodeCommentField(
                    labelEnd == std::string::npos
                        ? line.substr(position)
                        : line.substr(position, labelEnd - position),
                    label)) {
                return false;
            }
            type.labels.push_back(std::move(label));
            if (labelEnd == std::string::npos) break;
            position = labelEnd + 1;
        }
    } else {
        const size_t nameEnd = line.find('|');
        if (nameEnd == std::string::npos) return false;
        type.name = line.substr(0, nameEnd);
        position = nameEnd + 1;
        while (true) {
            const size_t labelEnd = line.find('|', position);
            type.labels.push_back(
                labelEnd == std::string::npos
                    ? line.substr(position)
                    : line.substr(position, labelEnd - position));
            if (labelEnd == std::string::npos) break;
            position = labelEnd + 1;
        }
    }
    return validEnumTypeDefinition(type);
}

static bool loadEnumTypes(
    const std::filesystem::path& path,
    std::vector<StorageEngine::EnumType>& types) {
    types.clear();
    std::error_code error;
    const bool exists = std::filesystem::exists(path, error);
    if (error) return false;
    if (!exists) return true;

    std::ifstream input(path);
    if (!input) return false;
    std::unordered_set<std::string> names;
    std::string line;
    while (std::getline(input, line)) {
        if (line.empty()) continue;
        StorageEngine::EnumType type;
        if (!parseEnumTypeRecord(line, type) ||
            !names.insert(type.name).second) {
            return false;
        }
        types.push_back(std::move(type));
    }
    return !input.bad();
}

static std::string serializeEnumTypes(
    const std::vector<StorageEngine::EnumType>& types) {
    std::ostringstream serialized;
    for (const auto& type : types) {
        serialized << ENUM_METADATA_V2_PREFIX << encodeCommentField(type.name);
        for (const auto& label : type.labels) {
            serialized << '|' << encodeCommentField(label);
        }
        serialized << '\n';
    }
    return serialized.str();
}

DBStatus StorageEngine::createEnumType(const std::string& dbname, const EnumType& et) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validEnumTypeDefinition(et)) return DBStatus::INVALID_ARGUMENT;
    const auto path = enumPath(dbname);
    std::vector<EnumType> types;
    if (!loadEnumTypes(path, types)) return DBStatus::IO_ERROR;
    for (const auto& existing : types) {
        if (existing.name == et.name) return DBStatus::TABLE_ALREADY_EXISTS;
    }
    types.push_back(et);
    return index_file::writeAtomically(path, serializeEnumTypes(types))
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::dropEnumType(const std::string& dbname, const std::string& name) {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validMetadataObjectName(name)) return DBStatus::INVALID_ARGUMENT;
    const auto path = enumPath(dbname);
    std::error_code pathError;
    const bool exists = std::filesystem::exists(path, pathError);
    if (pathError) return DBStatus::IO_ERROR;
    if (!exists) return DBStatus::TABLE_NOT_FOUND;
    std::vector<EnumType> types;
    if (!loadEnumTypes(path, types)) return DBStatus::IO_ERROR;
    bool found = false;
    std::vector<EnumType> retained;
    retained.reserve(types.size());
    for (auto& type : types) {
        if (type.name == name) {
            found = true;
        } else {
            retained.push_back(std::move(type));
        }
    }
    if (!found) return DBStatus::TABLE_NOT_FOUND;
    return index_file::writeAtomically(path, serializeEnumTypes(retained))
        ? DBStatus::OK : DBStatus::IO_ERROR;
}

DBStatus StorageEngine::updateEnumType(const std::string& dbname, const EnumType& et) {
    std::unique_lock<std::recursive_mutex> cacheLock(cacheMutex_);
    if (!databaseExists(dbname)) return DBStatus::DATABASE_NOT_FOUND;
    if (!validEnumTypeDefinition(et)) return DBStatus::INVALID_ARGUMENT;
    const auto path = enumPath(dbname);
    std::error_code pathError;
    const bool exists = std::filesystem::exists(path, pathError);
    if (pathError) return DBStatus::IO_ERROR;
    if (!exists) return DBStatus::TABLE_NOT_FOUND;
    std::vector<EnumType> types;
    if (!loadEnumTypes(path, types)) return DBStatus::IO_ERROR;
    const std::vector<EnumType> originalTypes = types;
    EnumType previous;
    size_t identicalPreviousDefinitions = 0;
    for (auto& type : types) {
        if (type.name == et.name) {
            previous = type;
            type = et;
        }
    }
    if (previous.name.empty()) return DBStatus::TABLE_NOT_FOUND;
    std::optional<std::pair<std::string, std::string>> renamedLabel;
    if (previous.labels.size() == et.labels.size()) {
        for (size_t labelIndex = 0; labelIndex < et.labels.size();
             ++labelIndex) {
            if (previous.labels[labelIndex] == et.labels[labelIndex]) continue;
            if (renamedLabel) {
                renamedLabel.reset();
                break;
            }
            renamedLabel = std::make_pair(previous.labels[labelIndex],
                                          et.labels[labelIndex]);
        }
    }
    for (const auto& type : types) {
        if (type.name != et.name && type.labels == previous.labels) {
            ++identicalPreviousDefinitions;
        }
    }

    struct EnumSchemaRewrite {
        std::string tableName;
        TableSchema original;
        TableSchema updated;
        std::vector<size_t> columns;
        std::map<int64_t, std::map<std::string, std::string>> renamedRows;
        std::string originalBytes;
        std::string updatedBytes;
    };
    std::vector<EnumSchemaRewrite> rewrites;
    std::vector<std::pair<std::string, std::string>> observedSchemas;
    auto serializeSchema = [&](const TableSchema& schema,
                               std::string& bytes) {
        std::ostringstream output(std::ios::out | std::ios::binary);
        writeSchema(output, schema);
        if (!output) return false;
        bytes = output.str();
        return true;
    };

    // Enum labels were historically copied into table schemas while the
    // declared type was replaced by varchar.  Migrate that old representation
    // only when the label list identifies exactly one enum; otherwise there is
    // no safe way to guess which same-shaped enum the column meant.
    const auto tableNames = getTableNames(dbname);
    for (const auto& tableName : tableNames) {
        const TableSchema schema = getTableSchema(dbname, tableName);
        if (schema.len == 0) return DBStatus::CORRUPTED_DATA;
        std::string originalSchemaBytes;
        if (!serializeSchema(schema, originalSchemaBytes)) return DBStatus::IO_ERROR;
        observedSchemas.emplace_back(tableName, std::move(originalSchemaBytes));
        EnumSchemaRewrite rewrite;
        rewrite.tableName = tableName;
        rewrite.original = schema;
        rewrite.updated = schema;
        for (size_t columnIndex = 0; columnIndex < schema.len; ++columnIndex) {
            const Column& column = schema.cols[columnIndex];
            const bool namedDependency =
                column.dataType == et.name && !column.enumValues.empty();
            const bool unambiguousLegacyDependency =
                column.dataType == "varchar" &&
                identicalPreviousDefinitions == 0 &&
                column.enumValues == previous.labels;
            if (!namedDependency && !unambiguousLegacyDependency) continue;
            rewrite.columns.push_back(columnIndex);
            rewrite.updated.cols[columnIndex].dataType = et.name;
            rewrite.updated.cols[columnIndex].enumValues = et.labels;
        }
        if (rewrite.columns.empty()) continue;
        if (!serializeSchema(rewrite.original, rewrite.originalBytes) ||
            !serializeSchema(rewrite.updated, rewrite.updatedBytes)) {
            return DBStatus::IO_ERROR;
        }
        rewrites.push_back(std::move(rewrite));
    }

    // Relation readers take the table lock before entering the storage
    // cache. Waiting for a database/metadata lock while holding cacheMutex_
    // would invert that order and block otherwise-compatible readers.
    cacheLock.unlock();

    // A label rename must update the current text-backed heap representation
    // in the same engine transaction. Begin before taking table locks so the
    // database/table lock order matches normal DML. ADD VALUE and pure order
    // changes do not rewrite heap rows.
    const bool ownsRenameTransaction = renamedLabel && !rewrites.empty();
    if (ownsRenameTransaction) {
        if (transactionContext().inTransaction) return DBStatus::INVALID_VALUE;
        const DBStatus beginStatus = beginTransaction(dbname);
        if (beginStatus != DBStatus::OK) return beginStatus;
    }

    // Lock every dependent relation in deterministic table-list order.
    std::vector<std::string> lockedTables;
    lockManager_.setResourceNamespace(dbname);
    for (const auto& rewrite : rewrites) {
        if (!lockManager_.lockExclusive(rewrite.tableName)) {
            for (auto it = lockedTables.rbegin(); it != lockedTables.rend(); ++it)
                lockManager_.unlock(*it);
            if (ownsRenameTransaction) (void)rollbackTransaction();
            return DBStatus::LOCK_CONFLICT;
        }
        lockedTables.push_back(rewrite.tableName);
    }
    auto unlockTables = [&]() {
        for (auto it = lockedTables.rbegin(); it != lockedTables.rend(); ++it)
            lockManager_.unlock(*it);
        lockedTables.clear();
    };
    cacheLock.lock();
    std::vector<EnumType> currentTypes;
    bool unchanged = loadEnumTypes(path, currentTypes) &&
        serializeEnumTypes(currentTypes) == serializeEnumTypes(originalTypes) &&
        getTableNames(dbname) == tableNames;
    for (const auto& [tableName, originalSchemaBytes] : observedSchemas) {
        if (!unchanged) break;
        const TableSchema currentSchema = getTableSchema(dbname, tableName);
        std::string currentSchemaBytes;
        unchanged = currentSchema.len != 0 &&
            serializeSchema(currentSchema, currentSchemaBytes) &&
            currentSchemaBytes == originalSchemaBytes;
    }
    if (!unchanged) {
        if (ownsRenameTransaction) (void)rollbackTransaction();
        unlockTables();
        return DBStatus::LOCK_CONFLICT;
    }
    const std::unordered_set<std::string> newLabels(et.labels.begin(),
                                                    et.labels.end());
    for (auto& rewrite : rewrites) {
        bool invalidStoredValue = false;
        if (!forEachRow(
                dbname, rewrite.tableName,
                [&](uint32_t pageId, uint16_t slotId, const char* data,
                    size_t length) {
                    if (invalidStoredValue) return;
                    const std::string row(data, length);
                    const int64_t rid = encodeRid(pageId, slotId);
                    for (const size_t columnIndex : rewrite.columns) {
                        if (rewrite.original.cols[columnIndex].isNull &&
                            dbms::detail::storedRowColumnIsNull(*this, dbname, rewrite.tableName, rewrite.original, rid,
                                              columnIndex)) {
                            continue;
                        }
                        const std::string value = extractColumnValue(
                            row, rewrite.original, columnIndex, dbname, true);
                        if (newLabels.count(value) == 0) {
                            if (renamedLabel &&
                                value == renamedLabel->first) {
                                rewrite.renamedRows[rid][
                                    rewrite.original.cols[columnIndex].dataName] =
                                    renamedLabel->second;
                            } else {
                                invalidStoredValue = true;
                                return;
                            }
                        }
                    }
                })) {
            if (ownsRenameTransaction) (void)rollbackTransaction();
            unlockTables();
            return DBStatus::IO_ERROR;
        }
        if (invalidStoredValue) {
            if (ownsRenameTransaction) (void)rollbackTransaction();
            unlockTables();
            return DBStatus::INVALID_VALUE;
        }
    }

    auto restoreSchemas = [&]() {
        for (const auto& rewrite : rewrites) {
            index_file::writeAtomically(schemaPath(dbname, rewrite.tableName),
                                        rewrite.originalBytes);
            invalidateCatalogSchema(dbname, rewrite.tableName);
        }
    };

    size_t publishedSchemas = 0;
    for (; publishedSchemas < rewrites.size(); ++publishedSchemas) {
        const auto& rewrite = rewrites[publishedSchemas];
        if (index_file::writeAtomically(
                schemaPath(dbname, rewrite.tableName),
                rewrite.updatedBytes)) {
            invalidateCatalogSchema(dbname, rewrite.tableName);
            continue;
        }
        for (size_t rollback = 0; rollback <= publishedSchemas; ++rollback) {
            const auto& prior = rewrites[rollback];
            index_file::writeAtomically(schemaPath(dbname, prior.tableName),
                                        prior.originalBytes);
            invalidateCatalogSchema(dbname, prior.tableName);
        }
        if (ownsRenameTransaction) (void)rollbackTransaction();
        unlockTables();
        return DBStatus::IO_ERROR;
    }

    // The new schema admits the replacement label. Rewrite each affected
    // physical row once, combining multiple enum columns in that row so a
    // versioned UPDATE never tries to revisit an already superseded RID.
    for (const auto& rewrite : rewrites) {
        ReferentialActionContext referentialContext;
        for (const auto& [rid, updates] : rewrite.renamedRows) {
            const std::set<int64_t> exactRid{rid};
            size_t affectedRows = 0;
            const DBStatus status = updateInternal(
                dbname, rewrite.tableName, updates, {}, {}, nullptr, {}, {},
                &exactRid, referentialContext, &affectedRows);
            if (status != DBStatus::OK || affectedRows != 1) {
                if (ownsRenameTransaction) (void)rollbackTransaction();
                restoreSchemas();
                unlockTables();
                return status == DBStatus::OK ? DBStatus::CORRUPTED_DATA
                                              : status;
            }
        }
    }

    if (!index_file::writeAtomically(path, serializeEnumTypes(types))) {
        // writeAtomically may report a directory-fsync failure after rename;
        // restore the target as well as the heap transaction and schemas.
        index_file::writeAtomically(path, serializeEnumTypes(originalTypes));
        if (ownsRenameTransaction) (void)rollbackTransaction();
        restoreSchemas();
        unlockTables();
        return DBStatus::IO_ERROR;
    }

    // Keep the SQL-visible type catalog synchronized before publishing the
    // heap transaction.  Older databases can have the sidecar without a
    // pg_type row, so repair that representation on the first ALTER.
    CatalogManager* enumCatalog = nullptr;
    Oid enumCatalogTypeOid = INVALID_OID;
    bool createdCatalogType = false;
    bool catalogLabelsChanged = false;
    auto restoreEnumCatalog = [&]() {
        if (!enumCatalog || enumCatalogTypeOid == INVALID_OID) return;
        if (createdCatalogType) {
            (void)enumCatalog->dropType(enumCatalogTypeOid);
        } else if (catalogLabelsChanged) {
            (void)enumCatalog->replaceEnumLabels(enumCatalogTypeOid,
                                                 previous.labels);
        }
        (void)enumCatalog->persistAll();
    };
    try {
        CatalogManager::QualifiedName qualifiedName;
        if (!CatalogManager::parseQualifiedName(et.name, qualifiedName) ||
            qualifiedName.name.empty()) {
            throw std::runtime_error("invalid enum catalog name");
        }
        const std::string namespaceName = qualifiedName.schema.empty()
            ? "public" : qualifiedName.schema;
        enumCatalog = &catalogService().get(dbname);
        const auto typeNamespace =
            enumCatalog->getNamespaceByName(namespaceName);
        if (!typeNamespace)
            throw std::runtime_error("enum namespace is not cataloged");
        const auto catalogType = enumCatalog->getTypeByName(
            qualifiedName.name, typeNamespace->oid);
        if (catalogType) {
            if (catalogType->typtype != 'e')
                throw std::runtime_error("catalog type is not an enum");
            enumCatalogTypeOid = catalogType->oid;
        } else {
            PgTypeRow newType;
            newType.typname = qualifiedName.name;
            newType.typnamespace = typeNamespace->oid;
            newType.typlen = 4;
            newType.typbyval = true;
            newType.typtype = 'e';
            newType.typcategory = 'E';
            enumCatalogTypeOid = enumCatalog->createType(newType);
            createdCatalogType = true;
        }
        if (!enumCatalog->replaceEnumLabels(enumCatalogTypeOid, et.labels))
            throw std::runtime_error("cannot update enum catalog labels");
        catalogLabelsChanged = true;
        if (!enumCatalog->persistAll())
            throw std::runtime_error("cannot persist enum catalog labels");
    } catch (const std::exception&) {
        restoreEnumCatalog();
        index_file::writeAtomically(path, serializeEnumTypes(originalTypes));
        if (ownsRenameTransaction) (void)rollbackTransaction();
        restoreSchemas();
        unlockTables();
        return DBStatus::IO_ERROR;
    }
    if (ownsRenameTransaction) {
        const DBStatus commitStatus = commitTransaction();
        if (commitStatus != DBStatus::OK) {
            if (transactionContext().inTransaction)
                (void)rollbackTransaction();
            restoreEnumCatalog();
            index_file::writeAtomically(path,
                                        serializeEnumTypes(originalTypes));
            restoreSchemas();
            unlockTables();
            return commitStatus;
        }
    }
    unlockTables();
    return DBStatus::OK;
}

StorageEngine::EnumType StorageEngine::getEnumType(const std::string& dbname,
                                                    const std::string& name) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    EnumType result;
    if (!validMetadataObjectName(name)) return result;
    std::vector<EnumType> types;
    if (!loadEnumTypes(enumPath(dbname), types)) return result;
    for (auto& type : types) {
        if (type.name == name) return type;
    }
    return result;
}

std::vector<std::string> StorageEngine::getEnumTypeNames(const std::string& dbname) const {
    std::lock_guard<std::recursive_mutex> cacheLock(cacheMutex_);
    std::vector<std::string> result;
    std::vector<EnumType> types;
    if (!loadEnumTypes(enumPath(dbname), types)) return result;
    for (const auto& type : types) result.push_back(type.name);
    return result;
}

std::vector<std::string> StorageEngine::getInheritedChildren(const std::string& dbname,
                                                             const std::string& parentName) const {
    std::vector<std::string> children;
    auto inhPath = std::filesystem::path(dbPath(dbname)) / ".inherits";
    if (!std::filesystem::exists(inhPath)) return children;
    std::ifstream ifs(inhPath);
    if (!ifs) return children;
    std::string line;
    while (std::getline(ifs, line)) {
        size_t sep = line.find('|');
        if (sep == std::string::npos) continue;
        std::string parent = line.substr(0, sep);
        std::string child = line.substr(sep + 1);
        if (parent == parentName) children.push_back(child);
    }
    return children;
}

// Auto-VACUUM: trigger vacuum when dead tuple count exceeds threshold
void StorageEngine::maybeAutoVacuum(const std::string& dbname,
                                    const std::string& tablename) {
    if (!g_config.autoVacuumEnabled) return;
    auto key = std::make_pair(dbname, tablename);
    size_t count = 0;
    {
        std::lock_guard<std::mutex> lock(deadTupleMutex_);
        auto it = deadTupleCounts_.find(key);
        if (it == deadTupleCounts_.end()) return;
        count = it->second;
    }
    if (count >= static_cast<size_t>(g_config.autoVacuumThreshold)) {
        // Defer to the background loop: a synchronous vacuum here ran a
        // full-table compaction on the query path while holding the
        // table's locks, serializing all concurrent statements behind it
        // (measured: multi-second global stalls when 4 workers crossed
        // the 50-dead-tuple threshold together).
        {
            std::lock_guard<std::mutex> lock(autoVacuumMutex_);
            autoVacuumPending_[key] = true;
        }
        std::lock_guard<std::mutex> lock(deadTupleMutex_);
        deadTupleCounts_[key] = 0;
    }
}

size_t StorageEngine::getDeadTupleCount(const std::string& dbname,
                                        const std::string& tablename) const {
    auto key = std::make_pair(dbname, tablename);
    std::lock_guard<std::mutex> lock(deadTupleMutex_);
    auto it = deadTupleCounts_.find(key);
    return (it != deadTupleCounts_.end()) ? it->second : 0;
}

void StorageEngine::resetDeadTupleCount(const std::string& dbname,
                                        const std::string& tablename) {
    auto key = std::make_pair(dbname, tablename);
    std::lock_guard<std::mutex> lock(deadTupleMutex_);
    deadTupleCounts_[key] = 0;
}

void StorageEngine::recordModification(const std::string& dbname,
                                       const std::string& tablename,
                                       size_t delta) {
    auto key = std::make_pair(dbname, tablename);
    std::lock_guard<std::mutex> lock(modifyMutex_);
    modifyCounts_[key] += delta;
}

void StorageEngine::maybeAutoAnalyze(const std::string& dbname,
                                     const std::string& tablename) {
    if (!g_config.autoAnalyzeEnabled) return;
    auto key = std::make_pair(dbname, tablename);
    size_t count = 0;
    {
        std::lock_guard<std::mutex> lock(modifyMutex_);
        auto it = modifyCounts_.find(key);
        if (it == modifyCounts_.end()) return;
        count = it->second;
    }
    if (count >= static_cast<size_t>(g_config.autoAnalyzeThreshold)) {
        analyzeTable(dbname, tablename);
        std::lock_guard<std::mutex> lock(modifyMutex_);
        modifyCounts_[key] = 0;
    }
}

static std::string privToStr(StorageEngine::TablePrivilege p) {
    switch (p) {
        case StorageEngine::TablePrivilege::Select: return "select";
        case StorageEngine::TablePrivilege::Insert: return "insert";
        case StorageEngine::TablePrivilege::Update: return "update";
        case StorageEngine::TablePrivilege::Delete: return "delete";
        case StorageEngine::TablePrivilege::All: return "all";
        case StorageEngine::TablePrivilege::Usage: return "usage";
        case StorageEngine::TablePrivilege::Execute: return "execute";
    }
    return "";
}

// Permission entry: user|table|priv -> set of columns (empty = table-level)
static std::string permKey(const std::string& u, const std::string& t, const std::string& p) {
    return u + "|" + t + "|" + p;
}

static std::vector<std::string> parseColumns(const std::string& colsStr) {
    std::vector<std::string> cols;
    std::stringstream ss(colsStr);
    std::string col;
    while (std::getline(ss, col, ',')) {
        if (!col.empty()) cols.push_back(col);
    }
    return cols;
}

static std::string joinColumns(const std::vector<std::string>& cols) {
    std::string s;
    for (size_t i = 0; i < cols.size(); ++i) {
        if (i > 0) s += ",";
        s += cols[i];
    }
    return s;
}

static constexpr const char* GRANT_OPTION_MARK = "__grant__";

// PostgreSQL ACL entries can target the session role, any role inherited by
// that session role, or PUBLIC. Keep this resolution in the storage ACL
// implementation so table- and column-level checks use identical semantics.
static bool aclGranteeMatches(const std::string& grantee, const std::string& username) {
    return grantee == username || grantee == "public" || userHasRole(username, grantee);
}

// PostgreSQL table owners have implicit privileges and grant options. Keep
// this in the same ACL resolution layer as explicit grants so AST and legacy
// DML paths cannot disagree about owner access.
static bool tableOwnerMatches(const StorageEngine& engine,
                              const std::string& dbname,
                              const std::string& tablename,
                              const std::string& username) {
    if (username.empty() || !engine.tableExists(dbname, tablename)) return false;
    return engine.getTableSchema(dbname, tablename).owner == username;
}

static bool colsEmptyIgnoreGrant(const std::string& colsStr) {
    if (colsStr.empty()) return true;
    // colsStr may start with space
    size_t start = 0;
    while (start < colsStr.size() && std::isspace(static_cast<unsigned char>(colsStr[start]))) ++start;
    if (start >= colsStr.size()) return true;
    // Check if remaining is only __grant__
    std::string rest = colsStr.substr(start);
    auto cols = parseColumns(rest);
    for (const auto& c : cols) {
        if (c != GRANT_OPTION_MARK) return false;
    }
    return true;
}

void StorageEngine::grant(const std::string& dbname, const std::string& tablename,
                          const std::string& username, TablePrivilege priv,
                          const std::vector<std::string>& columns,
                          bool withGrantOption,
                          const std::string& grantedBy) {
    auto ppath = permPath(dbname);
    std::map<std::string, std::set<std::string>> perms;
    if (std::filesystem::exists(ppath)) {
        std::ifstream ifs(ppath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string u, t, p, cols;
            ss >> u >> t >> p;
            std::getline(ss, cols);
            if (!cols.empty() && cols[0] == ' ') cols = cols.substr(1);
            auto key = permKey(u, t, p);
            if (!cols.empty()) {
                for (const auto& c : parseColumns(cols)) perms[key].insert(c);
            } else {
                perms[key] = {};
            }
        }
    }
    auto key = permKey(username, tablename, privToStr(priv));
    if (columns.empty()) {
        perms[key] = {};
    } else {
        if (perms[key].empty()) {
            auto it = perms.find(key);
            if (it != perms.end() && it->second.empty()) {
                it->second.clear();
            }
        }
        for (const auto& c : columns) perms[key].insert(c);
    }
    if (withGrantOption) {
        perms[key].insert(GRANT_OPTION_MARK);
    }
    std::ofstream ofs(ppath);
    for (const auto& kv : perms) {
        size_t p1 = kv.first.find('|');
        size_t p2 = kv.first.find('|', p1 + 1);
        std::string u = kv.first.substr(0, p1);
        std::string t = kv.first.substr(p1 + 1, p2 - p1 - 1);
        std::string p = kv.first.substr(p2 + 1);
        ofs << u << " " << t << " " << p;
        if (!kv.second.empty()) ofs << " " << joinColumns(std::vector<std::string>(kv.second.begin(), kv.second.end()));
        ofs << "\n";
    }
    // Record every explicit grant when the grantor is known.  PostgreSQL's
    // CASCADE semantics must be able to follow grants made without GRANT
    // OPTION as well: removing a grant option from the upstream grantor can
    // invalidate those downstream grants.
    if (!grantedBy.empty()) {
        auto gcp = grantChainPath(dbPath(dbname));
        bool exists = false;
        if (std::filesystem::exists(gcp)) {
            std::ifstream ifs(gcp);
            std::string line;
            while (std::getline(ifs, line)) {
                std::stringstream ss(line);
                std::string grantee, object, privilege, grantor;
                ss >> grantee >> object >> privilege >> grantor;
                if (grantee == username && object == tablename &&
                    privilege == privToStr(priv) && grantor == grantedBy) {
                    exists = true;
                    break;
                }
            }
        }
        if (!exists) {
            std::ofstream gcfs(gcp, std::ios::app);
            gcfs << username << " " << tablename << " " << privToStr(priv)
                 << " " << grantedBy << "\n";
        }
    }
}

bool StorageEngine::revoke(const std::string& dbname, const std::string& tablename,
                           const std::string& username, TablePrivilege priv,
                           const std::vector<std::string>& columns, bool cascade,
                           bool grantOptionOnly) {
    auto ppath = permPath(dbname);
    const auto gcp = grantChainPath(dbPath(dbname));
    std::vector<std::string> chainLines;
    if (std::filesystem::exists(gcp)) {
        std::ifstream ifs(gcp);
        std::string line;
        while (std::getline(ifs, line)) {
            if (!line.empty()) chainLines.push_back(line);
        }
    }
    std::vector<std::tuple<std::string, std::string, std::string>> downstream;
    for (const auto& line : chainLines) {
        std::stringstream ss(line);
        std::string grantee, object, privilege, grantor;
        ss >> grantee >> object >> privilege >> grantor;
        if (grantor == username && object == tablename &&
            privilege == privToStr(priv)) {
            downstream.emplace_back(grantee, object, privilege);
        }
    }
    if (!cascade && !downstream.empty()) return false;
    if (!std::filesystem::exists(ppath)) return true;
    std::map<std::string, std::set<std::string>> perms;
    {
        std::ifstream ifs(ppath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string u, t, p, cols;
            ss >> u >> t >> p;
            std::getline(ss, cols);
            if (!cols.empty() && cols[0] == ' ') cols = cols.substr(1);
            auto key = permKey(u, t, p);
            if (!cols.empty()) {
                for (const auto& c : parseColumns(cols)) perms[key].insert(c);
            } else {
                perms[key] = {};
            }
        }
    }
    auto key = permKey(username, tablename, privToStr(priv));
    auto it = perms.find(key);
    if (it != perms.end()) {
        if (columns.empty()) {
            if (grantOptionOnly) {
                it->second.erase(GRANT_OPTION_MARK);
                // An empty set is the canonical representation of a
                // table-level privilege, so keep it when the grant option
                // is removed from a table-level grant.  Column-scoped
                // grants with no remaining columns disappear.
                if (it->second.empty() && !columns.empty()) perms.erase(it);
            } else {
                perms.erase(it); // revoke entire privilege
            }
        } else {
            if (grantOptionOnly) {
                it->second.erase(GRANT_OPTION_MARK);
            } else {
                for (const auto& c : columns) it->second.erase(c);
            }
            if (it->second.empty()) perms.erase(it);
        }
    }
    {
        std::ofstream ofs(ppath);
        for (const auto& kv : perms) {
            size_t p1 = kv.first.find('|');
            size_t p2 = kv.first.find('|', p1 + 1);
            std::string u = kv.first.substr(0, p1);
            std::string t = kv.first.substr(p1 + 1, p2 - p1 - 1);
            std::string p = kv.first.substr(p2 + 1);
            ofs << u << " " << t << " " << p;
            if (!kv.second.empty()) ofs << " " << joinColumns(std::vector<std::string>(kv.second.begin(), kv.second.end()));
            ofs << "\n";
        }
    }

    // A fully revoked privilege no longer has a valid upstream grant chain.
    // Keep the chain when only GRANT OPTION is removed, because the base
    // privilege itself remains valid.
    if (!grantOptionOnly) {
        std::vector<std::string> remaining;
        for (const auto& line : chainLines) {
            std::stringstream ss(line);
            std::string grantee, object, privilege, grantor;
            ss >> grantee >> object >> privilege >> grantor;
            if (grantee == username && object == tablename &&
                privilege == privToStr(priv)) continue;
            remaining.push_back(line);
        }
        chainLines.swap(remaining);
    }

    if (!chainLines.empty()) {
        std::ofstream ofs(gcp);
        for (const auto& line : chainLines) ofs << line << "\n";
    } else if (std::filesystem::exists(gcp)) {
        std::error_code ec;
        std::filesystem::remove(gcp, ec);
    }

    // CASCADE: recursively revoke from users who received this privilege via the revoked user
    if (cascade) {
        std::vector<std::string> remaining;
        for (const auto& line : chainLines) {
            std::stringstream ss(line);
            std::string grantee, object, privilege, grantor;
            ss >> grantee >> object >> privilege >> grantor;
            if (grantor == username && object == tablename &&
                privilege == privToStr(priv)) continue;
            remaining.push_back(line);
        }
        chainLines.swap(remaining);
        for (const auto& ch : downstream) {
            revoke(dbname, std::get<1>(ch), std::get<0>(ch), priv, {}, true);
        }
    }
    return true;
}

bool StorageEngine::hasPermission(const std::string& dbname, const std::string& tablename,
                                  const std::string& username, TablePrivilege priv) const {
    if (tableOwnerMatches(*this, dbname, tablename, username)) return true;
    auto ppath = permPath(dbname);
    if (!std::filesystem::exists(ppath)) return false;
    std::string target = privToStr(priv);
    std::ifstream ifs(ppath);
    std::string line;
    bool hasDbLevel = false;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string u, t, p, cols;
        ss >> u >> t >> p;
        std::getline(ss, cols);
        if (!aclGranteeMatches(u, username)) continue;
        if (t == tablename && (p == "all" || p == target)) {
            if (colsEmptyIgnoreGrant(cols)) return true;
        }
        if (t == "*" && (p == "all" || p == target)) hasDbLevel = true;
    }
    return hasDbLevel;
}

bool StorageEngine::hasGrantOption(const std::string& dbname, const std::string& tablename,
                                   const std::string& username, TablePrivilege priv) const {
    if (tableOwnerMatches(*this, dbname, tablename, username)) return true;
    auto ppath = permPath(dbname);
    if (!std::filesystem::exists(ppath)) return false;
    std::string target = privToStr(priv);
    std::ifstream ifs(ppath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string u, t, p, cols;
        ss >> u >> t >> p;
        std::getline(ss, cols);
        if (!cols.empty() && cols[0] == ' ') cols = cols.substr(1);
        if (!aclGranteeMatches(u, username)) continue;
        if (t != tablename && t != "*") continue;
        if (p == "all" || p == target) {
            auto colList = parseColumns(cols);
            for (const auto& c : colList) {
                if (c == GRANT_OPTION_MARK) return true;
            }
        }
    }
    return false;
}

bool StorageEngine::hasColumnPermission(const std::string& dbname, const std::string& tablename,
                                        const std::string& username, TablePrivilege priv,
                                        const std::vector<std::string>& columns) const {
    if (tableOwnerMatches(*this, dbname, tablename, username)) return true;
    if (columns.empty()) return hasPermission(dbname, tablename, username, priv);
    auto ppath = permPath(dbname);
    if (!std::filesystem::exists(ppath)) return false;
    std::string target = privToStr(priv);
    std::set<std::string> allowedCols;
    bool hasTableLevel = false;
    bool hasDbLevel = false;
    {
        std::ifstream ifs(ppath);
        std::string line;
        while (std::getline(ifs, line)) {
            if (line.empty()) continue;
            std::stringstream ss(line);
            std::string u, t, p, cols;
            ss >> u >> t >> p;
            std::getline(ss, cols);
            if (!cols.empty() && cols[0] == ' ') cols = cols.substr(1);
            if (!aclGranteeMatches(u, username)) continue;
            if (t == "*" && (p == "all" || p == target)) hasDbLevel = true;
            if (t != tablename) continue;
            if (p == "all") hasTableLevel = true;
            if (p == target) {
                if (cols.empty()) hasTableLevel = true;
                else {
                    bool hasGrantMarker = false;
                    bool hasColumn = false;
                    for (const auto& c : parseColumns(cols)) {
                        if (c == GRANT_OPTION_MARK) hasGrantMarker = true;
                        else {
                            hasColumn = true;
                            allowedCols.insert(c);
                        }
                    }
                    // A table-level grant with GRANT OPTION is serialized as
                    // the marker alone and still applies to every column.
                    if (hasGrantMarker && !hasColumn) hasTableLevel = true;
                }
            }
        }
    }
    if (hasTableLevel || hasDbLevel) return true;
    for (const auto& col : columns) {
        if (allowedCols.find(col) == allowedCols.end()) return false;
    }
    return true;
}

std::vector<std::string> StorageEngine::getUserPermissions(
    const std::string& dbname, const std::string& tablename,
    const std::string& username) const {
    std::vector<std::string> result;
    if (tableOwnerMatches(*this, dbname, tablename, username)) {
        result.push_back("all");
        return result;
    }
    auto ppath = permPath(dbname);
    if (!std::filesystem::exists(ppath)) return result;
    std::ifstream ifs(ppath);
    std::string line;
    while (std::getline(ifs, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string u, t, p;
        ss >> u >> t >> p;
        if (t == tablename && aclGranteeMatches(u, username)) result.push_back(p);
    }
    return result;
}

