// Preserve actual libc collation results and count calls only on this thread.
// The quantitative control is available on glibc with the required locale;
// other platforms still run the full value/NULL/statistics assertions.
// This is an operation-count bound, not a wall-clock performance assertion.
#include "catalog/collation.h"
#include "catalog/type_registry.h"
#include "commands/TableManage.h"
#include "common/Config.h"
#include "test_utils.h"
#include <cassert>
#include <iostream>
#include <optional>
#include <string>
#include <vector>
#ifdef __GLIBC__
#include <dlfcn.h>
#include <locale.h>
#include <unistd.h>
namespace {
thread_local bool countLocale = false;
thread_local size_t localeCalls = 0;
}
extern "C" int __strcoll_l(const char* left, const char* right, locale_t locale) noexcept {
    using Compare = int (*)(const char*, const char*, locale_t);
    static const auto original = reinterpret_cast<Compare>(dlsym(RTLD_NEXT, "__strcoll_l"));
    if (!original) _exit(91);
    if (countLocale) ++localeCalls;
    return original(left, right, locale);
}
#endif

extern dbms::StorageEngine g_engine;
extern dbms::Config g_config;

int main() {
    using namespace dbms;
    TypeRegistry::instance().bootstrap();
    const bool savedAnalyze = g_config.autoAnalyzeEnabled;
    g_config.autoAnalyzeEnabled = false; // Isolate explicit ANALYZE, not a product policy.
    struct Restore {bool value; ~Restore(){g_config.autoAnalyzeEnabled=value;}} restore{savedAnalyze};
    const std::string database = testDbPath("analyze_duplicate_text_cost");
    assert(g_engine.createDatabase(database) == DBStatus::OK);
    TableSchema table;
    table.tablename = "duplicate_text";
    table.append(makeTextColumn("v", true));
    assert(g_engine.createTable(database, table) == DBStatus::OK);
    const std::string payload(16384, 'x');
    assert(g_engine.beginTransaction(database) == DBStatus::OK);
    for (size_t i = 0; i < 32; ++i)
        assert(g_engine.insertRow(database, table.tablename, {{"v", payload}}) == DBStatus::OK);
    for (size_t i = 0; i < 4; ++i)
        assert(g_engine.insertRow(database, table.tablename, {{"v", std::nullopt}}) == DBStatus::OK);
    assert(g_engine.commitTransaction() == DBStatus::OK);
    size_t referenceCalls = 0, analyzedCalls = 0;
    bool counterAvailable = false;
#ifdef __GLIBC__
    localeCalls = 0; countLocale = true;
    const int compared = collation::compare(payload, payload, "en_US.utf8");
    countLocale = false; referenceCalls = localeCalls;
    assert(compared == 0);
    counterAvailable = referenceCalls > 0;
    localeCalls = 0; countLocale = true;
#endif
    const bool analyzed = g_engine.analyzeTable(database, table.tablename);
#ifdef __GLIBC__
    countLocale = false; analyzedCalls = localeCalls;
#endif
    assert(analyzed);
    const auto stats = g_engine.getColumnStats(database, table.tablename, "v");
    bool semantics = stats.cardinality == 1 && stats.nullCount == 4 &&
        stats.minVal == payload && stats.maxVal == payload &&
        stats.mcv == std::vector<std::pair<std::string,size_t>>{{payload,32}} &&
        stats.histogram.size() == 10 && g_engine.getTableRowCount(database, table.tablename) == 36;
    for (const auto& bucket : stats.histogram)
        semantics = semantics && bucket.first == payload && bucket.second == payload;
    std::cout << "ANALYZE_DUPLICATE_TEXT_COST reference=" << referenceCalls
              << " analyzed=" << analyzedCalls << " available=" << counterAvailable
              << " semantics=" << semantics << '\n';
    const bool bounded = !counterAvailable || analyzedCalls <= referenceCalls;
    if (!counterAvailable) std::cout << "ANALYZE_DUPLICATE_TEXT_COST_COUNTER_UNAVAILABLE\n";
    assert(g_engine.dropDatabase(database) == DBStatus::OK);
    return semantics && bounded ? 0 : 1;
}

#include "catalog/type_registry.h"
#include "commands/TableManage.h"
#include "test_utils.h"
#include <cassert>
#include <cmath>
#include <iostream>
#include <map>
#include <sstream>

extern dbms::StorageEngine g_engine;

static double nullFraction(const std::string& db, const std::string& table,
                           const std::string& column) {
    const auto rows = g_engine.getPgStatsRows(db, table, column);
    assert(rows.size() == 1);
    std::istringstream fields(rows.front());
    std::string database, relation, attribute;
    double fraction = -1;
    fields >> database >> relation >> attribute >> fraction;
    assert(attribute == column);
    return fraction;
}

int main() {
    dbms::TypeRegistry::instance().bootstrap();
    const auto db = testDbPath("analyze_null_statistics");
    assert(g_engine.createDatabase(db, "utf8") == dbms::DBStatus::OK);
    dbms::TableSchema table;
    table.tablename = "items";
    table.append(dbms::makeVarCharColumn("text_value", true, 32));
    table.append(dbms::makeIntColumn("number_value", true, 4));
    table.append(dbms::makeVarCharColumn("all_null", true, 32));
    assert(g_engine.createTable(db, table) == dbms::DBStatus::OK);
    for (int i = 0; i < 20; ++i) {
        const bool isNull = i < 5;
        const std::string text = i < 10 ? "" : i < 15 ? "NULL" : "other";
        dbms::StorageEngine::SqlRow row{
            {"text_value", isNull ? std::nullopt : std::optional<std::string>(text)},
            {"number_value", isNull ? std::nullopt : std::optional<std::string>("7")},
            {"all_null", std::nullopt}};
        assert(g_engine.insertRow(db, "items", row) == dbms::DBStatus::OK);
    }
    assert(g_engine.analyzeTable(db, "items"));
    assert(g_engine.getTableRowCount(db, "items") == 20);
    const auto text = g_engine.getColumnStats(db, "items", "text_value");
    assert(text.nullCount == 5); // Empty text is data, not a sixth NULL.
    assert(text.cardinality == 3);
    const std::map<std::string, size_t> textMcv(text.mcv.begin(), text.mcv.end());
    assert((textMcv == std::map<std::string, size_t>{{"", 5}, {"NULL", 5}, {"other", 5}}));
    assert(text.histogram.empty()); // Only 15 non-NULL inputs, below the threshold.
    const auto number = g_engine.getColumnStats(db, "items", "number_value");
    assert(number.nullCount == 5 && number.cardinality == 1);
    assert(number.minVal == "7" && number.maxVal == "7");
    assert((number.mcv == std::vector<std::pair<std::string, size_t>>{{"7", 15}}));
    const auto allNull = g_engine.getColumnStats(db, "items", "all_null");
    assert(allNull.nullCount == 20 && allNull.cardinality == 0);
    assert(allNull.minVal.empty() && allNull.maxVal.empty());
    assert(allNull.histogram.empty() && allNull.mcv.empty());
    assert(std::abs(nullFraction(db, "items", "text_value") - 0.25) < 1e-9);
    assert(std::abs(nullFraction(db, "items", "number_value") - 0.25) < 1e-9);
    assert(nullFraction(db, "items", "all_null") == 1.0);
    table.tablename = "empty";
    assert(g_engine.createTable(db, table) == dbms::DBStatus::OK);
    assert(g_engine.analyzeTable(db, "empty"));
    assert(nullFraction(db, "empty", "text_value") == 0.0);
    // Leaf page/slot numbers collide. NULL metadata must come from the
    // physical leaf tuple rather than a lookup in the parent heap.
    table.tablename = "partitioned";
    table.partitionType = dbms::TableSchema::PartitionType::Range;
    table.partitionKey = "number_value";
    table.rangePartitions = {{"low_values", "10"}, {"high_values", "MAXVALUE"}};
    assert(g_engine.createTable(db, table) == dbms::DBStatus::OK);
    for (int i = 0; i < 4; ++i) {
        dbms::StorageEngine::SqlRow row{
            {"text_value", i % 2 == 0 ? std::nullopt
                : std::optional<std::string>(i == 1 ? "" : "other")},
            {"number_value", std::to_string(i < 2 ? i + 1 : i + 9)},
            {"all_null", std::nullopt}};
        assert(g_engine.insertRow(db, "partitioned", row) == dbms::DBStatus::OK);
    }
    assert(g_engine.analyzeTable(db, "partitioned"));
    const auto partitioned = g_engine.getColumnStats(db, "partitioned", "text_value");
    assert(partitioned.nullCount == 2 && partitioned.cardinality == 2);
    const std::map<std::string, size_t> partitionMcv(partitioned.mcv.begin(), partitioned.mcv.end());
    assert((partitionMcv == std::map<std::string, size_t>{{"", 1}, {"other", 1}}));
    assert(nullFraction(db, "partitioned", "text_value") == 0.5);
    const auto dropStatus = g_engine.dropDatabase(db);
    if (dropStatus != dbms::DBStatus::OK)
        std::cerr << "ANALYZE_NULL_CLEANUP_STATUS " << static_cast<int>(dropStatus) << '\n';
    assert(dropStatus == dbms::DBStatus::OK);
    std::cout << "[ANALYZE NULL STATISTICS] passed\n";
}

#include "catalog/type_registry.h"
#include "commands/TableManage.h"
#include "common/Config.h"
#include "executor/ExecutionPlan.h"
#include "test_utils.h"
#include <algorithm>
#include <cassert>
#include <iostream>
#include <optional>
#include <string>
#include <vector>

extern dbms::StorageEngine g_engine;
extern dbms::Config g_config;

using Cell = std::optional<std::string>;
using Rows = std::vector<std::vector<Cell>>;
using Engine = dbms::StorageEngine;

static Rows snapshot(const std::string& database, const dbms::TableSchema& table) {
    dbms::TableScanOp scan(&g_engine, database, table.tablename);
    assert(scan.open());
    Rows result;
    std::string raw;
    while (scan.next(raw)) {
        std::vector<Cell> row;
        for (size_t i = 0; i < table.len; ++i) {
            if (scan.lastColumnIsNull(i)) row.push_back(std::nullopt);
            else row.push_back(Engine::extractColumnValueStatic(raw, table, i));
        }
        result.push_back(std::move(row));
    }
    assert(!scan.hasError());
    scan.close();
    return result;
}

// Independent oracle: the pre-optimization comparator and statistics rules,
// applied to the actual stored values (not potentially normalized input text).
static Engine::ColumnStats reference(const dbms::Column& column,
                                     const Rows& rows, size_t ordinal) {
    Engine::ColumnStats expected;
    std::vector<std::string> values;
    for (const auto& row : rows) {
        if (!row[ordinal]) ++expected.nullCount;
        else values.push_back(*row[ordinal]);
    }
    std::sort(values.begin(), values.end(), [&column](const auto& left, const auto& right) {
        const bool leftComparable = Engine::compareValues(column, left, false,
            left, false, "=") != Engine::PredicateTruth::Unknown;
        const bool rightComparable = Engine::compareValues(column, right, false,
            right, false, "=") != Engine::PredicateTruth::Unknown;
        if (leftComparable != rightComparable) return leftComparable;
        if (!leftComparable) return left < right;
        return Engine::compareValues(column, left, false, right, false, "<")
            == Engine::PredicateTruth::True;
    });
    if (!values.empty()) {
        expected.minVal = values.front();
        expected.maxVal = values.back();
    }
    if (values.size() >= 20) {
        const size_t width = values.size() / 10;
        for (size_t i = 0; i < 10; ++i)
            expected.histogram.push_back({values[i * width],
                values[i == 9 ? values.size() - 1 : (i + 1) * width]});
    }
    for (const auto& value : values) {
        if (!expected.mcv.empty() && (expected.mcv.back().first == value ||
            Engine::compareValues(column, expected.mcv.back().first, false,
                value, false, "=") == Engine::PredicateTruth::True))
            ++expected.mcv.back().second;
        else expected.mcv.push_back({value, 1});
    }
    expected.cardinality = expected.mcv.size();
    std::stable_sort(expected.mcv.begin(), expected.mcv.end(),
        [](const auto& left, const auto& right) { return left.second > right.second; });
    if (expected.mcv.size() > 10) expected.mcv.resize(10);
    return expected;
}

int main() {
    using namespace dbms;
    TypeRegistry::instance().bootstrap();
    const bool savedAnalyze = g_config.autoAnalyzeEnabled;
    g_config.autoAnalyzeEnabled = false;
    struct Restore { bool value; ~Restore() { g_config.autoAnalyzeEnabled = value; } } restore{savedAnalyze};
    const auto database = testDbPath("analyze_sort_permutation");
    assert(g_engine.createDatabase(database) == DBStatus::OK);
    size_t controls = 0;
    for (const size_t population : {0, 1, 2, 3, 17, 20, 33, 65}) {
        TableSchema table;
        table.tablename = "rows_" + std::to_string(population);
        table.append(makeIntColumn("big", true, 8));
        table.append(makeDecimalColumn("exact", true, 40, 3));
        table.append(makeDoubleColumn("floating", true));
        table.append(makeTextColumn("plain", true));
        auto folded = makeTextColumn("folded", true);
        folded.collation = "nocase";
        table.append(folded);
        table.append(makeTextColumn("all_null", true));
        assert(g_engine.createTable(database, table) == DBStatus::OK);
        assert(g_engine.beginTransaction(database) == DBStatus::OK);
        const std::vector<std::string> floats{"NaN", "-Infinity", "Infinity", "-2.25", "0", "1.25"};
        const std::vector<std::string> texts{"", "NULL", "Apple", "apple", "Zoo", "10", "2"};
        for (size_t row = 0; row < population; ++row) {
            // A nontrivial permutation, adjacent and separated duplicates,
            // exact integers beyond double precision and typed-equal spellings.
            const size_t key = (row * 23 + population * 7) % 29;
            Engine::SqlRow input{
                {"big", std::to_string(9007199254740992LL + static_cast<long long>(key))},
                {"exact", "123456789012345678901234567890." + std::to_string(key + 10)},
                {"floating", floats[key % floats.size()]},
                {"plain", texts[key % texts.size()]},
                {"folded", texts[(key + row / 3) % texts.size()]},
                {"all_null", std::nullopt}};
            if (row % 7 == 6) input["plain"] = std::nullopt;
            if (row % 11 == 10) input["floating"] = std::nullopt;
            if (row % 5 == 4) input["exact"] = row % 2 ? "0.50" : "0.500";
            assert(g_engine.insertRow(database, table.tablename, input) == DBStatus::OK);
        }
        assert(g_engine.commitTransaction() == DBStatus::OK);
        const auto stored = g_engine.getTableSchema(database, table.tablename);
        const auto before = snapshot(database, stored);
        assert(before.size() == population);
        std::vector<Engine::ColumnStats> expected;
        for (size_t ordinal = 0; ordinal < stored.len; ++ordinal)
            expected.push_back(reference(stored.cols[ordinal], before, ordinal));
        // Repeated ANALYZE must not retain indexes/flags from a previous run.
        for (int repeat = 0; repeat < 2; ++repeat) {
            assert(g_engine.analyzeTable(database, table.tablename));
            assert(g_engine.getTableRowCount(database, table.tablename) == population);
            assert(snapshot(database, stored) == before);
            for (size_t ordinal = 0; ordinal < stored.len; ++ordinal) {
                const auto actual = g_engine.getColumnStats(database,
                    table.tablename, stored.cols[ordinal].dataName);
                const auto& wanted = expected[ordinal];
                assert(actual.nullCount == wanted.nullCount);
                assert(actual.cardinality == wanted.cardinality);
                assert(actual.minVal == wanted.minVal && actual.maxVal == wanted.maxVal);
                assert(actual.histogram == wanted.histogram);
                assert(actual.mcv == wanted.mcv);
                ++controls;
            }
        }
    }
    assert(g_engine.dropDatabase(database) == DBStatus::OK);
    std::cout << "[ANALYZE SORT PERMUTATION] " << controls << " column/run controls passed\n";
}

#include "catalog/type_registry.h"
#include "commands/TableManage.h"
#include "test_utils.h"
#include <algorithm>
#include <cassert>
#include <iostream>
#include <set>

extern dbms::StorageEngine g_engine;

static void check(const std::string& db, const std::string& name,
                  dbms::Column column, std::vector<std::string> values,
                  const std::string& minimum, const std::string& maximum) {
    dbms::TableSchema table;
    table.tablename = name;
    table.append(column);
    assert(g_engine.createTable(db, table) == dbms::DBStatus::OK);
    // Deliberately reverse insertion order to exercise typed sorting.
    std::reverse(values.begin(), values.end());
    for (const auto& value : values)
        assert(g_engine.insert(db, name, {{"v", value}}) == dbms::DBStatus::OK);
    assert(g_engine.analyzeTable(db, name));
    const auto stats = g_engine.getColumnStats(db, name, "v");
    if (stats.minVal != minimum || stats.maxVal != maximum)
        std::cerr << name << ": min=" << stats.minVal << " max=" << stats.maxVal << '\n';
    assert(stats.minVal == minimum && stats.maxVal == maximum);
    assert(stats.histogram.size() == (values.size() >= 20 ? 10 : 0));
    const std::set<std::string> original(values.begin(), values.end());
    std::string previous;
    bool first = true;
    for (const auto& bucket : stats.histogram) {
        assert(original.count(bucket.first) && original.count(bucket.second));
        assert(dbms::StorageEngine::compareValues(column, bucket.first, false,
            bucket.second, false, "<=") == dbms::StorageEngine::PredicateTruth::True);
        if (!first)
            assert(dbms::StorageEngine::compareValues(column, previous, false,
                bucket.first, false, "<=") == dbms::StorageEngine::PredicateTruth::True);
        previous = bucket.second;
        first = false;
    }
    if (!stats.histogram.empty()) {
        assert(stats.histogram.front().first == minimum);
        assert(stats.histogram.back().second == maximum);
    }
}

int main() {
    dbms::TypeRegistry::instance().bootstrap();
    const auto db = testDbPath("analyze_typed_statistics");
    assert(g_engine.createDatabase(db, "utf8") == dbms::DBStatus::OK);
    std::vector<std::string> fractional, largeIntegers, exactNumeric;
    for (int i = 1; i <= 20; ++i) {
        fractional.push_back(std::to_string(i) + ".25");
        largeIntegers.push_back(std::to_string(9007199254740992LL + i));
        exactNumeric.push_back("123456789012345678901234567890." + std::to_string(i + 10));
    }
    check(db, "double_values", dbms::makeDoubleColumn("v", false),
        fractional, "1.25", "20.25");
    check(db, "float_values", dbms::makeFloatColumn("v", false),
        fractional, "1.25", "20.25");
    check(db, "bigint_values", dbms::makeIntColumn("v", false, 8),
        largeIntegers, "9007199254740993", "9007199254741012");
    check(db, "numeric_values", dbms::makeDecimalColumn("v", false, 40, 2),
        exactNumeric, "123456789012345678901234567890.11", "123456789012345678901234567890.30");
    check(db, "signed_values", dbms::makeIntColumn("v", false, 8),
        {"-10", "-2", "0", "2", "10"}, "-10", "10");
    // Text digits remain lexically ordered rather than coerced to numbers.
    check(db, "text_values", dbms::makeVarCharColumn("v", false, 32),
        {"1", "2", "10", "20"}, "1", "20");
    check(db, "special_values", dbms::makeDoubleColumn("v", false),
        {"-Infinity", "-2.25", "1.25", "Infinity", "NaN"}, "-Infinity", "NaN");
    assert(g_engine.dropDatabase(db) == dbms::DBStatus::OK);
    std::cout << "[ANALYZE TYPED STATISTICS] passed\n";
}

#include "catalog/type_registry.h"
#include "commands/TableManage.h"
#include "executor/ExecutionPlan.h"
#include "test_utils.h"
#include <cassert>
#include <iostream>

extern dbms::StorageEngine g_engine;

static void estimatedHotRows(const std::string& db, const std::string& table,
                             const std::string& probe, size_t expected) {
    dbms::PlanContext context;
    context.dbname = db;
    context.tablename = table;
    context.conds = {{"=", "v", probe}};
    auto plan = dbms::QueryPlanner::buildSelectPlan(&g_engine, context);
    const auto explain = dbms::QueryPlanner::explain(plan, &g_engine, db);
    const auto filter = explain.find("Filter");
    assert(filter != std::string::npos);
    const auto rows = explain.find("rows=", filter);
    assert(rows != std::string::npos);
    if (std::stoull(explain.substr(rows + 5)) != expected) std::cerr << explain;
    assert(std::stoull(explain.substr(rows + 5)) == expected);
}

int main() {
    dbms::TypeRegistry::instance().bootstrap();
    const auto db = testDbPath("typed_statistics_mcv");
    assert(g_engine.createDatabase(db, "utf8") == dbms::DBStatus::OK);
    dbms::TableSchema table;
    table.tablename = "numeric_values";
    table.append(dbms::makeDecimalColumn("v", true, 20, 4));
    assert(g_engine.createTable(db, table) == dbms::DBStatus::OK);
    for (int i = 0; i < 40; ++i)
        assert(g_engine.insert(db, table.tablename, {{"v", i < 20 ? "0.50" : i < 35 ? "0.500" : "2.00"}})
            == dbms::DBStatus::OK);
    assert(g_engine.analyzeTable(db, table.tablename));
    const auto numeric = g_engine.getColumnStats(db, table.tablename, "v");
    assert(numeric.cardinality == 2 && numeric.mcv.size() == 2);
    assert(numeric.mcv.front().second == 35);
    assert(dbms::StorageEngine::compareValues(table.cols[0], numeric.mcv.front().first,
        false, "0.5", false, "=") == dbms::StorageEngine::PredicateTruth::True);
    for (const auto& probe : {"0.5", "0.50", "0.5000"})
        estimatedHotRows(db, table.tablename, probe, 35);
    table.tablename = "floating_values";
    table.cols[0] = dbms::makeDoubleColumn("v", false);
    assert(g_engine.createTable(db, table) == dbms::DBStatus::OK);
    for (int i = 0; i < 40; ++i)
        assert(g_engine.insert(db, table.tablename, {{"v", i < 35 ? "1.25" : "2.25"}})
            == dbms::DBStatus::OK);
    assert(g_engine.analyzeTable(db, table.tablename));
    estimatedHotRows(db, table.tablename, "1.2500", 35);
    table.tablename = "text_values";
    table.cols[0] = dbms::makeVarCharColumn("v", false, 32);
    assert(g_engine.createTable(db, table) == dbms::DBStatus::OK);
    for (const auto& value : {"0.50", "0.500", "0.5", ""})
        assert(g_engine.insert(db, table.tablename, {{"v", value}}) == dbms::DBStatus::OK);
    assert(g_engine.analyzeTable(db, table.tablename));
    const auto text = g_engine.getColumnStats(db, table.tablename, "v");
    assert(text.cardinality == 4 && text.mcv.size() == 4 && text.nullCount == 0);
    table.tablename = "empty";
    assert(g_engine.createTable(db, table) == dbms::DBStatus::OK);
    assert(g_engine.analyzeTable(db, table.tablename));
    const auto empty = g_engine.getColumnStats(db, table.tablename, "v");
    assert(empty.cardinality == 0 && empty.mcv.empty());
    assert(g_engine.dropDatabase(db) == dbms::DBStatus::OK);
    std::cout << "[TYPED STATISTICS MCV] passed\n";
}

// ============================================================================
// CREATE STATISTICS ndistinct / mcv test — Phase 4 Wave 4.32b
// Covers StorageEngine::computeNDistinct (per-column + full-group distinct
// counts) and computeMCVCombinations (most-common value combinations), the
// two extended-statistics kinds that complement computeFunctionalDependencies.
// ============================================================================

#include "commands/DdlExecutor.h"
#include "commands/TableManage.h"
#include "Session.h"
#include "catalog/type_registry.h"
#include <cassert>
