namespace {
using namespace dbms;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int64_t stamp(clockid_t id){timespec t{};if(clock_gettime(id,&t))throw std::runtime_error("clock_gettime");return int64_t(t.tv_sec)*1000000000+t.tv_nsec;}
struct Metric{int64_t wall=0,cpu=0,thread=0;uint64_t calls=0,bytes=0;};
template<class Action>Metric measured(Action run) {
    requests::calls=requests::bytes=0;requests::active=REINDEX_COST_COUNT_NEW;
    const auto wall=stamp(CLOCK_MONOTONIC_RAW),cpu=stamp(CLOCK_PROCESS_CPUTIME_ID),thread=stamp(CLOCK_THREAD_CPUTIME_ID);
    try{run();}catch(...){requests::active=false;throw;}
    Metric m{stamp(CLOCK_MONOTONIC_RAW)-wall,stamp(CLOCK_PROCESS_CPUTIME_ID)-cpu,
        stamp(CLOCK_THREAD_CPUTIME_ID)-thread,requests::calls,requests::bytes};requests::active=false;return m;
}
void metric(const char* phase,size_t n,size_t call,const Metric& m) {
    std::cout<<"REINDEX_PUBLIC_COST phase="<<phase<<" N="<<n<<" invocation="<<call
        <<" wall_ns="<<m.wall<<" process_cpu_ns="<<m.cpu<<" thread_cpu_ns="<<m.thread
        <<" allocations_measured="<<REINDEX_COST_COUNT_NEW<<" requested_calls="<<m.calls
        <<" requested_bytes="<<m.bytes<<" all_values_verified=1\n";
}
std::vector<int64_t> sorted(std::vector<int64_t> v){std::sort(v.begin(),v.end());return v;}
void verify(const std::string& db,const std::string& relation,size_t n) {
    const auto schema=g_engine.getTableSchema(db,relation);
    std::map<size_t,int64_t> rids;
    require(g_engine.forEachRow(db,relation,[&](uint32_t page,uint16_t slot,const char* data,size_t size){
        const std::string row(data,size);
        const auto id=static_cast<size_t>(std::stoull(g_engine.extractColumnValue(row,schema,0,db)));
        require(id>=1&&id<=n,"original heap id range");
        require(g_engine.extractColumnValue(row,schema,1,db)==std::to_string(id%100),"original grp values");
        require(g_engine.extractColumnValue(row,schema,2,db)==std::to_string(id%1000),"unindexed amount values");
        require(g_engine.extractColumnValue(row,schema,3,db)=="row-"+std::to_string(id),"unindexed payload values");
        require(rids.emplace(id,StorageEngine::encodeRid(page,slot)).second,"one real heap occurrence per id");
    }),"real full heap verification");
    require(rids.size()==n,"complete rows");
    auto* pk=g_engine.getPKIndex(db,relation);auto* secondary=g_engine.getSecondaryIndex(db,relation,"grp");
    require(pk&&secondary&&pk->isOpen()&&secondary->isOpen(),"actual PK/secondary present");
    std::vector<int64_t> expectedAll;
    for(size_t id=1;id<=n;++id){int64_t actual=-1;require(pk->search(std::to_string(id),actual)&&actual==rids.at(id),"complete PK RID mapping");expectedAll.push_back(actual);}
    std::vector<int64_t> actualAll;require(pk->allValuesChecked(actualAll)&&sorted(actualAll)==sorted(expectedAll),"complete primary membership");
    for(size_t group=0;group<100;++group){
        std::vector<int64_t> expected;
        for(size_t id=1;id<=n;++id)if(id%100==group)expected.push_back(rids.at(id));
        std::vector<int64_t> actual;require(secondary->searchMultiChecked(std::to_string(group),actual),"checked genuine secondary traversal");
        require(sorted(actual)==sorted(expected),"all original duplicate secondary key memberships");
    }
    actualAll.clear();require(secondary->allValuesChecked(actualAll)&&sorted(actualAll)==sorted(expectedAll),"complete secondary membership no extra RID");
    for(const auto& entry:std::filesystem::recursive_directory_iterator(db)){
        const auto name=entry.path().filename().string();
        require(name.find(".reindex.tmp.")==std::string::npos&&name.find(".reindex.old.")==std::string::npos&&name.find(".reindex_swap")==std::string::npos,"completed rebuild leaves no private publication artifacts");
    }
}
