int main(){
    using namespace dbms;
    TypeRegistry::instance().bootstrap();
    const std::string name="reindex_dependency_public_cost",db=testDbPath(name);
    cleanupTestDb(name);require(g_engine.createDatabase(db,"utf8")==DBStatus::OK,"create owned database");
    Session session;session.username="admin";session.permission=1;session.currentDB=db;
    DdlExecutor ddl;
    std::cout<<"REINDEX_PUBLIC_COST_IDENTITY cpp_counter="<<REINDEX_COST_COUNT_NEW
        <<" sizeof_StorageEngine="<<sizeof(StorageEngine)<<" initialization_before_main_and_bootstrap_unmeasured=1\n";
    size_t controls=0,rebuilds=0;
    for(const size_t n:{size_t(0),size_t(1),size_t(1000)}){
        const std::string table="reindex_n"+std::to_string(n);
        const auto setup=measured([&]{
            require(!ddl.executeSql("CREATE TABLE "+table+"(id INTEGER PRIMARY KEY,grp INTEGER,amount INTEGER,payload VARCHAR(64))",session),"real original four-column DDL");
            require(g_engine.beginTransaction(db)==DBStatus::OK,"setup transaction");
            for(size_t id=1;id<=n;++id){
                StorageEngine::SqlRow row={{"id",std::to_string(id)},{"grp",std::to_string(id%100)},
                    {"amount",std::to_string(id%1000)},{"payload","row-"+std::to_string(id)}};
                require(g_engine.insertRow(db,table,row)==DBStatus::OK,"original actual heap insertion");
            }
            require(g_engine.commitTransaction()==DBStatus::OK,"setup durable commit");
            require(g_engine.createIndex(db,table,"grp")==DBStatus::OK,"actual original grp secondary");
        });
        verify(db,table,n);metric("setup",n,0,setup);
        for(size_t invocation=0;invocation<4;++invocation){
            const auto value=measured([&]{require(g_engine.reindex(db,table)==DBStatus::OK,"actual public REINDEX");});
            verify(db,table,n);metric(invocation==0?"first_rebuild":"repeat_rebuild",n,invocation,value);++rebuilds;
        }
        ++controls;
    }
    require(g_engine.dropDatabase(db)==DBStatus::OK,"drop private database");cleanupTestDb(name);finalCleanupTestData();
    std::cout<<"REINDEX_PUBLIC_COST_TERMINAL controls="<<controls<<" expected=3 rebuilds="<<rebuilds<<" expected_rebuilds=12 setups=3 all_values=1\n";
    return controls==3&&rebuilds==12?0:1;
}

// Artifact-only real REINDEX functional and decoder-demand diagnostic.
// Requires paired private TableManage observer objects; not normal production.
